typedef _SavedStoreSearchVisit = ({
  int token, WorkSession source, String? accountScope, String? storeId,
  bool authenticated, bool fromOrders,
});

class _WorkWorkspaceDashboardScreenState
    extends State<WorkWorkspaceDashboardScreen> {
  WorkSession get session => widget.session;
  bool get _accountRecoveryReady => widget.accountRecoveryReady ?? widget.accountAuthenticated;
  WorkProcurementController? _storeProcurement;
  bool _leavingProcurement = false;
  BuyV2Session? _observedProcurement;
  String? _observedProcurementQuery;
  BuyV2View? _observedProcurementView;
  int? _observedProcurementItemCount;
  bool _procurementRouteCovered = false;
  BuyV2Session get _activeProcurement =>
      _storeProcurement?.session ?? widget.procurementSession;
  final _workspaceMessengerKey = GlobalKey<ScaffoldMessengerState>();
  late final TextEditingController _searchController;
  final FocusNode _searchFocus = FocusNode(debugLabel: 'workspace-search');
  final ScrollController _searchScroll = ScrollController();
  double _searchReturnOffset = 0;
  String? _ordersSearchStoreId, _ordersSearchReturnOrderId;
  int _searchVisitToken = 0;
  _SavedStoreSearchVisit? _savedSearchVisit;
  ({_SavedStoreSearchVisit visit, String query})? _retainedSavedSearch;
  String? get _searchAccountScope =>
      session.contactDraftStore?.accountScope ?? session.pendingProofStore?.accountScope;

  bool _searchScopeCurrent(_SavedStoreSearchVisit visit) =>
      mounted && identical(session, visit.source) &&
      session.activeWorkspace?.id == visit.storeId &&
      _searchAccountScope == visit.accountScope &&
      widget.accountAuthenticated == visit.authenticated;

  void _searchScopeChanged() {
    _refreshProductAssistantVersionOwner();
    if (!session.workspaceAccountCurrent(accountReady: _accountRecoveryReady)) {
      // Storage identity drift is not permission to keep showing the former
      // Store. Detach through its existing recovery owner, not a second reset.
      _retainedSavedSearch = null;
      _focusedOrderId = _focusedCustomerId = null;
      _salesVisitEpoch++;
      _salesTask = null; _salesTaskScope = null;
      final previousWorkspace = session.activeWorkspace;
      _recoverDashboardAccount();
      // Initial owner binding may retain a trusted same-owner Store. Keep its
      // requested operation; a real owner transition detaches it synchronously.
      if (!identical(session.activeWorkspace, previousWorkspace)) {
        _view = _WorkspaceControlView.dashboard;
      }
    }
    final visit = _savedSearchVisit;
    if (visit == null || _searchScopeCurrent(visit)) return;
    _savedSearchVisit = null;
    _searchVisitToken++;
    _ordersSearchStoreId = null;
    _ordersSearchReturnOrderId = null;
    _searchFocus.unfocus();
    _searchController.clear();
    // Reconcile only this obsolete local surface. Never clear the replacement
    // account/Store's session query from an old visit's notification/callback.
    if (_view == _WorkspaceControlView.search) _view = _WorkspaceControlView.dashboard;
  }
  void _recoverDashboardAccount({bool retry = false}) {
    final source = session, authenticated = widget.accountAuthenticated, ready = _accountRecoveryReady;
    final pending = source.recoverWorkspaceAccount(accountReady: ready, retry: retry);
    final owner = source.workspaceAccountRecoveryContext;
    if (retry && mounted) setState(() {});
    unawaited(pending.then((restored) {
      if (!restored || !mounted || !identical(session, source) || widget.accountAuthenticated != authenticated || _accountRecoveryReady != ready ||
          source.workspaceAccountRecoveryContext != owner) {
        return;
      }
      // The root retains document restoration/redirect ownership. This local
      // account reconciliation never consumes a pending proof operation.
      setState(() {});
      GoRouter.maybeOf(context)?.refresh();
    }));
  }
  final ScrollController _alertsScroll = ScrollController();
  final _financeOwner = ValueNotifier<int>(0);
  Object? _financeSnapshotOwner;
  int _financeSnapshotRevision = 0;
  int _financeFormRevision = 0;
  Object? _purchaseAssistantOwner;
  final _purchaseAssistantAnchors = <(String, String?), ({String signature, int version})>{};
  int _purchaseAssistantVersion = 0;
  Object? _stockAssistantOwner;
  final _stockAssistantVersions=<(String,String?),(String,int)>{};
  int _stockAssistantVersion = 0;
  Object? _supplierAdjustmentRecoveryOwner;
  String? _supplierAdjustmentRecoveryDigest;
  int _supplierAdjustmentRecoveryVersion = 0;
  Object? _supplierAdjustmentAssistantOwner;
  String? _supplierAdjustmentAssistantDigest;
  int _supplierAdjustmentAssistantVersion = 0;
  Object? _supplierAllocationAssistantOwner;
  String? _supplierAllocationAssistantDigest;
  int _supplierAllocationAssistantVersion = 0;
  Object? _supplierMoneyAssistantOwner;
  String? _supplierMoneyAssistantDigest;
  int _supplierMoneyAssistantVersion = 0;
  final Map<Object, (String, int)> _productAssistantVersions = {};
  Object? _productAssistantVersionOwner;
  int _productAssistantVersion = 0;
  bool _financeSheetOpen = false;
  bool _couponsSheetOpen = false;
  final ScrollController _settingsScroll = ScrollController();
  final ScrollController _homeContentScroll = ScrollController();
  final _settingsForm = GlobalKey<FormState>();
  double _settingsReturnOffset = 0;
  double _alertsReturnOffset = 0;
  String? _focusedOrderId, _focusedCustomerId;
  final _catalogueKey = GlobalKey<_WorkspaceCatalogueSurfaceState>();
  final _counterKey = GlobalKey<_CounterOrderSurfaceState>();
  final _purchaseEntryKey = GlobalKey<_StoreRecordPurchaseState>();
  final _purchasesKey = GlobalKey<_StorePurchasesSurfaceState>();
  final _receivingKey = GlobalKey<_StoreReceiveGoodsState>();
  bool _purchaseNavigationPending = false;
  bool _openingCounterSale = false;
  Offset? _saleSwipeStart;
  final _salesKey = GlobalKey<_StoreStatementSurfaceState>();
  String? _salesTask;
  int _salesVisitEpoch = 0;
  String get _salesTaskTitle => switch (_salesTask) {
    'counter' => 'Counter sale',
    'manage' => 'Manage sales',
    'records' => 'Recorded sales',
    _ => 'Sales',
  };
  Object? _salesTaskScope;
  final _saleSearchController = TextEditingController();
  final Map<String, Map<String, String>> _requirementDrafts = {};
  final Map<Object, _StockStatementBookmark> _stockStatementViews = {};
  final Map<Object, _PurchaseRegisterBookmark> _purchaseRegisterViews = {};
  _PurchaseRegisterBookmark? _purchaseRegisterBookmark() {
    final account = session.contactDraftStore?.accountScope ?? session.pendingProofStore?.accountScope;
    final store = session.activeWorkspace?.id;
    // Unknown identity must not create a shared null/Store-only cache entry.
    if (account == null || account.isEmpty || store == null) {
      return null;
    }
    return _purchaseRegisterViews.putIfAbsent(
      (account, store, session.workspaceSupplierScope), _PurchaseRegisterBookmark.new);
  }
  final Set<Object> _collapsedStockActions = {};
  bool _requirementPickerOpen = false;
  _WorkspaceControlView _view = _WorkspaceControlView.dashboard;
  bool _draftAcceptingOrders = true;
  bool _draftVisibleToCustomers = false;
  String _draftFulfilmentMode = 'Delivery and pickup';
  int _draftBusyMinutes = 0;
  String _draftReopensAt = '';
  String _draftOpeningTime = '8:00 AM';
  String _draftClosingTime = '10:00 PM';
  int _draftMaximumActiveOrders = 8;
  bool _draftOrderAlertSound = true;
  bool _draftOrderAlertVibration = true;
  String? _settingsStoreId;
  String? _settingsPrivateSourceProof;
  int? _settingsScopeRevision;
  bool _settingsOpening = false, _settingsSaving = false;
  _WorkspaceOperation _operation = _WorkspaceOperation.orders;
  _WorkspaceControlView _operationReturnView = _WorkspaceControlView.dashboard;
  _WorkspaceFinanceFocus? _focusedFinance;
  _WorkspaceOperation? _operationReturnOperation;
  int _deliveryOrderVisit = 0;
  ({int visit, String orderId, String? selectedOrderId, String? storeId, String? accountScope,
    _WorkspaceControlView returnView, _WorkspaceOperation? returnOperation})?
      _deliveryOrderOrigin;
  Timer? _procurementRevealTimer;
  bool _procurementReady = false;
  bool _procurementSearchOpen = false;
  _WorkspaceOperation? _procurementReturnOperation;
  String? _procurementProductId;
  WorkspacePurchaseRecord? _trackedPurchase;
  bool _directFilterApplied = false;
  String? _filterBeforeDirect;
  WorkspaceOrderRecord? _reviewedOrder;

  @override
  void initState() {
    super.initState();
    session.clearMessages();
    if (widget.useStoreProcurement) {
      _storeProcurement =
          widget.procurementControllerFactory?.call() ??
          WorkProcurementController(
            currentAccountId: () => widget.accountAuthenticated
                ? session.contactDraftStore?.accountScope
                : null,
            currentStoreId: () => session.activeWorkspace?.id,
            currentProfileId: () => session.activeWorkspace?.profileId,
            storeApproved: () => session.activeWorkspace?.verified == true,
            reviewCatalogueAllowed: () => session.canLoadStoreReviewSeed,
            catalogueGateway: session.catalogueGateway is AuthenticatedWorkspaceCatalogueGateway
                ? session.catalogueGateway as AuthenticatedWorkspaceCatalogueGateway : null,
            originalPurchaseReader: () => session.originalPurchaseReader,
            originalPurchaseRealm: () => session.originalPurchaseRealm,
          );
      session.addListener(_procurementIdentityChanged);
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted) unawaited(_restoreProcurement());
      });
    }
    session.bindWorkspaceAssistantRestockReader(this, _captureAssistantRestockReadHints);
    _searchController = TextEditingController(
      text: session.workspaceSearchQuery,
    );
    session.addListener(_searchScopeChanged);
    session.addListener(_settlementObserveSource);
    _settlementObserveSource();
    WidgetsBinding.instance.addPostFrameCallback((_) {if (mounted) _searchScopeChanged();});
    _storeProcurement?.addListener(_observeProcurementQuery);
    _observeProcurementQuery();
    final section = switch (widget.initialSection) {
      'orders' => _WorkspaceOperation.orders,
      'sell' => _WorkspaceOperation.counterOrder,
      'stock' => _WorkspaceOperation.catalogue,
      _ => null,
    };
    if (section != null) {
      _operation = section;
      _view = _WorkspaceControlView.operation;
    }
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted || ModalRoute.of(context)?.isCurrent != true) return;
      if (!session.takeWorkspaceApprovalWelcome()) return;
      _workspaceMessengerKey.currentState?.showSnackBar(
        const SnackBar(
          content: Text(
            'Welcome to MoolSocial. Your Workspace is approved.',
            key: Key('work-approval-welcome'),
            style: TextStyle(fontSize: 13, height: 1.3, color: Colors.white),
          ),
          backgroundColor: MoolColors.navy,
          elevation: 0,
          padding: EdgeInsets.symmetric(horizontal: 12, vertical: 8),
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.all(Radius.circular(12)),
          ),
          behavior: SnackBarBehavior.floating,
          duration: Duration(seconds: 4),
          showCloseIcon: true,
          closeIconColor: Colors.white,
        ),
      );
    });
  }

  @override
  void dispose() {
    session.clearWorkspaceAssistantRestockReader(this);
    session.removeListener(_searchScopeChanged);
    session.removeListener(_settlementObserveSource);
    _financeOwner.value++;
    _productAssistantVersions.clear();
    _productAssistantVersionOwner = null;
    _settingsReviewScope?.dispose(); _alertSettingsReviewScope?.dispose();
    _financeOwner.dispose();
    session.removeListener(_procurementIdentityChanged);
    _storeProcurement?.removeListener(_observeProcurementQuery);
    _observedProcurement?.removeListener(_procurementQueryChanged);
    _storeProcurement?.dispose();
    _saleSearchController.dispose();
    _procurementRevealTimer?.cancel();
    _searchController.dispose();
    _searchScroll.dispose();
    _alertsScroll.dispose();
    _settingsScroll.dispose();
    _homeContentScroll.dispose();
    _searchFocus.dispose();
    super.dispose();
  }

  void _observeProcurementQuery() {
    final purchase = _activeProcurement;
    if (identical(purchase, _observedProcurement)) return;
    _observedProcurement?.removeListener(_procurementQueryChanged);
    _observedProcurement = purchase;
    _observedProcurementQuery = purchase.query;
    _observedProcurementView = purchase.view;
    _observedProcurementItemCount = purchase.itemCount;
    purchase.addListener(_procurementQueryChanged);
  }

  void _procurementQueryChanged() {
    final query = _observedProcurement?.query;
    final view = _observedProcurement?.view;
    final itemCount = _observedProcurement?.itemCount;
    if (query == _observedProcurementQuery && view == _observedProcurementView &&
        itemCount == _observedProcurementItemCount) {
      return;
    }
    _observedProcurementQuery = query;
    _observedProcurementView = view;
    _observedProcurementItemCount = itemCount;
    if (!mounted || _view != _WorkspaceControlView.procurement) return;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted || _view != _WorkspaceControlView.procurement) return;
      final currentQuery = _activeProcurement.query;
      if (_searchController.text != currentQuery) {
        _searchController.value = TextEditingValue(
          text: currentQuery,
          selection: TextSelection.collapsed(offset: currentQuery.length),
        );
      }
      setState(() {});
    });
  }

  @override
  Widget build(BuildContext context) {
    final inherited = context.getInheritedWidgetOfExactType<MoolAssistantNativeScope>();
    return MoolAssistantNativeScope(
      readAdapters: (hostContext) {
        final existing = inherited?.readAdapters(hostContext).toList() ??
            <MoolAssistantNativeAdapter>[];
        final trusted = _financeAssistantContext(hostContext);
        final supplierSource = session;
        final invoice = _purchaseEntryKey.currentState;
        final receiving = _receivingKey.currentState;
        final activeReceiving = receiving != null && _assistantReceivingOwnerActive(receiving);
        MoolAssistantNativeSnapshot? receivingSnapshot(
          MoolAssistantContext ctx, String? entity, String action,
        ) {
          final now = _financeAssistantContext(hostContext);
          if (receiving == null || now == null || now.binding != ctx.binding ||
              !_financePermitted(ctx) || !_assistantReceivingOwnerActive(receiving)) return null;
          return receiving._assistantReceiptSnapshot(ctx, entity, action);
        }
        return [
          ...existing,
          if(trusted!=null&&_financePermitted(trusted))for(final action in const ['AI-ACT-284','AI-ACT-285','AI-ACT-286','AI-ACT-287'])
            if(!existing.any((adapter)=>adapter.actionId==action))_StoreOrderFollowupAdapter(actionId:action,
              read:(ctx,entity)=>_orderFollowupSnapshot(hostContext,supplierSource,action,ctx,entity),
              open:(proposal,current,changes)=>_openOrderFollowupNative(hostContext,supplierSource,proposal,current,changes)),
          if(trusted!=null&&_financePermitted(trusted)&&!existing.any((adapter)=>adapter.actionId=='AI-ACT-280'))
            _StoreOrderPackingAdapter(read:(ctx,entity)=>_orderPackingSnapshot(hostContext,supplierSource,ctx,entity),
              open:(proposal,current,changes)=>_openOrderPackingNative(hostContext,supplierSource,proposal,current,changes)),
          if(trusted!=null&&_financePermitted(trusted))for(final action in const ['AI-ACT-282','AI-ACT-283'])
            if(!existing.any((adapter)=>adapter.actionId==action))_StoreOrderPhysicalAdapter(actionId:action,
              read:(ctx,entity)=>_orderPhysicalSnapshot(hostContext,supplierSource,action,ctx,entity),
              open:(proposal,current,changes)=>_openOrderPhysicalNative(hostContext,supplierSource,proposal,current,changes)),
          if(trusted!=null&&_financePermitted(trusted))for(final action in const ['AI-ACT-277','AI-ACT-278','AI-ACT-279'])
            if(!existing.any((adapter)=>adapter.actionId==action))_StoreOrderIssueAdapter(actionId:action,
              read:(ctx,entity)=>_orderIssueSnapshot(hostContext,supplierSource,action,ctx,entity),
              open:(proposal,current,changes)=>_openOrderIssueNative(hostContext,supplierSource,proposal,current,changes)),
          if(trusted!=null&&_financePermitted(trusted)&&!existing.any((adapter)=>adapter.actionId=='AI-ACT-276'))
            _StoreOrderTimeNativeAdapter(read:(ctx,entity)=>_orderTimeSnapshot(hostContext,supplierSource,ctx,entity),
              open:(proposal,current,changes)=>_openOrderTimeNative(hostContext,supplierSource,proposal,current,changes)),
          for(final action in const ['AI-ACT-275','AI-ACT-281'])
            if(trusted!=null&&_financePermitted(trusted)&&!existing.any((adapter)=>adapter.actionId==action))
              _StoreOrderEffectAdapter(actionId:action,read:(ctx,entity)=>_orderEffectSnapshot(hostContext,supplierSource,action,ctx,entity),
                open:(proposal,current,changes)=>_openOrderEffectNative(hostContext,supplierSource,proposal,current,changes)),
          if(trusted!=null&&_financePermitted(trusted)&&!existing.any((adapter)=>adapter.actionId=='AI-ACT-273'))
            _StoreOrderStatusNativeAdapter(read:(ctx,entity)=>_orderStatusSnapshot(hostContext,supplierSource,ctx,entity),
              open:(proposal,current)=>_openOrderStatusNative(hostContext,supplierSource,proposal,current)),
          if(trusted!=null&&_financePermitted(trusted)&&!existing.any((adapter)=>adapter.actionId=='AI-ACT-234'))
            _StoreRestockNativeAdapter(read:(ctx,entity)=>_restockSnapshot(hostContext,supplierSource,ctx,entity),
              open:(proposal,current,changes)=>_openRestockNative(hostContext,supplierSource,proposal,current,changes)),
          if (trusted != null && _financePermitted(trusted))
            for (final action in const ['AI-ACT-308', 'AI-ACT-309', 'AI-ACT-310'])
