  Widget _buildDashboard() {
    return AnimatedBuilder(
      animation: session,
      builder: (context, _) {
        final pending = !session.workspaceAccountCurrent(accountReady: _accountRecoveryReady) || session.workspaceAccountRecoveryPending;
        if (pending || session.workspaceAccountRecoveryFailed) {
          final owner = session.workspaceAccountRecoveryContext, authenticated = widget.accountAuthenticated, ready = _accountRecoveryReady;
          return WorkPageScaffold(session: session, title: 'Your Workspace', subtitle: 'Account access',
            fallbackBackRoute: '/app/work/earn', activeLocalAction: 'workspace', showHeaderChat: false, showTrailingAction: false,
            showBottomNavigation: false, showMessageBanner: false,
            body: pending ? const Center(child: SingleChildScrollView(child: Padding(padding: EdgeInsets.all(24),
              child: Column(key: Key('work-account-recovery'), mainAxisSize: MainAxisSize.min, children: [
                CircularProgressIndicator(semanticsLabel: 'Restoring your Workspace'), SizedBox(height: 16),
                Text('Restoring your Workspace…', textAlign: TextAlign.center),
              ])))) : WorkEmptyState(keyName: 'work-account-recovery-error', title: 'Workspace access unavailable',
              detail: 'Saved details could not be restored. Your saved Store data is kept.', actionLabel: 'Try again',
              onAction: () {
                if (mounted && session.workspaceAccountRecoveryContext == owner && widget.accountAuthenticated == authenticated && _accountRecoveryReady == ready) {
                  _recoverDashboardAccount(retry: true);
                }
              }));
        }
        final workspace = session.activeWorkspace;
        final profile = workspace == null
            ? null
            : _profileForWorkspace(session, workspace);
        if (workspace == null || profile == null || !workspace.verified) {
          return WorkPageScaffold(
            session: session,
            title: 'Your Workspace',
            subtitle: 'Business and professional tools',
            fallbackBackRoute: '/app/work/earn',
            activeLocalAction: 'workspace',
            showHeaderChat: false,
            showTrailingAction: false,
            body: WorkEmptyState(
              title: 'No approved Workspace yet',
              detail:
                  'Choose how you work and complete the review before opening your dashboard.',
              actionLabel: 'Choose a Workspace',
              onAction: () => context.go('/app/work/workspace/choose'),
            ),
          );
        }

        final presentation = _presentationFor(profile);
        final retailer = const {
          'retailer-grocery',
          'retailer-speciality',
        }.contains(profile.id);
        if (retailer || session.workspaceStoreAuthoringAvailable) {
          return _buildRetailerControls(
            context,
            workspace: workspace,
            profile: profile,
          );
        }
        return WorkPageScaffold(
          session: session,
          title: workspace.name,
          subtitle: '${profile.label} · ${workspace.area}',
          fallbackBackRoute: '/app/work/earn',
          activeLocalAction: 'workspace',
          showHeaderChat: false,
          showTrailingAction: false,
          bottomAction: WorkPrimaryButton(
            keyName: 'work-dashboard-earn',
            label: presentation.earnAction,
            icon: Icons.bolt_rounded,
            onPressed: () => context.go('/app/work/earn'),
          ),
          body: ListView(
            key: const Key('work-workspace-dashboard'),
            padding: const EdgeInsets.fromLTRB(
              MoolSpacing.md,
              MoolSpacing.sm,
              MoolSpacing.md,
              MoolSpacing.xl,
            ),
            children: [
              _DashboardReveal(
                child: _WorkspaceDashboardHero(
                  workspace: workspace,
                  profile: profile,
                ),
              ),
              const SizedBox(height: MoolSpacing.md),
              _DashboardReveal(
                delay: const Duration(milliseconds: 70),
                child: WorkSectionTitle(
                  title: presentation.title,
                  detail: presentation.detail,
                ),
              ),
              const SizedBox(height: MoolSpacing.sm),
              _DashboardReveal(
                delay: const Duration(milliseconds: 110),
                child: Row(
                  children: [
                    for (
                      var index = 0;
                      index < presentation.signals.length;
                      index++
                    ) ...[
                      Expanded(
                        child: _DashboardSignal(
                          icon: presentation.signals[index].icon,
                          label: presentation.signals[index].label,
                        ),
                      ),
                      if (index < presentation.signals.length - 1)
                        const SizedBox(width: 6),
                    ],
                  ],
                ),
              ),
              const SizedBox(height: MoolSpacing.md),
              _DashboardReveal(
                delay: const Duration(milliseconds: 150),
                child: _DashboardPriorityCard(
                  session: session,
                  profile: profile,
                  presentation: presentation,
                ),
              ),
              const SizedBox(height: MoolSpacing.md),
              const WorkSectionTitle(
                title: 'Grow with one connected Workspace',
                detail:
                    'Your approved identity stays connected while each tool follows how you work.',
              ),
              const SizedBox(height: MoolSpacing.sm),
              _DashboardCapability(
                keyName: 'work-dashboard-customers',
                icon: Icons.campaign_outlined,
                title: presentation.customerTitle,
                detail: profile.sellSide,
              ),
              const SizedBox(height: MoolSpacing.xs),
              _DashboardCapability(
                keyName: 'work-dashboard-sourcing',
                icon: Icons.handshake_outlined,
                title: presentation.networkTitle,
                detail: profile.buySide,
              ),
              const SizedBox(height: MoolSpacing.xs),
              _DashboardCapability(
                keyName: 'work-dashboard-tools',
                icon: Icons.dashboard_customize_outlined,
                title: presentation.toolsTitle,
                detail: profile.tools,
              ),
              const SizedBox(height: MoolSpacing.md),
              _WorkspaceAccountState(session: session, workspace: workspace),
              const SizedBox(height: MoolSpacing.md),
              Row(
                children: [
                  Expanded(
                    child: OutlinedButton.icon(
                      key: const Key('work-dashboard-manage-record'),
                      onPressed: () =>
                          context.push('/app/work/workspace/proof'),
                      icon: const Icon(Icons.fact_check_outlined),
                      label: const Text('Workspace record'),
                    ),
                  ),
                  const SizedBox(width: MoolSpacing.xs),
                  Expanded(
                    child: OutlinedButton.icon(
                      key: const Key('work-dashboard-add-workspace'),
                      onPressed: () {
                        if (session.startAnotherWork()) {
                          context.push('/app/work/workspace/choose');
                        }
                      },
                      icon: const Icon(Icons.add_business_outlined),
                      label: const Text('Add Workspace'),
                    ),
                  ),
                ],
              ),
            ],
          ),
        );
      },
    );
  }

  Widget _buildRetailerControls(
    BuildContext context, {
    required WorkWorkspace workspace,
    required WorkProfileOption profile,
  }) {
    final savedSearchVisit = _savedSearchVisit;
    const dashboardReturn = '/app/work/workspace/dashboard';
    void openRetailer(
      String path, {
      Map<String, String> queryParameters = const {},
    }) {
      context.push(
        Uri(
          path: path,
          queryParameters: {
            ...queryParameters,
            'workspaceId': workspace.id,
            'return': dashboardReturn,
          },
        ).toString(),
      );
    }

    void openScopedRoute(String route) {
      if (!mounted || session.activeWorkspace?.id != workspace.id) return;
      final target = Uri.parse(route);
      if (target.path == '/app/buy' &&
          const {
            'wholesale',
            'business',
          }.contains(target.queryParameters['sub'])) {
        _showProcurement(
          productId: target.queryParameters['product'],
          searchQuery: target.queryParameters['search'],
          returnOperation: _view == _WorkspaceControlView.operation
              ? _operation
              : null,
        );
        return;
      }
      if (target.path == '/app/work/workspace/dashboard') {
        _showStatus();
        return;
      }
      if (target.path.startsWith('/app/retailer')) {
        final operation = switch (target.path) {
          '/app/retailer/orders' => _WorkspaceOperation.orders,
          '/app/retailer/customers' => _WorkspaceOperation.customers,
          '/app/retailer/books/money' => _WorkspaceOperation.payments,
          '/app/retailer/books' => _WorkspaceOperation.books,
          '/app/retailer/wholesale' => _WorkspaceOperation.sourcing,
          '/app/retailer/home' when target.queryParameters['view'] == 'stock' =>
            _WorkspaceOperation.catalogue,
          _ => null,
        };
        if (operation != null) {
          final orderId = operation == _WorkspaceOperation.orders
              ? target.queryParameters['order']
              : null;
          if (orderId != null &&
              !session.visibleWorkspaceOrders.any(
                (order) => order.id == orderId,
              )) {
            session.showNotice('This order is no longer available.');
            return;
          }
          if (orderId != null && _openCounterSaleInvoice(orderId)) return;
          final fromAlerts = _view == _WorkspaceControlView.alerts;
          if (fromAlerts) {
            _alertsReturnOffset = _alertsScroll.hasClients
                ? _alertsScroll.offset
                : 0;
          }
          _showOperation(
            operation,
            focusedOrderId: orderId,
            returnView: fromAlerts ? _WorkspaceControlView.alerts : null,
          );
          return;
        }
        openRetailer(target.path, queryParameters: target.queryParameters);
        return;
      }
      context.push(
        target
            .replace(
              queryParameters: {
                ...target.queryParameters,
                'workspaceId': workspace.id,
                'return': dashboardReturn,
              },
            )
            .toString(),
      );
    }

    final title = switch (_view) {
      _WorkspaceControlView.dashboard => workspace.name,
      _WorkspaceControlView.search => 'Search your store',
      _WorkspaceControlView.status => 'Store settings',
      _WorkspaceControlView.alerts => 'Needs your attention',
      _WorkspaceControlView.procurement => 'Buying for ${workspace.name}',
      _WorkspaceControlView.operation =>
        _operation == _WorkspaceOperation.counterOrder &&
                session.workspaceOrderNeedsDelivery
            ? 'Deliver order'
            : _operation == _WorkspaceOperation.counterOrder
            ? 'New sale'
            : _operation.title,
    };
    final subtitle = switch (_view) {
      _WorkspaceControlView.dashboard => '${profile.label} · ${workspace.area}',
      _WorkspaceControlView.search =>
        'Find orders, products, customers or business records',
      _WorkspaceControlView.status => 'Open, pause and run your store',
      _WorkspaceControlView.alerts => 'Orders and tasks needing action',
      _WorkspaceControlView.procurement => '',
      _WorkspaceControlView.operation =>
        _operation == _WorkspaceOperation.counterOrder &&
                session.workspaceOrderNeedsDelivery
            ? 'Phone, Counter or Chat order with customer delivery'
            : _operation.subtitle,
    };
    final statusOwner = session, statusStore = session.activeWorkspace?.id ?? session.workspaceId;
    final statusNavigation = session.navigationScopeRevision, statusPrincipal = widget.accountIdentity;
    final statusContext = session.publicationPreferencesContext, statusReview = _settingsReviewScope;
    final statusDraftGeneration = _settingsDraftGeneration;
    bool statusCurrent() => mounted && identical(session, statusOwner) && identical(widget.accountIdentity, statusPrincipal) &&
      session.publicationPreferencesContext == statusContext && session.navigationScopeRevision == statusNavigation &&
      (session.activeWorkspace?.id ?? session.workspaceId) == statusStore && identical(_settingsReviewScope, statusReview) &&
      _settingsDraftGeneration == statusDraftGeneration && _view == _WorkspaceControlView.status && statusReview?.current() != false &&
      !_settingsSaving && !session.workspaceTradingPreferencesSaving;
    final bottomAction = switch (_view) {
      _WorkspaceControlView.dashboard when _reviewedOrder == null => Wrap(
        alignment: WrapAlignment.center, spacing: 8, children: [
          IntrinsicWidth(child: _StoreEdgeAction(keyName: 'work-home-coupons', label: 'Coupons',
            icon: Icons.local_offer_outlined, onTap: () => unawaited(_showCoupons()))),
          IntrinsicWidth(child: _StoreEdgeAction(keyName: 'work-home-business-finance', label: 'Business finance',
            icon: Icons.account_balance_outlined, onTap: () => unawaited(_showBusinessFinance()))),
        ]),
      _WorkspaceControlView.status => WorkPrimaryButton(
        keyName: 'work-status-save',
        label: _settingsSaving || session.workspaceTradingPreferencesSaving || session.workspacePrivatePreferenceBusy(WorkspacePrivatePreferenceKind.status)
          ? 'Saving…' : session.workspaceOriginalPrivatePreferencesConfigured ? 'Save preferences' : 'Apply settings',
        busy: _settingsSaving || session.workspaceTradingPreferencesSaving || session.workspacePrivatePreferenceBusy(WorkspacePrivatePreferenceKind.status),
        icon: Icons.check_circle_outline_rounded,
        onPressed: () => statusCurrent() ? _saveAvailability(reviewScope: statusReview, current: statusCurrent) : Future<void>.value(),
      ),
      _ => null,
    };
    final storeActiveId = switch ((_view, _operation)) {
      (_WorkspaceControlView.search, _) when
          _ordersSearchStoreId == workspace.id => 'orders',
      (_WorkspaceControlView.operation, _WorkspaceOperation.dues)
          when _operationReturnView == _WorkspaceControlView.operation &&
              _operationReturnOperation == _WorkspaceOperation.sales => 'sell',
      (_WorkspaceControlView.operation, _WorkspaceOperation.orders) => 'orders',
      (_WorkspaceControlView.operation, _WorkspaceOperation.delivery) =>
        'orders',
      (_WorkspaceControlView.operation, _WorkspaceOperation.counterOrder) =>
        'sell',
      (_WorkspaceControlView.operation, _WorkspaceOperation.sales) => 'sell',
      (_WorkspaceControlView.operation, _WorkspaceOperation.catalogue) =>
        'stock',
      (_WorkspaceControlView.operation, _WorkspaceOperation.stockStatement) =>
        'stock',
      (_WorkspaceControlView.operation, _WorkspaceOperation.sourcing) =>
        'stock',
      (_WorkspaceControlView.operation, _WorkspaceOperation.groupBuying) =>
        'stock',
      (
        _WorkspaceControlView.operation,
        _WorkspaceOperation.customers ||
            _WorkspaceOperation.payments ||
            _WorkspaceOperation.growth ||
            _WorkspaceOperation.books ||
            _WorkspaceOperation.services ||
            _WorkspaceOperation.settings ||
            _WorkspaceOperation.deliverySettings ||
            _WorkspaceOperation.staff ||
            _WorkspaceOperation.offers ||
            _WorkspaceOperation.paidWork ||
            _WorkspaceOperation.statement ||
            _WorkspaceOperation.dues ||
            _WorkspaceOperation.storeLink ||
            _WorkspaceOperation.direct,
      ) =>
        'store',
      (_WorkspaceControlView.status || _WorkspaceControlView.alerts, _) =>
        'store',
      (_WorkspaceControlView.procurement, _) => 'stock',
      _ => 'store',
    };
    final storeActions = [
      MoolLocalNavigationAction(
        keyName: 'work-store-home',
        id: 'store',
        label: 'Store',
        icon: Icons.storefront_outlined,
        onPressed: _view == _WorkspaceControlView.dashboard
            ? null
            : _view == _WorkspaceControlView.status
            ? () => unawaited(_leaveSettings())
            : () => unawaited(_navigateFromCounterDraft(_showDashboard)),
      ),
      MoolLocalNavigationAction(
        keyName: 'work-store-orders',
        id: 'orders',
        label: 'Orders',
        icon: Icons.receipt_long_outlined,
        onPressed:
            _view == _WorkspaceControlView.operation &&
                _operation == _WorkspaceOperation.orders
            ? null
            : () => unawaited(
                _navigateFromCounterDraft(
                  () => _showOperation(_WorkspaceOperation.orders),
                ),
              ),
      ),
      MoolLocalNavigationAction(
        keyName: 'work-store-sell',
        id: 'sell',
        label: 'Sales',
        icon: Icons.receipt_long_outlined,
        onPressed:
            _operation == _WorkspaceOperation.sales &&
                _view == _WorkspaceControlView.operation
            ? null
            : () => unawaited(
                _navigateFromCounterDraft(
                  () => _showOperation(_WorkspaceOperation.sales),
                ),
              ),
      ),
      MoolLocalNavigationAction(
        keyName: 'work-store-stock',
        id: 'stock',
        label: 'Stock',
        icon: Icons.inventory_2_outlined,
        onPressed:
            _view == _WorkspaceControlView.operation &&
                _operation == _WorkspaceOperation.catalogue
            ? null
            : () => unawaited(
                _navigateFromCounterDraft(
                  () => _showOperation(_WorkspaceOperation.catalogue),
                ),
              ),
      ),
    ];
    final restockNavigationSession = _view == _WorkspaceControlView.procurement &&
        _activeProcurement.procurementContext?.purpose == BuyV2ProcurementPurpose.restock
        ? _activeProcurement : null;
    final compactSettings =
        _view == _WorkspaceControlView.status ||
        (_view == _WorkspaceControlView.operation &&
            (_operation == _WorkspaceOperation.deliverySettings ||
                _operation == _WorkspaceOperation.staff));
    final analyticsSurface = _view == _WorkspaceControlView.dashboard && _reviewedOrder == null &&
      (session.retailerSetupSaved || session.reviewStage == WorkReviewStage.live);
    final showStoreProfile =
        _view == _WorkspaceControlView.dashboard && _reviewedOrder == null;
    final storeRootSurface =
        _view == _WorkspaceControlView.dashboard ||
        _view == _WorkspaceControlView.search ||
        _view == _WorkspaceControlView.alerts ||
        _view == _WorkspaceControlView.operation ||
        _view == _WorkspaceControlView.procurement;

    final saleOpen =
        _view == _WorkspaceControlView.operation &&
        _operation == _WorkspaceOperation.counterOrder;
    final salesOpen =
        _view == _WorkspaceControlView.operation &&
        _operation == _WorkspaceOperation.sales;
    final salesTaskScope = session.workspaceStockHistoryScope()?.key ?? workspace.id;
    if (_salesTaskScope != salesTaskScope) {
      _salesTaskScope = salesTaskScope;
      _salesTask = null;
      _salesVisitEpoch++;
    }
    final salesTaskOpen = salesOpen && _salesTask != null ||
        _view == _WorkspaceControlView.operation && _operationReturnOperation == _WorkspaceOperation.sales;
    final procurementOpen = _view == _WorkspaceControlView.procurement;
    final sharedRestock = procurementOpen &&
        _activeProcurement.procurementContext?.purpose ==
            BuyV2ProcurementPurpose.restock;
    final restockSharedHeader = sharedRestock &&
        _activeProcurement.destination == BuyV2Destination.wholesale &&
        (_activeProcurement.view == BuyV2View.cart ||
            _activeProcurement.view == BuyV2View.checkout ||
            !_procurementRouteCovered &&
                (_activeProcurement.view == BuyV2View.catalogue ||
                    _activeProcurement.view == BuyV2View.product));
    final ordersContext =
        (_view == _WorkspaceControlView.operation &&
            _operation == _WorkspaceOperation.orders) ||
        (_view == _WorkspaceControlView.search &&
            _ordersSearchStoreId == workspace.id);
    final ordersOperation = _view == _WorkspaceControlView.operation &&
        _operation == _WorkspaceOperation.orders;
    final compactOperation =
        _view == _WorkspaceControlView.operation &&
        const {
          _WorkspaceOperation.catalogue,
          _WorkspaceOperation.stockStatement,
          _WorkspaceOperation.sales,
          _WorkspaceOperation.statement,
          _WorkspaceOperation.dues,
          _WorkspaceOperation.payments,
          _WorkspaceOperation.sourcing,
          _WorkspaceOperation.groupBuying,
          _WorkspaceOperation.storeLink,
          _WorkspaceOperation.offers,
          _WorkspaceOperation.paidWork,
        }.contains(_operation);
    final stockSectionRoot =
        _view == _WorkspaceControlView.operation &&
        _operation == _WorkspaceOperation.catalogue &&
        _operationReturnView == _WorkspaceControlView.dashboard &&
        !_directFilterApplied;
    final hasHeaderBack =
        procurementOpen ||
        (_view == _WorkspaceControlView.operation && !stockSectionRoot) ||
        _view == _WorkspaceControlView.alerts ||
        _reviewedOrder != null;
    final shortHomeHeader =
        (_view == _WorkspaceControlView.dashboard ||
          (_view == _WorkspaceControlView.search && ordersContext)) &&
        MediaQuery.sizeOf(context).width >= 700 &&
        MediaQuery.sizeOf(context).height <= 450;
    final headerNameWidth = ((shortHomeHeader
        ? (MediaQuery.sizeOf(context).width - 40) / 2
        : MediaQuery.sizeOf(context).width) -
      (procurementOpen ? 137 : 127) - (showStoreProfile ? 48 : 0) -
      (hasHeaderBack ? (procurementOpen ? 51 : 47) : 0)).clamp(64.0, double.infinity);
    final namePainter =
        TextPainter(
          text: TextSpan(
            text: workspace.name,
            style: Theme.of(context).textTheme.titleLarge!.copyWith(
              fontSize: analyticsSurface ? 16 : 13,
              fontWeight: FontWeight.w800,
            ),
          ),
          textDirection: Directionality.of(context),
          textScaler: MediaQuery.textScalerOf(context),
          maxLines: procurementOpen ? 2 : null,
          ellipsis: procurementOpen ? '…' : null,
        )..layout(maxWidth: headerNameWidth);
    final buyerCaptionPainter = procurementOpen ? (TextPainter(
      text: const TextSpan(text: 'Buying for', style: TextStyle(fontSize: 10, height: 1.2, fontWeight: FontWeight.w600)),
      textDirection: Directionality.of(context), textScaler: MediaQuery.textScalerOf(context),
    )..layout(maxWidth: headerNameWidth)) : null;
    final storeHeaderHeight =
        (compactOperation || ordersOperation || shortHomeHeader || sharedRestock ? 0 : 47) +
        (namePainter.height + (buyerCaptionPainter?.height ?? 0) + (procurementOpen ? 2 : 0) + 8).clamp(
          procurementOpen || ordersOperation || shortHomeHeader ? 48.0 : 44.0,
          double.infinity,
        );
    final analyticsHeaderHeight = (namePainter.height + 12).clamp(48.0, double.infinity);
    namePainter.dispose();
    buyerCaptionPainter?.dispose();
    final composerStore = session.activeWorkspace?.id ?? session.workspaceId;
    final composerAccount = session.contactDraftStore?.accountScope ?? session.pendingProofStore?.accountScope;
    Widget counterSurface(bool expanded) => _CounterOrderSurface(
      key: _counterKey,
      query: _saleSearchController.text,
      session: session,
      fullScreen: expanded,
      onExit: () => unawaited(_leaveOperation()),
      onArrangeDelivery: (orderId) {
          final saved = session.currentWorkspaceOrder;
          if (!mounted || _view != _WorkspaceControlView.operation ||
              !(_operation == _WorkspaceOperation.counterOrder ||
                (_operation == _WorkspaceOperation.sales && _salesTask == 'counter')) ||
              (session.activeWorkspace?.id ?? session.workspaceId) != composerStore ||
              (session.contactDraftStore?.accountScope ?? session.pendingProofStore?.accountScope) != composerAccount ||
              session.currentWorkspaceOrderId != orderId || saved?.id != orderId ||
              !saved!.needsDelivery || saved.isCustomerCollection ||
              !const ['Own delivery', 'Mool delivery'].contains(saved.fulfilment) ||
              saved.stage != 'Confirmed') {
            return;
          }
          // Exact successful submission is not an unfinished draft. Do not
          // reset its selected saved identity or attempt another journal save.
          _showOperation(_WorkspaceOperation.orders);
      },
      onOpenCatalogue: () => unawaited(
        _navigateFromCounterDraft(
          () => _showOperation(_WorkspaceOperation.catalogue),
        ),
      ),
    );
    if (saleOpen) {
      void goBack() => unawaited(_leaveOperation());
      return Theme(
        data: _counterSaleTheme(Theme.of(context)),
        child: PopScope(
          canPop: false,
          onPopInvokedWithResult: (didPop, result) {
            if (!didPop) goBack();
          },
          child: Listener(
            onPointerDown: (event) => _saleSwipeStart = event.position.dx < 24
                ? event.position
                : null,
            onPointerUp: (event) {
              final start = _saleSwipeStart;
              _saleSwipeStart = null;
              if (start != null &&
                  event.position.dx - start.dx > 80 &&
                  (event.position.dy - start.dy).abs() < 60) {
                goBack();
              }
            },
            child: Scaffold(
              appBar: AppBar(
                flexibleSpace: const SizedBox.expand(
                  child: DecoratedBox(
                    key: Key('work-counter-header-gradient'),
                    decoration: BoxDecoration(
                      gradient: _counterSaleHeaderGradient,
                    ),
                  ),
                ),
                leading: IconButton(
                  key: const Key('work-counter-fullscreen-back'),
                  tooltip: 'Back',
                  onPressed: goBack,
                  icon: const Icon(Icons.arrow_back),
                ),
                toolbarHeight:
                    (MediaQuery.textScalerOf(context).scale(18) * 2.4).clamp(
                      kToolbarHeight,
                      double.infinity,
                    ),
                title: Text(
                  'Counter sale',
                  softWrap: true,
                  maxLines: 2,
                  style: TextStyle(fontSize: 18),
                ),
                actions: [
                  IconButton(
                    key: const Key('work-counter-close'),
                    tooltip: 'Close sale',
                    onPressed: () => unawaited(_leaveOperation(exitSale: true)),
                    icon: const Icon(Icons.close),
                  ),
                ],
              ),
              body: SafeArea(
                maintainBottomViewPadding: true,
                child: counterSurface(true),
              ),
            ),
          ),
        ),
      );
    }
    final page = WorkPageScaffold(
      session: session,
      title: title,
      subtitle: subtitle,
      beforeExternalNavigation: _confirmPurchaseNavigation,
      contentMaxWidth: (salesOpen || ordersContext ||
          (_view == _WorkspaceControlView.operation &&
            _operation == _WorkspaceOperation.sourcing)) &&
          MediaQuery.sizeOf(context).width >= 700 &&
          MediaQuery.sizeOf(context).height <= 450
          ? double.infinity : MoolMetrics.maximumContentWidth,
      showBottomNavigation: !salesTaskOpen && restockNavigationSession == null,
      headerHeight: restockSharedHeader ? 0 : salesTaskOpen
          ? MediaQuery.textScalerOf(context).scale(18).clamp(48, 72)
          : analyticsSurface
          ? analyticsHeaderHeight
          : compactSettings
          ? 64
          : storeRootSurface
          ? storeHeaderHeight
          : 88,
      headerTitle: restockSharedHeader ? const SizedBox.shrink() : salesTaskOpen
          ? Text(salesOpen ? _salesTaskTitle : title, key: const Key('work-sales-task-heading'),
              style: const TextStyle(fontSize: 18, fontWeight: FontWeight.w600))
          : analyticsSurface
          ? Row(children: [
              Expanded(child: Text(workspace.name, key: const Key('work-store-full-name'),
                style: const TextStyle(fontSize: 16, fontWeight: FontWeight.w700, color: MoolColors.navy))),
              IconButton(
                key: const Key('work-dashboard-settings'),
                tooltip: 'Store status and tools',
                constraints: const BoxConstraints(minWidth: 48, minHeight: 48),
                onPressed: () => _showStoreSignals(context),
                icon: const Icon(Icons.tune_rounded, size: 22),
              ),
              MoolGlobalProfileShortcutV2(keyName: 'work-dashboard-profile',
                freeStanding: true, onPressed: () => _openProfile(context, workspace)),
            ])
          : compactSettings
          ? Row(
              children: [
                if (_view == _WorkspaceControlView.operation)
                  IconButton(
                    key: const Key('work-operation-back'),
                    tooltip: 'Back to Store settings',
                    onPressed: () => unawaited(_leaveOperation()),
                    icon: const Icon(Icons.arrow_back_rounded),
                  ),
                Expanded(
                  child: Text(
                    'Store settings',
                    style: const TextStyle(
                      fontSize: 18,
                      fontWeight: FontWeight.w700,
                      color: MoolColors.navy,
                    ),
                  ),
                ),
              ],
            )
          : storeRootSurface
          ? _WorkspaceDashboardHeader(
              showStatusLabel:
                  _view == _WorkspaceControlView.dashboard || ordersContext ||
                  _view == _WorkspaceControlView.alerts,
              compact: compactOperation || ordersOperation || sharedRestock ||
                  _view == _WorkspaceControlView.alerts,
              singleLine: shortHomeHeader,
              session: session,
              workspace: workspace,
              profile: profile,
              searchOpen:
                  _view == _WorkspaceControlView.search ||
                  (procurementOpen && _procurementSearchOpen),
              keepSearchUtilities: procurementOpen,
              nameLabel: procurementOpen ? workspace.name : null,
              buyingForStore: procurementOpen,
              buyingInformation: sharedRestock && _storeProcurement != null
                  ? _StoreRestockSupplierFilter(controller: _storeProcurement!)
                  : null,
              showProductScanner: !ordersContext,
              nameTextStyle: procurementOpen
                  ? Theme.of(context).textTheme.titleLarge!.copyWith(
                      fontSize: 13,
                      fontWeight: FontWeight.w800,
                    )
                  : null,
              nameTextScaler: procurementOpen
                  ? MediaQuery.textScalerOf(context)
                  : null,
              backKey: Key(
                procurementOpen ? 'work-back' : 'work-operation-back',
              ),
              backSize: procurementOpen ? 48 : 44,
              searchHint: procurementOpen
                  ? (_activeProcurement.query.isEmpty
                        ? 'Search wholesale or bulk'
                        : _activeProcurement.query)
                  : ordersContext
                  ? 'Search order or customer'
                  : 'Search your store',
              searchSemanticsLabel: ordersContext
                  ? 'Search saved orders by order number or customer details'
                  : null,
              searchController: _searchController,
              searchFocusNode: _searchFocus,
              onSwitchWorkspace: () => _showWorkspaceSwitcher(context),
              onBack: procurementOpen
                  ? () => unawaited(_leaveProcurement())
                  : _view == _WorkspaceControlView.operation
                  ? stockSectionRoot
                        ? null
                        : () => unawaited(_leaveOperation())
                  : _view == _WorkspaceControlView.alerts
                  ? _showDashboard
                  : _reviewedOrder != null
                  ? _closeOrderDetails
                  : null,
              onSearch: procurementOpen
                  ? () {
                      if (_activeProcurement.view != BuyV2View.catalogue ||
                          _activeProcurement.destination !=
                              BuyV2Destination.wholesale) {
                        _activeProcurement.openDestination(
                          BuyV2Destination.wholesale,
                        );
                      }
                      _searchController.text = _activeProcurement.query;
                      setState(() => _procurementSearchOpen = true);
                      _searchFocus.requestFocus();
                    }
                  : saleOpen
                  ? () => unawaited(_navigateFromCounterDraft(_showSearch))
                  : _showSearch,
              onSearchChanged: procurementOpen
                  ? (query) {
                      _activeProcurement.updateQuery(query);
                      setState(() {});
                    }
                  : (query) {
                      if (_view != _WorkspaceControlView.search ||
                          savedSearchVisit == null || _savedSearchVisit != savedSearchVisit ||
                          !_searchScopeCurrent(savedSearchVisit)) return;
                      _retainedSavedSearch = (visit: savedSearchVisit, query: query);
                      if (_searchScroll.hasClients) _searchScroll.jumpTo(0);
                      session.updateWorkspaceSearch(query);
                    },
              onCloseSearch: _view == _WorkspaceControlView.search
                  ? () => _exitSavedSearch(savedSearchVisit)
                  : _finishSearch,
              onScan: () {
                if (procurementOpen) {
                  final purchase = _activeProcurement;
                  unawaited(
                    showStoreProductScanner(context).then((code) {
                      if (!mounted ||
                          code == null ||
                          _activeProcurement != purchase ||
                          _view != _WorkspaceControlView.procurement) {
                        return;
                      }
                      if (purchase.view != BuyV2View.catalogue ||
                          purchase.destination != BuyV2Destination.wholesale) {
                        purchase.openDestination(BuyV2Destination.wholesale);
                      }
                      _searchController.text = code;
                      purchase.updateQuery(code);
                      setState(() => _procurementSearchOpen = true);
                    }),
                  );
                  return;
                }
                if (saleOpen) {
                  unawaited(_counterKey.currentState?._scanProduct());
                  return;
                }
                final origin = (
                  view: _view,
                  operation: _operation,
                  returnView: _operationReturnView,
                  returnOperation: _operationReturnOperation,
                  workspaceId: session.activeWorkspace?.id,
                );
                _showOperation(
                  _WorkspaceOperation.catalogue,
                  retainDirectFilter: true,
                );
                WidgetsBinding.instance.addPostFrameCallback((_) async {
                  if (!mounted) return;
                  final scanned = await _catalogueKey.currentState?._scan();
                  if (mounted && scanned == true) _releaseDirectFilter();
                  if (!mounted ||
                      scanned != false ||
                      session.activeWorkspace?.id != origin.workspaceId ||
                      _view != _WorkspaceControlView.operation ||
                      _operation != _WorkspaceOperation.catalogue) {
                    return;
                  }
                  setState(() {
                    _view = origin.view;
                    _operation = origin.operation;
                    _operationReturnView = origin.returnView;
                    _operationReturnOperation = origin.returnOperation;
                  });
                });
              },
              onSettings: () => _showStoreSignals(context),
              onAlerts: _showAlerts,
              onProfile: showStoreProfile
                  ? () => _openProfile(context, workspace)
                  : null,
            )
          : null,
      fallbackBackRoute: '/app/work/earn',
      activeLocalAction: 'workspace',
      showBack: salesTaskOpen || !storeRootSurface,
      showHeaderChat: false,
      showTrailingAction: false,
      contextualDestinationLabel: 'Store',
      contextualActiveId: storeActiveId,
      contextualLocalActions: storeActions,
      onBack: switch (_view) {
        _WorkspaceControlView.dashboard =>
          _reviewedOrder == null ? null : _closeOrderDetails,
        _WorkspaceControlView.procurement => _leaveProcurement,
        _WorkspaceControlView.status => () => unawaited(_leaveSettings()),
        _WorkspaceControlView.operation => () => unawaited(_leaveOperation()),
        _WorkspaceControlView.search =>
          () => _exitSavedSearch(savedSearchVisit, preserveGlobalQuery: true),
        _ => _showDashboard,
      },
      manageSystemBack: _view != _WorkspaceControlView.procurement,
      hideNavigationWhenKeyboardVisible: !saleOpen,
      navigationOverBody: false,
      resizeToAvoidBottomInset: _view != _WorkspaceControlView.procurement,
      bottomAction: bottomAction,
      body: _StoreWorkingSurface(
        child: switch (saleOpen || salesOpen
            ? _WorkspaceControlView.dashboard
            : _view) {
          _WorkspaceControlView.dashboard => _StoreControlDashboard(
            session: session,
            workspace: workspace,
            homeContentScroll: _homeContentScroll,
            showWorkingFinance: !salesOpen,
            onNavigate: (action) =>
                unawaited(_navigateFromCounterDraft(action)),
            workingCentre: saleOpen
                ? counterSurface(false)
                : salesOpen
                ? _StoreStatementSurface(
                    key: _salesKey,
                    session: session,
                    onSalesTaskChanged: (task) => setState(() {
                      _salesTask = task;
                      _salesVisitEpoch++;
                    }),
                    initialSalesTask: _salesTask ?? 'home',
                    salesOnly: true,
                    showNewSaleAction: true,
                    counterContent: _salesTask == 'counter' || (_counterKey.currentState != null && !_counterKey.currentState!._assistantClosed)
                        ? counterSurface(true)
