      product.wholesaleOffer?.enabled != true || product.wholesaleOffer?.valid != true ||
      product.wholesaleOffer?.saleType != (channel == BuyV2OfferClass.bulk ? BuyV2WholesaleSaleType.bulk : BuyV2WholesaleSaleType.wholesale))) {
