      _productAssistantNativeIdentity(hostContext, source, proposal, current);
    Future<MoolAssistantReviewResult> open(StoreProductInitialData initial, MoolAssistantProposal proposal, bool Function() current) =>
      _showProductAssistantInitial(hostContext, source, initial, proposal, current);
    return _StoreBatchedProductInitialAdapter(actionId: action, readContext: readContext,
      readSnapshot: read, readNativeIdentity: identity, open: open,
      readSnapshots: (ctx, entities) => _productAssistantNativeBatch(hostContext, source, action, ctx, entities));
  }

  bool _manualProductAssistantReady(BuildContext host,WorkSession source,MoolAssistantContext ctx) =>
    mounted&&host.mounted&&identical(source,session)&&ctx.inWorkspace&&_financePermitted(ctx)&&
    _financeAssistantContext(host)?.binding==ctx.binding&&!_financeSheetOpen&&!_couponsSheetOpen&&!_productEditorOpen(source)&&
    source.workspaceInventoryLoaded&&source.workspaceInventoryError==null&&!source.workspaceGoodsReceiptBusy&&
    !source.workspaceGoodsReceiptRecoveryPending&&!source.workspaceAccountRecoveryPending&&!source.workspaceAccountRecoveryFailed;
  String _manualProductAssistantRevision(WorkSession source,MoolAssistantContext ctx)=>'native-product-authoring:v1:${assistant_hash.sha256.convert(
    utf8.encode(jsonEncode([ctx.binding.toString(),source.publicationPreferencesContext.toString(),
      source.workspaceProductDefaults.toJson(),for(final item in source.workspaceCatalogueItems)item.toInventoryJson()]))) }';
  Future<MoolAssistantNativeSnapshot?> _manualProductAssistantSnapshot(BuildContext host,WorkSession source,
      MoolAssistantContext ctx,String? entity)async{
    if(entity!=null||!_manualProductAssistantReady(host,source,ctx))return null;
    final store=source.activeWorkspace!.id;
    if(!await source.loadWorkspaceProductDefaults(expectedStoreId:store)||!_manualProductAssistantReady(host,source,ctx))return null;
    return MoolAssistantNativeSnapshot(binding:ctx.binding,entityId:null,permitted:true,
      sourceRevision:_manualProductAssistantRevision(source,ctx));
  }
  Future<MoolAssistantReviewResult> _openManualProductAssistant(BuildContext host,WorkSession source,
      MoolAssistantProposal proposal,bool Function() requestCurrent)async{
    final ctx=_financeAssistantContext(host),request=proposal.preparationRequestId;
    if(ctx==null||request==null||request.isEmpty||proposal.entityId!=null||_manualProductInputError(proposal.fields)!=null||
        proposal.binding!=ctx.binding||!requestCurrent()||!_manualProductAssistantReady(host,source,ctx))return MoolAssistantReviewResult.stale;
    if(ctx.accountScope case (environment:final String environment,projectId:final String projectId,
        tenantId:final String? tenantId,userId:final String userId)) {
      final gateway=source.catalogueGateway;
      if(gateway is! WorkspaceCatalogueOwnerGateway)return MoolAssistantReviewResult.unavailable;
      final digest=assistant_hash.sha256.convert(utf8.encode(jsonEncode(['manual-product-preparation:v1',
        environment,projectId,tenantId,userId,(gateway as WorkspaceCatalogueOwnerGateway).realm,ctx.workspaceId,request]))).toString();
      final product=_newManualWorkspaceProduct(id:'custom-ai-$digest',sku:'SKU-${digest.substring(0,24).toUpperCase()}',
        defaults:source.workspaceProductDefaults);
      bool absent()=>!source.workspaceCatalogueItems.any((p)=>p.id==product.id||p.sku.toLowerCase()==product.sku.toLowerCase());
      if(!absent())return MoolAssistantReviewResult.stale;
      // This is the real blank manual draft, not a catalogue reference. Keep
      // the existing strict referenced-product decoder unchanged for edits.
      final initial=StoreProductInitialData._(product.canonicalId,product.sku,product.pack,
        product.retailEnabled,product.wholesaleOffer?.enabled==true,Map<String,String>.from(proposal.fields));
      final signature=_manualProductAssistantRevision(source,ctx),publication=source.publicationPreferencesContext;
      bool owner()=>mounted&&host.mounted&&identical(source,session)&&_financePermitted(ctx)&&
        _financeAssistantContext(host)?.binding==ctx.binding&&source.publicationPreferencesContext==publication;
      bool unchanged()=>owner()&&absent()&&_manualProductAssistantRevision(source,ctx)==signature;
      final changes=Listenable.merge([source,?host.getInheritedWidgetOfExactType<MoolAssistantHost>()?.contextChanges]);
      await Navigator.of(host,rootNavigator:true).push<void>(MaterialPageRoute(builder:(page)=>_StoreProductOwnerSurface(
        current:owner,changes:changes,child:Scaffold(
        appBar:AppBar(title:const Text('Review product')),
        body:SafeArea(child:_CatalogueProductEditor(session:source,product:product,embeddedPage:true,
          initialData:initial,initialField:initial.inputs.keys.first,ownerCurrent:owner,sourceCurrent:unchanged,
          prefillCurrent:()=>owner()&&requestCurrent(),stockEntryMethod:WorkspaceStockEntryMethod.manual,
          onDone:()=>Navigator.of(page).pop(),onSaved:()=>Navigator.of(page).pop(),
          reviewChanges:changes),
        ),
      ),
    )));
      return owner()?MoolAssistantReviewResult.opened:MoolAssistantReviewResult.stale;
    }
    return MoolAssistantReviewResult.unavailable;
  }

  Future<MoolAssistantNativeBatchSnapshot> _productAssistantNativeBatch(BuildContext hostContext, WorkSession source,
      String action, MoolAssistantContext ctx, List<String?> entities, {bool Function()? routeCurrent}) async {
    bool actor() => mounted && hostContext.mounted && identical(source, session) &&
      _financeAssistantContext(hostContext)?.binding == ctx.binding && _financePermitted(ctx) &&
      routeCurrent?.call() != false && !_financeSheetOpen && !_couponsSheetOpen && !_productEditorOpen(source) &&
      source.workspaceInventoryLoaded && source.workspaceInventoryError == null && !source.workspaceGoodsReceiptBusy &&
      !source.workspaceGoodsReceiptRecoveryPending && !source.workspaceAccountRecoveryPending && !source.workspaceAccountRecoveryFailed;
    if (!actor() || !const {'AI-ACT-214', 'AI-ACT-221', 'AI-ACT-220', 'AI-ACT-370', 'AI-ACT-230', 'AI-ACT-222', 'AI-ACT-223', 'AI-ACT-226', 'AI-ACT-227', 'AI-ACT-371'}.contains(action)) {
      return MoolAssistantNativeBatchSnapshot(owner: source, sourceRevision: 'unavailable:v2', entries: const {}, current: () => false);
    }
    if (action == 'AI-ACT-222' && (!await source.restoreWorkspaceCatalogueListing() || !actor())) {
      return MoolAssistantNativeBatchSnapshot(owner: source, sourceRevision: 'unavailable:v3', entries: const {}, current: () => false);
    }
    final shared = _assistantProductSharedSignature(source);
    final products = {for (final product in source.workspaceCatalogueItems) product.id: product};
    final result = <String?, MoolAssistantNativeSnapshot?>{};
    var retired = false;
    bool current() {
      if (retired) return false;
      try {
        if (!actor() || products.length != source.workspaceCatalogueItems.length || _assistantProductSharedSignature(source) != shared) {
          retired = true; return false;
        }
        // Recheck per-target native pending/readiness state against this same
        // shared inventory hash; never rehash the full inventory for each SKU.
        for (final entry in result.entries) {
          final product = products[entry.key];
          final ready = product != null && (const {'AI-ACT-214', 'AI-ACT-221'}.contains(action) ||
            (action == 'AI-ACT-230' ? source.catalogueGateway is AuthenticatedWorkspaceCatalogueGateway && source.gateway is! ReviewWorkGateway
              : action == 'AI-ACT-223' ? _productSubmissionCaptureReady(source, product)
              : _nativeProductReady(source, action, entry.key, capturedProduct: product)));
          if ((entry.value?.permitted == true) != ready) {retired = true; return false;}
          if (!ready) continue;
          final revision = const {'AI-ACT-214', 'AI-ACT-221'}.contains(action)
            ? _productAssistantSourceRevision(source, action, ctx, entry.key, capturedProduct: product, sharedSignature: shared)
            : _nativeProductRevision(source, action, ctx, entry.key, capturedProduct: product, sharedSignature: shared);
          if (revision != entry.value!.sourceRevision) {retired = true; return false;}
        }
        return true;
      } on Object {retired = true; return false;}
    }
    for (final entity in entities) {
      final product = products[entity];
      if (entity == null || product == null || !actor()) {result[entity] = null; continue;}
      final snapshot = action == 'AI-ACT-230'
        ? await _publishedProductSnapshot(hostContext, source, ctx, entity, routeCurrent ?? () => true,
            capturedProduct: product, sharedSignature: shared)
        : const {'AI-ACT-214', 'AI-ACT-221'}.contains(action)
        ? await _productAssistantSnapshot(hostContext, source, action, ctx, entity, capturedProduct: product, sharedSignature: shared)
        : await _productNativeSnapshot(hostContext, source, action, ctx, entity, routeCurrent ?? () => true,
            capturedProduct: product, sharedSignature: shared, captureOnly: true);
      result[entity] = snapshot;
    }
    return MoolAssistantNativeBatchSnapshot(owner: source, sourceRevision: 'store-native-batch:v4:$shared', entries: result, current: current);
  }

  void _refreshProductAssistantVersionOwner() {
    final owner = (session, widget.accountIdentity, widget.accountAuthenticated,
      _financeAssistantContext(context)?.binding,
      session.activeWorkspace?.id, session.navigationScopeRevision,
      session.publicationPreferencesContext, session.tradingPreferencesContext);
    if (_productAssistantVersionOwner != owner) {
      _productAssistantVersions.clear();
      _productAssistantVersionOwner = owner;
    }
  }

  String? _productAssistantSourceRevision(WorkSession source, String actionId,
    MoolAssistantContext ctx, String? entityId, {WorkspaceCatalogueItem? capturedProduct, String? sharedSignature}) {
    _refreshProductAssistantVersionOwner();
    final product = capturedProduct ?? _assistantProductTarget(source, actionId == 'AI-ACT-213', entityId);
    if (product == null || product.id != entityId) return null;
    final key = (source, actionId, entityId, ctx.binding,
      source.publicationPreferencesContext, source.tradingPreferencesContext);
    final signature = _assistantProductSignature(source, product, sharedSignature: sharedSignature);
    if (_productAssistantVersions[key]?.$1 != signature) {
      _productAssistantVersions[key] = (signature, ++_productAssistantVersion);
    }
    return 'store-product:v2:${_productAssistantVersions[key]!.$2}';
  }

  Future<String?> _productAssistantNativeIdentity(BuildContext hostContext, WorkSession source,
      MoolAssistantProposal proposal, bool Function() current) async {
    final ctx = _financeAssistantContext(hostContext), entity = proposal.entityId;
    if (ctx == null || entity == null || !const {'AI-ACT-214', 'AI-ACT-221', 'AI-ACT-370', 'AI-ACT-220', 'AI-ACT-230', 'AI-ACT-222', 'AI-ACT-223', 'AI-ACT-226', 'AI-ACT-227', 'AI-ACT-371'}.contains(proposal.actionId)) return null;
    bool owner() => current() && mounted && hostContext.mounted && identical(source, session) &&
      _financeAssistantContext(hostContext)?.binding == ctx.binding && ctx.binding == proposal.binding && _financePermitted(ctx) &&
      !_productEditorOpen(source) && !_financeSheetOpen && !_couponsSheetOpen;
    if (!owner()) return null;
    final product = _assistantProductTarget(source, false, entity);
    if (product == null) return null;
    final acknowledgement = source.workspaceAssistantProductAcknowledgement(entity, proposal.sourceRevision, current: owner);
    if (acknowledgement == null || !acknowledgement.current()) return null;
    final expected = {...StoreProductInitialData.referenceFields(product),
      'sourceCanonicalId': acknowledgement.canonicalProductId};
    final proposed = {for (final key in StoreProductInitialData.referenceKeys) key: proposal.fields[key]};
    if (!mapEquals(expected, proposed) || !owner() || !acknowledgement.current()) return null;
    return product.canonicalId;
  }

  Future<MoolAssistantNativeSnapshot?> _productAssistantSnapshot(
    BuildContext hostContext, WorkSession source, String actionId,
    MoolAssistantContext ctx, String? entityId, {WorkspaceCatalogueItem? capturedProduct, String? sharedSignature}
  ) async {
    bool current() => mounted && hostContext.mounted && identical(widget.session, source) &&
        _financeAssistantContext(hostContext)?.binding == ctx.binding && _financePermitted(ctx) &&
        !_financeSheetOpen && !_couponsSheetOpen && !_productEditorOpen(source);
    if (entityId == null || !current()) return null;
    // Native Load/Recover may queue a durable Stock report. AI snapshots use
    // only a checkpoint already admitted by the original native owner.
    if (source.localInventoryEnabled && (!source.workspaceInventoryLoaded ||
        source.workspaceInventoryError != null || source.workspaceGoodsReceiptBusy ||
        source.workspaceGoodsReceiptRecoveryPending)) return null;
    if (actionId == 'AI-ACT-213') {
      final storeId = source.activeWorkspace?.id;
      final ready = storeId != null && await source.loadWorkspaceProductDefaults(expectedStoreId: storeId);
      if (!ready || !current()) return null;
    }
    final adding = actionId == 'AI-ACT-213';
    final product = capturedProduct ?? _assistantProductTarget(source, adding, entityId);
    if (product == null || adding && source.workspaceCatalogueItems.any((item) =>
        item.id == product.id || item.sku.trim().toLowerCase() == product.sku.trim().toLowerCase())) return null;
    final revision = _productAssistantSourceRevision(source, actionId, ctx, entityId,
      capturedProduct: product, sharedSignature: sharedSignature);
    return revision == null ? null : MoolAssistantNativeSnapshot(binding: ctx.binding,
      sourceRevision: revision, entityId: entityId, permitted: true);
  }

  Future<MoolAssistantReviewResult> _showProductAssistantInitial(
    BuildContext hostContext, WorkSession source, StoreProductInitialData initial,
    MoolAssistantProposal proposal, bool Function() reviewCurrent,
  ) async {
    final trusted = _financeAssistantContext(hostContext);
    if (trusted == null || proposal.entityId == null || !reviewCurrent() ||
        !identical(widget.session, source) || !_financePermitted(trusted) ||
        trusted.binding != proposal.binding || _financeSheetOpen || _couponsSheetOpen ||
        proposal.sourceRevision != _productAssistantSourceRevision(
          source, proposal.actionId, trusted, proposal.entityId)) {
      return MoolAssistantReviewResult.stale;
    }
    bool ownerCurrent() => mounted && hostContext.mounted && identical(widget.session, source) &&
        _financeAssistantContext(hostContext)?.binding == trusted.binding && _financePermitted(trusted);
    return showStoreProductInitialReview(context, source,
      adding: proposal.actionId == 'AI-ACT-213', entityId: proposal.entityId!, initialData: initial,
      isCurrent: () => reviewCurrent() && ownerCurrent(), ownerCurrent: ownerCurrent);
  }


  String? _supplierMoneyAssistantRevision(WorkSession source, String actionId,
    MoolAssistantContext ctx, String? entityId) {
    final target = _assistantSupplierMoneyTarget(source, actionId, entityId);
    if (target == null) return null;
    final signature = _assistantSupplierMoneySignature(source, target);
    if (signature == null) return null;
    if (source.workspaceOriginalSupplierMoneyConfigured) return signature;
    final owner = (source, actionId, entityId, ctx.binding, source.workspaceSupplierScope,
      source.publicationPreferencesContext);
    if (_supplierMoneyAssistantOwner != owner || _supplierMoneyAssistantDigest != signature) {
      _supplierMoneyAssistantOwner = owner;
      _supplierMoneyAssistantDigest = signature;
      _supplierMoneyAssistantVersion++;
    }
    return 'supplier-money:$_supplierMoneyAssistantVersion';
  }

  Future<MoolAssistantNativeSnapshot?> _supplierMoneyAssistantSnapshot(
    BuildContext hostContext, WorkSession source, String actionId,
    MoolAssistantContext ctx, String? entityId,
  ) async {
    bool current() => mounted && hostContext.mounted && identical(widget.session, source) &&
        _financeAssistantContext(hostContext)?.binding == ctx.binding && _financePermitted(ctx) &&
        !_supplierMoneyFormOpen(source) && !_financeSheetOpen && !_couponsSheetOpen;
    if (entityId == null || !current()) return null;
    if (source.workspaceOriginalSupplierMoneyConfigured && source.workspaceOriginalLedgerSections == null) {
      if (!_assistantFinancialBookAdmitted(source) || !await source.loadWorkspaceOriginalLedger() || !current()) return null;
    }
    if (!_assistantSupplierMoneyAdmitted(source) || !current()) return null;
    final target = _assistantSupplierMoneyTarget(source, actionId, entityId);
    if (target == null) return null;
    final key = _assistantSupplierMoneyKey(source, target);
    final signature = _assistantSupplierMoneySignature(source, target);
    if (key == null || signature == null) return null;
    try {
      final saved = await source.readLedgerForm(key);
      if (!current() || saved != null || _assistantSupplierMoneySignature(source, target) != signature) return null;
    } on Object { return null; }
    final revision = _supplierMoneyAssistantRevision(source, actionId, ctx, entityId);
    return revision == null ? null : MoolAssistantNativeSnapshot(binding: ctx.binding,
      sourceRevision: revision, entityId: entityId, permitted: true);
  }

  Future<MoolAssistantReviewResult> _showSupplierMoneyAssistantInitial(
    BuildContext hostContext, WorkSession source, StoreSupplierMoneyInitialData initial,
    MoolAssistantProposal proposal, bool Function() reviewCurrent, {StoreSupplierSelectedDocumentInput? selectedDocument}
  ) async {
    final trusted = _financeAssistantContext(hostContext);
    if (trusted == null || !reviewCurrent() || proposal.entityId == null ||
        !identical(widget.session, source) || !_financePermitted(trusted) ||
        proposal.binding != trusted.binding || _financeSheetOpen || _couponsSheetOpen ||
        proposal.sourceRevision != _supplierMoneyAssistantRevision(source,
          proposal.actionId, trusted, proposal.entityId)) return MoolAssistantReviewResult.stale;
    bool ownerCurrent() => mounted && hostContext.mounted && identical(widget.session, source) &&
        _financeAssistantContext(hostContext)?.binding == trusted.binding && _financePermitted(trusted);
    return showStoreSupplierMoneyInitialReview(context, source,
      actionId: proposal.actionId, entityId: proposal.entityId!, initialData: initial,
      isCurrent: () => reviewCurrent() && ownerCurrent(), ownerCurrent: ownerCurrent, selectedDocument: selectedDocument);
  }

  String _supplierAllocationAssistantRevision(WorkSession source, String actionId,
    MoolAssistantContext ctx, String entityId, String signature) {
    // The existing canonical context guard pins this local draft digest
    // independently from the server's original-ledger revision. A stable
    // value also prevents other bill snapshots from retiring this bill.
    if (source.workspaceOriginalSupplierAllocationConfigured) return 'store-allocation-native-v1:$signature';
    final owner = (source, actionId, entityId, ctx.binding, source.workspaceSupplierScope,
      source.publicationPreferencesContext);
    if (_supplierAllocationAssistantOwner != owner || _supplierAllocationAssistantDigest != signature) {
      _supplierAllocationAssistantOwner = owner;
      _supplierAllocationAssistantDigest = signature;
      _supplierAllocationAssistantVersion++;
    }
    return 'supplier-allocation:$_supplierAllocationAssistantVersion';
  }
  Future<MoolAssistantNativeSnapshot?> _supplierAllocationAssistantSnapshot(BuildContext hostContext,
    WorkSession source, String actionId, MoolAssistantContext ctx, String? entityId) async {
    bool current() => mounted && hostContext.mounted && identical(widget.session, source) &&
      _financeAssistantContext(hostContext)?.binding == ctx.binding && _financePermitted(ctx) &&
      !_financeSheetOpen && !_couponsSheetOpen && !_supplierMoneyFormOpen(source);
    if (entityId == null || !current()) return null;
    final read = await _readAssistantSupplierAllocation(source, entityId, current);
    if (read == null || !current()) return null;
    if (actionId == 'AI-ACT-262' && source.workspaceOriginalSupplierAllocationConfigured &&
        !source.canRecordWorkspaceOriginalSupplierMoney(read.copy.supplier.id)) return null;
    if (actionId == 'AI-ACT-262' ? read.saved != null :
        read.saved?.valid != true || read.saved?.supplierAllocationIntent == null) return null;
    return MoolAssistantNativeSnapshot(binding: ctx.binding, entityId: entityId, permitted: true,
      sourceRevision: _supplierAllocationAssistantRevision(source, actionId, ctx, entityId, read.signature));
  }
  Future<MoolAssistantReviewResult> _showSupplierAllocationAssistant(BuildContext hostContext,
    WorkSession source, MoolAssistantProposal proposal, bool Function() reviewCurrent, {StoreSupplierSelectedDocumentInput? selectedDocument}) async {
    final trusted = _financeAssistantContext(hostContext);
    if (trusted == null || proposal.entityId == null || trusted.binding != proposal.binding) {
      return MoolAssistantReviewResult.stale;
    }
    bool owner() => mounted && hostContext.mounted && identical(widget.session, source) &&
      _financeAssistantContext(hostContext)?.binding == trusted.binding && _financePermitted(trusted) &&
      !_financeSheetOpen && !_couponsSheetOpen;
    final read = await _readAssistantSupplierAllocation(source, proposal.entityId!, () => owner() && reviewCurrent());
    if (read == null || !owner() || !reviewCurrent() || proposal.sourceRevision !=
        _supplierAllocationAssistantRevision(source, proposal.actionId, trusted, proposal.entityId!, read.signature)) {
      return MoolAssistantReviewResult.stale;
    }
    return showStoreSupplierAllocationReview(hostContext, source,
      actionId: proposal.actionId, entityId: proposal.entityId!,
      initialData: proposal.actionId == 'AI-ACT-262'
        ? StoreSupplierAllocationInitialData.fromFields(proposal.fields) : null,
      operationId: source.workspaceOriginalSupplierAllocationConfigured
        ? read.saved?.supplierAllocationIntent?.operationId : proposal.fields['operationId'] as String?, expectedSignature: read.signature,
      isCurrent: () => owner() && reviewCurrent(), ownerCurrent: owner, selectedDocument: selectedDocument);
  }


  String? _supplierAdjustmentSignature(WorkSession source, String actionId, String entityId) {
    if (actionId == 'AI-ACT-266') {
      final target = _assistantRefundTarget(source, entityId);
      return target == null ? null : _assistantRefundSignature(source, target);
    }
    final copy = source.workspacePurchaseCopies.where((copy) => copy.id == entityId).singleOrNull;
    return copy == null ? null : _assistantCreditSignature(source, copy);
  }
  WorkspaceLedgerFormKey? _supplierAdjustmentKey(WorkSession source, String actionId, String entityId) {
    if (actionId == 'AI-ACT-266') return _assistantRefundTarget(source, entityId)?.key(source);
    final copy = source.workspacePurchaseCopies.where((copy) => copy.id == entityId).singleOrNull;
    return copy == null ? null : source.supplierCreditFormKey(copy);
  }
  String? _supplierAdjustmentRevision(WorkSession source, String actionId,
    MoolAssistantContext ctx, String entityId) {
    final digest = _supplierAdjustmentSignature(source, actionId, entityId);
    if (digest == null) return null;
    if (actionId == 'AI-ACT-266' && source.workspaceOriginalSupplierRefundConfigured) return 'store-refund-native-v1:$digest';
    if (actionId != 'AI-ACT-266' && source.workspaceOriginalSupplierCreditConfigured) return 'store-credit-native-v1:$digest';
    final owner = (source, actionId, entityId, ctx.binding, source.workspaceSupplierScope,
      source.publicationPreferencesContext);
    if (_supplierAdjustmentAssistantOwner != owner || _supplierAdjustmentAssistantDigest != digest) {
      _supplierAdjustmentAssistantOwner = owner;
      _supplierAdjustmentAssistantDigest = digest;
      _supplierAdjustmentAssistantVersion++;
    }
    return 'supplier-credit-refund:$_supplierAdjustmentAssistantVersion';
  }
  Future<MoolAssistantNativeSnapshot?> _supplierAdjustmentAssistantSnapshot(
    BuildContext hostContext, WorkSession source, String actionId,
    MoolAssistantContext ctx, String? entityId) async {
    bool current() => mounted && hostContext.mounted && identical(widget.session, source) &&
      _financeAssistantContext(hostContext)?.binding == ctx.binding && _financePermitted(ctx) &&
      !_supplierAdjustmentOpen(source) && !_financeSheetOpen && !_couponsSheetOpen;
    if (entityId == null || !current()) return null;
    if ((actionId == 'AI-ACT-266' ? source.workspaceOriginalSupplierRefundConfigured : source.workspaceOriginalSupplierCreditConfigured) &&
        source.workspaceOriginalLedgerSections == null) {
      if (!await source.loadWorkspaceOriginalLedger() || !current()) return null;
    }
    if (!(actionId == 'AI-ACT-266' ? _assistantSupplierRefundAdmitted(source) : _assistantSupplierCreditAdmitted(source)) || !current()) return null;
    final key = _supplierAdjustmentKey(source, actionId, entityId);
    final digest = _supplierAdjustmentSignature(source, actionId, entityId);
    if (key == null || digest == null) return null;
    try {
      final saved = await source.readLedgerForm(key);
      if (!current() || saved != null || _supplierAdjustmentSignature(source, actionId, entityId) != digest) return null;
    } on Object { return null; }
    final revision = _supplierAdjustmentRevision(source, actionId, ctx, entityId);
    return revision == null ? null : MoolAssistantNativeSnapshot(binding: ctx.binding,
      entityId: entityId, sourceRevision: revision, permitted: true);
  }
  Future<MoolAssistantReviewResult> _showSupplierAdjustmentAssistantInitial(
    BuildContext hostContext, WorkSession source, MoolAssistantProposal proposal,
    bool Function() reviewCurrent, {StoreSupplierSelectedDocumentInput? selectedDocument}) async {
    final trusted = _financeAssistantContext(hostContext);
    if (trusted == null || !reviewCurrent() || proposal.entityId == null ||
        !identical(widget.session, source) || !_financePermitted(trusted) || proposal.binding != trusted.binding ||
        proposal.sourceRevision != _supplierAdjustmentRevision(source, proposal.actionId, trusted, proposal.entityId!)) {
      return MoolAssistantReviewResult.stale;
    }
    bool ownerCurrent() => mounted && hostContext.mounted && identical(widget.session, source) &&
      _financeAssistantContext(hostContext)?.binding == trusted.binding && _financePermitted(trusted);
    if (proposal.actionId == 'AI-ACT-266') return showStoreSupplierRefundInitialReview(context, source,
      entityId: proposal.entityId!, initialData: StoreSupplierRefundInitialData.fromFields(proposal.fields),
      isCurrent: () => ownerCurrent() && reviewCurrent(), ownerCurrent: ownerCurrent, selectedDocument: selectedDocument);
    return showStoreSupplierCreditInitialReview(context, source,
      actionId: proposal.actionId, entityId: proposal.entityId!,
      initialData: StoreSupplierCreditInitialData.fromFields(proposal.fields),
      isCurrent: () => ownerCurrent() && reviewCurrent(), ownerCurrent: ownerCurrent, selectedDocument: selectedDocument);
  }

  String _supplierAdjustmentRecoveryRevision(WorkSession source, String actionId,
    MoolAssistantContext ctx, String entityId, String signature) {
    final owner = (source, actionId, entityId, ctx.binding, source.workspaceSupplierScope,
      source.publicationPreferencesContext);
    if (const {'AI-ACT-267', 'AI-ACT-378'}.contains(actionId) && source.workspaceOriginalSupplierRefundConfigured) {
      return 'store-refund-recovery-native-v1:$signature';
    }
    if (const {'AI-ACT-265', 'AI-ACT-379'}.contains(actionId) && source.workspaceOriginalSupplierCreditConfigured) {
      return 'store-credit-recovery-native-v1:$signature';
    }
    if (_supplierAdjustmentRecoveryOwner != owner || _supplierAdjustmentRecoveryDigest != signature) {
      _supplierAdjustmentRecoveryOwner = owner;
      _supplierAdjustmentRecoveryDigest = signature;
      _supplierAdjustmentRecoveryVersion++;
    }
