  bool _supplierAssistantPermitted(WorkSession source, MoolAssistantContext ctx) {
    final scope = source.workspaceSupplierScope;
    // The assistant uses the authenticated persistence identity record. The
    // directory uses its private String namespace; they are different types.
    // Trusted approved-Workspace binding and native account recovery bridge
    // those owners; never compare their storage keys as account identifiers.
    return identical(widget.session, source) && _financePermitted(ctx) && !source.workspaceSupplierRecoveryRequired &&
        scope != null && ctx.workspaceId == scope.$2;
  }

  Future<MoolAssistantNativeSnapshot?> _supplierAssistantSnapshot(
    BuildContext hostContext, WorkSession source,
    MoolAssistantContext ctx, String? entityId,
  ) async {
    bool current() => mounted && hostContext.mounted &&
        _financeAssistantContext(hostContext)?.binding == ctx.binding &&
        _supplierAssistantPermitted(source, ctx) && !source.workspaceSupplierSaving &&
        !_financeSheetOpen && !_couponsSheetOpen &&
        _openSupplierSelectors[source] != true;
    if (entityId != null || !current()) return null;
    final scope = source.workspaceSupplierScope;
    final loaded = await source.loadWorkspaceSuppliers(retry: true);
    if (!loaded || !current() || source.workspaceSupplierScope != scope) return null;
    return MoolAssistantNativeSnapshot(binding: ctx.binding, permitted: true,
      sourceRevision: _supplierSourceRevision(source));
  }

  Future<MoolAssistantReviewResult> _showSupplierAssistantAdd(
    BuildContext hostContext, WorkSession source, StoreSupplierInitialData initial,
    MoolAssistantProposal proposal, bool Function() reviewCurrent,
  ) async {
    final trusted = _financeAssistantContext(hostContext);
    final scope = source.workspaceSupplierScope;
    if (!reviewCurrent() || trusted == null || scope == null ||
        trusted.binding != proposal.binding || proposal.entityId != null ||
        !_supplierAssistantPermitted(source, trusted) || source.workspaceSupplierSaving ||
        _financeSheetOpen || _couponsSheetOpen ||
        proposal.sourceRevision != _supplierSourceRevision(source)) {
      return MoolAssistantReviewResult.stale;
    }
    // Native form ownership remains independent of proposal cancellation.
    // This full trusted binding/permission guard also protects the form's Save.
    bool ownerCurrent() => mounted && hostContext.mounted &&
        _financeAssistantContext(hostContext)?.binding == trusted.binding &&
        _supplierAssistantPermitted(source, trusted) &&
        source.workspaceSupplierScope == scope;
    return showStoreSupplierAddReview(context, source,
      initialData: initial, expectedScope: scope,
      expectedRevision: source.workspacePurchaseEntryRevision,
      isCurrent: () => reviewCurrent() && ownerCurrent(), ownerCurrent: ownerCurrent);
  }


  Future<MoolAssistantNativeSnapshot?> _supplierEditAssistantSnapshot(
    BuildContext hostContext, WorkSession source, MoolAssistantContext ctx, String? entityId,
  ) async {
    bool current() => mounted && hostContext.mounted &&
      _financeAssistantContext(hostContext)?.binding == ctx.binding &&
      _supplierAssistantPermitted(source, ctx) && !source.workspaceSupplierSaving &&
      !_financeSheetOpen && !_couponsSheetOpen && _openSupplierSelectors[source] != true;
    if (entityId == null || !current()) return null;
    final scope = source.workspaceSupplierScope;
    if (!await source.loadWorkspaceSuppliers(retry: true) || !current() || source.workspaceSupplierScope != scope) return null;
    final profile = source.workspaceSuppliers.where((p) => p.id == entityId).singleOrNull;
    return profile == null ? null : MoolAssistantNativeSnapshot(binding: ctx.binding,
      sourceRevision: _supplierEditSourceRevision(source, profile), entityId: entityId, permitted: true);
  }

  Future<MoolAssistantReviewResult> _showSupplierExistingAssistant(
    BuildContext hostContext, WorkSession source, MoolAssistantProposal proposal, bool Function() reviewCurrent,
  ) async {
    final trusted = _financeAssistantContext(hostContext), scope = source.workspaceSupplierScope;
    if (trusted == null || scope == null || !reviewCurrent() || proposal.binding != trusted.binding ||
        !_supplierAssistantPermitted(source, trusted) || source.workspaceSupplierSaving ||
        _financeSheetOpen || _couponsSheetOpen) return MoolAssistantReviewResult.stale;
    bool ownerCurrent() => mounted && hostContext.mounted &&
      _financeAssistantContext(hostContext)?.binding == trusted.binding &&
      _supplierAssistantPermitted(source, trusted) && source.workspaceSupplierScope == scope;
    if (proposal.actionId == 'AI-ACT-236') {
      if (proposal.entityId != null || proposal.sourceRevision != _supplierSourceRevision(source)) return MoolAssistantReviewResult.stale;
      return showStoreSupplierLookupReview(context, source, query: proposal.fields['query']! as String,
        expectedScope: scope, expectedRevision: source.workspacePurchaseEntryRevision,
        isCurrent: () => ownerCurrent() && reviewCurrent(), ownerCurrent: ownerCurrent);
    }
    final original = source.workspaceSuppliers.where((p) => p.id == proposal.entityId).singleOrNull;
    if (original == null || proposal.sourceRevision != _supplierEditSourceRevision(source, original)) return MoolAssistantReviewResult.stale;
    return showStoreSupplierEditReview(context, source, originalProfile: original,
      initialData: StoreSupplierEditInitialData.fromFields(proposal.fields), expectedScope: scope,
      expectedRevision: source.workspacePurchaseEntryRevision,
      isCurrent: () => ownerCurrent() && reviewCurrent(), ownerCurrent: ownerCurrent);
  }

  MoolAssistantNativeSnapshot? _financeSnapshot(
    BuildContext hostContext, MoolAssistantContext ctx, String? entityId,
  ) {
    final trusted = _financeAssistantContext(hostContext);
    if (entityId != null || trusted == null || trusted.binding != ctx.binding ||
        !_financePermitted(ctx) || _financeSheetOpen || _couponsSheetOpen) return null;
    // A local form-owner version, never catalogue, loan or funding truth.
    final key = (session, widget.accountIdentity, widget.accountAuthenticated,
      _financeOwner.value, session.activeWorkspace?.id,
      session.publicationPreferencesContext, session.navigationScopeRevision,
      _financeFormRevision);
    if (_financeSnapshotOwner != key) {
      _financeSnapshotOwner = key;
      _financeSnapshotRevision++;
    }
    return MoolAssistantNativeSnapshot(
      binding: ctx.binding, permitted: true,
      sourceRevision: '$moolBusinessFinanceFormRevision:$_financeSnapshotRevision',
    );
  }

  Future<MoolAssistantReviewResult> _showBusinessFinance({
    MoolBusinessFinancePrefill? prefill,
    bool Function()? reviewCurrent,
  }) async {
    if (reviewCurrent?.call() == false) return MoolAssistantReviewResult.stale;
    if (_financeSheetOpen || _couponsSheetOpen) return MoolAssistantReviewResult.unavailable;
    final source = session, epoch = _financeOwner.value;
    final store = source.activeWorkspace;
    if (store == null) return MoolAssistantReviewResult.unavailable;
    final owner = source.publicationPreferencesContext;
    final navigation = source.navigationScopeRevision;
    final identity = widget.accountIdentity;
    final authenticated = widget.accountAuthenticated;
    final ownContact = authenticated && identity?.firebasePrincipal != null ? identity : null;
    bool current() => mounted && identical(widget.session, source) &&
        _financeOwner.value == epoch && identical(widget.accountIdentity, identity) &&
        widget.accountAuthenticated == authenticated && source.activeWorkspace?.id == store.id &&
        source.publicationPreferencesContext == owner && source.navigationScopeRevision == navigation &&
        (reviewCurrent?.call() ?? true);
    if (!current()) return MoolAssistantReviewResult.stale;
    _financeSheetOpen = true;
    try {
      await showMoolBusinessFinanceSheet(context,
        scopeOwner: Listenable.merge([source, _financeOwner]),
        isCurrent: current,
        storeName: store.name,
        contactName: ownContact?.displayName,
        callbackNumber: ownContact?.phoneNumber,
        prefill: prefill,
        origin: 'store', buyingStoreId: store.id,
      );
      return current() ? MoolAssistantReviewResult.opened : MoolAssistantReviewResult.stale;
    } finally {
      _financeSheetOpen = false;
      _financeFormRevision++;
    }
  }

  String _couponNativeReferences(WorkSession source) => assistant_hash.sha256.convert(utf8.encode(jsonEncode([
    source.workspaceInventoryRevision,
    [for (final item in source.workspaceCatalogueItems) item.toInventoryJson()],
    [for (final buyer in source.workspaceCustomerBook) [buyer.id, buyer.name, buyer.mobile]],
  ]))).toString();
  String _couponNativeSource(WorkSession source, String action, String? entity, {Map<String,String>? draft}) {
    final values=draft??source.workspaceAssistantCouponDraft;
    final campaign = entity==null?null:decodeStoreCouponCampaigns(values['storeCouponCampaignsV1'],source.activeWorkspace?.id??'')
      .where((value) => source.workspaceAssistantCouponEntityMatches(value,entity)).singleOrNull;
    final publisher = action == 'AI-ACT-310' ? source.workspaceAssistantLoadedCouponController : null;
    return assistant_hash.sha256.convert(utf8.encode(jsonEncode([
      action, entity, source.navigationScopeRevision, values,
      if (campaign != null) campaign.toJson(),
      if (action == 'AI-ACT-309') _couponNativeReferences(source),
      if (publisher != null) [publisher.active, publisher.pending?.fingerprint,
        publisher.currentRecord?.revision, publisher.currentRecord?.input.fingerprint, publisher.loadedCouponId],
    ]))).toString();
  }
  Future<MoolAssistantNativeSnapshot?> _couponNativeSnapshot(BuildContext hostContext,
    MoolAssistantContext ctx, String action, String? entity) async {
    final source = session, identity = widget.accountIdentity, publication = source.publicationPreferencesContext;
    bool current() => mounted && hostContext.mounted && identical(widget.session, source) &&
      identical(widget.accountIdentity, identity) && source.publicationPreferencesContext == publication &&
      _financePermitted(ctx) && _financeAssistantContext(hostContext)?.binding == ctx.binding &&
      !_couponsSheetOpen && !_financeSheetOpen && !storeCouponNativeEditorOpen(source);
    if (!current() || action == 'AI-ACT-308' && entity != null) return null;
    final store = source.activeWorkspace?.id;
    if (store == null) return null;
    final draft=action=='AI-ACT-308'?source.workspaceAssistantCouponDraft:
      await source.readWorkspaceAssistantCouponDraft(expectedStoreId:store,inputCurrent:current);
    if (!current() || draft==null) return null;
    final campaigns=decodeStoreCouponCampaigns(draft['storeCouponCampaignsV1'],store);
    if (entity != null && campaigns.where((value) => source.workspaceAssistantCouponEntityMatches(value,entity)).length != 1 ||
        action == 'AI-ACT-310' && entity == null) return null;
    if (action == 'AI-ACT-310') {
      final publisher = source.workspaceAssistantLoadedCouponController;
      if (publisher != null && (publisher.busy ||
          publisher.pending != null && publisher.pending!.couponId != campaigns
            .where((value)=>source.workspaceAssistantCouponEntityMatches(value,entity)).singleOrNull?.id)) return null;
      // Peek only. Explicit native Review retains the original guarded reads
      // and exact pending recovery; capture never adopts another coupon head.
    }
    if (!current()) return null;
    return MoolAssistantNativeSnapshot(binding: ctx.binding, sourceRevision: _couponNativeSource(source, action, entity,draft:draft),
      permitted: true, entityId: entity);
  }
  Future<MoolAssistantReviewResult> _openCouponNative(BuildContext hostContext, MoolAssistantProposal proposal,
    bool Function() reviewCurrent, Listenable authorityChanges) async {
    final source = session, ctx = _financeAssistantContext(hostContext), epoch = _financeOwner.value;
    final router = GoRouter.of(hostContext), navigation = source.navigationScopeRevision;
    final uri = router.state.uri, page = router.state.pageKey;
    final publication = source.publicationPreferencesContext, identity = widget.accountIdentity;
    bool owner() => mounted && hostContext.mounted && identical(widget.session, source) && ctx != null &&
      identical(widget.accountIdentity, identity) && _financeOwner.value == epoch &&
      source.navigationScopeRevision == navigation && source.publicationPreferencesContext == publication &&
      router.state.uri == uri && router.state.pageKey == page &&
      _financePermitted(ctx) && _financeAssistantContext(hostContext)?.binding == ctx.binding && reviewCurrent();
    if (!owner() || ctx!.binding != proposal.binding || _couponsSheetOpen || _financeSheetOpen ||
        storeCouponNativeEditorOpen(source)) return MoolAssistantReviewResult.stale;
    final store=source.activeWorkspace?.id;
    if(store==null)return MoolAssistantReviewResult.stale;
    final draft=proposal.actionId=='AI-ACT-308'?source.workspaceAssistantCouponDraft:
      await source.readWorkspaceAssistantCouponDraft(expectedStoreId:store,inputCurrent:owner);
    if(!owner()||draft==null||proposal.sourceRevision!=_couponNativeSource(source,proposal.actionId,proposal.entityId,draft:draft))return MoolAssistantReviewResult.stale;
    if(proposal.actionId!='AI-ACT-308'){
      // Hydration belongs to the explicit native Review, never preparation.
      if(!await source.loadWorkspaceOfferDraft(expectedStoreId:store)||!owner()||
        proposal.sourceRevision!=_couponNativeSource(source,proposal.actionId,proposal.entityId))return MoolAssistantReviewResult.stale;
    }
    final campaign = source.workspaceStoreCouponCampaigns
      .where((value) => source.workspaceAssistantCouponEntityMatches(value,proposal.entityId)).singleOrNull;
    if (proposal.entityId != null && campaign == null || proposal.actionId == 'AI-ACT-310' && campaign == null) return MoolAssistantReviewResult.unavailable;
    final initial = proposal.actionId == 'AI-ACT-309' ? StoreCouponReviewInitial.fromFields(proposal.fields) : null;
    if (initial != null && !initial.referencesCurrent(source)) {
      source.showError('A selected Store product or buyer is unavailable. Review the original selection.');
      return MoolAssistantReviewResult.unavailable;
    }
    final problem = initial?.problemFor(campaign);
    if (problem != null) { source.showError(problem); return MoolAssistantReviewResult.unavailable; }
    final references = initial == null ? null : _couponNativeReferences(source);
    final original = campaign == null ? null : encodeStoreCouponCampaigns([campaign]);
    bool campaignCurrent() => owner() && (campaign == null || source.workspaceStoreCouponCampaigns.any((saved) =>
      saved.id == campaign.id && encodeStoreCouponCampaigns([saved]) == original));
    final changes = Listenable.merge([source, _financeOwner, routerDelegateOf(hostContext), authorityChanges,
      hostContext.getInheritedWidgetOfExactType<MoolAssistantHost>()?.contextChanges]);
    _couponsSheetOpen = true;
    try {
      if (proposal.actionId == 'AI-ACT-308') {
        await showStoreCouponsManager(hostContext, session: source, scopeOwner: changes, isCurrent: owner,
          initialQuery: proposal.fields['query'] as String?);
      } else if (initial != null) {
        final applied = await showStoreCouponEditorReview(hostContext, session: source, initial: initial, campaign: campaign,
          owner: changes, current: owner, sourceCurrent: () => campaignCurrent() &&
            references == _couponNativeReferences(source) && initial.referencesCurrent(source));
        if (!applied) return MoolAssistantReviewResult.stale;
      } else {
        await showStoreCouponPublicationReview(hostContext, session: source, campaign: campaign!,
          operation: proposal.fields['operation'] as String, owner: changes, current: campaignCurrent);
      }
      return owner() && (proposal.actionId != 'AI-ACT-310' || campaignCurrent())
        ? MoolAssistantReviewResult.opened : MoolAssistantReviewResult.stale;
    } finally { _couponsSheetOpen = false; }
  }


  Future<void> _showCoupons() async {
    if (_couponsSheetOpen || _financeSheetOpen) return;
    final source = session, epoch = _financeOwner.value, store = session.activeWorkspace;
    if (store == null) return;
    final owner = source.publicationPreferencesContext, navigation = source.navigationScopeRevision;
    final identity = widget.accountIdentity, authenticated = widget.accountAuthenticated;
    bool current() => mounted && identical(widget.session, source) && _financeOwner.value == epoch &&
      identical(widget.accountIdentity, identity) && widget.accountAuthenticated == authenticated &&
      source.activeWorkspace?.id == store.id && source.publicationPreferencesContext == owner &&
      source.navigationScopeRevision == navigation;
    _couponsSheetOpen = true;
    try {
      await showStoreCouponsManager(context, session: source,
        scopeOwner: Listenable.merge([source, _financeOwner]), isCurrent: current);
    } finally { _couponsSheetOpen = false; }
  }

  Future<void> _restoreProcurement() async {
    // An explicit dashboard return wins over an older purchase bookmark.
    // Leave the bookmark intact so Restock can still reopen that purchase.
    if (widget.initialSection == 'dashboard') return;
    final controller = _storeProcurement;
    if (controller == null) return;
    final restored = await controller.open(
      purpose: BuyV2ProcurementPurpose.restock,
      returnTo: 'dashboard',
      restoreOnly: true,
    );
    if (!mounted || !restored || !controller.scopeCurrent) return;
    _searchController.text = _activeProcurement.query;
    setState(() {
      _procurementReturnOperation = _WorkspaceOperation.values
          .where((value) => value.name == controller.bookmark!.returnTo)
          .firstOrNull;
      _procurementProductId = null;
      _procurementReady = true;
      _view = _WorkspaceControlView.procurement;
    });
  }

  bool _isNestedWorkspaceOperation(_WorkspaceOperation operation) => const {
    _WorkspaceOperation.deliverySettings,
    _WorkspaceOperation.staff,
    _WorkspaceOperation.offers,
    _WorkspaceOperation.paidWork,
    _WorkspaceOperation.stockStatement,
  }.contains(operation);

  bool get _hasCounterOrderDraft =>
      _view == _WorkspaceControlView.operation &&
      (_operation == _WorkspaceOperation.counterOrder ||
          (_operation == _WorkspaceOperation.sales && _counterKey.currentState != null)) &&
      (session.workspaceOrderCustomer.trim().isNotEmpty ||
          session.workspaceOrderQuantities.isNotEmpty);

  Future<bool> _confirmPurchaseNavigation() async {
    if (_purchaseNavigationPending) return false;
    _purchaseNavigationPending = true;
    final scope = session.workspaceSupplierScope;
    final view = _view, operation = _operation;
    final receiving = _receivingKey.currentState;
    final purchaseEntry = view == _WorkspaceControlView.operation &&
        operation == _WorkspaceOperation.sourcing ? _purchaseEntryKey.currentState : null;
    final discardEditablePurchase = purchaseEntry != null &&
        !purchaseEntry.widget.openingOnly && !purchaseEntry._readOnly && purchaseEntry._dirty;
    bool current() => mounted && scope == session.workspaceSupplierScope &&
        view == _view && operation == _operation &&
        identical(receiving, _receivingKey.currentState) &&
        (purchaseEntry == null || (purchaseEntry.mounted &&
          identical(purchaseEntry, _purchaseEntryKey.currentState)));
    try {
      if (!await (receiving?.confirmLeave() ?? Future.value(true)) || !current()) {
        return false;
      }
      if (!await (purchaseEntry?.confirmLeave() ?? Future.value(true))) {
        return false;
      }
      if (!current()) return false;
      if (operation == _WorkspaceOperation.sourcing) {
        _purchasesKey.currentState?.cancelPendingAction();
      }
      // An imperative destination can retain this editor underneath it.
      // Explicit discard must not resurrect its unsaved input on return.
      if (discardEditablePurchase) purchaseEntry.widget.onBack();
      return current();
    } finally {
      _purchaseNavigationPending = false;
    }
  }

  Future<bool> _confirmDiscardCounterOrder() async {
    if (!await _confirmPurchaseNavigation()) return false;
    if (_counterKey.currentState?._assistantClosed == true || _counterKey.currentState?._assistantMode == true || _counterKey.currentState?._transferredOwner != null && !_counterKey.currentState!._nativeOwnerCurrent) return await _counterKey.currentState!.flushForNavigation();
    if ((_operation == _WorkspaceOperation.counterOrder || _counterKey.currentState != null) &&
        !await (_counterKey.currentState?.flushForNavigation() ??
            Future.value(true))) {
      return false;
    }
    if (!mounted) return false;
    if (session.counterDraftSubmitting) return false;
    if (session.counterDraftNeedsReconciliation) return true;
    if ((_operation == _WorkspaceOperation.counterOrder || _counterKey.currentState != null) &&
        (_counterKey.currentState?.hasCompletedInvoice ?? false)) {
      // The invoice/ledger already owns this sale. Reset only the next-sale
      // editor, retaining the existing busy/reconciliation guards.
      return session.startNewWorkspaceOrder();
    }
    if (!_hasCounterOrderDraft) return true;
    // A durable draft makes leaving non-destructive; ask only when saving fails.
    if (await session.saveWorkspaceCounterDraft()) {
      // Release the active editor so another order can be selected. The scoped
      // journal, not these transient fields, restores the bill on return.
      // Unscoped sessions have no durable journal and must retain their fields.
      return session.counterDraftIdentity == null ||
          session.startNewWorkspaceOrder();
    }
    if (!mounted) return false;
    final discard = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        key: const Key('work-order-discard-dialog'),
        title: const Text('Draft not saved'),
        titlePadding: const EdgeInsets.fromLTRB(16, 16, 16, 8),
        contentPadding: const EdgeInsets.symmetric(horizontal: 16),
        actionsPadding: const EdgeInsets.all(8),
        content: const Text(
          'Keep editing to retry, or discard this unfinished sale.',
        ),
        actions: [
          TextButton(
            key: const Key('work-order-keep-editing'),
            onPressed: () => Navigator.of(dialogContext).pop(false),
            child: const Text('Keep editing'),
          ),
          TextButton(
            key: const Key('work-order-discard'),
            style: TextButton.styleFrom(
              foregroundColor: const Color(0xFFB42318),
            ),
            onPressed: () => Navigator.of(dialogContext).pop(true),
            child: const Text('Discard sale'),
          ),
        ],
      ),
    );
    return discard == true &&
        await session.discardWorkspaceCounterDraft() &&
        session.startNewWorkspaceOrder();
  }

  Future<void> _leaveOperation({bool exitSale = false}) async {
    Object salesExitIdentity() => (
      _view, _operation, _salesTask, _salesVisitEpoch,
      session.counterDraftIdentity, session.workspaceFinance?.accountScope,
      session.activeWorkspace?.id, session.counterSaleGeneration,
      session.currentWorkspaceOrderId, session.currentWorkspaceOrder,
      _counterKey.currentState, _counterKey.currentState?._invoice,
      _counterKey.currentState?._stage,
    );
    final salesExit = salesExitIdentity();
    final deliveryVisitAtBack = _operation == _WorkspaceOperation.delivery ? _deliveryOrderOrigin : null;
    final receiving = _receivingKey.currentState;
    if (receiving != null) {
      await receiving._close();
      return;
    }
    final purchaseEntry = _purchaseEntryKey.currentState;
    if (_operation == _WorkspaceOperation.sourcing && purchaseEntry != null) {
      await purchaseEntry._back();
      return;
    }
    if (_operation == _WorkspaceOperation.sourcing &&
        (_purchasesKey.currentState?.backWithinPurchases() ?? false)) {
      return;
    }
    if (_operation == _WorkspaceOperation.sales &&
        (_salesKey.currentState?.closeSelectedInvoice() ?? false)) {
      return;
    }
    if (!exitSale &&
        (_operation == _WorkspaceOperation.counterOrder ||
            (_operation == _WorkspaceOperation.sales &&
                _salesKey.currentState?._salesHubView == 'counter' &&
                _counterKey.currentState?._stage != 'items')) &&
        await (_counterKey.currentState?.backWithinSale() ??
            Future.value(false))) {
      return;
    }
    if (_operation == _WorkspaceOperation.sales && _salesTask != null) {
      final counter = _counterKey.currentState;
      final task = _salesTask;
      if (!await (counter?.flushForNavigation() ?? Future.value(true)) || !mounted ||
          salesExitIdentity() != salesExit) return;
      // A completed invoice owns its records; clear only the retained composer.
      // Ordinary unfinished bills still leave and resume without a reset.
      if (task == 'counter' && (counter?.hasCompletedInvoice ?? false) && counter?._assistantClosed != true &&
          (session.counterDraftNeedsReconciliation ||
              !(counter?._startNextSale() ?? false))) return;
      _salesKey.currentState?.showSalesHome();
      return;
    }
    if ((_operation == _WorkspaceOperation.sourcing ||
            _operation == _WorkspaceOperation.statement) &&
        session.focusedWorkspacePurchaseId != null) {
      session.clearWorkspacePurchaseSelection();
      if (_operationReturnView != _WorkspaceControlView.alerts &&
          _operationReturnView != _WorkspaceControlView.search) {
        return;
      }
    }
    if (!await _confirmDiscardCounterOrder() || !mounted) return;
    if (deliveryVisitAtBack != null &&
        (_view != _WorkspaceControlView.operation ||
            _operation != _WorkspaceOperation.delivery ||
            _deliveryOrderOrigin != deliveryVisitAtBack)) {
      return;
    }
    if (_operationReturnView == _WorkspaceControlView.alerts) {
      setState(() => _view = _WorkspaceControlView.alerts);
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted &&
            _view == _WorkspaceControlView.alerts &&
            _alertsScroll.hasClients) {
          _alertsScroll.jumpTo(
            _alertsReturnOffset.clamp(
              0,
              _alertsScroll.position.maxScrollExtent,
            ),
          );
        }
      });
      return;
    }
    if (_operationReturnView == _WorkspaceControlView.search) {
      setState(() => _view = _WorkspaceControlView.search);
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted &&
            _view == _WorkspaceControlView.search &&
            _searchScroll.hasClients) {
          _searchScroll.jumpTo(
            _searchReturnOffset.clamp(
              0,
              _searchScroll.position.maxScrollExtent,
            ),
          );
        }
      });
      return;
    }
    if (_operationReturnView == _WorkspaceControlView.status) {
      // Nested settings must not reset unsaved Store controls or their position.
      setState(() => _view = _WorkspaceControlView.status);
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted &&
            _view == _WorkspaceControlView.status &&
            _settingsScroll.hasClients) {
          // The lazy list's first max extent is only an estimate, especially
          // with enlarged text. Let layout resolve the saved offset before
          // scroll physics clamps it to the actual content extent.
          _settingsScroll.jumpTo(_settingsReturnOffset);
        }
      });
      return;
    }
    final parent = _operationReturnOperation;
    final deliveryOrigin = _deliveryOrderOrigin;
    if (_operation == _WorkspaceOperation.delivery &&
        parent == _WorkspaceOperation.orders && deliveryOrigin != null) {
      final restore = deliveryOrigin.storeId != null &&
          deliveryOrigin.storeId == (session.activeWorkspace?.id ?? session.workspaceId) &&
          deliveryOrigin.accountScope == (session.contactDraftStore?.accountScope ?? session.pendingProofStore?.accountScope) &&
          deliveryOrigin.selectedOrderId == session.currentWorkspaceOrderId &&
          session.workspaceOrders.any((order) => order.id == deliveryOrigin.orderId && !order.isClosed);
      setState(() {
        _operation = _WorkspaceOperation.orders;
        _focusedOrderId = restore ? deliveryOrigin.orderId : null;
        _operationReturnView = restore ? deliveryOrigin.returnView : _WorkspaceControlView.dashboard;
        _operationReturnOperation = restore ? deliveryOrigin.returnOperation : null;
        _deliveryOrderOrigin = null;
      });
      return;
    }
    if (_operationReturnView == _WorkspaceControlView.operation &&
        parent != null) {
      setState(() {
        if (parent == _WorkspaceOperation.orders &&
            _operation == _WorkspaceOperation.orders) {
          _focusedOrderId = null;
        }
        _operation = parent;
        _operationReturnView = _WorkspaceControlView.dashboard;
        _operationReturnOperation = null;
      });
      return;
    }
    _showDashboard();
  }

  Future<void> _navigateFromCounterDraft(VoidCallback destination) async {
    if (!await _confirmDiscardCounterOrder() || !mounted) return;
    destination();
  }

  void _handleProcurementDestinationChanged(BuyV2Destination destination) {
    if (destination != BuyV2Destination.shop ||
        _view != _WorkspaceControlView.procurement) {
      return;
    }
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted && _view == _WorkspaceControlView.procurement) {
        _leaveProcurement();
      }
    });
  }

  Future<void> _openProfile(BuildContext context, WorkWorkspace workspace) async {
    if (!await _confirmPurchaseNavigation() || !context.mounted) return;
    var profileApproved = false;
    try {
      final approved = context.getInheritedWidgetOfExactType<MoolAssistantWorkspaceScope>()?.readWorkspace();
      profileApproved = widget.accountAuthenticated && approved?.approved == true &&
          approved?.isStore == true && approved?.approvalAccountScope != null &&
          approved?.id == workspace.id && approved?.profile == workspace.profileId &&
          approved?.revision == session.navigationScopeRevision;
    } on Object {
      // A failed or absent approval readback must leave personal Profile usable
      // without exposing retained Store controls as an activated Workspace.
    }
    showGlobalProfilePanelV2(
      context,
      accountAuthenticated: widget.accountAuthenticated,
      activeWorkspace: !profileApproved ? null : GlobalProfileWorkspaceContext(
        name: workspace.name,
        roleLabel: workspace.profileLabel,
        area: workspace.area,
      ),
      contextAction: !profileApproved ? null : GlobalProfileContextAction(
        id: 'store-settings',
        title: 'Store tools',
        detail: 'Business settings, customers and records',
        actionLabel: 'Manage store',
        icon: Icons.tune_rounded,
        accentColor: MoolColors.navy,
        gradientColors: const [MoolColors.navy, MoolColors.navy],
        onPressed: () => _showOperation(_WorkspaceOperation.settings),
      ),
      onOpenRoute: (route) {
        if (route == '/app/work/my-work' && profileApproved) {
          _showOperation(_WorkspaceOperation.settings);
        } else if (Uri.tryParse(route)?.path == '/app/account/plans' && profileApproved) {
          context.push('/app/account/plans?scope=workspace');
        } else if (Uri.tryParse(route)?.path == '/app/account/security') {
          // A pushed Store can differ from the router's displayed base URI.
          // Retain its actual destination when sign-in replaces the stack.
          final current = GoRouterState.of(context).uri;
          final returnLocation = _view == _WorkspaceControlView.dashboard
              ? current.replace(
                  queryParameters: {
                    ...current.queryParameters,
                    'section': 'dashboard',
                  },
                )
              : current;
          context.push(
            globalSecurityLocationForReturn(returnLocation.toString()),
          );
        } else {
          context.push(route);
        }
      },
    );
  }

  Future<void> _showWorkspaceSwitcher(BuildContext context, {StoreSettingsReviewScope? reviewScope, String? selectedId}) async {
    if (reviewScope?.mayApply == false) return;
    final current = session.activeWorkspace;
    if (current == null) return;
    if (reviewScope == null) session.retainWorkspaceApplication();
    final applications = session.savedWorkspaceApplications;
    final bottomInset = MediaQuery.viewPaddingOf(context).bottom;
    final choices = [current, ...session.otherWorkspaces].where((store) => selectedId == null || store.id == selectedId).toList();
    await showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      useSafeArea: true,
      showDragHandle: true,
      builder: (sheetContext) => SafeArea(
        top: false,
        bottom: false,
        child: ConstrainedBox(
          constraints: BoxConstraints(
            maxHeight: MediaQuery.sizeOf(sheetContext).height * .76,
          ),
          child: WorkWorkspaceApplicationChooserBody(choices: choices,
            applications: reviewScope == null ? applications : const [], currentId: current.id, bottomInset: bottomInset,
            onWorkspace: (workspace) async {
              if (reviewScope?.mayApply == false || !await _confirmPurchaseNavigation() ||
                  reviewScope?.mayApply == false || !mounted || !sheetContext.mounted) return;
              if (reviewScope != null && !session.otherWorkspaces.any((store) => store.id == workspace.id)) return;
              if (!await session.activateWorkspace(workspace) || !mounted || !sheetContext.mounted ||
                  session.activeWorkspace?.id != workspace.id) return;
              Navigator.of(sheetContext).pop(); _showDashboard();
            },
            onApplication: (application) async {
              if (!await _confirmPurchaseNavigation() || !mounted || !sheetContext.mounted) return;
              if (!session.resumeWorkspaceApplication(application.id)) return;
              Navigator.of(sheetContext).pop(); context.push(session.workspaceApplicationRoute);
            },
            onRequest: () async {
              if (!await _confirmPurchaseNavigation() || !mounted || !sheetContext.mounted) return;
              if (session.startAnotherWork()) { Navigator.of(sheetContext).pop(); context.push('/app/work/workspace/choose'); }
            }),
        ),
      ),
    );
  }

  void _clearSearch() {
    _searchController.clear();
    session.updateWorkspaceSearch('');
    _searchFocus.requestFocus();
  }

  void _exitSavedSearch(_SavedStoreSearchVisit? visit, {
    bool preserveGlobalQuery = false,
  }) {
    if (visit == null || _savedSearchVisit != visit ||
        _view != _WorkspaceControlView.search || !_searchScopeCurrent(visit)) return;
    _finishSearch(preserveQuery: preserveGlobalQuery && !visit.fromOrders);
  }

  void _finishSearch({bool preserveQuery = false}) {
    final returnToOrders =
        _ordersSearchStoreId != null &&
        _ordersSearchStoreId == session.activeWorkspace?.id;
    final orderId = _ordersSearchReturnOrderId;
    _searchFocus.unfocus();
    if (!preserveQuery) _retainedSavedSearch = null;
    _savedSearchVisit = null;
    _searchVisitToken++;
    if (!preserveQuery) {
      _searchController.clear();
      session.updateWorkspaceSearch('');
    }
    _ordersSearchStoreId = null;
    _ordersSearchReturnOrderId = null;
    if (returnToOrders) {
      _showOperation(_WorkspaceOperation.orders, focusedOrderId: orderId);
    } else {
      _showDashboard();
    }
  }

  Future<void> _saveAvailability({StoreSettingsReviewScope? reviewScope, bool Function()? current}) async {
    if (current?.call() == false || reviewScope?.mayApply == false) { session.showError('These settings changed. Your entries are kept. Reopen this task.'); return; }
    if (_settingsSaving || session.workspaceTradingPreferencesSaving || session.workspacePrivatePreferenceBusy(WorkspacePrivatePreferenceKind.status)) return;
    if (!_privatePreferenceCanSave(session, WorkspacePrivatePreferenceKind.status, _settingsPrivateSourceProof)) {
      session.showError('Check the saved preferences before making another Save. Your entries are kept.'); return;
    }
    final inputSignature = _settingsInputSignature;
    final owner = session, scope = session.tradingPreferencesContext;
    final expectedStore = _settingsStoreId, expectedNavigation = _settingsScopeRevision;
    if (_settingsStoreId != (session.activeWorkspace?.id ?? session.workspaceId) ||
        _settingsScopeRevision != session.navigationScopeRevision) {
      session.showError('Your Store changed. Reopen these settings in the correct Store. Your entries are kept.');
      return;
    }
    if (_draftBusyMinutes < 0 || _draftFulfilmentMode.trim().isEmpty) {
      session.showError('Check the preparation time and fulfilment preference.');
      return;
    }
    if (_draftMaximumActiveOrders < 0 ||
        !(_settingsForm.currentState?.validate() ?? true)) {
      _settingsForm.currentState?.validate();
      if (_settingsScroll.hasClients) _settingsScroll.jumpTo(0);
      session.showError('Enter an active-order limit or choose Unlimited.');
      return;
    }
    final availabilityChanged = _availabilityDirty;
    final tradingControlsChanged = _tradingControlsDirty;
    final durableTrading = session.tradingPreferencesPersistenceAvailable;
    // Refuse invalid publication before any preference is applied. For the
    // durable path, leave other settings untouched if the device write fails.
    if (durableTrading && _draftVisibleToCustomers &&
        !session.workspaceVisibleToCustomers && !session.workspacePublicationReport.ready) {
      session.setWorkspaceVisibility(true); // Existing truthful refusal copy.
      return;
    }
    final desired = <String, Object?>{
      'acceptingOrders': _draftAcceptingOrders, 'visibleToCustomers': _draftVisibleToCustomers,
      'fulfilmentMode': _draftFulfilmentMode, 'busyMinutes': _draftBusyMinutes,
      'reopensAt': availabilityChanged && _draftAcceptingOrders ? '' : _draftReopensAt,
      'openingTime': _draftOpeningTime.trim(), 'closingTime': _draftClosingTime.trim(),
      'maximumActiveOrders': _draftMaximumActiveOrders, 'alertSound': _draftOrderAlertSound, 'alertVibration': _draftOrderAlertVibration};
    final tradingKeys = {'openingTime', 'closingTime', 'maximumActiveOrders', 'alertSound', 'alertVibration'};
    final readinessKeys = {'busyMinutes', 'fulfilmentMode'};
    final availabilityKeys = {'acceptingOrders', 'visibleToCustomers', 'busyMinutes', 'fulfilmentMode', 'reopensAt'};
    if (reviewScope?.beginAttempt(desired, intermediate: [
      {for (final key in tradingKeys) key: desired[key]},
      {for (final key in {...tradingKeys, ...readinessKeys}) key: desired[key]},
      {'visibleToCustomers': desired['visibleToCustomers']},
      {for (final key in {...tradingKeys, ...readinessKeys, 'visibleToCustomers'}) key: desired[key]},
      {for (final key in availabilityKeys) key: desired[key]},
    ]) == false) { session.showError('Check the original settings attempt. Your entries are kept.'); return; }
    bool applyOtherPreferences() {
      if (current?.call() == false || reviewScope?.current() == false || reviewScope?.sourceCurrent() == false) return false;
      if ((desired['visibleToCustomers'] as bool) != session.workspaceVisibleToCustomers &&
          !session.setWorkspaceVisibility((desired['visibleToCustomers'] as bool))) { return false; }
      return !availabilityChanged || session.saveWorkspaceAvailability(
        acceptingOrders: desired['acceptingOrders'] as bool,
        fulfilmentMode: desired['fulfilmentMode'] as String,
        busyMinutes: desired['busyMinutes'] as int,
        reopensAt: desired['reopensAt'] as String,
        expectedStoreId: expectedStore,
        expectedNavigationRevision: expectedNavigation,
      );
    }
    if (!durableTrading && !applyOtherPreferences()) return;
    if (tradingControlsChanged || session.tradingPreferencesPersistenceAvailable &&
        (!session.workspaceTradingPreferencesSaved || !session.workspaceReadinessPreferencesSaved ||
          session.workspaceTradingPreferencesError != null)) {
      if (current?.call() == false || reviewScope?.sourceCurrent() == false) return;
      final saved = session.saveWorkspaceTradingControls(
        openingTime: desired['openingTime'] as String,
        closingTime: desired['closingTime'] as String,
        maximumActiveOrders: desired['maximumActiveOrders'] as int,
        alertSound: desired['alertSound'] as bool,
        alertVibration: desired['alertVibration'] as bool,
        preparationMinutes: desired['busyMinutes'] as int,
        fulfilmentPreference: desired['fulfilmentMode'] as String,
        expectedStoreId: expectedStore,
        expectedNavigationRevision: expectedNavigation,
      );
      if (!saved) return;
      if (session.tradingPreferencesPersistenceAvailable) {
        setState(() => _settingsSaving = true);
        final confirmed = await session.workspaceTradingPreferencesWrite;
        if (!mounted) return;
        setState(() => _settingsSaving = false);
        if (current?.call() == false || reviewScope?.current() == false || !identical(owner, session) || scope != session.tradingPreferencesContext ||
            _view != _WorkspaceControlView.status) { return; }
        if (!confirmed || !session.workspaceTradingPreferencesSaved) {
          session.showError(session.workspaceTradingPreferencesError ?? 'Device save could not be confirmed. Your entries are kept. Try again.');
          return;
        }
        session.showNotice('Store preferences saved on this device. Public sync is pending.');
      }
    }
    if (durableTrading && !applyOtherPreferences()) return;
    if (session.workspaceOriginalPrivatePreferencesConfigured) {
      if (!mounted || current?.call() == false || _settingsInputSignature != inputSignature) return;
      FocusScope.of(context).unfocus();
      reviewScope?.completeAttempt();
      final confirmed = await _saveStorePrivatePreference(session, WorkspacePrivatePreferenceKind.status, desired,
        originalProof: _settingsPrivateSourceProof, reviewScope: reviewScope,
        current: () => mounted && identical(owner, session) && current?.call() != false && _settingsInputSignature == inputSignature);
      if (!confirmed || !mounted || current?.call() == false) return;
      _settingsPrivateSourceProof = session.workspacePrivatePreferenceSourceProof(WorkspacePrivatePreferenceKind.status);
    }
    reviewScope?.completeAttempt();
    if (current?.call() == false) return;
    reviewScope?.dispose();
    setState(() => _view = _WorkspaceControlView.dashboard);
  }

  String get _settingsInputSignature => jsonEncode([_draftAcceptingOrders, _draftVisibleToCustomers, _draftFulfilmentMode,
    _draftBusyMinutes, _draftReopensAt, _draftOpeningTime, _draftClosingTime, _draftMaximumActiveOrders,
    _draftOrderAlertSound, _draftOrderAlertVibration]);

  bool get _availabilityDirty =>
      _draftAcceptingOrders != session.workspaceAcceptingOrders ||
      _draftFulfilmentMode != session.workspaceFulfilmentMode ||
      _draftBusyMinutes != session.workspaceBusyMinutes ||
      _draftReopensAt != session.workspaceReopensAt;

  bool get _tradingControlsDirty =>
      _draftBusyMinutes != session.workspaceBusyMinutes ||
      _draftFulfilmentMode != session.workspaceFulfilmentMode ||
      _draftOpeningTime != session.workspaceOpeningTime ||
      _draftClosingTime != session.workspaceClosingTime ||
      _draftMaximumActiveOrders != session.workspaceMaximumActiveOrders ||
      _draftOrderAlertSound != session.workspaceOrderAlertSound ||
      _draftOrderAlertVibration != session.workspaceOrderAlertVibration;

  bool get _settingsDirty =>
      session.workspaceOriginalPrivatePreferencesConfigured &&
        (session.workspacePrivatePreferencePending(WorkspacePrivatePreferenceKind.status) != null || session.workspacePrivatePreferenceError(WorkspacePrivatePreferenceKind.status) != null) ||
      _availabilityDirty ||
      _draftVisibleToCustomers != session.workspaceVisibleToCustomers ||
      _tradingControlsDirty;

  Future<void> _leaveSettings() async {
    if (!_settingsDirty) {
      _showDashboard();
      return;
    }
    final discard = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        key: const Key('work-settings-discard-dialog'),
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(24)),
        titlePadding: const EdgeInsets.fromLTRB(14, 14, 14, 0),
        title: Container(
          padding: const EdgeInsets.all(12),
          decoration: BoxDecoration(
            color: const Color(0xFFFFF0DB),
            borderRadius: BorderRadius.circular(16),
          ),
          child: const Row(
            children: [
              Icon(Icons.warning_amber_rounded, color: Color(0xFF9A4A00)),
              SizedBox(width: 8),
              Expanded(child: Text('Unsaved Store settings')),
            ],
          ),
        ),
        contentPadding: const EdgeInsets.fromLTRB(18, 12, 18, 18),
        content: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            const Text(
              'Keep editing to save your changes, or discard them.',
              style: TextStyle(color: MoolColors.muted),
            ),
            const SizedBox(height: 14),
            Row(
              children: [
                Expanded(
                  child: OutlinedButton(
                    onPressed: () => Navigator.of(dialogContext).pop(false),
                    child: const FittedBox(child: Text('Keep editing')),
                  ),
                ),
                const SizedBox(width: 8),
                Expanded(
                  child: FilledButton(
                    style: FilledButton.styleFrom(
                      backgroundColor: const Color(0xFFB42318),
                    ),
                    onPressed: () => Navigator.of(dialogContext).pop(true),
                    child: const FittedBox(child: Text('Discard')),
                  ),
                ),
              ],
            ),
          ],
        ),
      ),
    );
    if (discard == true && mounted) _showDashboard();
  }
}

enum _WorkspaceControlView {
  dashboard,
  search,
  status,
  alerts,
  procurement,
  operation,
}

class _StoreRestockSupplierFilter extends StatelessWidget {
  const _StoreRestockSupplierFilter({required this.controller});
  final WorkProcurementController controller;
  @override
  Widget build(BuildContext context) {
    final types = controller.restockSupplierTypes, names = controller.restockSupplierTypesLabel;
    final status = controller.restockSupplierClassificationMessage ??
      (controller.restockSupplierFilterConnected ? 'The catalogue requests these supplier types. Check each product before buying.' :
        'Supplier filter awaiting connection. Matching results cannot be confirmed yet.');
    return IconButton(
      key: const Key('work-restock-supplier-types'),
      tooltip: 'Supplier types · $names',
      constraints: const BoxConstraints.tightFor(width: 48, height: 48),
      onPressed: () => showModalBottomSheet<void>(context: context, isScrollControlled: true,
        builder: (sheetContext) => SafeArea(child: SingleChildScrollView(padding: const EdgeInsets.all(20),
          child: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.start, children: [
            Text('Supplier types', style: Theme.of(sheetContext).textTheme.titleMedium),
            const SizedBox(height: 12), Text(names), const SizedBox(height: 12), Text(status),
            if (!controller.restockSupplierClassificationResolved && types.isNotEmpty) ...[
              const SizedBox(height: 12),
              const Text('Prepared buying rules'),
              const Text('Wholesaler: Manufacturers.\nDistributor: Manufacturers and wholesalers.\nSub-distributor: Manufacturers and distributors.'),
            ],
            const SizedBox(height: 12), TextButton(key: const Key('work-restock-supplier-types-close'),
              onPressed: () {
                if (sheetContext.mounted && ModalRoute.of(sheetContext)?.isCurrent == true) {
                  Navigator.of(sheetContext).pop();
                }
              }, child: const Text('Close')),
          ])))),
      icon: const Icon(Icons.info_outline, size: 20),
    );
  }
}

class _StoreRestockPurposeControl extends StatelessWidget {
  const _StoreRestockPurposeControl({required this.controller});
  final WorkProcurementController controller;

  Future<void> _choose(BuildContext context) async {
    if (!context.mounted || !controller.scopeCurrent || controller.bookmark?.active != true) return;
    final opened = controller.session, revision = controller.restockPolicyRevision;
    await showModalBottomSheet<void>(context: context, isScrollControlled: true,
      backgroundColor: const Color(0xFFF8FAFF), builder: (sheetContext) {
        bool routeCurrent() => sheetContext.mounted && ModalRoute.of(sheetContext)?.isCurrent == true;
        bool purchaseCurrent() => context.mounted && routeCurrent() && controller.scopeCurrent && controller.bookmark?.active == true &&
          identical(controller.session, opened) && controller.restockPolicyRevision == revision;
        return AnimatedBuilder(animation: controller, builder: (context, _) => SafeArea(
          child: SingleChildScrollView(padding: const EdgeInsets.all(16), child: Column(
            mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.stretch, children: [
              const Text('Purchase purpose', style: TextStyle(fontSize: 17, fontWeight: FontWeight.w700, color: MoolColors.navy)),
              const SizedBox(height: 8),
              for (final choice in controller.restockPurposeOptions)
                ListTile(key: ValueKey('work-restock-purpose-${choice.name}'), dense: true,
                  contentPadding: EdgeInsets.zero, title: Text(choice.label),
                  trailing: controller.restockPurpose == choice ? const Icon(Icons.check_rounded) : null,
                  enabled: !controller.restockChoiceBusy,
                  onTap: () async {
                    if (!purchaseCurrent()) return;
                    final saved = await controller.selectRestockPurpose(choice);
                    if (saved && sheetContext.mounted && routeCurrent() && identical(controller.session, opened) &&
                        controller.restockPolicyRevision == revision + 1) {
                      Navigator.of(sheetContext).pop();
                    }
                  }),
              const SizedBox(height: 8),
              if (controller.restockPurposeOptions.isEmpty)
                const Text('Your Store profile changed. Reopen this purchase to choose its purpose.', style: TextStyle(fontSize: 12))
              else if (!controller.restockPurposeOptions.contains(WorkRestockPurchasePurpose.resale))
                const Text('Finished goods for resale require a verified resale role.', style: TextStyle(fontSize: 12)),
              if (controller.restockChoiceBusy) const LinearProgressIndicator(semanticsLabel: 'Saving purchase purpose'),
              if (controller.restockChoiceMessage case final message?) Padding(padding: const EdgeInsets.only(top: 8),
                child: Text(message, style: const TextStyle(fontSize: 12))),
              Align(alignment: Alignment.centerRight, child: TextButton(onPressed: () {
                if (routeCurrent()) Navigator.of(sheetContext).pop();
              },
                child: const Text('Close'))),
            ])),
        ));
      });
  }

  @override
  Widget build(BuildContext context) {
    final opened = controller.session, revision = controller.restockPolicyRevision;
    return Material(color: const Color(0xFFF8FAFF),
    child: Padding(padding: const EdgeInsets.symmetric(horizontal: 12),
      child: TextButton.icon(key: const Key('work-restock-purpose'),
        style: TextButton.styleFrom(alignment: Alignment.centerLeft,
          minimumSize: const Size(double.infinity, 44), foregroundColor: MoolColors.navy),
        onPressed: controller.restockChoiceBusy ? null : () {
          if (context.mounted && identical(controller.session, opened) && controller.restockPolicyRevision == revision) {
            unawaited(_choose(context));
          }
        },
        icon: const Icon(Icons.inventory_2_outlined, size: 18),
        label: Text(controller.restockPurpose?.label ?? 'Choose purchase purpose',
          style: const TextStyle(fontSize: 13, fontWeight: FontWeight.w600)))),
  );
  }
}

class _StoreProcurementRouteObserver extends NavigatorObserver {
  _StoreProcurementRouteObserver(this.onChanged);
  final ValueChanged<bool> onChanged;
  void _changed() => onChanged(navigator?.canPop() ?? false);
  @override
  void didPush(Route<dynamic> route, Route<dynamic>? previousRoute) => _changed();
  @override
  void didPop(Route<dynamic> route, Route<dynamic>? previousRoute) => _changed();
  @override
  void didRemove(Route<dynamic> route, Route<dynamic>? previousRoute) => _changed();
  @override
  void didReplace({Route<dynamic>? newRoute, Route<dynamic>? oldRoute}) => _changed();
}

class _StoreProcurementSurface extends StatefulWidget {
  const _StoreProcurementSurface({
    required this.session,
    required this.workSession,
    required this.receivingKey,
    required this.accountIdentity,
    required this.accountAuthenticated,
    required this.ready,
    this.productId,
    this.orderId,
    required this.onExit,
    required this.onDestinationChanged,
    required this.onRouteCoveredChanged,
  });
  final BuyV2Session session;
  final WorkSession workSession;
  final GlobalKey<_StoreReceiveGoodsState> receivingKey;
  final AuthenticatedAccountIdentity? accountIdentity;
  final bool accountAuthenticated, ready;
  final String? productId, orderId;
  final VoidCallback onExit;
  final ValueChanged<BuyV2Destination> onDestinationChanged;
  final ValueChanged<bool> onRouteCoveredChanged;

  @override
  State<_StoreProcurementSurface> createState() =>
      _StoreProcurementSurfaceState();
}

class _StoreProcurementSurfaceState extends State<_StoreProcurementSurface> {
  WorkspaceRestockPurchaseOriginal? _receivingOriginal;
  WorkspacePurchaseOrder? _receivingOrder;
  bool _openingReceiving = false;
  GlobalKey<NavigatorState> _buyingNavigatorKey = GlobalKey<NavigatorState>();
  late final _routeObserver = _StoreProcurementRouteObserver(
    (covered) => widget.onRouteCoveredChanged(covered));

  Widget _scopedBuyingRoutes(Widget child) {
    // Supplier/product routes belong inside the existing buying Store shell.
    // An invalid owner retires every covered route to the existing recovery UI.
    if (!widget.session.isStoreProcurement || !widget.session.procurementScopeCurrent) {
      return child;
    }
    return NavigatorPopHandler<Object?>(
      onPopWithResult: (result) {
        final navigator = _buyingNavigatorKey.currentState;
        if (navigator != null) unawaited(navigator.maybePop(result));
      },
      child: Navigator(
        key: _buyingNavigatorKey,
        observers: [_routeObserver],
        pages: [
          MaterialPage<Object?>(
            key: ObjectKey(widget.session),
            child: child,
          ),
        ],
        onDidRemovePage: (_) {},
      ),
    );
  }

  bool _billingScopeCurrent(WorkSession work, BuyV2Session buy) {
    final owner = buy.procurementContext;
    return mounted && identical(widget.workSession, work) &&
        identical(widget.session, buy) && widget.accountAuthenticated && widget.ready &&
        buy.isStoreProcurement && buy.procurementScopeCurrent && owner != null &&
        work.activeWorkspace?.verified == true &&
        work.activeWorkspace?.id == owner.storeId &&
        work.publicationPreferencesContext ==
            (owner.accountId, owner.storeId, work.navigationScopeRevision);
  }

  Future<void> _openBillingDetails({required Object owner,
    required Object account, required int visit}) async {
    final work = widget.workSession, buy = widget.session;
    var retired = false;
    bool current() {
      if (retired) return false;
      final valid = _billingScopeCurrent(work, buy) &&
          owner == work.publicationPreferencesContext &&
          account == work.workspaceAccountRecoveryContext &&
          visit == buy.navigationMotionSequence && !buy.cartChangesBlocked &&
          buy.checkoutSubmissionState == BuyV2CheckoutSubmissionState.idle &&
          !buy.checkoutRequiresResolution;
      if (!valid) retired = true;
      return valid;
    }
    if (!current() || work.workspacePublicationPreferencesSaving) return;
    final updates = Listenable.merge([work, buy]);
    Widget retiredDetails(BuildContext sheet) => SafeArea(child: Padding(
      padding: const EdgeInsets.all(12), child: Row(children: [
        const Expanded(child: Text('Your Store changed. Reopen these details in the correct Store.')),
        IconButton(key: const Key('work-procurement-billing-close'),
          tooltip: 'Back to checkout', onPressed: () => Navigator.pop(sheet),
          icon: const Icon(Icons.close)),
      ])));
    await showModalBottomSheet<void>(
      context: context, isScrollControlled: true, useSafeArea: true,
      builder: (sheet) => !current() ? retiredDetails(sheet) : AnimatedBuilder(
        animation: updates,
        builder: (context, _) => Padding(
          padding: EdgeInsets.only(bottom: MediaQuery.viewInsetsOf(context).bottom),
          child: FractionallySizedBox(heightFactor: .92,
            child: SafeArea(top: false, child: Column(children: [
              Padding(padding: const EdgeInsets.only(left: 16, right: 4),
                child: Row(children: [
                  const Expanded(child: Text('Store details',
                    style: TextStyle(fontSize: 16, fontWeight: FontWeight.w700))),
                  IconButton(key: const Key('work-procurement-billing-close'),
                    tooltip: 'Back to checkout',
                    onPressed: () => Navigator.pop(sheet),
                    icon: const Icon(Icons.close)),
                ])),
              Expanded(child: SingleChildScrollView(
                key: const Key('work-procurement-billing-editor'),
                padding: const EdgeInsets.fromLTRB(12, 4, 12, 16),
                child: current()
                    ? StorePublicationSettings(
                        key: ValueKey(('restock-billing', owner, visit)), session: work)
                    : const Text('Your Store changed. Reopen these details in the correct Store.'),
              )),
            ])),
          ),
        ),
      ),
    );
  }

  Widget _billingDetails(BuildContext context) {
    final work = widget.workSession, buy = widget.session;
    return AnimatedBuilder(animation: Listenable.merge([work, buy]),
      builder: (context, _) {
        final current = _billingScopeCurrent(work, buy);
        final ready = current && work.workspacePublicationInputsReady;
        final saving = current && work.workspacePublicationPreferencesSaving;
        final error = current ? work.workspacePublicationPreferencesError : null;
        // These are Store-entered inputs, never account/KYC or issued-invoice facts.
        final details = current ? work.workspacePublicationDetails : null;
        final name = ready ? details!.legalName.trim() : '';
        final completeAddress = ready && [details!.street, details.city,
          details.state, details.pinCode].every((part) => part.trim().isNotEmpty);
        final address = !ready ? '' : details!.billingAddress.trim().isNotEmpty
            ? details.billingAddress.trim() : completeAddress ? details.address : '';
        final message = !current
            ? 'Return to your Store to check billing details.'
            : saving ? 'Saving Store details…'
            : error ?? (!ready ? 'Open Store details to check the saved billing details.'
                : name.isEmpty || address.isEmpty
                    ? 'Add the Store’s legal business name and billing address.' : null);
        final canEdit = current && !saving && !buy.cartChangesBlocked &&
            buy.checkoutSubmissionState == BuyV2CheckoutSubmissionState.idle &&
            !buy.checkoutRequiresResolution;
        final owner = work.publicationPreferencesContext;
        final account = work.workspaceAccountRecoveryContext;
        final visit = buy.navigationMotionSequence;
        return WorkCard(key: const Key('work-procurement-billing-details'),
          padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 6),
          child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
            Row(children: [
              const Icon(Icons.receipt_long_outlined, size: 20),
              const SizedBox(width: 10),
              const Expanded(child: Text('Billing details',
                style: TextStyle(fontSize: 13, fontWeight: FontWeight.w700))),
              TextButton(key: const Key('work-procurement-billing-edit'),
                style: TextButton.styleFrom(foregroundColor: MoolColors.navy,
                  backgroundColor: Colors.white, minimumSize: const Size(44, 44),
                  textStyle: Theme.of(context).textTheme.labelLarge?.copyWith(
                    fontSize: 12, fontWeight: FontWeight.w600)),
                onPressed: canEdit ? () => _openBillingDetails(
                  owner: owner, account: account, visit: visit) : null,
                child: Text(ready ? 'Edit' : 'Open')),
            ]),
            if (message != null) Text(message,
              style: const TextStyle(fontSize: 12, color: MoolColors.muted))
            else ...[
              Text(name, key: const Key('work-procurement-billing-name'),
                style: const TextStyle(fontSize: 13, fontWeight: FontWeight.w600)),
              Text(address, key: const Key('work-procurement-billing-address'),
                style: const TextStyle(fontSize: 12, color: MoolColors.muted)),
            ],
          ]));
      });
  }

  Future<void> _receiveOriginal(WorkspacePurchaseReference reference, WorkspacePurchaseOrder original) async {
    final work = widget.workSession, buy = widget.session;
    final scope = work.workspaceSupplierScope, reader = work.originalPurchaseReader, realm = work.originalPurchaseRealm;
    final buyerReader = buy.purchaseReader;
    final visit = buy.navigationMotionSequence;
    bool current() => mounted && identical(widget.workSession, work) && identical(widget.session, buy) &&
      scope != null && scope == work.workspaceSupplierScope && reader != null && reader.isCurrent &&
      identical(work.originalPurchaseReader, reader) && work.originalPurchaseRealm == realm &&
      buyerReader != null && buyerReader.isCurrent && identical(buy.purchaseReader, buyerReader) &&
      buyerReader.accountUserId == scope.$1 && buy.purchaseRealm == realm &&
      buy.isStoreProcurement && buy.procurementScopeCurrent && buy.navigationMotionSequence == visit &&
      buy.destination == BuyV2Destination.orders && buy.view == BuyV2View.catalogue &&
      buy.procurementContext?.accountId == scope.$1 &&
      buy.procurementContext?.storeId == scope.$2 && reader.accountUserId == scope.$1;
    if (_openingReceiving || _receivingOriginal != null || scope == null || reader == null || buyerReader == null || !current() ||
        original.purchaser?.kind != 'store' || original.purchaser?.storeId != scope.$2 ||
        original.originalFingerprint != reference.originalFingerprint) {
      return;
    }
    setState(() => _openingReceiving = true);
    try {
      final checked = await buyerReader.readReferencedOrder(role: WorkspaceOrderIdentityRole.buyer,
        realm: realm, reference: reference, buyingStoreId: scope.$2);
      if (!mounted || !current()) return;
      if (checked == null || checked.purchaser?.kind != 'store' || checked.purchaser?.storeId != scope.$2) {
        work.showError('This purchase could not be checked for your Store. Reopen its saved details and try again.');
        return;
      }
      final source = WorkspaceRestockPurchaseOriginal.fromJson({'schemaVersion': 1, 'realm': realm,
        'accountScope': scope.$1, 'buyingStoreId': scope.$2, 'reference': reference.toJson(),
        'lines': [for (final line in checked.lines) {'lineId': line.lineId,
          'quantityMilli': line.quantityMilli, 'quantityUnit': line.quantityUnit}]});
      FocusScope.of(context).unfocus();
      setState(() { _receivingOriginal = source; _receivingOrder = checked; });
    } on Object {
      if (current()) work.showError('This purchase could not be opened for receiving. Your saved goods are kept.');
    } finally { if (mounted) setState(() => _openingReceiving = false); }
  }

  void _closeReceiving() {
    if (mounted) setState(() { _receivingOriginal = null; _receivingOrder = null; });
  }
  bool _trackingOpened = false;
  bool _returnScheduled = false;
  late BuyV2View _initialView;
  late BuyV2Destination _initialDestination;
  String? _initialProductId, _initialOrderId;

  void _captureEntry() {
    final session = widget.session;
    _initialView = widget.orderId != null
        ? BuyV2View.tracking
        : widget.productId != null
        ? BuyV2View.product
        : session.isStoreProcurement
        ? session.view
        : BuyV2View.catalogue;
    _initialDestination =
        widget.orderId != null ||
            (session.isStoreProcurement &&
                session.destination == BuyV2Destination.orders)
        ? BuyV2Destination.orders
        : BuyV2Destination.wholesale;
    _initialProductId =
        widget.productId ??
        (_initialView == BuyV2View.product ? session.selectedProductId : null);
    _initialOrderId =
        widget.orderId ??
        (<BuyV2View>{
              BuyV2View.tracking,
              BuyV2View.orderItems,
              BuyV2View.assist,
            }.contains(_initialView)
            ? session.selectedOrderId
            : null);
  }

  @override
  void initState() {
    super.initState();
    _captureEntry();
    _trackingOpened =
        !widget.session.isStoreProcurement &&
        widget.orderId != null &&
        widget.session.view == BuyV2View.tracking &&
        widget.session.selectedOrderId == widget.orderId;
    widget.session.addListener(_trackingChanged);
  }

  @override
  void didUpdateWidget(covariant _StoreProcurementSurface oldWidget) {
    super.didUpdateWidget(oldWidget);
    final source = _receivingOriginal, scope = widget.workSession.workspaceSupplierScope;
    if (source != null && (scope == null || source.accountScope != scope.$1 || source.buyingStoreId != scope.$2)) {
      _receivingOriginal = null; _receivingOrder = null;
    }
    if (oldWidget.session != widget.session ||
        oldWidget.productId != widget.productId ||
        oldWidget.orderId != widget.orderId) {
      _captureEntry();
      _buyingNavigatorKey = GlobalKey<NavigatorState>();
    }
    if (oldWidget.session != widget.session) {
      oldWidget.session.removeListener(_trackingChanged);
      widget.session.addListener(_trackingChanged);
    }
    if (oldWidget.orderId != widget.orderId) {
      _trackingOpened = false;
      _returnScheduled = false;
    }
  }

  void _trackingChanged() {
    final orderId = widget.orderId;
    if (orderId == null) return;
    final session = widget.session;
    if (session.view == BuyV2View.tracking &&
        session.selectedOrderId == orderId) {
      _trackingOpened = true;
    }
    if (!_trackingOpened || _returnScheduled) return;
    if (session.view != BuyV2View.catalogue &&
        session.selectedOrderId == orderId) {
      return;
    }
    setState(() => _returnScheduled = true);
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted && widget.orderId == orderId) widget.onExit();
    });
  }

  @override
  void dispose() {
    widget.session.removeListener(_trackingChanged);
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    if (_returnScheduled) return const SizedBox.shrink();
    final session = widget.session;
    final publicRestockPresentation =
        session.procurementContext?.purpose == BuyV2ProcurementPurpose.restock &&
        (session.view == BuyV2View.catalogue || session.view == BuyV2View.product);
    final accountIdentity = widget.accountIdentity;
    final accountAuthenticated = widget.accountAuthenticated;
    final ready = widget.ready;
    final onExit = widget.onExit;
    final onDestinationChanged = widget.onDestinationChanged;
    final media = MediaQuery.of(context);
    final keyboardVisible = media.viewInsets.bottom > 0;
    final view = View.of(context);
    final devicePadding = EdgeInsets.fromViewPadding(
      view.viewPadding,
      view.devicePixelRatio,
    );
    final navigationHeight =
        MoolLocalNavigationTokens.destinationRailHeight +
        (media.viewPadding.bottom > 2 ? media.viewPadding.bottom : 2) +
        moolAndroidExportedSemanticsClearance(
          viewPadding: devicePadding,
          platform: defaultTargetPlatform,
        );
    return LayoutBuilder(
      builder: (context, constraints) {
        // Buy hides its own footer while typing. Keep the same subtree through
        // every inset change; only move its unneeded footer outside the clip.
        final crop = widget.session.isStoreProcurement || keyboardVisible
            ? 0.0
            : navigationHeight;
        final height = constraints.maxHeight + crop;
        return Stack(
          key: const Key('work-store-procurement-screen'),
          children: [
            Positioned.fill(
              child: Offstage(
                offstage: _receivingOriginal != null,
                child: ClipRect(
                child: OverflowBox(
                  alignment: Alignment.topCenter,
                  minHeight: height,
                  maxHeight: height,
                  child: SizedBox(
                    height: height,
                    child: MediaQuery(
                      data: media.copyWith(
                        size: Size(
                          media.size.width,
                          session.isStoreProcurement && !publicRestockPresentation
                              ? height
                              : media.size.height + crop,
                        ),
                      ),
                      child: _scopedBuyingRoutes(BuyV2Screen(
                        key: const ValueKey('work-store-procurement-buy-host'),
                        session: session,
                        embeddedStore: session.isStoreProcurement,
                        embeddedCartInNavigation:
                            session.procurementContext?.purpose == BuyV2ProcurementPurpose.restock,
                        financeStoreName: session.isStoreProcurement
                            ? widget.workSession.activeWorkspace?.name : null,
                        storeInvoiceDetailsBuilder: session.isStoreProcurement
                            ? _billingDetails : null,
                        onReceivePurchasedOrder: session.isStoreProcurement
                          ? (reference, original) => unawaited(_receiveOriginal(reference, original)) : null,
                        onEmbeddedSystemBack: _receivingOriginal == null ? null
                          : () => unawaited(widget.receivingKey.currentState?._close() ?? Future.value()),
                        accountIdentity: accountIdentity,
                        accountAuthenticated: accountAuthenticated,
                        initialDestination: _initialDestination,
                        initialView: _initialView,
                        productId: _initialProductId,
                        orderId: _initialOrderId,
                        initialCartScope: BuyV2CartScope.wholesale,
                        onExit: onExit,
                        onDestinationChanged: onDestinationChanged,
                      )),
                    ),
                  ),
                ),
              )),
            ),
            if (_receivingOriginal case final source?) Positioned.fill(child: Material(color: const Color(0xFFF8FAFF),
              child: Padding(padding: EdgeInsets.only(bottom: media.viewInsets.bottom),
                child: _StoreReceiveGoodsSurface(key: widget.receivingKey, session: widget.workSession,
                  initialRestockOriginal: source, initialRestockOrder: _receivingOrder, onBack: _closeReceiving)))),
            if (_openingReceiving) const Positioned(top: 0, left: 0, right: 0,
              child: LinearProgressIndicator(minHeight: 2, semanticsLabel: 'Opening goods receiving')),
            if (!ready)
              const Positioned.fill(
                child: ColoredBox(
                  color: Color(0xFFF8FAFF),
                  child: Center(
                    child: Column(
                      mainAxisSize: MainAxisSize.min,
                      children: [
                        CircularProgressIndicator(),
                        SizedBox(height: 12),
                        Text(
                          'Preparing Wholesale and Bulk',
                          style: TextStyle(
                            color: MoolColors.navy,
                            fontWeight: FontWeight.w700,
                          ),
                        ),
                      ],
                    ),
                  ),
                ),
              ),
          ],
        );
      },
    );
  }
}

