    key: const Key('work-first-tap-working-surface'),
    color: Colors.white,
    textStyle: DefaultTextStyle.of(context).style,
    child: DefaultTextStyle.merge(
      style: const TextStyle(color: MoolColors.ink),
      child: child,
    ),
  );
}

String? _storeOrderWorkFilter(WorkspaceOrderRecord order) {
  if (order.isClosed) return null;
  return switch (order.stage) {
    'Confirmed' => 'New',
    'Preparing' => 'Packing',
    'Ready' ||
    'Ready for pickup' ||
    'Ready for collection' ||
    'Awaiting customer' ||
    'Matched' ||
    'Customer confirmed' => 'Ready',
    'Delivery requested' ||
    'Assigned' ||
    'At store' ||
    'Picked up' ||
    'Out for delivery' ||
    'Dispatched' ||
    'Delivering' => 'Delivery',
    _ => 'Attention',
  };
}

bool _hasStoreWorkload(WorkSession session) =>
    session.visibleWorkspaceOrders.any(
      (order) =>
          _storeOrderWorkFilter(order) != null &&
          (!session.isSelectedWorkspaceOrder(order) ||
              _storeOrderWorkFilter(order) == 'Attention'),
    );

class _StoreWorkloadSummary extends StatelessWidget {
  // Counts may repeat while an earlier fade is still outgoing. Let the
  // switcher identify each transition independently of the displayed count.
  static Widget _countTransition(Widget child, Animation<double> animation) =>
      FadeTransition(opacity: animation, child: child);

  const _StoreWorkloadSummary({required this.session, required this.onOrders});
  final WorkSession session;
  final VoidCallback onOrders;

  @override
  Widget build(BuildContext context) {
    const labels = {
      'New': 'Accept',
      'Packing': 'Pack',
      'Ready': 'Check pickup',
      'Delivery': 'Track',
      'Attention': 'Review',
    };
    final counts = {for (final group in labels.keys) group: 0};
    var selectedOrderIsActive = false;
    for (final order in session.visibleWorkspaceOrders) {
      final group = _storeOrderWorkFilter(order);
      if (group != null) {
        counts[group] = counts[group]! + 1;
        selectedOrderIsActive |= session.isSelectedWorkspaceOrder(order);
      }
    }
    final activeCount = counts.values.fold<int>(0, (sum, count) => sum + count);
    if (activeCount == 0 ||
        (activeCount == 1 &&
            selectedOrderIsActive &&
            counts['Attention'] == 0)) {
      return const SizedBox.shrink();
    }
    final groups = labels.keys
        .where((group) => group != 'Attention' || counts[group]! > 0)
        .toList(growable: false);
    final reducedMotion = MediaQuery.of(context).disableAnimations;
    final storeId = session.activeWorkspace?.id ?? session.workspaceId;
    return Padding(
      key: const Key('work-store-workload'),
      padding: const EdgeInsets.fromLTRB(12, 8, 12, 0),
      child: LayoutBuilder(
        builder: (context, constraints) {
          final enlarged = MediaQuery.textScalerOf(context).scale(12) > 18;
          final columns = enlarged || constraints.maxWidth < 208
              ? 2
              : groups.length > 4
              ? 3
              : 4;
          return Material(
            color: Colors.white,
            borderRadius: BorderRadius.circular(12),
            child: Wrap(
              children: [
                for (final group in groups)
                  SizedBox(
                    width: constraints.maxWidth / columns,
                    child: Semantics(
                      button: true,
                      enabled: counts[group]! > 0,
                      label:
                          '${labels[group]}, ${counts[group]} customer orders',
                      child: InkWell(
                        key: Key('work-store-workload-${group.toLowerCase()}'),
                        borderRadius: BorderRadius.circular(10),
                        onTap: counts[group] == 0
                            ? null
                            : () {
                                if (storeId !=
                                    (session.activeWorkspace?.id ??
                                        session.workspaceId)) {
                                  return;
                                }
                                session.setWorkspaceOrderFilter(group);
                                onOrders();
                              },
                        child: ConstrainedBox(
                          constraints: const BoxConstraints(minHeight: 56),
                          child: Padding(
                            padding: const EdgeInsets.symmetric(
                              horizontal: 3,
                              vertical: 7,
                            ),
                            child: ExcludeSemantics(
                              child: AnimatedSwitcher(
                                transitionBuilder: _countTransition,
                                duration: reducedMotion
                                    ? Duration.zero
                                    : const Duration(milliseconds: 140),
                                child: Text.rich(
                                  TextSpan(
                                    text: '${counts[group]}\n',
                                    style: TextStyle(
                                      color: counts[group] == 0
                                          ? MoolColors.muted
                                          : MoolColors.navy,
                                      fontSize: 16,
                                      height: 1.15,
                                      fontWeight: FontWeight.w800,
                                    ),
                                    children: [
                                      TextSpan(
                                        text: labels[group],
                                        style: const TextStyle(
                                          fontSize: 10,
                                          fontWeight: FontWeight.w600,
                                        ),
                                      ),
                                    ],
                                  ),
                                  key: ValueKey((group, counts[group])),
                                  textAlign: TextAlign.center,
                                ),
                              ),
                            ),
                          ),
                        ),
                      ),
                    ),
                  ),
              ],
            ),
          );
        },
      ),
    );
  }
}

class _StoreControlDashboard extends StatelessWidget {
  const _StoreControlDashboard({
    required this.session,
    required this.workspace,
    required this.onSetup,
    required this.onCustomers,
    required this.onMoney,
    required this.onGrow,
    required this.onPromote,
    required this.onAddProducts,
    required this.onOrders,
    required this.onNewSale,
    required this.onDeliverOrder,
    required this.onStock,
    required this.onOpenOperation,
    required this.onBuyStock,
    required this.onReviewFinance,
    required this.reviewedOrder,
    required this.onReviewOrder,
    required this.onCloseOrder,
    this.workingCentre,
    this.showWorkingFinance = true,
    this.homeContentScroll,
    this.onNavigate,
  });

  final WorkSession session;
  final WorkWorkspace workspace;
  final VoidCallback onSetup, onCustomers, onMoney, onGrow, onOrders;
  final VoidCallback onNewSale, onDeliverOrder, onStock, onBuyStock;
  final VoidCallback onPromote, onAddProducts;
  final ValueChanged<_WorkspaceOperation> onOpenOperation;
  final ValueChanged<_WorkspaceFinanceFocus> onReviewFinance;
  final WorkspaceOrderRecord? reviewedOrder;
  final VoidCallback onReviewOrder, onCloseOrder;
  final Widget? workingCentre;
  final bool showWorkingFinance;
  final ScrollController? homeContentScroll;
  final ValueChanged<VoidCallback>? onNavigate;

  void _navigate(VoidCallback action) {
    if (onNavigate case final navigate?) {
      navigate(action);
    } else {
      action();
    }
  }

  @override
  Widget build(BuildContext context) {
    final ready =
        session.retailerSetupSaved ||
        session.reviewStage == WorkReviewStage.live;
    return Material(
      key: const Key('work-workspace-dashboard'),
      color: const Color(0xFFF7F8FC),
      child: LayoutBuilder(
        builder: (context, constraints) {
          if (workingCentre != null) {
            if (!showWorkingFinance) return workingCentre!;
            final keyboard = View.of(context).viewInsets.bottom > 0;
            final actionsBelow = _storeActionsBelowContent(context);
            final height = constraints.maxHeight;
            return SingleChildScrollView(
              key: const Key('work-active-counter-layout'),
              child: SizedBox(
                height: height,
                child: Column(
                  children: [
                    ConstrainedBox(
                      constraints: BoxConstraints(maxHeight: height / 2),
                      child: SingleChildScrollView(
                        child: Offstage(
                          offstage: keyboard,
                          child: _StoreLiveBusinessPulse(
                            session: session,
                            compactHome: false,
                            onOrders: () => _navigate(onCustomers),
                            onSales: () => _navigate(onMoney),
                            onStock: () => _navigate(onStock),
                            onSettlement: () => _navigate(
                              () =>
                                  onOpenOperation(_WorkspaceOperation.payments),
                            ),
                          ),
                        ),
                      ),
                    ),
                    Expanded(
                      child: Flex(
                        key: const Key('work-active-content-area'),
                        direction: actionsBelow
                            ? Axis.vertical
                            : Axis.horizontal,
                        crossAxisAlignment: actionsBelow
                            ? CrossAxisAlignment.stretch
                            : CrossAxisAlignment.start,
                        children: [Expanded(child: workingCentre!)],
                      ),
                    ),
                  ],
                ),
              ),
            );
          }
          if (!ready) {
            return _StoreSetupDeck(
              session: session,
              workspace: workspace,
              onSetup: onSetup,
              onProducts: onAddProducts,
            );
          }
          if (reviewedOrder != null) {
            return _StoreActivityDeck(
              key: const Key('store-stable-working-centre'),
              session: session,
              reviewedOrder: reviewedOrder,
              onOrders: onOrders,
              onReviewOrder: onReviewOrder,
              onCloseOrder: onCloseOrder,
              onStock: onStock,
              onMoney: onMoney,
              onGroupBulk: () =>
                  onOpenOperation(_WorkspaceOperation.groupBuying),
            );
          }
          return _StoreOperatingBoard(
            key: ValueKey(
              session.workspaceStockHistoryScope()?.key ?? workspace.id,
            ),
            session: session,
            scrollController: homeContentScroll,
            onSales: () => onOpenOperation(_WorkspaceOperation.sales),
            onStock: onStock,
            onOrders: onOrders,
            onSettlement: () => onOpenOperation(_WorkspaceOperation.payments),
            onDues: () => onOpenOperation(_WorkspaceOperation.dues),
            onReviewFinance: onReviewFinance,
            onPurchase: (purchase) {
              final current = session.workspacePurchases.where((p) =>
                p.shipmentId == purchase.shipmentId && p.orderId == purchase.orderId &&
                p.accountScope == purchase.accountScope && p.workspaceId == purchase.workspaceId &&
                _homeReceiptNeedsReview(p)).firstOrNull;
              if (current == null || !session.selectWorkspacePurchase(current.shipmentId)) {
                session.showNotice('This purchase has changed. Review the latest purchases.');
                return;
              }
              onOpenOperation(_WorkspaceOperation.sourcing);
            },
          );
        },
      ),
    );
  }
}

/// Read-only projections of the existing Store records, never a second ledger.
bool _homeReceiptNeedsReview(WorkspacePurchaseRecord purchase) {
  final origin = purchase.procurementContext;
  return purchase.valid && origin != null && origin.hasIdentity &&
      const {BuyV2ProcurementPurpose.restock, BuyV2ProcurementPurpose.groupBulkBuying}.contains(origin.purpose) &&
      !purchase.updatedAt.isAfter(DateTime.now()) &&
      !const {WorkspaceSupplyStage.cancelled, WorkspaceSupplyStage.returned}.contains(purchase.stage) &&
      (const {WorkspaceReceiptState.partial, WorkspaceReceiptState.disputed}.contains(purchase.receiptState) ||
       (purchase.stage == WorkspaceSupplyStage.delivered && purchase.receiptState == WorkspaceReceiptState.awaiting));
}

class _StoreOperatingBoard extends StatefulWidget {
  const _StoreOperatingBoard({
    required this.session,
    required this.onSales,
    required this.onStock,
    required this.onOrders,
    required this.onSettlement,
    required this.onDues,
    required this.onPurchase,
    required this.onReviewFinance,
    this.scrollController, this.initialPeriodDays, this.initialReport, this.reviewCurrent, this.readOnlyPreparedSource = false,
    super.key,
  });
  final WorkSession session;
  final int? initialPeriodDays;
  final String? initialReport;
  final bool Function()? reviewCurrent;
  final bool readOnlyPreparedSource;
  final VoidCallback onSales, onStock, onOrders, onSettlement, onDues;
  final ValueChanged<WorkspacePurchaseRecord> onPurchase;
  final ValueChanged<_WorkspaceFinanceFocus> onReviewFinance;
  final ScrollController? scrollController;
  @override
  State<_StoreOperatingBoard> createState() => _StoreOperatingBoardState();
}

class _StoreOperatingBoardState extends State<_StoreOperatingBoard>
    with WidgetsBindingObserver {
  Timer? _dayBoundary;
  Timer? _orderClock;
  final Set<String> _expandedCategories = {};
  int _periodDays = 1;
  DateTime _periodEnd = DateTime.now();
  bool _periodRestored = false;
  Object? _operationalViewScope;

  void _loadOperationalPositions({bool refresh = false}) {
    if (widget.readOnlyPreparedSource || widget.reviewCurrent?.call() == false) return;
    final session = widget.session;
    final scope = (session, session.originalPurchaseReader, session.originalPurchaseRealm,
      session.activeWorkspace?.id, session.navigationScopeRevision);
    if (!session.workspaceOperationalFeedAvailable ||
        (!refresh && scope == _operationalViewScope)) { return; }
    _operationalViewScope = scope;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted && scope == (widget.session, widget.session.originalPurchaseReader,
          widget.session.originalPurchaseRealm, widget.session.activeWorkspace?.id,
          widget.session.navigationScopeRevision)) {
        // The same scoped reader/journal as Orders. Only loaded current positions,
        // not complete online coverage, period activity or public tracking.
        unawaited(widget.session.loadWorkspaceOperationalOrders());
      }
    });
  }

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    if (_periodRestored) return;
    _periodRestored = true;
    if (widget.initialPeriodDays != null) { _periodDays = widget.initialPeriodDays!; return; }
    final scope = widget.session.workspaceStockHistoryScope()?.key;
    if (scope == null) return;
    final saved = PageStorage.maybeOf(context)?.readState(context,
      identifier: ('analytics-period', scope));
    final now = DateTime.now();
    if (saved is ({int days, DateTime cutoff}) &&
        const {1, 7, 30}.contains(saved.days) && !saved.cutoff.isAfter(now)) {
      _periodDays = saved.days;
      // Preserve an ordinary Back cutoff, but never label yesterday as Today.
      _periodEnd = DateUtils.dateOnly(saved.cutoff.toLocal()) == _today
        ? saved.cutoff : now;
    }
  }

  void _rememberPeriod({bool explicitNative = false}) {
    if (widget.reviewCurrent?.call() == false || widget.readOnlyPreparedSource && !explicitNative) return;
    final scope = widget.session.workspaceStockHistoryScope()?.key;
    if (scope != null) {
      PageStorage.maybeOf(context)?.writeState(context,
      (days: _periodDays, cutoff: _periodEnd),
      identifier: ('analytics-period', scope));
    }
  }

  void _toggleCategory(String id) => setState(() {
    if (!_expandedCategories.remove(id)) _expandedCategories.add(id);
  });
  DateTime _today = DateUtils.dateOnly(DateTime.now());

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    _scheduleDayBoundary();
    _startOrderClock();
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) return;
      if (widget.readOnlyPreparedSource || widget.reviewCurrent?.call() == false) return;
      // Hydrate the same scoped records used by Stock and Sales. Missing
      // adapters remain unavailable; Home never supplies replacement data.
      unawaited(widget.session.loadWorkspaceInventory());
      unawaited(widget.session.recoverCustomerLedger());
    });
  }

  void _scheduleDayBoundary() {
    _dayBoundary?.cancel();
    if (widget.readOnlyPreparedSource || widget.reviewCurrent?.call() == false) return;
    final now = DateTime.now();
    final day = DateUtils.dateOnly(now);
    if (day != _today && mounted) {
      setState(() { _today = day; _periodEnd = now; });
      if (_periodRestored) _rememberPeriod();
    }
    _dayBoundary = Timer(
      DateTime(now.year, now.month, now.day + 1).difference(now),
      _scheduleDayBoundary,
    );
  }

  void _startOrderClock() {
    _orderClock?.cancel();
    if (widget.readOnlyPreparedSource || widget.reviewCurrent?.call() == false) return;
    _orderClock = Timer.periodic(const Duration(seconds: 30), (_) {
      if (mounted && !widget.readOnlyPreparedSource && widget.reviewCurrent?.call() != false && ModalRoute.of(context)?.isCurrent == true) {
        setState(() {});
        unawaited(widget.session.loadWorkspaceCommodityPriceAttention());
      }
    });
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (widget.readOnlyPreparedSource || widget.reviewCurrent?.call() == false) {
      if (state == AppLifecycleState.paused) { _dayBoundary?.cancel(); _orderClock?.cancel(); }
      return;
    }
    if (state == AppLifecycleState.resumed) {
      _scheduleDayBoundary();
      _startOrderClock();
      _loadOperationalPositions(refresh: true);
      setState(() => _periodEnd = DateTime.now());
      _rememberPeriod();
    }
    if (state == AppLifecycleState.paused) {
      _dayBoundary?.cancel();
      _orderClock?.cancel();
    }
  }

  @override
  void dispose() {
    _dayBoundary?.cancel();
    _orderClock?.cancel();
    WidgetsBinding.instance.removeObserver(this);
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => ListenableBuilder(
    listenable: widget.session,
    builder: (context, _) {
      final session = widget.session;
      _loadOperationalPositions();
      if (!widget.readOnlyPreparedSource && widget.reviewCurrent?.call() != false && ModalRoute.of(context)?.isCurrent == true && session.workspaceCommodityPriceAttentionConfigured) {
        WidgetsBinding.instance.addPostFrameCallback((_) {
          if (mounted && !widget.readOnlyPreparedSource && widget.reviewCurrent?.call() != false && ModalRoute.of(context)?.isCurrent == true && identical(widget.session, session)) unawaited(session.loadWorkspaceCommodityPriceAttention());
        });
      }
      final periodEnd = _periodEnd;
      final periodStart = DateTime(_today.year, _today.month, _today.day - _periodDays + 1);
      final periodLabel = _periodDays == 1 ? 'today' : 'in last $_periodDays days';
      bool inPeriod(DateTime at) => !at.isBefore(periodStart) && at.isBefore(periodEnd);
      final invoices = session.workspaceInvoices;
      final invoiceIds = <String>{};
      final invoiceReady =
          session.workspaceInvoiceHistoryLoaded &&
          session.customerLedgerRecoveryError == null &&
          invoices.every(
            (invoice) => invoice.validBillAmounts && invoiceIds.add(invoice.id),
          );
      final todayInvoices = invoices.where(
        (invoice) => inPeriod(invoice.issuedAt.toLocal()),
      );
      final billed = invoiceReady
          ? todayInvoices.fold<int>(
              0,
              (sum, invoice) => sum + invoice.payableMinor,
            )
          : null;
      final products = session.workspaceCatalogueItems;
      final stockReady =
          session.workspaceInventoryLoaded &&
          session.workspaceInventoryError == null;
      final exactStock =
          stockReady &&
          products.every(
            (product) =>
                product.stockMode == WorkspaceStockMode.exactQuantity &&
                product.stock >= 0,
          );
      final costsKnown =
          exactStock &&
          products.every(
            (product) => product.stock == 0 || product.purchasePriceMinor > 0,
          );
      final pricesKnown =
          exactStock &&
          products.every(
            (product) => product.stock == 0 || product.sellingPriceMinor > 0,
          );
      int? stockValue(bool selling) {
        if (!(selling ? pricesKnown : costsKnown)) return null;
        var total = BigInt.zero;
        for (final product in products) {
          total += BigInt.from(product.stock) * BigInt.from(
            selling ? product.sellingPriceMinor : product.purchasePriceMinor);
        }
        // The report/formatter owns integer output; never wrap an oversized
        // aggregate into a plausible smaller amount on a native int64 runtime.
        return total > BigInt.from(9223372036854775807) ? null : total.toInt();
      }
      final cost = stockValue(false), resale = stockValue(true);
      final finance = session.workspaceFinance;
      final collectionsReady =
          finance != null &&
          finance.valid &&
          finance.historyComplete &&
          !session.workspaceFinanceStale &&
          !finance.asOf.isAfter(DateTime.now()) &&
          finance.customerLedgers.every((ledger) => ledger.historyComplete);
      final collected = collectionsReady
          ? finance.customerLedgers
                .expand((ledger) => ledger.entries)
                .where(
                  (entry) =>
                      entry.kind == WorkspaceLedgerEntryKind.collection &&
                      entry.state == WorkspaceLedgerPostingState.posted &&
                      inPeriod(entry.occurredAt.toLocal()),
                )
                .fold<int>(0, (sum, entry) => sum + entry.amountMinor)
          : null;
      final returnReasons = collectionsReady
          ? finance.returnReasonsBetween(
              periodStart, periodEnd)
          : null;
      String money(int? value) =>
          value == null ? '—' : '₹${_formatStoreMinorAmount(value)}';
      String count(int? value) =>
          value == null ? '—' : _formatStoreAmount(value);
      String productCount(int value) => '$value ${value == 1 ? 'product' : 'products'}';
      final belowCost = stockReady
          ? products.where((p) => p.stockMode == WorkspaceStockMode.exactQuantity && p.stock > 0 && p.purchasePriceMinor > 0 &&
              p.sellingPriceMinor > 0 && p.sellingPriceMinor < p.purchasePriceMinor).length
          : 0;
      final replenish = stockReady
          ? session.workspaceLowStockProducts.where((p) => p.stock > 0).length
          : 0;
      final unavailable = stockReady ? session.workspaceOutOfStockCount : 0;
      final trendDay = DateUtils.dateOnly(periodEnd);
      final savedBillDays = invoiceReady ? [
        for (var offset = 6; offset >= 0; offset--)
          DateTime(trendDay.year, trendDay.month, trendDay.day - offset),
      ] : <DateTime>[];
      final savedBillSeries = [for (final day in savedBillDays)
        (day, invoices.where((invoice) {
          final at = invoice.issuedAt.toLocal();
          return !at.isBefore(day) && at.isBefore(DateTime(day.year, day.month, day.day + 1)) &&
            at.isBefore(periodEnd);
        }).fold<int>(0, (sum, invoice) => sum + invoice.payableMinor))];
      final hasSavedBillsInTrend = invoiceReady && invoices.any((invoice) =>
        !invoice.issuedAt.toLocal().isBefore(savedBillDays.first) && invoice.issuedAt.toLocal().isBefore(periodEnd));
      final previousStart = DateTime(trendDay.year, trendDay.month, trendDay.day - 1);
      // Calendar-local same-clock cutoff, not a full yesterday against a partial today.
      final previousEnd = DateTime(periodEnd.year, periodEnd.month, periodEnd.day - 1,
        periodEnd.hour, periodEnd.minute, periodEnd.second, periodEnd.millisecond, periodEnd.microsecond);
      final previousBilled = invoiceReady ? invoices.where((invoice) {
        final at = invoice.issuedAt.toLocal();
        return !at.isBefore(previousStart) && at.isBefore(previousEnd);
      }).fold<int>(0, (sum, invoice) => sum + invoice.payableMinor) : null;
      final financeReady = finance != null && finance.valid &&
          finance.historyComplete && !session.workspaceFinanceStale &&
          !finance.asOf.isAfter(DateTime.now());
      // The summary is authoritative; possibly partial rows only establish
      // whether the existing register has a relevant record to review.
      final hasDuesToReview = financeReady &&
          !session.workspaceFinanceUsesLegacyReview && finance.duesMinor > 0 &&
          finance.payments.any((p) => p.dueMinor > 0 && const {
            WorkspacePaymentState.unpaid, WorkspacePaymentState.partPaid,
          }.contains(p.state));
      final settlementIssues = financeReady && !session.workspaceFinanceUsesLegacyReview
          ? finance.payouts.where((p) => const {
              WorkspacePayoutState.failed, WorkspacePayoutState.held,
              WorkspacePayoutState.unknown,
            }.contains(p.state)).toList()
          : <WorkspacePayoutRecord>[];
      final pendingRefunds = financeReady && !session.workspaceFinanceUsesLegacyReview
          ? finance.payments.where((p) => p.state == WorkspacePaymentState.refundPending).toList()
          : <WorkspacePaymentRecord>[];
      // A local order list is not proof of complete remote order coverage.
      final hasOnlinePositions = session.workspaceOperationalFeedAvailable ||
          session.workspaceOrders.any((order) => order.isOperationalProjection);
      final orderCoverage = !hasOnlinePositions
          ? 'Saved orders only · online coverage may be incomplete'
          : session.workspaceOperationalFeedBusy
          ? 'Updating online orders · partial coverage'
          : session.workspaceOperationalFeedError != null
          ? (session.workspaceOrders.isEmpty ? 'Online order source unavailable · not zero'
              : 'Online refresh unavailable · retained partial records')
          : 'Known local and online orders · partial coverage';
      final seenOrderIds = <String>{};
      final openOrders = session.workspaceOrders.where((order) =>
        seenOrderIds.add(order.id) && !order.isClosed &&
        !const {'Delivered', 'Collected', 'Rejected'}.contains(order.stage)).toList();
      final orderNow = DateTime.now();
      final acceptanceExpired = openOrders.where((order) =>
        order.stage == 'Confirmed' && order.actionDeadline != null &&
        !order.actionDeadline!.isAfter(orderNow)).toList();
      final awaitingAcceptance = openOrders.where((order) =>
        order.stage == 'Confirmed' && (order.actionDeadline == null ||
        order.actionDeadline!.isAfter(orderNow))).toList();
      final fulfilmentOrders = openOrders.where((order) =>
        const {'Preparing', 'Ready', 'Ready for pickup'}.contains(order.stage)).toList();
      final overdueOrders = fulfilmentOrders.where((order) =>
        order.fulfilmentDeadline != null &&
        !order.fulfilmentDeadline!.isAfter(orderNow)).toList();
      final missingTargets = fulfilmentOrders.where((order) => order.fulfilmentDeadline == null).length;
      final orderAttention = overdueOrders.isNotEmpty ? overdueOrders.first
        : acceptanceExpired.isNotEmpty ? acceptanceExpired.first
        : awaitingAcceptance.isNotEmpty ? awaitingAcceptance.first : null;
      final orderAttentionTitle = overdueOrders.isNotEmpty
        ? '${overdueOrders.length} past fulfilment time · review orders'
        : acceptanceExpired.isNotEmpty
        ? 'Acceptance update pending · ${acceptanceExpired.length}'
        : '${awaitingAcceptance.length} awaiting acceptance';
      final visibilityProducts = stockReady
          ? products.where((p) => p.available &&
              (p.stockMode == WorkspaceStockMode.availabilityOnly || p.stock > 0) && !p.published).toList()
          : <WorkspaceCatalogueItem>[];
      final visibilityReview = visibilityProducts.length;
      final visibilityOff = visibilityProducts.where((p) => !p.publicListing).length;
      final visibilityDetails = visibilityProducts.where((p) => p.publicListing &&
          (!p.customerProductFieldsComplete || p.catalogueFactsRequireReview)).length;
      final visibilityPhotos = visibilityReview - visibilityOff - visibilityDetails;
      final visibilityReasons = [
        if (visibilityOff > 0) '$visibilityOff visibility off',
        if (visibilityDetails > 0) '$visibilityDetails need product details checked',
        if (visibilityPhotos > 0) '$visibilityPhotos need photo review',
      ].join(' · ');
      final missingCosts = stockReady
          ? products.where((p) => p.stockMode == WorkspaceStockMode.exactQuantity &&
              p.stock > 0 && p.purchasePriceMinor <= 0).length : 0;
      final receiptPurchases = session.workspacePurchases.where(_homeReceiptNeedsReview).toList();
      final stockAlerts = <_OperatingAttention>[
        if (session.workspaceCommodityPriceAttentionProducts.isNotEmpty)
          _OperatingAttention(id: 'commodity-price-refresh',
            title: '${productCount(session.workspaceCommodityPriceAttentionProducts.length)} · confirm trade prices',
            detail: '${session.workspaceCommodityPriceAttentionProducts.take(3).map((p) => p.title).join(', ')}. Price validity is ending, confirmation is pending, or buyers have requested a refresh.',
            action: 'Review trade prices in Stock', onTap: widget.onStock,
            color: _OperatingPalette.warning, expanded: _expandedCategories.contains('stock')),
        if (session.workspaceCommodityPriceAttentionError != null)
          _OperatingAttention(id: 'commodity-price-check-unavailable', title: 'Trade price reminders need checking',
            detail: session.workspaceCommodityPriceAttentionError!, action: 'Check price reminders',
            onTap: () { if (widget.reviewCurrent?.call() != false) unawaited(session.loadWorkspaceCommodityPriceAttention(force: true)); },
            color: _OperatingPalette.warning, expanded: _expandedCategories.contains('stock')),
        if (unavailable > 0)
          _OperatingAttention(id: 'unavailable',
            title: '${productCount(unavailable)} unavailable',
            detail: 'Check quantity or availability in Stock.',
            action: 'Review stock', onTap: widget.onStock,
            color: _OperatingPalette.error, expanded: _expandedCategories.contains('stock')),
        if (replenish > 0)
          _OperatingAttention(id: 'replenish',
            title: '${productCount(replenish)} running low',
            detail: 'At or below the product’s alert level. Review replenishment.',
            action: 'Review stock', onTap: widget.onStock,
            color: _OperatingPalette.warning, expanded: _expandedCategories.contains('stock')),
        if (belowCost > 0)
          _OperatingAttention(id: 'price',
            title: '${productCount(belowCost)} priced below cost',
            detail: 'Check selling prices against purchase prices. Not a realised loss.',
            action: 'Review prices in Stock', onTap: widget.onStock,
            color: _OperatingPalette.warning, expanded: _expandedCategories.contains('stock')),
        if (visibilityReview > 0)
          _OperatingAttention(id: 'visibility',
            title: '${productCount(visibilityReview)} · review public visibility',
            detail: '$visibilityReasons. Review in Stock; online status unverified.',
            action: 'Review products in Stock', onTap: widget.onStock,
            color: MoolColors.navy, expanded: _expandedCategories.contains('stock')),
        if (missingCosts > 0)
          _OperatingAttention(id: 'cost-details',
            title: '${productCount(missingCosts)} · purchase cost needed for valuation',
            detail: 'Enter the actual purchase price in the product editor.',
            action: 'Review costs in Stock', onTap: widget.onStock,
            color: MoolColors.navy, expanded: _expandedCategories.contains('stock')),
      ];
      // Freeze the same eligible primitive values as the canvas, not widgets or
      // a second query/calculation owner. Device history is not remote coverage.
      StoreAnalyticsReportRow exportRow(String area, String label, String value,
          String meaning, {bool period = false, DateTime? asOf}) => StoreAnalyticsReportRow(
        area: area, label: label, value: value == '—' ? 'Unavailable' : value,
        basis: period ? 'Selected period activity' : 'Current position',
        source: area == 'Stock' ? 'Saved inventory; captured at export, not a historical stock balance'
          : area == 'Sales' && label == 'Billed' || label == 'Invoice count' || label == 'Average bill'
          ? 'Saved invoices; cutoff ${periodEnd.toUtc().toIso8601String()}'
          : area == 'Orders' ? (hasOnlinePositions
              ? 'Saved local records and loaded online positions; captured at export'
              : 'Orders saved on this phone; captured at export')
          : 'Saved finance${asOf == null ? '; as-of unavailable' : '; as of ${asOf.toUtc().toIso8601String()}'}',
        coverage: value == '—' ? 'Unavailable; incomplete source' : area == 'Orders'
          ? (hasOnlinePositions ? '$orderCoverage; current positions, not selected-period activity'
              : 'Partial saved records; online coverage unverified') : 'Saved device records only; backend coverage unverified',
        meaning: meaning);
      final exportRows = <StoreAnalyticsReportRow>[
        exportRow('Sales', 'Billed', money(billed), 'INR; before returns', period: true),
        exportRow('Sales', 'Collected', money(collected), 'INR; customer receipts before refunds', period: true, asOf: collectionsReady ? finance.asOf : null),
        exportRow('Sales', 'Invoice count', count(invoiceReady ? todayInvoices.length : null), 'Saved invoices, not visitors', period: true),
        exportRow('Sales', 'Average bill', money(billed != null && todayInvoices.isNotEmpty ? (billed / todayInvoices.length).round() : null), 'INR; billed value divided by invoice count; no bills means unavailable', period: true),
        exportRow('Sales', 'Returns', count(returnReasons?.values.fold<int>(0, (sum, row) => sum + row.count)), 'Confirmed returns, not units or refunds', period: true, asOf: collectionsReady ? finance.asOf : null),
        exportRow('Sales', 'Return credit', money(returnReasons?.values.fold<int>(0, (sum, row) => sum + row.creditMinor)), 'INR; credit against original bills, not cash refunded', period: true, asOf: collectionsReady ? finance.asOf : null),
        if (returnReasons != null) for (final reason in returnReasons.entries)
          exportRow('Sales', WorkspaceCustomerReturn.reasonLabels[reason.key] ?? 'Reason not categorised', money(reason.value.creditMinor), '${reason.value.count} confirmed returns; credited value, not cash refund', period: true, asOf: finance?.asOf),
        for (final day in savedBillSeries)
          StoreAnalyticsReportRow(area: 'Saved bill trend - separate 7-day window',
            label: '${day.$1.year}-${day.$1.month}-${day.$1.day}', value: money(day.$2),
            basis: 'Independent 7-day series ${savedBillDays.first.toUtc().toIso8601String()} to ${periodEnd.toUtc().toIso8601String()}',
            source: 'Saved invoices; before returns', coverage: 'Saved device invoice history only; backend coverage unverified',
            meaning: 'Daily INR; independent trend window, not selected-period total'),
        if (!invoiceReady) const StoreAnalyticsReportRow(area: 'Saved bill trend - separate 7-day window',
          label: 'Saved bill history', value: 'Unavailable', basis: 'Independent 7-day series',
          source: 'Saved invoices unavailable', coverage: 'Unknown; not zero', meaning: 'No trend inferred'),
        if (previousBilled != null) StoreAnalyticsReportRow(area: 'Saved bill comparison',
          label: 'Previous day at comparable cutoff', value: money(previousBilled),
          basis: '${previousStart.toUtc().toIso8601String()} to ${previousEnd.toUtc().toIso8601String()}',
          source: 'Saved invoices; before returns', coverage: 'Saved device invoice history only; backend coverage unverified',
          meaning: 'INR; same-clock previous day, not a full day versus a partial day'),
        exportRow('Stock', 'Saved products', count(stockReady ? products.length : null), 'Product count, not units'),
        exportRow('Stock', 'Low stock', count(stockReady ? session.workspaceLowStockCount : null), 'Products using their saved alert levels'),
        exportRow('Stock', 'Unavailable products', count(stockReady ? unavailable : null), 'Product count, not units'),
        exportRow('Stock', 'Available products', count(stockReady ? products.length - unavailable : null), 'Product count, not units'),
        exportRow('Stock', 'Stock cost', money(cost), 'INR; saved purchase prices; not audited valuation'),
        exportRow('Stock', 'Stock sale value', money(resale), 'INR; potential selling value, not received money'),
        exportRow('Stock', 'Potential gross profit', money(cost != null && resale != null ? resale - cost : null), 'INR; before taxes, discounts and expenses; not earned profit'),
        exportRow('Orders', 'Open orders', count(session.workspaceOrders.isEmpty ? null : openOrders.length), 'Known open orders; not all online orders'),
        exportRow('Orders', 'Awaiting acceptance', count(session.workspaceOrders.isEmpty ? null : awaitingAcceptance.length), 'Known orders; expired acceptance excluded'),
        exportRow('Orders', 'Fulfilment overdue', count(session.workspaceOrders.isEmpty ? null : overdueOrders.length), 'Known orders past recorded deadline; missing deadlines excluded'),
        exportRow('Money', 'Customer dues', money(financeReady ? finance.duesMinor : null), 'INR; money owed, not cash', asOf: financeReady ? finance.asOf : null),
        exportRow('Money', 'Supplier dues', '—', 'Complete supplier population unavailable; not zero'),
        exportRow('Money', 'Settlement available', money(financeReady ? finance.availableMinor : null), 'INR; MoolSocial settlement, not bank balance', asOf: financeReady ? finance.asOf : null),
        exportRow('Money', 'Settlement on hold', money(financeReady ? finance.heldMinor : null), 'INR; held, not available for payout', asOf: financeReady ? finance.asOf : null),
        exportRow('Working capital', 'Cash tied up', '—', 'Compatible complete balances unavailable'),
        exportRow('Working capital', 'Stock days', '—', 'Complete historical quantities and turnover unavailable'),
      ];
      return _StoreAnalyticsPresentation(
        session: session, initialReport: widget.initialReport, reviewCurrent: widget.reviewCurrent,
        exportRows: List.unmodifiable(exportRows),
        periodDays: _periodDays, periodStart: periodStart, periodEnd: periodEnd,
        onPeriod: (days) {
          if (widget.reviewCurrent?.call() == false) return;
          if (!const {1, 7, 30}.contains(days)) return;
          setState(() { _periodDays = days; _periodEnd = DateTime.now(); if (widget.readOnlyPreparedSource) _today = DateUtils.dateOnly(_periodEnd); });
          _rememberPeriod(explicitNative: true);
        },
        onRefresh: () {
          if (widget.reviewCurrent?.call() == false) return;
          setState(() { _periodEnd = DateTime.now(); if (widget.readOnlyPreparedSource) _today = DateUtils.dateOnly(_periodEnd); });
          _rememberPeriod(explicitNative: true);
          _loadOperationalPositions(refresh: true);
        },
        scrollController: widget.scrollController,
            overviewVisuals: {
              if (stockReady) 'stock': _StockAvailabilityGraphic(
                available: products.length - unavailable, unavailable: unavailable, overview: true),
              if (invoiceReady) 'sales': _AnalyticsOverviewTrend(series: savedBillSeries),
            },
            compactVisuals: {
          if (stockReady) 'stock': _StockAvailabilityGraphic(
            available: products.length - unavailable, unavailable: unavailable, compact: true),
          if (invoiceReady) 'sales': _SavedBillGraphic(series: savedBillSeries, compact: true, hasSavedBills: hasSavedBillsInTrend,
            todayMinor: savedBillSeries.last.$2, previousMinor: previousBilled!),
        },
        detailVisuals: {
          'stock': stockReady ? Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
            if (cost != null && resale != null) ...[
              const SizedBox(height: 12), _StockValueGraphic(cost: cost, sale: resale),
            ],
            const SizedBox(height: 12),
            _StockAvailabilityGraphic(available: products.length - unavailable, unavailable: unavailable),
          ]) :
            const Text('Stock distribution unavailable · load saved Stock first'),
          'sales': invoiceReady ? _SavedBillGraphic(series: savedBillSeries, hasSavedBills: hasSavedBillsInTrend,
            todayMinor: savedBillSeries.last.$2, previousMinor: previousBilled!) :
            const Text('Saved-bill trend unavailable · recover Sales history first',
              key: Key('analytics-sales-trend-unavailable')),
        },
        sections: [
                const Text('Store overview', style: TextStyle(fontSize: 14,
                  fontWeight: FontWeight.w700, color: MoolColors.navy)),
                const SizedBox(height: 4),
                const Tooltip(
                  message: 'Saved on this phone, not live across devices. A last-updated time is not available for the complete overview. Dated balances show their own date.',
                  child: Text('Phone records · update time unavailable',
                    key: Key('store-overview-freshness'),
                    style: TextStyle(fontSize: 11, color: _OperatingPalette.secondary)),
                ),
                const SizedBox(height: 4),
                if (session.workspaceDashboardState !=
                    WorkspaceDashboardState.ready)
                  _DashboardSyncBanner(session: session),
                _OperatingCategory(id: 'sales', title: 'Sales & collections',
                  expanded: _expandedCategories.contains('sales'),
                  onToggle: () => _toggleCategory('sales'),
                  primaryIds: const ['billed', 'collections'], children: [
                _OperatingMetric(
                  id: 'billed',
                  onTap: widget.onSales,
                  label: 'Billed $periodLabel',
                  value: money(billed),
                  detail: invoiceReady
                      ? '${todayInvoices.length} invoices · before returns'
                      : 'Sales history is not available yet',
                ),
                _OperatingMetric(
                  id: 'collections',
                  label: 'Collected $periodLabel',
                  value: money(collected),
                  detail: collectionsReady
                      ? 'Customer payments received · before refunds'
                      : 'Complete payment history is not available yet',
                ),
                _OperatingMetric(
                  id: 'invoice-count',
                  label: 'Invoices $periodLabel',
                  value: count(invoiceReady ? todayInvoices.length : null),
                  detail: invoiceReady
                      ? 'Invoices recorded $periodLabel. Open Sales to review.'
                      : 'Sales history is not available yet',
                  onTap: widget.onSales,
                ),
                _OperatingMetric(
                  id: 'average-bill', label: 'Average bill $periodLabel',
                  value: money(billed != null && todayInvoices.isNotEmpty
                    ? (billed / todayInvoices.length).round() : null),
                  detail: !invoiceReady ? 'Sales history is not available yet'
                    : todayInvoices.isEmpty ? 'No bills saved $periodLabel'
                    : 'Selected-period billed value divided by invoice count · before returns; not spend per visitor',
                ),
                _OperatingMetric(
                  id: 'return-count', label: 'Returns $periodLabel',
                  value: count(returnReasons?.values.fold<int>(0, (sum, row) => sum + row.count)),
                  detail: returnReasons == null ? 'Complete return history is not available yet'
                    : 'Confirmed returns, not returned units or refunds',
                ),
                _OperatingMetric(
                  id: 'return-credit', label: 'Return credit $periodLabel',
                  value: money(returnReasons?.values.fold<int>(0, (sum, row) => sum + row.creditMinor)),
                  detail: 'Credit against original bills, not money refunded',
                ),
                if (returnReasons != null)
                  for (final entry in returnReasons.entries)
                    _OperatingMetric(
                      id: 'return-reason-${entry.key}',
                      label: WorkspaceCustomerReturn.reasonLabels[entry.key] ?? 'Reason not categorised',
                      value: money(entry.value.creditMinor),
                      detail: '${entry.value.count} confirmed ${entry.value.count == 1 ? 'return' : 'returns'} $periodLabel · credited value',
                    ),
                ]),
                _OperatingCategory(id: 'stock', title: 'Stock & visibility',
                  expanded: _expandedCategories.contains('stock'),
                  onToggle: () => _toggleCategory('stock'),
                  primaryIds: const ['stock-cost', 'low-stock'],
                  alertCount: stockAlerts.length,
                  attention: stockAlerts.isEmpty ? null : stockAlerts.first,
                  children: [
                _OperatingMetric(
                  id: 'skus',
                  onTap: widget.onStock,
                  label: 'Saved products',
                  value: count(stockReady ? products.length : null),
                  detail: 'Number of saved products, not individual units',
                ),
                _OperatingMetric(
                  id: 'low-stock',
                  alertColor: stockReady && session.workspaceLowStockCount > 0
                      ? _OperatingPalette.warning
                      : null,
                  label: 'Low stock',
                  value: count(
                    stockReady ? session.workspaceLowStockCount : null,
                  ),
                  detail: 'Using each product’s stock alert level',
                ),
                _OperatingMetric(
                  id: 'out-of-stock',
                  alertColor: stockReady && session.workspaceOutOfStockCount > 0
                      ? _OperatingPalette.error
                      : null,
                  label: 'Out of stock',
                  value: count(
                    stockReady ? session.workspaceOutOfStockCount : null,
                  ),
                  detail: 'Unavailable products',
                ),
                const _OperatingSection('Current stock value'),
                _OperatingMetric(
                  id: 'stock-cost',
                  label: 'Money in stock',
                  value: money(cost),
                  detail: costsKnown && cost == null
                      ? 'Current stock value exceeds the supported amount range.'
                      : costsKnown
                      ? 'Current stock at saved purchase prices · not an audited inventory valuation'
                      : 'Exact stock quantities and purchase prices are needed',
                ),
                _OperatingMetric(
                  id: 'stock-sale',
                  label: 'Stock sale value',
                  value: money(resale),
                  detail: pricesKnown && resale == null
                      ? 'Current stock value exceeds the supported amount range.'
                      : pricesKnown
                      ? 'Potential sales value · not money received'
                      : 'Exact stock quantities and selling prices are needed',
                ),
                _OperatingMetric(
                  id: 'stock-spread',
                  label: 'Potential gross profit*',
                  value: money(
                    cost != null && resale != null ? resale - cost : null,
                  ),
                  detail:
                      'Selling value less purchase value · before tax, discounts and expenses',
                ),
                ...stockAlerts.skip(1),
                for (final state in [WorkspaceReceiptState.awaiting, WorkspaceReceiptState.partial, WorkspaceReceiptState.disputed])
                  if (receiptPurchases.any((p) => p.receiptState == state))
                    _OperatingAttention(id: 'receipt-${state.name}',
                      title: '${receiptPurchases.where((p) => p.receiptState == state).length} ${state == WorkspaceReceiptState.awaiting ? 'delivered · check receipt' : state == WorkspaceReceiptState.partial ? 'part received · review remaining items' : 'under receipt review'}',
                      detail: 'Open ${receiptPurchases.firstWhere((p) => p.receiptState == state).orderId} · ${receiptPurchases.firstWhere((p) => p.receiptState == state).supplierName}',
                      action: 'Review purchase', color: _OperatingPalette.warning, expanded: true,
                      onTap: () => widget.onPurchase(receiptPurchases.firstWhere((p) => p.receiptState == state))),
                if (!stockReady)
                  const Text('Stock details are unavailable. Please check Stock.',
                    style: TextStyle(fontSize: 12, color: _OperatingPalette.secondary)),
                if (stockReady && stockAlerts.isEmpty)
                  const Text('No stock or listing-readiness alerts in saved inventory.',
                    style: TextStyle(fontSize: 11, color: _OperatingPalette.secondary)),
                const Text('Online views, carts, repeat purchases and forecasts need verified activity and more history.',
                  style: TextStyle(fontSize: 11, color: _OperatingPalette.secondary)),
                ]),
                _OperatingCategory(id: 'orders', title: 'Orders & fulfilment',
                  expanded: _expandedCategories.contains('orders'),
                  onToggle: () => _toggleCategory('orders'),
                  primaryIds: const ['recorded-open-orders', 'overdue-fulfilment'],
                  alertCount: overdueOrders.length + acceptanceExpired.length + awaitingAcceptance.length,
                  coverage: orderCoverage,
                  attention: orderAttention == null ? null :
                    _OperatingAttention(id: 'order-attention', title: orderAttentionTitle,
                      detail: 'Review order ${orderAttention.id}. ${acceptanceExpired.length} acceptance updates pending; $missingTargets preparing or ready orders have no recorded fulfilment deadline.',
                      action: 'Review order', expanded: _expandedCategories.contains('orders'),
                      color: _OperatingPalette.warning,
                      onTap: () => context.go(Uri(path: '/app/retailer/orders',
                        queryParameters: {'order': orderAttention.id}).toString())),
                  children: [
                _OperatingMetric(
                  id: 'recorded-open-orders', label: 'Open orders',
                  value: count(session.workspaceOrders.isEmpty ? null : openOrders.length),
                  detail: hasOnlinePositions
                    ? 'Saved local records and loaded online positions only. Online orders may not all be included.'
                    : 'Open orders saved on this phone only. Online orders may not all be included.',
                  onTap: widget.onOrders,
                ),
                _OperatingMetric(
                  id: 'awaiting-acceptance', label: 'Awaiting acceptance',
                  value: count(session.workspaceOrders.isEmpty ? null : awaitingAcceptance.length),
                  detail: '${hasOnlinePositions ? 'Known' : 'Saved'} confirmed orders awaiting acceptance. Expired acceptance windows are excluded and need a status update.',
                  onTap: widget.onOrders,
                ),
                _OperatingMetric(
                  id: 'overdue-fulfilment', label: 'Fulfilment overdue',
                  value: count(session.workspaceOrders.isEmpty ? null : overdueOrders.length),
                  detail: '${hasOnlinePositions ? 'Known' : 'Saved'} preparing or ready orders past their recorded fulfilment deadline. Orders without a deadline are not counted. This is not a live delivery-status feed.',
                  alertColor: overdueOrders.isEmpty ? null : _OperatingPalette.error,
                  onTap: widget.onOrders,
                ),
                if (session.workspaceOrders.isEmpty)
                  Text(hasOnlinePositions ? 'No loaded order records · online coverage incomplete'
                    : 'No saved order records · online coverage unavailable',
                    style: const TextStyle(fontSize: 11, color: _OperatingPalette.secondary)),
                if (orderAttention == null && missingTargets > 0)
                  Text('$missingTargets preparing or ready orders have no recorded fulfilment deadline.',
                    style: const TextStyle(fontSize: 11, color: _OperatingPalette.secondary)),
                ]),
                _OperatingCategory(id: 'money', title: 'Receivables & payables',
                  expanded: _expandedCategories.contains('money'),
                  onToggle: () => _toggleCategory('money'),
                  primaryIds: const ['customer-dues', 'payables'],
                  coverage: financeReady
                    ? 'Balances as of · ${MaterialLocalizations.of(context).formatShortDate(finance.asOf.toLocal())}'
                    : 'Balances unavailable · not zero',
                  children: [
                _OperatingMetric(
                  id: 'customer-dues', label: 'Receivables',
                  value: money(financeReady ? finance.duesMinor : null),
                  detail: 'Money customers owe you · not cash received. Complete customer balances are required.',
                  onTap: hasDuesToReview ? widget.onDues : null,
                ),
                if (financeReady) ...[
                  _OperatingMetric(
                    id: 'settlement-available', label: 'Settlement available',
                    value: money(finance.availableMinor),
                    detail: 'Available for MoolSocial settlement · not a bank balance',
                    onTap: widget.onSettlement,
                  ),
                  _OperatingMetric(
                    id: 'settlement-held', label: 'Settlement on hold',
                    value: money(finance.heldMinor),
                    detail: 'Money held by MoolSocial · not yet available for payout',
                  ),
                  Text('Balances as of · ${MaterialLocalizations.of(context).formatShortDate(finance.asOf.toLocal())} · ${MaterialLocalizations.of(context).formatTimeOfDay(TimeOfDay.fromDateTime(finance.asOf.toLocal()))}',
                    style: const TextStyle(fontSize: 11, color: _OperatingPalette.secondary)),
                ] else
                  const Text('Customer dues and settlement balances are not available yet.',
                    key: Key('store-insights-finance-unavailable'),
                    style: TextStyle(fontSize: 12, color: _OperatingPalette.secondary)),
                const _OperatingMetric(
                  id: 'payables', label: 'Payables', value: '—',
                  detail: 'Money owed to suppliers. A complete set of supplier balances is not available yet; a few saved purchase bills cannot establish the total.',
                ),
                if (hasDuesToReview)
                  _OperatingAttention(id: 'customer-dues',
                    title: 'Review unpaid customer payments',
                    detail: 'Check unpaid and part-paid records. A balance due does not mean overdue.',
                    action: 'Collect dues', onTap: widget.onDues,
                    color: MoolColors.navy, expanded: true),
                if (pendingRefunds.isNotEmpty)
                  _OperatingAttention(id: 'pending-refunds',
                    title: '${pendingRefunds.length} recorded ${pendingRefunds.length == 1 ? 'refund awaits' : 'refunds await'} confirmation',
                    detail: 'Review ${pendingRefunds.first.orderId} · ${pendingRefunds.first.customerName}. Not confirmed as refunded.',
                    action: 'Review payment', color: _OperatingPalette.warning, expanded: true,
                    onTap: () => widget.onReviewFinance((
                      accountScope: finance!.accountScope, workspaceId: finance.workspaceId,
                      orderId: pendingRefunds.first.orderId, customerId: pendingRefunds.first.customerId,
                      payoutId: null, operationId: null,
                    ))),
                if (settlementIssues.isNotEmpty)
                  _OperatingAttention(id: 'settlement-issues',
                    title: '${settlementIssues.length} recorded ${settlementIssues.length == 1 ? 'settlement needs' : 'settlements need'} review',
                    detail: [
                      for (final state in [WorkspacePayoutState.failed, WorkspacePayoutState.held, WorkspacePayoutState.unknown])
                        if (settlementIssues.any((p) => p.state == state))
                          '${settlementIssues.where((p) => p.state == state).length} ${state == WorkspacePayoutState.failed ? 'failed' : state == WorkspacePayoutState.held ? 'on hold' : 'awaiting an update'}',
                    ].join(' · '),
                    action: 'Review MoolSocial settlement', onTap: widget.onSettlement,
                    color: _OperatingPalette.warning, expanded: true),
                ]),
                _OperatingCategory(id: 'capital', title: 'Working capital',
                  expanded: _expandedCategories.contains('capital'),
                  onToggle: () => _toggleCategory('capital'),
                  primaryIds: const ['trade-cash', 'stock-days'],
                  coverage: 'Incomplete history · — means unavailable', children: [
                const _OperatingMetric(
                  id: 'trade-cash', label: 'Cash tied up', value: '—',
                  detail: 'Money in stock + customer receivables − supplier payables. This is trade cash tied up, not full accounting working capital. Complete matching balances are needed.',
                ),
                const _OperatingMetric(
                  id: 'stock-days', label: 'Stock days', value: '—',
                  detail: 'Estimated days current stock will last. Complete sales history and exact product quantities are needed. A partial order list cannot establish Store-wide stock days.',
                ),
                const Text(
                  'Payables & cash tied up: supplier balances incomplete. Stock days: not enough history yet.',
                  key: Key('store-working-capital-coverage'),
                  style: TextStyle(fontSize: 11, color: _OperatingPalette.secondary),
                ),
                const Text(
                  'Credit sales / purchases · Not available yet',
                  style: TextStyle(fontSize: 11, color: _OperatingPalette.secondary),
                ),
                const Text(
                  'Collection days / payment days / cash cycle · Not enough history yet',
                  style: TextStyle(fontSize: 11, color: _OperatingPalette.secondary),
                ),
                ]),
        ],
      );
    },
  );
}

String _analyticsReportTitle(String report) => switch (report) {
  'public' => 'Public Store',
  'journey' => 'Customer journey',
  'operations' => 'Store operations',
  'supply' => 'Buy / Restock',
  'receiving' => 'Purchases & goods received',
  'orders' => 'Customer orders',
  'stock' => 'Stock',
  'sales' => 'Sales & collections',
  'money' => 'Money & dues',
  _ => 'Overview',
};

Widget _analyticsPeriodPicker(int days, ValueChanged<int> onChanged) => PopupMenuButton<int>(
  key: const Key('store-analytics-period-picker'), tooltip: 'Choose reporting period',
  initialValue: days, onSelected: onChanged,
  itemBuilder: (_) => [for (final value in const [1, 7, 30])
    PopupMenuItem<int>(value: value, child: Text(value == 1 ? 'Today' : 'Last $value days'))],
  child: ConstrainedBox(constraints: const BoxConstraints(minHeight: 48),
    child: Row(mainAxisSize: MainAxisSize.min, children: [
      const Icon(Icons.date_range_outlined, size: 16, color: MoolColors.navy),
      const SizedBox(width: 6),
      Text(days == 1 ? 'Today' : 'Last $days days',
        style: const TextStyle(fontSize: 12, fontWeight: FontWeight.w600, color: MoolColors.navy)),
      const Icon(Icons.arrow_drop_down, color: MoolColors.navy, size: 20),
    ])),
);
Widget _storeInlineBackPriority(BuildContext context, {
  required bool Function() enabled,
  required VoidCallback onBack,
  required Widget child,
}) {
  if (Router.maybeOf<Object?>(context)?.backButtonDispatcher == null) {
    return child;
  }
  return BackButtonListener(
    onBackButtonPressed: () async {
      final route = ModalRoute.of(context);
      // Leave dialogs and the launcher's local-history menu to their owners.
      if (!enabled() || route == null || !route.isCurrent || route.willHandlePopInternally) {
        return false;
      }
      onBack();
      return true;
    },
    child: child,
  );
}

/// One reporting canvas; domain expansion never starts a request or a route.
class _StoreAnalyticsPresentation extends StatefulWidget {
  const _StoreAnalyticsPresentation({
    required this.session, required this.sections, required this.periodDays,
    required this.periodStart, required this.periodEnd, required this.onPeriod,
    required this.onRefresh,
    this.compactVisuals = const {}, this.detailVisuals = const {}, this.overviewVisuals = const {},
    this.scrollController, this.exportRows = const [], this.initialReport, this.reviewCurrent,
  });
  final WorkSession session;
  final String? initialReport;
  final bool Function()? reviewCurrent;
  final int periodDays;
  final DateTime periodStart, periodEnd;
  final ValueChanged<int> onPeriod;
  final VoidCallback onRefresh;
  final List<Widget> sections;
  final Map<String, Widget> compactVisuals, detailVisuals, overviewVisuals;
  final ScrollController? scrollController;
  final List<StoreAnalyticsReportRow> exportRows;
  @override
  State<_StoreAnalyticsPresentation> createState() => _StoreAnalyticsPresentationState();
}

class _StoreAnalyticsPresentationState extends State<_StoreAnalyticsPresentation> {
  String? _expanded;
  WorkspaceAnalyticsRequest? _request;
  Future<WorkspaceAnalyticsSnapshot>? _result;
  Object? _scopeIdentity;
  final _detailKey = GlobalKey();
  final _reportHeadingKey = GlobalKey();
  final _viewportKey = GlobalKey();
  final _localScroll = ScrollController();
  ScrollController get _scroll => widget.scrollController ?? _localScroll;
  bool _contextHeader = false;
  double? _summaryOffset;
  int _transition = 0;
  bool _exportBusy = false;
  String? _exportNotice;
  bool _reportRestored = false;

  void _restoreReport() {
    final scope = widget.session.workspaceStockHistoryScope()?.key;
    if (scope == null) return;
    final saved = PageStorage.maybeOf(context)?.readState(context,
      identifier: ('analytics-report', scope));
    if (saved is! ({String? report, double? summaryOffset})) return;
    if (saved.report != null && !const {
      'public', 'journey', 'supply', 'receiving', 'orders', 'stock', 'sales', 'money',
    }.contains(saved.report)) { return; }
    if (saved.summaryOffset != null &&
        (!saved.summaryOffset!.isFinite || saved.summaryOffset! < 0)) { return; }
    _expanded = saved.report;
    _summaryOffset = saved.summaryOffset;
  }

  void _rememberReport() {
    final scope = widget.session.workspaceStockHistoryScope()?.key;
    if (scope != null) {
      PageStorage.maybeOf(context)?.writeState(context,
      (report: _expanded, summaryOffset: _summaryOffset),
      identifier: ('analytics-report', scope));
    }
  }

  Future<void> _exportAnalytics(WorkspaceAnalyticsSnapshot? provider) async {
    final request = _request;
    if (widget.reviewCurrent?.call() == false || _exportBusy || request == null) { return; }
    final session = widget.session;
    bool current() => widget.reviewCurrent?.call() != false && mounted && identical(_request, request) &&
      identical(widget.session, session) && session.analyticsRequest(
        start: request.start, end: request.end)?.sameScope(request) == true;
    setState(() { _exportBusy = true; _exportNotice = null; });
    try {
    final capturedAt = DateTime.now();
    final eligible = provider != null && provider.usableFor(request, capturedAt) &&
      provider.state == WorkspaceAnalyticsState.verified;
    final rows = <StoreAnalyticsReportRow>[...widget.exportRows];
    for (final area in const ['public', 'journey', 'supply', 'receiving']) {
      for (final definition in _StoreAnalyticsProviderReportState.definitions(area)) {
        final metric = eligible ? provider.metrics.where((m) => m.id == definition.id).firstOrNull : null;
        final percentage = const {'order-conversion', 'cart-dropoff'}.contains(definition.id);
        final known = storeAnalyticsMetricEligible(definition.id, metric);
        if (definition.id == 'journey-checkout' && !known) { continue; }
        rows.add(StoreAnalyticsReportRow(area: _analyticsReportTitle(area),
          label: definition.label,
          value: known ? percentage ? '${metric!.value!.toStringAsFixed(1)}%' : '${_formatStoreAmount(metric!.value!.toInt())} count' : 'Unavailable',
          basis: known ? metric!.basis == WorkspaceAnalyticsBasis.periodActivity
            ? 'Selected period activity' : 'Current position' : 'Basis unverified',
          source: known ? '${metric!.source}; as of ${metric.asOf!.toUtc().toIso8601String()}' : 'Report source not connected or eligible',
          coverage: known ? '${metric!.coverage.name}; provider records ${provider!.coveredFrom!.toUtc().toIso8601String()} to ${provider.coveredUntil!.toUtc().toIso8601String()}' : 'Unknown; not zero',
          meaning: _StoreAnalyticsProviderReportState.metricGuide(definition.id, definition.guide, metric)));
      }
    }
    for (final group in const [
      (id: 'discovery-sources', title: 'How customers found you', dimension: WorkspaceAnalyticsDimension.discoverySource),
      (id: 'broad-locations', title: 'Customer areas', dimension: WorkspaceAnalyticsDimension.broadLocation),
      (id: 'most-viewed-products', title: 'Most-viewed products', dimension: WorkspaceAnalyticsDimension.product),
      (id: 'products-without-orders', title: 'Products viewed without orders', dimension: WorkspaceAnalyticsDimension.product),
    ]) {
      final data = eligible ? provider.breakdowns.where((r) => r.id == group.id && r.dimension == group.dimension).firstOrNull : null;
      final source = data == null ? 'Report source not connected' : '${data.source}; as of ${data.asOf.toUtc().toIso8601String()}';
      final coverage = data == null ? 'Unknown; not zero' : '${data.coverage.name}; aggregate provider records';
      if (data == null || data.rows.isEmpty) {
        rows.add(StoreAnalyticsReportRow(area: 'Public Store rankings', label: group.title,
          value: data == null ? 'Unavailable' : 'No ranked records', basis: 'Selected period activity',
          source: source, coverage: coverage, meaning: 'Aggregate rankings, not a conversion rate'));
      } else {
        for (final row in data.rows) { rows.add(StoreAnalyticsReportRow(area: 'Public Store rankings',
          label: '${group.title}: ${row.label}', value: '${_formatStoreAmount(row.count)} count',
          basis: 'Selected period activity', source: source, coverage: coverage,
          meaning: 'Aggregate ranking; provider definition, not customer identities')); }
      }
    }
    final statement = StoreAnalyticsStatement(request: request,
      storeName: session.activeWorkspace?.name ?? session.workName,
      capturedAt: capturedAt, rows: rows,
      reviewOnly: const bool.fromEnvironment('MOOLSOCIAL_UI_REVIEW_ONLY'));
      final bytes = await statement.report.generate(StoreStockExportFormat.pdf);
      if (!current()) { return; }
      final saved = await saveStoreStockFile(bytes, statement.fileName, StoreStockExportFormat.pdf);
      if (current()) setState(() => _exportNotice = saved ? 'Analytics PDF saved.' : 'Download cancelled.');
    } catch (error) {
      if (current()) { setState(() => _exportNotice = error is FormatException
        ? error.message : 'Could not save analytics. Check your files before retrying.'); }
    } finally {
      if (mounted) setState(() => _exportBusy = false);
    }
  }

  @override
  void dispose() { _localScroll.dispose(); super.dispose(); }

  void _checkContextHeader() {
    final detail = _detailKey.currentContext?.findRenderObject();
    final viewport = _viewportKey.currentContext?.findRenderObject();
    if (detail is! RenderBox || viewport is! RenderBox || !detail.attached || !viewport.attached) return;
    final top = detail.localToGlobal(Offset.zero).dy - viewport.localToGlobal(Offset.zero).dy;
    final heading = _reportHeadingKey.currentContext?.findRenderObject();
    final headingGone = heading is RenderBox && heading.attached &&
      heading.localToGlobal(Offset(0, heading.size.height)).dy <= viewport.localToGlobal(Offset.zero).dy;
    final show = _expanded != null && headingGone && top + detail.size.height > 48;
    if (show != _contextHeader && mounted) setState(() => _contextHeader = show);
  }

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    if (_reportRestored) return;
    _reportRestored = true;
    if (widget.initialReport != null) _expanded = widget.initialReport; else _restoreReport();
    _load();
  }

  void _load() {
    if (widget.reviewCurrent?.call() == false) return;
    _scopeIdentity = widget.session.workspaceStockHistoryScope()?.key ?? widget.session.activeWorkspace?.id;
    _request = widget.session.analyticsRequest(
      start: widget.periodStart, end: widget.periodEnd);
    _result = _request == null ? null : widget.session.readWorkspaceAnalytics(_request!);
  }

  @override
  void didUpdateWidget(covariant _StoreAnalyticsPresentation oldWidget) {
    super.didUpdateWidget(oldWidget);
    final request = _request;
    final scopeChanged = oldWidget.session != widget.session || _scopeIdentity !=
      (widget.session.workspaceStockHistoryScope()?.key ?? widget.session.activeWorkspace?.id);
    final requestChanged = request != null &&
      widget.session.analyticsRequest(start: request.start, end: request.end)?.sameScope(request) != true;
    if (scopeChanged) {
      _expanded = null; _summaryOffset = null; _contextHeader = false; _transition++;
      _restoreReport();
    }
    if (scopeChanged || requestChanged || oldWidget.periodDays != widget.periodDays ||
        oldWidget.periodEnd != widget.periodEnd) {
      _exportNotice = null;
      _load();
    }
  }

  void _toggle(String id) {
    if (widget.reviewCurrent?.call() == false) return;
    final generation = ++_transition;
    final closing = _expanded == id;
    if (_expanded == null && _scroll.hasClients) _summaryOffset = _scroll.offset;
    setState(() { _expanded = closing ? null : id; _contextHeader = false; });
    _rememberReport();
    if (closing) { WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted && generation == _transition && _scroll.hasClients && _summaryOffset != null) {
        _scroll.jumpTo(_summaryOffset!.clamp(0, _scroll.position.maxScrollExtent));
      }
    }); }
    if (_expanded != null) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!mounted || generation != _transition) return;
        _scheduleReveal(generation);
      });
    }
  }

  bool get _reducedReportMotion => MoolMotion.isReduced(context) ||
      MediaQuery.accessibleNavigationOf(context);

  void _scheduleReveal(int generation) {
    WidgetsBinding.instance.addPostFrameCallback((_) {
      final target = _detailKey.currentContext;
      if (mounted && generation == _transition && _expanded != null && target != null) {
        Scrollable.ensureVisible(target, duration: _reducedReportMotion
          ? Duration.zero : const Duration(milliseconds: 180), alignment: 0);
      }
    });
    WidgetsBinding.instance.scheduleFrame();
  }

  Widget _inlineReveal(Widget child) {
    return KeyedSubtree(key: const Key('analytics-inline-reveal'),
      child: _expanded == null || _reducedReportMotion ? child : TweenAnimationBuilder<double>(key: ValueKey(_expanded),
        tween: Tween(begin: .35, end: 1),
        duration: const Duration(milliseconds: 240),
        curve: Curves.easeOutCubic, child: child,
        builder: (_, opacity, child) => Opacity(opacity: opacity, child: child)));
  }

  Widget _metrics(Iterable<_OperatingMetric> source, {bool hero = false, bool ledger = false}) => LayoutBuilder(builder: (context, box) {
    if (ledger) { return Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
      for (final metric in source) Padding(padding: const EdgeInsets.symmetric(vertical: 1),
        child: Row(children: [if (box.maxWidth >= 320 && MediaQuery.textScalerOf(context).scale(1) <= 1.3) ...[Icon(switch (metric.id) {
          'recorded-open-orders' => Icons.receipt_long_outlined,
          'awaiting-acceptance' => Icons.hourglass_empty_rounded,
          'overdue-fulfilment' => Icons.schedule_outlined,
          'settlement-held' => Icons.lock_outline,
          _ => Icons.account_balance_wallet_outlined,
        }, key: Key('analytics-status-glyph-${metric.id}'), size: 20, color: _AnalyticsChartPalette.reportAccent(_expanded ?? 'money')),
        const SizedBox(width: 10)], Expanded(child: _OperatingMetric(id: metric.id, label: metric.label, value: metric.value,
          detail: metric.detail, onTap: metric.onTap, alertColor: metric.alertColor ?? _AnalyticsChartPalette.ink,
          ledger: true, analyticsNavigation: true,
          valueFontSize: _analyticsNumberSize(context, metric.value, 20, box.maxWidth -
            (box.maxWidth >= 320 && MediaQuery.textScalerOf(context).scale(1) <= 1.3 ? 64 : 34))))])),
    ]); }
    final preferred = hero ? 24.0 : 20.0;
    var columns = box.maxWidth >= 300 && MediaQuery.textScalerOf(context).scale(1) <= 1.3 ? 2 : 1;
    for (final metric in source) {
      final measured = TextPainter(text: TextSpan(text: metric.value,
        style: TextStyle(fontSize: preferred, fontWeight: FontWeight.w700)),
        textDirection: Directionality.of(context), textScaler: MediaQuery.textScalerOf(context))..layout();
      if (measured.width + 42 > (box.maxWidth - 8) / 2) columns = 1;
      measured.dispose();
    }
    Widget cell(_OperatingMetric metric) => DecoratedBox(key: Key('analytics-metric-surface-${metric.id}'),
          decoration: BoxDecoration(
            color: metric.value == '—' ? _AnalyticsChartPalette.softSurface : null,
            gradient: metric.value == '—' ? null : _AnalyticsChartPalette.reportGradient(_expanded ?? 'stock'),
            borderRadius: _AnalyticsChartPalette.radius,
            border: Border.all(color: _AnalyticsChartPalette.border),
            boxShadow: const [_AnalyticsChartPalette.softShadow]),
          child: Padding(padding: const EdgeInsets.all(10), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            if (metric.id == 'customer-dues' || metric.id == 'payables')
              Padding(padding: const EdgeInsets.only(bottom: 6), child: Icon(
                metric.id == 'customer-dues' ? Icons.call_received : Icons.call_made,
                key: Key('analytics-balance-glyph-${metric.id}'), color: _AnalyticsChartPalette.reportAccent(metric.id == 'customer-dues' ? 'sales' : 'stock'), size: 20)),
            _OperatingMetric(
            id: metric.id, label: metric.label, value: metric.value, detail: metric.detail, analyticsNavigation: true,
            alertColor: metric.alertColor ?? (metric.value == '—' ? _AnalyticsChartPalette.secondary : _AnalyticsChartPalette.ink), onTap: metric.onTap,
            valueFontSize: _analyticsNumberSize(context, metric.value, preferred,
              (box.maxWidth - (columns - 1) * 8) / columns - 20 - (metric.onTap == null ? 0 : 14))),
            if (metric.id == 'customer-dues' && metric.value != '—' && widget.session.workspaceFinance != null)
              Text('As of ${MaterialLocalizations.of(context).formatShortDate(widget.session.workspaceFinance!.asOf.toLocal())}',
                style: const TextStyle(fontSize: 11, color: _AnalyticsChartPalette.secondary)),
          ])));
    final items = source.toList();
    if (hero && columns == 2 && items.length == 2) {
      // These non-ledger children contain no LayoutBuilder; enlarged values stack above.
      return Padding(padding: const EdgeInsets.only(top: 8), child: IntrinsicHeight(child: Row(
        crossAxisAlignment: CrossAxisAlignment.stretch, children: [
          Expanded(child: cell(items.first)), const SizedBox(width: 8), Expanded(child: cell(items.last)),
        ])));
    }
    return Padding(padding: const EdgeInsets.only(top: 8), child: Wrap(spacing: 8, runSpacing: 8, children: [
      for (final metric in items) SizedBox(width: (box.maxWidth - (columns - 1) * 8) / columns, child: cell(metric)),
    ]));
  });

  Widget _attention(Widget item) => item is _OperatingAttention
    ? Tooltip(message: item.detail, triggerMode: TooltipTriggerMode.longPress,
      child: Container(margin: const EdgeInsets.symmetric(vertical: 3),
        padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 2),
        decoration: BoxDecoration(
          border: Border(left: BorderSide(width: 3, color: item.color == MoolColors.navy
            ? _AnalyticsChartPalette.reportAccent(_expanded ?? 'stock') : item.color))),
        child: _OperatingAttention(
          id: item.id, title: item.title, detail: item.id == 'pending-refunds'
            ? 'Open the payment record to check the refund. Not confirmed as refunded.' : item.detail,
          action: item.action, color: item.color, expanded: true, onTap: item.onTap,
          analyticsAccent: _AnalyticsChartPalette.reportAccent(_expanded ?? 'stock'))))
    : item;

  @override
  Widget build(BuildContext context) {
    final categories = {for (final c in widget.sections.whereType<_OperatingCategory>()) c.id: c};
    final metrics = {for (final c in categories.values)
      for (final m in c.children.whereType<_OperatingMetric>()) m.id: m};
    final content = FutureBuilder<WorkspaceAnalyticsSnapshot>(
      key: ObjectKey(_result), future: _result, builder: (context, result) {
        final snapshot = result.data;
        final valid = snapshot != null && _request != null && snapshot.usableFor(_request!, DateTime.now());
        final verified = result.connectionState == ConnectionState.done && valid &&
          snapshot.state == WorkspaceAnalyticsState.verified;
        final loading = _result != null && (result.connectionState != ConnectionState.done ||
          valid && snapshot.state == WorkspaceAnalyticsState.loading);
        final failed = result.hasError || valid && snapshot.state == WorkspaceAnalyticsState.error;
        final status = loading ? result.connectionState == ConnectionState.done
          ? 'Report update pending' : 'Loading analytics…' : failed
          ? 'Could not load analytics' : verified
          ? '${snapshot.coverage == WorkspaceAnalyticsCoverage.complete ? 'Complete' : 'Partial'} provider coverage · ${snapshot.source}'
          : !widget.session.hasAnalyticsReader ? 'Public and supply data not connected' : 'Provider data unavailable';
        String remote(String id, {bool position = false}) {
          final metric = verified ? snapshot.metrics.where((m) => m.id == id).firstOrNull : null;
          return metric?.state == WorkspaceAnalyticsState.verified &&
            metric?.unit == WorkspaceAnalyticsUnit.count &&
            metric?.basis == (position ? WorkspaceAnalyticsBasis.currentPosition : WorkspaceAnalyticsBasis.periodActivity)
              ? '${metric!.coverage == WorkspaceAnalyticsCoverage.partial ? '~' : ''}${_formatStoreAmount(metric.value!.toInt())}' : '—';
        }
        String local(String id) => metrics[id]?.value ?? '—';
        final summaries = <String, String>{
          'public': '${remote('visitors')} visitors in period · ${remote('visible-skus', position: true)} products visible now',
          'journey': '${remote('journey-cart')} added to cart · ${remote('journey-order')} ordered',
          'supply': '${remote('supply-placed')} orders in period · ${remote('supply-delivery', position: true)} deliveries pending now',
          'receiving': '${remote('goods-without-bill', position: true)} goods without bill · ${remote('bills-without-goods', position: true)} bills awaiting goods',
          'orders': '${local('recorded-open-orders')} open · ${local('overdue-fulfilment')} overdue',
          'stock': '${local('stock-cost')} at purchase cost · ${local('low-stock')} low stock',
          'sales': '${local('billed')} billed · ${local('collections')} collected',
          'money': '${local('customer-dues')} customer dues · ${local('payables')} supplier dues',
        };
        final figures = <String, List<(String, String)>>{
          'public': [('Visitors (period)', remote('visitors')), ('Visible now', remote('visible-skus', position: true))],
          'journey': [('Added to cart', remote('journey-cart')), ('Ordered', remote('journey-order'))],
          'supply': [('Orders (period)', remote('supply-placed')), ('Delivery pending', remote('supply-delivery', position: true))],
          'receiving': [('Goods, no bill', remote('goods-without-bill', position: true)), ('Bills, no goods', remote('bills-without-goods', position: true))],
          'orders': [('Open orders', local('recorded-open-orders')), ('Overdue', local('overdue-fulfilment'))],
          'stock': [('Stock cost', local('stock-cost')), ('Low stock', local('low-stock'))],
          'sales': [('Billed', local('billed')), ('Collected', local('collections'))],
          'money': [('Customer dues', local('customer-dues')), ('Supplier dues', local('payables'))],
        };
        List<Widget> categoryDetail(String id) {
          final c = categories[id]!;
          return [
            if (c.alertCount > 0) Text(id == 'stock'
              ? '${c.alertCount} ${c.alertCount == 1 ? 'issue type' : 'issue types'}'
              : '${c.alertCount} ${c.alertCount == 1 ? 'order' : 'orders'} to review',
              key: Key('store-category-alerts-$id'), style: const TextStyle(fontSize: 12, color: _OperatingPalette.warning)),
            if (c.coverage != null && id != 'money') Text(c.coverage!,
              style: TextStyle(fontSize: 12, fontWeight: id == 'orders' ? FontWeight.w600 : FontWeight.w400)),
            _metrics(c.children.whereType<_OperatingMetric>().where((m) =>
              id == 'stock' ? m.id != 'stock-cost' && m.id != 'stock-sale' :
              id == 'sales' ? m.id != 'billed' && m.id != 'collections' :
              id == 'money' ? m.id != 'customer-dues' && m.id != 'payables' && !m.id.startsWith('settlement-') : true),
              ledger: id == 'orders' || id == 'capital'),
            if (id == 'stock') const Text(
              '* Selling value less purchase value, before tax, discounts and expenses. Not earned profit. Values use saved quantities and prices.',
              key: Key('store-analytics-stock-valuation-guide'), style: TextStyle(fontSize: 12)),
            if (c.attention != null) _attention(c.attention!),
            ...c.children.where((item) => item is! _OperatingMetric && item is! _OperatingSection).map(_attention),
          ];
        }
        final expanded = _expanded;
        WidgetsBinding.instance.addPostFrameCallback((_) { if (mounted) _checkContextHeader(); });
        final end = _request?.end ?? widget.periodEnd;
        final start = _request?.start ?? widget.periodStart;
        Widget reportHeading(String id, {bool compact = false}) => Container(
          key: Key(compact ? 'analytics-context-heading-$id' : 'analytics-report-heading-$id'),
          padding: const EdgeInsets.only(left: 8),
          decoration: BoxDecoration(gradient: _AnalyticsChartPalette.headerGradient(id),
            borderRadius: _AnalyticsChartPalette.radius,
            border: Border.all(color: _AnalyticsChartPalette.reportAccent(id).withValues(alpha: .35))),
          child: KeyedSubtree(key: compact ? null : _reportHeadingKey,
            child: LayoutBuilder(builder: (context, box) {
            final heading = Row(children: [Icon(switch (id) {
              'public' => Icons.storefront_outlined, 'journey' => Icons.route_outlined,
              'supply' => Icons.local_shipping_outlined, 'receiving' => Icons.move_to_inbox_outlined,
              'orders' => Icons.receipt_long_outlined, 'stock' => Icons.inventory_2_outlined,
              'sales' => Icons.bar_chart_rounded, _ => Icons.account_balance_wallet_outlined,
            }, size: 20, color: Colors.white), const SizedBox(width: 8),
              Expanded(child: Padding(padding: const EdgeInsets.symmetric(vertical: 8),
                child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                  Text(_analyticsReportTitle(id), semanticsLabel: compact
                    ? id == 'orders' ? '${_analyticsReportTitle(id)}. Current order status, all dates.'
                    : '${_analyticsReportTitle(id)}. Selected period: ${MaterialLocalizations.of(context).formatShortDate(start)} – ${MaterialLocalizations.of(context).formatShortDate(end)}'
                    : null, style: TextStyle(fontSize: compact ? 14 : 16,
                    fontWeight: FontWeight.w700, color: Colors.white)),
                  if (!compact) Text(id == 'orders' ? 'Current order status · all dates'
                    : 'Selected period: ${MaterialLocalizations.of(context).formatShortDate(start)}${DateUtils.isSameDay(start, end) ? '' : ' – ${MaterialLocalizations.of(context).formatShortDate(end)}'}',
                    key: Key(compact ? 'analytics-context-period-$id' : 'analytics-report-period-$id'),
                    style: const TextStyle(fontSize: 11, color: Color(0xFFE4EDF4))),
                ])))]);
            final hide = Tooltip(message: compact ? 'Hide active report' : 'Collapse details', child: TextButton(
              style: TextButton.styleFrom(foregroundColor: Colors.white, minimumSize: const Size(48, 48)),
              onPressed: () => _toggle(id), child: compact
                ? Semantics(label: 'Hide active report', child: const Icon(Icons.expand_less, size: 18))
                : const Row(mainAxisSize: MainAxisSize.min,
                  children: [Text('Hide', style: TextStyle(fontSize: 11)), Icon(Icons.expand_less, size: 18)])));
            return compact || box.maxWidth >= 280 && MediaQuery.textScalerOf(context).scale(1) <= 1.3
              ? Row(children: [Expanded(child: heading), hide]) : Column(crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [heading, Align(alignment: Alignment.centerRight, child: hide)]);
          })));
        final detail = expanded == null ? const SizedBox.shrink() : Padding(key: _detailKey,
          padding: const EdgeInsets.symmetric(vertical: 12), child: Column(key: Key('store-analytics-detail-$expanded'),
            crossAxisAlignment: CrossAxisAlignment.stretch, children: [
              reportHeading(expanded),
              SizedBox(key: Key('analytics-depth-$expanded'), height: 8),
              if (const {'public', 'journey', 'supply', 'receiving'}.contains(expanded))
                _StoreAnalyticsProviderReport(session: widget.session, report: expanded, request: _request, result: _result),
              if (expanded == 'receiving') ...categories['stock']!.children.whereType<_OperatingAttention>()
                .where((a) => a.id.startsWith('receipt-')).map(_attention),
              if (expanded == 'stock') _metrics(categories['stock']!.children.whereType<_OperatingMetric>()
                .where((m) => m.id == 'stock-cost' || m.id == 'stock-sale'), hero: true),
              if (expanded == 'sales') _metrics(categories['sales']!.children.whereType<_OperatingMetric>()
                .where((m) => m.id == 'billed' || m.id == 'collections'), hero: true),
              if (expanded == 'money') ...[
                _metrics(categories['money']!.children.whereType<_OperatingMetric>()
                  .where((m) => m.id == 'customer-dues' || m.id == 'payables'), hero: true),
                if (categories['money']!.coverage != null) Text(categories['money']!.coverage!, style: const TextStyle(fontSize: 12)),
                if (categories['money']!.children.whereType<_OperatingMetric>().any((m) => m.id.startsWith('settlement-')))
                Container(key: const Key('analytics-settlement-group'), padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 2),
                  decoration: BoxDecoration(color: _AnalyticsChartPalette.softSurface, borderRadius: _AnalyticsChartPalette.radius),
                  child: _metrics(categories['money']!.children.whereType<_OperatingMetric>()
                    .where((m) => m.id.startsWith('settlement-')), ledger: true)),
                if (metrics['settlement-available']?.value != null && metrics['settlement-available']!.value != '—' &&
                    metrics['settlement-held']?.value != null && metrics['settlement-held']!.value != '—' &&
                    widget.session.workspaceFinance != null)
                  _AnalyticsSettlementGraphic(available: widget.session.workspaceFinance!.availableMinor,
                    held: widget.session.workspaceFinance!.heldMinor),
              ],
              if (widget.detailVisuals[expanded] != null)
                Padding(padding: const EdgeInsets.symmetric(vertical: 8), child: widget.detailVisuals[expanded]!),
              if (const {'orders', 'stock', 'sales', 'money'}.contains(expanded)) ...categoryDetail(expanded),
              if (expanded == 'money') ...categoryDetail('capital'),
            ]));
        return LayoutBuilder(builder: (context, available) {
          // Keep at least60% of the actual analytics body scrollable. Native
          // accessibility scaling is preserved; an over-budget title scrolls
          // with the full heading instead of being clipped or shrunk.
          final contextTitle = TextPainter(text: TextSpan(
            text: expanded == null ? '' : _analyticsReportTitle(expanded),
            style: const TextStyle(fontSize: 14, fontWeight: FontWeight.w700)),
            textDirection: Directionality.of(context), textScaler: MediaQuery.textScalerOf(context))
            ..layout(maxWidth: (available.maxWidth - 88).clamp(1, double.infinity));
          final contextHeight = (contextTitle.height + 16).clamp(50, double.infinity);
          final pinContext = contextHeight <= available.maxHeight * .4;
          contextTitle.dispose();
          return Column(children: [
          if (_contextHeader && expanded != null && pinContext) reportHeading(expanded, compact: true),
          Expanded(child: NotificationListener<ScrollNotification>(onNotification: (_) {
            WidgetsBinding.instance.addPostFrameCallback((_) { if (mounted) _checkContextHeader(); });
            return false;
          }, child: SizedBox(key: _viewportKey, child: SingleChildScrollView(
          key: const Key('work-store-operating-board'), controller: _scroll,
          padding: const EdgeInsets.fromLTRB(12, 0, 12, 20),
          child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
            LayoutBuilder(builder: (context, box) {
              const heading = Text('Store overview',
                style: TextStyle(fontSize: 16, fontWeight: FontWeight.w700, color: _AnalyticsChartPalette.ink));
              final controls = [
                _analyticsPeriodPicker(widget.periodDays, widget.onPeriod),
                IconButton(key: const Key('store-analytics-export'), tooltip: 'Download analytics PDF',
                  style: IconButton.styleFrom(minimumSize: const Size(48, 48), visualDensity: VisualDensity.standard),
                  onPressed: _exportBusy || loading || _request == null ? null : () => _exportAnalytics(snapshot),
                  icon: _exportBusy ? const SizedBox(width: 18, height: 18,
                    child: CircularProgressIndicator(strokeWidth: 2)) : const Icon(Icons.download_outlined, size: 20)),
                IconButton(tooltip: failed ? 'Retry analytics' : 'Refresh analytics',
                  style: IconButton.styleFrom(minimumSize: const Size(48, 48), visualDensity: VisualDensity.standard),
                  onPressed: widget.onRefresh, icon: const Icon(Icons.refresh, size: 20)),
              ];
              return Wrap(
                spacing: 8, runSpacing: 4,
                alignment: WrapAlignment.spaceBetween,
                crossAxisAlignment: WrapCrossAlignment.center,
                children: [heading, Wrap(
                  alignment: WrapAlignment.end,
                  crossAxisAlignment: WrapCrossAlignment.center,
                  children: controls,
                )],
              );
            }),
            if (_exportNotice != null) Text(_exportNotice!, key: const Key('store-analytics-export-notice'),
              style: const TextStyle(fontSize: 12)),
            Text('${MaterialLocalizations.of(context).formatShortDate(start)}${DateUtils.isSameDay(start, end) ? '' : ' – ${MaterialLocalizations.of(context).formatShortDate(end)}'} · through ${MaterialLocalizations.of(context).formatTimeOfDay(TimeOfDay.fromDateTime(end))}',
              style: const TextStyle(fontSize: 12, color: _OperatingPalette.secondary)),
            ...widget.sections.where((item) => item is Tooltip || item is _DashboardSyncBanner),
            Padding(padding: const EdgeInsets.symmetric(vertical: 2),
              child: Container(key: const Key('analytics-provider-status-surface'),
                decoration: BoxDecoration(color: failed ? const Color(0xFFFFF0ED) :
                  verified ? const Color(0xFFEDF6F4) : _AnalyticsChartPalette.softSurface,
                  borderRadius: BorderRadius.circular(6)),
                padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 2),
                child: Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
                  if (loading) SizedBox(key: const Key('analytics-provider-loading'), width: 12, height: 12,
                    child: TweenAnimationBuilder<double>(
                      duration: MoolMotion.isReduced(context) ? Duration.zero : const Duration(milliseconds: 180),
                      tween: Tween(begin: .4, end: 1),
                      builder: (context, value, child) => Opacity(opacity: value, child: child),
                      child: const Icon(Icons.hourglass_empty_rounded, size: 12, color: _AnalyticsChartPalette.sales)))
                  else Icon(failed ? Icons.error_outline_rounded : verified ? Icons.check_circle_outline_rounded :
                    Icons.info_outline_rounded, size: 14,
                    color: failed ? _OperatingPalette.error : _AnalyticsChartPalette.secondary),
                  const SizedBox(width: 5), Expanded(child: Text(status,
                    key: const Key('store-analytics-provider-status'),
                    style: const TextStyle(fontSize: 12, color: _AnalyticsChartPalette.secondary))),
                ]))),
            if (verified) Text('Provider updated ${MaterialLocalizations.of(context).formatShortDate(snapshot.updatedAt!.toLocal())} · ${MaterialLocalizations.of(context).formatTimeOfDay(TimeOfDay.fromDateTime(snapshot.updatedAt!.toLocal()))}',
              style: const TextStyle(fontSize: 11, color: _OperatingPalette.secondary)),
            Row(children: [const Expanded(child: Text('Explore reports',
              style: TextStyle(fontSize: 14, fontWeight: FontWeight.w700, color: _AnalyticsChartPalette.ink))),
              const Tooltip(message: 'Tap a card for details · — unavailable · ~ partial data',
                triggerMode: TooltipTriggerMode.tap, child: SizedBox(width: 44, height: 44,
                  child: Icon(Icons.info_outline, size: 16, color: _AnalyticsChartPalette.secondary)))]),
            LayoutBuilder(builder: (context, box) {
              final halfWidth = (box.maxWidth - 8) / 2 - 16;
              final fitsFigures = figures.values.expand((rows) => rows).every((row) {
                final measure = TextPainter(text: TextSpan(text: row.$2,
                  style: const TextStyle(fontSize: 14, fontWeight: FontWeight.w700)),
                  textDirection: Directionality.of(context), textScaler: MediaQuery.textScalerOf(context))..layout();
                final fits = measure.width <= halfWidth;
                measure.dispose();
                return fits;
              });
              final columns = box.maxWidth >= 320 && MediaQuery.textScalerOf(context).scale(1) <= 1.3 && fitsFigures ? 2 : 1;
              final width = (box.maxWidth - (columns - 1) * 8) / columns;
              final ids = summaries.keys.toList();
              Widget card(String id) {
                final known = figures[id]!.first.$2 != '—';
                const foreground = _AnalyticsChartPalette.ink;
                final background = !known ? _AnalyticsChartPalette.softSurface
                  : id == 'sales' ? const Color(0xFFEDF1FC)
                  : id == 'orders' ? const Color(0xFFEDF6F4) : _AnalyticsChartPalette.surface;
                return Material(
                    animationDuration: MoolMotion.isReduced(context) ? Duration.zero : const Duration(milliseconds: 180),
                    elevation: expanded == id ? 3 : .5,
                    shadowColor: _AnalyticsChartPalette.ink.withValues(alpha: .14),
                    surfaceTintColor: Colors.transparent,
                    color: expanded == id ? _AnalyticsChartPalette.selectedSurface : background,
                    shape: RoundedRectangleBorder(borderRadius: _AnalyticsChartPalette.radius,
                      side: BorderSide(width: expanded == id ? 2 : 1,
                        color: expanded == id ? _AnalyticsChartPalette.sales : _AnalyticsChartPalette.border)),
                    child: Semantics(
                      expanded: expanded == id, selected: expanded == id, button: true,
                      child: InkWell(key: Key('store-analytics-$id'), onTap: () => _toggle(id),
                        hoverColor: foreground.withValues(alpha: .06),
                        focusColor: foreground.withValues(alpha: .10),
                        highlightColor: foreground.withValues(alpha: .08),
                        borderRadius: _AnalyticsChartPalette.radius, child: Padding(
                          padding: const EdgeInsets.all(8), child: Column(
                            mainAxisSize: MainAxisSize.min,
                            crossAxisAlignment: CrossAxisAlignment.start, children: [
                              Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
                                Container(width: 24, height: 24, margin: const EdgeInsets.only(right: 6),
                                  decoration: BoxDecoration(color: _AnalyticsChartPalette.reportTint(id), borderRadius: BorderRadius.circular(6)),
                                  child: Icon(_AnalyticsChartPalette.reportIcon(id), size: 16,
                                    color: _AnalyticsChartPalette.reportAccent(id))),
                                Expanded(child: Text(id == 'receiving' ? 'Purchases' : _analyticsReportTitle(id),
                                  style: TextStyle(fontSize: 13, fontWeight: FontWeight.w700, color: foreground))),
                              ]),
                              Semantics(key: Key('store-analytics-summary-$id'), label: summaries[id],
                                child: _AnalyticsExplorePreview(id: id, figures: figures[id]!,
                                  graphic: widget.compactVisuals[id],
                                  unavailable: failed ? 'Could not load data' : loading ? 'Updating data…' :
                                    !widget.session.hasAnalyticsReader
                                      ? (id == 'public' || id == 'journey' ? 'Tracking not connected' : 'Supply data not connected')
                                      : 'Data unavailable',
                                  balanceDate: id == 'money' && local('customer-dues') != '—'
                                    ? widget.session.workspaceFinance?.asOf : null,
                                  orderCoverage: id == 'orders' ? categories[id]?.coverage : null,
                                  expanded: expanded == id,
                                  publicRanking: verified ? snapshot.breakdowns.where((data) =>
                                    data.id == 'discovery-sources' && data.dimension == WorkspaceAnalyticsDimension.discoverySource).firstOrNull : null)),
                            ])))));
              }
              return Column(children: [
                for (var index = 0; index < ids.length; index += columns) ...[
                  Padding(padding: EdgeInsets.only(bottom: index + columns < ids.length ? 8 : 0),
                    child: IntrinsicHeight(child: Row(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
                      for (var offset = 0; offset < columns && index + offset < ids.length; offset++) ...[
                        if (offset > 0) const SizedBox(width: 8),
                        SizedBox(width: width, child: card(ids[index + offset])),
                      ],
                    ]))),
                  if (expanded != null && ids.skip(index).take(columns).contains(expanded)) _inlineReveal(detail),
                ],
                if (expanded == null) _inlineReveal(const SizedBox.shrink()),
              ]);
            }),
            const SizedBox(height: 16),
            _AnalyticsOverviewPanel(id: 'stock-hero', title: 'Stock',
              colour: _AnalyticsChartPalette.stockSurface,
              figures: [('Money in stock', local('stock-cost'))],
              guide: metrics['stock-cost']?.detail ?? 'Stock valuation unavailable',
              graphic: widget.overviewVisuals['stock'], onTap: () => _toggle('stock')),
            const SizedBox(height: 10),
            _AnalyticsOverviewPanel(id: 'sales-hero', title: 'Sales & collections',
              colour: _AnalyticsChartPalette.moneySurface, figures: figures['sales']!,
              guide: '${metrics['billed']?.detail ?? 'Sales history unavailable'} · ${metrics['collections']?.detail ?? 'Collection history unavailable'}',
              graphic: widget.overviewVisuals['sales'], onTap: () => _toggle('sales')),
            const SizedBox(height: 10),
            _AnalyticsOverviewPanel(id: 'dues-strip', title: 'Outstanding balances', figures: figures['money']!,
              guide: categories['money']?.coverage ?? 'Balances use their own saved sources; not a combined cash position.',
              onTap: () => _toggle('money')),
          ]),
        )))),
        ]);
        });
      });
    return _storeInlineBackPriority(context,
      enabled: () => _expanded != null,
      onBack: () {
        final expanded = _expanded;
        if (expanded != null) {
          _toggle(expanded);
        }
      },
      child: content,
    );
  }
}

double _analyticsNumberSize(BuildContext context, String value, double preferred, double width) {
  final measured = TextPainter(text: TextSpan(text: value,
    style: DefaultTextStyle.of(context).style.merge(TextStyle(fontSize: preferred, fontWeight: FontWeight.w700))),
    textDirection: Directionality.of(context), textScaler: MediaQuery.textScalerOf(context))..layout();
  final available = (width - 4).clamp(0.0, double.infinity);
  final size = measured.width <= available ? preferred : (preferred * available / measured.width).clamp(12.0, preferred);
  measured.dispose();
  return size;
}

/// Overview composition uses the same read-only metric owners as each report.
/// Visible read-only report previews. Decorative stages never imply measured flow.
class _AnalyticsExplorePreview extends StatelessWidget {
  const _AnalyticsExplorePreview({required this.id, required this.figures,
    required this.unavailable, this.graphic, this.publicRanking, this.balanceDate, this.orderCoverage, this.expanded = false});
  final String id, unavailable;
  final String? orderCoverage;
  final List<(String, String)> figures;
  final Widget? graphic;
  final WorkspaceAnalyticsBreakdown? publicRanking;
  final DateTime? balanceDate;
  final bool expanded;

  @override
  Widget build(BuildContext context) {
    final accent = _AnalyticsChartPalette.reportAccent(id);
    final known = figures.any((row) => row.$2 != '—');
    final cue = switch (id) {
      'public' => 'View reach', 'journey' => 'View journey', 'supply' => 'View supply',
      'receiving' => 'View receiving', 'orders' => 'View orders', 'stock' => 'View stock',
      'sales' => 'View sales', _ => 'View balances',
    };
    Widget stages(List<(IconData, String)> rows, {bool connected = false}) {
      if (rows.length == 4) { return Column(children: [
        for (var start = 0; start < rows.length; start += 2) Padding(
          padding: const EdgeInsets.only(bottom: 4), child: Row(children: [
            for (var offset = 0; offset < 2; offset++) Expanded(child: Row(children: [
              Icon(rows[start + offset].$1, size: 14, color: accent), const SizedBox(width: 3),
              Expanded(child: Text(rows[start + offset].$2,
                style: const TextStyle(fontSize: 11, color: _AnalyticsChartPalette.secondary))),
            ])),
          ])),
      ]); }
      return Row(
      crossAxisAlignment: CrossAxisAlignment.start, children: [
        for (final (index, row) in rows.indexed) ...[
          if (index > 0 && connected) Padding(padding: const EdgeInsets.only(top: 9),
            child: SizedBox(width: 8, height: 1, child: ColoredBox(color: accent.withValues(alpha: .3)))),
          Expanded(child: Column(children: [Icon(row.$1, size: 20, color: accent),
            const SizedBox(height: 3), Text(row.$2, textAlign: TextAlign.center,
              style: const TextStyle(fontSize: 11, color: _AnalyticsChartPalette.secondary))])),
        ],
      ]);
    }
    Widget visual;
    if (id == 'stock' && graphic is _StockAvailabilityGraphic) {
      final stock = graphic! as _StockAvailabilityGraphic;
      final total = stock.available + stock.unavailable;
      visual = Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Row(children: [
        if (total > 0) SizedBox(width: 36, height: 36, child: Padding(padding: const EdgeInsets.all(4),
          child: CircularProgressIndicator(key: const Key('analytics-preview-stock-ring'),
            value: stock.available / total, strokeWidth: 5,
            color: _AnalyticsChartPalette.available, backgroundColor: _AnalyticsChartPalette.unavailable))),
        if (total > 0) const SizedBox(width: 6),
        Expanded(child: Text('${stock.available} available\n${stock.unavailable} unavailable',
          style: const TextStyle(fontSize: 11, color: _AnalyticsChartPalette.secondary))),
      ]), const SizedBox(height: 3), const Text('Products · saved Stock',
        style: TextStyle(fontSize: 11, color: _AnalyticsChartPalette.secondary))]);
    } else if (id == 'sales' && graphic != null) {
      visual = Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
        _AnalyticsChartReveal(id: 'preview-sales', child: graphic!),
        const SizedBox(height: 4), const Text('Saved bills · 7 days\nBefore returns',
          style: TextStyle(fontSize: 11, color: _AnalyticsChartPalette.secondary)),
      ]);
    } else if (id == 'public' && publicRanking != null && publicRanking!.rows.isNotEmpty) {
      final data = publicRanking!;
      final rows = (data.rows.toList()..sort((a, b) => b.count.compareTo(a.count))).take(2);
      final maximum = data.rows.fold<int>(0, (value, row) => row.count > value ? row.count : value);
      visual = Column(key: const Key('analytics-preview-public-ranking'),
        crossAxisAlignment: CrossAxisAlignment.stretch, children: [
          Text('Discovery · ${data.coverage == WorkspaceAnalyticsCoverage.partial ? 'partial' : 'complete'}',
            style: const TextStyle(fontSize: 11, color: _AnalyticsChartPalette.secondary)),
          for (final row in rows) ...[
            Text('${row.label} · ${row.count}', style: const TextStyle(fontSize: 11, color: _AnalyticsChartPalette.ink)),
            if (maximum > 0) Align(alignment: Alignment.centerLeft, child: FractionallySizedBox(
              widthFactor: row.count / maximum, child: SizedBox(key: Key('analytics-preview-rank-${row.id}'),
                height: 4, child: ColoredBox(color: accent)))),
          ],
        ]);
    } else {
      visual = switch (id) {
        'public' => stages([(Icons.visibility_outlined, 'Visitors'), (Icons.storefront_outlined, 'Listings')]),
        'journey' => stages([(Icons.storefront_outlined, 'Store'), (Icons.shopping_cart_outlined, 'Cart'),
          (Icons.receipt_long_outlined, 'Order')], connected: true),
        'supply' => stages([(Icons.fact_check_outlined, 'Accept'), (Icons.local_shipping_outlined, 'Dispatch'), (Icons.route_outlined, 'Transit'),
          (Icons.inventory_2_outlined, 'Receive')]),
        'receiving' => stages([(Icons.inventory_2_outlined, 'Goods'), (Icons.description_outlined, 'Bill')]),
        'orders' || 'money' => const SizedBox.shrink(),
        _ => stages([(_AnalyticsChartPalette.reportIcon(id), 'Data unavailable')]),
      };
    }
    return Padding(key: Key('analytics-preview-$id'), padding: const EdgeInsets.only(top: 8),
      child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
        if (known && id == 'sales') const Text('Selected period',
          style: TextStyle(fontSize: 11, color: _AnalyticsChartPalette.secondary)),
        if (known) for (final (index, row) in figures.indexed) Padding(
          padding: const EdgeInsets.only(bottom: 4), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
              if (id == 'orders' || id == 'money') ...[
                ExcludeSemantics(child: Icon(id == 'orders'
                  ? index == 0 ? Icons.receipt_long_outlined : Icons.schedule_outlined
                  : index == 0 ? Icons.call_received : Icons.call_made, size: 14, color: accent)),
                const SizedBox(width: 4),
              ],
              Expanded(child: Text(id == 'stock' && index == 1 ? 'Low-stock products' : row.$1,
                style: const TextStyle(fontSize: 11, color: _AnalyticsChartPalette.secondary))),
            ]),
            Text(row.$2, key: Key('analytics-preview-value-$id-$index'), softWrap: false,
              style: const TextStyle(fontSize: 14, fontWeight: FontWeight.w700, color: _AnalyticsChartPalette.ink)),
            if (id == 'money' && index == 0 && balanceDate != null)
              Text('As of ${MaterialLocalizations.of(context).formatShortDate(balanceDate!.toLocal())}',
                key: const Key('analytics-preview-customer-balance-date'),
                style: const TextStyle(fontSize: 11, color: _AnalyticsChartPalette.secondary)),
          ])),
        KeyedSubtree(key: Key('analytics-preview-visual-$id'),
          child: id != 'sales' && (known || id == 'public' && publicRanking != null && publicRanking!.rows.isNotEmpty)
            ? _AnalyticsChartReveal(id: 'preview-$id', child: visual) : visual),
        if (!known && const {'public', 'journey', 'supply', 'receiving'}.contains(id))
          Padding(padding: const EdgeInsets.only(top: 5), child: Text(
            id == 'public' && publicRanking != null && publicRanking!.rows.isNotEmpty ? 'Visitor totals unavailable' : unavailable,
            style: const TextStyle(fontSize: 11, color: _AnalyticsChartPalette.secondary))),
        if (id == 'journey') const Text('Selected stages',
          style: TextStyle(fontSize: 11, color: _AnalyticsChartPalette.secondary)),
        if (id == 'orders' && !expanded) Text(orderCoverage ?? 'Saved orders · online coverage incomplete',
          style: const TextStyle(fontSize: 11, color: _AnalyticsChartPalette.secondary)),
        if (id == 'money' && figures.last.$2 == '—') const Text('Supplier balance unavailable',
          style: TextStyle(fontSize: 11, color: _AnalyticsChartPalette.secondary)),
        const SizedBox(height: 6),
        Row(key: Key('analytics-preview-action-$id'), children: [Expanded(child: Text(
          expanded ? 'Hide details' : cue,
          style: TextStyle(fontSize: 11, fontWeight: FontWeight.w600, color: accent))),
          Icon(expanded ? Icons.expand_less : Icons.expand_more, size: 16, color: accent)]),
      ]));
  }
}

class _AnalyticsOverviewPanel extends StatelessWidget {
  const _AnalyticsOverviewPanel({required this.id, required this.title,
    required this.figures, required this.guide, required this.onTap, this.colour, this.graphic});
  final String id, title, guide;
  final List<(String, String)> figures;
  final Color? colour;
  final Widget? graphic;
  final VoidCallback onTap;
  @override
  Widget build(BuildContext context) {
    final ink = colour == null ? _AnalyticsChartPalette.ink : Colors.white;
    final muted = colour == null ? _AnalyticsChartPalette.secondary : const Color(0xFFD9E4EF);
    return Container(key: Key('analytics-overview-$id'),
      decoration: BoxDecoration(
        gradient: colour == null ? null : LinearGradient(colors: [colour!, Color.lerp(colour, Colors.black, .18)!],
          begin: Alignment.topLeft, end: Alignment.bottomRight),
        color: colour == null ? _AnalyticsChartPalette.softSurface : null,
        borderRadius: BorderRadius.circular(16)),
      padding: const EdgeInsets.fromLTRB(12, 0, 12, 10),
      child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
        Row(children: [Expanded(child: Text(title, style: TextStyle(color: ink,
          fontSize: 15, fontWeight: FontWeight.w700))),
          IconButton(tooltip: 'View $title report', onPressed: onTap,
            icon: Icon(Icons.arrow_forward_rounded, size: 20, color: ink))]),
        LayoutBuilder(builder: (context, box) {
          var paired = figures.length == 2 && MediaQuery.textScalerOf(context).scale(1) <= 1.3;
          final half = (box.maxWidth - 16) / 2;
          for (final figure in figures) {
            final measure = TextPainter(text: TextSpan(text: figure.$2,
              style: const TextStyle(fontSize: 24, fontWeight: FontWeight.w700)),
              textDirection: Directionality.of(context), textScaler: MediaQuery.textScalerOf(context))..layout();
            if (measure.width > half) paired = false;
            measure.dispose();
          }
          Widget value((String, String) figure, double width) => Column(
            crossAxisAlignment: CrossAxisAlignment.start, children: [
              Text(figure.$1, style: TextStyle(fontSize: 12, color: muted)),
              Text(figure.$2, key: Key('analytics-overview-$id-${figures.indexOf(figure)}'),
                style: TextStyle(fontSize: _analyticsNumberSize(context, figure.$2, 28, width),
                  fontWeight: FontWeight.w700, color: ink)),
            ]);
          return paired ? Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Expanded(child: value(figures.first, half)), const SizedBox(width: 16),
            Expanded(child: value(figures.last, half)),
          ]) : Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
            for (final (index, figure) in figures.indexed) ...[
              if (index > 0) const SizedBox(height: 10), value(figure, box.maxWidth),
            ],
          ]);
        }),
        const SizedBox(height: 4),
        Text(guide, style: TextStyle(fontSize: 11, color: muted)),
        if (graphic != null) ...[const SizedBox(height: 8), graphic!],
      ]));
  }
}

