/// The same daily observations as the bars; no interpolated business values.
class _AnalyticsSalesPlot extends StatefulWidget {
  const _AnalyticsSalesPlot({required this.series});
  final List<(DateTime, int)> series;
  @override
  State<_AnalyticsSalesPlot> createState() => _AnalyticsSalesPlotState();
}

class _AnalyticsSalesPlotState extends State<_AnalyticsSalesPlot> {
  int? _selected;
  final _dateScroll = ScrollController();
  final _dateViewport = GlobalKey();
  final _dateKeys = <GlobalKey>[];
  (int, Size, double, DateTime)? _dateRevealSignature;
  @override
  void dispose() { _dateScroll.dispose(); super.dispose(); }
  void _revealSelected(int index) {
    final item = _dateKeys[index].currentContext?.findRenderObject();
    final viewport = _dateViewport.currentContext?.findRenderObject();
    if (!mounted || !_dateScroll.hasClients || item is! RenderBox || viewport is! RenderBox) return;
    final start = item.localToGlobal(Offset.zero).dx - viewport.localToGlobal(Offset.zero).dx;
    final end = start + item.size.width;
    final delta = start < 0 ? start : end > viewport.size.width ? end - viewport.size.width : 0.0;
    if (delta.abs() > .5) _dateScroll.jumpTo((_dateScroll.offset - delta).clamp(0.0, _dateScroll.position.maxScrollExtent));
  }
  @override
  Widget build(BuildContext context) {
    while (_dateKeys.length < widget.series.length) { _dateKeys.add(GlobalKey()); }
    final index = (_selected ?? widget.series.length - 1).clamp(0, widget.series.length - 1);
    final selected = widget.series[index];
    final signature = (index, MediaQuery.sizeOf(context), MediaQuery.textScalerOf(context).scale(1), selected.$1);
    if (_dateRevealSignature != signature) {
      _dateRevealSignature = signature;
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted && _dateRevealSignature == signature) _revealSelected(index);
      });
    }
    final maximum = widget.series.fold<int>(0, (value, row) => row.$2 > value ? row.$2 : value);
    String date(DateTime at) => '${at.day.toString().padLeft(2, '0')}/${at.month.toString().padLeft(2, '0')}';
    return Container(key: const Key('analytics-sales-plot'), padding: const EdgeInsets.all(10),
      child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
        _AnalyticsMoneyCaption(id: 'analytics-sales-selected-point', label: date(selected.$1),
          minor: selected.$2, suffix: 'Before returns'),
        const SizedBox(height: 8),
        if (maximum > 0) _AnalyticsMoneyCaption(id: 'analytics-sales-axis-zero', label: 'Scale from', minor: 0),
        if (maximum > 0) _AnalyticsMoneyCaption(id: 'analytics-sales-axis-max', label: 'Scale to', minor: maximum),
        ExcludeSemantics(child: _AnalyticsChartReveal(id: 'sales-line', child: SizedBox(height: maximum == 0 ? 20 : 112,
          child: CustomPaint(key: const Key('analytics-sales-line'),
            painter: _AnalyticsSalesPainter(widget.series.map((row) => row.$2).toList(), index))))),
        SizedBox(key: _dateViewport, child: SingleChildScrollView(key: const Key('analytics-sales-date-strip'), controller: _dateScroll, scrollDirection: Axis.horizontal,
          reverse: true, child: Row(mainAxisSize: MainAxisSize.min, children: [for (var i = 0; i < widget.series.length; i++)
          Semantics(selected: i == index, label: 'Select ${date(widget.series[i].$1)} · ₹${_formatStoreMinorAmount(widget.series[i].$2)}',
            child: SizedBox(key: _dateKeys[i], child: TextButton(key: Key('analytics-sales-point-$i'),
              style: TextButton.styleFrom(minimumSize: const Size(44, 44), padding: const EdgeInsets.symmetric(horizontal: 6),
                tapTargetSize: MaterialTapTargetSize.shrinkWrap,
                foregroundColor: _AnalyticsChartPalette.ink,
                backgroundColor: i == index ? _AnalyticsChartPalette.sales.withValues(alpha: .14) : Colors.transparent),
              onPressed: () => setState(() => _selected = i), child: AnimatedDefaultTextStyle(
                key: Key('analytics-sales-date-style-$i'),
                duration: MoolMotion.isReduced(context) ? Duration.zero : const Duration(milliseconds: 180),
                style: DefaultTextStyle.of(context).style.copyWith(fontSize: 11, color: _AnalyticsChartPalette.ink,
                  fontWeight: i == index ? FontWeight.w700 : FontWeight.w500), child: Text(date(widget.series[i].$1)))))),
        ]))),
      ]));
  }
}

class _AnalyticsSalesPainter extends CustomPainter {
  _AnalyticsSalesPainter(this.values, this.selected);
  final List<int> values;
  final int selected;
  @override
  void paint(Canvas canvas, Size size) {
    if (values.isEmpty) return;
    final maximum = values.fold<int>(0, (max, value) => value > max ? value : max);
    final area = Rect.fromLTWH(8, 8, (size.width - 16).clamp(0, double.infinity), size.height - 16);
    final grid = Paint()..color = _AnalyticsChartPalette.border..strokeWidth = 1;
    for (var i = maximum == 0 ? 2 : 0; i < 3; i++) {
      final y = area.top + area.height * i / 2;
      canvas.drawLine(Offset(area.left, y), Offset(area.right, y), grid);
    }
    final points = [for (var i = 0; i < values.length; i++)
      Offset(area.left + area.width * i / (values.length > 1 ? values.length - 1 : 1),
        area.bottom - (maximum == 0 ? 0 : area.height * values[i] / maximum))];
    final path = Path()..moveTo(points.first.dx, points.first.dy);
    for (final point in points.skip(1)) { path.lineTo(point.dx, point.dy); }
    if (maximum > 0) {
      final fill = Path.from(path)..lineTo(area.right, area.bottom)..lineTo(area.left, area.bottom)..close();
      canvas.drawPath(fill, Paint()..shader = LinearGradient(begin: Alignment.topCenter, end: Alignment.bottomCenter,
        colors: [_AnalyticsChartPalette.sales.withValues(alpha: .28), _AnalyticsChartPalette.sales.withValues(alpha: .02)]).createShader(area));
    }
    canvas.drawPath(path, Paint()..shader = _AnalyticsChartPalette.barGradient.createShader(area)
      ..style = PaintingStyle.stroke..strokeWidth = 3..strokeJoin = StrokeJoin.round..strokeCap = StrokeCap.round);
    for (var i = 0; i < points.length; i++) {
      canvas.drawCircle(points[i], i == selected ? 6 : 3, Paint()..color = _AnalyticsChartPalette.sales);
      if (i == selected) canvas.drawCircle(points[i], 3, Paint()..color = Colors.white);
    }
  }
  @override
  bool shouldRepaint(covariant _AnalyticsSalesPainter old) => old.selected != selected || !listEquals(old.values, values);
}

class _SavedBillGraphic extends StatelessWidget {
  const _SavedBillGraphic({required this.series, required this.todayMinor,
    required this.previousMinor, this.compact = false, this.hasSavedBills = false});
  final List<(DateTime, int)> series;
  final int todayMinor, previousMinor;
  final bool compact;
  final bool hasSavedBills;
  String money(int minor) => '₹${_formatStoreMinorAmount(minor)}';
  @override
  Widget build(BuildContext context) {
    final maximum = series.fold<int>(0, (max, row) => row.$2 > max ? row.$2 : max);
    final total = series.fold<int>(0, (sum, row) => sum + row.$2);
    String date(DateTime day) => '${day.day.toString().padLeft(2, '0')}/${day.month.toString().padLeft(2, '0')}';
    final label = series.map((row) => '${date(row.$1)} ${money(row.$2)}').join(', ');
    if (compact && maximum == 0) {
      return Text(hasSavedBills ? '₹0 billed · last 7 days' : 'No saved bills · last 7 days',
        key: const Key('analytics-sales-zero-preview'),
        style: const TextStyle(fontSize: 11, color: _AnalyticsChartPalette.secondary));
    }
    if (compact) {
      return Tooltip(message: 'Saved bills last 7 days, before returns: $label',
      decoration: BoxDecoration(color: _AnalyticsChartPalette.ink, borderRadius: BorderRadius.circular(8)),
      textStyle: const TextStyle(color: Colors.white, fontSize: 13),
      child: Semantics(label: 'Saved bills last 7 days, before returns: $label',
      child: ExcludeSemantics(child: SizedBox(key: const Key('analytics-sales-spark-bars'), height: 12,
        child: Row(crossAxisAlignment: CrossAxisAlignment.end, children: [for (final row in series)
          Expanded(child: Padding(padding: const EdgeInsets.symmetric(horizontal: 1),
            child: Container(height: maximum == 0 ? 1 : 1 + 11 * row.$2 / maximum,
              decoration: BoxDecoration(color: row.$2 == 0 ? _AnalyticsChartPalette.emptyTrack : _AnalyticsChartPalette.sales,
                borderRadius: BorderRadius.circular(2))))) ])))));
    }
    final change = todayMinor - previousMinor;
    final comparison = change == 0 ? 'No change · through the same time' :
      '${change > 0 ? 'Up' : 'Down'} ${money(change.abs())} · through the same time';
    return Column(key: const Key('analytics-sales-bars'), crossAxisAlignment: CrossAxisAlignment.start, children: [
      Row(children: [Icon(change == 0 ? Icons.trending_flat : change > 0 ? Icons.trending_up : Icons.trending_down,
        color: _AnalyticsChartPalette.sales, size: 20), const SizedBox(width: 6), Expanded(child: Text(comparison,
          key: const Key('analytics-sales-comparison'), style: const TextStyle(fontSize: 12, fontWeight: FontWeight.w600)))]),
      Text('${money(todayMinor)} today · ${money(previousMinor)} yesterday', style: const TextStyle(fontSize: 12)),
      const Text('Saved invoices only · today ends at the displayed time. Not live online sales or money collected.',
        style: TextStyle(fontSize: 11, color: _OperatingPalette.secondary)),
      const SizedBox(height: 8),
      const Text('Saved bills · last 7 days', style: TextStyle(fontSize: 13, fontWeight: FontWeight.w600)),
      Text('${money(total)} billed · before returns', style: const TextStyle(fontSize: 12)),
      const SizedBox(height: 6),
      _AnalyticsSalesPlot(series: series),
      const SizedBox(height: 8),
      if (maximum > 0) for (final row in series) Padding(padding: const EdgeInsets.symmetric(vertical: 3),
        child: LayoutBuilder(builder: (context, box) {
          final amountMeasure = TextPainter(text: TextSpan(text: money(row.$2),
            style: const TextStyle(fontSize: 12, fontWeight: FontWeight.w600)),
            textDirection: Directionality.of(context), textScaler: MediaQuery.textScalerOf(context))..layout();
          final wide = box.maxWidth >= 320 && MediaQuery.textScalerOf(context).scale(1) <= 1.3 &&
            amountMeasure.width <= box.maxWidth * .35;
          amountMeasure.dispose();
          final bar = Semantics(label: '${date(row.$1)} saved bill total ${money(row.$2)}',
            child: ExcludeSemantics(child: SizedBox(height: 10, child: LayoutBuilder(builder: (context, track) =>
              Align(alignment: Alignment.centerLeft, child: Container(
                width: maximum == 0 ? 0 : track.maxWidth * row.$2 / maximum,
                decoration: BoxDecoration(gradient: _AnalyticsChartPalette.barGradient, borderRadius: BorderRadius.circular(3))))))));
          final content = wide ? Row(children: [SizedBox(width: 44, child: Text(date(row.$1), style: const TextStyle(fontSize: 11))),
            Expanded(child: bar), const SizedBox(width: 8),
            SizedBox(width: box.maxWidth * .35, child: Text(money(row.$2), textAlign: TextAlign.end,
              style: const TextStyle(fontSize: 12, fontWeight: FontWeight.w600)))]) :
            Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
              Text(date(row.$1), style: const TextStyle(fontSize: 11)),
              Text(money(row.$2), style: const TextStyle(fontSize: 12, fontWeight: FontWeight.w600)), bar]);
          return Tooltip(message: '${date(row.$1)} · ${money(row.$2)} · Before returns',
            triggerMode: TooltipTriggerMode.tap, showDuration: const Duration(seconds: 4),
            decoration: BoxDecoration(color: _AnalyticsChartPalette.ink, borderRadius: BorderRadius.circular(8)),
            textStyle: const TextStyle(color: Colors.white, fontSize: 13),
            child: Container(padding: const EdgeInsets.symmetric(vertical: 4, horizontal: 6),
              constraints: const BoxConstraints(minHeight: 44),
              decoration: BoxDecoration(color: _AnalyticsChartPalette.softSurface, borderRadius: BorderRadius.circular(6)),
              child: content));
        })),
      if (maximum == 0) Text(hasSavedBills ? 'Saved bills have a zero billed total' : 'No bills saved in this period',
        style: const TextStyle(fontSize: 12)),
      const SizedBox(height: 8),
    ]);
  }
}

class _StoreAnalyticsProviderReport extends StatefulWidget {
  const _StoreAnalyticsProviderReport({
    required this.session, required this.report, required this.request, required this.result,
  });
  final WorkSession session;
  final String report;
  final WorkspaceAnalyticsRequest? request;
  final Future<WorkspaceAnalyticsSnapshot>? result;
  @override
  State<_StoreAnalyticsProviderReport> createState() => _StoreAnalyticsProviderReportState();
}

class _StoreAnalyticsProviderReportState extends State<_StoreAnalyticsProviderReport> {
  bool _definitions = false;
  WorkspaceAnalyticsRequest? get _request => widget.request;
  Future<WorkspaceAnalyticsSnapshot>? get _result => widget.result;
  static String metricGuide(String id, String fallback, WorkspaceAnalyticsMetric? metric) =>
      id == 'journey-checkout' && storeAnalyticsMetricEligible(id, metric)
          ? 'Signed-in accounts · each counted once. Opening Checkout is not an order or conversion.'
          : id == 'journey-store' && storeAnalyticsMetricEligible(id, metric) &&
        metric!.coverage == WorkspaceAnalyticsCoverage.partial &&
        metric.source.startsWith('Signed-in Store visits only · tracked ')
          ? 'Signed-in accounts · each counted once. Only recorded visits are included.'
          : fallback;
  static List<({String id, String label, String guide})> definitions(String report) => switch (report) {
      'public' => const [
        (
          id: 'visitors',
          label: 'Visitors',
          guide: 'Unique visitors to your Store',
        ),
        (
          id: 'visits',
          label: 'Visits',
          guide: 'Visits, including repeat visits',
        ),
        (
          id: 'store-views',
          label: 'Store views',
          guide: 'Times your public Store was viewed',
        ),
        (
          id: 'product-views',
          label: 'Product views',
          guide: 'Recorded product presentations, including repeat views. Not unique customers; coverage may be partial.',
        ),
        (
          id: 'visible-skus',
          label: 'Visible products',
          guide: 'Confirmed visible on the public Store · current position',
        ),
        (
          id: 'hidden-skus',
          label: 'Hidden products',
          guide: 'Confirmed hidden listings · current position',
        ),
        (
          id: 'unavailable-skus',
          label: 'Unavailable products',
          guide: 'Confirmed unavailable online · current position',
        ),
        (
          id: 'interest-no-order',
          label: 'Interest without orders',
          guide: 'Products viewed but not ordered',
        ),
        (id: 'listing-corrections', label: 'Listings needing correction', guide: 'Confirmed listing issues · current position'),
        (id: 'enquiries', label: 'Customer enquiries', guide: 'Enquiries about your Store or products'),
        (id: 'offer-orders', label: 'Orders from offers', guide: 'Customer orders with verified offer attribution'),
      ],
      'journey' => const [
        (
          id: 'journey-store',
          label: 'Visited Store',
          guide: 'Start of the customer journey',
        ),
        (
          id: 'journey-product',
          label: 'Viewed a product',
          guide: 'Customers exploring your products',
        ),
        (
          id: 'journey-cart',
          label: 'Added to cart',
          guide: 'Customers adding your Store’s products',
        ),
        (
          id: 'journey-checkout',
          label: 'Opened Checkout',
          guide: 'Signed-in accounts opening Checkout · not orders or conversion',
        ),
        (
          id: 'journey-order',
          label: 'Placed an order',
          guide: 'Customer orders received by this Store',
        ),
        (
          id: 'journey-completed',
          label: 'Completed an order',
          guide: 'Confirmed delivery or collection',
        ),
        (
          id: 'journey-left',
          label: 'Left without ordering',
          guide: 'Verified customer drop-off',
        ),
        (
          id: 'repeat-customers',
          label: 'Repeat customers',
          guide: 'Customers with a previous completed order',
        ),
        (id: 'order-conversion', label: 'Visitors who ordered', guide: 'Verified share of the same tracked customer group'),
        (id: 'cart-dropoff', label: 'Customers who left their cart', guide: 'Verified share who added items but did not order'),
      ],
      'supply' => const [
        (
          id: 'supply-placed',
          label: 'Supplier orders placed',
          guide: 'Your Store buying from suppliers · selected period',
        ),
        (
          id: 'supply-acceptance',
          label: 'Awaiting supplier acceptance',
          guide: 'Current pending supplier orders',
        ),
        (
          id: 'supply-dispatch',
          label: 'Dispatch pending',
          guide: 'Accepted orders not yet dispatched',
        ),
        (
          id: 'supply-transit',
          label: 'Goods in transit',
          guide: 'Dispatched goods not yet received',
        ),
        (
          id: 'supply-delivery',
          label: 'Deliveries pending',
          guide: 'Current goods awaiting delivery',
        ),
        (
          id: 'supply-cancelled',
          label: 'Cancelled supplier orders',
          guide: 'Confirmed cancellations · selected period',
        ),
      ],
      _ => const [
        (
          id: 'received-full',
          label: 'Fully received',
          guide: 'Confirmed full receipts · selected period',
        ),
        (
          id: 'received-part',
          label: 'Partly received',
          guide: 'Receipts with goods still pending',
        ),
        (
          id: 'received-short',
          label: 'Shortages',
          guide: 'Recorded missing quantities',
        ),
        (
          id: 'received-damaged',
          label: 'Damage reported',
          guide: 'Receipts with damaged goods',
        ),
        (
          id: 'goods-without-bill',
          label: 'Goods received without bill',
          guide: 'Awaiting the supplier’s invoice',
        ),
        (
          id: 'bills-without-goods',
          label: 'Bills awaiting goods',
          guide: 'Invoice received before delivery',
        ),
      ],
    };
  @override
  Widget build(BuildContext context) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [

        FutureBuilder<WorkspaceAnalyticsSnapshot>(
          key: ObjectKey(_result),
          future: _result,
          builder: (context, result) {
            final snapshot = result.data;
            final request = _request;
            final valid =
                snapshot != null &&
                request != null &&
                snapshot.usableFor(request, DateTime.now());
            final verified =
                result.connectionState == ConnectionState.done &&
                valid && snapshot.state == WorkspaceAnalyticsState.verified;
            final loading =
                _result != null &&
                (result.connectionState != ConnectionState.done ||
                  (valid && snapshot.state == WorkspaceAnalyticsState.loading));
            final values = verified
                ? {for (final metric in snapshot.metrics) metric.id: metric}
                : <String, WorkspaceAnalyticsMetric>{};
            final rows = definitions(widget.report).where((row) => row.id != 'journey-checkout' ||
              storeAnalyticsMetricEligible(row.id, values[row.id])).toList();
            return Column(
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [

                if (verified) ...[
                  Text(
                    'Updated ${MaterialLocalizations.of(context).formatShortDate(snapshot.updatedAt!.toLocal())} · ${MaterialLocalizations.of(context).formatTimeOfDay(TimeOfDay.fromDateTime(snapshot.updatedAt!.toLocal()))}',
                    style: const TextStyle(fontSize: 12),
                  ),
                  Text('Records covered: ${MaterialLocalizations.of(context).formatShortDate(snapshot.coveredFrom!.toLocal())} ${MaterialLocalizations.of(context).formatTimeOfDay(TimeOfDay.fromDateTime(snapshot.coveredFrom!.toLocal()))} – ${MaterialLocalizations.of(context).formatShortDate(snapshot.coveredUntil!.toLocal())} ${MaterialLocalizations.of(context).formatTimeOfDay(TimeOfDay.fromDateTime(snapshot.coveredUntil!.toLocal()))}',
                    key: const Key('store-analytics-covered-period'),
                    style: const TextStyle(fontSize: 11, color: _OperatingPalette.secondary)),
                ],
                if (!loading && !verified)
                  const Padding(
                    padding: EdgeInsets.only(top: 4, bottom: 8),
                    child: Text(
                      'Report data unavailable · — does not mean zero.',
                      style: TextStyle(fontSize: 12),
                    ),
                  ),
                Wrap(
                  spacing: 8,
                  crossAxisAlignment: WrapCrossAlignment.center,
                  children: [
                    TextButton(
                      key: Key('analytics-measure-definitions-${widget.report}'),
                      onPressed: () => setState(() => _definitions = !_definitions),
                      child: Text(_definitions ? 'Hide explanations' : 'About these measures')),
                    if (widget.report == 'public')
                      Tooltip(
                        message: 'Store link sharing is not available yet.',
                        child: Semantics(
                          key: const Key('work-store-share-link-state'),
                          button: true,
                          enabled: false,
                          label: 'Share Store link. Store link sharing is not available yet.',
                          excludeSemantics: true,
                          child: TextButton.icon(
                            key: const Key('work-store-share-link'),
                            onPressed: null,
                            style: TextButton.styleFrom(
                              minimumSize: const Size(48, 48),
                              disabledForegroundColor: _AnalyticsChartPalette.secondary,
                            ),
                            icon: const Icon(Icons.share_outlined, size: 18),
                            label: const Text('Share Store link'),
                          ),
                        ),
                      ),
                  ],
                ),
                if (widget.report == 'journey') const Text('Separate stage counts · not a conversion funnel',
                  style: TextStyle(fontSize: 11, color: _AnalyticsChartPalette.secondary)),
                if (widget.report == 'supply') const Text('Independent supply statuses · do not add them together',
                  style: TextStyle(fontSize: 11, color: _AnalyticsChartPalette.secondary)),
                if (_definitions) Text(switch (widget.report) {
                  'public' => 'Visitors, visits and views are separate measures. Their counting definitions depend on the connected report source.',
                  'journey' => 'Stage counts may represent different measures. Compare conversion only for the same verified customer group.',
                  'supply' => 'Order and delivery statuses can overlap. A count does not establish delivered units.',
                  _ => 'Bill, receipt and shortage measures are independent. Counted receipts and missing units need their own confirmed definitions.',
                }, style: const TextStyle(fontSize: 11, color: _AnalyticsChartPalette.secondary)),
                for (final row in rows.where((row) => row.id != 'bills-without-goods')) ...[
                  if (row == rows.first || const {'visible-skus', 'interest-no-order', 'listing-corrections', 'enquiries', 'supply-acceptance', 'supply-cancelled', 'received-part', 'received-short', 'goods-without-bill', 'journey-left'}.contains(row.id))
                    Container(margin: const EdgeInsets.only(top: 8, bottom: 2),
                      padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
                      decoration: BoxDecoration(color: _AnalyticsChartPalette.reportTint(widget.report),
                        border: Border(left: BorderSide(width: 3, color: _AnalyticsChartPalette.reportAccent(widget.report)))),
                      child: Text(
                      row.id == 'visible-skus' ? 'Public listings · current position' :
                      row.id == 'interest-no-order' ? 'Customer interest · selected period' :
                      row.id == 'listing-corrections' ? 'Listing issues · current position' :
                      row.id == 'enquiries' ? 'Customer response · selected period' :
                      row.id == 'journey-left' ? 'Customer outcomes · selected period' :
                      row.id == 'received-part' ? 'Pending receipts · current position' :
                      row.id == 'goods-without-bill' ? 'Bill / goods reconciliation · current position' :
                      row.id == 'received-short' ? 'Receipt issues · selected period' :
                      row.id == 'supply-acceptance' ? 'Pending supply · current position' :
                      row.id == 'supply-cancelled' ? 'Cancelled orders · selected period' :
                      widget.report == 'public' ? 'Store activity · selected period' :
                      widget.report == 'journey' ? 'Journey stages · selected period' :
                      widget.report == 'supply' ? 'Supplier orders · selected period' : 'Goods received · selected period',
                      style: TextStyle(fontSize: 13, fontWeight: FontWeight.w700,
                        color: _AnalyticsChartPalette.reportAccent(widget.report)))),
                  if (row.id == 'goods-without-bill') LayoutBuilder(key: const Key('analytics-reconciliation-lanes'), builder: (context, box) {
                    var paired = box.maxWidth >= 320 && MediaQuery.textScalerOf(context).scale(1) <= 1.3;
                    for (final id in ['goods-without-bill', 'bills-without-goods']) {
                      final metric = values[id];
                      final text = metric?.state == WorkspaceAnalyticsState.verified &&
                        metric?.basis == WorkspaceAnalyticsBasis.currentPosition && metric?.unit == WorkspaceAnalyticsUnit.count
                          ? _formatStoreAmount(metric!.value!.toInt()) : '—';
                      final painter = TextPainter(text: TextSpan(text: text,
                        style: const TextStyle(fontSize: 20, fontWeight: FontWeight.w700)),
                        textDirection: Directionality.of(context), textScaler: MediaQuery.textScalerOf(context))..layout();
                      if (painter.width > box.maxWidth / 2 - 16) paired = false;
                      painter.dispose();
                    }
                    double titleHeight = 0;
                    if (paired) {
                      for (final item in rows.where((item) => item.id == 'goods-without-bill' || item.id == 'bills-without-goods')) {
                        final painter = TextPainter(text: TextSpan(text: item.label,
                          style: DefaultTextStyle.of(context).style.merge(const TextStyle(fontSize: 14, fontWeight: FontWeight.w600))),
                          textDirection: Directionality.of(context), textScaler: MediaQuery.textScalerOf(context))
                          ..layout(maxWidth: box.maxWidth / 2 - 16);
                        if (painter.height > titleHeight) titleHeight = painter.height;
                        painter.dispose();
                      }
                    }
                    Widget lane(String id, IconData icon) {
                      final item = rows.firstWhere((item) => item.id == id);
                      final metric = values[id];
                      final known = metric?.state == WorkspaceAnalyticsState.verified &&
                        metric?.basis == WorkspaceAnalyticsBasis.currentPosition && metric?.unit == WorkspaceAnalyticsUnit.count;
                      return Padding(padding: const EdgeInsets.all(8), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                        Icon(icon, color: _AnalyticsChartPalette.reportAccent('receiving'), size: 24),
                        const SizedBox(height: 4), SizedBox(height: paired ? titleHeight : null,
                          child: Text(item.label, style: const TextStyle(fontSize: 14, fontWeight: FontWeight.w600))),
                        Align(key: Key('analytics-receiving-value-$id'), alignment: Alignment.centerLeft,
                          child: LayoutBuilder(builder: (context, laneBox) {
                            final value = known ? _formatStoreAmount(metric!.value!.toInt()) : '—';
                            return Text(value, key: Key('store-analytics-value-$id'), softWrap: false,
                              style: TextStyle(fontSize: _analyticsNumberSize(context, value, known ? 20 : 14, laneBox.maxWidth),
                                fontWeight: FontWeight.w700));
                          })),
                        if (known || _definitions) Text(item.guide, style: const TextStyle(fontSize: 12, color: _AnalyticsChartPalette.secondary)),
                        if (known) Text('${metric!.coverage == WorkspaceAnalyticsCoverage.partial ? 'Partial · ' : ''}As of ${MaterialLocalizations.of(context).formatShortDate(metric.asOf!.toLocal())}', style: const TextStyle(fontSize: 11)),
                      ]));
                    }
                    final goods = lane('goods-without-bill', Icons.inventory_2_outlined);
                    final bill = lane('bills-without-goods', Icons.receipt_long_outlined);
                    return paired
                      ? Row(crossAxisAlignment: CrossAxisAlignment.start, children: [Expanded(child: goods), Expanded(child: bill)])
                      : Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [goods, bill]);
                  }) else Builder(
                    builder: (_) {
                      final metric = values[row.id];
                      final percentage = const {'order-conversion', 'cart-dropoff'}.contains(row.id);
                      final known = storeAnalyticsMetricEligible(row.id, metric);
                      final guide = metricGuide(row.id, row.guide, metric);
                      final stageIcon = switch (row.id) {
                        'journey-store' => Icons.storefront_outlined,
                        'journey-product' => Icons.inventory_2_outlined,
                        'journey-cart' => Icons.shopping_cart_outlined,
                        'journey-checkout' => Icons.fact_check_outlined,
                        'journey-order' => Icons.receipt_long_outlined,
                        'journey-completed' => Icons.shopping_bag_outlined,
                        'supply-acceptance' => Icons.pending_actions_outlined,
                        'supply-dispatch' => Icons.warehouse_outlined,
                        'supply-transit' => Icons.local_shipping_outlined,
                        'supply-delivery' => Icons.move_to_inbox_outlined,
                        'goods-without-bill' => Icons.inventory_2_outlined,
                        'bills-without-goods' => Icons.receipt_long_outlined,
                        'received-short' => Icons.inventory_outlined,
                        'received-damaged' => Icons.warning_amber_outlined,
                        'visitors' => Icons.people_outline,
                        'visible-skus' => Icons.visibility_outlined,
                        _ => null,
                      };
                      return Container(key: Key('analytics-provider-cell-${row.id}'),
                        padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 4),
                        decoration: BoxDecoration(color: known ? _AnalyticsChartPalette.reportTint(widget.report) :
                          const Color(0xFFF6F8FA),
                          border: Border(bottom: const BorderSide(color: _AnalyticsChartPalette.border, width: .5),
                            left: BorderSide(width: stageIcon == null ? 0 : 2,
                              color: stageIcon == null ? Colors.transparent : _AnalyticsChartPalette.reportAccent(widget.report).withValues(alpha: .25)))),
                        child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
                          _AnalyticsFigure(
                            label: Column(
                              crossAxisAlignment: CrossAxisAlignment.start,
                              children: [
                                Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
                                  if (stageIcon != null) ...[
                                    ExcludeSemantics(child: Icon(stageIcon, key: Key('analytics-journey-stage-${row.id}'),
                                      size: 18, color: _AnalyticsChartPalette.reportAccent(widget.report))),
                                    const SizedBox(width: 6),
                                  ],
                                  Expanded(child: Tooltip(message: guide, triggerMode: TooltipTriggerMode.tap, child: Text(
                                  row.label,
                                  style: const TextStyle(
                                    fontSize: 14,
                                    fontWeight: FontWeight.w600,
                                  ),
                                ))),
                                ]),
                                Container(key: row.id.startsWith('journey-') && stageIcon != null ? Key('analytics-stage-spine-${row.id}') : null,
                                  margin: EdgeInsets.only(left: stageIcon == null ? 0 : 9),
                                  padding: EdgeInsets.only(left: stageIcon == null ? 0 : 15, top: 4, bottom: 4),
                                  decoration: BoxDecoration(border: row.id.startsWith('journey-') && stageIcon != null && row.id != 'journey-completed'
                                    ? Border(left: BorderSide(width: 2, color: _AnalyticsChartPalette.border)) : null),
                                  child: known || _definitions ? Text(guide,
                                  style: const TextStyle(
                                    fontSize: 12,
                                    color: _OperatingPalette.secondary,
                                  ),
                                ) : const SizedBox(height: 2)),
                                if (known)
                                  Text(
                                    '${metric!.coverage == WorkspaceAnalyticsCoverage.partial ? 'Partial · ' : ''}${metric.basis == WorkspaceAnalyticsBasis.currentPosition ? 'As of' : 'Recorded through'} ${MaterialLocalizations.of(context).formatShortDate(metric.asOf!.toLocal())}',
                                    style: const TextStyle(fontSize: 11),
                                  ),
                              ],
                            ),
                          value: Text(
                            known
                                ? percentage ? '${metric!.value!.toStringAsFixed(1)}%' : _formatStoreAmount(metric!.value!.toInt())
                                : '—',
                            key: Key('store-analytics-value-${row.id}'),
                            style: TextStyle(
                              fontSize: known ? 20 : 14,
                              fontWeight: known ? FontWeight.w700 : FontWeight.w500,
                              color: known ? _AnalyticsChartPalette.ink : _AnalyticsChartPalette.secondary,
                            ),
                          ),
                          ),
                          if (known && percentage && metric!.value! >= 0 && metric.value! <= 100)
                            Padding(padding: const EdgeInsets.only(top: 8), child: ExcludeSemantics(
                              child: _AnalyticsChartReveal(id: 'percent-${row.id}', child: LinearProgressIndicator(key: Key('analytics-percent-${row.id}'),
                                value: metric.value! / 100, minHeight: 6,
                                borderRadius: BorderRadius.circular(3),
                                color: _AnalyticsChartPalette.sales,
                                backgroundColor: _AnalyticsChartPalette.emptyTrack)))),
                        ]));
                    },
                  ),
                ],
                if (widget.report == 'public')
                  for (final group in const [
                    (id: 'discovery-sources', title: 'How customers found you', dimension: WorkspaceAnalyticsDimension.discoverySource),
                    (id: 'broad-locations', title: 'Customer areas', dimension: WorkspaceAnalyticsDimension.broadLocation),
                    (id: 'most-viewed-products', title: 'Most-viewed products', dimension: WorkspaceAnalyticsDimension.product),
                    (id: 'products-without-orders', title: 'Products viewed without orders', dimension: WorkspaceAnalyticsDimension.product),
                  ]) Builder(builder: (_) {
                    final matches = verified ? snapshot.breakdowns.where((data) =>
                      data.id == group.id && data.dimension == group.dimension).toList()
                      : <WorkspaceAnalyticsBreakdown>[];
                    final data = matches.isEmpty ? null : matches.single;
                    return Padding(padding: const EdgeInsets.only(top: 12),
                      child: Container(key: Key('analytics-breakdown-${group.id}'), padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
                      decoration: const BoxDecoration(border: Border(bottom: BorderSide(color: _AnalyticsChartPalette.border))),
                      child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
                        Text(group.title, style: const TextStyle(fontSize: 14, fontWeight: FontWeight.w600)),
                        if (data == null) const Text('Not available yet', style: TextStyle(fontSize: 12))
                        else ...[
                          Text('${data.coverage == WorkspaceAnalyticsCoverage.complete ? 'Complete' : 'Partial'} coverage · ${data.source}', style: const TextStyle(fontSize: 11)),
                          if (data.rows.isEmpty) const Text('No recorded activity in covered data', style: TextStyle(fontSize: 12)),
                          for (final row in (data.rows.toList()..sort((a, b) => b.count.compareTo(a.count))).take(10))
                            _AnalyticsRankRow(groupId: group.id, row: row,
                              maximum: data.rows.fold<int>(0, (max, item) => item.count > max ? item.count : max)),
                        ],
                        if (group.dimension == WorkspaceAnalyticsDimension.broadLocation)
                          const Text('City, district or delivery-area summary', style: TextStyle(fontSize: 11)),
                      ])));
                  }),
                if (widget.report == 'journey')
                  const Padding(
                    padding: EdgeInsets.only(top: 12),
                    child: Text(
                      'Each stage needs the same tracked customer group before a drop-off rate can be calculated. Orders are your customers’ purchases—not supplier Restock.',
                      style: TextStyle(fontSize: 12),
                    ),
                  ),
              ],
            );
          },
        ),
      ],
    );
  }
}

