Future<void> _showWorkspacePickupSheet(
  BuildContext context,
  WorkSession session, {
  bool Function()? inputCurrent, bool Function()? displayCurrent,Listenable? ownerChanges,
}) async {
  if(inputCurrent?.call()==false)return;
  if (session.currentWorkspaceOrder?.isCustomerCollection == true) {
    context.go('/app/work/workspace/dashboard');
    return;
  }
  final pageContext = context;
  var pickupCode = '';
  String? error;
  await showModalBottomSheet<void>(
    context: context,
    isScrollControlled: true,
    useSafeArea: true,
    showDragHandle: true,
    builder: (sheetContext) => StatefulBuilder(
      builder: (context, setSheetState) => _purchaseCapturedOwnerPage(context,sheetContext,session,displayCurrent??inputCurrent,AnimatedPadding(
        duration: const Duration(milliseconds: 180),
        padding: EdgeInsets.fromLTRB(
          18,
          0,
          18,
          MediaQuery.viewInsetsOf(context).bottom +
              MediaQuery.viewPaddingOf(context).bottom +
              18,
        ),
        child: SingleChildScrollView(
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              const Text(
                'Confirm customer pickup',
                style: TextStyle(
                  color: MoolColors.navy,
                  fontSize: 20,
                  fontWeight: FontWeight.w900,
                ),
              ),
              Text(
                '${session.workspaceOrderCustomer} · ₹${session.workspaceOrderAmount}',
                style: const TextStyle(color: MoolColors.muted),
              ),
              const SizedBox(height: 4),
              const Text(
                'Enter the 6-digit pickup code shown to the customer. The invoice is created after confirmation.',
                style: TextStyle(color: MoolColors.muted),
              ),
              const SizedBox(height: 12),
              TextField(
                key: const Key('work-pickup-code'),
                autofocus: true,
                keyboardType: TextInputType.number,
                textInputAction: TextInputAction.done,
                maxLength: 6,
                onChanged: (value) => pickupCode = value,
                decoration: InputDecoration(
                  labelText: 'Customer pickup code',
                  errorText: error,
                  prefixIcon: const Icon(Icons.password_rounded),
                ),
              ),
              const SizedBox(height: 8),
              FilledButton.icon(
                key: const Key('work-pickup-confirm'),
                onPressed: session.workspaceHandoverBusy
                    ? null
                    : () async {
                        if(!sheetContext.mounted||ModalRoute.of(sheetContext)?.isCurrent!=true||inputCurrent?.call()==false)return;
                        final success = await session.verifyWorkspacePickup(
                          pickupCode,
                          inputCurrent:inputCurrent,
                        );
                        if (!sheetContext.mounted||displayCurrent?.call()==false) return;
                        if (!success) {
                          setSheetState(() => error = session.errorMessage);
                          return;
                        }
                        final invoice = session.latestWorkspaceInvoice;
                        if(ModalRoute.of(sheetContext)?.isCurrent!=true)return;
                        Navigator.of(sheetContext).pop();
                        await Future<void>.delayed(
                          const Duration(milliseconds: 260),
                        );
                        if (invoice != null && pageContext.mounted && displayCurrent?.call()!=false) {
                          await _showWorkspaceInvoiceSheet(
                            pageContext,
                            session,
                            invoice,
                          );
                        }
                      },
                icon: const Icon(Icons.verified_rounded),
                label: const Text('Confirm pickup'),
              ),
            ],
          ),
        ),
      ),ownerChanges:ownerChanges),
    ),
  );
}

String _workspaceInvoiceMessage(
  WorkSession session,
  WorkspaceCustomerInvoice invoice,
  String? invoiceAccount,
  String? invoiceStore,
  String invoiceStoreName,
) {
  final finance = session.workspaceFinance;
  final payment =
      finance?.accountScope == invoiceAccount &&
          finance?.workspaceId == invoiceStore &&
          session.activeWorkspace?.id == invoiceStore
      ? finance?.payments
            .where(
              (p) =>
                  p.invoiceId == invoice.id &&
                  p.orderId == invoice.orderId &&
                  p.valid,
            )
            .firstOrNull
      : null;
  final status = payment == null
      ? 'Payment status unavailable'
      : '${payment.label} · Received ${_purchaseAmount(payment.paidMinor)} · Due ${_purchaseAmount(payment.dueMinor)}';
  final billing = invoice.billingDetails;
  final customerDetails = [
    if (billing.name.trim().isNotEmpty) 'Customer: ${billing.name.trim()}',
    if (billing.business && billing.businessName.trim().isNotEmpty)
      'Business: ${billing.businessName.trim()}',
    if (billing.business && billing.gst.trim().isNotEmpty)
      'GST: ${billing.gst.trim()}',
    if (billing.address.trim().isNotEmpty)
      'Billing address: ${billing.address.trim()}',
  ].join('\n');
  return '${invoice.id} from $invoiceStoreName\n'
      '${customerDetails.isEmpty ? '' : '$customerDetails\n'}'
      '${invoice.items}\n'
      '${invoice.discountMinor == 0 ? '' : 'Subtotal ₹${_formatStoreMinorAmount(invoice.subtotalMinor)}\nDiscount −₹${_formatStoreMinorAmount(invoice.discountMinor)}\n'}'
      'Total ₹${_formatStoreMinorAmount(invoice.payableMinor)} · Payment method: ${invoice.payment}\n$status';
}

Future<void> _showWorkspaceInvoiceSheet(
  BuildContext context,
  WorkSession session,
  WorkspaceCustomerInvoice invoice, {bool Function()? ownerCurrent,Listenable? ownerChanges}
) async {
  if (ownerCurrent?.call() == false) return;
  final router = GoRouter.of(context);
  final returnRoute = GoRouterState.of(context).uri.toString();
  final account = session.workspaceFinance?.accountScope;
  final store = session.activeWorkspace?.id;
  final name = invoice.sellerName.trim().isNotEmpty
      ? invoice.sellerName
      : session.activeWorkspace?.name ?? session.workName;
  ModalRoute<bool>? route;
  final chat = await showModalBottomSheet<bool>(
    context: context,
    isScrollControlled: true,
    useSafeArea: true,
    showDragHandle: true,
    builder: (sheetContext) {
      route = ModalRoute.of<bool>(sheetContext);
      final surface = _StoreInvoiceSurface(
        session: session,
        invoice: invoice,ownerCurrent: ownerCurrent,ownerChanges: ownerChanges,
        onClose: () => Navigator.pop(sheetContext),
        onOpenChat: () => Navigator.pop(sheetContext, true),
      );
      return ownerCurrent == null ? surface : _StoreSalesOwnerSurface(current: ownerCurrent,changes: Listenable.merge([session,ownerChanges]),child: surface);
    },
  );
  if (chat != true || ownerCurrent?.call() == false) return;
  await route?.completed;
  if (!context.mounted || ownerCurrent?.call() == false ||
      session.activeWorkspace?.id != store ||
      session.workspaceFinance?.accountScope != account) {
    return;
  }
  router.push(
    Uri(
      path: '/app/chat/inbox',
      queryParameters: {
        'type': 'business',
        'return': returnRoute,
        'recipient': invoice.customer,
        'draft': _workspaceInvoiceMessage(
          session,
          invoice,
          account,
          store,
          name,
        ),
      },
    ).toString(),
  );
}

class _StoreInvoiceSurface extends StatefulWidget {
  const _StoreInvoiceSurface({
    required this.session,
    required this.invoice,
    required this.onClose,
    this.onOpenChat,
    this.onRecord,
    this.receiptEditor,
    this.embedded = false,
    this.counterAppearance = false,
    this.orderDetails = false,
    this.salesPresentation = false,
    this.ownerCurrent,this.ownerChanges,
    super.key,
  });
  final WorkSession session;
  final WorkspaceCustomerInvoice invoice;
  final VoidCallback onClose;
  final VoidCallback? onOpenChat;
  final ValueChanged<WorkspacePaymentRecord>? onRecord;
  final Widget? receiptEditor;
  final bool embedded;
  final bool counterAppearance;
  final bool orderDetails;
  final bool salesPresentation;
  final bool Function()? ownerCurrent;
  final Listenable? ownerChanges;
  @override
  State<_StoreInvoiceSurface> createState() => _StoreInvoiceSurfaceState();
}

class _StoreInvoiceSurfaceState extends State<_StoreInvoiceSurface> {
  final _invoiceScroll = ScrollController();
  final _invoiceActions = GlobalKey();
  void _showInvoiceActions() {
    final target = _invoiceActions.currentContext;
    if (target != null) {
      Scrollable.ensureVisible(target, alignment: 0,
          duration: const Duration(milliseconds: 180));
    }
  }

  @override
  void didUpdateWidget(covariant _StoreInvoiceSurface oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.receiptEditor != null && widget.receiptEditor == null) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted && _invoiceScroll.hasClients) _invoiceScroll.jumpTo(0);
      });
    }
  }

  @override
  void dispose() {
    _invoiceScroll.dispose();
    super.dispose();
  }

  WorkSession get session => widget.session;
  WorkspaceCustomerInvoice get invoice => widget.invoice;
  bool get _counterInvoice =>
      widget.counterAppearance ||
      session.workspaceOrders.any(
        (order) => order.id == invoice.orderId && order.source == 'Counter',
      );
  late final invoiceAccount = session.workspaceFinance?.accountScope;
  late final invoiceStore = session.activeWorkspace?.id;
  late final invoiceDeliveryScope = session.storeInvoiceDeliveryScope;
  late final invoiceStoreName = invoice.sellerName.trim().isNotEmpty
      ? invoice.sellerName
      : session.activeWorkspace?.name ?? session.workName;
  String? shareError;
  bool openingWhatsApp = false;
  void _openAdjustments(WorkspacePaymentRecord payment) {
    openAdjustments(context, session, invoice, payment, invoiceAccount, invoiceStore);
  }
  static void openAdjustments(BuildContext context, WorkSession session,
      WorkspaceCustomerInvoice invoice, WorkspacePaymentRecord payment,
      String? account, String? store) {
    if (account == null || store == null) return;
    showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      useSafeArea: true,
      builder: (context) => FractionallySizedBox(
        heightFactor: .9,
        child: AnimatedBuilder(
          animation: session,
          builder: (context, _) {
            final finance = session.workspaceFinance;
            final matching = finance?.payments.any(
              (p) => p.valid && p.invoiceId == invoice.id &&
                  p.orderId == payment.orderId &&
                  p.customerId == payment.customerId,
            ) ?? false;
            if (session.activeWorkspace?.id != store ||
                (finance != null && (finance.workspaceId != store ||
                    finance.accountScope != account))) {
              return const Center(child: Text('Return to this invoice’s Store to view it.'));
            }
            if (finance == null || !matching) {
              return Center(child: Padding(
                padding: const EdgeInsets.all(16),
                child: Text(finance == null
                    ? 'Payment records are unavailable. Close and reopen this invoice after records have loaded.'
                    : 'This invoice’s payment record is unavailable. Close and check its saved records before recording an adjustment.'),
              ));
            }
            return _StoreFinanceSurface(
              session: session,
              section: 'payments',
              returnsOnly: true,
              focus: (
                accountScope: account, workspaceId: store,
                orderId: payment.orderId, customerId: payment.customerId,
                payoutId: null, operationId: null,
              ),
            );
          },
        ),
      ),
    );
  }
  void _closeOwned() {
    if (widget.ownerCurrent != null && ModalRoute.of(context)?.isCurrent != true) return;
    widget.onClose();
  }
  void _openPdf() {
    if (widget.ownerCurrent != null && ModalRoute.of(context)?.isCurrent != true) return;
    if (widget.ownerCurrent?.call() == false) return;
    if (session.activeWorkspace?.id != invoiceStore ||
        session.workspaceFinance?.accountScope != invoiceAccount) {
      return;
    }
    final order = session.workspaceOrders
        .where((value) => value.id == invoice.orderId)
        .firstOrNull;
    final payment = session.workspaceFinance?.payments
        .where(
          (value) =>
              value.valid &&
              value.invoiceId == invoice.id &&
              value.orderId == invoice.orderId,
        )
        .firstOrNull;
    final request = WorkInvoicePdfRequest(
      accountId: invoiceAccount ?? '',
      storeId: invoiceStore ?? '',
      invoice: invoice,
      items: order?.itemSnapshots ?? const [],
      paymentStatus: payment == null
          ? 'Payment status unavailable'
          : '${payment.label} · Received ${_purchaseAmount(payment.paidMinor)} · Due ${_purchaseAmount(payment.dueMinor)}',
    );
    Navigator.of(context).push(
      MaterialPageRoute<void>(
        builder: (_) {
          final screen = WorkInvoicePdfScreen(request: request,source: createWorkInvoicePdfSource(),
            scopeChanges: Listenable.merge([session,widget.ownerChanges]),isCurrent: () => widget.ownerCurrent?.call() != false &&
              session.activeWorkspace?.id == invoiceStore && session.workspaceFinance?.accountScope == invoiceAccount);
          return widget.ownerCurrent == null ? screen : _StoreSalesOwnerSurface(current: widget.ownerCurrent!,
            changes: Listenable.merge([session,widget.ownerChanges]),child: screen);
        },
      ),
    );
  }

  @override
  void initState() {
    super.initState();
    // Freeze identity before any account/Store change can rebuild this view.
    invoiceAccount;
    invoiceStore;
    invoiceDeliveryScope;
    invoiceStoreName;
  }

  String invoiceMessage() => _workspaceInvoiceMessage(
    session,
    invoice,
    invoiceAccount,
    invoiceStore,
    invoiceStoreName,
  );

