  // Orders composes the existing invoice rows/totals and payment owners inline.
  // Other invoice callers retain their approved presentation and modal behavior.
  Widget _orderInvoice(WorkspacePaymentRecord? payment, bool canAdjust) {
    final localizations = MaterialLocalizations.of(context);
    final issued = invoice.issuedAt.toLocal();
    return Column(
      key: const Key('work-order-inline-invoice'),
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        Row(children: [
          Expanded(child: Text('Invoice · Issued ${localizations.formatShortDate(issued)}',
              style: const TextStyle(fontSize: 11, color: MoolColors.muted))),
          TextButton.icon(key: const Key('work-invoice-open-pdf'),
              onPressed: _openPdf,
              style: TextButton.styleFrom(minimumSize: const Size(48, 48),
                  padding: const EdgeInsets.symmetric(horizontal: 8),
                  textStyle: const TextStyle(fontSize: 12)),
              icon: const Icon(Icons.picture_as_pdf_outlined, size: 18),
              label: const Text('PDF')),
        ]),
        Text(invoice.id, key: const Key('work-order-invoice-reference'),
            style: const TextStyle(fontSize: 11, color: MoolColors.ink)),
        const SizedBox(height: 4),
        _InvoiceCollectionSummary(session: session, invoice: invoice,
            accountScope: invoiceAccount, storeId: invoiceStore, orderDetails: true, allowActions: widget.ownerCurrent == null),
        const Divider(height: 12),
        _invoiceItemRows(),
        _invoiceTotal(),
        if (payment != null && !session.workspaceFinanceStale)
          _recordedPayments(payment),
        KeyedSubtree(
          key: PageStorageKey((invoiceAccount, invoiceStore, invoice.id, 'billing-details')),
          child: ExpansionTile(
          key: const Key('work-invoice-details'), tilePadding: EdgeInsets.zero,
          minTileHeight: 48,
          shape: const Border(), collapsedShape: const Border(),
          title: const Text('Billing details', style: TextStyle(
              fontSize: 12, color: MoolColors.muted)),
          children: [Align(alignment: Alignment.centerLeft,
              child: Text([
                'Sold by: $invoiceStoreName', ...?invoice.seller?.detailLines,
                if (invoice.billingDetails.business && invoice.billingDetails.gst.isNotEmpty)
                  'Customer GST: ${invoice.billingDetails.gst}',
                if (invoice.billingDetails.address.isNotEmpty) invoice.billingDetails.address,
              ].join('\n'), style: const TextStyle(fontSize: 12, color: MoolColors.ink)))],
        )),
        if (canAdjust && !session.workspaceFinanceStale && payment != null)
          Align(alignment: Alignment.centerLeft, child: TextButton.icon(
              key: const Key('work-invoice-adjustments'),
              onPressed: () => _openAdjustments(payment),
              icon: const Icon(Icons.assignment_return_outlined, size: 18),
              label: const Text('Returns & refunds'),
              style: TextButton.styleFrom(textStyle: const TextStyle(fontSize: 12)))),
      ],
    );
  }

  @override
  Widget build(BuildContext context) {
    if (widget.ownerCurrent?.call() == false) return const SizedBox.shrink();
    if (session.activeWorkspace?.id == invoiceStore &&
        session.workspaceFinance == null && invoiceAccount != null) {
      return const Center(child: Text('Payment records are unavailable. Close and reopen this invoice after records have loaded.'));
    }
    if (session.activeWorkspace?.id != invoiceStore ||
        session.workspaceFinance?.accountScope != invoiceAccount) {
      return const Center(
        child: Text('Return to this invoice’s Store to view it.'),
      );
    }
    final finance = session.workspaceFinance;
    final payment =
        finance?.accountScope == invoiceAccount &&
            finance?.workspaceId == invoiceStore
        ? finance?.payments
              .where(
                (record) =>
                    record.valid &&
                    record.invoiceId == invoice.id &&
                    record.orderId == invoice.orderId,
              )
              .firstOrNull
        : null;
    final issued = invoice.issuedAt.toLocal();
    final paid = payment != null && payment.dueMinor == 0 &&
        payment.paidMinor > 0 && payment.paidMinor >= payment.amountMinor;
    final invoiceDate = '${issued.day.toString().padLeft(2, '0')}/${issued.month.toString().padLeft(2, '0')}/${issued.year}';
    final settlementLedger = finance?.customerLedgers.where((ledger) =>
        ledger.valid && ledger.accountScope == invoiceAccount &&
        ledger.workspaceId == invoiceStore &&
        ledger.customerId == payment?.customerId).firstOrNull;
    final adjusted = (payment?.refundedMinor ?? 0) > 0 ||
        payment?.state == WorkspacePaymentState.refundPending ||
        (finance?.customerLedgers.any(
          (ledger) => ledger.customerId == payment?.customerId &&
              (ledger.invoiceBalance(invoice.id)?.creditedMinor ?? 0) > 0,
        ) ?? false);
    final canAdjust = widget.ownerCurrent == null && payment != null &&
        (session.workspaceOrders.any((order) => order.id == invoice.orderId &&
            order.isCompleted && order.hasCompleteItemSnapshot) ||
        (finance?.customerLedgers.any((ledger) => ledger.customerId == payment.customerId &&
            (ledger.invoiceBalance(invoice.id)?.refundableMinor ?? 0) > 0) ?? false));
    if (widget.orderDetails) return _orderInvoice(payment, canAdjust);
    return StatefulBuilder(
      builder: (sheetContext, updateSheet) => SafeArea(
        top: false,
        bottom: !widget.embedded,
        child: Padding(
          padding: const EdgeInsets.fromLTRB(18, 8, 18, 18),
          child: SingleChildScrollView(
            controller: _invoiceScroll,
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                if (widget.salesPresentation)
                  Wrap(alignment: WrapAlignment.spaceBetween, crossAxisAlignment: WrapCrossAlignment.center,
                    spacing: 8, children: [
                      const Text('Invoice', key: Key('work-invoice-title'),
                        style: TextStyle(color: MoolColors.ink, fontSize: 18, fontWeight: FontWeight.w700)),
                      Wrap(crossAxisAlignment: WrapCrossAlignment.center, spacing: 4, children: [
                        if (payment != null && (!paid || canAdjust))
                          TextButton(key: const Key('work-invoice-jump-actions'),
                            style: TextButton.styleFrom(minimumSize: const Size(48, 48),
                              padding: const EdgeInsets.symmetric(horizontal: 6),
                              textStyle: const TextStyle(fontFamily: 'Inter', fontSize: 12)),
                            onPressed: _showInvoiceActions, child: const Text('Payment / returns')),
                        TextButton.icon(key: const Key('work-invoice-open-pdf'),
                          style: TextButton.styleFrom(minimumSize: const Size(48, 48),
                            padding: const EdgeInsets.symmetric(horizontal: 6),
                            textStyle: const TextStyle(fontFamily: 'Inter', fontSize: 12)),
                          onPressed: _openPdf, icon: const Icon(Icons.picture_as_pdf_outlined, size: 18),
                          label: const Text('PDF')),
                      ]),
                    ])
                else Row(
                  children: [
                    Expanded(
                      child: Text(
                        widget.counterAppearance
                            ? 'Invoice created'
                            : 'Invoice',
                        key: const Key('work-invoice-title'),
                        style: TextStyle(
                          color: MoolColors.ink,
                          fontSize: widget.counterAppearance ? 18 : 21,
                          fontWeight: FontWeight.w700,
                        ),
                      ),
                    ),
                    if (payment != null && (!paid || canAdjust) && !widget.salesPresentation) IconButton(
                      key: const Key('work-invoice-jump-actions'),
                      tooltip: 'Payment and return actions',
