class _DeliveryActivityCard extends StatelessWidget {
  const _DeliveryActivityCard({required this.session,this.assignmentReview=false,this.ownerCurrent,this.reviewPerform,this.reviewForeground,this.nativeReturnUri});
  final WorkSession session;final String? nativeReturnUri;
  final bool assignmentReview;final bool Function()? ownerCurrent,reviewForeground;final Future<void> Function(Future<void> Function())? reviewPerform;

  @override
  Widget build(BuildContext context) {
    final storeId = session.activeWorkspace?.id ?? session.workspaceId;
    final orderId = session.currentWorkspaceOrderId ?? 'current-store-order';
    final customer = session.workspaceOrderCustomer;
    final address = session.workspaceOrderAddress;
    final renderedStage = session.workspaceOrderStage;
    final storeName = session.activeWorkspace?.name ?? 'Store';
    final returnRoute = nativeReturnUri??GoRouterState.of(context).uri.toString();
    bool sameOrder() =>
        context.mounted && ownerCurrent?.call()!=false &&
        storeId == (session.activeWorkspace?.id ?? session.workspaceId) &&
        orderId == (session.currentWorkspaceOrderId ?? 'current-store-order') &&
        customer == session.workspaceOrderCustomer &&
        address == session.workspaceOrderAddress;
    final candidate = session.workspaceDeliveryAssignment;
    final assignment =
        candidate?.orderId ==
            (session.currentWorkspaceOrderId ?? 'current-store-order')
        ? candidate
        : null;
    final deliveryStage = switch (session.workspaceOrderStage) {
      'Delivery cancelled' => WorkspaceDeliveryStage.cancelled,
      'Delivery failed' => WorkspaceDeliveryStage.failed,
      _ => assignment?.deliveryStage,
    };
    final needsDeliveryRequest =
        renderedStage == 'Ready' &&
        session.workspaceOrderNeedsDelivery &&
        assignment == null;
    final bookingUnavailable = session.hasScopedWorkspaceOrder(orderId);
    final phone = workspaceCustomerMobile(customer);
    final canConfirmOwnDelivery =
        session.workspaceOrderFulfilment == 'Own delivery' &&
        session.currentWorkspaceOrder?.isClosed != true &&
        !session.hasScopedWorkspaceOrder(
          session.currentWorkspaceOrderId ?? '',
        ) &&
        const [
          WorkspaceDeliveryStage.pickedUp,
          WorkspaceDeliveryStage.outForDelivery,
        ].contains(deliveryStage);
    final stackContacts = MediaQuery.textScalerOf(context).scale(11) > 16;
    return SingleChildScrollView(
      key: const Key('work-activity-delivery'),
      child: Column(
      children: [
        Padding(
            padding: const EdgeInsets.all(14),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                const Text(
                  'Customer delivery',
                  style: TextStyle(
                    color: MoolColors.navy,
                    fontSize: 16,
                    fontWeight: FontWeight.w800,
                  ),
                ),
                const SizedBox(height: 10),
                Text(
                  session.workspaceOrderCustomer,
                  style: const TextStyle(
                    color: MoolColors.ink,
                    fontSize: 14,
                    fontWeight: FontWeight.w700,
                  ),
                ),
                const SizedBox(height: 5),
                Text(
                  assignment != null
                      ? 'Rider · ${assignment.partnerName}'
                      : needsDeliveryRequest
                      ? 'Order ready'
                      : (deliveryStage == WorkspaceDeliveryStage.cancelled ||
                                deliveryStage == WorkspaceDeliveryStage.failed
                            ? deliveryStage!.label
                            : 'Awaiting a delivery partner'),
                  key: const Key('work-delivery-status'),
                  style: const TextStyle(
                    color: MoolColors.ink,
                    fontSize: 15,
                    fontWeight: FontWeight.w700,
                  ),
                ),
                if (needsDeliveryRequest) ...[
                  const SizedBox(height: 8),
                  FilledButton.icon(
                    key: const Key('work-delivery-arrange'),
                    style: FilledButton.styleFrom(
                      minimumSize: const Size(48, 48),
                      padding: const EdgeInsets.symmetric(
                        horizontal: 8,
                        vertical: 10,
                      ),
                      textStyle: const TextStyle(
                        fontFamily: 'Inter',
                        fontSize: 13,
                        fontWeight: FontWeight.w700,
                      ),
                    ),
                    onPressed:
                        bookingUnavailable ||
                            session.busy ||
                            session.workspaceOperationsSyncing ||
                            session.workspaceHandoverBusy
                        ? null
                        : () {
                            if (sameOrder() &&
                                session.workspaceOrderStage == 'Ready' &&
                                session.workspaceOrderNeedsDelivery &&
                                session.workspaceDeliveryAssignment == null &&
                                !session.hasScopedWorkspaceOrder(orderId) &&
                                !session.busy &&
                                !session.workspaceOperationsSyncing &&
                                !session.workspaceHandoverBusy) {
                              _advanceDeskOrder(
                                session,
                                expectedOrderId: orderId,
                              );
                            }
                          },
                    icon: const Icon(Icons.delivery_dining_outlined, size: 18),
                    label: const Text(
                      'Arrange delivery',
                      textAlign: TextAlign.center,
                    ),
                  ),
                  if (bookingUnavailable)
                    const Text(
                      'Delivery booking is not available for this order yet.',
                      key: Key('work-delivery-booking-unavailable'),
                      style: TextStyle(color: MoolColors.muted, fontSize: 12),
                    ),
                ],
                if (assignment != null) ...[
                  Text(
                    '${assignment.vehicleLabel} · ${deliveryStage!.label}',
                    style: const TextStyle(
                      color: MoolColors.muted,
                      fontSize: 12,
                    ),
                  ),
                  const SizedBox(height: 8),
                  _DeliveryProgressTrack(stage: deliveryStage),
                  const SizedBox(height: 8),
                  if (deliveryStage.progressIndex >= 0 &&
                      deliveryStage != WorkspaceDeliveryStage.delivered)
                    _LiveCountdownText(
                      deadline: assignment.eta,
                      fallback: 'Arrival estimate unavailable',
                      prefix: 'Estimated arrival · ',
                      expiredLabel: 'Awaiting arrival update',
                      style: const TextStyle(
                        color: MoolColors.navy,
                        fontSize: 12,
                      ),
                    ),
                  Text(
                    assignment.updatedAt == null
                        ? 'Live rider location unavailable'
                        : 'Last update ${MaterialLocalizations.of(context).formatCompactDate(assignment.updatedAt!.toLocal())} ${MaterialLocalizations.of(context).formatTimeOfDay(TimeOfDay.fromDateTime(assignment.updatedAt!.toLocal()))} · Live location unavailable',
                    key: const Key('work-delivery-freshness'),
                    style: const TextStyle(
                      color: MoolColors.muted,
                      fontSize: 12,
                    ),
                  ),
                ],
                const Divider(height: 22),
                if (session.currentWorkspaceOrder case final order?) ...[
                  _StoreOrderAmount(
                    '₹${_formatStoreMinorAmount(order.payableMinor)}',
                    orderReference: order.id,
                    style: const TextStyle(
                      color: MoolColors.navy,
                      fontSize: 15,
                      fontWeight: FontWeight.w800,
                    ),
                  ),
                  Text(
                    session.workspaceOrderPaymentLabel(order),
                    style: const TextStyle(
                      color: MoolColors.muted,
                      fontSize: 12,
                    ),
                  ),
                  const SizedBox(height: 5),
                  Text(
                    '${order.id} · ${order.items}',
                    style: const TextStyle(
                      color: MoolColors.muted,
                      fontSize: 12,
                    ),
                  ),
                  const SizedBox(height: 5),
                ],
                Text(
                  session.workspaceOrderAddress.isEmpty
                      ? 'Customer address unavailable'
                      : session.workspaceOrderAddress,
                  style: const TextStyle(
                    color: MoolColors.muted,
                    fontSize: 12,
                    height: 1.4,
                  ),
                ),
                if (session.workspaceOperationsSyncError != null) ...[
                  const SizedBox(height: 10),
                  Text(
                    session.workspaceOperationsSyncError!,
                    style: const TextStyle(color: MoolColors.ink, fontSize: 12),
                  ),
                  TextButton(
                    key: const Key('work-delivery-retry'),
                    onPressed: session.workspaceOperationsSyncing
                        ? null
                        : () {
                            if(!sameOrder()||reviewForeground?.call()==false||ModalRoute.of(context)?.isCurrent!=true)return;
                            Future<void> retry()async{await session.retryWorkspaceDeliveryAssignment(inputCurrent:ownerCurrent);}
                            if(reviewPerform!=null){unawaited(reviewPerform!(retry));}else{unawaited(retry());}
                          },
                    child: const Text('Try again'),
                  ),
                ],
              ],
            ),
        ),
        const Divider(height: 1),
        Padding(
          padding: const EdgeInsets.fromLTRB(8, 4, 8, 8),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              if(!assignmentReview)Flex(
                direction: stackContacts ? Axis.vertical : Axis.horizontal,
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: stackContacts
                    ? CrossAxisAlignment.stretch
                    : CrossAxisAlignment.center,
                children: [
                  Flexible(
                    flex: stackContacts ? 0 : 1,
                    fit: FlexFit.tight,
                    child: TextButton.icon(
                      key: const Key('work-delivery-call-customer'),
                      onPressed: phone == null
                          ? null
                          : () async {
                              if (!sameOrder()) {
                                return;
                              }
                              final messenger = ScaffoldMessenger.of(context);
                              try {
                                if (await launchUrl(
                                  Uri(scheme: 'tel', path: phone),
                                )) {
                                  return;
                                }
                              } catch (_) {
                                // The OS phone handler is unavailable; no call occurred.
                              }
                              if (sameOrder()) {
                                messenger.showSnackBar(
                                  const SnackBar(
                                    content: Text(
                                      'Could not open your phone app. Please try again.',
                                    ),
                                  ),
                                );
                              }
                            },
                      style: TextButton.styleFrom(
                        minimumSize: const Size(48, 48),
                        padding: const EdgeInsets.symmetric(horizontal: 4),
                      ),
                      icon: const Icon(Icons.call_outlined, size: 18),
                      label: const Text('Call'),
                    ),
                  ),
                  Flexible(
                    flex: stackContacts ? 0 : 1,
                    fit: FlexFit.tight,
                    child: TextButton.icon(
                      key: const Key('work-delivery-chat-customer'),
                      onPressed: () {
                        if (!sameOrder()) {
                          return;
                        }
                        context.push(
                          Uri(
                            path: '/app/chat/inbox',
                            queryParameters: {
                              'return': returnRoute,
                              'type': 'business',
                              'recipient': customer,
                              'draft':
                                  'Delivery for order $orderId · $storeName',
                            },
                          ).toString(),
                        );
                      },
                      style: TextButton.styleFrom(
                        minimumSize: const Size(48, 48),
                        padding: const EdgeInsets.symmetric(horizontal: 4),
                      ),
                      icon: const Icon(
                        Icons.chat_bubble_outline_rounded,
                        size: 18,
                      ),
                      label: const Text('Chat'),
                    ),
                  ),
                  Flexible(
                    flex: stackContacts ? 0 : 1,
                    fit: FlexFit.tight,
                    child: TextButton.icon(
                      key: const Key('work-delivery-open-map'),
                      onPressed: address.isEmpty
                          ? null
                          : () async {
                              if (!sameOrder()) {
                                return;
                              }
                              final messenger = ScaffoldMessenger.of(context);
                              try {
                                if (await launchUrl(
                                  Uri.https('www.google.com', '/maps/search/', {
                                    'api': '1',
                                    'query': address,
                                  }),
                                  mode: LaunchMode.externalApplication,
                                )) {
                                  return;
                                }
                              } catch (_) {
                                // Opening an address is not a delivery event.
                              }
                              if (sameOrder()) {
                                messenger.showSnackBar(
                                  const SnackBar(
                                    content: Text(
                                      'Could not open Maps. Please try again.',
                                    ),
                                  ),
                                );
                              }
                            },
                      style: TextButton.styleFrom(
                        minimumSize: const Size(48, 48),
                        padding: const EdgeInsets.symmetric(horizontal: 4),
                      ),
                      icon: const Tooltip(
                        message: 'Customer address, not live rider tracking',
                        child: Icon(Icons.map_outlined, size: 18),
                      ),
                      label: const Text('Map'),
                    ),
                  ),
                ],
              ),
              if (canConfirmOwnDelivery&&!assignmentReview)
                FilledButton.icon(
                  key: const Key('work-activity-confirm-handover'),
                  onPressed: session.workspaceHandoverBusy
                      ? null
                      : () {
                          if (sameOrder() &&
                              renderedStage == session.workspaceOrderStage &&
                              identical(
                                candidate,
                                session.workspaceDeliveryAssignment,
                              )) {
                            _showWorkspaceHandoverSheet(context, session);
                          }
                        },
                  icon: const Icon(Icons.password_rounded, size: 18),
                  label: const Text('Confirm customer delivery'),
                )
              else if (!needsDeliveryRequest)
                Text(
                  switch (deliveryStage) {
                    WorkspaceDeliveryStage.cancelled ||
                    WorkspaceDeliveryStage.failed =>
                      'Contact the customer about this delivery.',
                    WorkspaceDeliveryStage.unknown =>
                      'Waiting for a confirmed delivery update.',
                    WorkspaceDeliveryStage.delivered => 'Delivery confirmed.',
                    _ =>
                      'Waiting for the delivery partner’s pickup or delivery confirmation.',
                  },
                  key: const Key('work-delivery-proof-pending'),
                  style: const TextStyle(
                    color: MoolColors.muted,
                    fontSize: 11,
                    height: 1.35,
                  ),
                ),
            ],
          ),
        ),
      ],
      ),
    );
  }
}

class _DeliveryProgressTrack extends StatelessWidget {
  const _DeliveryProgressTrack({required this.stage});

  final WorkspaceDeliveryStage stage;

  @override
  Widget build(BuildContext context) {
    const steps = ['Assigned', 'At store', 'Picked up', 'Delivered'];
    final currentIndex = stage.progressIndex;
    if (currentIndex < 0) return const SizedBox.shrink();
    return Container(
      key: const Key('work-delivery-progress'),
      padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 9),
      decoration: BoxDecoration(
        color: const Color(0xFFF4F5FF),
        borderRadius: BorderRadius.circular(16),
      ),
      child: LayoutBuilder(
        builder: (context, constraints) {
          final columns =
              constraints.maxWidth /
                      MediaQuery.textScalerOf(context).scale(1) >=
                  220
              ? 4
              : 2;
          return Wrap(
            runSpacing: 10,
            children: [
              for (var index = 0; index < steps.length; index++)
                SizedBox(
                  width: constraints.maxWidth / columns,
                  child: Semantics(
                    selected: index == currentIndex,
                    label:
                        '${steps[index]}: ${index < currentIndex
                            ? 'complete'
                            : index == currentIndex
                            ? 'current'
                            : 'pending'}',
                    excludeSemantics: true,
                    child: Column(
                      children: [
                        AnimatedContainer(
                          key: ValueKey('work-delivery-step-$index'),
                          duration: MediaQuery.disableAnimationsOf(context)
                              ? Duration.zero
                              : const Duration(milliseconds: 180),
                          width: 24,
                          height: 24,
                          decoration: BoxDecoration(
                            color: index <= currentIndex
                                ? MoolColors.navy
                                : const Color(0xFFDCE2F2),
                            shape: BoxShape.circle,
                          ),
                          child: Icon(
                            index < currentIndex
                                ? Icons.check_rounded
                                : index == currentIndex
                                ? Icons.circle
                                : Icons.circle_outlined,
                            color: index <= currentIndex
                                ? Colors.white
                                : MoolColors.muted,
                            size: index == currentIndex ? 10 : 14,
                          ),
                        ),
                        const SizedBox(height: 5),
                        Padding(
                          padding: const EdgeInsets.symmetric(horizontal: 3),
                          child: Text(
                            steps[index],
                            textAlign: TextAlign.center,
                            style: const TextStyle(
                              color: MoolColors.navy,
                              fontSize: 11,
                              fontWeight: FontWeight.w800,
                            ),
                          ),
                        ),
                      ],
                    ),
                  ),
                ),
            ],
          );
        },
      ),
    );
  }
}

Future<void> _showWorkspaceHandoverSheet(
  BuildContext context,
  WorkSession session, {
  bool Function()? inputCurrent,bool Function()? displayCurrent,Listenable? ownerChanges,
}) async {
  if(inputCurrent?.call()==false)return;
  // Freeze the order at entry, not when the sheet rebuilds or submits. The
  // model's in-flight response checks remain separate from this UI boundary.
  final account = session.contactDraftStore?.accountScope ??
      session.pendingProofStore?.accountScope;
  final storeId = session.activeWorkspace?.id ?? session.workspaceId;
  final order = session.currentWorkspaceOrder;
  final selectedId = session.currentWorkspaceOrderId;
  final customer = session.workspaceOrderCustomer;
  final address = session.workspaceOrderAddress;
  final stage = session.workspaceOrderStage;
  final fulfilment = session.workspaceOrderFulfilment;
  final needsDelivery = session.workspaceOrderNeedsDelivery;
  final assignment = session.workspaceDeliveryAssignment;
  // Encode now: retaining the ledger map would retain mutable quantities too.
  final originalLedger = order == null ? null : jsonEncode(order.toLedgerJson());
  final completedLedger = order == null ? null :
      jsonEncode({...order.toLedgerJson(), 'stage': 'Completed'});
  bool sameContext() =>
      account == (session.contactDraftStore?.accountScope ??
          session.pendingProofStore?.accountScope) &&
      storeId == (session.activeWorkspace?.id ?? session.workspaceId) &&
      selectedId == session.currentWorkspaceOrderId &&
      order != null && session.currentWorkspaceOrder?.id == order.id &&
      customer == session.workspaceOrderCustomer &&
      address == session.workspaceOrderAddress;
  bool canSubmit() => inputCurrent?.call()!=false && sameContext() &&
      identical(order, session.currentWorkspaceOrder) &&
      originalLedger == jsonEncode(session.currentWorkspaceOrder!.toLedgerJson()) &&
      order!.customer == customer && order.address == address &&
      order.stage == stage && order.needsDelivery == needsDelivery &&
      stage == session.workspaceOrderStage &&
      fulfilment == session.workspaceOrderFulfilment &&
      needsDelivery == session.workspaceOrderNeedsDelivery && needsDelivery &&
      fulfilment == 'Own delivery' && order.fulfilment == 'Own delivery' &&
      !order.isClosed && !order.isCustomerCollection &&
      !session.hasScopedWorkspaceOrder(order.id) &&
      identical(assignment, session.workspaceDeliveryAssignment) &&
      assignment?.orderId == order.id &&
      const [WorkspaceDeliveryStage.pickedUp, WorkspaceDeliveryStage.outForDelivery]
          .contains(assignment?.deliveryStage) &&
      !session.busy && !session.workspaceOperationsSyncing &&
      !session.workspaceHandoverBusy &&
      session.currentCollection?.needsReconciliation != true;
  bool completedAsExpected() => sameContext() &&
      session.workspaceOrderStage == 'Completed' &&
      fulfilment == session.workspaceOrderFulfilment &&
      needsDelivery == session.workspaceOrderNeedsDelivery &&
      identical(assignment, session.workspaceDeliveryAssignment) &&
      completedLedger == jsonEncode(session.currentWorkspaceOrder!.toLedgerJson());
  await showModalBottomSheet<void>(
    context: context,
    isScrollControlled: true,
    useSafeArea: true,
    showDragHandle: true,
    builder: (sheetContext) => _purchaseCapturedOwnerPage(sheetContext,sheetContext,session,displayCurrent??inputCurrent,_WorkspaceHandoverSheet(session: session,
        canSubmit: canSubmit, sameContext: sameContext,
        completedAsExpected: completedAsExpected,inputCurrent:inputCurrent),ownerChanges:ownerChanges),
  );
}

class _WorkspaceHandoverSheet extends StatefulWidget {
  const _WorkspaceHandoverSheet({required this.session,
      required this.canSubmit, required this.sameContext,
      required this.completedAsExpected,this.inputCurrent});

  final WorkSession session;
  final bool Function()? inputCurrent;
  final bool Function() canSubmit, sameContext, completedAsExpected;

  @override
  State<_WorkspaceHandoverSheet> createState() =>
      _WorkspaceHandoverSheetState();
}

class _WorkspaceHandoverSheetState extends State<_WorkspaceHandoverSheet> {
  final TextEditingController _controller = TextEditingController();
  String? _error;

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return AnimatedPadding(
      duration: const Duration(milliseconds: 180),
      padding: EdgeInsets.fromLTRB(
        18,
        0,
        18,
        MediaQuery.viewInsetsOf(context).bottom + 18,
      ),
      child: Column(
        mainAxisSize: MainAxisSize.min,
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          const Text(
            'Confirm customer handover',
            style: TextStyle(
              color: MoolColors.navy,
              fontSize: 20,
              fontWeight: FontWeight.w900,
            ),
          ),
          const Text(
            'Enter the 6-digit OTP shared by the customer after receiving the order.',
            style: TextStyle(color: MoolColors.muted),
          ),
          const SizedBox(height: 12),
          TextField(
            key: const Key('work-handover-otp'),
            controller: _controller,
            autofocus: true,
            keyboardType: TextInputType.number,
            maxLength: 6,
            decoration: InputDecoration(
              labelText: 'Customer delivery OTP',
              errorText: _error,
              prefixIcon: const Icon(Icons.password_rounded),
            ),
          ),
          const SizedBox(height: 8),
          FilledButton.icon(
            key: const Key('work-handover-confirm'),
            onPressed: widget.session.workspaceHandoverBusy
                ? null
                : () async {
                    if (!mounted || ModalRoute.of(this.context)?.isCurrent != true) return;
                    if (!widget.canSubmit()) {
                      _controller.clear();
                      setState(() => _error = 'This delivery has changed. Close and reopen it before entering the OTP.');
                      return;
                    }
                    final success = await widget.session
                        .verifyWorkspaceHandover(_controller.text,inputCurrent:widget.inputCurrent);
                    if (!mounted) return;
                    if (ModalRoute.of(this.context)?.isCurrent != true ||
                        !widget.sameContext()) {
                      _controller.clear();
                      return;
                    }
                    if (success && widget.completedAsExpected()) {
                      Navigator.of(this.context).pop();
                    } else if (!success && widget.canSubmit()) {
                      setState(() => _error = widget.session.errorMessage);
                    } else {
                      _controller.clear();
                      setState(() => _error = 'This delivery has changed. Close and reopen it before entering the OTP.');
                    }
                  },
            icon: const Icon(Icons.verified_rounded),
            label: const Text('Verify and complete order'),
          ),
        ],
      ),
    );
  }
}

