/// Rebuilds actions once at the deadline, independently of the digit ticker.
/// Expiry is not evidence of rejection, reassignment or any server outcome.
class _OrderDeadlineBoundary extends StatefulWidget {
  const _OrderDeadlineBoundary({required this.deadline, required this.builder,
    this.observeMetrics = false});
  final DateTime? deadline;
  final Widget Function(bool expired) builder;
  final bool observeMetrics;

  @override
  State<_OrderDeadlineBoundary> createState() => _OrderDeadlineBoundaryState();
}

class _OrderDeadlineBoundaryState extends State<_OrderDeadlineBoundary>
    with WidgetsBindingObserver {
  Timer? _timer;
  bool _expired = false;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    _schedule();
  }

  void _schedule() {
    _timer?.cancel();
    final remaining = widget.deadline?.difference(DateTime.now());
    _expired = remaining != null && remaining <= Duration.zero;
    if (remaining != null && !_expired) {
      _timer = Timer(remaining, () {
        if (mounted) setState(() => _expired = true);
      });
    }
  }

  @override
  void didUpdateWidget(covariant _OrderDeadlineBoundary oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.deadline != widget.deadline) _schedule();
  }

  @override
  void didChangeMetrics() {
    // Some Store working pages remove inherited keyboard insets. Opted-in
    // order actions must still observe the native View before rebuilding.
    if (mounted && widget.observeMetrics) setState(() {});
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.resumed) {
      _schedule();
      setState(() {});
    } else if (state == AppLifecycleState.paused) {
      _timer?.cancel();
    }
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    _timer?.cancel();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => widget.builder(_expired);
}

class _LiveCountdownText extends StatefulWidget {
  const _LiveCountdownText({
    required this.deadline,
    required this.fallback,
    required this.style,
    this.prefix = '',
    this.expiredLabel = 'Time ended',
  });

  final DateTime? deadline;
  final String fallback;
  final TextStyle style;
  final String prefix, expiredLabel;

  @override
  State<_LiveCountdownText> createState() => _LiveCountdownTextState();
}

class _LiveCountdownTextState extends State<_LiveCountdownText>
    with WidgetsBindingObserver {
  Timer? _timer;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    _restartTicker();
  }

  @override
  void didUpdateWidget(covariant _LiveCountdownText oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.deadline != widget.deadline) _restartTicker();
  }

  void _restartTicker() {
    _timer?.cancel();
    final deadline = widget.deadline;
    if (deadline == null || !deadline.isAfter(DateTime.now())) return;
    _timer = Timer.periodic(const Duration(seconds: 1), (timer) {
      if (!mounted) return;
      setState(() {});
      if (!deadline.isAfter(DateTime.now())) timer.cancel();
    });
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.resumed) {
      _restartTicker();
      setState(() {});
    } else if (state == AppLifecycleState.paused) {
      _timer?.cancel();
    }
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    _timer?.cancel();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final deadline = widget.deadline;
    var label = widget.fallback;
    if (deadline != null) {
      final remaining = deadline.difference(DateTime.now());
      final seconds = (remaining.inMilliseconds / 1000).ceil().clamp(
        0,
        1 << 31,
      );
      label = seconds == 0
          ? widget.expiredLabel
          : '${widget.prefix}${(seconds ~/ 60).toString().padLeft(2, '0')}:${(seconds % 60).toString().padLeft(2, '0')}';
    }
    return _StoreValueMotion(
      value: label,
      child: Text(
        label,
        style: widget.style.copyWith(
          fontFeatures: const [FontFeature.tabularFigures()],
        ),
      ),
    );
  }
}

Future<void> _showRejectOrderSheet(
  BuildContext context,
  WorkSession session, {
  bool Function()? inputCurrent,Listenable? ownerChanges,String? initialReason,VoidCallback? onConfirm,
}) async {
  if(inputCurrent?.call()==false)return;
  final storeId = session.activeWorkspace?.id ?? session.workspaceId;
  final orderId = session.currentWorkspaceOrderId;
  final stage = session.workspaceOrderStage;
  final reviewedOrder = session.currentWorkspaceOrder;
  final accountScope = session.contactDraftStore?.accountScope ??
      session.pendingProofStore?.accountScope;
  final anonymous = orderId == null && session.workspaceOrders.isEmpty;
  final displayed = anonymous ? session.visibleWorkspaceOrders.singleOrNull : reviewedOrder;
  if (stage != 'Confirmed' || displayed == null) {
    return;
  }
  String ledger(WorkspaceOrderRecord record) {
    if (record.operational case final exact?) {
      return jsonEncode([exact.realm, exact.viewerUserId, exact.reference.toJson(),
        exact.operationalSourceRevision, exact.revision, exact.stage]);
    }
    final facts = record.toLedgerJson();
    if (anonymous) {
      // Only the unsaved fallback timestamp is regenerated by the model.
      facts.remove('createdAt');
    }
    return jsonEncode(facts);
  }
  final capturedLedger = ledger(displayed);
  final capturedAmount = session.workspaceOrderAmount;
  final capturedQuantities = Map<String, int>.of(displayed.quantities);
  String promotionInputs() => jsonEncode({
    'discount': session.workspaceCounterDiscount.toJson(),
    'products': [for (final product in session.workspaceCatalogueItems)
      if ((capturedQuantities[product.id] ?? 0) > 0) product.toInventoryJson()],
  });
  final capturedPromotion = anonymous ? promotionInputs() : null;
  bool sameIdentity() => context.mounted && inputCurrent?.call()!=false &&
      storeId == (session.activeWorkspace?.id ?? session.workspaceId) &&
      accountScope == (session.contactDraftStore?.accountScope ??
          session.pendingProofStore?.accountScope);
  bool sameScope() => sameIdentity() && orderId == session.currentWorkspaceOrderId;
  bool eligible() {
    if (!sameScope() || session.workspaceOrderStage != 'Confirmed' ||
        session.busy || session.workspaceOperationsSyncing ||
        session.workspaceHandoverBusy || session.counterDraftSubmitting ||
        session.hasPendingOrderTime ||
        session.currentCollection?.needsReconciliation == true) {
      return false;
    }
    final current = anonymous
        ? (session.workspaceOrders.isEmpty ? session.visibleWorkspaceOrders.singleOrNull : null)
        : session.currentWorkspaceOrder;
    if (current == null || current.stage != 'Confirmed' || current.isClosed ||
        current.isCustomerCollection || ledger(current) != capturedLedger ||
        current.actionDeadline?.isAfter(DateTime.now()) == false) {
      return false;
    }
    if (current.isOperationalProjection &&
        !session.workspaceOrderCanAct(current.id, WorkOrderAction.reject)) {
      return false;
    }
    return anonymous
        ? current.id == 'current-store-order' &&
            session.workspaceOrderAmount == capturedAmount &&
            promotionInputs() == capturedPromotion
        : identical(current, reviewedOrder);
  }
  if (!eligible()) {
    return;
  }
  String? selectedReason=initialReason;
  final reason = await showDialog<String>(
    context: context,
    builder: (dialogContext) => StatefulBuilder(
      builder: (context, setDialogState) => _purchaseCapturedOwnerPage(context,dialogContext,session,inputCurrent,AlertDialog(
        key: const Key('work-reject-order-dialog'),
        scrollable: true,
        backgroundColor: const Color(0xFFFFFDFD),
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(24)),
        titlePadding: const EdgeInsets.fromLTRB(14, 14, 14, 0),
        title: Container(
          padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 10),
          decoration: BoxDecoration(
            color: const Color(0xFFFFE9E7),
            borderRadius: BorderRadius.circular(16),
          ),
          child: const Row(
            children: [
              Icon(Icons.cancel_outlined, color: Color(0xFFB42318), size: 24),
              SizedBox(width: 10),
              Expanded(child: Text('Reject order')),
            ],
          ),
        ),
        contentPadding: const EdgeInsets.fromLTRB(16, 8, 16, 14),
        actionsPadding: const EdgeInsets.fromLTRB(16, 0, 16, 14),
        actions: [
          Row(
            children: [
              Expanded(
                child: OutlinedButton(
                  onPressed: () {
                    if (dialogContext.mounted && ModalRoute.of(dialogContext)?.isCurrent == true) {
                      Navigator.of(dialogContext).pop();
                    }
                  },
                  child: const Text('Keep order', textAlign: TextAlign.center),
                ),
              ),
              const SizedBox(width: 8),
              Expanded(
                child: FilledButton(
                  style: FilledButton.styleFrom(
                    backgroundColor: const Color(0xFFB42318),
                    disabledBackgroundColor: const Color(0xFFE7E7EE),
                  ),
                  onPressed: selectedReason == null
                      ? null
                      : () {
                          if (dialogContext.mounted && ModalRoute.of(dialogContext)?.isCurrent == true) {
                            Navigator.of(dialogContext).pop(selectedReason);
                          }
                        },
                  child: const Text(
                    'Reject order',
                    textAlign: TextAlign.center,
                  ),
                ),
              ),
            ],
          ),
        ],
        content: ConstrainedBox(
          constraints: const BoxConstraints(maxWidth: 360),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              const Text(
                'Choose a reason, then confirm rejection.',
                style: TextStyle(color: MoolColors.muted),
              ),
              const SizedBox(height: 6),
              for (final option in const [
                'Product unavailable',
                'Cannot meet requested time',
                'Delivery unavailable',
                'Customer requested cancellation',
              ])
                Padding(
                  padding: const EdgeInsets.only(top: 4),
                  child: Material(
                    color: selectedReason == option
                        ? const Color(0xFFFFE9E7)
                        : const Color(0xFFF7F7FA),
                    shape: RoundedRectangleBorder(
                      borderRadius: BorderRadius.circular(14),
                      side: BorderSide(
                        color: selectedReason == option
                            ? const Color(0xFFE4574F)
                            : const Color(0xFFE7E7EE),
                      ),
                    ),
                    child: RadioListTile<String>(
                      dense: true,
                      visualDensity: VisualDensity.compact,
                      contentPadding: const EdgeInsets.symmetric(horizontal: 4),
                      activeColor: const Color(0xFFB42318),
                      value: option,
                      // ignore: deprecated_member_use
                      groupValue: selectedReason,
                      title: Text(option),
                      // ignore: deprecated_member_use
                      onChanged: (value) =>
                          setDialogState(() => selectedReason = value),
                    ),
                  ),
                ),
            ],
          ),
        ),
      ),ownerChanges:ownerChanges),
    ),
  );
  if (reason == null || !context.mounted) return;
  if (!sameIdentity()) {
    return;
  }
  if (!eligible()) {
    session.showNotice('This order changed. Review its latest status.');
    return;
  }
  onConfirm?.call();
  if(inputCurrent!=null&&orderId!=null&&session.hasScopedWorkspaceOrder(orderId)){
    await session.submitWorkspaceOrderAction(orderId,WorkOrderAction.reject,reason:reason,inputCurrent:inputCurrent);
  }else{session.cancelWorkspaceOrder(reason: reason);}
}

class _DashboardSyncBanner extends StatelessWidget {
  const _DashboardSyncBanner({required this.session});

  final WorkSession session;

  @override
  Widget build(BuildContext context) {
    final lastUpdated = session.workspaceLastUpdatedAt;
    final time = lastUpdated == null
        ? null
        : '${lastUpdated.hour.toString().padLeft(2, '0')}:${lastUpdated.minute.toString().padLeft(2, '0')}';
    final (
      icon,
      color,
      title,
      detail,
    ) = switch (session.workspaceDashboardState) {
      WorkspaceDashboardState.refreshing => (
        Icons.sync_rounded,
        MoolColors.navy,
        'Refreshing store activity',
        'Saved records remain available while the latest activity arrives.',
      ),
      WorkspaceDashboardState.offline => (
        Icons.cloud_off_outlined,
        const Color(0xFF9A4A00),
        'Showing saved store activity',
        time == null
            ? 'Reconnect to receive new orders and payment updates.'
            : 'Last updated $time. Reconnect to receive new activity.',
      ),
      WorkspaceDashboardState.failed => (
        Icons.error_outline_rounded,
        const Color(0xFFB42318),
        'Store activity could not be refreshed',
        session.workspaceDashboardError.isEmpty
            ? 'Your saved records are unchanged. Try again shortly.'
            : session.workspaceDashboardError,
      ),
      WorkspaceDashboardState.ready => (
        Icons.check_circle_outline_rounded,
        const Color(0xFF08765D),
        'Store activity is up to date',
        time == null ? 'Ready for today.' : 'Updated $time.',
      ),
    };
    return Container(
      key: const Key('work-dashboard-sync-state'),
      padding: const EdgeInsets.all(10),
      decoration: BoxDecoration(
        color: color.withValues(alpha: .07),
        borderRadius: BorderRadius.circular(12),
        border: Border.all(color: color.withValues(alpha: .2)),
      ),
      child: Row(
        children: [
          Icon(icon, color: color, size: 20),
          const SizedBox(width: 8),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  title,
                  style: const TextStyle(
                    color: MoolColors.ink,
                    fontSize: 12,
                    fontWeight: FontWeight.w900,
                  ),
                ),
                Text(
                  detail,
                  style: const TextStyle(
                    color: MoolColors.muted,
                    fontSize: 10.5,
                    height: 1.25,
                  ),
                ),
              ],
            ),
          ),
          if (session.workspaceDashboardState ==
              WorkspaceDashboardState.refreshing)
            const SizedBox(
              width: 20,
              height: 20,
              child: CircularProgressIndicator(strokeWidth: 2.2),
            )
          else if (session.workspaceDashboardState ==
                  WorkspaceDashboardState.offline ||
              session.workspaceDashboardState == WorkspaceDashboardState.failed)
            IconButton(
              key: const Key('work-dashboard-retry'),
              tooltip: 'Refresh store activity',
              onPressed: session.retryWorkspaceDashboard,
              icon: const Icon(Icons.refresh_rounded),
            ),
        ],
      ),
    );
  }
}

