class _WorkspaceSearchSurface extends StatelessWidget {
  const _WorkspaceSearchSurface({
    required this.session,
    required this.query,
    this.ordersOnly = false,
    required this.scrollController,
    required this.onClear,
    required this.onOpenRecord,
  });

  final WorkSession session;
  final String query;
  final bool ordersOnly;
  final ScrollController scrollController;
  final VoidCallback onClear;
  final ValueChanged<_WorkspaceSearchRecord> onOpenRecord;

  @override
  Widget build(BuildContext context) {
    final normalized = query.trim().toLowerCase();
    final results = _workspaceSearchRecords(session, normalized,
        ordersOnly: ordersOnly)
        .where((record) =>
            !ordersOnly || record.kind == _WorkspaceSearchKind.order)
        .toList();
    return AnimatedSwitcher(
      key: const Key('work-dashboard-search-screen'),
      // Repeated empty/results states can overlap outgoing fades. Let the
      // switcher give each transition its own identity.
      transitionBuilder: (child, animation) =>
          FadeTransition(opacity: animation, child: child),
      duration: MediaQuery.of(context).disableAnimations
          ? Duration.zero
          : const Duration(milliseconds: 160),
      child: results.isEmpty
          ? ordersOnly
              ? Align(
                  key: const Key('work-dashboard-search-empty'),
                  alignment: AlignmentDirectional.topStart,
                  child: SingleChildScrollView(
                    keyboardDismissBehavior: ScrollViewKeyboardDismissBehavior.onDrag,
                    padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 8),
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(normalized.isEmpty ? 'No saved orders yet' : 'No matching order',
                          style: const TextStyle(color: MoolColors.navy,
                            fontSize: 14, fontWeight: FontWeight.w600)),
                        const SizedBox(height: 4),
                        Text(normalized.isEmpty
                            ? 'Saved orders will appear here.'
                            : 'Try the customer’s name, phone or order number.',
                          style: const TextStyle(color: MoolColors.ink, fontSize: 12)),
                      ],
                    ),
                  ),
                )
              : Center(
              key: const Key('work-dashboard-search-empty'),
              child: SingleChildScrollView(
                keyboardDismissBehavior:
                    ScrollViewKeyboardDismissBehavior.onDrag,
                child: Padding(
                  padding: const EdgeInsets.all(MoolSpacing.lg),
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      const Icon(
                        Icons.manage_search_rounded,
                        size: 46,
                        color: MoolColors.muted,
                      ),
                      const SizedBox(height: MoolSpacing.sm),
                      Text(
                        ordersOnly
                            ? (normalized.isEmpty
                                ? 'No saved orders yet'
                                : 'No matching order')
                            : normalized.isEmpty
                            ? 'Search products, orders, customers or records'
                            : 'No matching store record',
                        textAlign: TextAlign.center,
                        style: const TextStyle(
                          color: MoolColors.navy,
                          fontSize: 17,
                          fontWeight: FontWeight.w900,
                        ),
                      ),
                      if (normalized.isNotEmpty) ...[
                        const SizedBox(height: MoolSpacing.sm),
                        TextButton.icon(
                          key: const Key('work-dashboard-search-clear'),
                          onPressed: onClear,
                          icon: const Icon(Icons.close_rounded),
                          label: const Text('Clear search'),
                        ),
                      ],
                    ],
                  ),
                ),
              ),
            )
          : ListView.separated(
              key: const Key('work-dashboard-search-results'),
              controller: scrollController,
              keyboardDismissBehavior: ScrollViewKeyboardDismissBehavior.onDrag,
              padding: EdgeInsets.fromLTRB(
                MediaQuery.textScalerOf(context).scale(1) >= 2
                    ? 8
                    : MoolSpacing.md,
                MoolSpacing.sm,
                MediaQuery.textScalerOf(context).scale(1) >= 2
                    ? 8
                    : MoolSpacing.md,
                MoolSpacing.xl,
              ),
              itemCount: results.length,
              separatorBuilder: (_, _) =>
                  const SizedBox(height: MoolSpacing.xs),
              itemBuilder: (context, index) {
                final destination = results[index];
                if (ordersOnly) {
                  final order = session.visibleWorkspaceOrders
                      .where((record) => record.id == destination.entityId).firstOrNull;
                  if (order == null) return const SizedBox.shrink();
                  return _OrdersHistoryRow(
                    session: session, order: order,
                    searchResult: true,
                    onOpen: () => onOpenRecord(destination),
                  );
                }
                return _WorkspaceNavigationRow(
                  keyName: 'work-search-${destination.id}',
                  icon: destination.icon,
                  title: destination.title,
                  detail: destination.detail,
                  amount: destination.amount,
                  wideMoney: destination.kind == _WorkspaceSearchKind.purchase,
                  amountLabel: switch (destination.kind) {
                    _WorkspaceSearchKind.order => 'Order total',
                    _WorkspaceSearchKind.invoice => 'Invoice total',
                    _WorkspaceSearchKind.purchase => 'Purchase total',
                    _ => 'Price',
                  },
                  onTap: () => onOpenRecord(destination),
                );
              },
            ),
    );
  }
}

String _customerBalanceText(WorkspaceCustomerRecord customer) =>
    !customer.balanceAvailable
    ? 'Balance unavailable'
    : _purchaseAmount(customer.amountDueMinor);

String _purchaseAmount(int minor) {
  final magnitude = minor.abs();
  return '${minor < 0 ? '−' : ''}₹${_formatStoreAmount(magnitude ~/ 100)}'
      '${magnitude % 100 == 0 ? '' : '.${(magnitude % 100).toString().padLeft(2, '0')}'}';
}

class _StoreReceiptEditor extends StatefulWidget {
  const _StoreReceiptEditor({
    super.key,
    required this.session,
    required this.purchase,
    this.ownerCurrent,this.assistantContinue=false,
  });
  final bool Function()? ownerCurrent;final bool assistantContinue;
  final WorkSession session;
  final WorkspacePurchaseRecord purchase;
  @override
  State<_StoreReceiptEditor> createState() => _StoreReceiptEditorState();
}

class _StoreReceiptEditorState extends State<_StoreReceiptEditor> {
  bool _open = false, _loading = false, _restored = false;
  final _counts = <String, TextEditingController>{};
  final _returns = <String, TextEditingController>{};
  final _problems = <String, WorkspaceReceiptProblem>{};
  final _note = TextEditingController();
  final _noteKey = GlobalKey();

  @override void initState(){super.initState();if(widget.assistantContinue)WidgetsBinding.instance.addPostFrameCallback((_){if(mounted)unawaited(_start(readOnly:true));});}

  bool get _capturedOwnerCurrent => mounted && widget.ownerCurrent?.call() != false;
  Future<void> _start({bool issue = false,bool readOnly=false}) async {
    if (!_capturedOwnerCurrent) return;
    setState(() {
      _open = true;
      _loading = true;
    });
    final session = widget.session;
    await session.loadWorkspaceReceiptDraft(widget.purchase);
    if (!_capturedOwnerCurrent) return;
    if (!readOnly && session.workspaceReceiptDraftLoaded(widget.purchase) &&
        session.workspaceReceiptDraft(widget.purchase) == null) {
      // Bind even an empty draft to the lines currently being checked.
      await session.saveWorkspaceReceiptDraft(
        widget.purchase,
        countedPacks: const {},
        problems: const {},
        note: '',
      );
    }
    if (!_capturedOwnerCurrent) return;
    final draft = session.workspaceReceiptDraft(widget.purchase);
    if (!_restored && draft != null) {
      for (final line in draft.lines) {
        _counts[line.id] = TextEditingController(
          text: draft.countedPacks[line.id] ?? '',
        );
        _returns[line.id] = TextEditingController(
          text: draft.returnedPacks[line.id] ?? '',
        );
      }
      _problems.addAll(draft.problems);
      _note.text = draft.note;
      _restored = true;
    }
    setState(() => _loading = false);
    if (issue && _restored) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        final target = _noteKey.currentContext;
        if (mounted && target != null) {
          unawaited(Scrollable.ensureVisible(target, alignment: .3));
        }
      });
    }
  }

  Future<void> _save() async {
    if (!_capturedOwnerCurrent) return;
    await widget.session.saveWorkspaceReceiptDraft(
      widget.purchase,
      countedPacks: _counts.map(
        (id, controller) => MapEntry(id, controller.text),
      ),
      problems: _problems,
      returnedPacks: _returns.map(
        (id, controller) => MapEntry(id, controller.text),
      ),
      note: _note.text,
    );
    if (mounted) setState(() {});
  }

  @override
  void dispose() {
    for (final controller in _counts.values) {
      controller.dispose();
    }
    for (final controller in _returns.values) {
      controller.dispose();
    }
    _note.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final session = widget.session;
    final purchase = widget.purchase;
    final draft = session.workspaceReceiptDraft(purchase);
    final ownReviewReceipt =
        draft != null &&
        session.canConfirmStoreReviewReceipt(purchase) &&
        purchase.receiptReference?.startsWith('TEST-') == true &&
        draft.matchesPurchasedItems(purchase);
    final lines = _open && draft != null && !ownReviewReceipt
        ? draft.lines
        : purchase.lines;
    final message = session.workspaceReceiptDraftMessage(purchase);
    final enlarged = MediaQuery.textScalerOf(context).scale(14) > 21;
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        if (!_open)
          Wrap(
            spacing: 8,
            children: [
              TextButton.icon(
                key: const Key('work-receipt-start'),
                onPressed: () => _start(),
                icon: const Icon(Icons.inventory_2_outlined),
                label: const Text('Receive stock'),
                style: TextButton.styleFrom(minimumSize: const Size(48, 48)),
              ),
              TextButton(
                key: const Key('work-receipt-report'),
                onPressed: () => _start(issue: true),
                style: TextButton.styleFrom(minimumSize: const Size(48, 48)),
                child: const Text('Report issue'),
              ),
            ],
          )
        else ...[
          Row(
            children: [
              const Expanded(
                child: Text(
                  'Check delivery',
                  style: TextStyle(
                    fontWeight: FontWeight.w700,
                    color: MoolColors.navy,
                  ),
                ),
              ),
              TextButton(
                key: const Key('work-receipt-close'),
                onPressed: () {
                  FocusScope.of(context).unfocus();
                  setState(() => _open = false);
                },
                style: TextButton.styleFrom(minimumSize: const Size(48, 48)),
                child: const Text('Close'),
              ),
            ],
          ),
          const Text(
            'Count the packs in this delivery. Stock stays unchanged until the receipt is confirmed.',
            style: TextStyle(fontSize: 12, color: MoolColors.muted),
          ),
          if (_loading) const Text('Opening your draft…'),
          if (!_loading && !_restored)
            TextButton(
              key: const Key('work-receipt-retry-open'),
              onPressed: () => _start(),
              child: const Text('Try again'),
            ),
          if (draft != null &&
              !draft.matchesSnapshot(purchase) &&
              !ownReviewReceipt)
            const Padding(
              padding: EdgeInsets.symmetric(vertical: 8),
              child: Text(
                'Delivery updated. Close to compare the latest items with your saved checks.',
                key: Key('work-receipt-stale'),
                style: TextStyle(fontSize: 12, fontWeight: FontWeight.w600),
              ),
            ),
        ],
        for (final line in lines)
          Padding(
            key: ValueKey('work-purchase-line-${line.id}'),
            padding: const EdgeInsets.symmetric(vertical: 10),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  '${line.name}${line.pack.isEmpty ? '' : ' · ${line.pack}'}',
                  style: const TextStyle(fontWeight: FontWeight.w700),
                ),
                Text('${_purchaseAmount(line.unitPriceMinor)} / pack'),
                Text(
                  'Ordered ${line.orderedPacks} packs · Received ${line.receivedPacks == null ? 'not confirmed' : '${line.receivedPacks} packs'}',
                ),
                if (line.receivedPacks != null &&
                    line.receivedPacks != line.orderedPacks)
                  Text(
                    line.receivedPacks! < line.orderedPacks
                        ? '${line.orderedPacks - line.receivedPacks!} packs outstanding'
                        : '${line.receivedPacks! - line.orderedPacks} extra packs reported',
                    style: const TextStyle(
                      fontSize: 12,
                      fontWeight: FontWeight.w600,
                    ),
                  ),
                if (_open && _restored) ...[
                  const SizedBox(height: 8),
                  TextField(
                    key: ValueKey('work-receipt-count-${line.id}'),
                    controller: _counts[line.id],
                    keyboardType: TextInputType.number,
                    textInputAction: TextInputAction.next,
                    decoration: InputDecoration(
                      labelText: 'Packs checked',
                      errorText:
                          (_counts[line.id]?.text.trim().isNotEmpty ?? false) &&
                              draft?.counted(line.id) == null
                          ? 'Enter a whole number of packs.'
                          : null,
                      errorMaxLines: 3,
                    ),
                    onChanged: (_) {
                      unawaited(_save());
                    },
                  ),
                  if (session.canConfirmStoreReviewReceipt(purchase))
                    TextField(
                      key: ValueKey('work-supplier-return-count-${line.id}'),
                      controller: _returns[line.id],
                      keyboardType: TextInputType.number,
                      decoration: const InputDecoration(
                        labelText: 'Returned packs',
                        helperText:
                            'Include any packs already returned for this delivery.',
                        helperMaxLines: 3,
                      ),
                      onChanged: (_) {
                        unawaited(_save());
                      },
                    ),
                  const SizedBox(height: 8),
                  DropdownButtonFormField<String>(
                    key: ValueKey('work-receipt-problem-${line.id}'),
                    initialValue: _problems[line.id]?.name ?? 'none',
                    isExpanded: true,
                    isDense: !enlarged,
                    itemHeight: null,
                    decoration: const InputDecoration(labelText: 'Item issue'),
                    items: [
                      const DropdownMenuItem(
                        value: 'none',
                        child: Text('No issue noted'),
                      ),
                      for (final problem in WorkspaceReceiptProblem.values)
                        DropdownMenuItem(
                          value: problem.name,
                          child: Text(problem.label),
                        ),
                    ],
                    onChanged: (value) {
                      if (value == null) return;
                      if (value == 'none') {
                        _problems.remove(line.id);
                      } else {
                        _problems[line.id] = WorkspaceReceiptProblem.values
                            .byName(value);
                      }
                      unawaited(_save());
                    },
                  ),
                ],
              ],
            ),
          ),
        if (_open && _restored) ...[
          TextField(
            key: _noteKey,
            controller: _note,
            minLines: 1,
            maxLines: enlarged ? 2 : 3,
            maxLength: 2000,
            decoration: const InputDecoration(
              labelText: 'Delivery note',
              helperText: 'Add details if needed.',
              helperMaxLines: 3,
              helperStyle: TextStyle(fontSize: 12),
              counterStyle: TextStyle(fontSize: 11),
            ),
            onChanged: (_) {
              unawaited(_save());
            },
          ),
          if (session.canConfirmStoreReviewReceipt(purchase))
            FilledButton.tonal(
              key: const Key('work-receipt-confirm-test'),
              onPressed: _loading
                  ? null
                  : () async {
                      setState(() => _loading = true);
                      try {
                        await _save();
                        if (!_capturedOwnerCurrent) return;
                        await session.confirmStoreReviewReceipt(purchase);
                      } finally {
                        if (mounted) {
                          setState(() => _loading = false);
                        }
                      }
                    },
              child: const Text('Confirm test receipt'),
            )
          else
            const Text(
              'Sending this receipt is not available yet.',
              style: TextStyle(fontSize: 12, color: MoolColors.muted),
            ),
          if (session.canConfirmStoreReviewReceipt(purchase))
            TextButton(
              key: const Key('work-supplier-return-confirm-test'),
              onPressed: _loading
                  ? null
                  : () async {
                      setState(() => _loading = true);
                      try {
                        await _save();
                        if (!_capturedOwnerCurrent) return;
                        await session.confirmStoreReviewSupplierReturn(
                          purchase,
                        );
                      } finally {
                        if (mounted) {
                          setState(() => _loading = false);
                        }
                      }
                    },
              child: const Text('Confirm test return'),
            ),
        ],
        if (_open && message != null)
          Text(
            message,
            key: const Key('work-receipt-save-state'),
            style: const TextStyle(fontSize: 12),
          ),
        if (_open &&
            _restored &&
            message?.startsWith('Draft not saved') == true)
          TextButton(
            key: const Key('work-receipt-retry-save'),
            onPressed: _save,
            child: const Text('Retry saving'),
          ),
      ],
    );
  }
}

/// Presentation only: number ambiguous choices against the complete ledger,
/// never the filtered picker. Recorded order is not physical arrival order.
@visibleForTesting
String storeBillGoodsReceiptLabel(
  Iterable<WorkspaceSupplierGoodsReceipt> receipts,
  WorkspaceSupplierGoodsReceipt receipt,
  WorkspaceSupplierGoodsReceiptLine line,
) {
  final base = '${receipt.reference} · ${receipt.deliveredOn} · ${line.purchaseUnit}';
  final group = [
    for (final other in receipts)
      if (other.reference == receipt.reference && other.deliveredOn == receipt.deliveredOn)
        for (final item in other.lines)
          if (item.productId == line.productId && item.purchaseUnit == line.purchaseUnit)
            (other, item),
  ]..sort((a, b) {
      final time = a.$1.recordedAt.compareTo(b.$1.recordedAt);
      if (time != 0) return time;
      final identity = a.$1.id.compareTo(b.$1.id);
      return identity != 0 ? identity : a.$2.sourceLineId.compareTo(b.$2.sourceLineId);
    });
  if (group.length < 2) return base;
  final index = group.indexWhere((pair) =>
    pair.$1.id == receipt.id && pair.$2.sourceLineId == line.sourceLineId);
  if (index < 0) return base;
  return '$base\nReceipt record ${index + 1} · Receipt line totals: '
    'Accepted ${_ReceivingLineInput._quantity(line.acceptedMilli)} ${line.purchaseUnit} · '
    'Damaged ${_ReceivingLineInput._quantity(line.damagedMilli)} ${line.purchaseUnit}';
}

/// Matches immutable supplier records; this surface never receives Stock or pays.
Widget _purchaseBillTaskSummary(Widget label, Widget value) => Row(
  crossAxisAlignment: CrossAxisAlignment.center,
  children: [Expanded(flex: 4, child: label), const SizedBox(width: 8),
    Expanded(flex: 6, child: Align(alignment: Alignment.centerRight, child: value))]);

class _StoreBillGoodsMatch extends StatefulWidget {
  const _StoreBillGoodsMatch({super.key, required this.session, required this.copy,
    required this.onOpenCopy, this.summary, this.actions, this.onBeforeOpen, this.headerBuilder, this.ownerCurrent, this.assistantReadOnlyOpen = false,this.receivingInitial});
  final bool Function()? ownerCurrent;
  final bool assistantReadOnlyOpen;final StoreReceivingReviewInitial? receivingInitial;
  final WorkSession session;
  final WorkspacePurchaseSavedCopy copy;
  final Future<void> Function(WorkspacePurchaseSavedCopy copy) onOpenCopy;
  final Widget Function(bool verified)? summary;
  final Widget Function(Widget header)? headerBuilder;
  final Widget? actions;
  final Future<bool> Function()? onBeforeOpen;
  @override
  State<_StoreBillGoodsMatch> createState() => _StoreBillGoodsMatchState();
}

class _StoreBillGoodsMatchState extends State<_StoreBillGoodsMatch>
    with AutomaticKeepAliveClientMixin<_StoreBillGoodsMatch> {
  @override
  bool get wantKeepAlive => true;
  bool _receivingMatchInitialAttempted=false,_receivingMatchRetired=false;
  StoreReceivingReviewInitial? _receivingMatchInitial;
  _ReceivingNativeLease? _receivingMatchLease;String? _receivingMatchCopy;
  bool get _receivingMatchCurrent {
    if(_receivingMatchLease==null)return true;
    if(!_receivingMatchLease!.current||jsonEncode(widget.copy.toJson())!=_receivingMatchCopy)_receivingMatchRetired=true;
    return !_receivingMatchRetired;
  }
  bool _canAdoptReceivingMatch(StoreReceivingReviewInitial initial)=>_current&&_loaded&&!_busy&&_frozen==null&&
    _otherReview==null&&!_uncertain&&!_dirty&&_receivingMatchTargetValid(session,widget.copy,initial);
  bool _adoptReceivingMatch(StoreReceivingReviewInitial initial,_ReceivingNativeLease lease) {
    if(!lease.current||!_canAdoptReceivingMatch(initial))return false;
    _receivingMatchLease?.dispose();_receivingMatchLease=lease;_receivingMatchCopy=jsonEncode(widget.copy.toJson());
    _receivingMatchInitial=initial;_receivingMatchInitialAttempted=false;_applyReceivingMatchInitial();return true;
  }
  void _applyReceivingMatchInitial() {
    final initial=_receivingMatchInitial??widget.receivingInitial;
    if(initial==null||_receivingMatchInitialAttempted)return;
    _receivingMatchInitialAttempted=true;
    final index=initial.values['billLineIndex'] as int?;
    if(!_current||!_loaded||_busy||_frozen!=null||_otherReview!=null||_uncertain||_dirty||
      index==null||index<0||index>=widget.copy.draft.goods.length) {
      setState(()=>_error='Original reconciliation input is kept. Resolve its saved review before applying new values.');return;
    }
    final receipt=_ledger?.goodsReceipts[initial.text('receiptId')];
    final line=receipt?.lines.where((line)=>line.sourceLineId==initial.text('receiptLineId')).singleOrNull;
    if(receipt==null||line==null||widget.copy.draft.goods[index]['productId']!=line.productId||
      !session.workspaceGoodsReceiptDrafts.any((r)=>r.supplierId==widget.copy.supplier.id&&jsonEncode(r.receipt.toJson())==jsonEncode(receipt.toJson()))) {
      setState(()=>_error='Choose an original matching bill item and recorded receipt line.');return;
    }
    setState((){
      _opened=true;_item=index;_chooseReceipt((receipt.id,line.sourceLineId));
      final controls={'quantity':_quantity,'free':_free,'accepted':_accepted,'damaged':_damaged,'numerator':_numerator,'denominator':_denominator};
      for(final entry in controls.entries){if(initial.text(entry.key) case final value?)entry.value.text=value;}
      _conversion=false; // Only the original native checkbox records user review.
    });
  }

  late final _scope = widget.session.workspaceSupplierScope;
  final _quantity = TextEditingController(), _free = TextEditingController(text: '0');
  final _accepted = TextEditingController(), _damaged = TextEditingController(text: '0');
  final _numerator = TextEditingController(text: '1'), _denominator = TextEditingController(text: '1');
  bool _opened = false, _busy = false, _loaded = false, _reviewVerified = false, _conversion = false;
  bool _uncertain = false, _knownUnstored = false;
  int? _item, _bookRevision;
  (String, String)? _receiptKey;
  WorkspaceSupplierBillGoodsAllocation? _frozen;
  WorkspaceBillGoodsReviewCancellation? _cancelAttempt;
  WorkspaceSupplierBillGoodsReview? _otherReview;
  final _savedReviewAnchor = GlobalKey();
  String? _error, _notice;
  WorkSession get session => widget.session;
  bool get _current => mounted && _scope != null && _scope == session.workspaceSupplierScope && widget.ownerCurrent?.call() != false && _receivingMatchCurrent;
  WorkspaceSupplierLedger? get _ledger => session.workspaceInvoiceHistoryLoaded
    ? session.workspaceSupplierLedger(widget.copy.supplier.id) : null;
  bool get _committed => _frozen != null &&
    jsonEncode(_ledger?.billGoodsAllocations[_frozen!.operationId]?.toJson()) == jsonEncode(_frozen!.toJson());
  bool get _dirty => _frozen == null && (_item != null || _receiptKey != null ||
    _quantity.text.isNotEmpty || _accepted.text.isNotEmpty);
  bool get _editable => _current && _loaded && _ledger != null && !_busy && !_uncertain &&
    !session.workspaceSupplierRecoveryRequired && _frozen == null && _otherReview == null;
  List<(WorkspaceSupplierGoodsReceipt, WorkspaceSupplierGoodsReceiptLine)> get _receipts {
    if (_item == null || _ledger == null) return const [];
    final product = widget.copy.draft.goods[_item!]['productId'];
    return [for (final receipt in _ledger!.goodsReceipts.values)
      if (session.workspaceGoodsReceiptDrafts.any((review) => review.supplierId == widget.copy.supplier.id &&
          jsonEncode(review.receipt.toJson()) == jsonEncode(receipt.toJson())))
        for (final line in receipt.lines) if (line.productId == product) (receipt, line)];
  }
  (WorkspaceSupplierGoodsReceipt, WorkspaceSupplierGoodsReceiptLine)? get _receipt =>
    _receipts.where((pair) => (pair.$1.id, pair.$2.sourceLineId) == _receiptKey).singleOrNull;
  String _reviewReceiptLabel(String receiptId, String lineId) {
    final receipt = _ledger?.goodsReceipts[receiptId];
    final line = receipt?.lines.where((item) => item.sourceLineId == lineId).firstOrNull;
    if (receipt == null || line == null) return receipt?.reference ?? receiptId;
    final label = storeBillGoodsReceiptLabel(_ledger!.goodsReceipts.values, receipt, line);
    // Keep the approved compact summary for an unambiguous receipt.
    return label.contains('\n') ? label : receipt.reference;
  }
  @override
  void initState() { super.initState(); unawaited(_recover(readOnlyOpen: widget.assistantReadOnlyOpen)); }
  @override
  void dispose() {
    _receivingMatchLease?.dispose();
    for (final c in [_quantity, _free, _accepted, _damaged, _numerator, _denominator]) { c.dispose(); }
    super.dispose();
  }
  Future<bool> confirmLeave() async {
    if (_busy) return false;
    if (_frozen != null && !_reviewVerified && !_committed && !_knownUnstored) {
      setState(() { _opened = true; _error = 'Review save status is unverified. Retry saved status before leaving.'; _uncertain = true; });
      return false;
    }
    if (!_dirty && !_knownUnstored) return true; // Only a verified saved review survives leaving.
    final leave = await showDialog<bool>(context: context, builder: (context) => AlertDialog(
      title: const Text('Leave goods reconciliation?'),
      content: const Text('These reconciliation quantities are not saved. The supplier bill and received Stock stay unchanged.'),
      actions: [TextButton(onPressed: () => Navigator.pop(context, false), child: const Text('Keep editing')),
        TextButton(onPressed: () => Navigator.pop(context, true), child: const Text('Discard changes'))]));
    if (mounted && leave == true) setState(_clear);
    return mounted && leave == true;
  }
  Future<bool> closePanel() async {
    if (!_opened) return true;
    if (!await confirmLeave() || !mounted || !_current) return false;
    setState(() => _opened = false);
    return true;
  }
  Future<void> _recover({bool readOnlyOpen = false}) async {
    if (!_current) return;
    setState(() { _busy = true; _error = null; });
    final ready = readOnlyOpen ? session.workspaceSuppliersLoaded && session.workspaceInvoiceHistoryLoaded
      : await session.loadWorkspaceSuppliers(retry: true) && await session.recoverCustomerLedger();
    if (!_current) return;
    final ledger = _ledger;
    final exact = ledger != null && jsonEncode(ledger.purchaseBills[widget.copy.draft.id]?.copy.toJson()) ==
      jsonEncode(widget.copy.toJson());
    _bookRevision = session.workspacePurchaseEntryRevision;
    _loaded = ready && exact && _bookRevision != null;
    if (!_loaded) {
      setState(() { _busy = false; _uncertain = true; _error = 'Saved bill or supplier account is unavailable. Retry without adding these goods again.'; });
      return;
    }
    _uncertain = false;
    for (final review in session.workspaceBillGoodsReviews.where((r) => r.supplierId == widget.copy.supplier.id)) {
      final posted = ledger!.billGoodsAllocations[review.allocation.operationId];
      final cancelled = session.workspaceBillGoodsCancellations.any((c) => c.operationId == review.allocation.operationId);
      if (posted != null && (cancelled || jsonEncode(posted.toJson()) != jsonEncode(review.allocation.toJson()))) {
        setState(() { _busy = false; _uncertain = true; _error = 'Saved goods reconciliation needs recovery. Do not receive or reconcile these goods again.'; });
        return;
      }
    }
    final pending = session.workspaceBillGoodsReviews.where((review) =>
      review.supplierId == widget.copy.supplier.id &&
      !session.workspaceBillGoodsCancellations.any((c) => c.operationId == review.allocation.operationId) &&
      !ledger!.billGoodsAllocations.containsKey(review.allocation.operationId)).toList();
    _otherReview = pending.where((r) => r.allocation.copyId != widget.copy.id ||
      r.allocation.copyRevision != widget.copy.revision).firstOrNull;
    if (pending.length > 1) { _uncertain = true; _error = 'More than one unfinished reconciliation needs recovery. Do not prepare another reconciliation.'; }
    final own = pending.where((r) => r.allocation.copyId == widget.copy.id &&
      r.allocation.copyRevision == widget.copy.revision).singleOrNull;
    if (own != null) {
      if (_frozen != null && jsonEncode(_frozen!.toJson()) != jsonEncode(own.allocation.toJson())) {
        setState(() { _busy = false; _uncertain = true; _error = 'Another saved reconciliation review was found. Keep this attempt and recover before continuing.'; });
        return;
      }
      _frozen = own.allocation; _reviewVerified = true; _opened = true;
    }
    if (_frozen != null) {
      final cancellation = session.workspaceBillGoodsCancellations.where((c) => c.operationId == _frozen!.operationId).singleOrNull;
      final posted = ledger!.billGoodsAllocations[_frozen!.operationId];
      final savedReview = session.workspaceBillGoodsReviews.where((r) => r.allocation.operationId == _frozen!.operationId).singleOrNull;
      _reviewVerified = savedReview != null && savedReview.supplierId == widget.copy.supplier.id &&
        jsonEncode(savedReview.allocation.toJson()) == jsonEncode(_frozen!.toJson());
      _knownUnstored = savedReview == null && posted == null && cancellation == null;
      if (cancellation != null && posted != null) {
        _uncertain = true;
        _error = 'Saved reconciliation and cancellation conflict. Recover the supplier account before continuing.';
      } else if (cancellation != null) {
        _clear(); _notice = 'Reconciliation review cancelled. Bill, Stock and payments are unchanged.';
      } else if (posted != null && jsonEncode(posted.toJson()) != jsonEncode(_frozen!.toJson())) {
        _uncertain = true;
        _error = 'Saved reconciliation details conflict. Recover before continuing.';
      } else if ((savedReview != null && !_reviewVerified) || (posted != null && savedReview == null)) {
        _uncertain = true; _error = 'Saved reconciliation review is missing or changed. Recover before continuing.';
      }
    }
    if (_opened && widget.onBeforeOpen != null) await widget.onBeforeOpen!();
    if (!_current) return;
    setState(() { _busy = false; });
    _applyReceivingMatchInitial();
  }
  void _clear() {
    _knownUnstored = false; _uncertain = false; _error = null; _notice = null;
    _frozen = null; _reviewVerified = false; _cancelAttempt = null; _item = null; _receiptKey = null;
    _quantity.clear(); _accepted.clear(); _free.text = '0'; _damaged.text = '0'; _conversion = false;
  }
  void _chooseReceipt((String, String)? key) {
    _receiptKey = key; _conversion = false;
    final pair = _receipt;
    if (pair == null || _item == null) return;
    final unit = widget.copy.draft.goods[_item!]['pack']!.trim();
    final previous = _ledger!.billGoodsAllocations.values.where((link) =>
      link.billId == widget.copy.draft.id && link.billLineIndex == _item).firstOrNull;
    _numerator.text = '${previous?.stockUnitsNumerator ?? (unit == pair.$2.stockUnit ? 1 :
      unit == pair.$2.purchaseUnit ? pair.$2.unitsPerPack : 1)}';
    _denominator.text = '${previous?.stockUnitsDenominator ?? 1}';
  }
  WorkspaceSupplierBillGoodsAllocation? _snapshot() {
    final pair = _receipt;
    if (_item == null || pair == null || !_conversion || _ledger == null) return null;
    final qty = _ReceivingLineInput.milli(_quantity.text), free = _ReceivingLineInput.milli(_free.text);
    final accepted = _ReceivingLineInput.milli(_accepted.text), damaged = _ReceivingLineInput.milli(_damaged.text);
    final numerator = int.tryParse(_numerator.text), denominator = int.tryParse(_denominator.text);
    if ([qty, free, accepted, damaged, numerator, denominator].any((v) => v == null)) return null;
    final line = widget.copy.draft.goods[_item!];
    return WorkspaceSupplierBillGoodsAllocation(operationId: session.newWorkspaceBillGoodsLinkId(),
      receiptId: pair.$1.id, receiptLineId: pair.$2.sourceLineId, billId: widget.copy.draft.id,
      copyId: widget.copy.id, copyRevision: widget.copy.revision, billLineIndex: _item!,
      productId: pair.$2.productId, billUnit: line['pack']!.trim(), stockUnit: pair.$2.stockUnit,
      stockUnitsNumerator: numerator!, stockUnitsDenominator: denominator!, billQuantityMilli: qty!,
      freeBillQuantityMilli: free!, acceptedReceiptMilli: accepted!, damagedReceiptMilli: damaged!,
      conversionReviewed: true, linkedAt: DateTime.now().toUtc());
  }
  Future<void> _saveReview() async {
    if (!_current || !_loaded || _busy || _bookRevision == null || _ledger == null) return;
    final link = _frozen ?? _snapshot();
    if (link == null || _ledger!.allocateBillGoods(link, expectedRevision: _ledger!.revision) == null) {
      setState(() => _error = 'Check remaining invoice/receipt quantities and the exact unit conversion. No goods or payment changed.');
      return;
    }
    final supplierRevision = _ledger!.revision;
    setState(() { _busy = true; _frozen = link; _knownUnstored = false; _error = null; });
    final saved = await session.saveWorkspaceBillGoodsReview(link, supplierId: widget.copy.supplier.id,
      scope: _scope!, expectedPurchaseRevision: _bookRevision!, expectedSupplierRevision: supplierRevision);
    if (!_current) return;
    setState(() { _busy = false; _reviewVerified = saved; _bookRevision = session.workspacePurchaseEntryRevision;
      _uncertain = !saved;
      if (!saved) _error = session.workspaceSupplierError ?? 'Review status needs recovery. Retry saved status before changing the reconciliation.'; });
    if (saved && mounted) {
      FocusScope.of(context).unfocus();
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!_current || !_opened || _busy || !_reviewVerified ||
            _frozen?.operationId != link.operationId || _committed ||
            ModalRoute.of(context)?.isCurrent != true) {
          return;
        }
        final anchor = _savedReviewAnchor.currentContext;
        if (anchor != null) {
          unawaited(Scrollable.ensureVisible(anchor, alignment: 0.15,
            duration: const Duration(milliseconds: 200)));
        }
      });
    }
  }
  Future<void> _confirm() async {
    if (!_current || _busy || !_loaded || !_reviewVerified || _frozen == null || _bookRevision == null || _ledger == null) return;
    setState(() { _busy = true; _error = null; });
    final saved = await session.confirmWorkspaceSupplierBillGoodsAllocation(_frozen!, supplierId: widget.copy.supplier.id,
      scope: _scope!, expectedSupplierRevision: _ledger!.revision, expectedPurchaseRevision: _bookRevision!, requireSavedReview: true);
    if (!_current) return;
    setState(() { _busy = false; _uncertain = !saved;
      if (saved) { _notice = 'Goods receipt reconciled. Stock, supplier balance and payments are unchanged.'; }
      else { _error = session.workspaceSupplierError ?? 'Reconciliation status is unverified. Retry saved status before preparing another reconciliation.'; } });
  }
  Future<void> _cancel() async {
    if (!_current || _busy || !_reviewVerified || _frozen == null || _committed || _bookRevision == null) return;
    _cancelAttempt ??= WorkspaceBillGoodsReviewCancellation(operationId: _frozen!.operationId,
      supplierId: widget.copy.supplier.id, revision: _bookRevision! + 1, cancelledAt: DateTime.now().toUtc(),
      reason: 'Retailer cancelled goods matching review to correct quantities');
    setState(() { _busy = true; _error = null; });
    final saved = await session.abandonWorkspaceBillGoodsReview(_frozen!.operationId, supplierId: widget.copy.supplier.id,
      scope: _scope!, expectedRevision: _cancelAttempt!.revision - 1,
      cancelledAt: _cancelAttempt!.cancelledAt, reason: _cancelAttempt!.reason);
    if (!_current) return;
    setState(() { _busy = false; if (saved) { _clear(); _bookRevision = session.workspacePurchaseEntryRevision;
        _notice = 'Reconciliation review cancelled. Bill, Stock and payments are unchanged.'; }
      else { _uncertain = true; _error = session.workspaceSupplierError ?? 'Cancellation status needs recovery. Retry saved status.'; } });
  }
  Widget _field(String label, TextEditingController controller, String key, {bool locked = false}) =>
    _purchaseCompactLabeledField(label, width: 112, field: TextField(key: Key(key), controller: controller,
      enabled: _editable && !locked, keyboardType: const TextInputType.numberWithOptions(decimal: true),
      decoration: const InputDecoration(), onChanged: (_) => setState(() {})));
  @override
  Widget build(BuildContext context) {
    super.build(context);final body=_buildReceivingMatch(context);
    return _receivingMatchLease==null?body:_ReceivingOwnerSurface(current:()=>_current,changes:_receivingMatchLease!.changes,child:body);
  }
  Widget _buildReceivingMatch(BuildContext context) {
    final ledger = _ledger;
    final pair = _receipt;
    final links = ledger?.billGoodsAllocations.values ?? const <WorkspaceSupplierBillGoodsAllocation>[];
    final billedLinks = links.where((link) => link.billId == widget.copy.draft.id && link.billLineIndex == _item);
    final receiptLinks = pair == null ? const <WorkspaceSupplierBillGoodsAllocation>[] :
      links.where((link) => link.receiptId == pair.$1.id && link.receiptLineId == pair.$2.sourceLineId);
    final line = _item == null ? null : widget.copy.draft.goods[_item!];
    final printedQuantity = line == null ? null : _ReceivingLineInput.milli(line['quantity'] ?? '');
    final freeText = (line?['freeQuantity'] ?? '').trim();
    final printedFree = line == null ? null : freeText.isEmpty ? 0 : _ReceivingLineInput.milli(freeText);
    final printedQuantitiesKnown = printedQuantity != null && printedFree != null;
    final priorMatches = links.where((link) => link.copyId == widget.copy.id && link.copyRevision == widget.copy.revision);
    final hasOlderReceipt = line != null && ledger != null && ledger.goodsReceipts.values.any((receipt) =>
      receipt.lines.any((item) => item.productId == line['productId']));
    final conversionLocked = billedLinks.isNotEmpty || (pair != null &&
      (line?['pack']?.trim() == pair.$2.stockUnit || line?['pack']?.trim() == pair.$2.purchaseUnit));
    final pendingCopy = _otherReview == null ? null : session.workspacePurchaseCopies.where((copy) =>
      copy.id == _otherReview!.allocation.copyId && copy.revision == _otherReview!.allocation.copyRevision).singleOrNull;
    final matchingProgress = _current && _loaded && !_busy && !_uncertain &&
      !session.workspaceSupplierRecoveryRequired && !session.workspaceGoodsReceiptRecoveryPending
        ? ledger?.goodsProgressFor(widget.copy) : null;
    final fullyMatched = matchingProgress != null && matchingProgress.totalItems > 0 &&
      matchingProgress.matchedItems == matchingProgress.totalItems;
    // Do not conceal unsaved input or a frozen/recovery attempt when progress changes.
    final completedView = fullyMatched && !_dirty && _frozen == null && _otherReview == null;
    Future<void> toggleGoods() async {
      if (_opened && !await confirmLeave()) return;
      if (!_opened && widget.onBeforeOpen != null && !await widget.onBeforeOpen!()) return;
      if (_current) setState(() => _opened = !_opened);
    }
    final header = TextButton(key: const Key('work-bill-goods-open'), onPressed: _busy ? null : toggleGoods,
