  DialogRoute<void>? _previewRoute;
  bool _previewClosing = false;
  final _previewChanges = ValueNotifier<int>(0);

  @override
  void setState(VoidCallback fn) {
    super.setState(fn);
    if (_fullScreenPreview) _previewChanges.value++;
    if (_receivingTaxLease != null) {
      _receivingTaxCurrent;
      _receivingTaxEdits.value++;
    }
  }

  Future<void> _openFullScreenPreview() async {
    if (_fullScreenPreview || !_current || _busy) return;
    final preserveInline = _readOnly && _sourceAttachment == null;
    final inlineZoom = _previewZoom.value.clone();
    final inlineAdjusted = _billReaderAdjusted;
    if (preserveInline) {
      _billReaderAdjusted = false;
      _fittedRecordedView = null;
    }
    FocusScope.of(context).unfocus();
    _previewClosing = false;
    setState(() => _fullScreenPreview = true);
    // There must be only one mounted invoice viewer for these keys/controllers.
    await WidgetsBinding.instance.endOfFrame;
    if (!mounted || !_current) {
      if (mounted) {
        setState(() {
          _fullScreenPreview = false;
          if (preserveInline) { _billReaderAdjusted = inlineAdjusted; _previewZoom.value = inlineZoom; }
        });
      }
      return;
    }
    try {
      final route = DialogRoute<void>(context: context, useSafeArea: true, barrierDismissible: false,
        builder: (previewContext) => Dialog.fullscreen(child: SafeArea(
          child: AnimatedBuilder(animation: Listenable.merge([_previewChanges, widget.session, _receivingPurchaseChanges]),
            builder: (_, _) => Column(
              key: const Key('purchase-full-screen-preview'), children: [
                Row(children: [Expanded(child: Padding(padding: const EdgeInsets.symmetric(horizontal: 12),
                  child: Text(_sourceAttachment != null ? 'Supplier document copy'
                    : _readOnly ? 'Recorded purchase copy' : 'Invoice preview',
                    style: const TextStyle(fontSize: 16, fontWeight: FontWeight.w700)))),
                  TextButton(key: const Key('purchase-full-screen-close'),
                    style: TextButton.styleFrom(minimumSize: const Size(48, 48)),
                    onPressed: _closeFullScreenPreview, child: const Text('Close'))]),
                Expanded(child: !_current ? const Center(child: Text('This purchase is no longer available. Close the preview.'))
                  : LayoutBuilder(builder: (context, constraints) => _sourceAttachment == null
                    ? Column(crossAxisAlignment: CrossAxisAlignment.stretch,
                      children: _reviewPurchase(constraints.maxHeight))
                    : _originalReadingView())),
              ])))));
      _previewRoute = route;
      await Navigator.of(context, rootNavigator: true).push(route);
      await route.completed;
    } finally {
      _previewRoute = null;
      if (mounted) {
        setState(() {
          _fullScreenPreview = false; _readingPointers.clear();
          if (preserveInline) {
            _previewZoom.value = inlineZoom;
            _billReaderAdjusted = inlineAdjusted;
            _fittedRecordedView = null;
          }
        });
        _positionReview();
      }
    }
  }
  void _closeFullScreenPreview() {
    final route = _previewRoute;
    if (_previewClosing || route == null || !route.isCurrent) return;
    _previewClosing = true;
    route.navigator?.pop();
  }
  void _showReadingPreview({bool recorded = true}) {
    _previewPurchase(recorded: recorded);
    unawaited(_openFullScreenPreview());
  }
