  bool _loading = true, _busy = false, _leaving = false;
  String? _error, _notice;
  final _expandedSections = <String>{};
  bool _showAllDocumentFields = false;
  String get _documentType => _details['documentType']!.text.trim();
  bool get _billOfSupply => _documentType == 'Bill of supply';
  bool get _combinedBill => _documentType == 'Invoice-cum-bill of supply';
  bool get _noSupplierGst => _billOfSupply || _documentType == 'Non-GST purchase bill';
  bool get _taxInvoice => const ['GST invoice', 'Tax invoice'].contains(_documentType);
  bool get _unknownDocument => !_taxInvoice && !_noSupplierGst && !_combinedBill;
  static const _documentTaxKeys = {'priceBasis', 'taxTreatment', 'taxableValue', 'cgst', 'sgst',
    'sgstAmount', 'utgst', 'igst', 'cess', 'totalTax', 'printedTaxRate', 'printedCgstRate',
    'printedSgstRate', 'printedUtgstRate', 'printedIgstRate'};
  static const _itemTaxKeys = {'taxableValue', 'taxAmount', 'gstRate', 'cess', 'cgstRate',
    'cgst', 'sgstRate', 'sgst', 'utgstRate', 'utgst', 'igstRate', 'igst', 'cessRate'};
  bool get _hasTaxDetails => _documentTaxKeys.any((k) => _details[k]!.text.isNotEmpty) ||
    _goods.any((line) => _itemTaxKeys.any((k) => line.extra[k]!.text.isNotEmpty)) ||
    _taxRows.any((row) => row.values.any((value) => value.text.isNotEmpty));
  bool get _hasEInvoiceDetails => const ['reverseCharge', 'eInvoiceStatus', 'irn', 'ackNumber',
    'ackDate', 'qrStatus', 'eInvoiceDeclaration'].any((k) => _details[k]!.text.isNotEmpty);
  bool get _showGstFields => !_noSupplierGst || _showAllDocumentFields || _hasTaxDetails;
  bool get _showEInvoiceFields => _taxInvoice || _unknownDocument || _showAllDocumentFields || _hasEInvoiceDetails;
  bool get _servicesOnly => _details['supplyNature']!.text == 'Services';
  bool get _hasGoodsReceipt => const ['receiptStatus', 'receivedDate'].any((k) => _details[k]!.text.isNotEmpty) ||
    _goods.any((line) => const ['receivedQuantity', 'damagedQuantity', 'shortQuantity']
      .any((k) => line.extra[k]!.text.isNotEmpty));
  Widget _documentField(bool visible, Widget child) => visible ? child : const SizedBox.shrink();
  List<String> get _documentMissingDetails {
    final missing = <String>[];
    for (final entry in <String, String>{'Supplier name': _name.text, 'Supplier address': _address.text,
        'Supplier document number': _reference.text, 'Supplier document date': _date.text,
        'Invoice total': _details['invoiceTotal']!.text}.entries) {
      if (entry.value.trim().isEmpty) missing.add(entry.key);
    }
    if (_documentType.isEmpty) missing.add('Supplier document type');
    if (const ['', 'Not stated'].contains(_details['supplyNature']!.text)) missing.add('Goods / services described on the bill');
    if (_taxInvoice || _billOfSupply || _combinedBill) {
      if (_gstin.text.trim().isEmpty) missing.add('Supplier GSTIN');
      if (const ['', 'Not shown'].contains(_details['signatureStatus']!.text)) missing.add('Signature / applicable electronic-document exception');
      if (const ['', 'Not confirmed'].contains(_details['buyerRegistration']!.text)) missing.add('Buyer GST registration status');
    }
    if (_billOfSupply && const ['', 'Not stated'].contains(_details['billOfSupplyReason']!.text)) {
      missing.add('Bill of Supply basis as printed');
    }
    if (_billOfSupply && _details['billOfSupplyReason']!.text == 'Composition scheme' &&
        _details['printedDeclaration']!.text.trim().isEmpty) {
      missing.add('Printed composition declaration');
    }
    if (_details['buyerRegistration']!.text == 'Registered') {
      if (_details['buyerName']!.text.isEmpty) missing.add('Registered buyer name');
      if (_details['buyerAddress']!.text.isEmpty) missing.add('Registered buyer address');
      if (_details['buyerGstin']!.text.isEmpty && _details['buyerUin']!.text.isEmpty) missing.add('Buyer GSTIN / UIN');
    }
    if (_combinedBill) {
      if (_details['buyerRegistration']!.text != 'Unregistered') missing.add('Confirm buyer is unregistered for the combined format');
      if (_details['exemptValue']!.text.isEmpty) missing.add('Printed exempt supply value');
    }
    if ((_taxInvoice || _combinedBill) && _details['taxableValue']!.text.isEmpty) missing.add('Printed taxable value');
    if (_taxInvoice && _details['reverseCharge']!.text.isEmpty) missing.add('Reverse-charge indication on the invoice');
    if (_unknownDocument && _details['documentTitle']!.text.isEmpty) missing.add('Exact printed document title');
    if (!_goods.any((line) => line.name.text.trim().isNotEmpty)) missing.add('Item / service descriptions');
    if (_details['supplyNature']!.text == 'Goods' &&
        _goods.any((line) => line.name.text.isNotEmpty && (line.quantity.text.isEmpty || line.pack.text.isEmpty))) {
      missing.add('Quantity and unit for goods lines');
    }
    return missing;
  }
  Widget _documentChecks() {
    final missing = _documentMissingDetails;
    return ExpansionTile(key: const Key('work-purchase-document-checks'), tilePadding: EdgeInsets.zero,
      title: const Text('Check the original bill', style: TextStyle(fontSize: 13, fontWeight: FontWeight.w600)),
      subtitle: Text(missing.isEmpty ? 'Record details entered · applicability still needs checking'
        : '${missing.length} record details to check', style: const TextStyle(fontSize: 12)),
      children: [for (final text in missing) Align(alignment: Alignment.centerLeft,
        child: Text('Not entered / not confirmed: $text', style: const TextStyle(fontSize: 12))),
        if (_details['supplyNature']!.text == 'Goods and services')
          const Text('For a mixed bill, check quantity and unit for goods lines only. A service line need not have a physical quantity or unit.',
            key: Key('work-purchase-mixed-quantity-review'), style: TextStyle(fontSize: 12)),
        const Text('Check applicable HSN / SAC, GST rates and amounts, buyer particulars, inter-State place of supply and delivery address against the original. Buyer particulars also depend on registration, value and requested details.', style: TextStyle(fontSize: 12)),
        const Text('These checks do not verify GST registration, IRN, electronic signatures or tax-credit eligibility.', style: TextStyle(fontSize: 12)),
      ]);
  }
  bool get _current => mounted && _scope != null && _scope == widget.session.workspaceSupplierScope &&
    widget.assistantOwnerCurrent?.call() != false && _receivingTaxCurrent;
  String get _input => jsonEncode([_name.text, _phone.text, _address.text, _gstin.text,
    _reference.text, _date.text, _goods.map((line) => line.fields).toList(), _supplierId,
    {for (final e in _details.entries) if (e.value.text.isNotEmpty) e.key: e.value.text},
    _attachments.map((a) => a.toJson()).toList(),
    _additional.map((f) => f.field.toJson()).toList(), _printedTaxRows]);
  bool get _dirty => !_loading && _baseline != _input;
  @override
  void initState() {
    super.initState();
    _assistantEditorOwner = widget.session;
    (_openPurchaseAssistantEditors[_assistantEditorOwner] ??= <Object>{}).add(_assistantEditorToken);
    unawaited(_load());
  }
  Future<void> _load({bool retry = false}) async {
    final generation = ++_shortageReadGeneration;
    setState(() { _shortageDraftKnown = false; _shortageDraftPresent = false; _allocationRecoveryDraft = null; });
    final session = widget.session;
    final opened = widget.assistantReadOnlyOpen && !retry
      ? session.workspaceSuppliersLoaded && !session.workspaceSupplierSaving && !session.workspaceSupplierRecoveryRequired
      : await session.loadWorkspaceSuppliers(retry: retry);
    if (!mounted || generation != _shortageReadGeneration) return;
    if (!_current || !opened) {
      setState(() { _loading = false; _error = session.workspaceSupplierError ??
        'Your Store is unavailable. Reopen this Store to continue.'; });
      return;
    }
    final copy = widget.savedCopy;
    if (copy != null && !session.workspacePurchaseCopies.any((c) => c.id == copy.id &&
        jsonEncode(c.toJson()) == jsonEncode(copy.toJson()))) {
      setState(() { _loading = false; _error = 'This saved purchase copy is unavailable. Return to Purchases and retry.'; });
      return;
    }
    if (copy != null && (!widget.assistantReadOnlyOpen || retry)) {
      if (session.workspaceOriginalSupplierOpeningConfigured) {
        await session.loadWorkspaceOriginalLedger(retry: retry);
      } else {
        await session.recoverCustomerLedger();
      }
      if (!mounted || !_current || generation != _shortageReadGeneration) return;
    }
    final pending = copy == null ? session.workspacePendingPurchaseInput : null;
    if (widget.startNew && copy == null && pending == null && !session.workspacePurchaseDraftReviewed) {
      setState(() { _loading = false; _error = 'Finish and save the current purchase copy before starting another bill. Return to Purchases to resume it.'; });
      return;
    }
    _replaceReviewedDraftId = widget.startNew && copy == null ? session.workspacePurchaseEntryDraft?.id : null;
    _original = copy?.draft ?? (widget.startNew ? null : session.workspacePurchaseEntryDraft);
    _revision = copy?.revision ?? session.workspacePurchaseEntryRevision;
    _draftId = _original?.id ?? session.newWorkspacePurchaseDraftId();
    _supplier = copy?.supplier ?? session.workspaceSuppliers.where((p) => p.id == _original?.supplierId).firstOrNull;
    _supplierId = _supplier?.id ?? session.newWorkspaceSupplierId();
    _name.text = _supplier?.name ?? '';
    _phone.text = _supplier?.phone ?? '';
    _address.text = _supplier?.address ?? '';
    _gstin.text = _supplier?.gstin ?? '';
    _reference.text = _original?.invoiceReference ?? '';
    _date.text = _original?.invoiceDate ?? '';
    for (final e in _details.entries) { e.value.text = _original?.details[e.key] ?? ''; }
    _attachments..clear()..addAll(_original?.attachments ?? const []);
    for (final field in _additional) { field.dispose(); }
    _additional..clear()..addAll((_original?.additionalFields ?? const []).map(_PurchaseAdditionalInput.new));
    for (final row in _taxRows) { for (final c in row.values) { c.dispose(); } }
    _taxRows..clear()..addAll([for (final row in _original?.printedTaxRows ?? const <Map<String, String>>[])
      {for (final key in WorkspacePurchaseEntryDraft.printedTaxKeys)
        key: TextEditingController(text: row[key] ?? '')}]);
    for (final line in _goods) { line.dispose(); }
    _goods
      ..clear()
      ..addAll((_original?.goods ?? [<String, String>{}]).map(_PurchaseGoodsInput.new));
    _baseline = _input;
    if (pending != null) _restorePurchaseInput(pending);
    final initial = widget.assistantInitialData;
    if (initial != null && !_assistantInitialAttempted) {
      _assistantInitialAttempted = true;
      if (pending != null || copy != null || _original != null || _copyAttempt != null || _sourceSaving || _sourceLoading ||
          widget.assistantPrefillCurrent?.call() == false ||
          widget.assistantSourceSignature != _assistantPurchaseSourceSignature(session, 'AI-ACT-252', null) ||
          !initial.referencesCurrent(session)) {
        _assistantPrefillRejected = true;
      } else {
        final supplier = session.workspaceSuppliers.singleWhere((supplier) => supplier.id == initial.supplierId);
        _supplier = supplier; _supplierId = supplier.id;
        _name.text = initial.header['name'] ?? supplier.name;
        _phone.text = initial.header['phone'] ?? supplier.phone;
        _address.text = initial.header['address'] ?? supplier.address;
        _gstin.text = initial.header['gstin'] ?? supplier.gstin;
        if (initial.header.containsKey('invoiceReference')) _reference.text = initial.header['invoiceReference']!;
        if (initial.header.containsKey('invoiceDate')) _date.text = initial.header['invoiceDate']!;
        for (final entry in initial.details.entries) { _details[entry.key]!.text = entry.value; }
        if (initial.nativeGoods case final goods?) {
          for (final line in _goods) { line.dispose(); }
          _goods..clear()..addAll(goods.map(_PurchaseGoodsInput.new));
        }
        if (initial.printedTaxRows case final rows?) {
          for (final row in _taxRows) { for (final controller in row.values) { controller.dispose(); } }
          _taxRows..clear()..addAll([for (final row in rows)
            {for (final key in WorkspacePurchaseEntryDraft.printedTaxKeys) key: TextEditingController(text: row[key] ?? '')}]);
        }
        // Existing baseline precedes proposed input, so native discard remains.
        // No draft save, confirm, selected-document/OCR or receipt mutation.
        _expandedSections.addAll({'work-purchase-supplier-section', 'work-purchase-invoice-section',
          'work-purchase-items-section', 'work-purchase-tax-details'});
      }
    }
    _copyVerified = copy != null;
    if (_readOnly) _reviewFocused = true;
    setState(() { _loading = false; _error = _assistantPrefillRejected
      ? 'Suggestion was not applied. Original purchase input is kept; reopen Purchases.' : null; });
    if (copy != null && widget.assistantActionId == 'AI-ACT-254') {
      WidgetsBinding.instance.addPostFrameCallback((_) { if (_current) unawaited(_readBillInvoice(zoom: true)); });
    }
    if (copy != null) {
      unawaited(_readShortageActionDraft(copy, generation));
      unawaited(_readAllocationActionDraft(copy, generation));
    }
  }
  void _restorePurchaseInput(WorkspacePurchaseDraftSaveIntent original) {
    final draft = original.draft, profile = original.profile;
    _remoteAttempt = original;
    _original = draft; _supplier = profile; _supplierId = profile.id; _draftId = draft.id;
    _revision = original.expectedRevision; _replaceReviewedDraftId = original.replaceReviewedDraftId;
    _name.text = profile.name; _phone.text = profile.phone; _address.text = profile.address; _gstin.text = profile.gstin;
    _reference.text = draft.invoiceReference; _date.text = draft.invoiceDate;
    for (final e in _details.entries) { e.value.text = draft.details[e.key] ?? ''; }
    _attachments..clear()..addAll(draft.attachments);
    for (final field in _additional) { field.dispose(); }
    _additional..clear()..addAll(draft.additionalFields.map(_PurchaseAdditionalInput.new));
    for (final row in _taxRows) { for (final controller in row.values) { controller.dispose(); } }
    _taxRows..clear()..addAll([for (final row in draft.printedTaxRows)
      {for (final key in WorkspacePurchaseEntryDraft.printedTaxKeys) key: TextEditingController(text: row[key] ?? '')}]);
    for (final line in _goods) { line.dispose(); }
    _goods..clear()..addAll(draft.goods.map(_PurchaseGoodsInput.new));
    _copyAttempt = original.reviewedCopy; _copyAttemptInput = _input;
    _expandedSections.addAll({'work-purchase-supplier-section', 'work-purchase-invoice-section', 'work-purchase-items-section'});
  }
  Future<void> _checkPurchaseSave() async {
    final original = _remoteAttempt;
    if (original == null || _busy || !_current) return;
    FocusScope.of(context).unfocus();
    setState(() { _busy = true; _error = null; });
    final result = await widget.session.readWorkspacePurchaseAttempt(original);
    if (!mounted) return;
    setState(() => _busy = false);
    if (!_current) return;
    if (result == null) {
      _showSaveError(widget.session.workspaceSupplierError ?? 'The original save still needs checking. Your entries are kept.');
    } else if (result.recorded) {
      _baseline = _input; _remoteAttempt = null;
      widget.onBack(); // The session contains the independently current book.
    } else {
      setState(() {
        _remoteAttempt = null; _copyAttempt = null; _copyAttemptInput = null;
        _revision = widget.session.workspacePurchaseEntryRevision;
      });
      _showSaveError(result.reason == 'private_original_unavailable'
        ? 'Original files cannot be saved yet. This bill was not saved; your entries and files are kept.'
        : 'This bill was not saved. Check the details before trying again; your entries are kept.');
    }
  }
  Future<void> _retryPurchaseSave() async {
    final original = _remoteAttempt;
    if (original == null || _busy || !_current || _scope == null) return;
    setState(() { _busy = true; _error = null; });
    final saved = await widget.session.retryWorkspacePurchaseAttempt(original);
    if (!mounted) return;
    setState(() => _busy = false);
    if (!_current) return;
    if (saved) { _baseline = _input; _remoteAttempt = null; widget.onBack(); }
    else if (widget.session.workspacePendingPurchaseInput == null) {
      // Read the same terminal original; do not infer a result from absence.
      await _checkPurchaseSave();
    } else {
      _showSaveError(widget.session.workspaceSupplierError ?? 'The original save still needs checking. Your entries are kept.');
    }
  }
  void _reviewUnsavedPurchase() {
    final original = widget.session.workspaceRejectedPurchaseInput;
    if (original == null || _busy || !_current || _dirty || _pendingPurchase) return;
    final current = widget.session.workspacePurchaseEntryDraft;
    if (current != null && current.id != original.draft.id) {
      _showSaveError('Another purchase draft is saved. Return to Purchases to finish it before reviewing these unsaved details.');
      return;
    }
    setState(() {
      _restorePurchaseInput(original); _remoteAttempt = null;
      _revision = widget.session.workspacePurchaseEntryRevision;
      _copyAttempt = null; _copyAttemptInput = null;
      _error = 'These details were not saved. Check them before saving again.';
    });
  }
  Future<void> _readAllocationActionDraft(WorkspacePurchaseSavedCopy copy, int generation) async {
    final session = widget.session;
    if (!session.workspaceOriginalSupplierAllocationConfigured) return;
    final key = session.supplierAllocationRecoveryFormKey(copy);
    if (key == null) return;
    try {
      final saved = await session.readLedgerForm(key);
      if (!mounted || !_current || generation != _shortageReadGeneration ||
          key != session.supplierAllocationRecoveryFormKey(copy) ||
          !session.workspacePurchaseCopies.any((candidate) => candidate.id == copy.id &&
            workspaceLedgerCanonical(candidate.toJson()) == workspaceLedgerCanonical(copy.toJson()))) return;
      setState(() => _allocationRecoveryDraft = saved?.supplierAllocationIntent == null ? null : saved);
    } on Object {
      // Failed raw-input reads never authorise editing or a replacement Save.
    }
  }
  Future<void> _readShortageActionDraft(WorkspacePurchaseSavedCopy copy, int generation) async {
    final session = widget.session, key = widget.session.supplierShortageRecoveryFormKey(copy);
    setState(() { _shortageDraftKnown = false; _shortageDraftPresent = false; });
    if (key == null) return; // Unavailable namespace is not proof of absence.
    try {
      final saved = await session.readLedgerForm(key);
      if (!mounted || !_current || generation != _shortageReadGeneration ||
          session.supplierShortageRecoveryFormKey(copy) != key ||
          !session.workspacePurchaseCopies.any((candidate) => candidate.id == copy.id &&
            jsonEncode(candidate.toJson()) == jsonEncode(copy.toJson()))) { return; }
      setState(() {
        _shortageDraftKnown = true;
        _shortageDraftPresent = saved != null && saved.fields.isNotEmpty;
      });
    } on Object {
      // Keep recovery discoverable; failure is never an empty-draft result.
    }
  }
  void _chooseSupplier(WorkspaceSupplierProfile p) {
    if (_supplierId != p.id) { _clearSupplierInstructions(); }
    setState(() { _supplier = p; _supplierId = p.id; _name.text = p.name;
      _phone.text = p.phone; _address.text = p.address; _gstin.text = p.gstin; });
    _supplierFocus.unfocus();
  }
  Future<void> _pickSupplier() async {
    if (_busy || _readOnly || !_current) return;
    final session = widget.session;
    if (_revision != session.workspacePurchaseEntryRevision) {
      _showSaveError('Saved purchases changed. Check the saved draft before choosing a supplier. Your entries are kept.');
      return;
    }
    final originalDraft = jsonEncode(session.workspacePurchaseEntryDraft?.toJson());
    FocusScope.of(context).unfocus();
    setState(() => _busy = true);
    final String? selected;
    try {
      selected = await _showStoreSupplierSelector(context, session, selectedId: _supplier?.id, ownerCurrent: _receivingPurchaseOwner);
    } finally {
      if (mounted) setState(() => _busy = false);
    }
    if (!_current || _readOnly || selected == null) return;
    if (jsonEncode(session.workspacePurchaseEntryDraft?.toJson()) != originalDraft) {
      _showSaveError('The saved bill changed. Your entries are kept; check the saved draft before continuing.');
      return;
    }
    final supplier = session.workspaceSuppliers.where((p) => p.id == selected).singleOrNull;
    if (supplier == null || session.workspaceSupplierRecoveryRequired) return;
    // A standalone contact save advances the same purchase-book revision. Only
    // adopt it after proving that the existing bill draft was not replaced.
    _revision = session.workspacePurchaseEntryRevision;
    _chooseSupplier(supplier);
  }
  void _clearSupplierInstructions() {
    for (final key in const ['supplierEmail', 'bankName', 'bankAccount', 'bankIfsc',
        'bankBranch', 'upiType', 'upiId', 'paymentQrStatus', 'terms', 'signatory', 'paymentTerms']) {
      _details[key]!.clear();
    }
  }
  Future<bool> confirmLeave() async {
    if (widget.openingOnly) {
      return await (_openingKey.currentState?.confirmLeave() ?? Future.value(true));
    }
    if (_busy || _leaving) return false;
    if (!await (_billGoodsKey.currentState?.confirmLeave() ?? Future.value(true))) return false;
    if (!mounted) return false;
    _leaving = true;
    FocusScope.of(context).unfocus();
    final discard = !_dirty && !_pendingPurchase || await showDialog<bool>(context: context, builder: (context) =>
      AlertDialog(title: const Text('Leave purchase draft?'),
        content: Text(_pendingPurchase ? 'The original save still needs checking. Reopen Purchases to recover it; leaving will not cancel or repeat the save.'
          : 'Unsaved changes will be discarded. Your last saved draft stays available.'),
        actions: [TextButton(onPressed: () => Navigator.pop(context, false), child: const Text('Keep editing')),
          TextButton(onPressed: () => Navigator.pop(context, true), child: Text(_pendingPurchase ? 'Leave' : 'Discard changes'))])) == true;
    _leaving = false;
    if (mounted && discard && !_readOnly && _scope != null) {
      widget.session.dismissWorkspacePurchaseValidation(_scope!);
    }
    return mounted && discard;
  }
  Future<void> _back() async {
    if (await confirmLeave() && mounted) widget.onBack();
  }
  Future<void> _addGoodsProduct(_PurchaseGoodsInput line) async {
    if (_busy || !_current || _scope == null || line.name.text.trim().isEmpty) return;
    final inputContext = widget.session.tradingPreferencesContext;
    final storeId = widget.session.activeWorkspace?.id;
    final loaded = storeId != null && await widget.session.loadWorkspaceProductDefaults(expectedStoreId: storeId);
    if (!mounted || !_current || _busy || inputContext != widget.session.tradingPreferencesContext) return;
    if (!loaded) {
      setState(() => _error = widget.session.workspaceTradingPreferencesError ?? 'Saved product defaults could not be opened. Try again.');
      return;
    }
    FocusScope.of(context).unfocus();
    final id = 'custom-${DateTime.now().microsecondsSinceEpoch}';
    final defaults = widget.session.workspaceProductDefaults;
    final product = WorkspaceCatalogueItem(
      id: id, canonicalId: id, categoryId: 'other', brand: '',
      title: line.name.text.trim(), variant: '', pack: line.pack.text.trim(),
      sku: 'SKU-${id.substring(7)}', barcode: '',
      // The bill can use decimal prices; the product editor accepts whole rupees.
      // Never round or replace the original bill price to make it fit.
      purchasePrice: int.tryParse(line.cost.text.trim()) ?? 0,
      sellingPrice: int.tryParse(line.extra['sellingPrice']!.text.trim()) ?? 0,
      mrp: int.tryParse(line.extra['mrp']!.text.trim()),
      unitPrice: '', stock: 0, available: false, publicListing: false,
      deliveryPromise: '', origin: '',
      visualLabel: 'Product image pending', visualKind: 'catalogue-packshot',
      stockMode: defaults.stockMode, lowStockThreshold: defaults.lowStockThreshold,
    );
    setState(() => _busy = true);
    try {
      final savedId = await Navigator.of(context).push<String>(MaterialPageRoute(
        builder: (pageContext) => _purchaseCapturedOwnerPage(context, pageContext, widget.session, _receivingPurchaseOwner, Scaffold(
          appBar: AppBar(title: const Text('Add product')),
          body: SafeArea(child: _CatalogueProductEditor(
            session: widget.session, product: product, embeddedPage: true,
            purchaseScope: _scope,
            onSaved: () => Navigator.of(pageContext).pop(product.id),
           ownerCurrent: _receivingPurchaseOwner)),
        ),ownerChanges:_receivingTaxChanges),
      ));
      if (!mounted || savedId == null) return;
      if (!_current) {
        setState(() => _error = 'You are in a different Store. Reopen the Store for this bill before matching items.');
        return;
      }
      final saved = widget.session.workspaceCatalogueItems.where((p) => p.id == savedId).firstOrNull;
      if (saved == null || !_goods.contains(line)) {
        setState(() => _error = 'Cannot find the saved product. Choose its match in Stock again.');
        return;
      }
      setState(() => line.productId = saved.id);
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }
  Future<void> _save({bool reviewed = false}) async {
    if (_readOnly || _busy || !_current || _scope == null || _assistantPrefillRejected || _pendingPurchase) return;
    final captured = DateTime.now();
    final now = widget.session.workspacePurchaseEntryRemoteCapture ? captured.toUtc() : captured;
    var profile = WorkspaceSupplierProfile(id: _supplierId, name: _name.text.trim(),
      phone: _phone.text.trim().replaceAll(RegExp(r'[\s()-]'), ''),
      address: _address.text.trim(), gstin: _gstin.text.trim().toUpperCase(),
      createdAt: _supplier?.createdAt ?? now, updatedAt: now);
    var draft = WorkspacePurchaseEntryDraft(id: _draftId, supplierId: profile.id,
      invoiceReference: _reference.text.trim(), invoiceDate: _date.text.trim(),
      createdAt: _original?.createdAt ?? now, updatedAt: now,
      goods: _goods.map((line) => line.fields).toList(),
      details: {for (final e in _details.entries) if (e.value.text.isNotEmpty) e.key: e.value.text},
      attachments: _attachments, additionalFields: _additional.map((f) => f.field).toList(),
      printedTaxRows: _printedTaxRows);
    if (reviewed) {
      if (_name.text.trim().isEmpty || _reference.text.trim().isEmpty || _date.text.trim().isEmpty ||
          !_goods.any((line) => line.name.text.trim().isNotEmpty)) {
        _showSaveError('Enter supplier, invoice number/date and items before saving a purchase copy. Save draft to finish later.');
        return;
      }
      if (_copyAttempt == null || _copyAttemptInput != _input) {
        _copyAttemptInput = _input;
        _copyAttempt = WorkspacePurchaseSavedCopy(
          id: '$_draftId-reviewed-r${(_revision ?? 0) + 1}',
          storeName: widget.session.activeWorkspace?.name ?? 'Store',
          revision: (_revision ?? 0) + 1, savedAt: now, supplier: profile, draft: draft,
          labels: _exportLabels);
      }
      profile = _copyAttempt!.supplier;
      draft = _copyAttempt!.draft;
    }
    if (profile.validationError != null || !draft.valid) {
      _showSaveError(profile.validationError ??
        'Check your entries before saving. Each extra detail needs a heading (up to 120 characters) and details (up to 4,000). Keep up to 200 extra details and 48,000 characters in total. Your entries are kept.');
      return;
    }
    FocusScope.of(context).unfocus();
    setState(() { _busy = true; _error = null; });
    try {
      for (final attachment in _attachments) {
        await widget.session.workspacePurchaseInvoiceCapture.read(_scope!, _draftId, attachment);
      }
    } on Object catch (e) {
      if (mounted) {
        setState(() => _busy = false);
        _showSaveError(e is WorkGatewayException ? e.message :
          'Could not open the attached bill. Your entries are kept; attach the original again.');
      }
      return;
    }
    if (!mounted || !_current) {
      if (mounted) setState(() => _busy = false);
      return;
    }
    final saved = await widget.session.saveWorkspacePurchaseEntry(profile, scope: _scope!,
      draft: draft, expectedRevision: _revision, reviewedCopy: reviewed ? _copyAttempt : null,
      replaceReviewedDraftId: _replaceReviewedDraftId);
    if (!mounted) return;
    setState(() => _busy = false);
    if (saved && _current) {
      _baseline = _input;
      widget.onBack();
    } else {
      final pending = widget.session.workspacePendingPurchaseInput;
      if (pending != null && _current) {
        setState(() => _restorePurchaseInput(pending));
      } else if (widget.session.workspacePurchaseEntryRemoteCapture) {
        // A definitive refusal allows explicit correction with a fresh copy.
        _copyAttempt = null; _copyAttemptInput = null;
      }
      _showSaveError(widget.session.workspaceSupplierError ??
        'Return to the Store where you started this bill. Your entries are kept.');
    }
  }
  void _showSaveError(String message) {
    if (!mounted) return;
    if (_current) FocusScope.of(context).unfocus();
    setState(() => _error = message);
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted || !_current || _error != message) return;
      unawaited(_revealAddedTradeLine(_purchaseEntryScroll, _saveErrorAnchor,
        () => mounted && _current && _error == message));
    });
  }
  Future<void> _refreshSaved() async {
    if (_busy || !_current) return;
    if (_pendingPurchase) { await _checkPurchaseSave(); return; }
    if (_draftId.isEmpty || _readOnly) { await _load(retry: true); return; }
    setState(() { _busy = true; _error = null; });
    final opened = await widget.session.loadWorkspaceSuppliers(retry: true);
    if (!mounted) return;
    setState(() => _busy = false);
    if (!_current || !opened) {
      setState(() => _error = widget.session.workspaceSupplierError ??
        'Cannot reopen saved purchases. Your entries are kept; retry.');
      return;
    }
    final attempted = _copyAttempt;
    if (attempted != null && widget.session.workspacePurchaseCopies.any((c) =>
        jsonEncode(c.toJson()) == jsonEncode(attempted.toJson()))) {
      // Reconcile a committed operation without writing its old draft back.
      _baseline = _input;
      widget.onBack();
      return;
    }
    final latest = widget.session.workspacePurchaseEntryDraft;
    final retainedReviewedDraft = _replaceReviewedDraftId != null &&
      latest?.id == _replaceReviewedDraftId && widget.session.workspacePurchaseDraftReviewed;
    if (latest != null && latest.id != _draftId && !retainedReviewedDraft) {
      setState(() => _error = 'Another purchase draft is saved. Your entries are kept; return to Purchases to choose it.');
      return;
    }
    setState(() {
      _original = retainedReviewedDraft ? null : latest;
      if (!retainedReviewedDraft) _replaceReviewedDraftId = null;
      _supplier = widget.session.workspaceSuppliers.where((p) => p.id == _supplierId).firstOrNull;
      _revision = widget.session.workspacePurchaseEntryRevision;
      _copyAttempt = null;
      _copyAttemptInput = null;
      _notice = 'Saved records refreshed. Your entries are kept; review the purchase before saving again.';
      _reviewFocused = false;
    });
  }
  @override
  void dispose() {
    _receivingTaxLease?.dispose();_receivingTaxEdits.dispose();
    _openPurchaseAssistantEditors[_assistantEditorOwner]?.remove(_assistantEditorToken);
    for (final controller in _billPanelControllers.values) { controller.dispose(); }
    _savedBillScroll.dispose();
    _purchaseEntryScroll.dispose();
    for (final c in [_name, _phone, _address, _gstin, _reference, _date]) { c.dispose(); }
    for (final c in _details.values) { c.dispose(); }
    _supplierFocus.dispose();
    _sourceEpoch++;
    final route = _previewRoute;
    void releasePreview() {
      _previewZoom.dispose();
      _previewChanges.dispose();
      _recordedItemScroll.dispose();
      _recordedTaxScroll.dispose();
      _sourcePdf.dispose();
    }
    if (route == null) {
      releasePreview();
    } else {
      // The root overlay must stop using this editor's resources before release.
      route.completed.then((_) => releasePreview());
      WidgetsBinding.instance.addPostFrameCallback((_) {
        final navigator = route.navigator;
        if (navigator != null && navigator.mounted && route.isActive) navigator.removeRoute(route);
      });
    }
    for (final line in _goods) { line.dispose(); }
    for (final field in _additional) { field.dispose(); }
    for (final row in _taxRows) { for (final c in row.values) { c.dispose(); } }
    super.dispose();
  }
  Widget _extraFields(String section, {int? itemIndex, int? summaryIndex}) {
    final selected = _additional.where((f) => f.record.section == section &&
      f.record.itemIndex == itemIndex && f.record.summaryIndex == summaryIndex);
    final owner = '$section-${itemIndex ?? 'all'}-${summaryIndex ?? 'all'}';
    final heading = switch (section) {
      'supplier' => 'Other supplier details', 'buyer' => 'Other buyer details',
      'items' => itemIndex == null ? 'Scanned item details to match' : 'Other item details',
      'tax' => summaryIndex == null ? 'Other tax details' : 'Other tax-row details',
      'receipt' => 'Other delivery details', 'payment' => 'Other payment details',
      _ => 'Other invoice details',
    };
    final example = switch (section) {
      'supplier' => ('Supplier code', 'SUP-104'),
      'buyer' => ('Customer code', 'CUST-104'),
      'items' => ('Grade', 'A'),
      'tax' => ('Exempt amount', '250.00'),
      'receipt' => ('LR number', 'LR-104'),
      'payment' => ('Credit period', '30 days'),
      _ => ('Dispatch reference', 'DSP-104'),
    };
    return _section('$heading${selected.isEmpty ? '' : ' · ${selected.length}'}',
      'work-purchase-extra-$owner', [
        if (selected.isEmpty) const Text('Add a printed detail that has no field above. Copy its field name and value.',
          style: TextStyle(fontSize: 11, color: MoolColors.muted)),
        for (final input in selected) ...[
          if (input.record.sourceItemIndex != null && input.record.itemIndex == null) ...[
            Text('From scanned item ${input.record.sourceItemIndex! + 1}. Choose the entered item it belongs to.',
              style: const TextStyle(fontSize: 11, color: MoolColors.muted)),
            DropdownButtonFormField<int>(key: Key('purchase-extra-match-${input.record.id}'),
              isExpanded: true, decoration: const InputDecoration(labelText: 'Choose invoice item',
                filled: false, isDense: true),
              items: [for (final (index, line) in _goods.indexed)
                DropdownMenuItem(value: index, child: Text('Item ${index + 1} · ${line.name.text}',
                  maxLines: 1, overflow: TextOverflow.ellipsis,
                  style: const TextStyle(fontSize: 12, color: MoolColors.ink)))],
              onChanged: (index) {
                if (index == null) return;
                final field = input.field;
                setState(() {
                  input.reviewed = false;
                  input.record = WorkspacePurchaseAdditionalField(id: field.id,
                    label: field.label, value: field.value, section: field.section, itemIndex: index,
                    sourceDigest: field.sourceDigest, sourcePage: field.sourcePage,
                    sourceItemIndex: field.sourceItemIndex, reviewed: false);
                });
              }),
          ],
          _field('Field name as printed', input.label, 'purchase-extra-label-${input.record.id}',
            hint: 'e.g. ${example.$1}', limit: 120, changed: (_) => setState(() => input.reviewed = false)),
          _field('Value as printed', input.value, 'purchase-extra-value-${input.record.id}',
            hint: 'e.g. ${example.$2}', limit: 4000, multiline: true, changed: (_) => setState(() => input.reviewed = false)),
          Row(children: [Expanded(child: Text(input.reviewed ? 'Checked with original bill' : 'Check original bill',
            style: const TextStyle(fontSize: 11, color: MoolColors.ink))),
            IconButton(tooltip: input.reviewed ? 'Check again' : 'Mark as checked',
              key: Key('purchase-extra-check-${input.record.id}'),
              onPressed: () => setState(() => input.reviewed = !input.reviewed),
              icon: Icon(input.reviewed ? Icons.check_circle_outline : Icons.radio_button_unchecked,
                size: 18, color: MoolColors.navy)),
            IconButton(key: Key('purchase-extra-remove-${input.record.id}'), tooltip: 'Remove extra detail', onPressed: () {
              final copyIndex = _attachments.indexWhere((a) => a.digest == input.record.sourceDigest);
              WorkspacePurchaseInvoiceAttachment? updated;
              if (copyIndex >= 0) {
                final copy = _attachments[copyIndex];
                updated = copy.withExtractedFields(copy.extractedFields, overflow: copy.extractionOverflow,
                  dismissed: {...copy.dismissedFieldIds, input.record.id}.toList());
                if (!updated.valid) {
                  setState(() => _error = 'The saved-copy detail limit is reached. Your field is kept; split the document before removing more scanned details.');
                  return;
                }
              }
              setState(() {
                if (updated != null) _attachments[copyIndex] = updated;
                _additional.remove(input);
              }); input.dispose();
            }, icon: const Icon(Icons.close_rounded, size: 18, color: MoolColors.navy))]),
        ],
        Align(alignment: Alignment.centerLeft, child: TextButton.icon(
          key: Key('work-purchase-add-extra-$owner'),
          onPressed: _additional.length >= 200 ? null : () => setState(() => _additional.add(
            _PurchaseAdditionalInput(WorkspacePurchaseAdditionalField(
              id: 'manual-${DateTime.now().microsecondsSinceEpoch}', label: '', value: '',
              section: section, itemIndex: itemIndex, summaryIndex: summaryIndex)))),
          icon: const Icon(Icons.add_rounded, size: 16),
          label: const Text('Add printed detail', style: TextStyle(fontSize: 12, color: MoolColors.navy)))),
      ]);
  }
  Future<void> _removeInvoiceRow(int index, {bool tax = false}) async {
    final associated = _additional.where((f) => tax ? f.record.summaryIndex == index : f.record.itemIndex == index).toList();
    if (associated.isNotEmpty && await showDialog<bool>(context: context, builder: (context) =>
      AlertDialog(title: Text(tax ? 'Remove tax row?' : 'Remove invoice item?'),
        content: const Text('Extra details added to this row will also be removed from this draft.'),
        actions: [TextButton(onPressed: () => Navigator.pop(context, false), child: const Text('Keep')),
          TextButton(onPressed: () => Navigator.pop(context, true), child: const Text('Remove'))])) != true) {
      return;
    }
    if (!mounted) return;
    setState(() {
      for (final input in associated) { _additional.remove(input); input.dispose(); }
      for (final input in _additional) {
        final f = input.field;
        if ((tax ? f.summaryIndex : f.itemIndex) case final int linked when linked > index) {
          input.record = WorkspacePurchaseAdditionalField(id: f.id, label: f.label, value: f.value,
            section: f.section, itemIndex: tax ? f.itemIndex : linked - 1,
            summaryIndex: tax ? linked - 1 : f.summaryIndex, sourceDigest: f.sourceDigest,
            sourcePage: f.sourcePage, sourceItemIndex: f.sourceItemIndex, reviewed: f.reviewed);
        }
      }
      if (tax) { for (final c in _taxRows.removeAt(index).values) { c.dispose(); } }
      else { _goods.removeAt(index).dispose(); }
    });
  }
  Widget _printedTaxTable() => _section('HSN / tax table on bill', 'work-purchase-printed-tax-table', [
    const Text('Copy the rows and TOTAL from your bill. These are kept as shown, not recalculated.',
      style: TextStyle(fontSize: 11, color: MoolColors.ink)),
    for (final (index, row) in _taxRows.indexed) ...[
      Row(children: [Expanded(child: Text('Tax row ${index + 1}',
        style: const TextStyle(fontSize: 12, color: MoolColors.navy, fontWeight: FontWeight.w600))),
        IconButton(tooltip: 'Remove tax row ${index + 1}', onPressed: () => _removeInvoiceRow(index, tax: true),
          icon: const Icon(Icons.close_rounded, size: 18))]),
      _compactFields([_field('Tax row description', row['label']!, 'purchase-tax-label-$index'),
        _field('HSN / SAC', row['hsn']!, 'purchase-tax-hsn-$index'),
        _field('Taxable value ₹', row['taxableValue']!, 'purchase-tax-taxable-$index')]),
      _section('Tax rates & amounts', 'purchase-tax-components-$index', [
        _compactFields([for (final e in const {'cgstRate':'CGST %', 'cgst':'CGST ₹',
          'sgstRate':'SGST %', 'sgst':'SGST ₹', 'utgstRate':'UTGST %', 'utgst':'UTGST ₹',
          'igstRate':'IGST %', 'igst':'IGST ₹', 'cessRate':'Cess %', 'cess':'Cess ₹',
          'taxRate':'Total GST %', 'totalTax':'Total tax ₹'}.entries)
          _field(e.value, row[e.key]!, 'purchase-tax-${e.key}-$index')]),
      ]),
      _extraFields('tax', summaryIndex: index),
    ],
    Align(alignment: Alignment.centerLeft, child: TextButton.icon(
      key: const Key('work-purchase-add-tax-row'), onPressed: _taxRows.length >= 100 ? null :
        () => setState(() => _taxRows.add({for (final key in WorkspacePurchaseEntryDraft.printedTaxKeys)
          key: TextEditingController()})), icon: const Icon(Icons.add_rounded, size: 16),
      label: const Text('Add tax-table row', style: TextStyle(fontSize: 12, color: MoolColors.navy)))),
  ]);
  Widget _field(String label, TextEditingController controller, String key, {
      int limit = 200, TextInputType? keyboard, FocusNode? focus,
      ValueChanged<String>? changed, String? hint, bool lookup = false, bool multiline = false}) {
    _fieldLabels[key] = label;
    // Entry examples are presentation only: never put them in the controllers.
    final entryHint = hint ?? switch (label) {
      'Supplier name' => 'Name on supplier bill',
      'Supplier phone' => 'Phone number',
      'Supplier email' => 'e.g. name@firm.in',
      'Supplier address' => 'Street, city and PIN',
      'Supplier GSTIN' => 'GSTIN, if registered',
      'Supplier invoice number' => 'e.g. INV-104',
      'Document title' => 'e.g. Tax invoice',
      'Date exactly as printed' => 'e.g. 23-Oct-2026',
      'Purchase order number' => 'PO number on bill',
      'Invoice copy type' => 'e.g. Original copy',
      'IRN' => '64-character IRN',
      'Ack. number' => 'Number with IRN',
      'Supplier declaration' => 'Printed declaration',
      'Buyer name on invoice' => 'Business name as billed',
      'Billing address' => 'Buyer address on bill',
      'Buyer phone' => 'Phone number',
      'Buyer email' => 'e.g. buyer@firm.in',
      'Buyer GSTIN' => 'GSTIN, if registered',
      'Buyer UIN (if printed)' => 'UIN, if printed',
      'Billing State' || 'Ship-to State' || 'Place of supply' => 'e.g. Rajasthan',
      'Billing State code' || 'Ship-to State code' || 'Supply State code' => 'e.g. 08',
      'Ship-to address' => 'Delivery address',
      'Item name on invoice' => 'Description on bill',
      'Unit on invoice' => 'e.g. kg',
      'Billed qty' => 'e.g. 10',
      'Rate / unit ₹' => 'e.g. 50.00',
      'HSN / SAC' => 'Code on invoice',
      'Invoice line no.' => 'e.g. 1',
      'Model / specifications' => 'Printed model / grade',
      'Item code / barcode' => 'e.g. ITEM-104',
      'Unit code on invoice' => 'e.g. KGS',
      'Free qty' => 'e.g. 2',
      'Batch No.' => 'e.g. B-104',
      'Expiry date' => 'Expiry date as printed',
      'Total items' => 'Item count on bill',
      'Total quantity' => 'Qty & unit on bill',
      'Amount in words' => 'Written bill amount',
      'Tax row description' => 'e.g. TOTAL',
      'Received qty' => 'Units received',
      'Damaged qty' => 'Damaged units',
      'Short qty' => 'Units short',
      'Delivery / shipping terms' => 'Agreed delivery terms',
      'Payment reference / UTR' => 'UTR / receipt no.',
      'Payment / credit terms' => 'e.g. Net 30 days',
      'Printed payment remark' => 'e.g. Paid / Credit',
      'Supplier bank name' => 'Bank as on bill',
      'Supplier account number' => 'Account no. on bill',
      'IFSC' => 'e.g. ABCD0123456',
      'Branch' => 'Branch as on bill',
      'Supplier UPI app' => 'App, if printed',
      'Supplier UPI ID' => 'e.g. shop@bank',
      'Terms & conditions' => 'Printed supplier terms',
      'Signatory name' => 'Name by signature',
      'Signatory business name' => 'Business by signature',
      'Signature caption' => 'e.g. Proprietor',
      'Printed declaration' => 'Declaration on bill',
      'Invoice footer text' => 'Closing text on bill',
      'Purchase narration' => 'Your purchase note',
      'Exempt value ₹' => 'e.g. 250.00',
      _ when label.endsWith('₹') => 'e.g. 250.00',
      _ when label.endsWith('%') => 'e.g. 5',
      _ => null,
    };
    return TextField(key: Key(key), controller: controller, readOnly: _pendingPurchase,
    focusNode: focus, maxLength: limit, maxLengthEnforcement: MaxLengthEnforcement.none, keyboardType: keyboard,
    minLines: 1, maxLines: multiline ? null : 1,
    textAlign: keyboard?.index == TextInputType.number.index ? TextAlign.right : TextAlign.left,
    textInputAction: TextInputAction.next, onChanged: changed ?? (_) => setState(() {}),
    style: TextStyle(fontSize: 13, color: _paperInk, letterSpacing: 0,
      fontWeight: const ['work-purchase-invoiceTotal', 'work-purchase-amountPayable'].contains(key)
        ? FontWeight.w600 : FontWeight.w400),
    decoration: InputDecoration(labelText: label, hintText: entryHint, counterText: '', filled: false,
      floatingLabelBehavior: FloatingLabelBehavior.always,
      // Flutter scales floating labels by .75. 16 keeps the visible label at 12sp.
      floatingLabelStyle: const TextStyle(fontSize: 16, color: _paperMuted),
      labelStyle: const TextStyle(fontSize: 12, color: _paperMuted),
      hintStyle: const TextStyle(fontSize: 13, color: _paperMuted, fontWeight: FontWeight.w400),
      isDense: true, contentPadding: const EdgeInsets.symmetric(vertical: 8),
      border: lookup ? InputBorder.none : const UnderlineInputBorder(borderSide: BorderSide(color: _paperRule)),
      enabledBorder: lookup ? InputBorder.none : const UnderlineInputBorder(borderSide: BorderSide(color: _paperRule)),
      focusedBorder: lookup ? InputBorder.none : const UnderlineInputBorder(borderSide: BorderSide(color: MoolColors.navy)),
      disabledBorder: InputBorder.none, errorBorder: InputBorder.none,
      focusedErrorBorder: InputBorder.none));
  }
  Widget _purchaseSection(String title, String key, List<Widget> fields,
      {required int number, required String summary}) {
    final expanded = _expandedSections.contains(key);
    final instruction = switch (key) {
      'work-purchase-supplier-section' => 'Enter who supplied the goods, as shown on the invoice.',
      'work-purchase-invoice-section' => 'Copy the invoice number, date and printed references.',
      'work-purchase-buyer-details' => 'Check your billed-to details and the delivery address.',
      'work-purchase-items-section' => 'Copy each item, quantity and rate; match it to Stock.',
      'work-purchase-tax-details' => 'Copy tax, discounts and totals from the invoice. Leave missing amounts blank.',
      'work-purchase-receipt-details' => 'Check the goods in hand; record shortages or damage.',
      'work-purchase-payment-details' => 'Record payments actually made. Copy any printed Paid / Credit remark separately below.',
      _ => 'Compare this entered record with the original, then save draft.',
    };
    return Column(key: key == 'work-purchase-review-section' ? _reviewAnchor
        : key == 'work-purchase-items-section' ? _itemsAnchor : null,
      crossAxisAlignment: CrossAxisAlignment.stretch, children: [
      Semantics(expanded: expanded, child: InkWell(key: Key(key), onTap: () {
        if (key == 'work-purchase-review-section') {
          _showReadingPreview(recorded: _sourceAttachment == null);
          return;
        }
        FocusScope.of(context).unfocus();
        setState(() {
          _reviewFocused = key == 'work-purchase-review-section' && !expanded;
          if (expanded) { _expandedSections.remove(key); } else { _expandedSections.add(key); }
        });
      }, child: Container(constraints: const BoxConstraints(minHeight: 52),
        padding: const EdgeInsets.symmetric(vertical: 8),
        decoration: const BoxDecoration(border: Border(bottom: BorderSide(color: _paperRule, width: .7))),
        child: Row(children: [
          Container(width: 24, height: 24, alignment: Alignment.center,
            decoration: const BoxDecoration(shape: BoxShape.circle, color: Color(0xffeeece5)),
            child: Text(number.toString().padLeft(2, '0'),
              style: const TextStyle(fontSize: 11, fontWeight: FontWeight.w600, color: MoolColors.navy))),
          const SizedBox(width: 10),
          Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Text(title, style: const TextStyle(fontSize: 13, fontWeight: FontWeight.w600, color: _paperInk)),
            Text(summary, maxLines: 2, overflow: TextOverflow.ellipsis,
              style: TextStyle(fontSize: 12, color: _paperMuted,
                fontWeight: key == 'work-purchase-invoice-section' && _details['invoiceTotal']!.text.isNotEmpty
                  ? FontWeight.w600 : FontWeight.w400)),
          ])),
          const SizedBox(width: 8),
          Icon(expanded ? Icons.expand_less_rounded : Icons.expand_more_rounded, size: 20, color: MoolColors.navy),
        ])))),
      if (expanded) Padding(padding: const EdgeInsets.symmetric(vertical: 8),
        child: Column(key: ValueKey('purchase-panel-$key'),
          crossAxisAlignment: CrossAxisAlignment.stretch, children: [
            if (key != 'work-purchase-review-section')
              Padding(padding: const EdgeInsets.only(bottom: 8), child: Text(instruction,
              key: ValueKey('purchase-instruction-$key'),
              style: const TextStyle(fontSize: 12, color: _paperMuted))), ...fields])),
    ]);
  }
  // Subheadings are not controls. A single main-step tap exposes all its fields.
  Widget _section(String title, String key, List<Widget> children) => Column(
    key: Key(key), crossAxisAlignment: CrossAxisAlignment.stretch, children: [
      Padding(padding: const EdgeInsets.only(top: 12, bottom: 6), child: Text(title,
        style: const TextStyle(fontSize: 12, fontWeight: FontWeight.w600, color: MoolColors.navy))),
      ...children,
    ]);
  Widget _remainingSteps(List<({String title, String key, List<Widget> fields})> sections) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch, children: [
      for (var i = 0; i < sections.length; i++)
        _purchaseSection(sections[i].title, sections[i].key, sections[i].fields, number: i + 5,
          summary: switch (sections[i].key) {
            'work-purchase-tax-details' => _details['invoiceTotal']!.text.isEmpty
              ? 'Copy taxes, discounts and the final total' : 'Invoice total ${_invoiceMoney(_details['invoiceTotal']!.text, currency: true)}',
            'work-purchase-receipt-details' => _details['receiptStatus']!.text.isEmpty
              ? 'Check received, short or damaged goods' : _details['receiptStatus']!.text,
            'work-purchase-payment-details' => _details['paymentStatus']!.text.isEmpty
              ? 'Amount paid, credit and due date' : [ _details['paymentStatus']!.text,
                  if (_details['dueDate']!.text.isNotEmpty) 'Due ${_details['dueDate']!.text}'].join(' · '),
            _ => '',
          }),
    ]);
  }
  Widget _detail(String label, String key, {bool number = false, bool date = false}) =>
    _field(label, _details[key]!, 'work-purchase-$key', limit: number ? 14 : date ? 10 : key == 'terms' ? 4000 : 500,
      hint: date ? 'DD/MM/YYYY' : key == 'documentTitle' ? switch (_documentType) {
        'GST invoice' || 'Tax invoice' => 'e.g. Tax invoice',
        'Bill of supply' => 'Bill of supply',
        'Non-GST purchase bill' => 'Bill / cash memo',
        _ => 'Printed title',
      } : null,
      multiline: const ['buyerAddress', 'deliveryAddress', 'terms', 'notes', 'shippingTerms', 'paymentTerms', 'amountInWords', 'printedDeclaration'].contains(key),
      keyboard: number ? const TextInputType.numberWithOptions(decimal: true, signed: true)
        : date ? TextInputType.datetime : key.endsWith('Email') ? TextInputType.emailAddress
        : key == 'buyerPhone' ? TextInputType.phone : null);
