  void _closeSource() {
    _sourceEpoch++;
    _sourcePdf.dispose();
    _sourcePdf = WorkPdfPreview();
    _sourceAttachment = null;
    _sourceBytes = null;
    _sourcePage = null;
    _sourceLoading = false;
    _sourceError = _sourceNotice = null;
  }
  bool _sourceCurrent(int epoch) => mounted && _current && epoch == _sourceEpoch &&
    _attachments.any((a) => a.digest == _sourceAttachment?.digest);
  Future<void> _openSource(WorkspacePurchaseInvoiceAttachment attachment, {int page = 0}) async {
    if (_busy || _sourceSaving || !_current || _scope == null) return;
    _closeSource();
    _lastOriginal = attachment;
    _lastOriginalPage = page;
    _requestedSourcePage = page;
    final epoch = _sourceEpoch;
    setState(() { _sourceAttachment = attachment; _sourceLoading = true; });
    _previewPurchase(recorded: false);
    try {
      final bytes = await widget.session.workspacePurchaseInvoiceCapture.read(_scope!, _draftId, attachment);
      if (!_sourceCurrent(epoch)) return;
      _sourceBytes = bytes;
      if (attachment.contentType == 'application/pdf') {
        final rendered = await _sourcePdf.render(bytes, page: page);
        if (!_sourceCurrent(epoch)) return;
        _sourcePage = rendered;
      }
    } on WorkGatewayException catch (error) {
      if (_sourceCurrent(epoch)) _sourceError = error.message;
    } on WorkPdfPreviewException catch (error) {
      if (_sourceCurrent(epoch)) { _sourceError = error.message; }
    } on Object {
      if (_sourceCurrent(epoch)) _sourceError = 'Cannot open the original invoice. Retry, or attach the original again.';
    } finally {
      if (_sourceCurrent(epoch)) {
        setState(() => _sourceLoading = false);
        _positionReview();
      }
    }
  }
  Future<void> _sourceTurnPage(int index) async {
    if (_sourceLoading || _sourceBytes == null || _sourcePage == null ||
        index < 0 || index >= _sourcePage!.pageCount) { return; }
    final epoch = _sourceEpoch;
    if (!_sourceCurrent(epoch)) return;
    setState(() { _sourceLoading = true; _sourceError = null; _requestedSourcePage = index; });
    try {
      final page = await _sourcePdf.render(_sourceBytes!, page: index);
      if (_sourceCurrent(epoch)) {
        _previewZoom.value = Matrix4.identity();
        _sourcePage = page;
        _lastOriginalPage = index;
      }
    } on WorkPdfPreviewException catch (error) {
      if (_sourceCurrent(epoch)) { _sourceError = error.message; }
    } finally {
      if (_sourceCurrent(epoch)) setState(() => _sourceLoading = false);
    }
  }
  Future<void> _downloadSource() async {
    final attachment = _sourceAttachment;
    final epoch = _sourceEpoch;
    if (_sourceSaving || attachment == null || !_sourceCurrent(epoch) || _scope == null) return;
    setState(() { _sourceSaving = true; _sourceNotice = _sourceError = null; });
    try {
      // Recheck the saved source's ownership, length and hash before handing its
      // unchanged bytes to the existing system save picker, never a page image.
      final bytes = await widget.session.workspacePurchaseInvoiceCapture.read(_scope!, _draftId, attachment);
      if (!_sourceCurrent(epoch)) return;
      final extension = switch (attachment.contentType) {
        'application/pdf' => 'pdf', 'image/png' => 'png',
        'image/jpeg' => 'jpg', 'image/webp' => 'webp', _ => throw StateError('Unsupported original'),
      };
      final result = await FilePicker.saveFile(dialogTitle: 'Save supplier invoice copy',
        fileName: 'purchase-original-${attachment.digest.substring(0, 16)}.$extension',
        mimeType: attachment.contentType, type: FileType.custom, allowedExtensions: [extension], bytes: bytes);
      if (_sourceCurrent(epoch)) {
        _sourceNotice = result == null
          ? 'Download cancelled. Supplier copy kept.' : 'Supplier copy saved.';
      }
    } on WorkGatewayException catch (error) {
      if (_sourceCurrent(epoch)) { _sourceError = error.message; }
    } on Object {
      if (_sourceCurrent(epoch)) _sourceError = 'Could not save the supplier copy. It is kept; retry.';
    } finally {
      if (mounted) setState(() => _sourceSaving = false);
    }
  }
  StorePurchaseAccountingSnapshot get _accountingSnapshot => !_readOnly
    ? StorePurchaseAccountingSnapshot.draft
    : StorePurchaseAccountingSnapshot.capture(copy: widget.savedCopy!, scope: _scope,
        recovered: _current && widget.session.workspaceSupplierScope == _scope &&
          widget.session.workspaceInvoiceHistoryLoaded && !widget.session.workspaceSupplierRecoveryRequired,
        ledger: widget.session.workspaceSupplierLedger(widget.savedCopy!.supplier.id));
  bool _recordedCurrent(WorkspacePurchaseEntryDraft draft, WorkspaceSupplierProfile supplier, int revision) =>
    mounted && _current && widget.session.workspaceSuppliersLoaded && !_dirty && !_busy && !widget.session.workspaceSupplierSaving &&
    (_readOnly ? widget.session.workspacePurchaseCopies.any((c) => c.id == widget.savedCopy!.id &&
      jsonEncode(c.toJson()) == jsonEncode(widget.savedCopy!.toJson())) :
    widget.session.workspaceSupplierError == null && _original == draft && _supplier == supplier &&
    widget.session.workspacePurchaseEntryDraft == draft && widget.session.workspacePurchaseEntryRevision == revision &&
    widget.session.workspaceSuppliers.contains(supplier) && draft.supplierId == supplier.id);
  Future<void> _downloadRecorded() async {
    if (_recordedSaving) return;
    final draft = _original, supplier = _supplier, revision = _revision;
    if (draft == null || supplier == null || revision == null || !_recordedCurrent(draft, supplier, revision)) {
      setState(() => _recordedNotice = _readOnly
        ? 'Saved purchase copy is unavailable. Reopen it from Purchases and retry.'
        : _dirty || draft == null
        ? 'Save draft, then reopen it to download the saved copy. Your entries are kept.'
        : 'Saved details changed or are unavailable. Reopen this purchase draft and retry.');
      return;
    }
    final accounting = _accountingSnapshot;
    bool evidenceCurrent() => _recordedCurrent(draft, supplier, revision) &&
      accounting.sameEvidence(_accountingSnapshot);
    setState(() { _recordedSaving = true; _recordedNotice = null; });
    try {
      final bytes = await generateStorePurchaseRecordedCopy(draft: draft, supplier: supplier,
        storeName: widget.savedCopy?.storeName ?? widget.session.activeWorkspace?.name ?? 'Store', storeId: _scope!.$2,
        revision: revision, labels: widget.savedCopy?.labels ?? _exportLabels, isSavedCopy: _readOnly,
        accounting: accounting);
      if (!evidenceCurrent()) {
        if (mounted && _current) {
          setState(() => _recordedNotice = _readOnly
            ? !_recordedCurrent(draft, supplier, revision)
              ? 'Saved purchase copy changed or is unavailable. Reopen it from Purchases before downloading.'
              : 'Supplier account status changed. Reopen this purchase before downloading.'
            : 'Saved details changed. Reopen this purchase draft before downloading.');
        }
        return;
      }
      // Filename binds to the saved entry version, not typed bill text.
      final stamp = draft.updatedAt.microsecondsSinceEpoch;
      final result = await FilePicker.saveFile(dialogTitle: 'Save recorded purchase copy',
        fileName: 'purchase-recorded-$stamp-r$revision.pdf', mimeType: 'application/pdf',
        type: FileType.custom, allowedExtensions: ['pdf'], bytes: bytes);
      if (evidenceCurrent()) {
        setState(() => _recordedNotice = result == null
          ? _readOnly ? 'Download cancelled. Your saved purchase copy is kept.'
            : 'Download cancelled. Your saved draft is kept.'
          : _readOnly ? 'Purchase copy downloaded.' : 'Recorded copy saved.');
      }
    } on FormatException catch (error) {
      if (mounted && _current) setState(() => _recordedNotice = error.message);
    } on Object {
      if (mounted && _current) {
        setState(() => _recordedNotice = _readOnly
          ? 'Could not download the purchase copy. It is kept; retry.'
          : 'Could not download the recorded copy. Your saved draft is kept; retry.');
      }
    } finally {
      if (mounted) setState(() => _recordedSaving = false);
    }
  }
  String _invoiceMoney(String text, {bool currency = false}) {
    final minor = WorkspacePurchaseEntryDraft.printedPaise(text);
    if (minor == null) return text;
    final absolute = minor.abs();
    return '${minor < 0 ? '−' : ''}${currency ? '₹' : ''}'
      '${_formatStoreAmount(absolute ~/ 100)}.${(absolute % 100).toString().padLeft(2, '0')}';
  }
