          if (await _openBillPanel(copy, 'account') && mounted && _current) controller.expand();
        }, icon: const Icon(Icons.account_balance_outlined, size: 18),
        label: const Text('Supplier ledger')),
    ]);
    return Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
      Column(key: const Key('work-purchase-bill-identity'),
        crossAxisAlignment: CrossAxisAlignment.stretch, children: [
        Row(children: [Expanded(flex: 7, child: Text(copy.supplier.name,
          style: const TextStyle(fontSize: 12, fontWeight: FontWeight.w600, color: _paperInk))),
          const SizedBox(width: 8),
          Expanded(flex: 3, child: Text(copy.draft.invoiceDate, textAlign: TextAlign.right,
            style: const TextStyle(fontSize: 10, color: _paperMuted))),
        ]),
        Row(children: [Expanded(flex: 6, child: Text('Bill ${copy.draft.invoiceReference}',
          style: const TextStyle(fontSize: 11, color: _paperInk))), const SizedBox(width: 8),
          Expanded(flex: 4, child: Text(!ready ? 'Supplier account status unavailable'
            : same ? 'Posted to supplier ledger'
            : accepted != null ? 'Another saved revision is confirmed · this copy is not posted'
            : 'Not posted to supplier ledger', key: const Key('work-purchase-bill-status'),
            textAlign: TextAlign.right, style: const TextStyle(fontSize: 10, color: _paperMuted))),
        ]),
      ]),
      Padding(padding: const EdgeInsets.symmetric(vertical: 4), child: Row(children: [
        if (same) Expanded(child: Text(ledger!.manualBillRemainingMinor(copy.draft.id) == null
            ? 'Individual bill due not yet verified'
            : ledger.manualBillRemainingMinor(copy.draft.id)! < 0
              ? 'Credit with supplier ${_purchaseAmount(-ledger.manualBillRemainingMinor(copy.draft.id)!)}'
              : 'Bill outstanding ${_purchaseAmount(ledger.manualBillRemainingMinor(copy.draft.id)!)}',
            key: const Key('work-purchase-payment-status'),
            textAlign: TextAlign.left,
            style: const TextStyle(fontSize: 16, fontWeight: FontWeight.w700, color: _paperInk)) ) else const Spacer(),
        const SizedBox(width: 8),
        Text(_sourceAttachment == null ? 'Recorded copy' : 'Supplier copy',
          key: const Key('work-purchase-bill-copy-kind'),
          style: const TextStyle(fontSize: 10, color: _paperMuted)),
      ])),
      TextButtonTheme(data: TextButtonThemeData(style:
        Theme.of(context).textButtonTheme.style?.copyWith(
          alignment: Alignment.center,
          textStyle: const WidgetStatePropertyAll(TextStyle(fontSize: 12, fontWeight: FontWeight.w500)),
          backgroundColor: const WidgetStatePropertyAll(Colors.white),
          padding: const WidgetStatePropertyAll(EdgeInsets.symmetric(horizontal: 6, vertical: 4)),
          shape: WidgetStatePropertyAll(RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(4), side: const BorderSide(color: MoolColors.line))))),
        child: Column(key: const Key('work-purchase-bill-actions-panel'),
          crossAxisAlignment: CrossAxisAlignment.stretch, spacing: 4, children: [
      if (!originalAccount && (same || (_billGoodsWasAccepted && !ready)))
      _StoreBillGoodsMatch(key: _billGoodsKey, session: session, copy: copy,
        onBeforeOpen: () => _openBillPanel(copy, 'goods'), actions: goodsActions,
        headerBuilder: (header) => actionGrid(header),
        summary: (verified) => Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.center, children: [
          const Text('Goods receipt', style: TextStyle(fontSize: 12, fontWeight: FontWeight.w600, color: MoolColors.navy)),
          if (same)
        Text(progress == null || !verified ? 'Reconciliation status unavailable'
          : !progress.hasMatches ? 'Pending reconciliation'
          : progress.matchedItems == progress.totalItems ? 'Fully reconciled'
          : 'Partly reconciled (${progress.matchedItems}/${progress.totalItems} items)',
          key: const Key('work-purchase-goods-status'),
          textAlign: TextAlign.center,
          style: const TextStyle(fontSize: 11, color: MoolColors.navy)),
          if (same) ...[
        if (verified && (progress?.damaged == true || progress?.shortage == true || progress?.returnedOnMatchedDelivery == true))
          Text([if (progress!.damaged) 'Damaged quantity reconciled', if (progress.shortage) 'Bill shortage recorded',
            if (progress.returnedOnMatchedDelivery) 'Return against goods receipt'].join(' · '),
            key: const Key('work-purchase-goods-exceptions'), style: const TextStyle(fontSize: 11, color: _paperMuted)),
          ],
        ]),
        onOpenCopy: (other) async {
          if (!await confirmLeave() || !mounted) return;
          final detailKey = GlobalKey<_StoreRecordPurchaseState>();
          var leaving = false;
          var allowPop = false;
          await Navigator.of(context).push<void>(MaterialPageRoute(builder: (pageContext) =>
            StatefulBuilder(builder: (routeContext, updateRoute) {
              void finishPop() {
                if (!routeContext.mounted || allowPop) return;
                updateRoute(() => allowPop = true);
                WidgetsBinding.instance.addPostFrameCallback((_) {
                  if (routeContext.mounted) Navigator.of(routeContext).pop();
                });
              }
              Future<void> requestPop() async {
                if (leaving || allowPop) return;
                leaving = true;
                final approved = await (detailKey.currentState?.confirmLeave() ?? Future.value(false));
                leaving = false;
                if (approved) finishPop();
              }
              return PopScope(canPop: allowPop,
                onPopInvokedWithResult: (didPop, result) { if (!didPop) unawaited(requestPop()); },
                child: Scaffold(body: SafeArea(child: _StoreRecordPurchaseSurface(key: detailKey,
                  session: session, savedCopy: other, onBack: finishPop))));
            })));
          if (mounted && _current) await _load(retry: true);
        }, ownerCurrent: _receivingPurchaseOwner, assistantReadOnlyOpen: widget.assistantReadOnlyOpen)
      else actionGrid(null),
      if (!(same || (_billGoodsWasAccepted && !ready))) goodsActions,
      if (same && !(progress != null && progress.totalItems > 0 &&
          progress.matchedItems == progress.totalItems && remaining != null && remaining > 0 &&
          session.workspaceSupplierMoneyInputAvailable && session.workspaceSupplierAllocationInputAvailable))
        Text(workPurchaseNextStep(progress: progress, remainingMinor: remaining),
          key: const Key('work-purchase-next-step'), style: const TextStyle(fontSize: 11, color: _paperMuted)),
      if (same) _StoreSupplierLedgerSummary(session: session, ledger: ledger, billId: copy.draft.id,
        compact: true, hideCompactHeader: true, controller: _billPanelController(copy, 'account'),
        onExpansionChanged: (expanded) { if (expanded) unawaited(_openBillPanel(copy, 'account')); }, ownerCurrent: _receivingPurchaseOwner, ownerChanges: _receivingPurchaseChanges),
      if ((session.workspaceSupplierOpeningConfirmationAvailable || originalAccount) && !ready)
        TextButton(key: const Key('work-purchase-bill-recover'),
          onPressed: _busy ? null : () => _load(retry: true), child: const Text('Retry supplier account')),
      if (ready && accepted == null && treatment == null)
        Text(ledger?.openingRecord == null
          ? 'Purchases → Opening dues: confirm this supplier’s starting balance. Confirm zero only if there are no earlier dues or advances.'
          : canReviewOpening
            ? 'Check whether this whole bill was included in the starting balance before confirming it.'
            : 'This bill conflicts with the saved starting-balance details. Review those details before confirming; the saved bill is kept unchanged.',
          style: const TextStyle(fontSize: 11, color: _paperMuted)),
      if (ready && accepted == null && !latestExact)
        const Text('Open the latest saved revision to confirm this bill.',
          style: TextStyle(fontSize: 11, color: _paperMuted)),
      if (pendingBill != null) ...[
        Text(session.workspaceOriginalLedgerError ?? 'This bill confirmation needs its original status checked.',
          key: const Key('work-purchase-bill-pending-status'),
          style: const TextStyle(fontSize: 12, color: _paperInk)),
        TextButton(key: const Key('work-purchase-bill-check-status'),
          onPressed: _busy || session.workspaceOriginalLedgerBusy ? null : () => _checkSavedBill(pendingBill),
          child: const Text('Check confirmation status')),
        TextButton(key: const Key('work-purchase-bill-retry-original'),
          onPressed: _busy || session.workspaceOriginalLedgerBusy ? null : () => _checkSavedBill(pendingBill, explicitRetry: true),
          child: const Text('Retry original confirmation')),
      ],
      if (ready && accepted == null && pendingBill == null && (treatment != null || canReviewOpening) && latestExact &&
          (session.workspaceSupplierOpeningConfirmationAvailable || session.workspaceOriginalSupplierBillConfirmationAvailable))
        TextButton.icon(key: const Key('work-purchase-bill-confirm'),
          onPressed: _busy || session.workspaceSupplierSaving ? null : () => _confirmSavedBill(copy),
          icon: const Icon(Icons.check_circle_outline, size: 18), label: const Text('Confirm bill in supplier account')),
      _reviewCopies(vertical: true),
      ])),
      if (_notice != null) Text(_notice!, key: const Key('work-purchase-bill-notice'),
        style: const TextStyle(fontSize: 12, color: _paperInk)),
    ]);
  }
  bool Function() _captureSavedBillOwner() {
    final session = widget.session, host = context.getInheritedWidgetOfExactType<MoolAssistantHost>();
    final captured = host?.readContext(), scope = session.workspaceSupplierScope;
    final original = session.workspaceOriginalSupplierOpeningConfigured;
    return () {
      if (!_current || session.workspaceSupplierScope != scope) return false;
      if (!original) return true;
      final current = host?.readContext(), account = current?.accountScope;
      return current?.binding == captured?.binding && account is
          ({String environment, String projectId, String? tenantId, String userId}) &&
        session.workspaceApprovalMatchesAccount(account);
    };
  }
  Future<void> _checkSavedBill(WorkspaceLedgerIntent original, {bool explicitRetry = false}) async {
    final owner = _captureSavedBillOwner();
    if (_busy || !owner()) return;
    setState(() {_busy = true; _notice = null;});
    final result = await widget.session.checkWorkspaceOriginalLedgerAttempt(original, explicitRetry: explicitRetry);
    if (!mounted || !owner()) return;
    setState(() {
      _busy = false;
      _notice = result?.attempt?['status'] == 'saved'
        ? 'Bill confirmation is recorded. Stock and payments stay unchanged.'
        : widget.session.workspaceOriginalLedgerError ?? 'The original confirmation status is not confirmed yet.';
    });
  }
  Future<void> _confirmSavedBill(WorkspacePurchaseSavedCopy copy) async {
    final session = widget.session;
    final owner = _captureSavedBillOwner();
    final scope = _scope;
    final ledger = session.workspaceSupplierLedger(copy.supplier.id);
    if (_busy || !owner() || scope == null ||
        !(session.workspaceOriginalSupplierOpeningConfigured
          ? session.workspaceSupplierOpeningAccountLoaded : session.workspaceInvoiceHistoryLoaded) || ledger == null) { return; }
    final invoiceTotal = WorkspacePurchaseEntryDraft.printedPaise(copy.draft.details['invoiceTotal']);
    if (invoiceTotal == null) {
      setState(() => _notice = 'Enter the invoice total as shown on the supplier bill before confirming.');
      return;
    }
    var treatment = _billTreatment(copy, ledger);
    WorkspaceSupplierBillOpeningReview? openingReview;
    if (treatment == null && (ledger.openingRecord == null ||
        ledger.openingRecord!.bills.any((link) => link.draftId == copy.draft.id) ||
        copy.draft.invoiceIssuedDay == null)) {
      return;
    }
    final bookRevision = session.workspacePurchaseEntryRevision;
    if (bookRevision == null) return;
    FocusScope.of(context).unfocus();
    setState(() => _busy = true);
    if (treatment == null) {
      final opening = ledger.openingRecord!;
      treatment = await showDialog<WorkspaceOpeningBillInclusion>(context: context,
        builder: (context) => AlertDialog(scrollable: true, title: const Text('Was this bill included?'),
          content: Text('${copy.supplier.name}\n'
            'Starting balance: ${_purchaseAmount(opening.amountMinor!)} '
            '${opening.supplierCredit ? 'advance / credit with supplier' : 'owed to supplier'}\n'
            'Dated ${_registerDate(DateTime.parse(opening.asOfDate))}\n'
            'Invoice total: ${_purchaseAmount(invoiceTotal)}\n'
            'Choose only after checking the whole supplier invoice. If unsure or partly included, cancel and check with the supplier.'),
          actions: [
            TextButton(onPressed: () => Navigator.pop(context), child: const Text('Cancel')),
            TextButton(onPressed: () => Navigator.pop(context, WorkspaceOpeningBillInclusion.included),
              child: const Text('Whole bill already included')),
            TextButton(onPressed: () => Navigator.pop(context, WorkspaceOpeningBillInclusion.excluded),
              child: const Text('Not included — add bill amount')),
          ]));
      if (!mounted || !owner()) return;
      if (treatment == null) { setState(() => _busy = false); return; }
      openingReview = WorkspaceSupplierBillOpeningReview(openingId: opening.id,
        openingRevision: opening.revision, treatment: treatment);
    }
    final confirmed = await showDialog<bool>(context: context, builder: (context) => AlertDialog(scrollable: true,
      title: const Text('Confirm supplier bill?'),
      content: Text(treatment == WorkspaceOpeningBillInclusion.included
        ? 'Invoice total ${_purchaseAmount(invoiceTotal)} is already included in the confirmed starting balance. No amount is added again. Included does not mean paid. Stock and payments stay unchanged.'
        : WorkspacePurchaseEntryDraft.printedPaise(copy.draft.details['invoiceTotal']) == 0
          ? 'This zero-total bill will be recorded without adding an amount owed. Stock and payments stay unchanged.'
          : 'Invoice total ${_purchaseAmount(invoiceTotal)} will be added to the supplier account. No payment is recorded; any supplier advance is retained. Stock stays unchanged.'),
      actions: [TextButton(onPressed: () => Navigator.pop(context, false), child: const Text('Cancel')),
        TextButton(key: const Key('work-purchase-bill-confirm-accept'),
          onPressed: () => Navigator.pop(context, true), child: const Text('Confirm bill'))]));
    if (!mounted || !owner()) return;
    setState(() => _busy = false);
    if (confirmed != true) return;
    if (session.workspacePurchaseEntryRevision != bookRevision ||
        session.workspaceSupplierLedger(copy.supplier.id)?.revision != ledger.revision) {
      setState(() => _notice = 'Saved records changed. Reopen this bill before confirming.');
      return;
    }
    setState(() { _busy = true; _notice = null; });
    final saved = await session.confirmWorkspacePurchaseBill(copy, scope: scope,
      expectedPurchaseRevision: bookRevision, expectedLedgerRevision: ledger.revision,
      openingTreatment: treatment, openingReview: openingReview, confirmedAt: DateTime.now(), ownerCurrent: owner);
    if (!mounted || !owner()) return;
    setState(() { _busy = false;
      _notice = saved ? 'Posted to supplier ledger. Confirming the bill does not change Stock or record a payment.'
        : session.workspaceSupplierError ?? 'Confirmation status needs recovery. Retry the supplier account before confirming again.'; });
  }
  Widget _goodsRow(int index) {
    final line = _goods[index];
    final linkedProduct = widget.session.workspaceCatalogueItems.where((p) => p.id == line.productId).firstOrNull;
    final query = line.stockSearch.text.toLowerCase().trim();
    final matches = widget.session.workspaceCatalogueItems.where((p) =>
      '${p.title} ${p.sku} ${p.barcode}'.toLowerCase().contains(query)).take(5);
    final sameDescription = linkedProduct != null &&
      linkedProduct.title.trim() == line.name.text.trim() && linkedProduct.pack.trim() == line.pack.text.trim();
    final itemTaxFields = [_field('Taxable value ₹', line.extra['taxableValue']!, 'work-purchase-taxableValue-$index',
        keyboard: const TextInputType.numberWithOptions(decimal: true)),
      _field('Tax amount ₹', line.extra['taxAmount']!, 'work-purchase-taxAmount-$index',
        keyboard: const TextInputType.numberWithOptions(decimal: true))];
    final extraItemFields = <Widget>[];
    for (final e in const {'barcode':'Item code / barcode', 'unitCode':'Unit code on invoice',
        'freeQuantity':'Free qty', 'batch':'Batch No.', 'expiry':'Expiry date', 'mrp':'MRP ₹',
        'sellingPrice':'Selling price ₹', 'discount':'Item discount ₹', 'gstRate':'GST %', 'cess':'Cess ₹'}.entries) {
      final input = _field(e.value, line.extra[e.key]!, 'work-purchase-${e.key}-$index', limit: 200,
        hint: e.key == 'expiry' ? 'DD/MM/YYYY' : null,
        keyboard: const ['barcode','batch','expiry','unitCode'].contains(e.key) ? null :
          const TextInputType.numberWithOptions(decimal: true));
      final goodsOnly = const ['barcode', 'unitCode', 'freeQuantity', 'batch', 'expiry', 'mrp', 'sellingPrice'].contains(e.key);
      if ((!_itemTaxKeys.contains(e.key) || _showGstFields) &&
          (!goodsOnly || !_servicesOnly || _showAllDocumentFields || line.extra[e.key]!.text.isNotEmpty)) {
        extraItemFields.add(input);
      }
    }
    return Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
      Row(children: [Padding(padding: const EdgeInsets.only(right: 8),
        child: Text('${index + 1}', semanticsLabel: 'Item ${index + 1}',
          style: const TextStyle(fontSize: 12, color: _paperMuted))),
        Expanded(child: _field('Item name on invoice', line.name, 'work-purchase-item-$index',
        lookup: true, hint: 'Enter item name as on bill')),
        if (_goods.length > 1) Tooltip(message: 'Remove item ${index + 1}', child: TextButton(
          key: Key('work-purchase-remove-item-$index'), onPressed: () => _removeInvoiceRow(index),
          child: const Text('Remove')))]),
      if (line.productId.isNotEmpty) Row(children: [Expanded(child: Text(linkedProduct == null
        ? 'Linked Stock product unavailable. Match this item again.'
        : sameDescription ? 'Linked to Stock' : 'Stock: ${linkedProduct.title} · ${linkedProduct.pack}',
        key: Key('work-purchase-stock-link-$index'),
        style: const TextStyle(fontSize: 11, color: _paperMuted))),
        TextButton(key: Key('work-purchase-change-stock-$index'),
          onPressed: () => setState(() => line.productId = ''), child: const Text('Change product'))]),
      if (!_servicesOnly && line.name.text.trim().isNotEmpty && line.productId.isEmpty)
        Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [Row(children: [
          const Expanded(child: Text('Choose a saved product below, or Add product if it is new.',
            key: Key('work-purchase-unmatched-item'),
            style: TextStyle(fontSize: 11, color: MoolColors.ink))),
          TextButton(key: Key('work-purchase-add-product-$index'),
            style: TextButton.styleFrom(minimumSize: const Size(48, 48),
              textStyle: const TextStyle(fontSize: 12, fontWeight: FontWeight.w700)),
            onPressed: () => _addGoodsProduct(line), child: const Text('Add product')),
        ]), _field('Find saved product', line.stockSearch, 'work-purchase-stock-search-$index',
          focus: line.focus, lookup: true, hint: 'Name, SKU or barcode')]),
      if (!_servicesOnly && line.focus.hasFocus && line.productId.isEmpty && query.isNotEmpty)
        for (final p in matches) TextButton(onPressed: () {
          setState(() => line.productId = p.id);
          line.focus.unfocus();
        }, style: TextButton.styleFrom(alignment: Alignment.centerLeft),
          child: Text('${p.title} · ${p.pack}', style: const TextStyle(fontSize: 12, color: MoolColors.navy))),
      LayoutBuilder(builder: (context, constraints) {
        final scaled = MediaQuery.textScalerOf(context).scale(1).clamp(1.0, 2.0);
        final quantityWidth = (76 * scaled).clamp(0, constraints.maxWidth).toDouble();
        final priceWidth = (96 * scaled).clamp(0, constraints.maxWidth).toDouble();
        final packWidth = constraints.maxWidth < quantityWidth + priceWidth + 100
          ? constraints.maxWidth : constraints.maxWidth - quantityWidth - priceWidth - 24;
        final packInput = _field('Unit on invoice', line.pack, 'work-purchase-pack-$index');
        final quantityInput = _field('Billed qty', line.quantity, 'work-purchase-quantity-$index',
          limit: 12, keyboard: const TextInputType.numberWithOptions(decimal: true));
        return Wrap(spacing: 12, runSpacing: 4, children: [
        if (!_servicesOnly || _showAllDocumentFields || line.pack.text.isNotEmpty)
          SizedBox(width: packWidth, child: packInput),
        if (!_servicesOnly || _showAllDocumentFields || line.quantity.text.isNotEmpty)
          SizedBox(width: quantityWidth, child: quantityInput),
        SizedBox(width: priceWidth, child: _field('Rate / unit ₹', line.cost, 'work-purchase-cost-$index',
          limit: 12, keyboard: const TextInputType.numberWithOptions(decimal: true))),
      ]); }),
      _compactFields([_field('HSN / SAC', line.extra['hsn']!, 'work-purchase-hsn-$index'),
        _field('Item amount ₹', line.extra['lineTotal']!, 'work-purchase-lineTotal-$index',
          keyboard: const TextInputType.numberWithOptions(decimal: true)),
        if (_showGstFields) ...itemTaxFields]),
      _section('Item details', 'work-purchase-item-details-$index', [
        _field('Invoice line no.', line.extra['printedSerial']!, 'work-purchase-printedSerial-$index'),
        _field('Model / specifications', line.extra['specifications']!,
          'work-purchase-specifications-$index', limit: 1000, multiline: true),
        const Text('HSN / SAC is the tax classification. Supplier item codes and barcodes are recorded separately. Copy only details shown on the invoice.',
          style: TextStyle(fontSize: 11, color: MoolColors.ink)),
        _compactFields(extraItemFields),
        _documentField(_showGstFields, _section('Item GST breakup', 'work-purchase-gst-split-$index', [
          const Text('Copy each tax rate and amount shown. Leave components not shown blank.',
            style: TextStyle(fontSize: 11, color: MoolColors.muted)),
          _compactFields([for (final e in const {'cgstRate':'CGST %', 'cgst':'CGST ₹',
            'sgstRate':'SGST %', 'sgst':'SGST ₹', 'utgstRate':'UTGST %', 'utgst':'UTGST ₹',
            'igstRate':'IGST %', 'igst':'IGST ₹', 'cessRate':'Cess %'}.entries)
            _field(e.value, line.extra[e.key]!, 'work-purchase-${e.key}-$index', limit: 200,
              keyboard: const TextInputType.numberWithOptions(decimal: true))]),
        ])), _extraFields('items', itemIndex: index)]),
      const SizedBox(height: 6),
      const Divider(height: 1, thickness: .7, color: _paperRule),
    ]);
  }
}

class _StoreSupplierOpeningSurface extends StatefulWidget {
  const _StoreSupplierOpeningSurface({
    super.key,
    required this.session,
    required this.onBack,
    this.initialSupplierId, this.initialData, this.initialActionId, this.ownerCurrent, this.sourceCurrent, this.readOnlyOpen = false,
  });
  final bool readOnlyOpen;
  final WorkSession session;
  final VoidCallback onBack;
  final String? initialSupplierId, initialActionId;
  final StoreSupplierOpeningInitialData? initialData;
  final bool Function()? ownerCurrent, sourceCurrent;
  @override
  State<_StoreSupplierOpeningSurface> createState() =>
      _StoreSupplierOpeningState();
}

class _StoreSupplierOpeningState extends State<_StoreSupplierOpeningSurface> {
  WorkspaceLedgerIntent? get _pendingConfirmation {
    final pending = session.workspaceOriginalLedgerPending;
    return pending?.operation == 'confirmStoreSupplierOpening' ? pending : null;
  }
  bool get _pendingSave => session.workspacePendingOpeningInput != null || _pendingConfirmation != null;
  bool get _confirmationConfigured => session.workspaceSupplierOpeningConfirmationAvailable || session.workspaceOriginalSupplierOpeningConfigured;
  bool get _confirmationAvailable => session.workspaceSupplierOpeningConfirmationAvailable || session.workspaceOriginalSupplierOpeningConfirmationAvailable;
  bool get _accountLoading => session.workspaceOriginalSupplierOpeningConfigured && session.workspaceOriginalLedgerBusy;
  final _date = TextEditingController(),
      _amount = TextEditingController(),
      _note = TextEditingController();
  final _relations = <String, WorkspaceOpeningBillInclusion>{};
  (String, String, bool)? _scope;
  String? _supplierId, _basisId, _error;
  int? _revision;
  int _selectionEpoch = 0;
  bool _known = false,
      _credit = false,
      _editing = true,
      _busy = false,
      _leaving = false;
  String _baseline = '';
  bool _assistantCommitted = false;
  bool get _assistantSourceCurrent => _assistantCommitted || widget.sourceCurrent?.call() != false;
  bool _postingRecovered = false;
  WorkspaceSupplierOpeningRecord? _viewed, _attempt;
  WorkSession get session => widget.session;
  bool get _current =>
      _scope != null && _scope == session.workspaceSupplierScope && widget.ownerCurrent?.call() != false;
  String get _input => jsonEncode([
    _supplierId,
    _date.text,
    _amount.text,
    _note.text,
    _known,
    _credit,
    _relations.map((k, v) => MapEntry(k, v.name)),
  ]);
  bool get _dirty => _editing && !_pendingSave && _input != _baseline;
  @override
  void initState() {
    super.initState();
    (_openSupplierOpeningForms[session] ??= <Object>{}).add(this);
    _scope = session.workspaceSupplierScope;
    _revision = session.workspacePurchaseEntryRevision;
    _baseline = _input;
    final supplier = widget.initialSupplierId;
    if (supplier != null && session.workspaceSuppliers.any((p) => p.id == supplier)) _show(supplier);
    final initial = widget.initialData;
    if (initial != null) {
      if (!_current || !_assistantSourceCurrent || supplier == null ||
          !initial.matches(session, widget.initialActionId ?? '', supplier)) {
        _error = 'Suggestion was not applied. Saved opening records are kept.';
      } else {
        _editing = true;
        _date.text = initial.asOfDate;
        _amount.text = initial.amount;
        _note.text = initial.sourceNote;
        _known = initial.amountKnown;
        _credit = initial.supplierCredit;
        _relations.addAll(initial.relations);
      }
    }
    final pending = session.workspacePendingOpeningInput;
    if (pending != null) _restoreOpening(pending);
    if (_pendingConfirmation case final original?) _restoreConfirmation(original);
    if (_confirmationConfigured && pending == null) {
      unawaited(_recoverPosting(readOnlyOpen: widget.readOnlyOpen));
    }
  }

  void _restoreOpening(WorkspaceSupplierOpeningSaveIntent original) {
    final record = original.opening;
    _supplierId = record.supplierId; _basisId = record.basisId; _revision = original.expectedRevision;
    _attempt = record; _viewed = null; _editing = true;
    _date.text = record.asOfDate; _amount.text = record.amountMinor == null ? '' : (record.amountMinor! / 100).toStringAsFixed(2);
    _note.text = record.sourceNote; _known = record.amountMinor != null; _credit = record.supplierCredit;
    _relations..clear()..addAll({for (final bill in record.bills) bill.copyId: bill.inclusion});
    _baseline = _input;
    _error = 'Check the saved status before changing these entries.';
  }
  void _restoreConfirmation(WorkspaceLedgerIntent original) {
    final record = WorkspaceSupplierOpeningRecord.fromJson(original.input);
    _show(record.supplierId, version: record);
    _revision = original.data['expectedPurchaseRevision']! as int;
    _error = 'Check the confirmation status before changing this starting balance.';
  }
  Future<void> _recoverConfirmation(WorkspaceLedgerIntent original, {bool explicitRetry = false}) async {
    if (!_current || _busy || session.workspaceOriginalLedgerBusy) return;
    FocusScope.of(context).unfocus(); setState(() {_busy = true; _error = null;});
    final result = await session.checkWorkspaceOriginalLedgerAttempt(original, explicitRetry: explicitRetry);
    if (!mounted) return;
    setState(() {
      _busy = false;
      if (!_current) return;
      _postingRecovered = session.workspaceSupplierOpeningAccountLoaded;
      if (result?.attempt?['status'] == 'saved') {
        _assistantCommitted = true;
        final record = WorkspaceSupplierOpeningRecord.fromJson(original.input);
        _show(record.supplierId, version: record);
      }
      _error = session.workspaceOriginalLedgerError ??
        (result?.attempt == null ? 'Confirmation status is not known yet. Keep this attempt and check again.' : null);
    });
  }
  Future<void> _recoverOpening({bool explicitRetry = false}) async {
    if (_pendingConfirmation case final pending?) {
      await _recoverConfirmation(pending, explicitRetry: explicitRetry); return;
    }
    final original = session.workspacePendingOpeningInput;
    if (original == null || !_current || _busy || session.workspaceSupplierSaving) return;
    FocusScope.of(context).unfocus(); setState(() {_busy = true; _error = null;});
    final result = await session.checkWorkspaceOpeningAttempt(original, explicitRetry: explicitRetry);
    if (!mounted) return;
    setState(() {
      _busy = false;
      if (!_current) {_error = 'Return to the Store where you started. The original entries are kept.'; return;}
      if (result == null) {_error = session.workspaceSupplierError ?? 'Saved status is not confirmed yet.'; return;}
      if (result.recorded) {_assistantCommitted = true; _show(original.opening.supplierId);
        if (session.workspaceOriginalSupplierOpeningConfigured) unawaited(_recoverPosting());}
      else {
        _attempt = null; _revision = session.workspacePurchaseEntryRevision;
        _basisId = session.workspaceSupplierOpeningRecord(original.opening.supplierId)?.basisId ?? original.opening.basisId;
        _error = session.workspaceSupplierError ?? 'The opening record was not saved. Review these entries before saving again.';
      }
    });
  }
  Future<void> _recoverPosting({bool readOnlyOpen = false}) async {
    final original = session.workspaceOriginalSupplierOpeningConfigured;
    final bookReady = !original || !session.workspaceSupplierRecoveryRequired || await session.loadWorkspaceSuppliers(retry: true);
    if (!mounted || !_current) return;
    final recovered = bookReady && (original
      ? await session.loadWorkspaceOriginalLedger(retry: true)
      : readOnlyOpen ? session.workspaceInvoiceHistoryLoaded : await session.recoverCustomerLedger());
    if (!mounted || !_current) {
      return;
    }
    setState(() {
      _postingRecovered = recovered;
      if (_pendingConfirmation case final original?) {
        _restoreConfirmation(original); return;
      }
      if (recovered && !_editing) {
        if (original && _supplierId != null) _show(_supplierId!);
        _error = null;
      }
      if (!recovered) {
        _error = session.workspaceSupplierError ?? session.workspaceOriginalLedgerError ?? session.customerLedgerRecoveryError ??
            'Supplier account could not be opened. Saved records are kept; try again.';
      }
    });
  }

  bool get _accountReady => _current && _postingRecovered && (!widget.readOnlyOpen || session.workspaceSupplierOpeningAccountLoaded) &&
      session.workspaceOriginalLedgerPending == null && !session.workspaceSupplierRecoveryRequired;
  bool get _posted {
    final proof = _supplierId == null ? null :
        session.workspaceSupplierLedger(_supplierId!)?.openingRecord;
    return _accountReady && proof != null && _viewed != null &&
        jsonEncode(proof.toJson()) == jsonEncode(_viewed!.toJson());
  }

  Future<void> _confirmOpening() async {
    final record = _viewed;
    if (_busy || _editing || !_accountReady || !_assistantSourceCurrent || record == null || _revision == null ||
        !_confirmationAvailable) {
      return;
    }
    FocusScope.of(context).unfocus();
    setState(() => _busy = true);
    try {
      final confirmed = await showDialog<bool>(context: context,
        builder: (context) => AlertDialog(
          title: const Text('Confirm opening balance?'),
          content: Text('${record.amountMinor == null ? 'Amount not known' : _purchaseAmount(record.amountMinor!)} · '
            '${record.supplierCredit ? 'Advance / credit with supplier' : 'You owe the supplier'}\n'
            'This adds the starting balance to the supplier account. It does not add Stock or record a payment.'),
          actions: [
            TextButton(onPressed: () => Navigator.pop(context, false),
              child: const Text('Cancel')),
            FilledButton(key: const Key('work-opening-confirm-accept'),
              onPressed: () => Navigator.pop(context, true),
              child: const Text('Confirm balance')),
          ],
        ));
      if (confirmed != true || !mounted || !_current || !_assistantSourceCurrent) {
        return;
      }
      final saved = await session.confirmWorkspaceSupplierOpeningRecord(record,
        scope: _scope!, expectedRevision: _revision!, confirmedAt: DateTime.now());
      if (!mounted || !_current) {
        return;
      }
      setState(() {
        _postingRecovered = session.workspaceSupplierOpeningAccountLoaded;
        _error = session.workspaceOriginalLedgerError ?? (saved ? null : session.workspaceSupplierError ??
          'Balance confirmation was not completed. Reopen the saved supplier account before trying again.');
      });
    } finally {
      if (mounted) {
        setState(() => _busy = false);
      }
    }
  }

  @override
  void dispose() {
    _openSupplierOpeningForms[session]?.remove(this);
    _date.dispose();
    _amount.dispose();
    _note.dispose();
    super.dispose();
  }

  Future<bool> confirmLeave() async {
    if (_busy || _leaving || session.workspaceSupplierSaving) return false;
    if (!_dirty) return true;
    _leaving = true;
    FocusScope.of(context).unfocus();
    final discard = await showDialog<bool>(
      context: context,
      builder: (context) => AlertDialog(
        title: const Text('Leave opening dues?'),
        content: const Text(
          'Discard only these unsaved changes? Saved purchases and opening records stay available.',
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(context, false),
            child: const Text('Keep editing'),
          ),
          TextButton(
            onPressed: () => Navigator.pop(context, true),
            child: const Text('Discard changes'),
          ),
        ],
      ),
    );
    _leaving = false;
    return mounted && discard == true;
  }

  Future<void> _pickSupplier() async {
    if (!mounted || !_current || _busy || _leaving || _pendingSave || _accountLoading ||
        session.workspaceSupplierSaving) {
      return;
    }
    final scope = _scope;
    final navigation = session.navigationScopeRevision;
    final epoch = _selectionEpoch;
    final original = _supplierId;
    bool validReturn() => mounted && _current && _scope == scope &&
        session.navigationScopeRevision == navigation &&
        _selectionEpoch == epoch && _supplierId == original;
    FocusScope.of(context).unfocus();
    setState(() => _busy = true);
    String? selected;
    try {
      selected = await _showStoreSupplierSelector(context, session, selectedId: original, ownerCurrent: widget.ownerCurrent);
    } finally {
      if (mounted) setState(() => _busy = false);
    }
    bool readySelection() => validReturn() && !_pendingSave && session.workspaceSuppliersLoaded &&
        !session.workspaceSupplierSaving && !session.workspaceSupplierRecoveryRequired &&
        session.workspaceSuppliers.any((p) => p.id == selected);
    if (selected == null || selected == original || !readySelection()) {
      return;
    }
    if (!await confirmLeave() || !readySelection()) return;
    setState(() {
      _selectionEpoch++;
      _show(selected!);
    });
  }

  List<WorkspacePurchaseSavedCopy> get _bills {
    return session.workspaceLatestPurchaseCopies
        .where((c) => c.supplier.id == _supplierId)
        .toList()
      ..sort((a, b) => b.savedAt.compareTo(a.savedAt));
  }

  void _show(String supplierId, {WorkspaceSupplierOpeningRecord? version}) {
    _supplierId = supplierId;
    _revision = session.workspacePurchaseEntryRevision;
    _viewed = version ?? session.workspaceSupplierOpeningRecord(supplierId);
    _basisId = _viewed?.basisId ?? session.newWorkspaceSupplierOpeningId();
    _date.text = _viewed?.asOfDate ?? '';
    _amount.text = _viewed?.amountMinor == null
        ? ''
        : (_viewed!.amountMinor! / 100).toStringAsFixed(2);
    _note.text = _viewed?.sourceNote ?? '';
    _known = _viewed?.amountMinor != null;
    _credit = _viewed?.supplierCredit ?? false;
    _relations.clear();
    _editing = _viewed == null;
    _attempt = null;
    _error = null;
    _baseline = _input;
  }

  void _changed({bool clearBills = true}) {
    if (_pendingSave) return;
    setState(() {
      if (clearBills) _relations.clear();
      _attempt = null;
      _error = null;
    });
  }

  Future<void> _save() async {
    if (_pendingSave) {await _recoverOpening(); return;}
    if (_busy || _accountLoading || !_editing || !_current || !_assistantSourceCurrent || _supplierId == null) return;
    final amount = _known
        ? WorkspacePurchaseEntryDraft.printedPaise(_amount.text)
        : null;
    if (_known && (amount == null || amount < 0)) {
      setState(
        () => _error =
            'Enter the confirmed amount in rupees, or choose Amount not known.',
      );
      return;
    }
    final scope = _scope!;
    _attempt ??= WorkspaceSupplierOpeningRecord(
      id: '$_basisId-r${(_revision ?? 0) + 1}',
      basisId: _basisId!,
      account: scope.$1,
      store: scope.$2,
      qa: scope.$3,
      supplierId: _supplierId!,
      revision: (_revision ?? 0) + 1,
      asOfDate: _date.text.trim(),
      savedAt: DateTime.now(),
      amountMinor: amount,
      supplierCredit: _credit,
      sourceNote: _note.text.trim(),
      bills: [
        for (final b in _bills)
          WorkspaceOpeningBillLink(
            copyId: b.id,
            copyRevision: b.revision,
            draftId: b.draft.id,
            inclusion:
                _relations[b.id] ?? WorkspaceOpeningBillInclusion.unknown,
          ),
      ],
    );
    if (!_attempt!.valid) {
      setState(
        () => _error =
            'Choose the supplier, enter a valid date (YYYY-MM-DD) and explain where this starting amount comes from.',
      );
      return;
    }
    FocusScope.of(context).unfocus();
    setState(() {
      _busy = true;
      _error = null;
    });
    if (session.workspaceSupplierRecoveryError != null) {
      await session.loadWorkspaceSuppliers(retry: true);
    }
    // Recheck the captured owner after native recovery and before the original Save.
    if (!mounted || !_current || !_assistantSourceCurrent) {
      if (mounted) setState(() { _busy = false; _error = 'Return to the Store where you started. Your entries are kept.'; });
      return;
    }
    final saved = await session.saveWorkspaceSupplierOpeningRecord(
      _attempt!,
      scope: scope,
      expectedRevision: _revision,
    );
    if (!mounted) return;
    setState(() {
      _busy = false;
      if (saved && _current) {
        _assistantCommitted = true;
        _show(_supplierId!);
        if (session.workspaceOriginalSupplierOpeningConfigured) unawaited(_recoverPosting());
      } else {
        _error =
            session.workspaceSupplierError ??
            'Return to the Store where you started. Your entries are kept.';
      }
    });
  }

  Widget _field(
    String label,
    TextEditingController controller,
    String key, {
    bool money = false,
    int lines = 1,
  }) => TextField(
    key: Key(key),
    controller: controller,
    readOnly: !_editing || _busy || _accountLoading || !_current || _pendingSave,
    maxLines: lines,
    maxLength: lines > 1 ? 4000 : 40,
    keyboardType: money
        ? const TextInputType.numberWithOptions(decimal: true)
        : TextInputType.text,
    style: const TextStyle(fontSize: 13, color: MoolColors.ink),
    onChanged: (_) => _changed(),
    decoration: InputDecoration(
      labelText: label,
      hintText: money ? 'Enter opening amount' : null,
      floatingLabelBehavior: money ? FloatingLabelBehavior.always : null,
      filled: false,
      counterText: '',
      border: money ? null : InputBorder.none,
      enabledBorder: money ? null : InputBorder.none,
      focusedBorder: money ? null : InputBorder.none,
      labelStyle: const TextStyle(fontSize: 12, color: MoolColors.ink),
    ),
  );
  @override
  Widget build(BuildContext context) {
    if (!_current) {
      return ListView(
        padding: const EdgeInsets.all(12),
        children: [
          const Text(
            'Return to the Store where you started. Unsaved opening entries are kept.',
          ),
          TextButton(
            onPressed: _busy
                ? null
                : () async {
                    if (await confirmLeave() && mounted) widget.onBack();
                  },
            child: const Text('Close'),
          ),
        ],
      );
    }
    final usable =
        _current &&
        !_busy && !_accountLoading &&
        session.workspaceSuppliersLoaded &&
        !session.workspaceSupplierSaving && !_pendingSave;
    final history = session.workspaceSupplierOpeningRecords
        .where((r) => r.supplierId == _supplierId)
        .toList();
    return ListView(
      key: const Key('work-opening-dues-form'),
      primary: false,
      keyboardDismissBehavior: ScrollViewKeyboardDismissBehavior.onDrag,
      padding: EdgeInsets.fromLTRB(
        12,
        0,
        12,
        20 + MediaQuery.viewInsetsOf(context).bottom,
      ),
      children: [
        Wrap(
          spacing: 8,
          crossAxisAlignment: WrapCrossAlignment.center,
          children: [
            const Text(
              'Opening dues record',
              style: TextStyle(
                fontSize: 16,
                fontWeight: FontWeight.w700,
                color: MoolColors.navy,
              ),
            ),
            Text(
              !_accountReady
                ? 'Supplier account status unavailable'
                : _posted ? 'Confirmed in supplier account' : 'Not posted',
              key: const Key('work-opening-posting-status'),
              style: const TextStyle(
                fontSize: 12,
                fontWeight: FontWeight.w600,
                color: MoolColors.ink,
              ),
            ),
            TextButton(
              key: const Key('work-opening-close'),
              onPressed: _busy
                  ? null
                  : () async {
                      if (await confirmLeave() && mounted) widget.onBack();
                    },
              child: const Text('Close'),
            ),
          ],
        ),
        Text(
          _posted ? 'The starting balance is kept. Record subsequent goods and payments separately.' :
          'Save the starting amount, check supporting bills, then confirm the balance in the supplier account. Saving alone does not change dues, Stock or payments.',
          style: const TextStyle(fontSize: 12, color: MoolColors.ink),
        ),
        if (_supplierId != null && session.workspaceOriginalLedgerPending?.operation == 'recordStoreSupplierMoney' &&
            session.workspaceOriginalLedgerPending?.targetId == _supplierId)
          TextButton.icon(key: const Key('work-opening-pending-money'),
            onPressed: _busy || !_current ? null : () async {
              final original = session.workspaceOriginalLedgerPending;
              if (original?.operation != 'recordStoreSupplierMoney' || original?.targetId != _supplierId) return;
              final entry = original!.input;
              if (entry is! Map) return;
              await _showSupplierMoneyEntry(context, session, _StoreSupplierMoneyTarget(supplierId: _supplierId!,
                advance: entry['kind'] == 'advance'), ownerCurrent: widget.ownerCurrent);
              if (mounted && _current) await _recoverPosting();
            }, icon: const Icon(Icons.history, size: 18), label: const Text('Check supplier payment')),
        if (_posted && _supplierId != null && session.workspaceSupplierMoneyInputAvailable) ...[
          Wrap(spacing: 8, children: [
            TextButton.icon(key: const Key('work-opening-record-payment'),
              onPressed: _busy || !_current
                ? null : () async {
                  await _showSupplierMoneyEntry(context, session, _StoreSupplierMoneyTarget(supplierId: _supplierId!), ownerCurrent: widget.ownerCurrent);
                  if (mounted && _current) await _recoverPosting();
                }, icon: const Icon(Icons.payments_outlined, size: 18),
                label: const Text('Record account payment')),
            TextButton.icon(key: const Key('work-opening-record-advance'),
              onPressed: _busy || !_current ? null : () async {
                await _showSupplierMoneyEntry(context, session, _StoreSupplierMoneyTarget(supplierId: _supplierId!, advance: true), ownerCurrent: widget.ownerCurrent);
                if (mounted && _current) await _recoverPosting();
              }, icon: const Icon(Icons.account_balance_wallet_outlined, size: 18), label: const Text('Record advance paid')),
          ]),
        ],
        if (_posted && _supplierId != null)
          _StoreSupplierLedgerSummary(session: session, ledger: session.workspaceSupplierLedger(_supplierId!), ownerCurrent: widget.ownerCurrent),
        if ((_posted || session.workspaceOriginalSupplierRefundConfigured) && _supplierId != null &&
            session.workspaceSupplierOpeningRecord(_supplierId!) != null)
          Align(alignment: Alignment.centerLeft, child: TextButton.icon(
            key: const Key('work-opening-record-refund'), onPressed: _busy || !_current ? null : () async {
              await _chooseSupplierRefund(context, session, _supplierId!, ownerCurrent: widget.ownerCurrent);
              if (mounted && _current) await _recoverPosting();
            }, icon: const Icon(Icons.call_received_outlined, size: 18),
            label: Text(_posted ? 'Refund received / saved requests' : 'Check saved supplier refund'))),
        if (!_current)
          const Text(
            'Return to the Store where you started. Unsaved entries are kept.',
          ),
        if (session.workspaceSuppliersLoaded && session.workspaceSuppliers.isEmpty)
          const Padding(
            padding: EdgeInsets.symmetric(vertical: 8),
            child: Text(
              'No suppliers yet. Choose Supplier, then Add supplier.',
            ),
          ),
        const SizedBox(height: 16),
        InkWell(
          key: const Key('work-opening-supplier-picker'),
          onTap: _current && !_busy && !_accountLoading && !_pendingSave && !session.workspaceSupplierSaving ? _pickSupplier : null,
          child: InputDecorator(
            key: ValueKey(('work-opening-supplier', _supplierId, _selectionEpoch)),
            decoration: InputDecoration(labelText: 'Supplier', filled: false,
              enabled: _current && !_busy && !_accountLoading && !_pendingSave && !session.workspaceSupplierSaving,
              suffixIcon: const Icon(Icons.search)),
            isEmpty: _supplierId == null,
            child: Text(session.workspaceSuppliers
                .where((p) => p.id == _supplierId).map((p) => p.name).firstOrNull ?? '',
              overflow: TextOverflow.ellipsis),
          ),
        ),
        if (_supplierId != null) ...[
          if (history.isNotEmpty) const SizedBox(height: 16),
          if (history.isNotEmpty)
            DropdownButtonFormField<int>(
              key: ValueKey(('opening-version', _viewed?.id, _selectionEpoch)),
              initialValue: _viewed?.revision,
              isExpanded: true,
              isDense: false,
              itemHeight: null,
              decoration: const InputDecoration(
                labelText: 'Saved version',
                filled: false,
              ),
              items: [
                for (final r in history)
                  DropdownMenuItem(
                    value: r.revision,
                    child: Text(
                      '${r.asOfDate} · ${r.amountMinor == null ? 'Amount unknown' : _purchaseAmount(r.amountMinor!)} · v${r.revision}',
                      style: const TextStyle(fontSize: 13),
                      softWrap: true,
                    ),
                  ),
              ],
              onChanged: !usable
                  ? null
                  : (rev) async {
                      final change = await confirmLeave();
                      if (!mounted) return;
                      setState(() {
                        _selectionEpoch++;
                        if (change && rev != null) {
                          _show(_supplierId!, version: history.firstWhere((r) => r.revision == rev));
                        }
                      });
                    },
            ),
          _field('As on date (YYYY-MM-DD)', _date, 'work-opening-date'),
          DropdownButtonFormField<bool>(
            key: ValueKey(('opening-known', _known, _viewed?.id)),
            initialValue: _known,
            isExpanded: true,
            decoration: const InputDecoration(
              labelText: 'Starting amount',
              filled: false,
            ),
            items: const [
              DropdownMenuItem(value: false, child: Text('Amount not known')),
              DropdownMenuItem(value: true, child: Text('Amount confirmed')),
            ],
            onChanged: !usable || !_editing
                ? null
                : (v) {
                    if (v != null) {
                      _known = v;
                      _changed();
                    }
                  },
          ),
          if (_known) ...[
            Padding(
              padding: const EdgeInsets.symmetric(vertical: 16),
              child: _field('Amount ₹', _amount, 'work-opening-amount', money: true),
            ),
            DropdownButtonFormField<bool>(
              key: ValueKey(('opening-credit', _credit, _viewed?.id)),
              initialValue: _credit,
              isExpanded: true,
              decoration: const InputDecoration(
                labelText: 'Who owes this amount?',
                filled: false,
              ),
              items: const [
                DropdownMenuItem(
                  value: false,
                  child: Text('You owe the supplier'),
                ),
                DropdownMenuItem(
                  value: true,
                  child: Text('Supplier owes you / credit available'),
                ),
              ],
              onChanged: !usable || !_editing
                  ? null
                  : (v) {
                      if (v != null) {
                        _credit = v;
                        _changed();
                      }
                    },
            ),
          ],
          _field(
            'Where is this amount from? / Notes',
            _note,
            'work-opening-note',
            lines: 2,
          ),
          const Text(
            'Supporting bills',
            style: TextStyle(
              fontSize: 13,
              fontWeight: FontWeight.w700,
              color: MoolColors.navy,
            ),
          ),
          if (_editing) ...[
            const Text(
              'Check each bill. Included means already counted in this starting amount; bill totals are not added again.',
              style: TextStyle(fontSize: 12, color: MoolColors.ink),
            ),
            if (_bills.isEmpty)
              const Text(
                'No saved purchase copies for this supplier. The starting record can be saved without a bill.',
              ),
            for (final b in _bills)
              Padding(
                padding: const EdgeInsets.only(top: 16, bottom: 8),
                child: DropdownButtonFormField<WorkspaceOpeningBillInclusion>(
                key: ValueKey((
                  'opening-bill',
                  b.id,
                  _basisId,
                  _editing,
                  _relations[b.id],
                )),
                initialValue:
                    _relations[b.id] ?? WorkspaceOpeningBillInclusion.unknown,
                isExpanded: true,
                isDense: false,
                itemHeight: null,
                style: const TextStyle(fontSize: 13, color: MoolColors.ink),
                decoration: InputDecoration(
                  labelText:
                      '${b.draft.invoiceReference} · ${b.draft.invoiceDate} · v${b.revision}',
                  filled: false,
                ),
                items: const [
                  DropdownMenuItem(
                    value: WorkspaceOpeningBillInclusion.unknown,
                    child: Text('Inclusion not confirmed'),
                  ),
                  DropdownMenuItem(
                    value: WorkspaceOpeningBillInclusion.included,
                    child: Text('Already included'),
                  ),
                  DropdownMenuItem(
                    value: WorkspaceOpeningBillInclusion.excluded,
                    child: Text('Not included'),
                  ),
                ],
                onChanged: !usable
                    ? null
                    : (v) {
                        if (v != null) {
                          _relations[b.id] = v;
                          _changed(clearBills: false);
                        }
                      },
                ),
              ),
          ] else ...[
            if (_viewed!.bills.isEmpty)
              const Text('No supporting bills recorded.'),
            for (final link in _viewed!.bills)
              Text(
                '${session.workspacePurchaseCopies.firstWhere((c) => c.id == link.copyId).draft.invoiceReference} · v${link.copyRevision} · '
                '${switch (link.inclusion) {
                  WorkspaceOpeningBillInclusion.included => 'Already included',
                  WorkspaceOpeningBillInclusion.excluded => 'Not included',
                  _ => 'Inclusion not confirmed',
                }}',
                style: const TextStyle(fontSize: 12, color: MoolColors.ink),
              ),
          ],
          if (_error != null)
            Padding(
              padding: const EdgeInsets.symmetric(vertical: 8),
              child: Text(
                _error!,
                key: const Key('work-opening-error'),
                style: const TextStyle(fontSize: 12, color: MoolColors.ink),
              ),
            ),
          Wrap(
            spacing: 8,
            children: [
              if (_pendingSave) ...[
                OutlinedButton(key: const Key('work-opening-check-status'),
                  onPressed: _current && !_busy && !session.workspaceSupplierSaving ? () => _recoverOpening() : null,
                  child: const Text('Check saved status')),
                FilledButton(key: const Key('work-opening-retry-original'),
                  onPressed: _current && !_busy && !session.workspaceSupplierSaving ? () => _recoverOpening(explicitRetry: true) : null,
                  child: Text(_pendingConfirmation != null ? 'Retry confirmation' : 'Retry save')),
              ] else if (_editing)
                FilledButton(
                  key: const Key('work-opening-save'),
                  style: FilledButton.styleFrom(
                    minimumSize: const Size(48, 48),
                    backgroundColor: MoolColors.navy,
                    foregroundColor: Colors.white,
                    textStyle: const TextStyle(
                      fontFamily: 'Inter',
                      fontSize: 13,
                    ),
                  ),
                  onPressed: usable ? _save : null,
                  child: Text(
                    _busy
                        ? 'Saving…'
                        : _attempt != null && _error != null
                        ? 'Retry save'
                        : 'Save opening record',
                  ),
                )
              else if (!_posted && _viewed ==
                  session.workspaceSupplierOpeningRecord(_supplierId!))
                TextButton(
                  key: const Key('work-opening-correct'),
                  onPressed: !usable
                      ? null
                      : () => setState(() {
                          _editing = true;
                          _relations.clear();
                          _attempt = null;
                          _baseline = '';
                          _error = null;
                        }),
                  child: const Text('Correct record'),
                ),
              if (_accountReady && !_editing && !_posted && _viewed != null &&
                  _viewed == session.workspaceSupplierOpeningRecord(_supplierId!) &&
                  _confirmationConfigured)
                FilledButton(
                  key: const Key('work-opening-confirm'),
                  onPressed: usable && _confirmationAvailable && _postingRecovered && _known &&
                      _viewed == session.workspaceSupplierOpeningRecord(_supplierId!) &&
                      _viewed!.bills.every((b) => b.inclusion != WorkspaceOpeningBillInclusion.unknown)
                      ? _confirmOpening : null,
                  child: Text(_busy ? 'Confirming…' : 'Confirm opening balance'),
                ),
              if (!_accountReady && _confirmationConfigured)
                TextButton(key: const Key('work-opening-recover'),
                  onPressed: usable ? _recoverPosting : null,
                  child: const Text('Reopen supplier account')),
            ],
          ),
          if (!_editing && !_posted && _viewed != null &&
              _confirmationConfigured &&
              (!_known || _viewed!.bills.any((b) => b.inclusion == WorkspaceOpeningBillInclusion.unknown)))
            const Text('Choose Correct record to check the amount and which bills are included before confirming.',
              style: TextStyle(fontSize: 12, color: MoolColors.ink)),
        ],
      ],
    );
  }
}

@immutable
class StoreReceivingReviewInitial {
  StoreReceivingReviewInitial._(this.actionId,Map<String,Object?> values) : values=Map.unmodifiable(values);
  final String actionId;
  final Map<String,Object?> values;
  static const mappedLineFields={'expected','delivered','damaged','short','batch','manufactured','expiry','mrp'};
  static bool canMapLineField(String field,{required bool arrives,required bool inherited,required bool restockLinked}) =>
    mappedLineFields.contains(field)&&arrives&&(field!='expected'||!inherited&&!restockLinked);
  static const actions={'AI-ACT-238','AI-ACT-239','AI-ACT-240','AI-ACT-243','AI-ACT-244','AI-ACT-245','AI-ACT-246','AI-ACT-247','AI-ACT-248','AI-ACT-249','AI-ACT-250','AI-ACT-251','AI-ACT-401','AI-ACT-402','AI-ACT-403','AI-ACT-404'};
  static const lineFields={'lineId','productId','unit','factor','expected','delivered','damaged','short','batch','manufactured','expiry','mrp'};
  static const fieldsByAction=<String,Set<String>>{
    'AI-ACT-238':{'reference','date','items'}, 'AI-ACT-239':{'items'},
    'AI-ACT-240':{'lineId','productId'}, 'AI-ACT-243':{},'AI-ACT-244':{},
    'AI-ACT-245':{'billLineIndex','receiptId','receiptLineId','quantity','free','accepted','damaged','numerator','denominator'},
    'AI-ACT-246':{'lineId','unit','factor','batch','manufactured','expiry','mrp'},
    'AI-ACT-247':{'reference','reason','returnedOn','items'},
    'AI-ACT-248':{'billLineIndex','deliveryId','receiptLineId','quantity'},
    'AI-ACT-249':{},'AI-ACT-250':{},'AI-ACT-251':{},
    'AI-ACT-401':{'documentType'},'AI-ACT-402':{'heading','value','page'},
    'AI-ACT-403':{'taxRow'},'AI-ACT-404':{'fieldId','heading','value','receiptField','lineId'},
  };
  factory StoreReceivingReviewInitial.fromFields(String action,Map<String,Object?> raw) {
    final allowed=fieldsByAction[action];
    if(allowed==null||!raw.keys.every(allowed.contains)||allowed.isNotEmpty&&raw.isEmpty) throw const FormatException('Use supplied original receiving fields.');
    final result=<String,Object?>{};
    for(final entry in raw.entries) {
      if(entry.key=='items') {
        if(entry.value is! List||(entry.value! as List).isEmpty) throw const FormatException('Supply receiving lines.');
        final rows=<Map<String,String>>[];final ids=<String>{};
        for(final value in entry.value! as List) {
          final keys=action=='AI-ACT-247'?const {'receiptLineId','accepted','damaged'}:lineFields;
          if(value is! Map||value.isEmpty||!value.keys.every(keys.contains)||!value.values.every((v)=>v is String)) throw const FormatException('Use original line references and raw native inputs.');
          final row=Map<String,String>.from(value);
          final id=row[action=='AI-ACT-247'?'receiptLineId':'lineId'];
          if(id!=null&&(id.trim().isEmpty||!ids.add(id))) throw const FormatException('Use distinct original line references.');
          rows.add(Map.unmodifiable(row));
        }
        result[entry.key]=List<Map<String,String>>.unmodifiable(rows);
      } else if(entry.key=='taxRow') {
        final value=entry.value;
        if(value is! Map||value.isEmpty||!value.keys.every(WorkspacePurchaseEntryDraft.printedTaxKeys.contains)||!value.values.every((v)=>v is String)) throw const FormatException('Use the native printed tax-row fields.');
        result[entry.key]=Map<String,String>.unmodifiable(Map<String,String>.from(value));
      } else if(entry.key=='billLineIndex'||entry.key=='page') {
        if(entry.value is! int||(entry.value! as int)<(entry.key=='page'?1:0)) throw const FormatException('Use an original item/page reference.');
        result[entry.key]=entry.value;
      } else {
        if(entry.value is! String) throw const FormatException('Keep native field values as raw text.');
        result[entry.key]=entry.value;
      }
    }
    void need(Set<String> keys) { if(!keys.every((k)=>result.containsKey(k)&&result[k]!=null&&result[k]!='')) throw const FormatException('An exact original target and supplied values are required.'); }
    if(action=='AI-ACT-240') need({'lineId','productId'});
    if(action=='AI-ACT-246') {need({'lineId'});if(result.length==1) throw const FormatException('Supply printed lot/pack fields.');}
    if(action=='AI-ACT-245') need({'billLineIndex','receiptId','receiptLineId'});
    if(action=='AI-ACT-248') need({'billLineIndex','deliveryId','receiptLineId','quantity'});
    if(action=='AI-ACT-401') {need({'documentType'});if(!WorkspacePurchaseInvoiceAttachment.receivingDocumentTypes.contains(result['documentType'])) throw const FormatException('Choose a native receiving document type.');}
    if(action=='AI-ACT-402') need({'heading','value'});
    if(action=='AI-ACT-404') {
      need({'fieldId'});
      if(result.containsKey('receiptField')) {
        if(!const {'reference','date','expected','delivered','damaged','short','batch','manufactured','expiry','mrp'}.contains(result['receiptField']) ||
          result.containsKey('heading')||result.containsKey('value')) throw const FormatException('Choose an existing receipt field and keep the original printed value.');
        if(!const {'reference','date'}.contains(result['receiptField'])) need({'lineId'});
        else if(result.containsKey('lineId')) throw const FormatException('Receipt headings do not have an item reference.');
      } else if(result.containsKey('lineId')) throw const FormatException('Choose the receipt field for this item.');
    }
    return StoreReceivingReviewInitial._(action,result);
  }
  List<Map<String,String>> get items=>values['items'] as List<Map<String,String>>? ?? const [];
  String? text(String key)=>values[key] as String?;
}
class _StoreReceivingNativeAdapter implements MoolAssistantOwnerAwareNativeAdapter, MoolAssistantRouteBoundNativeAdapter {
  _StoreReceivingNativeAdapter({required this.actionId,required this.read,required this.open});
  (Route<void>,NavigatorState)? _assistantOwner;
  bool _invalidAssistantOwner=false;
  @override void bindAssistantRoute(Route<void> route,NavigatorState navigator) {
    if(_assistantOwner case final previous?) {
      if(!identical(previous.$1,route)||!identical(previous.$2,navigator))_invalidAssistantOwner=true;
    } else {_assistantOwner=(route,navigator);}
  }
  @override final String actionId;
  @override Set<String> get allowedFields=>StoreReceivingReviewInitial.fieldsByAction[actionId]??const {};
  @override String? validateFields(Map<String,Object?> fields) {
    try {StoreReceivingReviewInitial.fromFields(actionId,fields);return null;}
    on FormatException catch(error){return error.message.toString();}
  }
  final Future<MoolAssistantNativeSnapshot?> Function(MoolAssistantContext,String?) read;
  final Future<MoolAssistantReviewResult> Function(MoolAssistantProposal,StoreReceivingReviewInitial,bool Function(),Listenable,(Route<void>,NavigatorState)?) open;
  @override Future<MoolAssistantNativeSnapshot?> snapshot(MoolAssistantContext context,String? entityId)=>read(context,entityId);
  @override Future<MoolAssistantReviewResult> openReview(MoolAssistantProposal proposal,bool Function() isCurrent) async=>MoolAssistantReviewResult.unavailable;
  @override Future<MoolAssistantReviewResult> openOwnedReview(MoolAssistantProposal proposal,{required bool Function() isCurrent,required Listenable ownerChanges}) async {
    if(_invalidAssistantOwner)return MoolAssistantReviewResult.stale;
    if(actionId=='AI-ACT-404'&&proposal.fields.containsKey('receiptField')) {
      if(_assistantOwner case final owner?) {
        if(!owner.$1.isCurrent||!identical(owner.$1.navigator,owner.$2))return MoolAssistantReviewResult.stale;
      }
    }
    try {return await open(proposal,StoreReceivingReviewInitial.fromFields(actionId,proposal.fields),isCurrent,ownerChanges,_assistantOwner);}
    on FormatException {return MoolAssistantReviewResult.unavailable;}
  }
}
// Notification is not authority: every callback also rechecks this predicate.
// The latch observes departure synchronously, including change/restore before a frame.
class _ReceivingNativeLease {
  _ReceivingNativeLease(this.owner,this.changes) {changes.addListener(_changed);_changed();}
  final bool Function() owner;
  final Listenable changes;
  bool _retired=false,_disposed=false;
  bool get current {
    if(_disposed||_retired)return false;
    if(!owner())_retired=true;return !_retired;
  }
  void _changed() {if(!owner()) _retired=true;}
  void dispose(){if(_disposed)return;_disposed=true;changes.removeListener(_changed);}
}

class _ReceivingOwnerSurface extends StatelessWidget {
  const _ReceivingOwnerSurface({required this.current,required this.changes,required this.child,this.onClose,
    this.retiredMessage = 'This original receiving source is no longer available. Close this review.'});
  final bool Function() current;final Listenable changes;final Widget child;final VoidCallback? onClose;final String retiredMessage;
  @override Widget build(BuildContext context)=>AnimatedBuilder(animation:changes,builder:(context,_) {
    final active=current();
    if(!active)WidgetsBinding.instance.addPostFrameCallback((_){if(context.mounted&&!current())FocusScope.of(context).unfocus();});
    return Stack(children:[Offstage(offstage:!active,child:ExcludeFocus(excluding:!active,child:child)),
      if(!active)Center(child:SingleChildScrollView(padding:const EdgeInsets.all(16),
        child:DefaultTextStyle(style:Theme.of(context).textTheme.bodyMedium ?? const TextStyle(fontSize:14,color:MoolColors.ink),
          child:Column(mainAxisSize:MainAxisSize.min,children:[
            Text(retiredMessage),
            if(onClose!=null)TextButton(key:const Key('receiving-native-retired-close'),onPressed:onClose,child:const Text('Close'))]))))]);
  });
}
