        child:_StoreBillGoodsMatch(key:key,session:widget.session,copy:widget.copy,onOpenCopy:openCopy,
          ownerCurrent:()=>widget.lease.current,assistantReadOnlyOpen:true,receivingInitial:widget.initial)))));
