      if (source == null || _checkedReceivingRead(source) == null) return false;
      return source.lines.entries.any((entry) => (_serverGroup?.lines.where((line) => line.sourceLineId == entry.key)
        .singleOrNull?.deliveredMilli ?? 0) < entry.value.quantityMilli);
    }
    final group = _ledger?.goodsReceipts.values.where((r) => r.expectedDeliveryId == _groupId).toList() ?? [];
    final expected = <String, int?>{for (final receipt in group) for (final line in receipt.lines) line.sourceLineId: line.expectedMilli,
      if (_restockOriginal case final source?) for (final line in source.lines.entries) line.key: line.value.quantityMilli};
    return expected.isNotEmpty && expected.entries.any((entry) => entry.value == null ||
      group.expand((r) => r.lines).where((line) => line.sourceLineId == entry.key)
        .fold<int>(0, (total, line) => total + line.deliveredMilli) < entry.value!);
  }
  String get _input => jsonEncode([_reference.text, _day.text, for (final line in _lines)
    [line.id, line.productId, line.arrives, line.unit.text, line.factor.text, line.expected.text,
      line.delivered.text, line.damaged.text, line.short.text,
      {for (final e in line.prior.entries) if (e.value.text.isNotEmpty) e.key: e.value.text},
      if (line.lotControllers.any((c) => c.text.isNotEmpty)) [for (final c in line.lotControllers) c.text]]]);
  @override
  void initState() {
    super.initState();_day.addListener(_syncDisplayDay);
    if (_originalAssistantReview) {
      WidgetsBinding.instance.addPostFrameCallback((_) {if (mounted) unawaited(_startOriginalReceivingAssistant());});
    } else if(widget.assistantInitial!=null) {
      WidgetsBinding.instance.addPostFrameCallback((_){if(mounted)unawaited(_startReceivingAssistant());});
    } else {unawaited(_recover());}
  }
  @override
  void dispose() { _receivingLease?.changes.removeListener(_receivingOwnerChanged);_receivingLease?.dispose();_receivingEdits.removeListener(_receivingOwnerChanged);_receivingEdits.dispose(); _receivingEntryScroll.dispose(); _draft?.removeListener(_draftChanged); _draft?.dispose(); _reference.dispose(); _day.removeListener(_syncDisplayDay); _day.dispose(); _displayDay.dispose(); for (final line in _lines) { line.dispose(); } super.dispose(); }
  String? _isoReceivedDate(String value) {
    final text = value.trim();
    final match = RegExp(r'^(\d{2})/(\d{2})/(\d{4})$').firstMatch(text);
    final iso = match == null ? text : '${match[3]}-${match[2]}-${match[1]}';
    final parsed = DateTime.tryParse(iso);
    return RegExp(r'^\d{4}-\d{2}-\d{2}$').hasMatch(iso) && parsed != null &&
      parsed.toIso8601String().substring(0, 10) == iso ? iso : null;
  }
  void _syncDisplayDay() {
    final iso = _isoReceivedDate(_day.text);
    final shown = iso == null ? _day.text : '${iso.substring(8, 10)}/${iso.substring(5, 7)}/${iso.substring(0, 4)}';
    if (_displayDay.text != shown) _displayDay.text = shown;
  }
  Future<void> _openSupportingEntry({required bool openingBalance}) async {
    if (!_current || _busy || _supplierId == null ||
        (_frozen != null && (!openingBalance || !_reviewVerified || _committed))) { return; }
    setState(() => _busy = true);
    if (!await _flushInput()) { if (_current) setState(() => _busy = false); return; }
    if (!mounted || !_current) return;
    FocusScope.of(context).unfocus();
    if (openingBalance) {
      final openingKey = GlobalKey<_StoreSupplierOpeningState>();
      await Navigator.of(context).push<void>(MaterialPageRoute(builder: (routeContext) {
        Future<void> close() async {
          if (await (openingKey.currentState?.confirmLeave() ?? Future.value(false)) && routeContext.mounted) {
            Navigator.pop(routeContext);
          }
        }
        return Scaffold(body: SafeArea(child: _purchaseCapturedOwnerPage(context, routeContext, session, _receivingEffectiveOwner, PopScope(canPop: false,
          onPopInvokedWithResult: (didPop, _) { if (!didPop) unawaited(close()); },
          child: _StoreSupplierOpeningSurface(key: openingKey, session: session,
            initialSupplierId: _supplierId, onBack: () => Navigator.pop(routeContext), ownerCurrent: _receivingEffectiveOwner)),ownerChanges:_receivingEffectiveChanges)));
      }));
    } else {
      await Navigator.of(context).push<bool>(MaterialPageRoute(builder: (catalogueContext) =>
        _purchaseCapturedOwnerPage(context, catalogueContext, session, _receivingEffectiveOwner, _WorkspaceCatalogueSurface(session: session, entryOnly: true, ownerCurrent: _receivingEffectiveOwner),ownerChanges:_receivingEffectiveChanges)));
    }
    if(_current){if(_receivingPreparing)setState((){_busy=false;_bookRevision=session.workspacePurchaseEntryRevision;});else await _recover();}
  }
  void _draftChanged() { if (_current) setState(() {}); }
  Map<String, String> get _draftFields => {'arrivalId': _arrivalId, 'groupId': _groupId, 'input': _input,
    if (_copyType.isNotEmpty) 'copyType': _copyType,
    if (_restockOriginal != null) 'restockOriginal': jsonEncode(_restockOriginal!.toJson()),
    if (_documents.isNotEmpty) 'documents': jsonEncode(_documents.map((a) => a.toJson()).toList())};
  bool get _showingOtherDelivery => widget.initialRestockOriginal != null && _arrivalId.isNotEmpty &&
    jsonEncode(widget.initialRestockOriginal!.toJson()) != jsonEncode(_restockOriginal?.toJson());
  void _saveInput() {
    if(mounted&&_receivingOwned)_receivingEdits.value++;
    if(!_current)return;
    if(_receivingPreparing&&!_receivingExplicitSave){_receivingDirty=true;return;}
    if (!_current || _frozen != null || _arrivalId.isEmpty || _draft?.key == null ||
        _draft?.ready != true) { return; }
    final fields = _draftFields;
    if (mapEquals(_lastQueuedInput, fields) && _draft!.error == null) return;
    if (!WorkspaceLedgerFormDraft(key: _draft!.key!, revision: 1, fields: fields).valid) {
      _draft!.error = 'Delivery input is too long. Shorten the details before saving.';
      _draft!.changed();
      return;
    }
    _lastQueuedInput = Map<String, String>.of(fields);
    _draft!.save(fields);
  }
  Future<bool> _flushInput() async {
    if(_receivingPreparing&&!_receivingExplicitSave)return _current;
    if (_supplierId == null || _frozen != null) return true;
    if (_discarding) {
      if (_current) setState(() => _error = 'Draft discard is not verified. Retry discard before leaving.');
      return false;
    }
    _saveInput();
    final saved = await _draft?.flush() ?? false;
    if (_current && !saved) setState(() { _error = 'Delivery input is not saved yet. Retry saving before leaving or reviewing.'; });
    return saved && _current;
  }
  void _resumeSupplierInput(Map<String, String> fields) {
    _copyType = fields['copyType'] ?? '';
    _documents..clear()..addAll([for (final a in fields.containsKey('documents')
      ? jsonDecode(fields['documents']!) as List : const []) WorkspacePurchaseInvoiceAttachment.fromJson(a)]);
    final reviews = session.workspaceGoodsReceiptDrafts.where((r) => r.supplierId == _supplierId &&
      !session.workspaceGoodsReceiptCancellations.any((c) => c.receiptId == r.receipt.id)).toList();
    final arrival = fields['arrivalId'];
    final reviewed = reviews.where((r) => r.receipt.id == arrival).firstOrNull;
    if (reviewed != null) { _restore(reviewed.receipt); return; }
    if (fields.isNotEmpty && !session.workspaceGoodsReceiptCancellations.any((c) => c.receiptId == arrival)) {
      if (_ledger?.goodsReceipts.containsKey(arrival) == true ||
          reviews.any((r) => !_receiptResolved(r.receipt))) {
        throw StateError('Saved receipt review unavailable');
      }
      final values = jsonDecode(fields['input']!) as List;
      final group = fields['groupId']!;
      final source = fields.containsKey('restockOriginal')
        ? WorkspaceRestockPurchaseOriginal.fromJson(jsonDecode(fields['restockOriginal']!)) : null;
      final originals = <String, WorkspaceSupplierGoodsReceiptLine>{
        for (final receipt in _ledger?.goodsReceipts.values ?? const <WorkspaceSupplierGoodsReceipt>[])
          if (receipt.expectedDeliveryId == group)
            for (final line in receipt.lines) line.sourceLineId: line};
      final restored = <_ReceivingLineInput>[];
      for (final value in values.skip(2).cast<List>()) {
        final original = originals[value[0]];
        if (original != null && (value[1] != original.productId || value[3] != original.purchaseUnit ||
            value[4] != '${original.unitsPerPack}' || value[5] !=
              (original.expectedMilli == null ? '' : _ReceivingLineInput._quantity(original.expectedMilli!)))) {
          throw StateError('Inherited delivery mapping changed');
        }
      }
      for (final value in values.skip(2).cast<List>()) {
        final line = _ReceivingLineInput(value[0] as String, saved: originals[value[0]]);
        line.productId = value[1] as String; line.arrives = value[2] as bool;
        for (final (index, controller) in [line.unit, line.factor, line.expected, line.delivered, line.damaged, line.short].indexed) {
          controller.text = value[index + 3] as String;
        }
        for (final c in line.prior.values) { c.dispose(); }
        line.prior.clear();
        for (final entry in (value[9] as Map).entries) {
          line.prior[entry.key as String] = TextEditingController(text: entry.value as String);
        }
        if (value.length == 11) {
          for (final (index, controller) in line.lotControllers.indexed) {
            controller.text = (value[10] as List)[index] as String;
          }
        }
        restored.add(line);
      }
      for (final line in _lines) { line.dispose(); }
      _lines..clear()..addAll(restored);
      _arrivalId = arrival!; _groupId = group;
      _restockOriginal = source;
      _reference.text = values[0] as String; _day.text = values[1] as String;
      _frozen = null; _reviewVerified = false; _cancelAttempt = null; _postResult = null;
      _notice = 'Unfinished delivery restored · Stock has not changed.';
    } else if (reviews.isNotEmpty) {
      final requested = widget.initialRestockOriginal;
      final matching = requested == null ? null : reviews.where((r) =>
        jsonEncode(r.receipt.restockOriginal?.toJson()) == jsonEncode(requested.toJson())).lastOrNull;
      final unfinished = reviews.where((r) => !_receiptResolved(r.receipt)).lastOrNull;
      if (matching != null) { _restore(matching.receipt); }
      else if (unfinished != null || requested == null) { _restore((unfinished ?? reviews.last).receipt); }
      else { _newArrival(); }
    } else { _newArrival(); }
  }
  Future<void> _retryInput() async {
    if (!_current || _busy || _draft == null) return;
    if (_discarding) { await _discardInput(); return; }
    setState(() { _busy = true; _error = null; });
    if (!_draft!.ready) {
      final fields = await _draft!.load();
      if (!_current) return;
      if (fields != null) {
        try { _resumeSupplierInput(fields); }
        on Object { _draft!.ready = false; _error = 'Saved delivery input needs recovery. Do not re-enter these goods.'; }
      }
    } else { await _flushInput(); }
    if (_current) setState(() => _busy = false);
  }
  Future<void> _discardInput() async {
    final draft = _draft, supplier = _supplierId, arrival = _arrivalId, input = _input;
    if (!_current || _busy || _frozen != null || draft?.ready != true) return;
    if (!_discarding) {
      final discard = await showDialog<bool>(context: context, builder: (context) => AlertDialog(
        title: const Text('Discard delivery draft?'),
        content: const Text('Only this unfinished draft will be removed. Saved goods, Stock and supplier account stay unchanged.'),
        titleTextStyle: const TextStyle(fontSize: 14, fontWeight: FontWeight.w600, color: MoolColors.navy),
        contentTextStyle: const TextStyle(fontSize: 12, color: MoolColors.ink),
        titlePadding: const EdgeInsets.fromLTRB(16, 12, 16, 8), contentPadding: const EdgeInsets.symmetric(horizontal: 16),
        actionsPadding: const EdgeInsets.all(8),
        actions: [TextButton(onPressed: () => Navigator.pop(context, false), child: const Text('Keep draft')),
          TextButton(onPressed: () => Navigator.pop(context, true), child: const Text('Discard draft'))]));
      if (discard != true || !_current || !identical(draft, _draft) || supplier != _supplierId ||
          arrival != _arrivalId || input != _input) {
        return;
      }
    }
    setState(() { _busy = true; _discarding = true; _error = null; });
    draft!.save(const {});
    final saved = await draft.flush();
    if (!_current || !identical(draft, _draft) || supplier != _supplierId) return;
    if (!saved) {
      setState(() { _busy = false; _error = 'Draft discard is not verified. Retry discard; do not re-enter this delivery.'; });
      return;
    }
    for (final line in _lines) { line.dispose(); } _lines.clear();
    _reference.clear(); _day.clear(); _arrivalId = ''; _groupId = '';
    _discarding = false;
    await _recover();
    if (_current) {
      setState(() => _notice = _loaded
        ? 'Delivery draft discarded. Saved goods history is unchanged.'
        : 'Delivery draft discarded. Recover saved goods status before continuing.');
    }
  }
  Future<void> _recover({WorkspaceSavedInventory? reviewedSavedStock, String? reviewedStockSignature}) async {
    if (mounted) setState(() { _busy = true; _error = null; });
    var ready = await session.loadWorkspaceSuppliers(retry: true);
    if (!_current) return;
    final supplier = _supplierId ?? widget.initialSupplierId;
    final saved = session.workspaceGoodsReceiptDrafts.where((r) => r.supplierId == supplier).lastOrNull?.receipt;
    final source = _frozen?.restockOriginal ?? _restockOriginal ?? saved?.restockOriginal ?? widget.initialRestockOriginal;
    _stockRecoverySource = source;
    final server = _frozen != null ? session.workspaceGoodsReceiptUsesServer(_frozen!)
      : source != null && !session.workspaceRestockUsesLegacyReceipts(source);
    if (ready && server) {
      ready = await session.recoverWorkspaceRestockReceiving(source!,
        reviewedSavedStock: reviewedSavedStock, reviewedStockSignature: reviewedStockSignature);
      if (_current && ready && _frozen != null && session.workspaceRestockAttempt(_frozen!.id) != null) {
        _postResult = await session.checkWorkspaceRestockGoodsReceipt(_frozen!, supplierId: _supplierId!, scope: _scope!);
      }
    } else if (ready) {
      ready = await session.loadWorkspaceInventory(retry: true) &&
        (source == null && !session.customerCollectionAvailable ||
          supplier == null && session.workspaceGoodsReceiptDrafts.any((r) => session.workspaceGoodsReceiptUsesServer(r.receipt)) ||
          await session.recoverCustomerLedger());
    }
    if (!_current) return;
    _bookRevision = session.workspacePurchaseEntryRevision;
    if (ready && _frozen != null) {
      _reviewVerified = session.workspaceGoodsReceiptDrafts.any((r) => r.supplierId == _supplierId &&
        jsonEncode(r.receipt.toJson()) == jsonEncode(_frozen!.toJson()) &&
        jsonEncode(r.documents.map((a) => a.toJson()).toList()) == jsonEncode(_documents.map((a) => a.toJson()).toList()));
      if (!_reviewVerified) _error = 'Saved receipt or copies differ from this review. Reopen the saved receiving record before recording goods.';
      _postResult = _closed ? WorkspaceGoodsReceiptSaveResult.closed : _committed ? session.workspaceGoodsReceiptRecoveryPending
        ? WorkspaceGoodsReceiptSaveResult.stockRecoveryPending : WorkspaceGoodsReceiptSaveResult.saved
        : session.workspaceRestockAttempt(_frozen!.id) != null ? WorkspaceGoodsReceiptSaveResult.statusUnknown
          : WorkspaceGoodsReceiptSaveResult.notPosted;
    }
    setState(() { _busy = false; _loaded = ready; if (!ready) _error = 'Saved receiving status is unavailable. Retry without clearing Store data.'; });
    if (ready && _supplierId != null && _arrivalId.isEmpty && _draft?.ready == true) _resumeSupplierInput(const {});
    if (ready && _supplierId == null) {
      final linked = widget.initialSupplierId ?? _sourceSupplierId;
      if (linked != null && session.workspaceSuppliers.any((p) => p.id == linked)) await _chooseSupplier(linked);
    }
  }
  Future<void> _reviewStockBaseline() async {
    final source = _stockRecoverySource, signature = session.workspaceRestockStockReviewSignature;
    final saved = session.workspaceRestockStockConflict;
    if (!_current || _busy || source == null || signature == null) return;
    final products = (saved?.products ?? session.workspaceCatalogueItems)
      .where((product) => product.stockMode == WorkspaceStockMode.exactQuantity).toList();
    if (products.isEmpty) {
      setState(() => _error = 'Save the Stock items and their current quantities before receiving this delivery.');
      return;
    }
    final confirmed = await showDialog<bool>(context: context, builder: (context) => AlertDialog(
      title: Text(saved == null ? 'Confirm current Stock' : 'Recover saved Stock'),
      titleTextStyle: const TextStyle(fontSize: 14, fontWeight: FontWeight.w600, color: MoolColors.navy),
      contentTextStyle: const TextStyle(fontSize: 12, color: MoolColors.ink),
      content: SizedBox(width: double.maxFinite, child: SingleChildScrollView(child: Column(
        mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.start, children: [
          Text(saved == null ? 'Check these quantities before adding this delivery. Include goods already received; link their earlier Stock entries when applicable.'
            : 'These saved quantities will replace the Stock view on this device. Check them before continuing.'),
          const SizedBox(height: 8),
          for (final product in products) Padding(padding: const EdgeInsets.symmetric(vertical: 4),
            child: Text('${product.title} · ${product.stock} ${product.pack}')),
        ]))),
      titlePadding: const EdgeInsets.fromLTRB(16, 12, 16, 8), contentPadding: const EdgeInsets.symmetric(horizontal: 16),
      actionsPadding: const EdgeInsets.all(8), actions: [
        TextButton(onPressed: () => Navigator.pop(context, false), child: const Text('Go back')),
        TextButton(key: const Key('work-receive-stock-baseline-confirm'),
          onPressed: () => Navigator.pop(context, true), child: Text(saved == null ? 'Confirm quantities' : 'Use saved Stock')),
      ]));
    if (confirmed != true || !_current || session.workspaceRestockStockReviewSignature != signature ||
        jsonEncode(session.workspaceRestockStockConflict?.toJson()) != jsonEncode(saved?.toJson())) { return; }
    if (saved != null) { await _recover(reviewedSavedStock: saved, reviewedStockSignature: signature); return; }
    setState(() { _busy = true; _error = null; });
    final retained = await session.confirmWorkspaceRestockStockBaseline(source, signature);
    if (!_current) return;
    setState(() { _busy = false; if (!retained) _error = 'Stock confirmation needs recovery. Check saved quantities before trying again.'; });
    if (retained) await _recover();
  }
  void _restore(WorkspaceSupplierGoodsReceipt receipt) {
    _copyType = '';
    _documents..clear()..addAll(session.workspaceGoodsReceiptDrafts.where((r) =>
      r.supplierId == _supplierId && r.receipt.id == receipt.id).singleOrNull?.documents ?? const []);
    for (final line in _lines) { line.dispose(); }
    _lines..clear()..addAll(receipt.lines.map((line) => _ReceivingLineInput(line.sourceLineId, saved: line, restoreLot: true)));
    _arrivalId = receipt.id; _groupId = receipt.expectedDeliveryId;
    _restockOriginal = receipt.restockOriginal;
    _reference.text = receipt.reference; _day.text = receipt.deliveredOn;
    _frozen = receipt; _reviewVerified = true; _cancelAttempt = null; _postResult = null;
  }
  String? get _sourceSupplierId {
    final source = widget.initialRestockOriginal;
    if (source == null) return null;
    return _checkedReceivingRead(source)?.group?.supplierId ??
      session.workspaceSuppliers.where((supplier) =>
        session.workspaceSupplierLedger(supplier.id)?.goodsReceipts.values.any((receipt) =>
          receipt.expectedDeliveryId == source.deliveryGroupId) == true).singleOrNull?.id;
  }
  Future<void> _pickSupplier() async {
    final selected = await _showStoreSupplierSelector(context, session,
      selectedId: _supplierId, lockedSupplierId: _sourceSupplierId, ownerCurrent: _receivingEffectiveOwner,
      useLoadedDirectory: _originalAssistantReview && _receivingPreparing);
    if (!_current) return;
    // A contact-only save advances the book, but never reloads dirty receipt inputs.
    _bookRevision = session.workspacePurchaseEntryRevision;
    if (selected != null) await _chooseSupplier(selected);
    if (_current) setState(() => _supplierPicker.currentState?.didChange(_supplierId));
  }
  Future<void> _chooseSupplier(String id) async {
    if (_supplierId == id) return;
    if (_busy) { _supplierPicker.currentState?.didChange(_supplierId); return; }
    final requested = widget.initialRestockOriginal;
    final serverSupplier = requested == null ? null : _checkedReceivingRead(requested)?.group?.supplierId;
    if (serverSupplier != null && serverSupplier != id) {
      setState(() => _error = 'This purchase is linked to another saved supplier. Keep that supplier for the next arrival.');
      _supplierPicker.currentState?.didChange(_supplierId);
      return;
    }
    final linked = requested == null ? null : session.workspaceSuppliers.where((supplier) =>
      session.workspaceSupplierLedger(supplier.id)?.goodsReceipts.values.any((receipt) =>
        receipt.expectedDeliveryId == requested.deliveryGroupId) == true).singleOrNull;
    if (linked != null && linked.id != id) {
      setState(() => _error = 'This purchase is already linked to ${linked.name}. Choose that supplier to continue.');
      _supplierPicker.currentState?.didChange(_supplierId);
      return;
    }
    if (_originalAssistantReview && _receivingPreparing) {
      if (!_current) return;
      setState(() => _busy = true);
      try {
        if (await _readOriginalSupplierInput(id) && _current) {
          _lastQueuedInput = Map.of(_draftFields);
        }
      } finally {if (mounted) setState(() => _busy = false);}
      return;
    }
    setState(() => _busy = true);
    if (!await _flushInput()) {
      if (_current) setState(() { _busy = false; _supplierPicker.currentState?.didChange(_supplierId); });
      return;
    }
    if (!_current) return;
    _draft?.removeListener(_draftChanged); _draft?.dispose();
    _supplierId = id;
    _documents.clear(); _copyType = '';
    _frozen = null; _reviewVerified = false; _error = null; _notice = null;
    for (final line in _lines) { line.dispose(); } _lines.clear();
    _reference.clear(); _day.clear(); _arrivalId = ''; _groupId = '';
    _draft = _LedgerFormAutosave(session, session.supplierReceivingInputFormKey(id))..addListener(_draftChanged);
    final fields = await _draft!.load();
    if (!_current) return;
    if (fields != null) {
      try {
        _resumeSupplierInput(fields);
        // Loading and closing an unchanged entry must not create a new revision.
        if (_draft!.ready && fields.isNotEmpty) {
          _lastQueuedInput = Map<String, String>.of(_draftFields);
        }
      }
      on Object { _draft!.ready = false; _error = 'Saved delivery input needs recovery. Do not re-enter these goods.'; }
    }
    setState(() => _busy = false);
    if (_restockOriginal != null) await _recover();
  }
  Future<void> _startArrival({bool selected = false}) async {
    final previous = selected ? null : _frozen;
    final source = selected ? widget.initialRestockOriginal : previous?.restockOriginal;
    if (!_current || _busy || !_savedStatusResolved) return;
    if (source != null && !session.workspaceRestockUsesLegacyReceipts(source)) {
      setState(() { _busy = true; _error = null; });
      final ready = await session.recoverWorkspaceRestockReceiving(source);
      if (!_current) return;
      setState(() { _busy = false; _loaded = ready; _bookRevision = session.workspacePurchaseEntryRevision;
        if (!ready) _error = 'Recover this purchase’s receiving status before starting another arrival.'; });
      if (!ready) return;
    }
    setState(() => _newArrival(previous: previous));
  }
  void _newArrival({WorkspaceSupplierGoodsReceipt? previous}) {
    if(_prepareNewArrival(previous:previous))_saveInput();
  }
  bool _prepareNewArrival({WorkspaceSupplierGoodsReceipt? previous}) {
    final source = previous != null ? previous.restockOriginal : widget.initialRestockOriginal;
    final groupId = source?.deliveryGroupId ?? previous?.expectedDeliveryId;
    final server = source != null && !session.workspaceRestockUsesLegacyReceipts(source);
    final serverRead = source == null ? null : _originalAssistantReview && _receivingPreparing
      ? _checkedReceivingRead(source) : session.workspaceRestockReceiving(source);
    if (server && (serverRead == null || session.workspaceGoodsReceiptRecoveryPending)) {
      _error = 'Recover this purchase’s receiving status before starting another arrival.';
      return false;
    }
    final serverGroup = serverRead?.group;
    final receipts = _ledger?.goodsReceipts.values.where((receipt) => receipt.expectedDeliveryId == groupId).toList() ??
      const <WorkspaceSupplierGoodsReceipt>[];
    if (source != null && source.lines.entries.every((entry) => (server
        ? serverGroup?.lines.where((line) => line.sourceLineId == entry.key).singleOrNull?.deliveredMilli ?? 0
        : receipts.expand((receipt) => receipt.lines).where((line) => line.sourceLineId == entry.key)
          .fold<int>(0, (sum, line) => sum + line.deliveredMilli)) >= entry.value.quantityMilli)) {
      _error = 'All ordered quantities for this purchase are already recorded. Saved goods are kept.';
      return false;
    }
    _billReceiptChosen = true;
    for (final line in _lines) { line.dispose(); }
    _lines.clear();
    _restockOriginal = source;
    if (!server && (previous != null || receipts.isNotEmpty)) {
      final inherited = <String, WorkspaceSupplierGoodsReceiptLine>{
        for (final receipt in receipts) for (final line in receipt.lines) line.sourceLineId: line,
        if (previous != null) for (final line in previous.lines) line.sourceLineId: line,
      };
      for (final saved in inherited.values) {
        final line = _ReceivingLineInput(saved.sourceLineId, saved: saved);
        line.delivered.clear(); line.damaged.text = '0'; line.short.text = '0';
        final earlier = receipts.expand((r) => r.lines).where((l) => l.sourceLineId == saved.sourceLineId)
          .fold<int>(0, (sum, l) => sum + l.deliveredMilli);
        line.arrives = saved.expectedMilli == null || earlier < saved.expectedMilli!;
        for (final c in line.prior.values) { c.dispose(); } line.prior.clear();
        _lines.add(line);
      }
    } else if (_restockOriginal == null) { _lines.add(_ReceivingLineInput(session.newWorkspaceDeliveryLineId())); }
    if (_restockOriginal case final source?) {
      for (final entry in source.lines.entries) {
        if (_lines.any((line) => line.id == entry.key)) continue;
        final line = _ReceivingLineInput(entry.key);
        line.unit.text = entry.value.quantityUnit;
        line.expected.text = _ReceivingLineInput._quantity(entry.value.quantityMilli);
        line.factor.clear();
        final mapping = serverGroup?.lines.where((line) => line.sourceLineId == entry.key).singleOrNull;
        if (mapping != null) {
          line.productId = mapping.productId;
          line.factor.text = '${mapping.unitsPerPack}';
          line.arrives = mapping.deliveredMilli < mapping.expectedMilli;
        }
        _lines.add(line);
      }
    }
    _arrivalId = session.newWorkspaceGoodsReceiptId();
    _documents.clear(); _copyType = '';
    _groupId = _restockOriginal?.deliveryGroupId ?? previous?.expectedDeliveryId ?? session.newWorkspaceDeliveryGroupId();
    _reference.text = previous?.reference ?? _restockOriginal?.reference['orderId'] ?? '';
    _day.text = DateTime.now().toIso8601String().substring(0, 10);
    _frozen = null; _reviewVerified = false; _cancelAttempt = null; _postResult = null;
    _error = null; _notice = null;
    return true;
  }
  WorkspaceSupplierGoodsReceipt? _snapshot() {
    final values = <WorkspaceSupplierGoodsReceiptLine>[];
    for (final input in _lines) {
      if (!input.arrives) continue;
      final product = session.workspaceCatalogueItems.where((p) => p.id == input.productId).singleOrNull;
      final delivered = _ReceivingLineInput.milli(input.delivered.text);
      final damage = _ReceivingLineInput.milli(input.damaged.text);
      final short = _ReceivingLineInput.milli(input.short.text);
      final expected = input.expected.text.trim().isEmpty ? null : _ReceivingLineInput.milli(input.expected.text);
      final factor = int.tryParse(input.factor.text);
      if (product == null || delivered == null || damage == null || short == null || factor == null ||
          (input.expected.text.trim().isNotEmpty && expected == null)) { return null; }
      final prior = <String, int>{};
      for (final e in input.prior.entries) {
        final amount = int.tryParse(e.value.text.trim());
        if (e.value.text.trim().isEmpty || amount == 0) continue;
        if (amount == null || amount < 0) { return null; }
        prior[e.key] = amount;
      }
      final mrp = input.mrp.text.trim().isEmpty ? null : workspacePriceMinorFromInput(input.mrp.text,
        maximumMinor: 9007199254740991);
      if (input.mrp.text.trim().isNotEmpty && mrp == null) return null;
      final lot = WorkspaceReceivingLotDetails(batch: input.batch.text.trim(),
        manufacturedLabel: input.manufactured.text.trim(), expiryLabel: input.expiry.text.trim(), mrpMinor: mrp);
      if (!lot.isEmpty && !lot.valid) return null;
      final mapping = _serverReceiving ? _serverGroup?.lines.where((line) => line.sourceLineId == input.id).singleOrNull : null;
      values.add(WorkspaceSupplierGoodsReceiptLine(sourceLineId: input.id, productId: product.id,
        productLabel: mapping?.productId == product.id ? mapping!.productLabel
          : input.original?.productId == product.id ? input.original!.productLabel : product.title,
        purchaseUnit: input.unit.text.trim(), stockUnit: product.pack,
        unitsPerPack: factor, deliveredMilli: delivered, acceptedMilli: delivered - damage,
        damagedMilli: damage, shortMilli: short, expectedMilli: expected, priorStockUnits: prior,
        lotDetails: lot.isEmpty ? null : lot));
    }
    final recordedAt = DateTime.now();
    final receipt = WorkspaceSupplierGoodsReceipt(id: _arrivalId, expectedDeliveryId: _groupId,
      reference: _reference.text.trim(), deliveredOn: _day.text.trim(), recordedAt: recordedAt.toUtc(), lines: values,
      recordedUtcOffsetMinutes: !_serverReceiving ? null : recordedAt.timeZoneOffset.inMinutes,
      restockOriginal: _restockOriginal);
    return receipt.valid ? receipt : null;
  }
  bool get _canEnter => _current && !_busy && _loaded && !_discarding && _draft?.ready == true && _frozen == null;
  String get _captureId => WorkspaceSupplierGoodsReceiptDraft.captureId(_supplierId!, _arrivalId);
  Object? _assistantReceiptOwner;
  List<WorkspacePurchaseInvoiceAttachment> _assistantReceiptCopies = const [];
  int _assistantReceiptRevision = 0;
  bool get _assistantReceiptReviewReady => _current && !_busy && _loaded && !_discarding &&
      _supplierId != null && _arrivalId.isNotEmpty && (_frozen == null || _savedStatusResolved);
  bool get _assistantReceiptImportReady => _assistantReceiptReviewReady && _canEnter;

  MoolAssistantNativeSnapshot? _assistantReceiptSnapshot(
    MoolAssistantContext context, String? entity, String action,
  ) {
    if (!_assistantReceiptReviewReady) return null;
    if (action == 'AI-ACT-241') {
      if (!_assistantReceiptImportReady || entity != null) return null;
    } else {
      final copy = _documents.where((value) => value.digest == entity).firstOrNull;
      if (copy == null || !copy.valid ||
          action == 'AI-ACT-242' && copy.extractedFields.isEmpty ||
          action == 'AI-ACT-406' && copy.detectedText.trim().isEmpty ||
          !const {'AI-ACT-242', 'AI-ACT-405', 'AI-ACT-406'}.contains(action)) return null;
    }
    final owner = (_scope, _supplierId, _arrivalId, _captureId,
      session.navigationScopeRevision, _draft?.revision, _bookRevision,
      _input, _copyType, _frozen);
    if (_assistantReceiptOwner != owner || !listEquals(_assistantReceiptCopies, _documents)) {
      _assistantReceiptOwner = owner;
      _assistantReceiptCopies = List.of(_documents);
      _assistantReceiptRevision++;
    }
    return MoolAssistantNativeSnapshot(binding: context.binding, permitted: true,
      entityId: entity, sourceRevision: 'receiving-document-form-v1:$_assistantReceiptRevision');
  }

  bool Function() _assistantReceiptGuard(bool Function() reviewCurrent) {
    final supplier = _supplierId, arrival = _arrivalId, capture = _captureId,
      navigation = session.navigationScopeRevision, input = _input,
      type = _copyType, draft = _draft, revision = _draft?.revision, frozen = _frozen,
      book = _bookRevision, sourceBook = session.workspacePurchaseEntryRevision;
    final copies = List<WorkspacePurchaseInvoiceAttachment>.of(_documents);
    return () => _current && !_discarding && _loaded && reviewCurrent() &&
      _supplierId == supplier && _arrivalId == arrival && _captureId == capture &&
      session.navigationScopeRevision == navigation && identical(_draft, draft) &&
      _draft?.revision == revision && _input == input && _copyType == type &&
      _bookRevision == book && session.workspacePurchaseEntryRevision == sourceBook &&
      identical(_frozen, frozen) && (_frozen == null || _savedStatusResolved) && listEquals(_documents, copies);
  }

  Future<MoolAssistantReviewResult> _assistantReceiptFields(
    WorkspacePurchaseInvoiceAttachment copy, bool Function() current, {
    WorkspacePurchaseInvoiceAttachment? existing,
    required bool Function() reviewCurrent,Listenable? ownerChanges,Future<bool> Function(WorkspacePurchaseInvoiceAttachment)? beforeKeep,
  }) async {
    if (!current()) return MoolAssistantReviewResult.stale;
    final arrival = _arrivalId, supplier = _supplierId,
      navigation = session.navigationScopeRevision, capture = _captureId;
    final readOnly = _frozen != null;
    // No _flushInput before navigation: staged proposal data is not autosaved.
    final edited = await Navigator.of(context, rootNavigator: true)
      .push<WorkspacePurchaseInvoiceAttachment>(MaterialPageRoute(builder: (_) {
        final fieldsKey=GlobalKey<_ReceivingScannedFieldsState>();
        final screen=_ReceivingScannedFieldsScreen(key:fieldsKey,session: session, scope: _scope!, captureId: capture,
          attachment: copy, readOnly: readOnly, isCurrent: current,
          beforeKeep:beforeKeep,canKeep: (value) => current() && WorkspaceSupplierGoodsReceiptDraft.validDocuments([
            for (final old in _documents) if (!identical(old, existing)) old, value,
          ]));
        return ownerChanges==null?screen:_ReceivingOwnerSurface(current:current,changes:ownerChanges,child:screen,onClose:(){if(fieldsKey.currentState case final state?)unawaited(state._close());});
      }));
    if (!current()) return MoolAssistantReviewResult.stale;
    if (edited == null || readOnly) return MoolAssistantReviewResult.opened;
    // A non-null result comes only from the ORIGINAL explicit Save printed
    // details action. Only this user action may change the receipt draft.
    final copies = [for (final old in _documents) if (!identical(old, existing)) old, edited];
    if (!WorkspaceSupplierGoodsReceiptDraft.validDocuments(copies))
      return MoolAssistantReviewResult.unavailable;
    setState(() { _documents..clear()..addAll(copies); });
    final saved = await _flushInput();
    if (!_current || !reviewCurrent() || _arrivalId != arrival || _supplierId != supplier ||
        session.navigationScopeRevision != navigation) return MoolAssistantReviewResult.stale;
    return saved ? MoolAssistantReviewResult.opened : MoolAssistantReviewResult.unavailable;
  }

  Future<MoolAssistantReviewResult> _assistantImportReceiptDocument(
    MoolAssistantSelectedDocument selected, bool Function() reviewCurrent,
  ) async {
    if (!reviewCurrent()) return MoolAssistantReviewResult.stale;
    if (!_assistantReceiptImportReady) return MoolAssistantReviewResult.unavailable;
    final current = _assistantReceiptGuard(reviewCurrent);
    final capture = _captureId, scope = _scope!, type = _copyType;
    if (_documents.any((copy) => copy.digest == selected.sourceDigest))
      return MoolAssistantReviewResult.unavailable;
    WorkspacePurchaseInvoiceAttachment? retained, scanned;
    setState(() { _busy = true; _error = null; });
    try {
      retained = await session.workspacePurchaseInvoiceCapture.retainSelectedForDraft(
        scope, capture, selected.proof, source: selected.reference.source,
        canRetain: (candidate) => current() && candidate.digest == selected.sourceDigest &&
          !_documents.any((copy) => copy.digest == candidate.digest) &&
          WorkspaceSupplierGoodsReceiptDraft.validDocuments([..._documents,
            type.isEmpty ? candidate : candidate.withDocumentDetails({'type': type})]),
      );
      if (!current()) return MoolAssistantReviewResult.stale;
      if (type.isNotEmpty) retained = retained.withDocumentDetails({'type': type});
      // Reuse native OCR; do not call _readDocument because it flushes input.
      scanned = await session.workspacePurchaseInvoiceCapture.scan(scope, capture, retained);
      if (!current()) return MoolAssistantReviewResult.stale;
      if (!WorkspaceSupplierGoodsReceiptDraft.validDocuments([..._documents, scanned])) {
        scanned = null;
        setState(() => _error = 'The read details exceed the copy limit. Your earlier copies and entries are kept.');
      }
    } on Object catch (error) {
      if (!current()) return MoolAssistantReviewResult.stale;
      setState(() => _error = error is WorkGatewayException ? error.message :
        'Text could not be read. The selected copy is kept; enter details manually.');
    } finally { if (mounted) setState(() => _busy = false); }
    if (!current()) return MoolAssistantReviewResult.stale;
    final ready = scanned;
    if (ready != null) return _assistantReceiptFields(ready, current, reviewCurrent: reviewCurrent);
    final original = retained;
    if (original != null) {
      // Actual visible original, never a covered underlying form-state change.
      await Navigator.of(context, rootNavigator: true).push<void>(MaterialPageRoute(builder: (_) =>
        _GoodsReceiptCopyScreen(session: session, scope: scope, captureId: capture,
          attachment: original, isCurrent: current)));
    }
    return current() ? MoolAssistantReviewResult.unavailable : MoolAssistantReviewResult.stale;
  }

  Future<MoolAssistantReviewResult> _assistantReviewReceiptDocument(
    String action, String digest, bool Function() reviewCurrent,
  ) async {
    if (!reviewCurrent()) return MoolAssistantReviewResult.stale;
    if (!_assistantReceiptReviewReady) return MoolAssistantReviewResult.unavailable;
    final copy = _documents.where((value) => value.digest == digest).firstOrNull;
    if (copy == null) return MoolAssistantReviewResult.unavailable;
    final current = _assistantReceiptGuard(reviewCurrent);
    if (action == 'AI-ACT-242') {
      if (copy.extractedFields.isEmpty) return MoolAssistantReviewResult.unavailable;
      return _assistantReceiptFields(copy, current, existing: copy, reviewCurrent: reviewCurrent);
    }
    if (action == 'AI-ACT-405') {
      await Navigator.of(context, rootNavigator: true).push<void>(MaterialPageRoute(builder: (_) =>
        _GoodsReceiptCopyScreen(session: session, scope: _scope!, captureId: _captureId,
          attachment: copy, isCurrent: current)));
    } else if (action == 'AI-ACT-406' && copy.detectedText.trim().isNotEmpty) {
      await _viewDetectedText(copy, reviewCurrent: current);
    } else { return MoolAssistantReviewResult.unavailable; }
    return current() ? MoolAssistantReviewResult.opened : MoolAssistantReviewResult.stale;
  }

  Future<void> _captureDocument(WorkProofSource source) async {
    if (!_canEnter || _documents.length >= 3) return;
    final arrival = _arrivalId, supplier = _supplierId, captureId = _captureId,
      navigation = session.navigationScopeRevision;
    FocusScope.of(context).unfocus();
    setState(() { _busy = true; _error = null; });
    try {
      if (!await _flushInput()) return;
      final captured = await session.workspacePurchaseInvoiceCapture.capture(_scope!, captureId, source);
      final attachment = captured == null ? null : _copyType.isEmpty ? captured : captured.withDocumentDetails({'type': _copyType});
      if (!_current || _arrivalId != arrival || _supplierId != supplier || _frozen != null ||
          navigation != session.navigationScopeRevision || attachment == null) { return; }
      if (_documents.any((a) => a.digest == attachment.digest)) {
        setState(() => _error = 'This copy is already attached.');
      } else if (!WorkspaceSupplierGoodsReceiptDraft.validDocuments([..._documents, attachment])) {
        setState(() => _error = 'Keep up to 3 copies, within 20 MB in total.');
      } else {
        setState(() => _documents.add(attachment));
        await _flushInput();
      }
    } on Object {
      if (_current) setState(() => _error = 'Copy could not be attached. Use a clear photo or PDF up to 10 MB. Your entries are kept.');
    } finally { if (_current) setState(() => _busy = false); }
  }
  Future<void> _readDocument(WorkspacePurchaseInvoiceAttachment attachment) async {
    if (!_canEnter || !_documents.contains(attachment)) return;
    final arrival = _arrivalId, supplier = _supplierId, captureId = _captureId,
      navigation = session.navigationScopeRevision;
    setState(() { _busy = true; _error = null; });
    try {
      final read = await session.workspacePurchaseInvoiceCapture.scan(_scope!, captureId, attachment);
      if (!_current || _arrivalId != arrival || _supplierId != supplier || _frozen != null ||
          navigation != session.navigationScopeRevision || !_documents.contains(attachment)) { return; }
      final copies = [for (final old in _documents) if (identical(old, attachment)) read else old];
      if (!WorkspaceSupplierGoodsReceiptDraft.validDocuments(copies)) {
        setState(() => _error = 'The read details exceed this delivery’s saved-copy limit. Earlier copies and entries are kept; use smaller copies.');
        return;
      }
      setState(() => _documents[_documents.indexOf(attachment)] = read);
      await _flushInput();
    } on Object catch (error) {
      if (_current) {
        setState(() => _error = error is WorkGatewayException ? error.message :
          'Text could not be read. The copy and your entries are kept; view it and enter details manually.');
      }
    } finally { if (_current) setState(() => _busy = false); }
  }
  Future<void> _viewDocument(WorkspacePurchaseInvoiceAttachment attachment) async {
    if (!_current || _busy || !_documents.contains(attachment)) return;
    if (_frozen == null && !await _flushInput()) return;
    if (!mounted || !_current) return;
    await Navigator.of(context).push<void>(MaterialPageRoute(builder: (_) => _GoodsReceiptCopyScreen(
      session: session, scope: _scope!, captureId: _captureId, attachment: attachment)));
  }
  Future<void> _viewDetectedText(WorkspacePurchaseInvoiceAttachment attachment, {
    bool Function()? reviewCurrent,
  }) async {
    if (!_current || _busy || !_documents.contains(attachment) || reviewCurrent?.call() == false) return;
    await showDialog<void>(context: context, builder: (dialogContext) => AlertDialog(
      title: const Text('Read from copy'),
      content: AnimatedBuilder(animation: session, builder: (context, _) => !_current || !_documents.contains(attachment) || reviewCurrent?.call() == false
        ? const Text('Return to the same receiving record to view this text.')
        : SingleChildScrollView(child: Column(mainAxisSize: MainAxisSize.min,
        crossAxisAlignment: CrossAxisAlignment.start, children: [
          const Text('Compare with the original. Printed quantities do not confirm goods received.', style: TextStyle(fontSize: 12)),
          const SizedBox(height: 8), SelectableText(attachment.pageTextLengths.isEmpty ? attachment.detectedText :
            attachment.recognizedTextPages.indexed.map((page) => 'Page ${page.$1 + 1}\n${page.$2}').join('\n\n'),
            style: const TextStyle(fontSize: 12)),
        ]))),
      actions: [TextButton(onPressed: () => Navigator.pop(dialogContext), child: const Text('Close'))]));
  }
  Future<void> _editDocumentFields(WorkspacePurchaseInvoiceAttachment attachment) async {
    if (!_current || _busy || !_documents.contains(attachment)) return;
    final arrival = _arrivalId, supplier = _supplierId, captureId = _captureId,
      navigation = session.navigationScopeRevision;
    final readOnly = _frozen != null;
    if (!readOnly && !await _flushInput()) return;
    if (!mounted || !_current || _arrivalId != arrival || _supplierId != supplier ||
        navigation != session.navigationScopeRevision || !_documents.contains(attachment)) { return; }
    setState(() { _busy = true; _error = null; });
    try {
      final edited = await Navigator.of(context).push<WorkspacePurchaseInvoiceAttachment>(MaterialPageRoute(
        builder: (_) => _ReceivingScannedFieldsScreen(session: session, scope: _scope!, captureId: captureId,
          attachment: attachment, readOnly: readOnly, canKeep: (edited) => WorkspaceSupplierGoodsReceiptDraft.validDocuments(
            [for (final old in _documents) if (identical(old, attachment)) edited else old]),
          isCurrent: () => _current && _arrivalId == arrival &&
            _supplierId == supplier && navigation == session.navigationScopeRevision && _documents.contains(attachment))));
      if (edited == null || readOnly || !_current || _frozen != null || _arrivalId != arrival ||
          _supplierId != supplier || navigation != session.navigationScopeRevision || !_documents.contains(attachment)) { return; }
      final copies = [for (final old in _documents) if (identical(old, attachment)) edited else old];
      if (!WorkspaceSupplierGoodsReceiptDraft.validDocuments(copies)) {
        setState(() => _error = 'These details exceed the saved-copy limit. Earlier details are kept; shorten or split the copy.');
        return;
      }
      setState(() => _documents[_documents.indexOf(attachment)] = edited);
      await _flushInput();
    } finally { if (_current) setState(() => _busy = false); }
  }
  Future<void> _editDocumentDetails(WorkspacePurchaseInvoiceAttachment attachment) async {
    if (!_current || _busy || !_documents.contains(attachment)) return;
    final supplier = _supplierId, arrival = _arrivalId, navigation = session.navigationScopeRevision;
    bool current() => _current && _supplierId == supplier && _arrivalId == arrival &&
      session.navigationScopeRevision == navigation && _documents.contains(attachment);
    final updated = await showModalBottomSheet<WorkspacePurchaseInvoiceAttachment>(context: context,
      isScrollControlled: true, useSafeArea: true, builder: (_) => _TradeDocumentDetailsEditor(
        session: session, attachment: attachment, types: WorkspacePurchaseInvoiceAttachment.receivingDocumentTypes,
        isCurrent: current, readOnly: _frozen != null, canKeep: (value) => WorkspaceSupplierGoodsReceiptDraft.validDocuments(
          [for (final a in _documents) if (identical(a, attachment)) value else a])));
    if (updated == null || !current() || _frozen != null || _busy) return;
    setState(() { _documents[_documents.indexOf(attachment)] = updated; _busy = true; });
    try { await _flushInput(); } finally { if (_current) setState(() => _busy = false); }
  }
