  String? _storeId, _lastViewedId;
  bool _showedDetails = false;
  final _returnRowKey = GlobalKey();
  final _purchaseSearch = TextEditingController();
  final _purchaseSearchFocus = FocusNode(debugLabel: 'purchase-search');
  List<String>? _purchaseHistory;
  String _purchaseFilter = 'All';
  bool _recordPurchase = false, _openingOnly = false;
  bool _actionCentreOpen = false;
  bool _centreVisible = false, _purchaseActionPending = false;
  int _centreEpoch = 0;
  final _expandedCategories = <String>{};
  final _receivingResumeIds = <String>{};
  bool _receivingResumeUnknown = false;
  bool _receiveGoods = false;
  String? _receivingSupplierId;
  WorkspacePurchaseSavedCopy? _returnReceivingCopy;
  Object? _surfaceScope;
  double _registerBookmark = 0;
  int _registerBookmarkEpoch = 0;
  final _localRegisterBookmark = _PurchaseRegisterBookmark();
  final Object _registerOwner = Object();
  late _PurchaseRegisterBookmark _registerView;
  bool _registerBindingChanged = false, _pendingDetailReturn = false, _detailReturnScheduled = false;
  Object get _registerScope => (
    session.contactDraftStore?.accountScope ?? session.pendingProofStore?.accountScope,
    session.activeWorkspace?.id, session.workspaceSupplierScope,
  );
  bool get _ownsRegisterView => identical(_registerView.owner, _registerOwner) &&
      _registerView.scope == _registerScope &&
      identical(_registerView.history, session.workspaceRecentSearches('purchases'));
  final _pendingRegisterRestoration = <ScrollPosition>{};
  final _scheduledRegisterRestoration = <ScrollPosition>{};
  final _registerRestorationExtents = <ScrollPosition, double>{};
  final _registerRestorationAttempts = <ScrollPosition, int>{};
  final _registerPositionEpochs = <ScrollPosition, int>{};
  late final ScrollController _registerScroll = ScrollController(
    keepScrollOffset: false,
    onDetach: (position) {
      if (_registerPositionEpochs.remove(position) == _registerBookmarkEpoch && position.hasPixels &&
          !_pendingRegisterRestoration.contains(position)) {
        _registerBookmark = position.pixels;
        if (_ownsRegisterView) {
          _registerView.offset = position.pixels;
          _registerView.query = _purchaseSearch.text;
          _registerView.filter = _purchaseFilter;
        }
      }
      _pendingRegisterRestoration.remove(position);
      _registerRestorationExtents.remove(position);
      _registerRestorationAttempts.remove(position);
    },
    onAttach: (position) {
      final scope = session.workspaceSupplierScope;
      final epoch = _registerBookmarkEpoch;
      _registerPositionEpochs[position] = epoch;
      _pendingRegisterRestoration.add(position);
      _scheduleRegisterRestoration(position, epoch, scope);
    },
  );
  bool _newPurchase = false;
  bool _assistantRegisterApplied = false, _assistantRegisterRejected = false;
  WorkspacePurchaseSavedCopy? _savedCopy;

  void _scheduleRegisterRestoration(ScrollPosition position, int epoch, Object? scope) {
    if (!_scheduledRegisterRestoration.add(position)) return;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      _scheduledRegisterRestoration.remove(position);
      if (!mounted || epoch != _registerBookmarkEpoch || scope != session.workspaceSupplierScope ||
          !_ownsRegisterView || !_registerScroll.positions.contains(position) ||
          session.focusedWorkspacePurchaseId != null || _centreVisible ||
          _recordPurchase || _savedCopy != null || _receiveGoods) {
        _pendingRegisterRestoration.remove(position);
        _registerRestorationExtents.remove(position);
        _registerRestorationAttempts.remove(position);
        return;
      }
      if (!_pendingRegisterRestoration.contains(position) || !position.hasContentDimensions) return;
      final maximum = position.maxScrollExtent;
      final previousMaximum = _registerRestorationExtents[position];
      final attempts = _registerRestorationAttempts[position] ?? 0;
      // A lazy sliver initially estimates its extent from the first built rows.
      // Jumping to that boundary lays out more rows; do not accept the initial
      // clamp as the saved position while the extent is still converging.
      if (_registerBookmark > maximum && previousMaximum != maximum && attempts < 32) {
        _registerRestorationExtents[position] = maximum;
        _registerRestorationAttempts[position] = attempts + 1;
        position.jumpTo(maximum);
        _scheduleRegisterRestoration(position, epoch, scope);
        WidgetsBinding.instance.scheduleFrame();
        return;
      }
      _pendingRegisterRestoration.remove(position);
      _registerRestorationExtents.remove(position);
      _registerRestorationAttempts.remove(position);
      position.jumpTo(_registerBookmark.clamp(position.minScrollExtent, maximum));
      _scheduleDetailReturn();
    });
  }

  void _scheduleDetailReturn() {
    if (!_pendingDetailReturn || _detailReturnScheduled) return;
    _detailReturnScheduled = true;
    final scope = _registerScope, epoch = _registerBookmarkEpoch;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      _detailReturnScheduled = false;
      if (!mounted || !_pendingDetailReturn || !_ownsRegisterView || scope != _registerScope ||
          epoch != _registerBookmarkEpoch || session.focusedWorkspacePurchaseId != null) return;
      if (_pendingRegisterRestoration.isNotEmpty) return;
      final target = _returnRowKey.currentContext;
      if (target != null && target.mounted) {
        _pendingDetailReturn = false;
        unawaited(Scrollable.ensureVisible(target, alignment: .5));
      }
    });
    // addPostFrameCallback alone does not request a subsequent layout frame.
    WidgetsBinding.instance.scheduleFrame();
  }

  VoidCallback? _captureTrackingReturn() {
    if (!_ownsRegisterView || _centreVisible || _registerScroll.positions.length != 1) return null;
    final position = _registerScroll.positions.single;
    if (!position.hasPixels || _pendingRegisterRestoration.contains(position)) return null;
    final bookmark = _registerView;
    final epoch = _registerBookmarkEpoch, scope = _registerScope;
    final history = _purchaseHistory;
    final offset = position.pixels, query = _purchaseSearch.text, filter = _purchaseFilter;
    return () {
      if (!mounted || !identical(bookmark, _registerView) || !_ownsRegisterView ||
          _centreVisible || session.focusedWorkspacePurchaseId != null || scope != _registerScope ||
          _registerScroll.positions.length != 1 || !identical(_registerScroll.positions.single, position) ||
          _pendingRegisterRestoration.contains(position) || _registerPositionEpochs[position] != epoch ||
          epoch != _registerBookmarkEpoch || !identical(history, _purchaseHistory) ||
          query != _purchaseSearch.text || filter != _purchaseFilter) return;
      _registerView.offset = offset;
      _registerView.query = query;
      _registerView.filter = filter;
      // Departing detach/dispose callbacks cannot overwrite this snapshot.
      _registerView.owner = null;
    };
  }

  @override
  void initState() {
    super.initState();
    _registerView = widget.registerBookmark ?? _localRegisterBookmark;
    _registerView.owner = _registerOwner;
    _purchaseSearchFocus.addListener(_refreshPurchaseSearch);
    if (!statement) {
      if (widget.assistantReadOnlyOpen) {
        // The original register binds its scope during its first build. A
        // read-only AI entry has no asynchronous admission to defer hydration.
        WidgetsBinding.instance.addPostFrameCallback((_) {
          if (mounted) unawaited(_loadEntry());
        });
      } else {
        unawaited(_loadEntry());
      }
    }
  }

  @override
  void didUpdateWidget(covariant _StorePurchasesSurface oldWidget) {
    super.didUpdateWidget(oldWidget);
    final next = widget.registerBookmark ?? _localRegisterBookmark;
    if (!identical(next, _registerView)) {
      if (identical(_registerView.owner, _registerOwner)) _registerView.owner = null;
      _registerView = next;
      _registerBindingChanged = true;
      _pendingRegisterRestoration.clear();
    }
  }

  Future<void> _loadEntry() async {
    final loaded = widget.assistantReadOnlyOpen
      ? session.workspaceSuppliersLoaded && !session.workspaceSupplierSaving && !session.workspaceSupplierRecoveryRequired
      : await session.loadWorkspaceSuppliers();
    if (!mounted || widget.assistantOwnerCurrent?.call() == false) return;
    final initial = widget.assistantInitialQuery != null || widget.assistantOpenActions || widget.assistantShipmentId != null;
    if (initial && !_assistantRegisterApplied && loaded && widget.assistantSourceCurrent?.call() != false &&
        !_registerBindingChanged && _ownsRegisterView && !_recordPurchase && !_receiveGoods && _savedCopy == null &&
        _purchaseSearch.text.isEmpty && !_centreVisible && !_actionCentreOpen) {
      _assistantRegisterApplied = true;
      if (widget.assistantShipmentId case final shipment?) {
        session.selectWorkspacePurchase(shipment); // Existing native read/navigation only.
      } else {
        session.clearWorkspacePurchaseSelection();
        if (widget.assistantInitialQuery case final query?) _purchaseSearch.text = query;
      }
      if (widget.assistantOpenActions) await _openActionCentre(readOnlyOpen: widget.assistantReadOnlyOpen);
    }
    if (initial && !_assistantRegisterApplied) _assistantRegisterRejected = true;
    if (mounted) setState(() {});
  }

  void _refreshPurchaseSearch() {
    if (mounted) setState(() {});
  }

  @override
  void dispose() {
    if (identical(_registerView.owner, _registerOwner)) _registerView.owner = null;
    _registerScroll.dispose();
    _purchaseSearch.dispose();
    _purchaseSearchFocus.removeListener(_refreshPurchaseSearch);
    _purchaseSearchFocus.dispose();
    super.dispose();
  }

  bool _matchesReceiptFilter(WorkspacePurchaseRecord record) =>
      switch (_purchaseFilter) {
        'Incoming' => record.stage != WorkspaceSupplyStage.unknown &&
            record.stage.incoming,
        'Needs receipt' =>
          record.stage != WorkspaceSupplyStage.cancelled &&
          record.stage != WorkspaceSupplyStage.returned &&
          (record.receiptState == WorkspaceReceiptState.partial ||
           record.receiptState == WorkspaceReceiptState.disputed ||
           (record.stage == WorkspaceSupplyStage.delivered &&
            record.receiptState == WorkspaceReceiptState.awaiting)),
        'Received' => record.receiptState == WorkspaceReceiptState.confirmed,
        _ => true,
      };

  String _actionReceiptSummary(WorkspaceSupplierGoodsReceipt receipt) {
    final quantity = receipt.lines.fold<int>(0, (sum, line) => sum + line.deliveredMilli);
    final code = receipt.id.length > 12 ? receipt.id.substring(receipt.id.length - 12) : receipt.id;
    return '${receipt.deliveredOn} · ${receipt.lines.length} items · Qty ${_ReceivingLineInput._quantity(quantity)}\n'
      'Recorded ${receipt.recordedAt.toLocal().toIso8601String()} · Delivery $code';
  }

  String _actionReceiptStock(WorkspaceSupplierGoodsReceiptLine line,
      WorkspaceSupplierGoodsReceipt receipt, bool verified) {
    final expected = receipt.movementFor(line);
    if (!verified || session.workspaceGoodsReceiptRecoveryPending ||
        (expected != null && !session.workspaceStockMovements.any((movement) =>
          movement.contentIdentity == expected.contentIdentity))) {
      return 'Stock update not verified · Qty to add ${line.newStockUnits}';
    }
    return 'Stock added ${line.newStockUnits}';
  }

  Future<T?> _chooseActionRecord<T>(String title, List<(T, String, String)> rows, {String? supplierName}) {
    if (supplierName != null) {
      return showDialog<T>(context: context, useRootNavigator: true, useSafeArea: true,
        builder: (sheetContext) => _purchaseCapturedOwnerPage(context, sheetContext, session, widget.assistantOwnerCurrent, Dialog(insetPadding: const EdgeInsets.symmetric(horizontal: 12, vertical: 24), child: ConstrainedBox(
          key: const Key('supplier-payment-purpose-sheet'),
          constraints: BoxConstraints(maxHeight: MediaQuery.sizeOf(sheetContext).height * .8),
          child: SafeArea(top: false, child: Column(mainAxisSize: MainAxisSize.min, children: [
            Padding(padding: const EdgeInsets.only(left: 16, right: 4), child: Row(children: [
              Expanded(child: Text(title, style: const TextStyle(fontSize: 14, fontWeight: FontWeight.w700, color: MoolColors.navy))),
              IconButton(key: const Key('supplier-payment-purpose-close'), tooltip: 'Close',
                onPressed: () => Navigator.pop(sheetContext), icon: const Icon(Icons.close, size: 20)),
            ])),
            Flexible(child: SingleChildScrollView(child: Padding(padding: const EdgeInsets.fromLTRB(16, 0, 16, 8),
              child: Column(crossAxisAlignment: CrossAxisAlignment.start, mainAxisSize: MainAxisSize.min, children: [
                Text(supplierName, style: const TextStyle(fontSize: 13, fontWeight: FontWeight.w600, color: MoolColors.ink)),
                const Padding(padding: EdgeInsets.only(top: 4, bottom: 8), child: Text('Choose how to record money already paid.',
                  style: TextStyle(fontSize: 12, color: MoolColors.muted))),
                for (final row in rows) ListTile(key: ValueKey('supplier-payment-purpose-${row.$1}'),
                  contentPadding: EdgeInsets.zero, minVerticalPadding: 8, dense: true,
                  title: Text(row.$2, style: const TextStyle(fontSize: 14, fontWeight: FontWeight.w600, color: MoolColors.navy)),
                  subtitle: Text(row.$3, style: const TextStyle(fontSize: 12, color: MoolColors.muted)),
                  trailing: const Icon(Icons.chevron_right, size: 20), onTap: () => Navigator.pop(sheetContext, row.$1)),
              ])))),
          ]))))));
    }
    return showDialog<T>(context: context, useSafeArea: true, builder: (dialogContext) => _purchaseCapturedOwnerPage(context, dialogContext, session, widget.assistantOwnerCurrent, Dialog.fullscreen(
      child: SafeArea(child: Column(children: [
        ListTile(title: Text(title), trailing: IconButton(tooltip: 'Close',
          onPressed: () => Navigator.pop(dialogContext), icon: const Icon(Icons.close))),
        Expanded(child: ListView(children: [
          if (rows.isEmpty) const Padding(padding: EdgeInsets.all(16), child: Text(
            'No eligible saved record is available. Return to Purchases to record or recover it.')),
          for (final row in rows) ListTile(title: Text(row.$2), subtitle: Text(row.$3),
            trailing: const Icon(Icons.chevron_right), onTap: () => Navigator.pop(dialogContext, row.$1)),
        ])),
      ])))));
  }

  Future<void> _purchaseAction(String action) async {
    _purchaseSearchFocus.unfocus();
    final scope = session.workspaceSupplierScope;
    final epoch = _centreEpoch;
    bool current() => mounted && epoch == _centreEpoch && scope != null &&
      widget.assistantOwnerCurrent?.call() != false &&
      scope == session.workspaceSupplierScope && ModalRoute.of(context)?.isCurrent != false;
    if (!current()) return;
    if (action == 'record-bill' || action == 'continue-bill') {
      if (action == 'record-bill' && session.workspacePurchaseEntryDraft != null && !session.workspacePurchaseDraftReviewed) {
        ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Continue your unfinished bill before starting another.')));
        return;
      }
      setState(() { _openingOnly = false; _savedCopy = null;
        _newPurchase = action == 'record-bill' && session.workspacePurchaseDraftReviewed;
        _recordPurchase = true; });
      return;
    }
    if (action == 'edit') {
      final copy = await _chooseActionBill('Choose saved bill entry to edit', editableOnly: true);
      if (!mounted || !current() || copy == null ||
          session.workspacePurchaseEntryDraft?.id != copy.draft.id ||
          jsonEncode(session.workspacePurchaseEntryDraft?.toJson()) != jsonEncode(copy.draft.toJson())) {
        return;
      }
      setState(() { _savedCopy = null; _openingOnly = false; _newPurchase = false; _recordPurchase = true; });
      return;
    }
    if (!session.workspaceSuppliersLoaded) return;
    if (action == 'recorded' || action == 'documents') {
      setState(() { _purchaseFilter = 'All'; _purchaseSearch.clear(); });
      return;
    }
    if (action == 'opening' || action == 'review-opening') {
      setState(() { _openingOnly = true; _newPurchase = false; _savedCopy = null; _recordPurchase = true; });
      return;
    }
    if (action == 'stock') { widget.onOpenStock?.call(); return; }
    if (action == 'receive') { setState(() => _receiveGoods = true); return; }
    if (action == 'continue-receive' || action == 'prior-stock') {
      final eligible = {
        for (final supplier in session.workspaceSuppliers)
          if (action != 'continue-receive' || _receivingResumeIds.contains(supplier.id)) supplier.id,
      };
      final selected = await _showStoreSupplierSelector(context, session, eligibleSupplierIds: eligible,
        purposeGuide: action == 'continue-receive'
          ? 'Choose the supplier for the delivery entry you want to continue.'
          : 'Choose the supplier for the goods already added to Stock.',
        emptyMessage: action == 'continue-receive'
          ? 'No unfinished delivery entries are available.' : 'No suppliers are available to link these goods.', ownerCurrent: widget.assistantOwnerCurrent);
      if (!current() || selected == null || !eligible.contains(selected) ||
          !session.workspaceSuppliers.any((p) => p.id == selected)) {
        return;
      }
      setState(() { _receivingSupplierId = selected; _receiveGoods = true; });
      return;
    }
    final recovered = await session.recoverCustomerLedger();
    if (!mounted || !current()) return;
    if (action == 'goods-history') {
      final review = await _chooseActionRecord<WorkspaceSupplierGoodsReceiptDraft>('Choose received goods', [
        for (final review in session.workspaceGoodsReceiptDrafts)
          if (!session.workspaceGoodsReceiptCancellations.any((c) => c.receiptId == review.receipt.id))
            (review, review.receipt.reference, '${session.workspaceSuppliers.where((s) => s.id == review.supplierId).firstOrNull?.name ?? 'Supplier unavailable'} · ${_actionReceiptSummary(review.receipt)}'),
      ]);
      if (!mounted || !current() || review == null || !session.workspaceGoodsReceiptDrafts.any((r) => jsonEncode(r.toJson()) == jsonEncode(review.toJson()))) return;
      final receipt = review.receipt;
      final supplier = session.workspaceSuppliers.where((s) => s.id == review.supplierId).firstOrNull;
      final ledger = session.workspaceSupplierLedger(review.supplierId);
      final verified = jsonEncode(ledger?.goodsReceipts[receipt.id]?.toJson()) == jsonEncode(receipt.toJson());
      await showDialog<void>(context: context, builder: (dialogContext) => _purchaseCapturedOwnerPage(context, dialogContext, session, widget.assistantOwnerCurrent, Dialog.fullscreen(child: SafeArea(
        child: Column(children: [ListTile(title: Text(receipt.reference), subtitle: Text('${supplier?.name ?? 'Supplier unavailable'} · ${receipt.deliveredOn}'),
          trailing: IconButton(tooltip: 'Close', onPressed: () => Navigator.pop(dialogContext), icon: const Icon(Icons.close))),
          Expanded(child: ListView(padding: const EdgeInsets.all(16), children: [
            Text(verified ? 'Goods received · saved record' : 'Delivery review · receipt posting not verified'),
            for (final line in receipt.lines) ListTile(title: Text(line.productLabel), subtitle: Text(
              'Received ${_ReceivingLineInput._quantity(line.deliveredMilli)} ${line.purchaseUnit} · Accepted ${_ReceivingLineInput._quantity(line.acceptedMilli)}\n'
              'Damaged ${_ReceivingLineInput._quantity(line.damagedMilli)} · Short ${_ReceivingLineInput._quantity(line.shortMilli)}\n'
              'Earlier Stock linked ${line.linkedStockUnits} · ${_actionReceiptStock(line, receipt, recovered && verified)}'
              '${line.lotDetails == null ? '' : '\nRecorded from this arrival · private\n${line.lotDetails!.labels.join('\n')}'}')),
            for (final returned in ledger?.goodsReturns.values ?? <WorkspaceSupplierGoodsReturn>[])
              if (returned.receiptId == receipt.id) ListTile(title: Text('Return ${returned.reference}'),
                subtitle: Text('${returned.returnedOn} · ${returned.reason}\n${returned.lines.map((l) => '${l.productLabel}: ${l.stockUnits}').join(', ')}')),
          ])),
        ])))));
      return;
    }
    if (action == 'accounts' || action == 'statement' || action == 'money-history' || action == 'money' || action == 'refund' || action == 'return') {
      final selected = await _showStoreSupplierSelector(context, session, ownerCurrent: widget.assistantOwnerCurrent);
      if (!mounted || !current() || selected == null) return;
      final supplier = session.workspaceSuppliers.where((p) => p.id == selected).singleOrNull;
      if (!mounted || !current() || supplier == null || !session.workspaceSuppliers.any((p) => p.id == supplier.id)) return;
      final ledger = session.workspaceSupplierLedger(supplier.id);
      if (action == 'money') {
        final purpose = await _chooseActionRecord<String>('Record supplier payment', const [
          ('bill', 'Against a bill', 'Select the supplier bill this payment settles.'),
          ('advance', 'Supplier advance', 'Paid before the supplier bill is received.'),
          ('account', 'On-account payment', 'Paid to the supplier without choosing a bill.'),
        ], supplierName: supplier.name);
        if (!mounted || !current() || purpose == null) return;
        if (purpose != 'bill') {
          await _showSupplierMoneyEntry(context, session,
            _StoreSupplierMoneyTarget(supplierId: supplier.id, advance: purpose == 'advance'), ownerCurrent: widget.assistantOwnerCurrent);
          return;
        }
        final copy = await _chooseActionBill('Choose the bill paid', supplierId: supplier.id, acceptedOnly: true, paymentSelection: true);
        if (!mounted || !current() || copy == null) return;
        await _showSupplierMoneyEntry(context, session, _StoreSupplierMoneyTarget(supplierId: supplier.id, copy: copy), ownerCurrent: widget.assistantOwnerCurrent);
      } else if (action == 'refund') {
        await _chooseSupplierRefund(context, session, supplier.id, ownerCurrent: widget.assistantOwnerCurrent);
      } else if (action == 'return') {
        final receipt = await _chooseActionRecord<WorkspaceSupplierGoodsReceipt>('Choose received goods to return', [
          for (final receipt in ledger?.goodsReceipts.values ?? <WorkspaceSupplierGoodsReceipt>[])
            (receipt, receipt.reference, '${supplier.name} · ${_actionReceiptSummary(receipt)}'),
        ]);
        if (!mounted || !current() || receipt == null ||
            jsonEncode(session.workspaceSupplierLedger(supplier.id)?.goodsReceipts[receipt.id]?.toJson()) != jsonEncode(receipt.toJson())) { return; }
        await _showSupplierGoodsReturn(context, session, supplier.id, receipt, ownerCurrent: widget.assistantOwnerCurrent);
      } else if (ledger != null) {
        await _showSupplierStatement(context, session, ledger, ownerCurrent: widget.assistantOwnerCurrent, ownerChanges: widget.assistantOwnerChanges);
      } else {
        await _chooseActionRecord<String>('Supplier account unavailable', const []);
      }
      return;
    }
    final copy = await _chooseActionBill('Choose supplier bill',
      acceptedOnly: action == 'allocate' || action == 'credit' || action == 'match',
      paymentSelection: action == 'allocate' || action == 'credit',
      purposeGuide: action == 'allocate'
        ? 'Choose the bill for an existing payment, advance or bill credit.'
        : action == 'credit' ? 'Choose the bill covered by your supplier’s credit note.' : null);
    if (!mounted || !current() || copy == null) return;
    if (action == 'allocate') {
      await _showSupplierAllocation(context, session, copy, ownerCurrent: widget.assistantOwnerCurrent);
    } else if (action == 'credit') {
      await _showSupplierCredit(context, session, copy, ownerCurrent: widget.assistantOwnerCurrent);
    } else if (action == 'shortage') {
      await _showSupplierShortage(context, session, copy, ownerCurrent: widget.assistantOwnerCurrent);
    } else {
      setState(() => _savedCopy = copy);
    }
  }

  Future<WorkspacePurchaseSavedCopy?> _chooseActionBill(String title, {String? supplierId, bool acceptedOnly = false, bool editableOnly = false, bool paymentSelection = false, String? purposeGuide}) async {
    final scope = session.workspaceSupplierScope;
    final eligible = <(WorkspacePurchaseSavedCopy, String, String)>[
      for (final copy in session.workspaceLatestPurchaseCopies)
        if ((supplierId == null || copy.supplier.id == supplierId) && (!editableOnly ||
          jsonEncode(session.workspacePurchaseEntryDraft?.toJson()) == jsonEncode(copy.draft.toJson())) && (!acceptedOnly ||
          jsonEncode(session.workspaceSupplierLedger(copy.supplier.id)?.purchaseBills[copy.draft.id]?.copy.toJson()) == jsonEncode(copy.toJson())))
          (copy, '${copy.supplier.name} · ${copy.draft.invoiceReference}', '${copy.draft.invoiceDate} · Revision ${copy.revision}'),
    ];
    final copy = editableOnly && eligible.length == 1 ? eligible.single.$1
      : paymentSelection
      ? await showDialog<WorkspacePurchaseSavedCopy>(context: context, useSafeArea: true,
          builder: (paymentContext) => _purchaseCapturedOwnerPage(context, paymentContext, session, widget.assistantOwnerCurrent, _StorePaymentBillSelector(title: title,
            purposeGuide: purposeGuide ?? 'Choose the supplier bill you have paid.',
            supplierName: supplierId == null ? null
              : session.workspaceSuppliers.where((s) => s.id == supplierId).firstOrNull?.name ?? 'Supplier unavailable',
            copies: eligible.map((row) => row.$1).toList())))
      : await _chooseActionRecord<WorkspacePurchaseSavedCopy>(title, eligible);
    if (!mounted || scope != session.workspaceSupplierScope || copy == null ||
        !session.workspacePurchaseCopies.any((c) => jsonEncode(c.toJson()) == jsonEncode(copy.toJson()))) { return null; }
    if (acceptedOnly && jsonEncode(session.workspaceSupplierLedger(copy.supplier.id)?.purchaseBills[copy.draft.id]?.copy.toJson()) != jsonEncode(copy.toJson())) { return null; }
    return copy;
  }

  Future<void> _openActionCentre({bool readOnlyOpen = false}) async {
    _purchaseSearchFocus.unfocus();
    if (_centreVisible) { backWithinPurchases(); return; }
    if (_actionCentreOpen || _purchaseActionPending) return;
    final epoch = ++_centreEpoch;
    setState(() { _centreVisible = true; _actionCentreOpen = true; _expandedCategories.clear(); });
    try {
    final scope = session.workspaceSupplierScope;
    _receivingResumeIds.clear(); _receivingResumeUnknown = false;
    final recovered = readOnlyOpen ? session.workspaceInvoiceHistoryLoaded : await session.recoverCustomerLedger();
    if (!mounted || widget.assistantOwnerCurrent?.call() == false || epoch != _centreEpoch || scope != session.workspaceSupplierScope) return;
    _receivingResumeUnknown = !recovered;
    for (final supplier in session.workspaceSuppliers) {
      final key = session.supplierReceivingInputFormKey(supplier.id);
      if (key == null) continue;
      try {
        final draft = await session.readLedgerForm(key);
        if (!mounted || epoch != _centreEpoch || scope != session.workspaceSupplierScope) return;
        final fields = draft?.fields;
        if (fields == null || fields.isEmpty) continue;
        final arrival = fields['arrivalId'];
        if (!session.workspaceInvoiceHistoryLoaded) { _receivingResumeUnknown = true; continue; }
        if (session.workspaceSupplierLedger(supplier.id)?.goodsReceipts.containsKey(arrival) == true) continue;
        if (session.workspaceGoodsReceiptCancellations.any((c) => c.receiptId == arrival)) continue;
        final input = fields['input'] == null ? null : jsonDecode(fields['input']!);
        if (input is List && ((input.isNotEmpty && input.first is String && (input.first as String).trim().isNotEmpty) ||
            input.skip(2).any((v) => v is List && v.length > 1 && v[1] is String && (v[1] as String).isNotEmpty))) {
          _receivingResumeIds.add(supplier.id);
        }
      } on Object {
        if (!mounted || epoch != _centreEpoch || scope != session.workspaceSupplierScope) return;
        _receivingResumeUnknown = true;
      }
    }
    if (!mounted || epoch != _centreEpoch || scope != session.workspaceSupplierScope) return;
    } finally {
      if (mounted && epoch == _centreEpoch) setState(() => _actionCentreOpen = false);
    }
  }

  bool backWithinPurchases() {
    if (!_centreVisible && !_actionCentreOpen) return false;
    ++_centreEpoch;
    setState(() { _centreVisible = false; _actionCentreOpen = false; _expandedCategories.clear(); });
    return true;
  }

  // Returns true when an original inner surface handled Back, including a
  // refused dirty/pending leave. A refusal must never pop the outer AI route.
  Future<bool> _assistantBackWithin() async {
    final receiving = widget.receivingKey?.currentState;
    if (receiving != null) {
      final permitted = await receiving.confirmLeave();
      if (!permitted) return true;
      // A retired, proven-retained child may leave the outer route directly.
      // Its safe retired check is read-only; do not rebuild another old form.
      if (widget.assistantOwnerCurrent?.call() == false) return false;
      if (mounted) receiving.widget.onBack();
      return true;
    }
    final entry = widget.purchaseEntryKey?.currentState;
    if (entry != null) {
      if (await entry.confirmLeave() && mounted) entry.widget.onBack();
      return true;
    }
    if (session.focusedWorkspacePurchaseId != null) {
      session.clearWorkspacePurchaseSelection(); return true;
    }
    if (_purchaseActionPending || _actionCentreOpen) return true;
    return backWithinPurchases();
  }

  void cancelPendingAction() {
    if (!backWithinPurchases()) ++_centreEpoch;
  }

  Future<void> _selectPurchaseAction(String action) async {
    if (_purchaseActionPending || _actionCentreOpen || !_centreVisible) return;
    _purchaseActionPending = true;
    backWithinPurchases();
    try { await _purchaseAction(action); }
    finally { _purchaseActionPending = false; }
  }

  static (String, String) _categoryCopy(String id) => switch (id) {
    'Supplier bills' => ('Purchase invoices', 'Purchase entry, saved invoices and corrections.'),
    'Goods received & returns' => ('Goods receipt & returns', 'Goods inward, invoice matching and purchase returns.'),
    'Money paid, credit & refunds' => ('Payments & credits', 'Supplier payments, advances, credit notes and refunds.'),
    'Starting records' => ('Opening stock & balances', 'Stock and supplier balances when starting MoolSocial.'),
    _ => ('Supplier accounts & statements', 'Supplier ledger, account statements and invoice copies.'),
  };

  List<Widget> _actionCentreSlivers(double width, double height) => [
            SliverToBoxAdapter(child: SizedBox(
              height: _actionCentreOpen ? 2 : 0,
              child: _actionCentreOpen ? const LinearProgressIndicator() : null)),
            if (_receivingResumeUnknown) const SliverToBoxAdapter(child: Padding(padding: EdgeInsets.symmetric(horizontal: 16),
              child: Text('Saved delivery status needs checking. Open Receive goods to recover it.',
                style: TextStyle(fontSize: 12, color: MoolColors.ink)))),
            for (final category in _purchaseActions)
              SliverMainAxisGroup(key: ValueKey('purchase-category-group-${category.$1}'), slivers: [
                SliverPersistentHeader(pinned: _expandedCategories.contains(category.$1) &&
                  _categoryCanPin(width, height, category.$1, category.$2),
                  delegate: _PurchaseCategoryHeader(title: category.$1,
                    label: _categoryCopy(category.$1).$1, guide: _categoryCopy(category.$1).$2,
                    extent: _purchaseCategoryExtent(context, width, category.$1),
                    expanded: _expandedCategories.contains(category.$1), onChanged: (expanded) {
                      setState(() { if (expanded) { _expandedCategories.add(category.$1); }
                        else { _expandedCategories.remove(category.$1); } });
                    })),
                if (_expandedCategories.contains(category.$1)) SliverList.list(children: [
              for (final item in category.$2)
                if ((item.$1 != 'continue-bill' || (session.workspacePurchaseEntryDraft != null && !session.workspacePurchaseDraftReviewed)) &&
                    (item.$1 != 'continue-receive' || _receivingResumeIds.isNotEmpty))
                DecoratedBox(decoration: const BoxDecoration(border: Border(bottom: BorderSide(color: MoolColors.line, width: .5))),
                child: Semantics(label: _categoryCopy(category.$1).$1, child: ListTile(key: Key('purchase-action-${item.$1}'), title: Text(item.$2,
                  style: TextStyle(fontSize: 13, fontWeight: FontWeight.w500,
                    color: Theme.of(context).colorScheme.onSurface)),
                  contentPadding: const EdgeInsets.fromLTRB(24, 4, 16, 4),
                  subtitle: Text(item.$3, style: const TextStyle(fontSize: 12, height: 1.25, color: MoolColors.muted)),
                  trailing: const Icon(Icons.chevron_right, size: 20),
                  onTap: !_actionCentreOpen && !_purchaseActionPending && (session.workspaceSuppliersLoaded || item.$1 == 'record-bill' || item.$1 == 'continue-bill' || item.$1 == 'edit') && (item.$1 != 'stock' || widget.onOpenStock != null) &&
                    (item.$1 != 'record-bill' || session.workspacePurchaseEntryDraft == null || session.workspacePurchaseDraftReviewed)
                    ? () => unawaited(_selectPurchaseAction(item.$1)) : null))),
              ]),
              ]),
          ];

  double _purchaseCategoryExtent(BuildContext context, double width, String title) {
    final copy = _categoryCopy(title);
    final painter = TextPainter(text: TextSpan(text: copy.$1,
      style: (Theme.of(context).textTheme.bodyMedium ?? const TextStyle())
        .copyWith(fontSize: 14, fontWeight: FontWeight.w700, color: MoolColors.navy)),
      textDirection: Directionality.of(context), textScaler: MediaQuery.textScalerOf(context))
      ..layout(maxWidth: (width - 80).clamp(1, double.infinity));
    var textHeight = painter.height;
    if (!_expandedCategories.contains(title)) {
      painter.text = TextSpan(text: copy.$2,
        style: (Theme.of(context).textTheme.bodyMedium ?? const TextStyle())
          .copyWith(fontSize: 11, color: MoolColors.muted));
      painter.layout(maxWidth: (width - 80).clamp(1, double.infinity));
      textHeight += painter.height + 4;
    }
    final padding = _expandedCategories.contains(title) ? 16 : 20;
    final height = (textHeight + padding).clamp(48, double.infinity).toDouble() + 1;
    painter.dispose();
    return height;
  }

  bool _categoryCanPin(double width, double height, String title,
      List<(String, String, String)> actions) {
    double measure(String text, TextStyle style) {
      final painter = TextPainter(text: TextSpan(text: text, style: style),
        textDirection: Directionality.of(context), textScaler: MediaQuery.textScalerOf(context))
        ..layout(maxWidth: (width - 80).clamp(1, double.infinity));
      final result = painter.height;
      painter.dispose();
      return result;
    }
    final theme = Theme.of(context).textTheme;
    var tallest = 80.0;
    for (final action in actions) {
      if (action.$1 == 'continue-bill' &&
          (session.workspacePurchaseEntryDraft == null || session.workspacePurchaseDraftReviewed)) {
        continue;
      }
      if (action.$1 == 'continue-receive' && _receivingResumeIds.isEmpty) continue;
      final row = measure(action.$2, (theme.bodyLarge ?? const TextStyle())
          .copyWith(fontSize: 13, fontWeight: FontWeight.w500)) +
        measure(action.$3, (theme.bodyMedium ?? const TextStyle()).copyWith(fontSize: 12, height: 1.25)) + 24;
      if (row > tallest) tallest = row;
    }
    return _purchaseCategoryExtent(context, width, title) + tallest + 2 <= height;
  }

