  Future<void> _openSalesStatement() async {
    if (widget.reportCurrent?.call() == false) return;
    final session = widget.session;
    final scope = session.workspaceStockHistoryScope();
    if (scope == null || !session.workspaceInvoiceHistoryLoaded) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Sales records are not ready. Please retry after loading.')));
      return;
    }
    final now = DateTime.now(), today = DateUtils.dateOnly(DateTime.now());
    final from = switch (_invoicePeriod) {
      'Week' => DateTime(today.year, today.month, today.day - 6),
      'Month' => DateTime(today.year, today.month),
      'Year' => DateTime(today.year),
      'Custom range' => _invoiceRange?.start ?? today,
      _ => today,
    };
    final last = _invoicePeriod == 'Custom range' ? _invoiceRange?.end ?? today : today;
    try {
      final statement = StoreSalesStatement(accountId: scope.accountScope, storeId: scope.workspaceId,
        reviewOnly: const bool.fromEnvironment('MOOLSOCIAL_UI_REVIEW_ONLY'),
        storeName: session.activeWorkspace!.name, from: from,
        until: DateTime(last.year, last.month, last.day + 1), generatedAt: now,
        invoices: session.workspaceInvoices,
        finance: !session.workspaceFinanceStale && !session.workspaceFinanceUsesLegacyReview ? session.workspaceFinance : null);
      if (!mounted || widget.reportCurrent?.call() == false) return;
      await showModalBottomSheet<void>(context: context, isScrollControlled: true, useSafeArea: true,
        showDragHandle: false,
        builder: (sheetContext) => SizedBox(height: MediaQuery.sizeOf(sheetContext).height *
            (MediaQuery.orientationOf(sheetContext) == Orientation.landscape ? 1 : .78),
          child: StoreSalesStatementPanel(statement: statement,
            onClose: () => Navigator.pop(sheetContext),
            changes: Listenable.merge([session, widget.reportChanges]), isCurrent: () => mounted && widget.reportCurrent?.call() != false && session.workspaceStockHistoryScope()?.key == scope.key)));
    } on FormatException catch (e) {
      if (mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(e.message)));
    }
  }

  Widget _compactInvoices(WorkSession session, {Widget? salesPeriodControl, Widget? inlineSearch}) {
    final now = DateTime.now();
    final today = DateTime(now.year, now.month, now.day);
    final start = !widget.salesOnly
        ? session.workspaceMoneyPeriodStart
        : switch (_invoicePeriod) {
            'Week' => today.subtract(const Duration(days: 6)),
            'Month' => DateTime(now.year, now.month),
            'Year' => DateTime(now.year),
            'Custom range' => _invoiceRange?.start ?? today,
            _ => today,
          };
    final end = _invoicePeriod == 'Custom range' && _invoiceRange != null
        ? DateTime(
            _invoiceRange!.end.year,
            _invoiceRange!.end.month,
            _invoiceRange!.end.day + 1,
          )
        : DateTime(now.year, now.month, now.day + 1);
    final invoices =
        session.workspaceInvoices
            .where(
              (invoice) =>
                  (widget.preparedExchangeInvoiceId==null||invoice.id==widget.preparedExchangeInvoiceId) &&
                  (_returnSelection || start == null || !invoice.issuedAt.isBefore(start)) &&
                  (_returnSelection || invoice.issuedAt.isBefore(end)),
            )
            .toList()
          ..sort((a, b) {
            final date = widget.salesOnly
                ? b.issuedAt.compareTo(a.issuedAt)
                : a.issuedAt.compareTo(b.issuedAt);
            return date == 0 ? a.id.compareTo(b.id) : date;
          });
    final totalMinor = invoices.fold<int>(
      0,
      (sum, invoice) => sum + invoice.payableMinor,
    );
    if (widget.salesOnly) {
      final finance = session.workspaceFinance;
      final financeReady = finance != null && finance.valid && finance.historyComplete &&
          finance.workspaceId == session.activeWorkspace?.id &&
          !session.workspaceFinanceStale && !session.workspaceFinanceUsesLegacyReview &&
          !finance.asOf.isAfter(now);
      final payments = <(String, String?), List<WorkspacePaymentRecord>>{};
      if (financeReady) {
        for (final payment in finance.payments) {
          payments.putIfAbsent((payment.orderId, payment.invoiceId), () => []).add(payment);
        }
      }
      final query = _invoiceSearch.text.trim().toLowerCase();
      final matches = invoices.where((invoice) =>
        '${invoice.id} ${invoice.orderId} ${invoice.customer} ${invoice.billingDetails.name} ${invoice.billingDetails.businessName}'.toLowerCase().contains(query)).toList();
      return LayoutBuilder(builder: (context, viewport) => Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
        if (_returnSelection)
          ConstrainedBox(constraints: BoxConstraints(maxHeight: viewport.maxHeight * .45), child: SingleChildScrollView(child: Padding(padding: const EdgeInsets.symmetric(horizontal: 12),
            child: Row(children: [
              Expanded(child: Text(_exchangeSelection ? 'Exchange' : 'Returns & refunds · All saved sales',
                style: const TextStyle(fontSize: 12, fontWeight: FontWeight.w600))),
              if (_exchangeSelection) IconButton(tooltip: 'How exchange works',
                onPressed: () => _exchangeSteps(), icon: const Icon(Icons.info_outline, size: 18)),
              IconButton(tooltip: _salesManageBeforeReturns ? 'Back to Manage sales' : 'Back to sales register', onPressed: _toggleReturnSelection,
                icon: const Icon(Icons.close_rounded, size: 18)),
            ])))),
        if (!_returnSelection)
        ConstrainedBox(constraints: BoxConstraints(maxHeight: viewport.maxHeight * .45), child: SingleChildScrollView(child: Padding(
          key: const Key('work-sales-period-summary'),
          padding: const EdgeInsets.symmetric(horizontal: 12),
          child: Row(children: [
            if (inlineSearch != null) Expanded(flex: 2, child: inlineSearch),
            Expanded(flex: 5, child: Column(mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.stretch, children: [
            Wrap(alignment: WrapAlignment.spaceBetween, crossAxisAlignment: WrapCrossAlignment.center,
              spacing: 4, runSpacing: 0, children: [
                ?salesPeriodControl,
                Semantics(label: 'Billed sales for $_salesPeriodLabel', child: Column(
                  crossAxisAlignment: CrossAxisAlignment.end, mainAxisSize: MainAxisSize.min, children: [
                    const Text('Billed', style: TextStyle(fontSize: 11, color: MoolColors.muted)),
                    Text('₹${_formatStoreMinorAmount(totalMinor)}', key: const Key('work-sales-period-total'),
                      style: const TextStyle(fontSize: 14, fontWeight: FontWeight.w700, color: MoolColors.ink,
                        fontFeatures: [FontFeature.tabularFigures()])),
                  ])),
              ]),
            if (_invoicePeriod == 'Custom range')
              Padding(padding: const EdgeInsets.only(bottom: 4),
                child: Text(_salesPeriodLabel, style: const TextStyle(fontSize: 11, color: MoolColors.muted))),
          ])),
          ]),
        ))),
        Expanded(child: ListView.separated(
          key: PageStorageKey(('sales-invoices', _salesScope, _returnSelection, _invoicePeriod, _invoiceRange, query)),
          keyboardDismissBehavior: ScrollViewKeyboardDismissBehavior.onDrag,
          padding: const EdgeInsets.only(bottom: 12),
          itemCount: matches.isEmpty ? 1 : matches.length,
          separatorBuilder: (_, _) => const Divider(height: 1, thickness: .5),
          itemBuilder: (context, index) {
            if (matches.isEmpty) { return Padding(padding: const EdgeInsets.all(16),
              child: Text(_returnSelection
                ? (query.isEmpty ? 'No saved invoices available. A return needs the original sale.' : 'No matching sale. Check the invoice number, customer name or phone.')
                : query.isEmpty ? 'No recorded invoices in this period.' : 'No matching invoices in this period. Clear search or change the period.',
                style: const TextStyle(fontSize: 13, color: MoolColors.muted))); }
            final invoice = matches[index];
            final candidates = payments[(invoice.orderId, invoice.id)] ?? const <WorkspacePaymentRecord>[];
            final payment = candidates.length == 1 ? candidates.single : null;
            final status = payment == null ? 'Payment status unavailable'
                : payment.dueMinor > 0 && payment.state.label == 'Payment due'
                    ? 'Amount due ₹${_formatStoreMinorAmount(payment.dueMinor)}'
                    : '${payment.state.label}${payment.dueMinor > 0 ? ' · Due ₹${_formatStoreMinorAmount(payment.dueMinor)}' : ''}';
            final customer = _RecentCounterCustomer(invoice.customer, invoice.billingDetails);
            final pendingRefund = payment?.state == WorkspacePaymentState.refundPending;
            final refundLedger = payment == null ? null : finance?.customerLedgers.where((ledger) =>
              ledger.valid && ledger.accountScope == finance.accountScope &&
              ledger.workspaceId == finance.workspaceId && ledger.customerId == payment.customerId).firstOrNull;
            final availableRefund = refundLedger?.invoiceBalance(invoice.id)?.refundableMinor;
            final displayStatus = pendingRefund
                ? '$status · ${availableRefund != null ? 'Available refund ₹${_formatStoreMinorAmount(availableRefund)}' : 'Refund amount unavailable'}'
                : status;
            final details = Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              Text(customer.mobile != null && customer.label == invoice.customer
                  ? 'Phone: ${invoice.customer}' : customer.label,
                style: const TextStyle(fontSize: 13, fontWeight: FontWeight.w600, color: MoolColors.ink)),
              Text(_registerDate(invoice.issuedAt),
                style: const TextStyle(fontSize: 11, color: MoolColors.muted)),
            ]);
            final amount = Column(crossAxisAlignment: CrossAxisAlignment.end, children: [
              const Text('Bill total', style: TextStyle(fontSize: 10, color: MoolColors.muted)),
              Text('₹${_formatStoreMinorAmount(invoice.payableMinor)}', textAlign: TextAlign.right,
              style: const TextStyle(fontSize: 13, fontWeight: FontWeight.w600, color: MoolColors.ink,
                fontFeatures: [FontFeature.tabularFigures()])),
            ]);
            return InkWell(
              key: ValueKey('work-sales-invoice-${invoice.id}'),
              onTap: () { FocusScope.of(context).unfocus();
                if (_returnSelection && payment != null) {
                  if (_exchangeSelection) { _openExchange(invoice, payment); return; }
                  _StoreInvoiceSurfaceState.openAdjustments(context, session, invoice, payment,
                    finance?.accountScope, session.activeWorkspace?.id);
                  return;
                }
                if (_returnSelection) {
                  ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:
                    Text('Payment records unavailable. Open the original invoice and recover its records before recording a return.')));
                }
                _openSalesInvoice(invoice); },
              child: Padding(padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),
                child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
                LayoutBuilder(builder: (context, box) =>
                  MediaQuery.textScalerOf(context).scale(13) > 19.5 || box.maxWidth < 300
                  ? Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [details, const SizedBox(height: 4), amount])
                  : Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
                      Expanded(flex: 3, child: details), const SizedBox(width: 12), Expanded(flex: 2, child: amount),
                    ])),
                Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
                  Expanded(child: Semantics(label: 'Invoice No.: ${invoice.id}', excludeSemantics: true,
                    child: Tooltip(message: 'Invoice No.: ${invoice.id}', excludeFromSemantics: true,
                    triggerMode: TooltipTriggerMode.longPress,
                    child: Text(invoice.id.length > 20 ? 'Ref …${invoice.id.substring(invoice.id.length - 12)}' : invoice.id,
                      key: ValueKey('work-sales-reference-${invoice.id}'),
                      maxLines: 1, overflow: TextOverflow.ellipsis,
                      style: const TextStyle(fontSize: 10, color: MoolColors.muted))))),
                  const Icon(Icons.chevron_right_rounded, size: 18, color: MoolColors.navy),
                ]),
                Row(children: [
                  if (pendingRefund) ...[
                    const Icon(Icons.schedule_rounded, size: 14, color: MoolColors.navy),
                    const SizedBox(width: 4),
                  ],
                  Expanded(child: Text(displayStatus, key: ValueKey('work-sales-status-${invoice.id}'),
                    style: TextStyle(fontSize: 11, fontWeight: pendingRefund ? FontWeight.w600 : FontWeight.w400,
                      color: pendingRefund || (payment != null && payment.dueMinor > 0) ? MoolColors.navy : MoolColors.muted))),
                ]),
              ])),
            );
          },
        )),
      ]));
    }
    final register = _StoreVoucherRegister(
      identity: (
        'sales',
        session.workspaceStockHistoryScope()?.key,
        widget.salesOnly ? _invoicePeriod : session.workspaceMoneyPeriod,
      ),
      headers: const [
        'Date',
        'Particulars',
        'Voucher Type',
        'Voucher No.',
        'Amount (₹)',
      ],
      rows: [
        for (final invoice in invoices)
          [
            _registerDate(invoice.issuedAt),
            invoice.customer,
            'Sales',
            invoice.id,
            _formatStoreMinorAmount(invoice.payableMinor),
          ],
      ],
      rowKeys: [
        for (final invoice in invoices)
          ValueKey('work-sales-invoice-${invoice.id}'),
      ],
      amountColumns: const {4},
      total: _formatStoreMinorAmount(totalMinor),
      notice: 'Recorded invoices only · not a customer balance statement',
      empty: 'No recorded invoices in this period.',
      onOpen: (index) => _openSalesInvoice(invoices[index]),
    );
    return register;
  }

  @override
  Widget build(BuildContext context) {
    final session = widget.session;
    final salesScope = session.workspaceStockHistoryScope()?.key ?? session.activeWorkspace?.id;
    if (widget.counterContent == null) return _buildSalesContent(context);
    if (_salesScope != salesScope) {
      _salesHubView = _salesScope == null ? widget.initialSalesTask : 'home';
      _buildSalesContent(context);
    }
    return Material(color: Colors.white,
      child: IndexedStack(sizing: StackFit.expand,
        index: _salesHubView == 'counter' ? 0 : 1, children: [
        ExcludeFocus(excluding: _salesHubView != 'counter',
          child: TickerMode(enabled: _salesHubView == 'counter', child: widget.counterContent!)),
        Column(key: const Key('work-sales-content'),
          children: [
          Expanded(child: _StockQuickActionsFrame(
            keyPrefix: 'work-sales-navigation', enabled: _salesHubView == 'home',
            expanded: _salesNavigationExpanded,
            onToggle: () => setState(() => _salesNavigationExpanded = !_salesNavigationExpanded),
            actions: [
          for (final route in const [
            (view: 'counter', key: 'work-sales-primary-counter-sale', label: 'Counter sale',
              icon: Icons.point_of_sale_outlined),
            (view: 'manage', key: 'work-sales-manage', label: 'Manage sales',
              icon: Icons.tune_rounded),
            (view: 'records', key: 'work-sales-recorded', label: 'Recorded sales',
              icon: Icons.receipt_long_outlined),
          ]) _StoreEdgeAction(keyName: route.key, label: route.label, icon: route.icon,
            selected: route.view == 'records',
            onTap: () => unawaited(_selectSalesHubView(route.view))),
        ], child: _salesHubView == 'counter' ? const SizedBox.shrink() : _buildSalesContent(context))),
          if (_salesHubView == 'home') const SizedBox.shrink(key: Key('work-sales-home')),
        ]),
      ]));
  }

  void showSalesHome() {
    setState(() { _salesHubView = 'home'; _salesManageOpen = false; });
    widget.onSalesTaskChanged?.call(null);
  }

  Future<void> _selectSalesHubView(String view) async {
    if (_changingSalesHubView) return;
    _changingSalesHubView = true;
    final scope = (widget.session.activeWorkspace?.id, widget.session.workspaceFinance?.accountScope);
    final origin = _salesHubView;
    bool current() => mounted && _salesHubView == origin &&
        scope == (widget.session.activeWorkspace?.id, widget.session.workspaceFinance?.accountScope);
    FocusScope.of(context).unfocus();
    try {
      if (!(await (widget.beforeSalesViewChange?.call() ?? Future.value(true))) || !current()) {
        return;
      }
      if (view == 'counter' &&
          (!(await (widget.onPrepareCounter?.call(current) ?? Future.value(true))) || !current())) {
        return;
      }
      setState(() {
        _salesHubView = view == 'records' ? 'home' : view;
        _selectedInvoice = null;
        _returnSelection = false;
        _exchangeSelection = false;
        _salesManageOpen = view == 'manage';
        if (view == 'manage') _salesCategories.addAll({0, 1, 2, 3, 4});
      });
      widget.onSalesTaskChanged?.call(view == 'records' ? null : view);
    } finally { _changingSalesHubView = false; }
  }

  Widget _buildSalesContent(BuildContext context) {
    final session = widget.session;
    final salesScope = session.workspaceStockHistoryScope()?.key ?? session.activeWorkspace?.id;
    if (_salesScope != salesScope) {
      _salesScope = salesScope;
      _invoiceSearch.clear();
      _returnSelection = false;
      _exchangeSelection = false;
      _salesQueryBeforeReturns = '';
      _salesManageOpen = widget.counterContent != null && _salesHubView == 'manage';
      _salesManageBeforeReturns = false;
      _salesCategories.clear();
      if (_salesManageOpen) _salesCategories.addAll({0, 1, 2, 3, 4});
      _salesActionsExpanded = true;
      _invoicePeriod = 'Today';
      _invoiceRange = null;
      final saved = PageStorage.maybeOf(context)?.readState(context, identifier: ('sales-browse', _salesScope));
      if (saved is ({String query, String period, DateTimeRange? range, bool expanded})) {
        _invoiceSearch.text = saved.query;
        _invoicePeriod = saved.period;
        _invoiceRange = saved.range;
        _salesActionsExpanded = saved.expanded;
      }
      if(widget.preparedExchangeInvoiceId!=null){
        _returnSelection=true;_exchangeSelection=true;_salesManageOpen=false;
        _invoiceSearch.text=widget.preparedExchangeInvoiceId!;
      }
      if (!_reportStatementPrepared && widget.initialReport != null && widget.reportCurrent?.call() != false) {
        _reportStatementPrepared = true;
        final fields = widget.initialReport!.fields;
        if (fields['period'] != null) _invoicePeriod = fields['period'] as String;
        if (_invoicePeriod == 'Custom range' && fields['from'] != null && fields['to'] != null) {
          _invoiceRange = DateTimeRange(start: DateTime.parse(fields['from'] as String), end: DateTime.parse(fields['to'] as String));
        }
        WidgetsBinding.instance.addPostFrameCallback((_) {
          if (mounted && widget.reportCurrent?.call() != false) unawaited(_openSalesStatement());
        });
      }
    }
    if (_selectedInvoice != null) {
      if (session.activeWorkspace?.id != _invoiceStoreScope ||
          session.workspaceFinance?.accountScope != _invoiceAccountScope) {
        _selectedInvoice = null;
      } else {
        return _StoreInvoiceSurface(
          key: ValueKey(_selectedInvoice!.id),
          session: session,
          invoice: _selectedInvoice!,
          embedded: true,
          salesPresentation: widget.salesOnly,
          onClose: () { closeSelectedInvoice(); },
        );
      }
    }
    final largeText = MediaQuery.textScalerOf(context).scale(14) > 21;
    final titleText = Text(
      widget.salesOnly || _book == 'Sales'
          ? 'Sales Register'
          : _book == 'Purchases'
          ? 'Purchase records'
          : _book == 'Expenses'
          ? 'Expense Register'
          : 'Cash / Bank Book',
      style: TextStyle(
        fontSize: 16,
        fontWeight: FontWeight.w800,
        color: MoolColors.navy,
      ),
    );
    final title = titleText;
    final periodControl = PopupMenuButton<String>(
      key: const Key('work-statement-period'),
      tooltip: widget.salesOnly ? 'Sales period · $_salesPeriodLabel' : 'Statement period',
      onSelected: (period) async {
        if (widget.salesOnly) {
          if (period == 'Custom range') {
            final range = await showDateRangePicker(
              context: context,
              firstDate: DateTime(2000),
              lastDate: DateTime.now(),
              initialDateRange: _invoiceRange,
              calendarDelegate: const _StoreDayFirstCalendarDelegate(),
              errorFormatText: 'Use DD/MM/YYYY',
              helpText: MediaQuery.orientationOf(context) == Orientation.landscape &&
                      MediaQuery.textScalerOf(context).scale(1) > 1.3
                  ? 'DD/MM/YYYY'
                  : 'Dates · DD/MM/YYYY',
              fieldStartLabelText: 'From',
              fieldEndLabelText: 'To',
              fieldStartHintText: '',
              fieldEndHintText: '',
              builder: (pickerContext, picker) {
                if (MediaQuery.orientationOf(pickerContext) != Orientation.landscape ||
                    MediaQuery.textScalerOf(pickerContext).scale(1) <= 1.3) {
                  return picker!;
                }
                final theme = Theme.of(pickerContext);
                return Theme(
                  data: theme.copyWith(
                    textTheme: theme.textTheme.copyWith(
                      headlineSmall: theme.textTheme.headlineSmall?.copyWith(fontSize: 14)),
                    datePickerTheme: theme.datePickerTheme.copyWith(
                    headerHelpStyle: (theme.datePickerTheme.headerHelpStyle ??
                        theme.textTheme.labelLarge)?.copyWith(fontSize: 11),
                  )),
                  child: picker!,
                );
              },
            );
            if (!mounted || range == null) return;
            _changeSalesBrowse(() {
              _invoicePeriod = period;
              _invoiceRange = range;
            });
          } else {
            _changeSalesBrowse(() => _invoicePeriod = period);
          }
          return;
        }
        if (_book == 'Purchases') {
          session.clearWorkspacePurchaseSelection();
        }
        session.setWorkspaceMoneyPeriod(period);
      },
      itemBuilder: (_) => [
        for (final period
            in widget.salesOnly
                ? ['Today', 'Week', 'Month', 'Year', 'Custom range']
                : ['Today', 'Week', 'Month', 'Financial year'])
          PopupMenuItem(value: period, child: Text(period)),
      ],
      child: Padding(
        padding: widget.salesOnly
            ? const EdgeInsets.symmetric(horizontal: 4, vertical: 14)
            : const EdgeInsets.all(12),
        child: Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            Text(
              widget.salesOnly
                  ? (_invoicePeriod == 'Custom range' ? 'Dates' : _salesPeriodLabel)
                  : session.workspaceMoneyPeriod,
              style: const TextStyle(
                color: MoolColors.navy,
                fontWeight: FontWeight.w700,
              ),
            ),
            const Icon(Icons.expand_more_rounded, size: 18),
          ],
        ),
      ),
    );
    if (widget.salesOnly) {
      final hasDraft = session.workspaceOrderSource == 'Counter' &&
          session.workspaceOrderFulfilment == 'At the shop' && session.currentWorkspaceOrderId == null &&
          (session.workspaceOrderCustomer.trim().isNotEmpty || session.workspaceOrderQuantities.isNotEmpty);
      if (_salesManageOpen) return _salesActionCentre(hasDraft);
      final landscapeBand = !_returnSelection &&
          MediaQuery.sizeOf(context).width >= 700 &&
          MediaQuery.sizeOf(context).height <= 450 &&
          MediaQuery.textScalerOf(context).scale(1) <= 1.3;
      final searchControl = StoreRecentSearches(
            controller: _invoiceSearch,
            history: session.workspaceRecentSearches(_exchangeSelection ? 'sales-exchange' : _returnSelection ? 'sales-returns' : 'sales'),
            isCurrent: () => _salesScope == (session.workspaceStockHistoryScope()?.key ?? session.activeWorkspace?.id),
            onChanged: (_) => _changeSalesBrowse(() {}),
            child: Row(children: [
              Expanded(child: TextField(
                key: const Key('work-sales-search'), controller: _invoiceSearch,
                textInputAction: TextInputAction.search,
                onChanged: (_) => _changeSalesBrowse(() {}),
                onSubmitted: (_) => FocusScope.of(context).unfocus(),
                style: const TextStyle(fontSize: 13, color: MoolColors.ink),
                decoration: InputDecoration(
                  hintText: _returnSelection ? 'Search phone, name or invoice'
                      : landscapeBand ? 'Search sales' : 'Search invoices or customers',
                  hintMaxLines: _returnSelection ? 3 : 1, filled: false, isDense: true,
                  border: InputBorder.none, enabledBorder: InputBorder.none, focusedBorder: InputBorder.none,
                  disabledBorder: InputBorder.none, errorBorder: InputBorder.none, focusedErrorBorder: InputBorder.none,
                  contentPadding: EdgeInsets.symmetric(vertical: _returnSelection ? 6 : 12),
                  fillColor: Colors.transparent, focusColor: Colors.transparent, hoverColor: Colors.transparent,
                  prefixIcon: const Icon(Icons.search_rounded, size: 21, color: MoolColors.navy),
                  suffixIcon: _invoiceSearch.text.isEmpty ? null : IconButton(
                    tooltip: 'Clear invoice search', onPressed: () => _changeSalesBrowse(_invoiceSearch.clear),
                    icon: const Icon(Icons.close_rounded, size: 18)),
                ),
              )),
            ]),
          );
      return ColoredBox(color: Colors.white, child: LayoutBuilder(builder: (context, viewport) => Column(key: const Key('work-store-statement'), children: [
          if (!landscapeBand) ConstrainedBox(
            constraints: BoxConstraints(maxHeight: viewport.maxHeight * .4),
            child: SingleChildScrollView(child: searchControl)),
          if (!_returnSelection && widget.counterContent == null)
            Align(alignment: Alignment.centerLeft, child: Padding(
              padding: const EdgeInsets.symmetric(horizontal: 12),
              child: Wrap(spacing: 8, crossAxisAlignment: WrapCrossAlignment.center, children: [
                if (widget.showNewSaleAction)
                  FilledButton.icon(key: const Key('work-sales-primary-counter-sale'),
                    style: FilledButton.styleFrom(minimumSize: const Size(48, 48),
                      padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),
                      backgroundColor: MoolColors.navy, foregroundColor: Colors.white,
                      textStyle: const TextStyle(fontSize: 13, fontWeight: FontWeight.w600),
                      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(7))),
                    onPressed: widget.onNewSale == null ? null : () {
                      FocusScope.of(context).unfocus();
                      widget.onNewSale!();
                    },
                    icon: Icon(hasDraft ? Icons.play_arrow_rounded : Icons.point_of_sale_rounded, size: 18),
                    label: Text(hasDraft ? 'Resume sale' : 'Counter sale')),
                TextButton.icon(key: const Key('work-sales-manage'),
                  style: TextButton.styleFrom(minimumSize: const Size(48, 48),
                    padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 8),
                    foregroundColor: MoolColors.navy,
                    textStyle: const TextStyle(fontSize: 12, fontWeight: FontWeight.w600)),
                  onPressed: () { FocusScope.of(context).unfocus(); setState(() => _salesManageOpen = true); },
                  icon: const Icon(Icons.more_horiz_rounded, size: 18), label: const Text('Manage sales')),
              ]))),
          if (widget.counterContent == null && !_returnSelection && !landscapeBand) const Align(alignment: Alignment.centerLeft,
            child: Padding(padding: EdgeInsets.symmetric(horizontal: 12, vertical: 4),
              child: Text('Recorded sales', style: TextStyle(fontSize: 14, fontWeight: FontWeight.w600)))),
          Expanded(child: _compactInvoices(session, salesPeriodControl: periodControl,
            inlineSearch: landscapeBand ? searchControl : null)),
        ])));
    }
    final content = Column(
      key: const Key('work-store-statement'),
      children: [
        if (_book != 'Purchases' || session.focusedWorkspacePurchaseId == null)
          Padding(
            padding: const EdgeInsets.fromLTRB(16, 12, 12, 4),
            child: largeText
                ? Align(
                    alignment: Alignment.centerLeft,
                    child: Wrap(
                      spacing: 8,
                      crossAxisAlignment: WrapCrossAlignment.center,
                      children: [
                        title,
                        periodControl,
                      ],
                    ),
                  )
                : _StoreScaledPair(
                    flexibleSecond: false,
                    first: title,
                    second: periodControl,
                  ),
          ),
        if (!widget.salesOnly)
          SafeArea(
            top: false,
            child: Padding(
              padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 0),
              child: LayoutBuilder(
                builder: (context, constraints) => SingleChildScrollView(
                  scrollDirection: Axis.horizontal,
                  child: ConstrainedBox(
                    constraints: BoxConstraints(minWidth: constraints.maxWidth),
                    child: Row(
                      mainAxisAlignment: MainAxisAlignment.spaceEvenly,
                      children: [
                        for (final book in [
                          'Sales',
                          'Purchases',
                          'Expenses',
                          'Money',
                        ])
                          TextButton(
                            key: Key('work-statement-${book.toLowerCase()}'),
                            onPressed: _book == book
                                ? null
                                : () {
                                    session.clearWorkspacePurchaseSelection();
                                    setState(() => _book = book);
                                  },
                            style: TextButton.styleFrom(
                              backgroundColor: _book == book
                                  ? const Color(0xFFECEFFF)
                                  : null,
                              disabledForegroundColor: MoolColors.navy,
                              minimumSize: const Size(48, 48),
                            ),
                            child: Text(
                              book,
                              style: const TextStyle(fontSize: 12),
                            ),
                          ),
                      ],
                    ),
                  ),
                ),
              ),
            ),
          ),
        if (!widget.salesOnly && _book == 'Money' && widget.onBusinessFinance != null)
          Align(alignment: Alignment.centerLeft, child: TextButton.icon(
            key: const Key('work-business-finance-open'),
            onPressed: widget.onBusinessFinance,
            icon: const Icon(Icons.account_balance_outlined, size: 18),
            label: const Text('Business finance'),
          )),
        Expanded(
          child: KeyedSubtree(
            // Keep each ledger's place without sharing offsets across Stores,
            // accounts, periods or the review/confirmed data boundary.
            key: PageStorageKey((
              'store-statement',
              session.workspaceStockHistoryScope()?.key ??
                  (session, session.activeWorkspace?.id),
              session.workspaceMoneyPeriod,
              _book,
              session.workspaceFinanceUsesLegacyReview,
            )),
            child:
                _book == 'Sales'
                ? _compactInvoices(session)
                : _book == 'Purchases'
                ? _StorePurchasesSurface(session: session, statement: true)
                : _book == 'Money'
                ? _StoreExpensesSurface(
                    key: ValueKey((
                      session.workspaceStockHistoryScope()?.key,
                      'money',
                    )),
                    session: session,
                    statement: true,
                  )
                : !widget.salesOnly && _book == 'Expenses'
                ? _StoreExpensesSurface(session: session, register: true)
                : !session.workspaceFinanceUsesLegacyReview
                ? _StoreFinanceSurface(
                    session: session,
                    section: _book == 'Sales' ? 'payments' : 'expenses',
                    onOpenInvoice: (invoice) => setState(() {
                      _selectedInvoice = invoice;
                      _invoiceStoreScope = session.activeWorkspace?.id;
                      _invoiceAccountScope =
                          session.workspaceFinance?.accountScope;
                    }),
                  )
                : _StoreExpensesSurface(session: session),
          ),
        ),
      ],
    );
    return LayoutBuilder(
      builder: (context, constraints) {
        final minimumHeight = largeText ? 480.0 : 240.0;
        if (constraints.maxHeight >= minimumHeight) {
          return content;
        }
        return SingleChildScrollView(
          child: SizedBox(height: minimumHeight, child: content),
        );
      },
    );
  }
}

String _registerDate(DateTime value) {
  final date = value.toLocal();
  return '${date.day.toString().padLeft(2, '0')}/${date.month.toString().padLeft(2, '0')}/${date.year}';
}

// Register totals are sums of recorded vouchers, never inferred ledger balances.
class _StoreVoucherRegister extends StatefulWidget {
  const _StoreVoucherRegister({
    required this.identity,
    required this.headers,
    required this.rows,
    required this.total,
    required this.notice,
    required this.empty,
    this.rowKeys = const [],
    this.amountColumns = const {},
    this.onOpen,
    this.openableRows,
    this.footer,
  });
  final Object identity;
  final List<String> headers;
  final List<List<String>> rows;
  final List<Key> rowKeys;
  final String total, notice, empty;
  final Set<int> amountColumns;
  final ValueChanged<int>? onOpen;
  final Set<int>? openableRows;
  final List<String>? footer;
  @override
  State<_StoreVoucherRegister> createState() => _StoreVoucherRegisterState();
}

class _StoreVoucherRegisterState extends State<_StoreVoucherRegister> {
  final horizontal = ScrollController();
  @override
  void dispose() {
    horizontal.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final scale = MediaQuery.textScalerOf(context).scale(12) / 12;
    final widths = [
      for (var i = 0; i < widget.headers.length; i++)
        (i == 0
                ? 100.0
                : i == 1
                ? 180.0
                : 150.0) *
            scale,
    ];
    Widget row(List<String> cells, {bool heading = false, Key? entryKey}) =>
        Row(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            for (var i = 0; i < cells.length; i++)
              SizedBox(
                key: i == 0 ? entryKey : null,
                width: widths[i],
                child: Padding(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 8,
                    vertical: 10,
                  ),
                  child: Text(
                    cells[i],
                    textAlign: widget.amountColumns.contains(i)
                        ? TextAlign.right
                        : TextAlign.left,
                    style: TextStyle(
                      fontSize: 12,
                      color: MoolColors.navy,
                      fontWeight: heading ? FontWeight.w700 : FontWeight.w400,
                    ),
                  ),
                ),
              ),
          ],
        );
    return Column(
      key: const Key('work-voucher-register'),
      children: [
        Expanded(
          child: Scrollbar(
            controller: horizontal,
            thumbVisibility: true,
            child: SingleChildScrollView(
              controller: horizontal,
              scrollDirection: Axis.horizontal,
              child: SizedBox(
                width: widths.fold<double>(0, (a, b) => a + b),
                child: ListView.builder(
                  key: PageStorageKey(('voucher-register', widget.identity)),
                  itemCount: widget.rows.length + 2,
                  itemBuilder: (_, position) {
                    if (position == 0) {
                      return ColoredBox(
                        color: const Color(0xFFF0F3FF),
                        child: row(widget.headers, heading: true),
                      );
                    }
                    if (position == widget.rows.length + 1) {
                      return Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          if (widget.rows.isEmpty)
                            Padding(
                              padding: const EdgeInsets.all(16),
                              child: Text(widget.empty),
                            ),
                          const Divider(height: 1),
                          row(
                            widget.footer ??
                                [
                                  for (
                                    var i = 0;
                                    i < widget.headers.length;
                                    i++
                                  )
                                    i == 1
                                        ? 'Recorded total'
                                        : i == widget.headers.length - 1
                                        ? widget.total
                                        : '',
                                ],
                            heading: true,
                          ),
                        ],
                      );
                    }
                    final index = position - 1;
                    return Material(
                      color: index.isEven
                          ? Colors.white
                          : const Color(0xFFF8F9FC),
                      child: InkWell(
                        onTap: widget.onOpen == null || widget.openableRows?.contains(index)==false
                            ? null
                            : () => widget.onOpen!(index),
                        child: ConstrainedBox(
                          constraints: const BoxConstraints(minHeight: 48),
                          child: Tooltip(
                            message: widget.notice,
                            child: row(
                              widget.rows[index],
                              entryKey: index < widget.rowKeys.length
                                  ? widget.rowKeys[index]
                                  : null,
                            ),
                          ),
                        ),
                      ),
                    );
                  },
                ),
              ),
            ),
          ),
        ),
      ],
    );
  }
}

