          const _DeskEmpty(
            icon: Icons.task_alt_rounded,
            title: 'No customer dues recorded',
            detail:
                'Unpaid invoices appear here. View paid invoices in Statement.',
          ),
        for (final customer in customers) ...[
          _StoreMoneyLine(
            leading: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  customer.name,
                  style: const TextStyle(
                    fontSize: 15,
                    fontWeight: FontWeight.w800,
                  ),
                ),
                Text(
                  customer.mobile,
                  style: const TextStyle(fontSize: 12, color: MoolColors.muted),
                ),
              ],
            ),
            value: '₹${_formatStoreMinorAmount(customer.amountDueMinor)}',
            style: const TextStyle(
              fontSize: 18,
              fontWeight: FontWeight.w800,
              color: MoolColors.navy,
            ),
          ),
          const SizedBox(height: 10),
          for (final order in customer.orders.where(
            (order) => order.payment.toLowerCase().contains('due'),
          ))
            Padding(
              padding: const EdgeInsets.symmetric(vertical: 6),
              child: _ProductPreviewLine(
                label: '${order.id} · ${order.payment}',
                value: '₹${_formatStoreMinorAmount(order.payableMinor)}',
              ),
            ),
          Align(
            alignment: Alignment.centerLeft,
            child: TextButton.icon(
              onPressed: () => onOpenRoute(
                Uri(
                  path: '/app/chat/inbox',
                  queryParameters: {
                    'type': 'business',
                    'recipient': customer.mobile,
                    'draft':
                        'Hello ${customer.name}, your recorded balance with ${session.activeWorkspace?.name ?? session.workName} is ₹${_formatStoreMinorAmount(customer.amountDueMinor)}. Please contact us if anything needs correcting.',
                  },
                ).toString(),
              ),
              icon: const Icon(Icons.chat_bubble_outline_rounded, size: 18),
              label: const Text('Discuss balance'),
            ),
          ),
          const Divider(height: 24),
        ],
      ],
    );
  }
}

class _StoreDirectSurface extends StatelessWidget {
