}

class _OperationActionCard extends StatelessWidget {
  const _OperationActionCard({
    required this.icon,
    required this.title,
    required this.detail,
    this.keyName,
    this.actionLabel,
    this.onPressed,
  });

  final String? keyName;
  final IconData icon;
  final String title;
  final String detail;
  final String? actionLabel;
  final VoidCallback? onPressed;

  @override
  Widget build(BuildContext context) {
    return WorkCard(
      keyName: keyName,
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          CircleAvatar(
            backgroundColor: const Color(0xFFEAF2FF),
            foregroundColor: MoolColors.navy,
            child: Icon(icon),
          ),
          const SizedBox(width: MoolSpacing.sm),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  title,
                  style: const TextStyle(
                    color: MoolColors.ink,
                    fontWeight: FontWeight.w900,
                  ),
                ),
                const SizedBox(height: 3),
                Text(
                  detail,
                  style: const TextStyle(
                    color: MoolColors.muted,
                    fontSize: 10.5,
                    height: 1.3,
                  ),
                ),
                if (actionLabel != null && onPressed != null) ...[
                  const SizedBox(height: MoolSpacing.xs),
                  FilledButton.tonalIcon(
                    onPressed: onPressed,
                    icon: const Icon(Icons.arrow_forward_rounded, size: 17),
                    label: Text(actionLabel!),
                  ),
                ],
              ],
            ),
          ),
        ],
      ),
    );
  }
}

class _WorkspaceCatalogueSurface extends StatefulWidget {
  const _WorkspaceCatalogueSurface({
    required this.session,
    this.entryOnly = false,
    this.ownerCurrent,
    this.actionsExpanded,
    this.onToggleActions,
    this.onBuyStock,
    this.onPurchases,
    this.onGroupBuying,
    this.onStatement,
    super.key,
  });

  final WorkSession session;
  final bool entryOnly;
  final bool Function()? ownerCurrent;
  final bool? actionsExpanded;
  final VoidCallback? onToggleActions;
  final VoidCallback? onBuyStock, onPurchases, onGroupBuying, onStatement;

  @override
  State<_WorkspaceCatalogueSurface> createState() =>
      _WorkspaceCatalogueSurfaceState();
}

class _WorkspaceCatalogueSurfaceState
    extends State<_WorkspaceCatalogueSurface> {
  final _stockActionKeys = <String, GlobalKey>{};
  final Set<Object> _localCollapsedActions = {};
  Object get _actionScope =>
      widget.session.workspaceStockHistoryScope()?.key ??
      widget.session.activeWorkspace?.id ??
      widget.session.workspaceId ??
      widget.session;
  bool get _actionsExpanded =>
      widget.actionsExpanded ?? !_localCollapsedActions.contains(_actionScope);
  void _toggleActions() {
    unawaited(HapticFeedback.selectionClick());
    if (widget.onToggleActions case final toggle?) {
      toggle();
    } else {
      setState(() {
        if (!_localCollapsedActions.remove(_actionScope)) {
          _localCollapsedActions.add(_actionScope);
        }
      });
    }
  }

  bool _retryingInventory = false;

  bool get _stockNeedsRecovery => !widget.session.workspaceInventoryLoaded &&
      (widget.session.localInventoryEnabled || widget.session.workspaceInventoryError != null ||
        widget.session.workspaceCatalogueItems.isEmpty);

  Future<void> _retryInventory(WorkSession owner, Object scope, int? navigation) async {
    bool current() => mounted && identical(widget.session, owner) &&
        owner.tradingPreferencesContext == scope && owner.navigationScopeRevision == navigation;
    if (_retryingInventory || !current()) return;
    setState(() => _retryingInventory = true);
    try {
      if (await owner.loadWorkspaceInventory(retry: true) && current()) {
        await owner.retryWorkspaceInventorySave();
      }
    } finally {
      if (mounted) setState(() => _retryingInventory = false);
    }
  }

  Widget _inventoryStatusCard({required bool recovery}) {
    final owner = widget.session, error = owner.workspaceInventoryError;
    final scope = owner.tradingPreferencesContext, navigation = owner.navigationScopeRevision;
    final title = recovery ? (error == null ? 'Stock not loaded' : 'Stock unavailable') : 'Stock changes not saved';
    final detail = error == 'Saved stock could not be recovered. Retry without clearing Store data.'
        ? 'Try again without clearing Store data.'
        : error ?? 'Load saved stock before searching or adding products.';
    final label = recovery
        ? (_retryingInventory ? (error == null ? 'Loading…' : 'Recovering…') : (error == null ? 'Load stock' : 'Recover stock'))
        : (_retryingInventory ? 'Saving…' : 'Retry stock save');
    return WorkCard(
      keyName: error == null ? 'store-inventory-load-status' : 'store-inventory-save-error',
      padding: const EdgeInsets.all(12),
      child: Column(
        key: Key(recovery ? 'work-stock-recovery-panel' : 'work-stock-save-panel'),
        crossAxisAlignment: CrossAxisAlignment.stretch,
        mainAxisSize: MainAxisSize.min,
        children: [
          Row(children: [
            const Icon(Icons.inventory_2_outlined, size: 20, color: MoolColors.muted),
            const SizedBox(width: 8),
            Expanded(child: Semantics(header: true, child: Text(title,
              style: const TextStyle(fontSize: 14, height: 1.25, fontWeight: FontWeight.w700, color: MoolColors.ink)))),
          ]),
          const SizedBox(height: 8),
          Align(alignment: Alignment.centerLeft, child: FilledButton.icon(
            key: const Key('work-stock-recovery-action'),
            onPressed: _retryingInventory ? null : () => unawaited(_retryInventory(owner, scope, navigation)),
            icon: const Icon(Icons.refresh_rounded, size: 18),
            label: Text(label),
          )),
          const SizedBox(height: 8),
          Text(detail,
            style: const TextStyle(fontSize: 12, height: 1.4, color: MoolColors.muted)),
        ],
      ),
    );
  }

  late final Widget _entryPage = _addProductEntry();
  late final WorkSession _entryOwner = widget.session;
  late final Object _entryInputContext = widget.session.tradingPreferencesContext;
  late final String? _entryStoreId = widget.session.activeWorkspace?.id;
  late Future<bool> _entryDefaultsLoad = _loadEntryDefaults();
  bool get _entryCurrent => widget.ownerCurrent?.call() != false && identical(widget.session, _entryOwner) &&
      _entryInputContext == widget.session.tradingPreferencesContext;
  Future<bool> _loadEntryDefaults() async {
    final id = _entryStoreId;
    final loaded = id != null && await widget.session.loadWorkspaceProductDefaults(expectedStoreId: id);
    return mounted && _entryCurrent && loaded;
  }

  void _restoreStockAction(String productId) {
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) return;
      final target = _stockActionKeys[productId]?.currentContext;
      if (target != null) {
        unawaited(Scrollable.ensureVisible(target, alignment: .5));
      }
    });
  }

  WorkspaceCatalogueItem _blankProduct({String barcode = '', WorkspaceProductDefaults? defaults}) {
    final stamp = DateTime.now().microsecondsSinceEpoch;
    return _newManualWorkspaceProduct(id:'custom-$stamp',sku:'SKU-$stamp',barcode:barcode,
      defaults:defaults??widget.session.workspaceProductDefaults);
  }

  Widget _addProductEntry({String initialMasterSearch = '', String? initialMasterCode,
      bool autoReviewSingleMasterMatch = false, bool Function()? reviewCurrent}) {
    final storeId =
        widget.session.activeWorkspace?.id ?? widget.session.workspaceId;
    final inputContext = widget.session.tradingPreferencesContext;
    final defaults = widget.session.workspaceProductDefaults;
    var tab = 0;
    var manualProduct = _blankProduct(barcode: initialMasterCode ?? '', defaults: defaults);
    WorkspaceCatalogueItem? catalogueProduct;
    WorkspaceMasterCatalogueOrigin? catalogueOrigin;
    var manualEditorKey = GlobalKey<_CatalogueProductEditorState>();
    var catalogueEditorKey = GlobalKey<_CatalogueProductEditorState>();
    bool storeUnchanged() {
      if (reviewCurrent?.call() == false) return false;
      if (!mounted) return false;
      if (inputContext != widget.session.tradingPreferencesContext ||
          (widget.session.activeWorkspace?.id ?? widget.session.workspaceId) !=
          storeId) {
        widget.session.showError('Your store changed. Open Add product again.');
        return false;
      }
      return true;
    }

    return StatefulBuilder(
      builder: (pageContext, setPageState) => StoreAddProductEntryScreen(
        selectedIndex: tab,
        catalogueEditing: catalogueProduct != null,
        onCloseCatalogueEditor: () =>
            catalogueEditorKey.currentState?._requestEditorExit(),
        onSelected: (index) {
          if (!storeUnchanged() || index == tab) return;
          final editor = tab == 1 ? manualEditorKey.currentState
              : tab == 0 ? catalogueEditorKey.currentState : null;
          void changeMode() {
            if (!pageContext.mounted || !storeUnchanged()) return;
            setPageState(() {
              if (tab == 1) {
                manualProduct = _blankProduct(defaults: defaults);
                manualEditorKey = GlobalKey<_CatalogueProductEditorState>();
              } else if (tab == 0) {
                catalogueProduct = null;
                catalogueOrigin = null;
                catalogueEditorKey = GlobalKey<_CatalogueProductEditorState>();
              }
              tab = index;
            });
          }
          if (editor == null) {
            changeMode();
          } else {
            unawaited(editor._requestEditorExit(afterExit: changeMode));
          }
        },
        catalogue: IndexedStack(
          index: catalogueProduct == null ? 0 : 1,
          children: [
            StoreAddProductSheet(
              embedded: true,
              catalogue: widget.session.referenceCatalogue,
              initialMasterSearch: initialMasterSearch,
              initialMasterCode: initialMasterCode,
              autoReviewSingleMasterMatch: autoReviewSingleMasterMatch,
              masterLookup: widget.session.workspaceUsesOriginalMasterCatalogue
                ? (search, code, cursor) => widget.session.readWorkspaceMasterCatalogue(search: search, code: code, cursor: cursor, current: storeUnchanged)
                : null,
              onMasterSelected: (source) {
                if (!storeUnchanged()) return;
                try {
                  final prepared = source.prepareNewStoreDraft(_blankProduct(defaults: defaults));
                  setPageState(() {catalogueProduct = prepared; catalogueOrigin = source.origin;});
                } catch (_) {widget.session.showError('These catalogue details need review. Try another product or add it manually.');}
              },
              isStoreCurrent: storeUnchanged,
              savedCatalogueKeys: widget.session.workspaceCatalogueShortlist,
              recentSearches: widget.session.workspaceCatalogueSearchHistory,
              onBrowseChanged: () {
                if (storeUnchanged()) {
                  widget.session.notifyWorkspaceCatalogueBrowsingChanged();
                }
              },
              ownedProducts: List.of(widget.session.workspaceCatalogueItems),
              createProduct: (barcode) => _blankProduct(barcode: barcode, defaults: defaults),
              scanBarcode: () => showStoreProductScanner(pageContext),
              onAdd: (product) {
                if (!storeUnchanged()) return;
                if (catalogueProduct != null) return;
                final existing = widget.session.workspaceCatalogueItems;
                if (existing.any(
                  (item) =>
                      item.id == product.id ||
                      (item.canonicalId == product.canonicalId &&
                          item.pack == product.pack &&
                          item.variant == product.variant &&
                          item.barcode == product.barcode),
                )) {
                  setPageState(() {});
                  return;
                }
                if (existing.any((item) => item.sku == product.sku)) {
                  widget.session.showError(
                    'This SKU is already in your store. Edit the existing product.',
                  );
                  return;
                }
                setPageState(() {
                  catalogueProduct = product.copyWith(
                    stockMode:
                        defaults.stockMode,
                    lowStockThreshold: defaults.lowStockThreshold,
                    purchasePrice: 0,
                    sellingPrice: 0,
                    unitPrice: '',
                    stock: 0,
                    available: false,
                    publicListing: defaults.customerListingRequested,
                    compliance: product.compliance == null
                        ? null
                        : WorkspaceProductCompliance.fromJson({
                            ...product.compliance!.toJson(),
                            'manufacturedOrPackedOn': null,
                            'bestBeforeOrUseBy': null,
                          }),
                  );
                });
              },
              onSelected: (product) {
                if (storeUnchanged()) {
                  setPageState(() => catalogueProduct = product);
                }
              },
            ),
            if (catalogueProduct != null)
              _CatalogueProductEditor(
                key: catalogueEditorKey,
                session: widget.session,
                product: catalogueProduct!,
                masterOrigin: catalogueOrigin,
                stockEntryMethod: WorkspaceStockEntryMethod.catalogue,
                embeddedPage: true,
                guardRouteExit: false,
                onDone: () => setPageState(() => catalogueProduct = null),
                onSaved: () => Navigator.of(pageContext).pop(true),
               ownerCurrent: widget.ownerCurrent)
            else
              const SizedBox.shrink(),
          ],
        ),
        manual: _CatalogueProductEditor(
          key: manualEditorKey,
          session: widget.session,
          product: manualProduct,
          stockEntryMethod: WorkspaceStockEntryMethod.manual,
          embeddedPage: true,
          guardRouteExit: false,
          onSaved: () => Navigator.of(pageContext).pop(true),
          onDone: () => setPageState(() {
            manualProduct = _blankProduct(defaults: defaults);
            manualEditorKey = GlobalKey<_CatalogueProductEditorState>();
            tab = 0;
          }),
         ownerCurrent: widget.ownerCurrent),
        importCsv: () async {
          if (!storeUnchanged()) {
            return 'Your store changed. Open Add product again.';
          }
          final result = await _importCatalogue(
            csvOnly: true,
            defaults: defaults,
            onSaved: () {
              if (pageContext.mounted && storeUnchanged()) {
                Navigator.of(pageContext).pop(true);
              }
            },
          );
          if (pageContext.mounted) setPageState(() {});
          return result;
        },
      ),
    );
  }

  Future<void> _edit(WorkspaceCatalogueItem product, {String? field, bool Function()? reviewCurrent, Listenable? reviewChanges}) async {
    if (widget.ownerCurrent != null) {
      reviewCurrent ??= widget.ownerCurrent;
      reviewChanges ??= Listenable.merge([widget.session,
        context.getInheritedWidgetOfExactType<MoolAssistantHost>()?.contextChanges]);
    }
    if (reviewCurrent?.call() == false) return;
    final saved = widget.session.workspaceCatalogueItems.any((item) => item.id == product.id);
    final signature = _assistantProductSignature(widget.session, product);
    bool sourceCurrent() {
      if (reviewCurrent?.call() == false) return false;
      final latest = _assistantProductTarget(widget.session, false, product.id);
      return saved ? latest != null && _assistantProductSignature(widget.session, latest) == signature : latest == null;
    }
    await Navigator.of(context).push<void>(
      MaterialPageRoute(
        builder: (pageContext) => _StoreProductOwnerSurface(current: () => reviewCurrent?.call() != false,
          changes: reviewChanges ?? widget.session, child: Scaffold(
          appBar: AppBar(title: const Text('Edit product')),
          body: SafeArea(
            child: _CatalogueProductEditor(
              session: widget.session,
              product: product,
              embeddedPage: true,
              ownerCurrent: reviewCurrent,
              sourceCurrent: reviewCurrent == null ? null : sourceCurrent,
              reviewChanges: reviewChanges,
              initialField: field,
              onDone: () => Navigator.of(pageContext).pop(),
              onSaved: () => Navigator.of(pageContext).pop(),
            ),
          ),
        )),
      ),
    );
    if (mounted) {
      setState(() {});
      if (reviewCurrent == null) _restoreStockAction(product.id);
    }
  }

  bool _originalMasterOpen = false;
  Future<bool> _openOriginalMasterCatalogue({String search = '', String? code,
      bool Function()? reviewCurrent, Listenable? reviewChanges}) async {
    if (_originalMasterOpen || !mounted || !widget.session.workspaceMasterCatalogueConnectionConfigured || reviewCurrent?.call() == false) return false;
    final owner = widget.session.tradingPreferencesContext, store = widget.session.activeWorkspace?.id;
    bool current() => mounted && reviewCurrent?.call() != false && widget.ownerCurrent?.call() != false &&
      widget.session.workspaceMasterCatalogueConnectionConfigured && widget.session.tradingPreferencesContext == owner &&
      widget.session.activeWorkspace?.id == store;
    if (!current() || store == null) return false;
    _originalMasterOpen = true;
    try {
      if (!await widget.session.loadWorkspaceProductDefaults(expectedStoreId: store) || !current()) return false;
      await Navigator.of(context).push<bool>(MaterialPageRoute(builder: (_) => _StoreProductOwnerSurface(
        current: current, changes: reviewChanges ?? widget.session,
        child: _addProductEntry(initialMasterSearch: search, initialMasterCode: code,
          autoReviewSingleMasterMatch: true, reviewCurrent: current))));
      return true;
    } finally {_originalMasterOpen = false;}
  }
  Future<bool> _scan({bool Function()? reviewCurrent, Listenable? reviewChanges}) async {
    if (widget.ownerCurrent != null) {
      reviewCurrent ??= widget.ownerCurrent;
      reviewChanges ??= Listenable.merge([widget.session,
        context.getInheritedWidgetOfExactType<MoolAssistantHost>()?.contextChanges]);
    }
    if (reviewCurrent?.call() == false) return false;
    final inputContext = widget.session.tradingPreferencesContext;
    final code = await showStoreProductScanner(context, ownerCurrent: reviewCurrent, ownerChanges: reviewChanges);
    if (reviewCurrent?.call() == false || !mounted || inputContext != widget.session.tradingPreferencesContext ||
        code == null || code.trim().isEmpty) { return false; }
    final normalized = code.trim().toLowerCase();
    if (widget.session.workspaceUsesOriginalMasterCatalogue) {
      final owned = widget.session.workspaceCatalogueItems.where((item) =>
        item.barcode.toLowerCase() == normalized || item.sku.toLowerCase() == normalized).toList(growable: false);
      if (owned.length > 1) {
        widget.session.showError('This code matches several Store products. Choose the correct pack from Stock.'); return false;
      }
      if (owned.length == 1) {
        await _edit(owned.single, reviewCurrent: reviewCurrent, reviewChanges: reviewChanges); return true;
      }
      return _openOriginalMasterCatalogue(code: code.trim(), reviewCurrent: reviewCurrent, reviewChanges: reviewChanges);
    }
    final products = [
      ...widget.session.workspaceCatalogueItems,
      ...widget.session.referenceCatalogue,
    ];
    final product = products
        .where(
          (item) =>
              item.barcode.toLowerCase() == normalized ||
              item.sku.toLowerCase() == normalized ||
              item.canonicalId.toLowerCase() == normalized,
        )
        .firstOrNull;
    final savedProduct = product != null && widget.session.workspaceCatalogueItems.any((item) => item.id == product.id);
    if (!savedProduct) {
      final id = widget.session.activeWorkspace?.id;
      final loaded = id != null && await widget.session.loadWorkspaceProductDefaults(expectedStoreId: id);
      if (reviewCurrent?.call() == false || !mounted || inputContext != widget.session.tradingPreferencesContext) return false;
      if (!loaded) {
        widget.session.showError(widget.session.workspaceTradingPreferencesError ?? 'Saved product defaults could not be opened. Try again.');
        return false;
      }
    }
    final draft = product == null ? _blankProduct(barcode: code.trim()) : savedProduct
        ? product : widget.session.workspaceProductDefaults.applyToNew(product);
    await _edit(draft, reviewCurrent: reviewCurrent, reviewChanges: reviewChanges);
    return true;
  }

  Future<void> _togglePublic(WorkspaceCatalogueItem product) async {
    await widget.session.toggleWorkspaceProductListing(product.id);
    if (mounted) setState(() {});
  }

  // ignore: unused_element
  Future<void> _showMasterCatalogue() async {
    final ownedIds = widget.session.workspaceCatalogueItems
        .map((product) => product.id)
        .toSet();
    final products = workspaceMasterCatalogue
        .where((product) => !ownedIds.contains(product.id))
        .toList(growable: false);
    await showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      useSafeArea: true,
      showDragHandle: true,
      builder: (sheetContext) => SizedBox(
        height: MediaQuery.sizeOf(context).height * .62,
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            const Padding(
              padding: EdgeInsets.symmetric(horizontal: 18),
              child: Text(
                'Add from MoolSocial catalogue',
                style: TextStyle(
                  color: MoolColors.navy,
                  fontSize: 20,
                  fontWeight: FontWeight.w900,
                ),
              ),
            ),
            const Padding(
              padding: EdgeInsets.fromLTRB(18, 2, 18, 10),
              child: Text(
                'Choose a product, then confirm your price and availability.',
                style: TextStyle(color: MoolColors.muted),
              ),
            ),
            Expanded(
              child: products.isEmpty
                  ? const Center(
                      child: Text('All available products are already added.'),
                    )
                  : ListView.separated(
                      padding: const EdgeInsets.fromLTRB(14, 0, 14, 24),
                      itemCount: products.length,
                      separatorBuilder: (_, _) => const SizedBox(height: 8),
                      itemBuilder: (context, index) {
                        final product = products[index];
                        return _WorkspaceProductRow(
                          product: product,
                          session: widget.session,
                          owned: false,
                          onEdit: () {
                            Navigator.pop(sheetContext);
                            _edit(product);
                          },
                        );
                      },
                    ),
            ),
          ],
        ),
      ),
    );
  }

  Future<String?> _importCatalogue({
    WorkPickedProof? selectedInput,
    bool csvOnly = false,
    WorkspaceProductDefaults? defaults,
    VoidCallback? onSaved,
    bool Function()? reviewCurrent, Listenable? reviewChanges, VoidCallback? onReviewShown,
  }) async {
    if (widget.ownerCurrent != null) {
      reviewCurrent ??= widget.ownerCurrent;
      reviewChanges ??= Listenable.merge([widget.session,
        context.getInheritedWidgetOfExactType<MoolAssistantHost>()?.contextChanges]);
    }
    final identity = widget.session.counterDraftIdentity;
    final storeId =
        widget.session.activeWorkspace?.id ?? widget.session.workspaceId;
    final inputContext = widget.session.tradingPreferencesContext;
    String? familyFingerprint;
    var invalidated = false;
    bool current() =>
        !invalidated &&
        reviewCurrent?.call() != false &&
        mounted &&
        identity == widget.session.counterDraftIdentity &&
        inputContext == widget.session.tradingPreferencesContext &&
        (familyFingerprint == null || familyFingerprint == jsonEncode(
          widget.session.workspaceVariantFamilies.map((f) => f.toJson()).toList())) &&
        storeId ==
            (widget.session.activeWorkspace?.id ?? widget.session.workspaceId);
    void trackScope() {
      if (!current()) invalidated = true;
    }
    // Preserve the exact manual route shape; only captured AI reviews gain
    // an outer cover for the original editor Scaffold and private controls.
    Widget protectImportEditor(Widget child) => reviewCurrent == null ? child
      : _StoreProductOwnerSurface(current: current, changes: reviewChanges ?? widget.session, child: child);

    widget.session.addListener(trackScope);
    try {
      final loaded = storeId != null && await widget.session.loadWorkspaceProductDefaults(expectedStoreId: storeId);
      if (!current()) return 'Your store changed. Import the file again.';
      if (!loaded) return widget.session.workspaceTradingPreferencesError ?? 'Saved product defaults could not be opened. Try again.';
      final importDefaults = defaults ?? widget.session.workspaceProductDefaults;
      final importFamilies = List<WorkspaceVariantFamily>.unmodifiable(widget.session.workspaceVariantFamilies);
      familyFingerprint = jsonEncode(importFamilies.map((f) => f.toJson()).toList());
      final String fileName;
      final Uint8List bytes;
      if (selectedInput != null) {
        // Actual copied original file: no repick, model CSV, path or new rows.
        if (!_storeSelectedCatalogueInputValid(selectedInput, csvOnly: csvOnly)) {
          return 'Choose a CSV or JSON file smaller than 10 MB.';
        }
        fileName = selectedInput.fileName;
        bytes = selectedInput.bytes;
      } else {
        final picked = await FilePicker.pickFile(
          type: FileType.custom,
          allowedExtensions: csvOnly ? const ['csv'] : const ['csv', 'json'],
        );
        if (!current()) return 'Your store changed. Import the file again.';
        if (picked == null) return null;
        if (await picked.length() > 10 * 1024 * 1024) {
          return 'Choose a file smaller than 10 MB.';
        }
        bytes = await picked.readAsBytes();
        fileName = picked.name;
      }
      if (!current()) return 'Your store changed. Import the file again.';
      if (bytes.length > 10 * 1024 * 1024) {
        return 'Choose a file smaller than 10 MB.';
      }
      final review = WorkspaceProductImport.parse(
        utf8.decode(bytes),
        json: fileName.toLowerCase().endsWith('.json'),
        catalogue: widget.session.referenceCatalogue,
        owned: List.of(widget.session.workspaceCatalogueItems),
        defaults: importDefaults,
        variantFamilies: importFamilies,
      );
      if (!current()) return 'Your store changed. Import the file again.';
      if (!mounted) return null;
      var savedCount = 0;
      WorkspaceProductDraftBatchSyncResult? productSync;
      Future<void> syncPrivateCopies(List<WorkspaceCatalogueItem> products) async {
        if (widget.session.gateway is ReviewWorkGateway) return;
        productSync = await widget.session.syncWorkspaceSavedProductDrafts(products.map((product) => product.id), current: current);
      }
      Map<String, String>? attemptedReview, attemptedStock;
      onReviewShown?.call();
      final saved = await Navigator.of(context).push<bool>(
        MaterialPageRoute(
          builder: (reviewContext) => _StoreProductOwnerSurface(current: current, changes: reviewChanges ?? widget.session, child: StoreProductImportReviewScreen(
            recentSearches: widget.session.workspaceRecentSearches(
              'csv:$fileName',
            ),
            fileName: fileName,
            review: review,
            correctRow: (row, readyProducts) async {
              if (!current() || !row.canCorrect) return null;
              // A presentation seed is not a validated or saveable import row.
              // Only an unambiguous exact identity may supply catalogue media.
              final raw = row.rawValues;
              final matches = widget.session.referenceCatalogue
                  .where(
                    (p) =>
                        p.title.trim().toLowerCase() ==
                            (raw['title'] ?? '').toLowerCase() &&
                        p.brand.trim().toLowerCase() ==
                            (raw['brand'] ?? '').toLowerCase() &&
                        p.variant.trim().toLowerCase() ==
                            (raw['variant'] ?? '').toLowerCase() &&
                        p.pack.trim().toLowerCase() ==
                            (raw['pack'] ?? '').toLowerCase() &&
                        ((raw['barcode'] ?? '').isEmpty ||
                            p.barcode == raw['barcode']) &&
                        ((raw['canonicalId'] ?? '').isEmpty ||
                            p.canonicalId == raw['canonicalId']),
                  )
                  .toList();
              final seed = matches.length == 1
                  ? matches.single
                  : _blankProduct(defaults: importDefaults);
              final corrected = await Navigator.of(reviewContext)
                  .push<WorkspaceProductImportRow>(
                    MaterialPageRoute(
                      builder: (editorContext) => protectImportEditor(Scaffold(
                        appBar: AppBar(
                          toolbarHeight: 48,
                          titleSpacing: 0,
                          title: Text(
                            'Correct product · Row ${row.number}',
                            style: const TextStyle(
                              fontSize: 16,
                              fontWeight: FontWeight.w700,
                              color: MoolColors.navy,
                            ),
                          ),
                        ),
                        body: SafeArea(
                          child: _CatalogueProductEditor(
                            session: widget.session,
                            product: seed,
                            embeddedPage: true,
                            ownerCurrent: current,
                            sourceCurrent: reviewCurrent == null ? null : current,
                            reviewChanges: reviewCurrent == null ? reviewChanges : reviewChanges ?? widget.session,
                            importRow: row,
                            onDone: () => Navigator.of(editorContext).pop(),
                            validateImport: (values, clearedContentFields) {
                              if (!current()) {
                                throw const FormatException(
                                  'Your Store changed. Close this import and open the correct Store.',
                                );
                              }
                              return WorkspaceProductImport.revalidateRow(
                                row,
                                values,
                                catalogue: widget.session.referenceCatalogue,
                                owned: [
                                  ...widget.session.workspaceCatalogueItems,
                                ],
                                readyRows: readyProducts,
                                defaults: importDefaults,
                                variantFamilies: importFamilies,
                                clearedContentFields: clearedContentFields,
                              );
                            },
                            onImportReviewed: (result) {
                              if (reviewCurrent == null || current()) Navigator.of(editorContext).pop(result);
                            },
                          ),
                        ),
                      )),
                    ),
                  );
              return current() ? corrected : null;
            },
            editProduct: (product) async {
              if (!current()) return null;
              final edited = await Navigator.of(reviewContext).push<WorkspaceCatalogueItem>(
                MaterialPageRoute(
                  builder: (editorContext) => protectImportEditor(Scaffold(
                    appBar: AppBar(
                      toolbarHeight: 48,
                      titleSpacing: 0,
                      title: const Text(
                        'Review product',
                        style: TextStyle(
                          fontSize: 16,
                          fontWeight: FontWeight.w700,
                          color: MoolColors.navy,
                        ),
                      ),
                    ),
                    body: SafeArea(
                      child: _CatalogueProductEditor(
                        session: widget.session,
                        product: product,
                        embeddedPage: true,
                        onDone: () => Navigator.of(editorContext).pop(),
                        onDraftReviewed: (edited) {
                          if (reviewCurrent == null || current()) Navigator.of(editorContext).pop(edited);
                        },
                        ownerCurrent: reviewCurrent == null ? widget.ownerCurrent : current,
                        sourceCurrent: reviewCurrent == null ? null : current,
                        reviewChanges: reviewCurrent == null ? null : reviewChanges ?? widget.session),
                    ),
                  )),
                ),
              );
              return reviewCurrent == null || current() ? edited : null;
            },
            saveProducts: (products) async {
              if (!current()) {
                return 'Your store changed. Close this review and import again.';
              }
              if (widget.session.localInventoryEnabled) {
                if (!await widget.session.loadWorkspaceInventory(retry: true) ||
                    !current()) {
                  return widget.session.workspaceInventoryError ??
                      'Return to the same Store before importing.';
                }
                if (savedCount > 0) {
                  final owned = {
                    for (final p in widget.session.workspaceCatalogueItems)
                      p.id: p,
                  };
                  final submittedIds = products.map((p) => p.id).toSet();
                  // A retry must cover every frozen row exactly once. Row count
                  // and per-row equality alone would accept A/A in place of A/B.
                  if (products.length != savedCount || attemptedReview == null ||
                      attemptedStock == null ||
                      submittedIds.length != products.length ||
                      submittedIds.length != attemptedReview!.length ||
                      submittedIds.length != attemptedStock!.length ||
                      !submittedIds.containsAll(attemptedReview!.keys) ||
                      !submittedIds.containsAll(attemptedStock!.keys) ||
                      products.any(
                    (p) =>
                        attemptedReview![p.id] != jsonEncode(
                          p.copyWith(publicListing: false).toInventoryJson()) ||
                        attemptedStock![p.id] !=
                          jsonEncode(owned[p.id]?.toInventoryJson()),
                  )) {
                    return 'The reviewed products changed. Keep this review open and check the unsaved Store stock.';
                  }
                  if (!await widget.session.retryWorkspaceInventorySave() || !current()) {
                    return widget.session.workspaceInventoryError ?? 'Stock was not saved. Retry.';
                  }
                  await syncPrivateCopies(products);
                  return null;
                }
              }
              // Recheck against live inventory: it may have changed while reviewing.
              final owned = widget.session.workspaceCatalogueItems;
              final ids = owned.map((p) => p.id).toSet();
              final skus = owned.map((p) => p.sku.trim().toLowerCase()).toSet();
              final barcodes = owned
                  .where((p) => p.barcode.isNotEmpty)
                  .map((p) => p.barcode)
                  .toSet();
              final identities = owned
                  .map(WorkspaceProductImport.identity)
                  .toSet();
              for (final p in products) {
                if (!ids.add(p.id) ||
                    !skus.add(p.sku.trim().toLowerCase()) ||
                    (p.barcode.isNotEmpty && !barcodes.add(p.barcode)) ||
                    !identities.add(WorkspaceProductImport.identity(p))) {
                  return 'Store stock changed or contains a duplicate. Import the file again; nothing was added.';
                }
              }
              if (!widget.session.importWorkspaceProducts(
                products.map((p) => p.copyWith(publicListing: false)).toList(),
                addOnly: true,
                stockEntryMethod: fileName.toLowerCase().endsWith('.csv') ? WorkspaceStockEntryMethod.csv : null,
                variantFamilyFingerprints: review.variantFamilyFingerprints,
              )) {
                return 'Goods receipt is being saved. Your reviewed products are kept; try again when it finishes.';
              }
              savedCount = products.length;
              // Freeze both sides of the attempted save. Provenance is created
              // by the session, not the review editor; retry it without inventing
              // a new entry time or hiding actual review/inventory changes.
              attemptedReview = Map.unmodifiable({for (final p in products)
                p.id: jsonEncode(p.copyWith(publicListing: false).toInventoryJson())});
              final attemptedOwned = {for (final p in widget.session.workspaceCatalogueItems)
                p.id: p};
              attemptedStock = Map.unmodifiable({for (final p in products)
                p.id: jsonEncode(attemptedOwned[p.id]?.toInventoryJson())});
              if (widget.session.localInventoryEnabled &&
                  !await widget.session.workspaceInventorySaved) {
                return widget.session.workspaceInventoryError ??
                    'Stock was not saved. Keep this review open and retry.';
              }
              await syncPrivateCopies(products);
              // Original Save may already be committed. A retired AI review
              // must report its changed owner rather than pop another route.
              if (reviewCurrent != null && !current()) {
                return 'Your store changed. Close this review and import again.';
              }
              return null;
            },
          )),
        ),
      );
      if (!current()) {
        return 'Your store changed. Open the correct Store to check its stock.';
      }
      if (saved != true) {
        if (savedCount > 0) {
          return 'Import review closed with unsaved stock changes. Return to Store stock to review and retry saving.';
        }
        return 'Import cancelled. No products were added.';
      }
      setState(() {});
      onSaved?.call();
      final sync = productSync;
      final synced = sync?.states.values.where((state) => state == WorkspaceProductDraftWriteState.saved).length ?? 0;
      final syncNote = sync == null ? '' : !sync.available ? ' Customer preview sync is unavailable right now.'
        : synced == sync.requested.length ? ' Customer previews synced.'
        : ' Customer previews: $synced synced, ${sync.requested.length - synced} need sync. Check product sync in the saved products.';
      return '$savedCount products saved to Store stock. Nothing was published.$syncNote';
    } on FormatException catch (error) {
      return error.message;
    } catch (_) {
      return 'Could not read this file. Choose a UTF-8 CSV or JSON file and try again.';
    } finally {
      widget.session.removeListener(trackScope);
    }
  }

  @override
  Widget build(BuildContext context) {
    if (widget.entryOnly) {
      if (!widget.session.tradingPreferencesPersistenceAvailable) return _entryPage;
      return FutureBuilder<bool>(future: _entryDefaultsLoad, builder: (context, snapshot) {
        if (_entryCurrent && snapshot.connectionState == ConnectionState.done && snapshot.data == true) return _entryPage;
        return Scaffold(key: const Key('work-product-defaults-hold'),
          appBar: AppBar(title: const Text('Add products')),
          body: Center(child: Padding(padding: const EdgeInsets.all(16), child:
            !_entryCurrent ? const Text('Your Store or account changed. Reopen Add products.') :
            snapshot.connectionState != ConnectionState.done
              ? const CircularProgressIndicator(semanticsLabel: 'Opening saved product defaults')
              : Column(mainAxisSize: MainAxisSize.min, children: [
                  Text(widget.session.workspaceTradingPreferencesError ?? 'Saved product defaults could not be opened.'),
                  OutlinedButton(onPressed: () => setState(() { _entryDefaultsLoad = _loadEntryDefaults(); }), child: const Text('Try again')),
                ]))));
      });
    }
    return SizedBox.expand(
      key: const Key('work-dashboard-catalogue-screen'),
      child: _StockQuickActionsFrame(
        wholeActions: true,
        expanded: _actionsExpanded,
        onToggle: _toggleActions,
        actions: [
          _StoreEdgeAction(
            keyName: 'work-quick-add-products',
            icon: Icons.add_box_outlined,
            label: 'Add products',
            onTap: _stockNeedsRecovery ? null : () async {
              if (_stockNeedsRecovery) return;
              await Navigator.of(context).push<bool>(
                MaterialPageRoute(
                  builder: (_) => _WorkspaceCatalogueSurface(
                    session: widget.session,
                    entryOnly: true,
                  ),
                ),
              );
              if (mounted) setState(() {});
            },
          ),
          if (widget.onBuyStock != null)
            _StoreEdgeAction(
              keyName: 'work-quick-buy',
              icon: Icons.inventory_2_outlined,
              label: 'Restock',
              onTap: widget.onBuyStock,
            ),
          if (widget.onPurchases != null)
            _StoreEdgeAction(
              keyName: 'work-incoming-purchases',
              icon: Icons.local_shipping_outlined,
              label: 'Purchase register',
              onTap: widget.onPurchases,
            ),
          if (widget.onGroupBuying != null)
            _StoreEdgeAction(
              keyName: 'work-quick-group-buy',
              icon: Icons.groups_2_outlined,
              label: 'Buy together',
              onTap: widget.onGroupBuying,
            ),
        ],
        child: _stockNeedsRecovery ? SingleChildScrollView(
          key: const Key('work-stock-recovery-scroll'),
          padding: const EdgeInsets.all(12),
          child: _inventoryStatusCard(recovery: true),
        ) : Column(
          children: [
            ListenableBuilder(
              listenable: widget.session,
              builder: (context, _) {
                final error = widget.session.workspaceInventoryError;
                if (error == null) return const SizedBox.shrink();
                return Padding(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 12,
                    vertical: 6,
                  ),
                  child: _inventoryStatusCard(recovery: false),
                );
              },
            ),
            Expanded(
              child: StoreAddProductSheet(
                key: ValueKey(
                  'store-stock-${widget.session.activeWorkspace?.id ?? widget.session.workspaceId}',
                ),
                embedded: true,
                stockOnly: true,
                onStockStatement: widget.onStatement,
                recentSearches: widget.session.workspaceRecentSearches('stock'),
                catalogue: const [],
                ownedProducts: List.of(widget.session.workspaceCatalogueItems),
                createProduct: (barcode) => _blankProduct(barcode: barcode),
                scanBarcode: () => showStoreProductScanner(context),
                onSelected: _edit,
                stockStatementBuilder: (products, count, vertical, loadMore) =>
                    _StoreStockStatementTable(
                      products: products,
                      showMrp: widget.session.workspaceCatalogueItems.any((item) => item.mrpMinor != null),
                      bottomClearance: _actionsExpanded
                          ? 0
                          : _stockQuickTabHeight(context) + 6,
                      visibleCount: count,
                      vertical: vertical,
                      loadMore: loadMore,
                      rowBuilder:
                          (product, horizontal, frozenWidth, widths, height) =>
                              _WorkspaceProductRow(
                                product: product,
                                session: widget.session,
                                owned: true,
                                statement: true,
                                horizontal: horizontal,
                                frozenWidth: frozenWidth,
                                statementWidths: widths,
                                statementHeight: height,
                                stockActionKey: _stockActionKeys.putIfAbsent(
                                  product.id,
                                  () => GlobalKey(),
                                ),
                                onEdit: () => _edit(product),
                                onChangePrice: () =>
                                    _edit(product, field: 'sellingPrice'),
                                onUpdateStock: () =>
                                    _edit(product, field: 'stock'),
                                onEditField: (field) =>
                                    _edit(product, field: field),
                                onTogglePublic: () => _togglePublic(product),
                              ),
                    ),
              ),
            ),
          ],
        ),
      ),
    );
  }
}

class _StoreEdgeAction extends StatelessWidget {
  const _StoreEdgeAction({
    required this.keyName,
    required this.icon,
    required this.label,
    required this.onTap,
    this.selected,
  });
  final String keyName, label;
  final IconData icon;
  final VoidCallback? onTap;
  final bool? selected;

  @override
  Widget build(BuildContext context) => Semantics(
    key: Key('$keyName-state'),
    button: true,
    selected: selected,
    label: label,
    enabled: onTap != null,
    onTap: onTap,
    excludeSemantics: true,
    child: Tooltip(
      message: label,
      child: Material(
        color: Colors.transparent,
        child: Ink(
          decoration: BoxDecoration(
            color: selected == true ? MoolColors.navy : Colors.white,
            borderRadius: BorderRadius.circular(9),
          ),
          child: InkWell(
            key: Key(keyName),
            onTap: onTap,
            borderRadius: BorderRadius.circular(9),
            focusColor: const Color(0xFFE9EBEF),
            hoverColor: const Color(0xFFF3F4F6),
            highlightColor: const Color(0xFFE9EBEF),
            child: Container(
              constraints: const BoxConstraints(minHeight: 48, minWidth: 48),
              padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 6),
              alignment: Alignment.center,
              child: Row(
                mainAxisSize: MainAxisSize.min,
                children: [
                  Icon(icon, size: 15, color: selected == true ? Colors.white : onTap == null
                      ? MoolColors.muted : MoolColors.navy),
                  const SizedBox(width: 5),
                  Flexible(child: Text(label, style: TextStyle(
                    fontSize: 11, height: 1.25, fontWeight: FontWeight.w600,
                    color: selected == true ? Colors.white : onTap == null ? MoolColors.muted : MoolColors.navy,
                  ))),
                ],
              ),
            ),
          ),
        ),
      ),
    ),
  );
}

double _stockQuickTabHeight(BuildContext context) {
  final painter = TextPainter(
    text: TextSpan(
      text: 'Quick actions',
      style: DefaultTextStyle.of(
        context,
      ).style.merge(const TextStyle(fontSize: 11, fontWeight: FontWeight.w600)),
    ),
    textDirection: TextDirection.ltr,
    textScaler: MediaQuery.textScalerOf(context),
  )..layout();
  final height = painter.width.ceilToDouble() + 41;
  painter.dispose();
  return height;
}

({int columns, double height}) _stockActionLayout(
  BuildContext context, List<_StoreEdgeAction> actions, double width,
) {
  final style = DefaultTextStyle.of(context).style.merge(const TextStyle(
    fontSize: 11, height: 1.25, fontWeight: FontWeight.w600));
  final painters = [for (final action in actions) TextPainter(
    text: TextSpan(text: action.label, style: style),
    textDirection: Directionality.of(context), textScaler: MediaQuery.textScalerOf(context))..layout()];
  var minimum = 48.0;
  for (final painter in painters) {
    if (painter.width + 40 > minimum) minimum = painter.width + 40;
  }
  final columns = (width / minimum).floor().clamp(1, actions.length).toInt();
  var height = 48.0;
  for (final painter in painters) {
    // Cell padding, icon and gap consume40px; text keeps its full scaled size.
    painter.layout(maxWidth: (width / columns - 40).clamp(1.0, double.infinity));
    if (painter.height + 12 > height) height = painter.height + 12;
    painter.dispose();
  }
  return (columns: columns, height: height.ceilToDouble());
}

/// Shared horizontal action shelf, collapsed manually to the corner control.
class _StockQuickActionsFrame extends StatelessWidget {
  const _StockQuickActionsFrame({
    required this.child,
    required this.actions,
    required this.expanded,
    required this.onToggle,
    this.keyPrefix = 'work-stock',
    this.enabled = true,
    this.wholeActions = false,
  });
  final Widget child;
  final List<Widget> actions;
  final bool expanded;
  final VoidCallback onToggle;
  final String keyPrefix;
  final bool enabled;
  final bool wholeActions;

  @override
  Widget build(BuildContext context) => LayoutBuilder(
    builder: (context, box) {
      if (!enabled) return child;
      // Preserve full-sized text and targets in short accessibility viewports.
      // Keep actions fixed while the register can use a readable scroll extent.
      final textScaler = MediaQuery.textScalerOf(context);
      final minimumHeight = textScaler.scale(200);
      Widget readableContent = child;
      if (MediaQuery.orientationOf(context) == Orientation.landscape &&
          textScaler.scale(1) > 1.3 &&
          box.hasBoundedHeight && box.maxHeight < minimumHeight + (expanded ? 54 : 0)) {
        readableContent = SingleChildScrollView(
          key: Key('$keyPrefix-large-landscape-scroll'),
          keyboardDismissBehavior: ScrollViewKeyboardDismissBehavior.onDrag,
          child: Builder(builder: (scrollContext) => NotificationListener<OverscrollNotification>(
            onNotification: (notification) {
              if (notification.metrics.axis != Axis.vertical) return false;
              final outer = Scrollable.of(scrollContext).position;
              final target = (outer.pixels + notification.overscroll)
                  .clamp(outer.minScrollExtent, outer.maxScrollExtent);
              if (target == outer.pixels) return false;
              outer.jumpTo(target);
              return true;
            },
            child: SizedBox(
              key: Key('$keyPrefix-readable-content'),
              height: minimumHeight,
              child: child,
            ),
          )),
        );
      }
      final desiredHeight = _stockQuickTabHeight(context);
      final short = box.maxHeight < desiredHeight + 12;
      final tabHeight = short ? 48.0 : desiredHeight;
      final label = expanded ? 'Hide Quick actions' : 'Show Quick actions';
      final toggle = Tooltip(
        message: label,
        child: Semantics(
          button: true,
          label: label,
          expanded: expanded,
          excludeSemantics: true,
          child: Material(
            color: expanded ? Colors.transparent : const Color(0xFFF0F1F7),
            borderRadius: const BorderRadius.only(
              topLeft: Radius.circular(12),
              bottomLeft: Radius.circular(12),
            ),
            child: InkWell(
              key: Key('$keyPrefix-actions-toggle'),
              onTap: onToggle,
              borderRadius: BorderRadius.circular(12),
              child: SizedBox(
                width: 48,
                height: expanded ? 48 : tabHeight,
                child: expanded || short
                    ? Icon(
                        expanded
                            ? Icons.chevron_right_rounded
                            : Icons.chevron_left_rounded,
                        color: MoolColors.navy,
                        size: 21,
                      )
                    : Padding(
                        padding: const EdgeInsets.symmetric(
                          horizontal: 4,
                          vertical: 6,
                        ),
                        child: Column(
                          mainAxisAlignment: MainAxisAlignment.center,
                          children: [
                            const Icon(
                              Icons.chevron_left_rounded,
                              size: 21,
                              color: MoolColors.navy,
                            ),
                            const RotatedBox(
                              quarterTurns: 3,
                              child: Text(
                                'Quick actions',
                                style: TextStyle(
                                  fontSize: 11,
                                  fontWeight: FontWeight.w600,
                                  color: MoolColors.navy,
                                ),
                              ),
                            ),
                          ],
                        ),
                      ),
              ),
            ),
          ),
        ),
      );
      if (expanded) {
        var actionHeight = (MediaQuery.textScalerOf(context).scale(11) * 1.25 + 16)
            .clamp(48.0, double.infinity);
        if (wholeActions && actions.isNotEmpty && actions.every((a) => a is _StoreEdgeAction)) {
          final width = (box.maxWidth - 48).clamp(1.0, double.infinity);
          actionHeight = _stockActionLayout(context, actions.cast<_StoreEdgeAction>(), width).height;
        }
        return Column(
          children: [
            Expanded(child: SizedBox(
              key: Key('$keyPrefix-action-content'),
              width: double.infinity,
              child: readableContent,
            )),
            _StoreBottomActionShelf(keyPrefix: keyPrefix, actions: actions,
              height: actionHeight + 6, toggle: toggle, wholeActions: wholeActions),
          ],
        );
      }
      return ColoredBox(
        color: const Color(0xFFF7F8FC),
        child: Stack(
          children: [
            Positioned.fill(
              child: ClipPath(
                key: Key('$keyPrefix-action-content'),
                clipper: _StockActionCutout(expanded ? 0 : tabHeight + 6),
                child: readableContent,
              ),
            ),
            Positioned(right: 0, bottom: 0, child: toggle),
          ],
        ),
      );
    },
  );
}

/// Stock shelf retains its horizontal action list and original collapse control.
class _StoreBottomActionShelf extends StatelessWidget {
  const _StoreBottomActionShelf({required this.keyPrefix,
    required this.actions, this.height, this.toggle, this.wholeActions = false});
  final String keyPrefix;
  final List<Widget> actions;
  final double? height;
  final Widget? toggle;
  final bool wholeActions;

  @override
  Widget build(BuildContext context) => Container(
    key: Key('$keyPrefix-actions-panel'), height: height, color: Colors.white,
    child: Row(children: [
      Expanded(child: wholeActions && actions.isNotEmpty && actions.every((a) => a is _StoreEdgeAction)
        ? _StockWholeActionStrip(keyPrefix: keyPrefix, actions: actions.cast<_StoreEdgeAction>())
        : SingleChildScrollView(
        key: Key('$keyPrefix-entry-controls'), scrollDirection: Axis.horizontal,
        padding: const EdgeInsets.symmetric(horizontal: 4, vertical: 3),
        child: Row(children: [for (final action in actions)
          Padding(padding: const EdgeInsets.only(right: 4), child: action)]),
      )),
      ?toggle,
    ]),
  );
