                        _ProductQuickValue(
                          keyName: 'work-catalogue-price-${product.id}',
                          icon: Icons.sell_outlined,
                          label: '₹${_formatStoreMinorAmount(product.sellingPriceMinor)}',
                          onTap: onChangePrice,
                        ),
                        _ProductQuickValue(
                          key: stockActionKey,
                          keyName: 'work-catalogue-stock-${product.id}',
