    this.guardRouteExit = true,
    this.initialField,
    this.onDone,
    this.onSaved,
    this.onDraftReviewed,
    this.importRow,
    this.validateImport,
    this.onImportReviewed,
    this.purchaseScope,
    this.stockEntryMethod,
    this.initialData, this.prefillCurrent, this.ownerCurrent, this.sourceCurrent,
    this.nativeReview, this.selectedPhoto, this.reviewChanges,
    this.stockAdjustmentInitial, this.stockAdjustmentCurrent,
    this.masterOrigin,
  });
  final StoreStockAdjustmentInitialData? stockAdjustmentInitial;
  final WorkspaceMasterCatalogueOrigin? masterOrigin;
  final bool Function()? stockAdjustmentCurrent;

  final StoreProductInitialData? initialData;
  final StoreProductNativeInitial? nativeReview;
  final MoolAssistantSelectedDocument? selectedPhoto;
  final Listenable? reviewChanges;
  final bool Function()? prefillCurrent, ownerCurrent, sourceCurrent;
  final WorkSession session;
  final WorkspaceCatalogueItem product;
  final bool embeddedPage;
  final bool guardRouteExit;
  final String? initialField;
  final VoidCallback? onDone;
  final VoidCallback? onSaved;
  final ValueChanged<WorkspaceCatalogueItem>? onDraftReviewed;
  final WorkspaceProductImportRow? importRow;
  final WorkspaceProductImportRow Function(Map<String, String>, Set<String>)? validateImport;
  final ValueChanged<WorkspaceProductImportRow>? onImportReviewed;
  // Only new-product setup launched by a purchase. All other editors are unchanged.
  final (String, String, bool)? purchaseScope;
  // Explicit creation route only; edits and purchase/CSV draft review do not post.
  final WorkspaceStockEntryMethod? stockEntryMethod;

  @override
  State<_CatalogueProductEditor> createState() =>
      _CatalogueProductEditorState();
}

class _CatalogueProductEditorState extends State<_CatalogueProductEditor> {
  late final String? _storeId;
  late final Object _reviewEditorContext;
  bool get _reviewEditorCurrent => mounted && widget.session.publicationPreferencesContext == _reviewEditorContext &&
      widget.ownerCurrent?.call() != false;
// Insert inside _CatalogueProductEditorState; all mutating operations remain
// original native controls. No photo picker, publisher, scanner or price engine.
bool _nativeReviewStarted = false;
final _nativeReviewTargetKey = GlobalKey();
bool get _hasCapturedReview => widget.nativeReview != null || widget.initialData != null || widget.sourceCurrent != null;
bool Function()? get _capturedRequestCurrent => _hasCapturedReview
    ? () => _reviewEditorCurrent && _assistantInputCurrent : null;
bool Function()? get _capturedOwnerCurrent => _hasCapturedReview
    ? () => _reviewEditorCurrent : null;
bool _nativeControlReady() {
  if (_reviewEditorCurrent && (!_hasCapturedReview || _assistantInputCurrent)) return true;
  if (mounted) _reject('Product or original request details changed. Close and reopen this review.');
  return false;
}
Future<T?> _showProductOwnerDialog<T>({required WidgetBuilder builder}) async {
  if (!_hasCapturedReview) {
    return showDialog<T>(context: context, builder: builder);
  }
  if (!_reviewEditorCurrent || !_assistantInputCurrent) return null;
  final navigator = Navigator.of(context, rootNavigator: true);
  late final DialogRoute<T> route;
  route = DialogRoute<T>(context: context, builder: builder);
  void changed() {
    if ((!_reviewEditorCurrent || !_assistantInputCurrent) && route.isActive) navigator.removeRoute(route);
  }
  final changes = widget.reviewChanges ?? Listenable.merge([widget.session,
    context.getInheritedWidgetOfExactType<MoolAssistantHost>()?.contextChanges]);
  changes.addListener(changed);
  try { return await navigator.push<T>(route); }
  finally { changes.removeListener(changed); }
}
void _startNativeReview() {
  if (_nativeReviewStarted || widget.nativeReview == null) return;
  _nativeReviewStarted = true;
  WidgetsBinding.instance.addPostFrameCallback((_) async {
    final initial = widget.nativeReview;
    if (!mounted || initial == null || widget.prefillCurrent?.call() == false || !_reviewEditorCurrent ||
        !_assistantInputCurrent || !initial.matches(widget.product)) {
      if (mounted) setState(() => _assistantPrefillRejected = true);
      return;
    }
    final action = initial.actionId;
    final section = switch (action) {
      'AI-ACT-215' || 'AI-ACT-224' || 'AI-ACT-374' => 'variants',
      'AI-ACT-370' => 'facts', 'AI-ACT-371' || 'AI-ACT-220' => 'selling', _ => 'summary',
    };
    setState(() {
      _expanded[section] = true;
      if (action == 'AI-ACT-222') { _public = initial.visible!; _listingIntentChanged = true; }
    });
    await WidgetsBinding.instance.endOfFrame;
    if (!mounted || !_reviewEditorCurrent || !_assistantInputCurrent || widget.prefillCurrent?.call() == false) return;
    switch (action) {
      case 'AI-ACT-215':
        await _editVariantOptions(create: _variantFamily == null, initialDimensions: initial.dimensions);
        break;
      case 'AI-ACT-216':
        final selected = widget.selectedPhoto;
        if (selected != null) await _chooseProductPhoto(selected: selected.proof,
          reviewCurrent: () => _reviewEditorCurrent && _assistantInputCurrent && widget.prefillCurrent?.call() != false);
        break;
      case 'AI-ACT-220': await _confirmTradePrice(initialValidity: initial.validityMinutes); break;
      case 'AI-ACT-226': case 'AI-ACT-227': await _confirmRetirement(); break;
      case 'AI-ACT-370': await _editGuidedDetails(warrantyInitial: initial.warranty, initialGuide: 'warranty'); break;
      default:
        final target = _nativeReviewTargetKey.currentContext ?? _sectionKeys[section]?.currentContext;
        if (target != null) await Scrollable.ensureVisible(target, alignment: .1);
    }
  });
}

  final Object _productEditorToken = Object();
  late final WorkSession _productEditorOwner;
  bool _assistantPrefillRejected = false;
  bool get _assistantInputCurrent => (!_hasCapturedReview) ||
      !_assistantPrefillRejected && _reviewEditorCurrent &&
      (_pendingInventorySave || widget.sourceCurrent?.call() != false);
  bool get _mediaEditorCurrent => _reviewEditorCurrent && ((!_hasCapturedReview) || _assistantInputCurrent) && (ModalRoute.of(context)?.isCurrent ?? true);
  late final bool _wasOwned;
  bool _saved = false;
  bool _savingInventory = false;
  bool _pendingInventorySave = false;
  bool _choosingPhoto = false;
  bool _allowEditorExit = false;
  bool _confirmingEditorExit = false;
  late final Map<String, String> _initialEditValues;
  late final String _initialVariantState;
  late WorkspaceVariantFamily? _variantFamily = widget.session.workspaceVariantFamilies
    .where((f) => f.id == widget.product.variantMembership?.familyId).firstOrNull;
  late final Map<String, String> _variantSelections = {
    ...?widget.product.variantMembership?.selections,
  };
  final Map<String, Map<String, String>> _siblingVariantSelections = {};
  late bool _useSharedVariantContent = widget.product.variantMembership?.useSharedContent ?? true;
  String get _variantState => jsonEncode([_variantFamily?.toJson(), _variantSelections,
    _siblingVariantSelections, _useSharedVariantContent]);
  bool get _hasUnsavedEdits => !_saved && (
    _importControllers.entries.any(
      (entry) => entry.value.text != _initialEditValues[entry.key]) ||
    _public != widget.product.publicListing ||
    _available != widget.product.available ||
    _privatePhoto != widget.product.privatePhoto || _variantState != _initialVariantState ||
    widget.stockAdjustmentInitial != null && _stockAdjustmentReason.text.isNotEmpty);
  late WorkspacePrivateProductPhoto? _privatePhoto =
      widget.product.privatePhoto;

  WorkspaceCatalogueItem get _photoIdentity => widget.product.copyWith(
    title: _title.text.trim(),
    brand: _brand.text.trim(),
    variant: _variant.text.trim(),
    pack: _pack.text.trim(),
    barcode: _barcode.text.trim(),
    categoryId: _category.text.trim(),
    clearPrivatePhoto: true,
  );

  WorkspacePrivateProductPhoto? get _matchingPhoto =>
      _privatePhoto?.matches(_photoIdentity) == true ? _privatePhoto : null;

  Future<void> _chooseProductPhoto({WorkPickedProof? selected, bool Function()? reviewCurrent}) async {
    bool current() => _reviewEditorCurrent && (!_hasCapturedReview || _assistantInputCurrent) && reviewCurrent?.call() != false;
    if (!current()) return;
    if (_choosingPhoto ||
        _savingInventory ||
        _saved ||
        widget.importRow != null) {
      return;
    }
    final product = _photoIdentity;
    if (widget.session.catalogueManagesProductPhoto(product)) return;
    final store = widget.session.privateProductPhotos;
    if (store == null) {
      _reject('Store photo storage is unavailable. Try again from your Store.');
      return;
    }
    setState(() => _choosingPhoto = true);
    try {
      String? selectedName;
      final picked = selected ?? await NativeWorkProofPicker(
        documentFileName: () => selectedName,
        documentPicker: () async {
          final selected = await FilePicker.pickFile(type: FileType.image);
          selectedName = selected?.name;
          return selected?.xFile;
        },
      ).pick(WorkProofSource.upload);
      if (picked == null || !current() || !store.isCurrent()) return;
      final photo = await store.save(product: product, picked: picked);
      final bytes = await store.read(product.copyWith(privatePhoto: photo));
      if (!current() || !store.isCurrent()) return;
      final accepted = await _showProductOwnerDialog<bool>(
        builder: (dialogContext) => AlertDialog(
          insetPadding: const EdgeInsets.symmetric(
            horizontal: 20,
            vertical: 16,
          ),
          titlePadding: const EdgeInsets.fromLTRB(16, 16, 16, 8),
          contentPadding: const EdgeInsets.symmetric(horizontal: 16),
          actionsPadding: const EdgeInsets.fromLTRB(8, 4, 8, 8),
          title: const Text(
            'Check product image',
            style: TextStyle(
              fontSize: 16,
              fontWeight: FontWeight.w700,
              color: Color(0xFF252B38),
            ),
          ),
          content: SingleChildScrollView(
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                SizedBox.square(
                  dimension: (MediaQuery.sizeOf(dialogContext).height * .28)
                      .clamp(80.0, 180.0),
                  child: Image.memory(bytes, fit: BoxFit.contain),
                ),
                const SizedBox(height: 8),
                const Text(
                  'Use an image you have permission to use. Check that the exact product and pack are upright, clear and fully visible.',
                  style: TextStyle(
                    fontSize: 12,
                    height: 1.35,
                    color: MoolColors.muted,
                  ),
                ),
              ],
            ),
          ),
          actions: [
            TextButton(
              style: TextButton.styleFrom(
                minimumSize: const Size(48, 48),
                textStyle: const TextStyle(
                  fontSize: 13,
                  fontWeight: FontWeight.w600,
                ),
              ),
              onPressed: () => Navigator.pop(dialogContext, false),
              child: const Text('Choose another'),
            ),
            TextButton(
              key: const Key('work-product-photo-confirm'),
              style: TextButton.styleFrom(
                minimumSize: const Size(48, 48),
                textStyle: const TextStyle(
                  fontSize: 13,
                  fontWeight: FontWeight.w600,
                ),
              ),
              onPressed: () { if (current()) Navigator.pop(dialogContext, true); },
              child: const Text('Use image'),
            ),
          ],
        ),
      );
      if (!current() || !store.isCurrent()) return;
      if (accepted == true) {
        if (!photo.matches(_photoIdentity)) {
          _reject(
            'Product details changed. Choose the image for this exact pack again.',
          );
          return;
        }
        setState(() {
          _privatePhoto = photo;
          _error = null;
        });
      }
    } on WorkGatewayException catch (error) {
      if (mounted) _reject(error.message);
    } on Object {
      if (mounted) {
        _reject(
          'The product image could not be saved. Your existing product is unchanged. Try again.',
        );
      }
    } finally {
      if (mounted) setState(() => _choosingPhoto = false);
    }
  }

  Future<void> _confirmRetirement() async {
    if (!_nativeControlReady() || _savingInventory || _choosingPhoto || (_hasCapturedReview && _hasUnsavedEdits)) return;
    final restore = !widget.product.counterSaleAllowed;
    FocusManager.instance.primaryFocus?.unfocus();
    final confirmed = await _showProductOwnerDialog<bool>(
      builder: (dialogContext) => AlertDialog(
        scrollable: true,
        titlePadding: const EdgeInsets.fromLTRB(16, 16, 16, 0),
        contentPadding: const EdgeInsets.fromLTRB(16, 10, 16, 8),
        actionsPadding: const EdgeInsets.fromLTRB(8, 0, 8, 8),
        titleTextStyle: const TextStyle(fontSize: 18, fontWeight: FontWeight.w700,
            color: MoolColors.navy),
        contentTextStyle: const TextStyle(fontSize: 14, height: 1.35,
            color: MoolColors.navy),
        title: Text(restore ? 'Resume Counter sale?' : 'Pause Counter sale?'),
        content: Text(
          restore
              ? 'Stock, history and public visibility stay unchanged. '
                'Unsaved edits are not applied.'
              : 'Stops Counter sale only. Stock, history and public visibility '
                'stay unchanged. Unsaved edits are not applied.',
        ),
        actions: [
          Flex(
            direction: MediaQuery.textScalerOf(dialogContext).scale(14) > 22
                ? Axis.vertical : Axis.horizontal,
            mainAxisSize: MainAxisSize.min,
            children: [
          Flexible(fit: FlexFit.loose, child: TextButton(
            key: const Key('work-product-retire-cancel'),
            onPressed: () => Navigator.pop(dialogContext, false),
            child: const Text('Cancel'),
          )),
          Flexible(fit: FlexFit.loose, child: TextButton(
            key: const Key('work-product-retire-confirm'),
            onPressed: () { if (_nativeControlReady()) Navigator.pop(dialogContext, true); },
            child: Text(restore ? 'Resume' : 'Pause'),
          )),
            ],
          ),
        ],
      ),
    );
    if (!mounted || confirmed != true || !_nativeControlReady()) return;
    if ((widget.session.activeWorkspace?.id ?? widget.session.workspaceId) !=
        _storeId) {
      _reject('Your store changed. Open this product in the correct store.');
      return;
    }
    if (!widget.session.workspaceCatalogueItems.any(
      (product) => product.id == widget.product.id,
    )) {
      _reject('This product is no longer in your catalogue.');
      return;
    }
    final changed = restore
        ? widget.session.restoreWorkspaceProduct(widget.product.id)
        : widget.session.retireWorkspaceProduct(widget.product.id);
    if (!changed) return;
    _finish();
  }

  Future<void> _requestEditorExit({VoidCallback? afterExit}) async {
    if (_savingInventory || _choosingPhoto || _confirmingEditorExit) return;
    if (_pendingInventorySave) {
      _reject('Saving is incomplete. Tap Save changes to retry before leaving.');
      return;
    }
    if (!_hasUnsavedEdits) {
      _finish(afterExit: afterExit);
      return;
    }
    _confirmingEditorExit = true;
    FocusManager.instance.primaryFocus?.unfocus();
    try {
      final discard = await showDialog<bool>(
        context: context,
        builder: (dialogContext) => AlertDialog(
          key: const Key('work-product-unsaved-dialog'),
          scrollable: true,
          titlePadding: const EdgeInsets.fromLTRB(16, 16, 16, 0),
          contentPadding: const EdgeInsets.fromLTRB(16, 10, 16, 8),
          actionsPadding: const EdgeInsets.fromLTRB(8, 0, 8, 8),
          title: const Text('Discard changes?', style: TextStyle(
            fontSize: 18, fontWeight: FontWeight.w700, color: MoolColors.navy)),
          content: const Text('Your edits have not been saved.', style: TextStyle(
            fontSize: 14, height: 1.35, color: MoolColors.navy)),
          actions: [
            TextButton(
              key: const Key('work-product-keep-editing'),
              onPressed: () => Navigator.pop(dialogContext, false),
              child: const Text('Keep editing'),
            ),
            TextButton(
              key: const Key('work-product-discard-edits'),
              onPressed: () => Navigator.pop(dialogContext, true),
              child: const Text('Discard changes'),
            ),
          ],
        ),
      );
      if (mounted && discard == true) _finish(afterExit: afterExit);
    } finally {
      _confirmingEditorExit = false;
    }
  }

  void _finish({VoidCallback? afterExit}) {
    FocusManager.instance.primaryFocus?.unfocus();
    // Rebuild PopScope before the approved save/discard performs its route pop.
    setState(() => _allowEditorExit = true);
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) return;
      final done = afterExit ?? widget.onDone;
      if (done != null) {
        done();
      } else {
        Navigator.pop(context);
      }
    });
  }

  @override
  void initState() {
    super.initState();
    _productEditorOwner = widget.session;
    (_openProductEditors[_productEditorOwner] ??= <Object>{}).add(_productEditorToken);
    _storeId = widget.session.activeWorkspace?.id ?? widget.session.workspaceId;
    _reviewEditorContext = widget.session.publicationPreferencesContext;
    _wasOwned =
        widget.importRow == null &&
        widget.session.workspaceCatalogueItems.any(
          (item) => item.id == widget.product.id,
        );
    if (widget.initialField case final field?) {
      _expanded[_fieldSection(field)] = true;
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!mounted) return;
        _fieldFocus[field]?.requestFocus();
        _revealImportIssue(field);
      });
    }
    if (widget.importRow case final row?) {
      final fields = _importControllers;
      for (final entry in row.rawValues.entries) {
        if (fields[entry.key] case final controller?) {
          if (WorkspaceProductImport.requiredColumns.contains(entry.key) ||
              entry.value.isNotEmpty) {
            controller.text = entry.value;
          }
        }
      }
      _initialImportInputs = {
        for (final entry in fields.entries) entry.key: entry.value.text,
      };
      if ((row.rawValues['sku'] ?? '').isEmpty &&
          !widget.product.matchesMasterCatalogueIdentity) {
        _sku.clear();
        _initialImportInputs['sku'] = '';
      }
      final field = row.issueValues.keys.firstOrNull;
      _error = row.issue;
      _errorField = field;
      if (field != null) _expanded[_fieldSection(field)] = true;
      if (field != null) _revealImportIssue(field);
    }
    for (final field in [
      _title,
      _brand,
      _pack,
      _variant,
      _barcode,
      _category,
      _composition,
      _regulatory,
      ..._contentFields.values,
      ..._packFields.values,
    ]) {
      field.addListener(_refreshIdentity);
    }
    _initialEditValues = {
      for (final entry in _importControllers.entries) entry.key: entry.value.text,
    };
    _initialVariantState = _variantState;
    if (widget.stockAdjustmentInitial case final initial?) {
      if (widget.initialData != null || widget.importRow != null || widget.purchaseScope != null ||
          widget.onDraftReviewed != null || widget.prefillCurrent?.call() == false || !_reviewEditorCurrent ||
          widget.stockAdjustmentCurrent?.call() == false || !initial.matches(widget.session, widget.product)) {
        _assistantPrefillRejected = true;
        _error = 'Stock changed. Close and reopen this exact SKU before adjusting.';
      } else {
        _stock.text = initial.quantity;
        _stockAdjustmentReason.text = initial.reason;
      }
    }
    if (widget.initialData case final initial?) {
      final controllers = _importControllers;
      if (widget.importRow != null || widget.purchaseScope != null || widget.onDraftReviewed != null ||
          widget.prefillCurrent?.call() == false || !_assistantInputCurrent ||
          !initial.matches(widget.product) || !initial.inputs.keys.every(controllers.containsKey)) {
        _assistantPrefillRejected = true;
        _error = 'Product details changed. Close and ask again.';
      } else {
        // Baseline was captured above, so proposed changes remain unsaved edits.
        for (final entry in initial.inputs.entries) { controllers[entry.key]!.text = entry.value; }
      }
    }
    if (_wasOwned && widget.purchaseScope == null && widget.importRow == null && widget.onDraftReviewed == null) {
      WidgetsBinding.instance.addPostFrameCallback((_) async {
        if (_reviewEditorCurrent) { await widget.session.workspaceProductSubmission(widget.product.id)?.restore(); }
        if (_reviewEditorCurrent) { await widget.session.workspaceProductMedia(widget.product.id)?.restore(); }
      });
    }
    _startNativeReview();
    if (_listingRecoveryRequired && !widget.session.workspaceCatalogueListingReady) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted) unawaited(_restoreListing());
      });
    }
  }

  void _refreshIdentity() => setState(() {});
  bool get _importFamilyReview => widget.onDraftReviewed != null && widget.product.variantMembership != null;

  void _loadVariantFamily(WorkspaceVariantFamily family) {
    _variantFamily = family;
    _title.text = family.title;
    _brand.text = family.brand;
    _category.text = family.categoryId;
    if (_useSharedVariantContent) {
      for (final entry in family.content.inputValues.entries) {
        _contentFields[entry.key]!.text = entry.value;
      }
    }
    _public = false;
    // Joining an unreviewed family is not a new provider visibility command.
    _listingIntentChanged = false;
    _expanded['variants'] = true;
  }

  WorkspaceVariantFamily? _variantDefinitionForSave(WorkspaceProductContent content) {
    final base = _variantFamily;
    if (base == null) {
      if (widget.product.variantMembership != null) throw const FormatException('Recover the saved product family before editing.');
      return null;
    }
    final candidate = base.copyWith(title: _title.text.trim(), brand: _brand.text.trim(),
      categoryId: _category.text.trim(), content: _useSharedVariantContent ? content : base.content);
    final member = WorkspaceVariantMembership(familyId: base.id, selections: _variantSelections,
      useSharedContent: _useSharedVariantContent);
    candidate.attributesFor(member);
    final current = widget.session.workspaceVariantFamilies.where((f) => f.id == base.id).firstOrNull;
    if (current == null) return candidate.copyWith(revision: 1);
    if (jsonEncode(candidate.copyWith(revision: current.revision).toJson()) == jsonEncode(current.toJson())) return current;
    if (base.revision != current.revision) throw const FormatException('This family changed. Reopen its latest details before saving.');
    return candidate.copyWith(revision: current.revision + 1);
  }

  void _updateVariantLabel() {
    final family = _variantFamily;
    if (family == null || widget.product.variantMembership != null) return;
    try {
      final attributes = family.attributesFor(WorkspaceVariantMembership(familyId: family.id,
        selections: _variantSelections));
      _variant.text = attributes.map((a) => a.optionLabel).join(' · ');
    } on FormatException { /* Keep incomplete choices editable. */ }
  }

  Widget _variantFamilySection() {
    final choices = {for (final f in widget.session.workspaceVariantFamilies) f.id: f};
    final family = _variantFamily;
    if (family != null) { choices[family.id] = family; }
    return _section('variants', 'work-product-variant-family-section', 'Variants & options', [
      DropdownButtonFormField<String>(
        key: ValueKey('work-product-family-${family?.id ?? 'none'}'),
        initialValue: family?.id ?? '', isExpanded: true,
        decoration: const InputDecoration(labelText: 'Product group'),
        items: [const DropdownMenuItem(value: '', child: Text('Single product')),
          for (final f in choices.values) DropdownMenuItem(value: f.id,
            child: Text(f.title, maxLines: 2, overflow: TextOverflow.ellipsis))],
        onChanged: _savingInventory || widget.product.variantMembership != null ? null : (id) => setState(() {
          _variantSelections.clear(); _siblingVariantSelections.clear();
          if (id == '') { _variantFamily = null; }
          else if (choices[id] case final selected?) { _loadVariantFamily(selected); }
        }),
      ),
      Wrap(spacing: 8, children: [
        if (!_importFamilyReview && widget.product.variantMembership == null)
          TextButton.icon(key: const Key('work-product-create-family'),
          onPressed: _savingInventory ? null : () => _editVariantOptions(create: true),
          icon: const Icon(Icons.add, size: 18), label: const Text('New product group')),
        if (family != null && !_importFamilyReview) TextButton.icon(key: const Key('work-product-edit-family'),
          onPressed: _savingInventory ? null : _editVariantOptions,
          icon: const Icon(Icons.tune, size: 18), label: const Text('Edit options')),
      ]),
      if (family != null) ...[
        const Text('Name, brand and category are shared by this group. Each combination keeps its own SKU, price and Stock.'),
        if (_importFamilyReview) const Text('To change group details or options, edit the group in Stock and import again. This review changes only this SKU.'),
        for (final dimension in family.dimensionIds) ...[
          const SizedBox(height: 10),
          Builder(builder: (_) {
            final options = family.options.where((a) => a.dimensionId == dimension).toList();
            final selected = _variantSelections[dimension];
            return DropdownButtonFormField<String>(
              key: ValueKey('work-product-option-$dimension-${options.map((o) => o.optionId).join(',')}-$selected'),
              initialValue: options.any((o) => o.optionId == selected) ? selected : null,
              isExpanded: true, decoration: InputDecoration(labelText: options.first.dimensionLabel),
              items: [for (final option in options) DropdownMenuItem(value: option.optionId,
                child: Text(option.optionLabel, maxLines: 2, overflow: TextOverflow.ellipsis))],
              onChanged: _savingInventory || widget.product.variantMembership?.selections.containsKey(dimension) == true
                ? null : (value) => setState(() {
                  if (value != null) {
                    _variantSelections[dimension] = value;
                    _siblingVariantSelections.remove(widget.product.id);
                  }
                  _updateVariantLabel();
                }),
            );
          }),
        ],
        CheckboxListTile(contentPadding: EdgeInsets.zero, controlAffinity: ListTileControlAffinity.leading,
          key: const Key('work-product-shared-family-content'),
          title: Text(_importFamilyReview ? 'Use saved group content' : 'Share description, highlights and specifications'),
          subtitle: Text(_importFamilyReview
            ? 'Untick for this SKU’s content exceptions. This import does not change the group.'
            : 'Edits apply to group members using shared content. Untick for this SKU’s exceptions.'),
          value: _useSharedVariantContent, onChanged: _savingInventory ? null : (value) => setState(() {
            _useSharedVariantContent = value ?? true;
            if (_useSharedVariantContent) {
              for (final entry in family.content.inputValues.entries) {
                _contentFields[entry.key]!.text = entry.value;
              }
            }
          })),
        if (_wasOwned && widget.importRow == null && widget.onDraftReviewed == null && widget.purchaseScope == null)
          _variantPublicationControls(family)
        else
          const Text('Save this SKU first. Options stay private until the group and each SKU are reviewed.'),
      ],
    ], initiallyExpanded: family != null);
  }

  Widget _variantPublicationControls(WorkspaceVariantFamily family) {
    if (!_reviewEditorCurrent) { return const Text('Your Store changed. Reopen this product before checking review.'); }
    final publisher = widget.session.workspaceVariantFamilyPublisher(family.id);
    if (publisher == null) {
      return const Padding(padding: EdgeInsets.only(top: 8), child: Text(
        'Saved group options stay private. Review submission is not connected yet.',
        key: Key('work-product-family-submission-unavailable')));
    }
    return ListenableBuilder(listenable: Listenable.merge([publisher, widget.session, ..._importControllers.values]),
      builder: (context, _) {
        final busy = !_reviewEditorCurrent || (_hasCapturedReview && !_assistantInputCurrent) || !publisher.active || _savingInventory || widget.session.workspaceVariantFamilyBusy(family.id);
        final pending = publisher.pending != null;
        final actionStyle = TextButton.styleFrom(minimumSize: const Size(48, 48),
          padding: const EdgeInsets.symmetric(horizontal: 8));
        return Padding(key: const {'AI-ACT-224','AI-ACT-374'}.contains(widget.nativeReview?.actionId) ? _nativeReviewTargetKey : null, padding: const EdgeInsets.only(top: 8), child: Column(crossAxisAlignment: CrossAxisAlignment.start,
          key: const Key('work-product-family-submission'), children: [
            Text(publisher.message ?? 'Save stays private. Submit the saved combinations for review separately.',
              style: Theme.of(context).textTheme.bodySmall),
            if (_hasUnsavedEdits && !pending) Text('Save current product changes before submitting the group.',
              style: Theme.of(context).textTheme.bodySmall),
            Wrap(spacing: 8, runSpacing: 2, children: [
              TextButton.icon(key: const Key('work-product-family-check-status'),
                style: actionStyle,
                onPressed: busy ? null : () async {
                  if (!_nativeControlReady()) return;
                  await widget.session.checkWorkspaceVariantFamily(family.id, original: pending, current: _capturedOwnerCurrent, inputCurrent: _capturedRequestCurrent);
                  if (_reviewEditorCurrent) setState(() {});
                }, icon: Icon(pending ? Icons.history : Icons.refresh, size: 18),
                label: Text(busy ? 'Checking…' : pending ? 'Check original submission' : 'Check review status')),
              if (!pending && publisher.headLoaded) TextButton.icon(key: const Key('work-product-family-submit'),
                style: actionStyle,
                onPressed: busy || _hasUnsavedEdits || !publisher.canSubmit ? null : () async {
                  if (!_nativeControlReady()) return;
                  await widget.session.submitWorkspaceVariantFamily(family.id,
                    inputCurrent: () => _reviewEditorCurrent && (!_hasCapturedReview || _assistantInputCurrent) && !_hasUnsavedEdits && !_savingInventory && _variantFamily?.id == family.id);
                  if (_reviewEditorCurrent) setState(() {});
                }, icon: const Icon(Icons.send_outlined, size: 18), label: const Text('Submit group for review')),
              if (pending && publisher.canRetryOriginal) TextButton.icon(key: const Key('work-product-family-retry-original'),
                style: actionStyle,
                onPressed: busy ? null : () async {
                  if (!_nativeControlReady()) return;
                  await widget.session.checkWorkspaceVariantFamily(family.id, retry: true, current: _capturedOwnerCurrent, inputCurrent: _capturedRequestCurrent);
                  if (_reviewEditorCurrent) setState(() {});
                }, icon: const Icon(Icons.replay, size: 18), label: const Text('Retry original submission')),
            ]),
          ]));
      });
  }

