  Widget _productDraftControls() {
    final controller = widget.session.workspaceSavedProductDraft(widget.product.id);
    if (controller == null) return const SizedBox.shrink();
    Future<void> check() async {
      if (!_reviewEditorCurrent || controller.busy) return;
      if (await controller.load() && controller.pending != null && _reviewEditorCurrent) await controller.recover();
    }
    return AnimatedBuilder(animation: controller, builder: (context, _) => Padding(
      padding: const EdgeInsets.symmetric(vertical: 4), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        if (controller.busy) const LinearProgressIndicator(minHeight: 2),
        Text(widget.session.workspaceSavedProductDraftMatchesLocal(widget.product.id)
          ? 'Product sync confirmed.' : controller.pending != null
          ? 'Check the previous Save before syncing again.' : 'Product sync is not confirmed.',
          style: const TextStyle(fontSize: 12, color: MoolColors.muted)),
        Wrap(spacing: 8, children: [
          TextButton.icon(onPressed: controller.busy || !_reviewEditorCurrent || _savingInventory ? null : check,
            icon: const Icon(Icons.sync, size: 18), label: const Text('Check sync')),
          if (controller.pending != null && controller.state == WorkspaceProductDraftWriteState.notFound)
            TextButton.icon(onPressed: controller.busy || !_reviewEditorCurrent || _hasUnsavedEdits || _savingInventory ? null : () async {
              await controller.recover(retryOriginal: true);
            }, icon: const Icon(Icons.replay, size: 18), label: const Text('Retry original Save')),
        ]),
      ])));
  }
  bool _openingCustomerPreview = false;
  Future<void> _openSavedCustomerPreview() async {
    if (!mounted || _openingCustomerPreview || !_reviewEditorCurrent) return;
    setState(() => _openingCustomerPreview = true);
    try {
    if (!_reviewEditorCurrent || _hasUnsavedEdits || _savingInventory || !await widget.session.workspaceInventorySaved || !mounted || !_reviewEditorCurrent) return;
    final saved = widget.session.workspaceCatalogueItems.where((item) => item.id == widget.product.id).firstOrNull;
    if (saved == null) return;
    final channels = [if (saved.retailEnabled) BuyV2Destination.shop,
      if (saved.wholesaleOffer?.enabled == true && saved.wholesaleOffer!.valid) BuyV2Destination.wholesale];
    if (channels.isEmpty) return;
    final channel = channels.length == 1 ? channels.single : await showModalBottomSheet<BuyV2Destination>(
      context: context, builder: (sheet) => SafeArea(child: Column(mainAxisSize: MainAxisSize.min, children: [
        for (final value in channels) ListTile(title: Text(value == BuyV2Destination.shop ? 'Retail'
          : saved.wholesaleOffer!.saleType == BuyV2WholesaleSaleType.bulk ? 'Bulk' : 'Wholesale'),
          onTap: () => Navigator.pop(sheet, value)),
      ])));
    if (channel == null || !mounted || !_reviewEditorCurrent || _hasUnsavedEdits ||
        !identical(widget.session.workspaceCatalogueItems.where((item) => item.id == saved.id).firstOrNull, saved)) { return; }
    if (widget.session.gateway is! ReviewWorkGateway && widget.session.workspaceProductPreviewConnectionConfigured) {
      bool current() => mounted && _reviewEditorCurrent && !_hasUnsavedEdits && !_savingInventory &&
        identical(widget.session.workspaceCatalogueItems.where((item) => item.id == saved.id).firstOrNull, saved);
      final kind = channel == BuyV2Destination.shop ? BuyV2OfferClass.retail
        : saved.wholesaleOffer?.saleType == BuyV2WholesaleSaleType.bulk ? BuyV2OfferClass.bulk : BuyV2OfferClass.wholesale;
      final frame = await widget.session.readWorkspaceProductPreviewSources(current: current);
      if (!current() || frame == null || !frame.current()) return;
      final copies = frame.references.where((row) => row.skuId == saved.id && row.channels.contains(kind.name)).toList(growable: false);
      if (copies.isEmpty) {
        widget.session.showError('No saved copy is available for this channel.'); return;
      }
      final selected = copies.length == 1 ? copies.single : await showModalBottomSheet<WorkspaceProductPreviewReference>(
        context: context, builder: (sheet) => SafeArea(child: Column(mainAxisSize: MainAxisSize.min, children: [
          for (final copy in copies) ListTile(title: Text(switch (copy.kind) {
            WorkspaceProductOriginalKind.savedDraft => 'Saved draft',
            WorkspaceProductOriginalKind.submittedOriginal => 'Submitted copy',
            WorkspaceProductOriginalKind.catalogueSku => 'Verified product copy',
          }), subtitle: Text([copy.title, copy.pack].where((value) => value.isNotEmpty).join(' · ')),
            onTap: () => Navigator.pop(sheet, copy)),
        ])));
      if (selected == null || !current() || !frame.current()) return;
      final original = await widget.session.readWorkspaceProductPreviewOriginal(saved.id, selected.kind,
        expected: selected, current: () => current() && frame.current());
      if (original == null || !original.current() || !current()) return;
      if (selected.kind == WorkspaceProductOriginalKind.catalogueSku && selected.publicListingRequested == true) {
        final entry = await widget.session.readWorkspacePublishedProductPreview(original.original, kind,
          current: () => current() && original.current());
        if (!current() || !original.current()) return;
        if (entry == null) {widget.session.showError('The customer listing could not be verified. Try again later.'); return;}
        final router = GoRouter.of(context);
        await router.push<void>(Uri(path: '/app/buy', queryParameters: {'sub': channel.name, 'view': 'product',
          'workspaceProduct': saved.id, 'product': entry.product.id, 'return': router.state.uri.toString()}).toString());
        return;
      }
      final presentation = original.original.presentation(storeName: widget.session.activeWorkspace!.name, channel: kind);
      await Navigator.of(context).push<void>(MaterialPageRoute(builder: (_) => OwnedStoreProductCustomerPreview.original(
        work: widget.session, presentation: presentation, sourceCurrent: original.current)));
      return;
    }
    if (widget.session.gateway is! ReviewWorkGateway) {
      final kind = channel == BuyV2Destination.shop ? BuyV2OfferClass.retail
        : saved.wholesaleOffer?.saleType == BuyV2WholesaleSaleType.bulk ? BuyV2OfferClass.bulk : BuyV2OfferClass.wholesale;
      final source = await widget.session.readWorkspaceSavedProductPreview(saved.id, kind,
        current: () => mounted && _reviewEditorCurrent && !_hasUnsavedEdits && !_savingInventory);
      if (!mounted || !_reviewEditorCurrent) return;
      if (source == null || !source.current()) {
        widget.session.showError('The saved product could not be verified. Check product sync before previewing.'); return;
      }
      await Navigator.of(context).push<void>(MaterialPageRoute(builder: (_) => OwnedStoreProductCustomerPreview(
        work: widget.session, controller: source.controller, presentation: source.presentation, sourceCurrent: source.current)));
      return;
    }
    await Navigator.of(context).push<void>(MaterialPageRoute(builder: (_) => SavedStoreProductCustomerPreview(
      work: widget.session, saved: saved, channel: channel)));
    } catch (_) {
      if (mounted && _reviewEditorCurrent) widget.session.showError('This product copy could not be verified. Reopen preview to try again.');
    } finally {if (mounted) setState(() => _openingCustomerPreview = false);}
  }

  Future<void> _editVariantOptions({bool create = false, List<StoreProductVariantInitialDimension>? initialDimensions}) async {
    if (!_nativeControlReady()) return;
    if (_savingInventory || _saved) return;
    if (_title.text.trim().isEmpty) { _reject('Enter the product name before creating its group.', field: 'title'); return; }
    final base = create ? null : _variantFamily;
    final stamp = DateTime.now().microsecondsSinceEpoch;
    var counter = 0;
    final dimensions = <({String id, String label, BuyV2VariantDimensionKind kind, String values})>[
      if (base != null) for (final id in base.dimensionIds)
        (id: id, label: base.options.firstWhere((a) => a.dimensionId == id).dimensionLabel,
          kind: base.options.firstWhere((a) => a.dimensionId == id).kind,
          values: base.options.where((a) => a.dimensionId == id).map((a) => a.optionLabel).join('\n')),
    ];
    void addDimension() => dimensions.add((id: 'dimension-$stamp-${counter++}', label: '',
      kind: BuyV2VariantDimensionKind.other, values: ''));
    if (initialDimensions != null) {
      for (final initial in initialDimensions) {
        final index = dimensions.indexWhere((dimension) => dimension.id == initial.dimensionId);
        if (initial.dimensionId != null && index < 0) return;
        final next = (id: initial.dimensionId ?? 'dimension-$stamp-${counter++}',
          label: initial.label, kind: initial.kind, values: initial.options);
        if (index < 0) { dimensions.add(next); } else { dimensions[index] = next; }
      }
    }
    if (dimensions.isEmpty) addDimension();
    final members = [if (base != null) for (final p in widget.session.workspaceCatalogueItems)
      if (p.variantMembership?.familyId == base.id) p];
    final staged = <String, Map<String, String>>{
      for (final member in members) member.id: {
        ...member.variantMembership!.selections,
        ...?_siblingVariantSelections[member.id],
        if (member.id == widget.product.id) ..._variantSelections,
      },
    };
    final assignments = <String, Map<String, String>>{
      for (final member in members) member.id: {
        for (final option in base!.options)
          if (staged[member.id]?[option.dimensionId] == option.optionId)
            option.dimensionId: option.optionLabel,
      },
    };
    String? error;
    BuildContext? focusedInput;
    bool revealPending = false;
    double? inputViewportDimension;
    void revealInput() {
      if (revealPending) return;
      revealPending = true;
      WidgetsBinding.instance.addPostFrameCallback((_) {
        revealPending = false;
        final target = focusedInput;
        if (target != null && target.mounted) Scrollable.ensureVisible(target, alignment: .15);
      });
    }
    Widget revealOnFocus(Widget input) => Builder(builder: (inputContext) => Focus(
      skipTraversal: true,
      onFocusChange: (focused) {
        if (focused) {
          focusedInput = inputContext;
          revealInput();
        } else if (focusedInput == inputContext) {
          focusedInput = null;
        }
      },
      child: input,
    ));
    final result = await _showProductOwnerDialog<({WorkspaceVariantFamily family, Map<String, Map<String, String>> selections})>(
      builder: (dialogContext) => StatefulBuilder(builder: (context, update) => NotificationListener<ScrollMetricsNotification>(
          onNotification: (notification) {
            if (notification.depth == 0 && notification.metrics.axis == Axis.vertical &&
                inputViewportDimension != notification.metrics.viewportDimension) {
              inputViewportDimension = notification.metrics.viewportDimension;
              revealInput();
            }
            return false;
          },
          child: AlertDialog(
        scrollable: true,
        title: Text(create ? 'New product group' : 'Edit group options'),
        content: SizedBox(width: 440, child: Column(
          mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.stretch, children: [
          const Text('Add dimensions such as Colour, Storage, Size or Flavour. Enter one option per line. Only combinations you save become SKUs.'),
          for (var i = 0; i < dimensions.length; i++) ...[
            const SizedBox(height: 16),
            revealOnFocus(TextFormField(key: ValueKey('family-dimension-${dimensions[i].id}'),
              initialValue: dimensions[i].label, decoration: const InputDecoration(labelText: 'Dimension name'),
              onChanged: (value) { final old = dimensions[i]; dimensions[i] = (id: old.id, label: value, kind: old.kind, values: old.values); })),
            const SizedBox(height: 8),
            DropdownButtonFormField<BuyV2VariantDimensionKind>(
              initialValue: dimensions[i].kind, isExpanded: true,
              decoration: const InputDecoration(labelText: 'Option type'),
              items: [for (final kind in BuyV2VariantDimensionKind.values) DropdownMenuItem(
                value: kind, child: Text(switch (kind) {
                  BuyV2VariantDimensionKind.colour => 'Colour', BuyV2VariantDimensionKind.size => 'Size',
                  BuyV2VariantDimensionKind.storage => 'Storage', BuyV2VariantDimensionKind.pack => 'Pack',
                  BuyV2VariantDimensionKind.other => 'Other',
                }))],
              onChanged: (value) { if (value == null) return; final old = dimensions[i];
                dimensions[i] = (id: old.id, label: old.label, kind: value, values: old.values); }),
            const SizedBox(height: 8),
            revealOnFocus(TextFormField(key: ValueKey('family-options-${dimensions[i].id}'),
              initialValue: dimensions[i].values, minLines: 2, maxLines: 6,
              decoration: const InputDecoration(labelText: 'Options'),
              onChanged: (value) => update(() { final old = dimensions[i];
                dimensions[i] = (id: old.id, label: old.label, kind: old.kind, values: value); }))),
            if (base != null)
              for (final member in members) ...[
                if (!member.variantMembership!.selections.containsKey(dimensions[i].id)) ...[
                const SizedBox(height: 8),
                DropdownButtonFormField<String>(
                  key: ValueKey('family-assign-${member.id}-${dimensions[i].id}-${dimensions[i].values}'),
                  initialValue: dimensions[i].values.split('\n').map((s) => s.trim()).contains(assignments[member.id]?[dimensions[i].id])
                    ? (assignments[member.id]?[dimensions[i].id]) : null,
                  isExpanded: true, decoration: InputDecoration(labelText: 'Choose for SKU ${member.sku}'),
                  items: [for (final label in dimensions[i].values.split('\n').map((s) => s.trim()).where((s) => s.isNotEmpty).toSet())
                    DropdownMenuItem(value: label, child: Text(label, overflow: TextOverflow.ellipsis))],
                  onChanged: (value) { if (value != null) {
                    (assignments[member.id] ??= {})[dimensions[i].id] = value;
                  } }),
                ],
              ],
          ],
          TextButton.icon(onPressed: dimensions.length >= 8 ? null : () => update(addDimension),
            icon: const Icon(Icons.add), label: const Text('Add dimension')),
          if (error != null) Text(error!, style: TextStyle(color: Theme.of(context).colorScheme.error)),
        ])),
        actions: [TextButton(onPressed: () => Navigator.pop(dialogContext), child: const Text('Cancel')),
          FilledButton(onPressed: () {
            if (!_nativeControlReady()) return;
            try {
              final options = <BuyV2VariantAttribute>[];
              for (final dimension in dimensions) {
                for (final label in dimension.values.split('\n').map((s) => s.trim()).where((s) => s.isNotEmpty)) {
                  final previous = base?.options.where((a) => a.dimensionId == dimension.id &&
                    a.optionLabel.toLowerCase() == label.toLowerCase()).firstOrNull;
                  options.add(BuyV2VariantAttribute(dimensionId: dimension.id, dimensionLabel: dimension.label.trim(),
                    kind: dimension.kind, optionId: previous?.optionId ?? 'option-$stamp-${counter++}',
                    optionLabel: label, swatchArgb: dimension.kind == BuyV2VariantDimensionKind.colour ? previous?.swatchArgb : null));
                }
              }
              final content = WorkspaceProductContent.parse({for (final e in _contentFields.entries) e.key: e.value.text});
              final family = WorkspaceVariantFamily(id: base?.id ?? 'family-$stamp', revision: base?.revision ?? 1,
                title: _title.text.trim(), brand: _brand.text.trim(), categoryId: _category.text.trim(), options: options,
                content: _useSharedVariantContent ? content : base?.content ?? content);
              if (!family.valid) throw const FormatException('Use unique dimension names and non-empty, unique options.');
              final selected = <String, Map<String, String>>{};
              for (final member in members) {
                final values = {...member.variantMembership!.selections};
                for (final dimension in family.dimensionIds.where((id) => !member.variantMembership!.selections.containsKey(id))) {
                  final label = assignments[member.id]?[dimension];
                  final option = family.options.where((a) => a.dimensionId == dimension && a.optionLabel == label).firstOrNull;
                  if (option == null) throw const FormatException('Choose the new option for every saved SKU. Nothing has been saved yet.');
                  values[dimension] = option.optionId;
                }
                family.attributesFor(WorkspaceVariantMembership(familyId: family.id, selections: values));
                selected[member.id] = values;
              }
              Navigator.pop(dialogContext, (family: family, selections: selected));
            } on FormatException catch (failure) { update(() => error = failure.message); }
          }, child: const Text('Use these options'))],
      ))));
    if (!mounted || result == null || !_nativeControlReady()) return;
    setState(() {
      if (create) { _variantSelections.clear(); _siblingVariantSelections.clear(); }
      _variantFamily = result.family;
      _siblingVariantSelections.addAll(result.selections);
      if (result.selections[widget.product.id] case final selected?) {
        _variantSelections..clear()..addAll(selected);
      }
      _loadVariantFamily(result.family);
      _updateVariantLabel();
    });
  }

  void _revealImportIssue(String field) {
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) return;
      final target = _fieldKeys[field]?.currentContext;
      if (target != null) {
        unawaited(
          Scrollable.ensureVisible(
            target,
            alignment: .15,
            duration: const Duration(milliseconds: 180),
          ),
        );
      }
    });
  }

