      controller.dispose();
    }
    for (final node in _fieldFocus.values) {
      node.dispose();
    }
    super.dispose();
  }

  final _stockAdjustmentReason = TextEditingController();
  bool _stockAdjustmentCommitted = false;
  String? _stockAdjustmentCommittedInput;
  bool get _stockAdjustmentOnlyEdits => _importControllers.entries.every((entry) =>
      entry.key == 'stock' || entry.value.text == _initialEditValues[entry.key]) &&
    _public == widget.product.publicListing && _available == widget.product.available &&
    _privatePhoto == widget.product.privatePhoto && _variantState == _initialVariantState;

  Future<void> _saveStockAdjustment() async {
    final initial = widget.stockAdjustmentInitial!;
    if (!_reviewEditorCurrent || _assistantPrefillRejected || !_stockAdjustmentOnlyEdits) {
      _reject('Stock source or other product fields changed. Reopen Stock; use Edit product for other changes.', field: 'stock');
      return;
    }
    final input = jsonEncode([_stock.text, _stockAdjustmentReason.text]);
    if (_stockAdjustmentCommitted && input != _stockAdjustmentCommittedInput) {
      _reject('An earlier Stock adjustment is retained. Check its saved quantity before another change.', field: 'stock');
      return;
    }
    if (!_stockAdjustmentCommitted && (widget.stockAdjustmentCurrent?.call() == false ||
        !initial.matches(widget.session, widget.product))) {
      _reject('Stock changed. Close and reopen this exact SKU before adjusting.', field: 'stock');
      return;
    }
    final quantity = int.tryParse(_stock.text.trim());
    if (quantity == null || quantity < 0) {
      _reject('Enter the available stock.', field: 'stock'); return;
    }
    if(quantity>(1<<31)){
      _reject('Enter a quantity between 0 and 2,147,483,648.',field:'stock');return;
    }
    if (_stockAdjustmentReason.text.trim().isEmpty) {
      _reject('Choose why the quantity changed.', field: 'stockAdjustmentReason'); return;
    }
    setState(() => _savingInventory = true);
    try {
      if (!_stockAdjustmentCommitted) {
        if (!_reviewEditorCurrent || widget.stockAdjustmentCurrent?.call() == false ||
            !initial.matches(widget.session, widget.product)) return;
        // The original quantity/reason operation owns the movement. Never use
        // generic product editing here or call this again after it returns true.
        if (!widget.session.updateWorkspaceStock(productId: widget.product.id, quantity: quantity,
            reason: _stockAdjustmentReason.text)) {
          _reject(widget.session.errorMessage ?? 'Stock is unavailable. Keep this adjustment and recover the original Store.');
          return;
        }
        _stockAdjustmentCommitted = true;
        _stockAdjustmentCommittedInput = input;
      }
      if (widget.session.localInventoryEnabled) {
        final saved = _pendingInventorySave ? await widget.session.retryWorkspaceInventorySave()
          : await widget.session.workspaceInventorySaved;
        if (!mounted) return;
        if (!saved) {
          _pendingInventorySave = true;
          _reject(widget.session.workspaceInventoryError ?? 'The original Stock save needs recovery. Retry this same adjustment.');
          return;
        }
        _pendingInventorySave = false;
      }
      if (!_reviewEditorCurrent) {
        _reject('Store access changed. Check the original Stock adjustment before another change.'); return;
      }
      _saved = true;
      _finish(afterExit: widget.onSaved);
    } finally { if (mounted) setState(() => _savingInventory = false); }
  }

  Future<void> _save() async {
    if (!mounted || _saved || _savingInventory || _choosingPhoto) return;
    if (widget.stockAdjustmentInitial != null) { await _saveStockAdjustment(); return; }
    if (!_assistantInputCurrent) {
      _reject('Product details changed. Close and reopen this product before saving.');
      return;
    }
    final listingRequested = _public, listingWasChanged = _listingIntentChanged;
    if (listingWasChanged && _listingRecoveryRequired &&
        (!widget.session.workspaceCatalogueListingReady ||
          widget.session.workspaceCatalogueListingPending ||
          widget.session.workspaceCatalogueListingBusy)) {
      _reject('Check the saved listing update before changing its visibility. Your product edits are kept.');
      return;
    }
    setState(() => _savingInventory = true);
    try {
      if (widget.importRow != null) {
        _applyImportCorrection();
        return;
      }
      if ((widget.session.activeWorkspace?.id ?? widget.session.workspaceId) !=
          _storeId || (widget.purchaseScope != null &&
              widget.purchaseScope != widget.session.workspaceSupplierScope)) {
        setState(
          () => _error =
              'Your store changed. Close this product and open it in the correct store.',
        );
        return;
      }
      if (widget.session.localInventoryEnabled &&
          widget.onDraftReviewed == null) {
        final ready = await widget.session.loadWorkspaceInventory(retry: true);
        if (!mounted) return;
        if (!ready || !_assistantInputCurrent ||
            (widget.session.activeWorkspace?.id ??
                    widget.session.workspaceId) !=
                _storeId || (widget.purchaseScope != null &&
                    widget.purchaseScope != widget.session.workspaceSupplierScope)) {
          setState(
            () => _error =
                widget.session.workspaceInventoryError ??
                'Return to this product’s Store before saving.',
          );
          return;
        }
      }
      if (!_wasOwned &&
          !_pendingInventorySave &&
          widget.session.workspaceCatalogueItems.any(
            (item) =>
                item.id == widget.product.id ||
                (item.canonicalId == widget.product.canonicalId &&
                    item.pack == _pack.text.trim() &&
                    item.variant == _variant.text.trim() &&
                    item.barcode == _barcode.text.trim()),
          )) {
        setState(
          () => _error =
              'This product was already added. Open it from Store stock to edit.',
        );
        return;
      }
      final duplicate = widget.session.workspaceCatalogueItems.any(
        (item) =>
            item.id != widget.product.id &&
            item.sku.trim().toLowerCase() == _sku.text.trim().toLowerCase(),
      );
      if (duplicate) {
        _reject(
          'This store SKU is already in use. Choose a different SKU.',
          field: 'sku',
        );
        return;
      }
      // Preserve the existing large-price editor range, not the narrower CSV
      // or trade-input ceiling. All money comparisons below are in paise.
      final purchase = workspacePriceMinorFromInput(_purchase.text, maximumMinor: 9007199254740991);
      final selling = workspacePriceMinorFromInput(_selling.text, maximumMinor: 9007199254740991);
      final mrp = workspacePriceMinorFromInput(_mrp.text, maximumMinor: 9007199254740991);
      final stock = widget.purchaseScope != null ? 0 : _stockMode == WorkspaceStockMode.availabilityOnly
          ? widget.product.stock.clamp(0, 1 << 31).toInt()
          : int.tryParse(_stock.text.trim());
      final lowStockThreshold = int.tryParse(_lowStockThreshold.text.trim());
      final minimumOrder = int.tryParse(_minimumOrder.text.trim());
      final issue = workspaceProductValuesIssue(
        title: _title.text.trim(),
        brand: _brand.text.trim(),
        pack: _pack.text.trim(),
        category: _category.text.trim(),
        sku: _sku.text.trim(),
        purchase: purchase,
        selling: selling,
        stock: stock,
        mrp: mrp,
        lowStockThreshold: lowStockThreshold,
        minimumOrder: minimumOrder,
        delivery: _delivery.text.trim(),
      );
      if (issue != null) {
        _reject(issue.message, field: issue.field);
        return;
      }
      if (_privatePhoto != null && _matchingPhoto == null) {
        _reject(
          'Product details changed. Choose the image for this exact pack again, or remove it before saving.',
        );
        return;
      }
      if (!_categories.containsKey(_category.text.trim())) {
        _reject('Choose a category from the list.', field: 'categoryId');
        return;
      }
      if (_mrp.text.trim().isNotEmpty && mrp == null) {
        _reject('Enter MRP with at most two decimal places, or leave it empty.', field: 'mrp');
        return;
      }
      late final WorkspaceProductContent content;
      try {
        content = WorkspaceProductContent.parse({
          for (final entry in _contentFields.entries)
            entry.key: entry.value.text,
        });
      } on FormatException catch (error) {
        _reject(
          error.message.substring(error.message.indexOf(':') + 1).trim(),
          field: error.message.split(':').first,
        );
        return;
      }
      late final WorkspaceSellingInputs sellingInputs;
      try {
        sellingInputs = WorkspaceSellingInputs.parse(
          _sellingInputValues,
          clearBlankTiers: true,
          existingMeasure: widget.product.packMeasure,
          existingWholesale: widget.product.wholesaleOffer,
          existingRetailEnabled: widget.product.retailEnabled,
          existingRetailTax: widget.product.retailTax,
          existingWholesaleTax: widget.product.wholesaleTax,
          existingSupplierGst: widget.product.supplierGst,
          clearBlankTaxes: true,
        );
      } on FormatException catch (error) {
        final field = error.message.split(':').first;
        _reject(
          error.message.substring(error.message.indexOf(':') + 1).trim(),
          field: field,
        );
        return;
      }
      if (sellingInputs.wholesale?.enabled == true &&
          mrp != null &&
          sellingInputs.wholesale!.priceMinor > mrp) {
        _reject(
          'Wholesale price cannot exceed the pack MRP.',
          field: 'wholesalePrice',
        );
        return;
      }
      if (sellingInputs.supplierGst == null && widget.product.supplierGst == null &&
          !widget.product.legacySupplierTaxInactive && sellingInputs.retailEnabled &&
          sellingInputs.retailTax?.validForPrice(selling!) == false) {
        _reject('Included tax cannot exceed the selling price; check the amount and basis.', field: 'retailTaxAmount');
        return;
      }
      final tradeTax = sellingInputs.wholesaleTax, trade = sellingInputs.wholesale;
      if (sellingInputs.supplierGst == null && widget.product.supplierGst == null &&
          !widget.product.legacySupplierTaxInactive && tradeTax != null && trade != null && trade.enabled &&
          [trade.priceMinor, ...trade.tiers.map((t) => t.packPriceMinor)].any((p) => !tradeTax.validForPrice(p))) {
        _reject('Check the trade tax against every quantity price.', field: 'wholesaleTaxAmount');
        return;
      }
      final measureChanged =
          jsonEncode(sellingInputs.measure?.toJson()) !=
          jsonEncode(widget.product.packMeasure?.toJson());
      final purchaseMinor = purchase!, sellingMinor = selling!;
      final exact = widget.product.usesMinorAmounts || purchaseMinor % 100 != 0 ||
          sellingMinor % 100 != 0 || mrp != null && mrp % 100 != 0 ||
          purchaseMinor > 214748364700 || sellingMinor > 214748364700 ||
          mrp != null && mrp > 214748364700;
      final reviewedProduct = widget.product.copyWith(
        supplierGst: sellingInputs.supplierGst,
        clearSupplierGst: sellingInputs.supplierGst == null,
        retailTax: sellingInputs.retailTax,
        wholesaleTax: sellingInputs.wholesaleTax,
        clearRetailTax: sellingInputs.retailTax == null,
        clearWholesaleTax: sellingInputs.wholesaleTax == null,
        variantMembership: _variantFamily == null ? null : WorkspaceVariantMembership(
          familyId: _variantFamily!.id, selections: _variantSelections,
          useSharedContent: _useSharedVariantContent),
        privatePhoto: _matchingPhoto,
        clearPrivatePhoto: _matchingPhoto == null,
        content: content,
        packMeasure: sellingInputs.measure,
        wholesaleOffer: sellingInputs.wholesale,
        retailEnabled: sellingInputs.retailEnabled,
        categoryId: _category.text.trim(),
        brand: _brand.text.trim(),
        title: _title.text.trim(),
        variant: _variant.text.trim(),
        pack: _pack.text.trim(),
        sku: _sku.text.trim(),
        barcode: _barcode.text.trim(),
        purchasePrice: exact ? null : purchaseMinor ~/ 100,
        sellingPrice: exact ? null : sellingMinor ~/ 100,
        purchasePriceMinor: exact ? purchaseMinor : null,
        sellingPriceMinor: exact ? sellingMinor : null,
        mrp: exact || mrp == null ? null : mrp ~/ 100,
        mrpMinor: exact ? mrp : null,
        clearMrp: _mrp.text.trim().isEmpty,
        stock: stock,
        unitPrice:
            _unitPrice.text.trim().isEmpty ||
                _unitPrice.text.trim() == widget.product.unitPrice
            ? '₹${workspacePriceInputFromMinor(sellingMinor)}/${_pack.text.trim()}'
            : _unitPrice.text.trim(),
        deliveryPromise: _delivery.text.trim(),
        origin: _origin.text.trim(),
        visualLabel: _visualLabel.text.trim().isEmpty
            ? '${_brand.text.trim()} ${_title.text.trim()} ${_pack.text.trim()}'
            : _visualLabel.text.trim(),
        minimumOrder: minimumOrder,
        returnPolicy: _returnPolicy.text.trim(),
        composition: _composition.text.trim(),
        regulatoryNote: _regulatory.text.trim(),
        compliance: _packInformation,
        catalogueFactsRequireReview: _factsNeedReview || measureChanged || _variantFamily != null,
        available: widget.purchaseScope != null ? false : _stockMode == WorkspaceStockMode.availabilityOnly ||
                (_wasOwned && !widget.product.available)
            ? _available
            : stock! > 0,
        publicListing:
            widget.purchaseScope == null && _variantFamily == null && _public &&
            _catalogueMatched &&
            !_factsNeedReview &&
            !measureChanged &&
            (_stockMode == WorkspaceStockMode.availabilityOnly
                ? _available
                : stock! > 0),
        stockMode: _stockMode,
        lowStockThreshold: lowStockThreshold,
      );
      if (widget.onDraftReviewed != null) {
        WorkspaceVariantFamily.validateInventory(widget.session.workspaceVariantFamilies, [reviewedProduct]);
        _saved = true;
        FocusManager.instance.primaryFocus?.unfocus();
        _finish(afterExit: () => widget.onDraftReviewed!(
          reviewedProduct.copyWith(publicListing: false)));
        return;
      }
      if (!_assistantInputCurrent) {
        _reject('Product details changed. Close and reopen this product before saving.');
        return;
      }
      if (!widget.session.addOrUpdateWorkspaceProduct(
        reviewedProduct, stockEntryMethod: widget.stockEntryMethod,
        variantFamily: _variantDefinitionForSave(content),
        variantSelections: {
          ..._siblingVariantSelections,
          if (_variantFamily != null) widget.product.id: Map.of(_variantSelections),
        })) {
        _reject('Goods receipt is being saved. Your changes are kept; try again when it finishes.');
        return;
      }
      if (widget.session.localInventoryEnabled) {
        final persisted = _pendingInventorySave
            ? await widget.session.retryWorkspaceInventorySave()
            : await widget.session.workspaceInventorySaved;
        if (!mounted) return;
        if (!persisted ||
            (widget.session.activeWorkspace?.id ??
                    widget.session.workspaceId) !=
                _storeId || (widget.purchaseScope != null &&
                    widget.purchaseScope != widget.session.workspaceSupplierScope)) {
          _pendingInventorySave = true;
          setState(
            () => _error =
                widget.session.workspaceInventoryError ??
                'The Store changed before saving finished. Check its stock before continuing.',
          );
          return;
        }
      }
      final productSync = await widget.session.syncWorkspaceSavedProductDraft(reviewedProduct.id, origin: widget.masterOrigin,
        current: () => mounted && _reviewEditorCurrent &&
          (widget.session.activeWorkspace?.id ?? widget.session.workspaceId) == _storeId);
      if (!mounted || (widget.session.activeWorkspace?.id ?? widget.session.workspaceId) != _storeId) return;
      if (listingWasChanged && widget.purchaseScope == null && widget.onDraftReviewed == null) {
        // Inventory already belongs to its original native save. A follow-on
        // listing request needs the same assistant form owner, not a new actor.
        if (_hasCapturedReview && !_reviewEditorCurrent) {
          _reject('Store access changed. Check saved stock in the original Store before changing listing.');
          return;
        }
        await widget.session.requestWorkspaceProductListing(reviewedProduct.id, listed: listingRequested, current: _capturedOwnerCurrent);
        if (!mounted || (widget.session.activeWorkspace?.id ?? widget.session.workspaceId) != _storeId) return;
      }
      _saved = true;
      if (widget.onSaved != null) {
        FocusManager.instance.primaryFocus?.unfocus();
        if (!listingWasChanged) {
          widget.session.showNotice(productSync != null && productSync != WorkspaceProductDraftWriteState.saved
              ? 'Product sync is unconfirmed. Check this product before continuing.'
              : widget.purchaseScope == null ? 'Saved to Store stock.'
              : 'Product saved. Goods stay in your purchase draft until receipt.');
        }
        _finish(afterExit: widget.onSaved);
      } else {
        _finish();
      }
    } on FormatException catch (error) {
      if (_variantFamily != null) _expanded['variants'] = true;
      _reject(error.message);
    } finally {
      if (mounted) setState(() => _savingInventory = false);
    }
  }

  final _sectionKeys = <String, GlobalKey>{};
  final _fieldKeys = <String, GlobalKey>{};
  final _fieldFocus = <String, FocusNode>{};
  final _expanded = <String, bool>{'summary': true};
  String? _errorField;

  Map<String, String> get _categories => {
    for (final category in [
      ...BuyV2Catalogue.shopCategories,
      ...BuyV2Catalogue.wholesaleCategories,
    ])
      if (category.id != 'all') category.id: category.label,
    for (final item in workspaceMasterCatalogue)
      item.categoryId: item.categoryId
          .split('-')
          .map(
            (part) => part.isEmpty
                ? part
                : '${part[0].toUpperCase()}${part.substring(1)}',
          )
          .join(' '),
    'other': 'Other products',
  };

  String _fieldSection(String field) => _rawImportLabels.containsKey(field) || WorkspaceProductImport.isOptionColumn(field)
      ? 'reference'
      : WorkspaceProductImport.packFieldLabels.containsKey(field)
      ? 'pack'
      : WorkspaceProductContent.labels.containsKey(field)
      ? 'facts'
      : WorkspaceSellingInputs.labels.containsKey(field)
      ? 'selling'
      : {
          'title',
          'purchasePrice',
          'sellingPrice',
          'mrp',
          'stock',
          'lowStockThreshold',
          'minimumOrder',
        }.contains(field)
      ? 'summary'
      : 'details';

  void _reject(String message, {String? field}) {
    final section = field == null ? null : _fieldSection(field);
    setState(() {
      _error = message;
      _errorField = field;
      if (section != null) _expanded[section] = true;
    });
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted || field == null) return;
      _fieldFocus[field]?.requestFocus();
      if (widget.importRow != null) {
        _revealImportIssue(field);
        return;
      }
      final target = _fieldKeys[field]?.currentContext;
      if (target != null) {
        unawaited(
          Scrollable.ensureVisible(
            target,
            alignment: .25,
            duration: const Duration(milliseconds: 180),
          ),
        );
      }
    });
  }

  void _clearFieldError(String field) {
    if (_errorField == field) {
      setState(() {
        _error = null;
        _errorField = null;
      });
    }
  }

  Widget _field(
    String id,
    String keyName,
    String label,
    TextEditingController controller, {
    bool numeric = false,
    bool money = false,
    bool percentage = false,
    int lines = 1,
    String? hint,
    String? helper,
  }) {
    final large = MediaQuery.textScalerOf(context).scale(1) > 1.2;
    final error = _errorField == id ? _error : null;
    return Container(
      key: _fieldKeys.putIfAbsent(id, () => GlobalKey()),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          if (large)
            Padding(
              padding: const EdgeInsets.only(bottom: 4),
              child: Text(
                label,
                key: Key('$keyName-label'),
                style: Theme.of(context).textTheme.bodySmall,
              ),
            ),
          TextField(
            key: Key(keyName),
            controller: controller,
            readOnly: _importFamilyReview && const {'title', 'brand', 'variant'}.contains(id) ||
              widget.stockAdjustmentInitial != null && _stockAdjustmentCommitted,
            focusNode: _fieldFocus.putIfAbsent(id, () => FocusNode()),
            // Replace the initial zero on entry without clearing valid existing
            // prices/quantities or changing the stored value merely on focus.
            selectAllOnFocus: numeric ? controller.text == '0' : null,
            onTap: numeric
                ? () {
                    // Android's tap caret placement follows focus selection.
                    if (controller.text == '0') {
                      controller.selection = const TextSelection(
                        baseOffset: 0,
                        extentOffset: 1,
                      );
                    }
                  }
                : null,
            keyboardType: numeric
                ? money || percentage ? const TextInputType.numberWithOptions(decimal: true) : TextInputType.number
                : lines > 1
                ? TextInputType.multiline
                : TextInputType.text,
            textInputAction: lines > 1
                ? TextInputAction.newline
                : TextInputAction.next,
            minLines: lines == 0 ? 1 : lines,
            maxLines: lines != 1 ? null : 1,
            scrollPadding: EdgeInsets.fromLTRB(16, large ? 64 : 24, 16, 104),
            onChanged: (_) {
              _clearFieldError(id);
              setState(() {});
            },
            decoration: InputDecoration(
              constraints: const BoxConstraints(minHeight: 48),
              labelText: large ? null : label,
              floatingLabelBehavior: FloatingLabelBehavior.always,
              hintText: hint,
              helperText: helper,
              helperMaxLines: 3,
              prefixText: money ? '₹ ' : null,
              suffixText: percentage ? '%' : null,
              error: error == null
                  ? null
                  : Semantics(
                      liveRegion: true,
                      child: Text(error, key: const Key('work-product-error')),
                    ),
            ),
          ),
        ],
      ),
    );
  }

  Widget _group(List<Widget> fields) => LayoutBuilder(
    builder: (context, constraints) {
      final paired =
          constraints.maxWidth >= 300 &&
          MediaQuery.textScalerOf(context).scale(1) <= 1.2;
      final width = paired
          ? (constraints.maxWidth - 8) / 2
          : constraints.maxWidth;
      return Wrap(
        spacing: 8,
        runSpacing: 10,
        children: [
          for (final field in fields) SizedBox(width: width, child: field),
        ],
      );
    },
  );

  Widget _section(
    String id,
    String keyName,
    String title,
    List<Widget> children, {
    Widget? leading,
    bool initiallyExpanded = false,
  }) {
    final open = _expanded[id] ?? initiallyExpanded;
    return Container(
      key: Key(keyName),
      margin: const EdgeInsets.only(bottom: 6),
      decoration: BoxDecoration(
        color: Colors.white,
        gradient: id == 'summary'
            ? const LinearGradient(
                colors: [Color(0xfff2f4ff), Colors.white],
                begin: Alignment.topLeft,
                end: Alignment.bottomRight,
              )
            : null,
        border: Border.all(color: MoolColors.line),
        borderRadius: BorderRadius.circular(12),
      ),
      child: Material(
        color: Colors.transparent,
        child: Column(
          children: [
            Material(
              color: Colors.transparent,
              child: InkWell(
                key: _sectionKeys.putIfAbsent(id, () => GlobalKey()),
                borderRadius: BorderRadius.circular(12),
                onTap: () {
                  FocusManager.instance.primaryFocus?.unfocus();
                  setState(() => _expanded[id] = !open);
                },
                child: Semantics(
                  button: true,
                  expanded: open,
                  child: ConstrainedBox(
                    constraints: const BoxConstraints(minHeight: 48),
                    child: Padding(
                      padding: const EdgeInsets.symmetric(
                        horizontal: 10,
                        vertical: 6,
                      ),
                      child: Row(
                        children: [
                          if (leading != null) ...[
                            leading,
                            const SizedBox(width: 10),
                          ],
                          Expanded(
                            child: Text(
                              title,
                              style: Theme.of(context).textTheme.titleMedium
                                  ?.copyWith(
                                    fontSize: 14,
                                    fontWeight: FontWeight.w600,
                                    color: MoolColors.navy,
                                  ),
                            ),
                          ),
                          Icon(
                            open ? Icons.expand_less : Icons.expand_more,
                            color: MoolColors.navy,
                            size: 22,
                          ),
                        ],
                      ),
                    ),
                  ),
                ),
              ),
            ),
            if (open)
              Padding(
                padding: const EdgeInsets.fromLTRB(10, 4, 10, 10),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: children,
                ),
              ),
          ],
        ),
      ),
    );
  }

  Widget _sellingChoice(
    String field,
    String label,
    Map<String, String> choices,
  ) => Container(
    key: _fieldKeys.putIfAbsent(field, () => GlobalKey()),
    child: DropdownButtonFormField<String>(
      key: Key('work-product-$field'),
      initialValue: choices.containsKey(_sellingFields[field]!.text)
          ? _sellingFields[field]!.text
          : null,
      isExpanded: true,
      itemHeight: null,
      focusNode: _fieldFocus.putIfAbsent(field, () => FocusNode()),
      decoration: InputDecoration(
        labelText: label,
        errorText: _errorField == field ? _error : null,
      ),
      items: [
        for (final choice in choices.entries)
          DropdownMenuItem(value: choice.key, child: Text(choice.value)),
      ],
      onChanged: (value) {
        if (value == null) return;
        setState(() => _sellingFields[field]!.text = value);
        _clearFieldError(field);
      },
    ),
  );

  Future<void> _confirmTradePrice({String? initialValidity}) async {
    if (!_nativeControlReady()) return;
    if (_hasUnsavedEdits || widget.session.workspaceCatalogueListingBusy) return;
    final trade = widget.product.wholesaleOffer;
    if (trade == null || trade.enabled != true || trade.valid != true) return;
    var input = initialValidity ?? trade.priceValidityMinutes?.toString() ?? '';
    String? error;
    final minutes = await _showProductOwnerDialog<int>(builder: (dialogContext) => StatefulBuilder(
      builder: (context, refresh) => AlertDialog(title: const Text('Confirm supplier price'),
        content: SingleChildScrollView(child: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.start, children: [
          Text('₹${workspacePriceInputFromMinor(trade.priceAtMinor(trade.minimumPacks))} per ${widget.product.pack} · minimum ${trade.minimumPacks} packs.'),
          const SizedBox(height: 12),
          const Text('Confirm that you will honour these saved trade prices and quantity tiers for the period below.'),
          const SizedBox(height: 12),
          TextFormField(key: const Key('work-confirm-price-minutes'), initialValue: input,
            keyboardType: TextInputType.number, decoration: InputDecoration(labelText: 'Honour price for (minutes)', errorText: error),
            onChanged: (value) { input = value; if (error != null) refresh(() => error = null); }),
        ])),
        actions: [TextButton(onPressed: () => Navigator.pop(dialogContext), child: const Text('Cancel')),
          FilledButton(key: const Key('work-confirm-price-submit'), onPressed: () {
            if (!_nativeControlReady()) return;
            final parsed = int.tryParse(input.trim());
            if (parsed == null || parsed < 1 || parsed > 525600) { refresh(() => error = 'Enter whole minutes from 1 to 525600.'); return; }
            Navigator.pop(dialogContext, parsed);
          }, child: const Text('Confirm price'))],
      )));
    if (minutes == null || !mounted || !_nativeControlReady()) return;
    await widget.session.confirmWorkspaceCommodityPrice(widget.product.id, validityMinutes: minutes, current: _capturedOwnerCurrent, inputCurrent: _capturedRequestCurrent);
    if (mounted) setState(() {});
  }

