  @override
  Widget build(BuildContext context) {
    final keyboardInset = widget.embeddedPage
        ? 0.0
        : MediaQuery.viewInsetsOf(context).bottom;
    final view = View.of(context);
    final exportedClearance = widget.embeddedPage &&
            defaultTargetPlatform == TargetPlatform.android && view.viewInsets.bottom == 0
        ? moolAndroidExportedSemanticsClearance(
            viewPadding: EdgeInsets.fromViewPadding(view.viewPadding, view.devicePixelRatio),
            platform: defaultTargetPlatform).clamp(36.0, double.infinity).toDouble()
        : 0.0;
    final product = widget.product.copyWith(
      privatePhoto: _matchingPhoto,
      clearPrivatePhoto: _matchingPhoto == null,
      title: _title.text.trim(),
      brand: _brand.text.trim(),
      pack: _pack.text.trim(),
      variant: _variant.text.trim(),
      barcode: _barcode.text.trim(),
      categoryId: _category.text.trim(),
    );
    return PopScope(
      // Check live inputs even when Back arrives before the next rebuild.
      canPop: !widget.guardRouteExit || _allowEditorExit,
      onPopInvokedWithResult: (didPop, result) {
        if (!didPop && widget.guardRouteExit) unawaited(_requestEditorExit());
      },
      child: StoreSettingsStyle(
      child: Builder(
        builder: (context) => Material(
          color: const Color(0xfff7f8fc),
          child: Padding(
            padding: EdgeInsets.only(bottom: keyboardInset),
            child: Column(
              children: [
                if (!widget.embeddedPage)
                  Row(
                    children: [
                      const SizedBox(width: 12),
                      const Expanded(
                        child: Text(
                          'Review product',
                          style: TextStyle(
                            fontSize: 16,
                            fontWeight: FontWeight.w700,
                            color: MoolColors.navy,
                          ),
                        ),
                      ),
                      IconButton(
                        key: const Key('work-product-close'),
                        tooltip: 'Close product editor',
                        onPressed: _requestEditorExit,
                        icon: const Icon(Icons.close_rounded),
                      ),
                    ],
                  ),
                Expanded(
                  child: SingleChildScrollView(
                    key: const Key('work-product-editor-scroll'),
                    keyboardDismissBehavior:
                        ScrollViewKeyboardDismissBehavior.onDrag,
                    padding: const EdgeInsets.fromLTRB(10, 6, 10, 12),
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.stretch,
                      children: [
                        _section(
