class _OrdersDestinationSurface extends StatefulWidget {
  const _OrdersDestinationSurface({
    required this.onOpenOrder,
    required this.session,
    required this.onOpenCollection,
    required this.onOpenDelivery,
    required this.onSearch,
    required this.onAlerts,
    this.orderId,
  });

  final WorkSession session;
  final VoidCallback onOpenCollection;
  final VoidCallback onOpenDelivery;
  final VoidCallback onSearch;
  final VoidCallback onAlerts;
  final String? orderId;

  final ValueChanged<String> onOpenOrder;

  @override
  State<_OrdersDestinationSurface> createState() =>
      _OrdersDestinationSurfaceState();
}

class _OrdersDestinationSurfaceState extends State<_OrdersDestinationSurface>
    with WidgetsBindingObserver {
  late String _filter;
  bool _feedbackOpen = false;
  bool _bulkQuotesOpen = false;
  Object? _operationalViewScope;
  final _selectedFilterKey = GlobalKey();
  final _filterViewportKey = GlobalKey();
  final _filterScroll = ScrollController();
  bool _filterOverflow = false, _atFilterEnd = false;
  bool _selectedFilterOffscreen = false;
  bool _filterMetricsScheduled = false;

  @override
  void initState() {
    super.initState();
    _filter = widget.session.workspaceOrderFilter;
    WidgetsBinding.instance.addObserver(this);
    _filterScroll.addListener(_scheduleFilterMetrics);
    _revealSelectedFilter();
    // Analytics no longer mounts the collection card. Read its existing
    // gateway when Orders first needs it; never infer collection from payment.
    final controller = widget.session.currentCollection;
    final storeId = widget.session.activeWorkspace?.id;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted || widget.session.activeWorkspace?.id != storeId ||
          !identical(widget.session.currentCollection, controller) ||
          controller == null || controller.storeId != storeId ||
          controller.snapshot != null || controller.busy) {
        return;
      }
      unawaited(controller.refresh());
    });
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    _filterScroll.dispose();
    super.dispose();
  }

  @override
  void didChangeMetrics() {
    if (mounted) setState(() {});
  }

  void _scheduleFilterMetrics() {
    if (_filterMetricsScheduled) return;
    _filterMetricsScheduled = true;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      _filterMetricsScheduled = false;
      if (!mounted || !_filterScroll.hasClients) return;
      final position = _filterScroll.position;
      final overflow = position.maxScrollExtent > 1;
      final atEnd = position.extentAfter <= 1;
      final cueWidthChanged = overflow != _filterOverflow;
      final selectedBox = _selectedFilterKey.currentContext?.findRenderObject();
      final viewportBox = _filterViewportKey.currentContext?.findRenderObject();
      var offscreen = false;
      if (selectedBox is RenderBox && selectedBox.hasSize &&
          viewportBox is RenderBox && viewportBox.hasSize) {
        final left = selectedBox.localToGlobal(Offset.zero).dx;
        final viewportLeft = viewportBox.localToGlobal(Offset.zero).dx;
        offscreen = left < viewportLeft - 1 ||
            left + selectedBox.size.width > viewportLeft + viewportBox.size.width + 1;
      }
      if (overflow != _filterOverflow || atEnd != _atFilterEnd ||
          offscreen != _selectedFilterOffscreen) {
        setState(() {
          _filterOverflow = overflow;
          _atFilterEnd = atEnd;
          _selectedFilterOffscreen = offscreen;
        });
        // The cue takes space after the first layout. Reveal again in the
        // final viewport, but never snap the strip during manual scrolling.
        if (cueWidthChanged) _revealSelectedFilter();
      }
    });
  }

  void _scrollFilters() {
    if (!_filterScroll.hasClients) return;
    final position = _filterScroll.position;
    final target = (position.pixels +
            position.viewportDimension * (_atFilterEnd ? -.8 : .8))
        .clamp(0.0, position.maxScrollExtent);
    if (MoolMotion.isReduced(context) ||
        MediaQuery.accessibleNavigationOf(context)) {
      _filterScroll.jumpTo(target);
      return;
    }
    unawaited(
      _filterScroll.animateTo(
        target,
        duration: const Duration(milliseconds: 180),
        curve: Curves.easeOut,
      ),
    );
  }

  @override
  void didUpdateWidget(covariant _OrdersDestinationSurface oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (_filter != widget.session.workspaceOrderFilter ||
        (oldWidget.orderId != null && widget.orderId == null)) {
      _filter = widget.session.workspaceOrderFilter;
      _revealSelectedFilter();
    }
  }

  void _revealSelectedFilter() {
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) return;
      final target = _selectedFilterKey.currentContext;
      if (target != null) {
        unawaited(Scrollable.ensureVisible(target, alignment: .5));
      }
    });
  }

  @override
  Widget build(BuildContext context) {
    final session = widget.session;
    final allOrders = session.visibleWorkspaceOrders
        .where((order) => !_isCounterSaleOrder(order));
    final operationalScope = (session, session.originalPurchaseReader, session.originalPurchaseRealm,
      session.activeWorkspace?.id, session.navigationScopeRevision);
    if (session.workspaceOperationalFeedAvailable && operationalScope != _operationalViewScope) {
      _operationalViewScope = operationalScope;
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted && operationalScope == (widget.session, widget.session.originalPurchaseReader,
            widget.session.originalPurchaseRealm, widget.session.activeWorkspace?.id, widget.session.navigationScopeRevision)) {
          unawaited(widget.session.loadWorkspaceOperationalOrders());
        }
      });
    }
    if (session.workspaceBulkQuotes case final quotes? when _bulkQuotesOpen) {
      return WorkspaceBulkQuotes(key: ValueKey(('store-bulk-quotes', quotes, session.activeWorkspace?.id)),
        access: quotes, storeId: session.activeWorkspace!.id,
        onClose: () => setState(() { _bulkQuotesOpen = false; }));
    }
    if (_feedbackOpen) {
      void closeFeedback() => setState(() { _feedbackOpen = false; });
      return _storeInlineBackPriority(context,
        enabled: () => _feedbackOpen,
        onBack: closeFeedback,
        child: StoreCustomerFeedback(
        controller: widget.session.workspaceCustomerFeedback,
        orderId: widget.orderId,
        onClose: closeFeedback,
        onOpenOrder: (id) {
          closeFeedback();
          widget.onOpenOrder(id);
        },
      ));
    }
    bool matches(WorkspaceOrderRecord order, String filter) => switch (filter) {
      'Live' => !order.isClosed,
      'Done' => order.isClosed,
      _ => _storeOrderWorkFilter(order) == filter,
    };

    const filterLabels = {
      'Live': 'All',
      'New': 'New',
      'Packing': 'Packing',
      'Ready': 'Ready',
      'Delivery': 'Delivery',
      'Attention': 'Needs review',
      'Done': 'History',
    };
    final counts = {for (final filter in filterLabels.keys) filter: 0};
    final visibleOrders = <WorkspaceOrderRecord>[];
    for (final order in allOrders) {
      for (final filter in filterLabels.keys) {
        if (!matches(order, filter)) continue;
        counts[filter] = counts[filter]! + 1;
      }
      if (widget.orderId != null
          ? order.id == widget.orderId
          : matches(order, _filter)) {
        visibleOrders.add(order);
      }
    }
    final history = widget.orderId == null && _filter == 'Done';
    if (history) {
      visibleOrders.sort((a, b) {
        final placed = b.createdAt.compareTo(a.createdAt);
        return placed != 0 ? placed : a.id.compareTo(b.id);
      });
    }
    final indices = {
      for (var index = 0; index < visibleOrders.length; index++)
        visibleOrders[index].id: index,
    };
    int countFor(String filter) => counts[filter] ?? 0;
    final storeId = session.activeWorkspace?.id ?? session.workspaceId;
    final originalReader = widget.orderId == null && _filter == 'Live'
        ? session.originalPurchaseReader : null;
    final showOriginals = originalReader != null && storeId != null;
    final showOnline = widget.orderId == null && session.workspaceOperationalFeedAvailable;
    final showHeader = showOriginals || showOnline;
    Widget originalDetails() => Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
      if (showOnline) ...[
        Text(session.workspaceOperationalFeedError ?? 'Saved online orders · partial coverage',
          key: const Key('work-online-orders-coverage'), style: const TextStyle(color: MoolColors.muted, fontSize: 12)),
        Wrap(spacing: 8, children: [
          TextButton(key: const Key('work-online-orders-refresh'),
            onPressed: session.workspaceOperationalFeedBusy ? null : () => session.loadWorkspaceOperationalOrders(),
            child: Text(session.workspaceOperationalFeedBusy ? 'Checking online orders…' : 'Refresh online orders')),
          if (session.workspaceOperationalFeedHasMore) TextButton(
            onPressed: session.workspaceOperationalFeedBusy ? null : () => session.loadWorkspaceOperationalOrders(more: true),
            child: const Text('More online orders')),
          if (session.workspaceOperationalPending) TextButton(key: const Key('work-online-orders-reconcile'),
            onPressed: session.workspaceOperationalFeedBusy ? null : session.reconcileWorkspacePendingOrders,
            child: const Text('Check pending updates')),
        ]),
      ],
      if (showOriginals) WorkspacePurchaseOriginals(
        key: ValueKey(('store-originals',originalReader,storeId,session.originalPurchaseRealm)),
        gateway: originalReader, role: WorkspaceOrderIdentityRole.seller,
        realm: session.originalPurchaseRealm, storeId: storeId,
        onOpenDeviceCase: (handoff) => _openReceivedDeviceCase(context, session, handoff)),
    ]);
    _scheduleFilterMetrics();
    final keyboardVisible = MediaQuery.viewInsetsOf(context).bottom > 0 ||
        View.of(context).viewInsets.bottom > 0;
    return Container(
      key: const Key('work-orders-destination'),
      color: Colors.white,
      child: LayoutBuilder(builder: (context, pageConstraints) => Column(
        children: [
          LayoutBuilder(builder: (context, constraints) {
            // Keep this slot, and the keyed list/editor below it, stable while
            // reclaiming the fixed header space for the keyboard viewport.
            if (keyboardVisible) return const SizedBox.shrink();
            final headingStyle = TextStyle(
              color: MoolColors.ink,
              fontSize: widget.orderId == null ? 16 : 14,
              fontWeight: FontWeight.w700,
            );
            final header = Semantics(
              header: true,
              label: widget.orderId == null ? 'Customer orders' : null,
              child: Padding(
              key: const Key('work-orders-toolbar'),
              padding: const EdgeInsets.fromLTRB(14, 8, 6, 2),
              child: Row(children: [
                Expanded(child: Column(mainAxisSize: MainAxisSize.min,
                  crossAxisAlignment: CrossAxisAlignment.start, children: [
                  if (widget.orderId != null)
                    Text('Order details', style: headingStyle)
                  else
                    TextButton(
                      key: const Key('work-dashboard-search'),
                      style: TextButton.styleFrom(
                        minimumSize: const Size(48, 48),
                        padding: const EdgeInsets.symmetric(vertical: 6),
                        foregroundColor: MoolColors.muted,
                        alignment: Alignment.centerLeft,
                      ),
                      onPressed: widget.onSearch,
                      child: Semantics(
                        label: 'Search saved orders by order number or customer details',
                        value: _selectedFilterOffscreen
                            ? '${filterLabels[_filter]} · ${countFor(_filter)}' : null,
                        excludeSemantics: true,
                        child: Row(children: [
                          const Icon(Icons.search_rounded, size: 20),
                          const SizedBox(width: 6),
                          Expanded(child: Column(
                            mainAxisSize: MainAxisSize.min,
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              Text(constraints.maxWidth < 360 ? 'Search' : 'Search orders',
                                style: const TextStyle(fontSize: 13, fontWeight: FontWeight.w600)),
                              if (_selectedFilterOffscreen)
                                Text('${filterLabels[_filter]} · ${countFor(_filter)}',
                                  key: const Key('work-orders-current-scope'),
                                  style: const TextStyle(fontSize: 11, color: MoolColors.navy)),
                            ],
                          )),
                        ]),
                      ),
                    ),
                ])),
                IconButton(
                  key: const Key('work-orders-customer-feedback'),
                  tooltip: widget.orderId == null ? 'Customer feedback' : 'Feedback for this order',
                  constraints: const BoxConstraints(minWidth: 48, minHeight: 48),
                  visualDensity: VisualDensity.standard,
                  color: MoolColors.navy,
                  onPressed: () => setState(() { _feedbackOpen = true; }),
                  icon: const Icon(Icons.rate_review_outlined, size: 22),
                ),
                if (widget.orderId == null)
                  SizedBox(
                    key: const Key('work-orders-alerts'),
                    width: 48,
                    height: 48,
                    child: _DashboardAlertButton(
                      count: _workspaceAlerts(session).length,
                      onPressed: widget.onAlerts,
                    ),
                  ),
              ]),
              ),
            );
            final compactHeader = pageConstraints.maxHeight <
                MediaQuery.textScalerOf(context).scale(260);
            if (compactHeader) {
              // Preserve enlarged labels and reachable controls, not a fixed
              // height that clips the title or steals the queue's viewport.
              return ConstrainedBox(
                constraints: BoxConstraints(maxHeight:
                  (pageConstraints.maxHeight *
                      (widget.orderId == null ? .4 : .25)).clamp(
                    widget.orderId == null
                        ? MediaQuery.textScalerOf(context).scale(48) + 6
                        : 48.0,
                    double.infinity)),
                child: SingleChildScrollView(
                  key: const Key('work-orders-compact-header-scroll'),
                  primary: false, child: header),
              );
            }
            return header;
          }),
          if (widget.orderId == null && session.workspaceBulkQuotes?.active == true)
            Material(type: MaterialType.transparency, child: ListTile(key: const ValueKey('work-orders-bulk-quotes'), dense: true,
              leading: const Icon(Icons.request_quote_outlined), title: const Text('Bulk quotes'),
              trailing: const Icon(Icons.chevron_right_rounded),
              onTap: () => setState(() { _feedbackOpen = false; _bulkQuotesOpen = true; }))),
          if (widget.orderId == null)
            keyboardVisible ? const SizedBox.shrink() : Row(
              children: [
                Expanded(
                  child: NotificationListener<ScrollMetricsNotification>(
                    key: _filterViewportKey,
                    onNotification: (_) {
                      _scheduleFilterMetrics();
                      return false;
                    },
                    child: SingleChildScrollView(
                      key: const Key('work-orders-filter-strip'),
                      controller: _filterScroll,
                      scrollDirection: Axis.horizontal,
                      padding: const EdgeInsets.symmetric(horizontal: 14),
                      child: Row(
                        children: [
                          for (final filter in filterLabels.keys.where(
                            (value) => value != 'Attention' ||
                                countFor(value) > 0 || _filter == value,
                          )) ...[
                            KeyedSubtree(
                              key: _filter == filter ? _selectedFilterKey : null,
                              child: ChoiceChip(
                                key: Key('work-orders-filter-${filter.toLowerCase()}'),
                                showCheckmark: false,
                                backgroundColor: Colors.white,
                                selectedColor: MoolColors.navy,
                                surfaceTintColor: Colors.transparent,
                                labelPadding: const EdgeInsets.symmetric(horizontal: 4),
                                padding: const EdgeInsets.symmetric(horizontal: 4),
                                materialTapTargetSize: MaterialTapTargetSize.padded,
                                visualDensity: VisualDensity.standard,
                                side: BorderSide(
                                  color: _filter == filter
                                      ? MoolColors.navy : const Color(0xFFE3E6EE),
                                  width: .7,
                                ),
                                shape: RoundedRectangleBorder(
                                  borderRadius: BorderRadius.circular(7),
                                ),
                                labelStyle: TextStyle(
                                  fontSize: 12,
                                  fontWeight: _filter == filter
                                      ? FontWeight.w700 : FontWeight.w500,
                                  color: _filter == filter ? Colors.white : MoolColors.navy,
                                ),
                                label: Text('${filterLabels[filter]} ${countFor(filter)}',
                                  key: _filter == filter && !_selectedFilterOffscreen
                                      ? const Key('work-orders-current-scope') : null),
                                selected: _filter == filter,
                                onSelected: (_) {
                                  widget.session.setWorkspaceOrderFilter(filter);
                                  setState(() => _filter = filter);
                                  _revealSelectedFilter();
                                },
                              ),
                            ),
                            const SizedBox(width: 5),
                          ],
                        ],
                      ),
                    ),
                  ),
                ),
                if (_filterOverflow)
                  DecoratedBox(
                    decoration: const BoxDecoration(
                      color: Color(0xFFF7F8FC),
                      border: Border(left: BorderSide(color: Color(0xFFE3E6EE))),
                    ),
                    child: IconButton(
                    key: const Key('work-orders-filter-more'),
                    tooltip: _atFilterEnd
                        ? 'Earlier order stages' : 'More order stages',
                    constraints: const BoxConstraints(minWidth: 48, minHeight: 48),
                    onPressed: _scrollFilters,
                    icon: Icon(
                      _atFilterEnd
                          ? Icons.chevron_left_rounded : Icons.chevron_right_rounded,
                      size: 20,
                      color: MoolColors.navy,
                    ),
                    ),
                  ),
              ],
            ),
          Expanded(
            child: visibleOrders.isNotEmpty
                ? ListView.builder(
                    key: PageStorageKey((
                      'work-orders-queue',
                      storeId,
                      _filter,
                      widget.orderId,
                    )),
                    padding: EdgeInsets.fromLTRB(14, widget.orderId == null ? 10 : 0, 14, 14),
                    itemCount: visibleOrders.length + (showHeader ? 1 : 0),
                    addAutomaticKeepAlives: false,
                    findChildIndexCallback: (key) {
                      if (key is! ValueKey<(String?, String)> ||
                          key.value.$1 != storeId) {
                        return null;
                      }
                      final index = indices[key.value.$2];
                      return index == null ? null : index + (showHeader ? 1 : 0);
                    },
                    itemBuilder: (context, index) {
                      if (showHeader && index == 0) return originalDetails();
                      final order = visibleOrders[index - (showHeader ? 1 : 0)];
                      return Padding(
                        key: ValueKey<(String?, String)>((storeId, order.id)),
                        padding: EdgeInsets.only(bottom: history ? 0 : 8),
                        child: history
                            ? _OrdersHistoryRow(
                                session: session,
                                order: order,
                                onOpen: () => widget.onOpenOrder(order.id),
                              )
                            : _LiveOrderTicket(
                          session: session,
                          detailed: widget.orderId != null,
                          onOpenCollection: widget.onOpenCollection,
                          order: order,
                          active:
                              session.hasActiveWorkspaceOrder &&
                              (session.currentWorkspaceOrderId == null ||
                                  order.id == session.currentWorkspaceOrderId),
                          onOpenDelivery: widget.onOpenDelivery,
                          onReview: () => widget.onOpenOrder(order.id),
                        ),
                      );
                    },
                  )
                : Align(
                    alignment: Alignment.topLeft,
                    child: SingleChildScrollView(
                      key: const Key('work-orders-empty-state'),
                      padding: const EdgeInsets.fromLTRB(14, 10, 14, 14),
                      child: Column(
                        mainAxisSize: MainAxisSize.min,
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          if (showHeader) originalDetails(),
                          Text(
                            widget.orderId != null ? 'Order unavailable' : switch (_filter) {
                              'Done' => 'No past orders yet',
                              'New' => 'No new orders',
                              'Packing' => 'No orders awaiting packing',
                              'Ready' => 'No orders ready for pickup',
                              'Delivery' => 'No orders awaiting delivery',
                              'Attention' => 'No orders need review',
                              _ => 'No active orders',
                            },
                            style: const TextStyle(
                              color: MoolColors.ink,
                              fontSize: 14,
                              fontWeight: FontWeight.w600,
                            ),
                          ),
                          const SizedBox(height: 4),
                          Text(
                            widget.orderId != null
                                ? 'Return to the order list and search again.'
                                : _filter == 'Done'
                                ? 'Saved completed and cancelled orders. Online orders may be missing. Counter sales are in Sales.'
                                : 'Saved orders only. Online orders may be missing. Counter sales are in Sales.',
                            style: const TextStyle(
                              color: Color(0xFF4C5268), fontSize: 12,
                            ),
                          ),
                          if (widget.orderId == null && _filter != 'Done' && countFor('Done') > 0)
                            TextButton.icon(
                              key: const Key('work-orders-empty-history'),
                              style: TextButton.styleFrom(
                                foregroundColor: MoolColors.navy,
                                minimumSize: const Size(48, 48),
                                padding: EdgeInsets.zero,
                              ),
                              onPressed: () {
                                session.setWorkspaceOrderFilter('Done');
                                setState(() => _filter = 'Done');
                                _revealSelectedFilter();
                              },
                              icon: const Icon(Icons.history_rounded, size: 16),
                              label: Text('View past orders · ${countFor('Done')}'),
                            ),
                        ],
                      ),
                    ),
                  ),
          ),
        ],
      )),
    );
  }
}

class _ExactOrderInformation extends StatelessWidget {
  const _ExactOrderInformation({
    required this.order,
    required this.showItems,
    this.paymentLabel,
    this.showPayment = true,
    this.showFacts = true,
    this.invoiceStyle = false,
    this.stageLabel,
    this.showAmounts = true,
  });
  final WorkspaceOrderRecord order;
  final bool showItems;
  final String? paymentLabel;
  final bool showPayment;
  final bool showFacts;
  final bool invoiceStyle;
  final String? stageLabel;
  final bool showAmounts;

  static String _price(int paise) {
    final fraction = paise % 100;
    return '₹${_formatStoreAmount(paise ~/ 100)}'
        '${fraction == 0 ? '' : '.${fraction.toString().padLeft(2, '0')}'}';
  }

  @override
  Widget build(BuildContext context) {
    if (order.operational != null) return _operationalInformation(context);
    if (invoiceStyle) return _invoiceInformation(context);
    final localizations = MaterialLocalizations.of(context);
    final placed = order.createdAt.toLocal();
    final facts = <(String, String)>[
      (
        'Placed',
        '${localizations.formatShortDate(placed)} · '
            '${localizations.formatTimeOfDay(TimeOfDay.fromDateTime(placed))}',
      ),
      ('Ordered via', order.source == 'App' ? 'MoolSocial app' : order.source),
      if (showPayment)
        (
          'Payment',
          paymentLabel ??
              (order.payment.isEmpty
                  ? 'Awaiting payment update'
                  : order.payment),
        ),
      (
        'Receive by',
        order.isCustomerCollection
            ? 'Collect at store'
            : order.fulfilment.isEmpty
            ? 'Awaiting confirmation'
            : order.fulfilment,
      ),
      if (order.needsDelivery || order.address.trim().isNotEmpty)
        (
          'Deliver to',
          order.address.trim().isEmpty
              ? 'Address not yet available'
              : order.address,
        ),
    ];
    return Column(
      key: Key('work-exact-order-information-${order.id}'),
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        if (showFacts) const Divider(height: 20, color: Color(0xFFE5E8F1)),
        for (final fact in showFacts ? facts : const <(String, String)>[])
          Padding(
            padding: const EdgeInsets.symmetric(vertical: 4),
            child: MediaQuery.textScalerOf(context).scale(1) >= 1.8
                ? Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        fact.$1,
                        style: const TextStyle(
                          color: MoolColors.muted,
                          fontSize: 12,
                        ),
                      ),
                      Text(
                        fact.$2,
                        style: const TextStyle(
                          color: MoolColors.ink,
                          fontSize: 13,
                        ),
                      ),
                    ],
                  )
                : Row(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      SizedBox(
                        width: 90,
                        child: Text(
                          fact.$1,
                          style: const TextStyle(
                            color: MoolColors.muted,
                            fontSize: 12,
                          ),
                        ),
                      ),
                      Expanded(
                        child: Text(
                          fact.$2,
                          style: const TextStyle(
                            color: MoolColors.ink,
                            fontSize: 13,
                          ),
                        ),
                      ),
                    ],
                  ),
          ),
        if (showItems) ...[
          const Divider(height: 24, color: Color(0xFFE5E8F1)),
          const Text(
            'Ordered items',
            style: TextStyle(
              color: MoolColors.navy,
              fontSize: 14,
              fontWeight: FontWeight.w700,
            ),
          ),
          if (order.hasCompleteItemSnapshot)
            for (final line in order.itemSnapshots)
              Padding(
                key: Key('work-exact-order-item-${line.productId}'),
                padding: const EdgeInsets.symmetric(vertical: 10),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    Text(
                      line.name,
                      style: const TextStyle(
                        color: MoolColors.ink,
                        fontSize: 14,
                        fontWeight: FontWeight.w700,
                      ),
                    ),
                    if (line.pack.trim().isNotEmpty)
                      Text(
                        line.pack,
                        style: const TextStyle(
                          color: MoolColors.muted,
                          fontSize: 12,
                        ),
                      ),
                    const SizedBox(height: 5),
                    _StoreMoneyLine(
                      leading: Text(
                        '${line.quantity} × ${_price(line.unitPricePaise)}',
                        style: const TextStyle(
                          color: MoolColors.muted,
                          fontSize: 12,
                        ),
                      ),
                      value: _price(line.lineTotalPaise),
                      style: const TextStyle(
                        color: MoolColors.navy,
                        fontSize: 14,
                        fontWeight: FontWeight.w700,
                      ),
                    ),
                  ],
                ),
              )
          else ...[
            const SizedBox(height: 8),
            Text(
              order.items,
              style: const TextStyle(color: MoolColors.ink, fontSize: 13),
            ),
            const SizedBox(height: 6),
            const Text(
              'Item prices are not available on this order.',
              key: Key('work-exact-order-prices-unavailable'),
              style: TextStyle(color: MoolColors.muted, fontSize: 12),
            ),
          ],
        ],
      ],
    );
  }

  Widget _operationalInformation(BuildContext context) {
    final exact = order.operational!;
    final originalAddress = exact.original.fulfilmentContext?.address;
    final localizations = MaterialLocalizations.of(context);
    String date(DateTime value) {
      final local = value.toLocal();
      return '${localizations.formatShortDate(local)} · ${localizations.formatTimeOfDay(TimeOfDay.fromDateTime(local))}';
    }
    const totals = {
      'itemsMinor': 'Items', 'discountMinor': 'Discount', 'taxMinor': 'Tax',
      'deliveryMinor': 'Delivery', 'freightMinor': 'Freight',
      'paymentFeeMinor': 'Payment fee', 'tipMinor': 'Tip', 'totalMinor': 'Order total',
    };
    return Column(key: Key('work-operational-details-${order.id}'),
      crossAxisAlignment: CrossAxisAlignment.stretch, children: [
      if (showFacts) ...[
        Text('Placed ${date(exact.placedAt)}', style: const TextStyle(color: MoolColors.muted, fontSize: 12)),
        if (originalAddress == null || originalAddress.line.isEmpty || originalAddress.area.isEmpty || originalAddress.pinCode.isEmpty)
          Text(exact.fulfilment == 'collection' ? 'Collect at store · ${exact.address}' : 'Delivery · ${exact.address}',
            style: const TextStyle(fontSize: 12)),
        WorkspaceOriginalFulfilmentForOrder(original: exact.original),
        if (exact.stage == 'Confirmed' && exact.acceptanceDeadline != null)
          Text('Accept by ${date(exact.acceptanceDeadline!)}', style: const TextStyle(fontSize: 12)),
        if (exact.fulfilmentDeadline case final deadline?)
          Text('Fulfil by ${date(deadline)}', style: const TextStyle(fontSize: 12)),
        if (showPayment) const Text('Payment status unavailable', style: TextStyle(color: MoolColors.muted, fontSize: 12)),
      ],
      if (showItems) ...[
        const Divider(height: 20),
        for (final line in exact.original.lines)
          Padding(key: Key('work-operational-line-${line.lineId}'),
            padding: const EdgeInsets.symmetric(vertical: 6),
            child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
              Text('${line.name} · ${line.packLabel}', style: const TextStyle(fontWeight: FontWeight.w600)),
              WorkspaceOriginalVariantForLine(line: line),
              WorkspaceOriginalSupplierTaxForLine(line: line),
              WorkspaceOriginalCommodityPriceForLine(line: line),
              WorkspaceOriginalScheduledForLine(line: line),
              WorkspaceOriginalInstructionsForLine(original: exact.original, lineId: line.lineId),
              _StoreMoneyLine(leading: Text('${line.quantityLabel} × ${_price(line.unitPriceMinor)}'),
                value: _price(line.lineTotalMinor), style: const TextStyle(fontWeight: FontWeight.w600)),
              WorkspaceOriginalBenefitsForLine(original: exact.original, lineId: line.lineId),
            ])),
      ],
      if (showAmounts) ...[
        const Divider(height: 20),
        for (final total in totals.entries)
          Padding(key: Key('work-operational-total-${total.key}'), padding: const EdgeInsets.symmetric(vertical: 3),
            child: _StoreMoneyLine(leading: Text(total.value),
              value: '${total.key == 'discountMinor' ? '−' : ''}${_price(exact.original.totals[total.key]!)}',
              style: TextStyle(fontWeight: total.key == 'totalMinor' ? FontWeight.w700 : FontWeight.w500))),
      ],
    ]);
  }

  // Opt-in Orders details only; approved invoice/collection callers stay intact.
  Widget _invoiceInformation(BuildContext context) {
    final localizations = MaterialLocalizations.of(context);
    String date(DateTime value) {
      final local = value.toLocal();
      return '${localizations.formatShortDate(local)} · '
          '${localizations.formatTimeOfDay(TimeOfDay.fromDateTime(local))}';
    }
    final lines = order.itemSnapshots;
    final reconciled = order.hasCompleteItemSnapshot &&
        order.validBillAmounts &&
        lines.fold<int>(0, (sum, line) => sum + line.lineTotalPaise) ==
            order.payableMinor &&
        lines.fold<int>(0, (sum, line) =>
            sum + line.quantity * line.unitPricePaise) == order.subtotalMinor;
    final facts = <(String, String)>[
      ('Placed', date(order.createdAt)),
      ('Order status', order.stage == 'Confirmed'
          ? 'Awaiting acceptance' : stageLabel ?? order.stage),
      if (showPayment) ('Payment', (paymentLabel ?? order.payment).trim().isEmpty
          ? 'Payment details unavailable' : paymentLabel ?? order.payment),
      ('Fulfilment', order.isCustomerCollection ? 'Collect at store'
          : order.fulfilment.isEmpty ? 'Awaiting confirmation' : order.fulfilment),
      if (order.fulfilmentDeadline case final deadline?)
        ('Fulfil by', date(deadline)),
      if (!order.isClosed)
        if (order.actionDeadline case final deadline?)
          ('Accept by', date(deadline)),
      if (order.needsDelivery || order.address.trim().isNotEmpty)
        ('Deliver to', order.address.trim().isEmpty
            ? 'Address not yet available' : order.address),
      if (order.rejectionReason?.trim().isNotEmpty == true)
        ('Cancellation reason', order.rejectionReason!),
    ];
    return Column(
      key: Key('work-exact-order-information-${order.id}'),
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        Wrap(spacing: 12, runSpacing: 2, children: [
          Text(order.source == 'Counter' ? 'Counter Sale'
              : order.source == 'App' ? 'MoolSocial order' : order.source,
              style: const TextStyle(fontSize: 11, color: MoolColors.muted)),
          for (final fact in facts.where((fact) =>
              fact.$1 == 'Order status' || fact.$1 == 'Payment'))
            Row(mainAxisSize: MainAxisSize.min, children: [
              Text('${fact.$1 == 'Order status' ? 'Order' : 'Payment'} · ',
                  style: const TextStyle(fontSize: 12, color: MoolColors.muted)),
              Flexible(child: Text(fact.$2,
                  key: fact.$1 == 'Order status'
                      ? Key('work-order-stage-label-${order.id}') : null,
                  style: const TextStyle(fontSize: 12, color: MoolColors.navy,
                      fontWeight: FontWeight.w600))),
            ]),
        ]),
        for (final fact in facts.where((fact) =>
            fact.$1 != 'Order status' && fact.$1 != 'Payment'))
          Padding(
            padding: const EdgeInsets.symmetric(vertical: 2),
            child: _StoreScaledPair(
              first: Text(fact.$1, style: const TextStyle(
                  color: MoolColors.muted, fontSize: 11)),
              second: Text(fact.$2,
                  key: fact.$1 == 'Order status'
                      ? Key('work-order-stage-label-${order.id}') : null,
                  textAlign: TextAlign.end,
                  style: const TextStyle(color: MoolColors.ink,
                      fontSize: 11, fontWeight: FontWeight.w500)),
            ),
          ),
        if (showItems) ...[
          const Divider(height: 16, color: Color(0xFFE5E8F1)),
          const Text('Ordered items', style: TextStyle(
            color: MoolColors.navy, fontSize: 13, fontWeight: FontWeight.w600)),
          if (order.hasCompleteItemSnapshot) ...[
            const Padding(
              padding: EdgeInsets.only(top: 6, bottom: 2),
              child: Row(children: [
                Expanded(child: Text('Quantity × price', style: TextStyle(
                    color: MoolColors.muted, fontSize: 11))),
                Text('Amount', style: TextStyle(
                    color: MoolColors.muted, fontSize: 11)),
              ]),
            ),
            for (final line in lines)
              Container(
                key: Key('work-exact-order-item-${line.productId}'),
                padding: const EdgeInsets.symmetric(vertical: 7),
                decoration: const BoxDecoration(border: Border(
                    bottom: BorderSide(color: Color(0xFFE8EAF0), width: .6))),
                child: Column(crossAxisAlignment: CrossAxisAlignment.stretch,
                    children: [
                  Text(line.name, style: const TextStyle(color: MoolColors.ink,
                      fontSize: 13, fontWeight: FontWeight.w600)),
                  if (line.pack.trim().isNotEmpty)
                    Text(line.pack, style: const TextStyle(
                        color: MoolColors.muted, fontSize: 11)),
                  _StoreMoneyLine(
                    alignAmountToEnd: true,
                    leading: Text('${line.quantity} × ${_price(line.unitPricePaise)}',
                        style: const TextStyle(color: MoolColors.ink, fontSize: 12)),
                    value: _price(reconciled
                        ? line.unitPricePaise * line.quantity : line.lineTotalPaise),
                    style: const TextStyle(color: MoolColors.ink,
                        fontSize: 13, fontWeight: FontWeight.w600),
                  ),
                ]),
              ),
          ] else ...[
            Text(order.items, style: const TextStyle(
                color: MoolColors.ink, fontSize: 13)),
            const Text('Item prices are not available on this order.',
                key: Key('work-exact-order-prices-unavailable'),
                style: TextStyle(color: MoolColors.muted, fontSize: 12)),
          ],
        ],
        if (showAmounts) ...[
        const SizedBox(height: 8),
        if (reconciled && order.discountMinor > 0) ...[
          _StoreMoneyLine(alignAmountToEnd: true,
              leading: const Text('Subtotal', style: TextStyle(
                  color: MoolColors.muted, fontSize: 12)),
              value: _price(order.subtotalMinor),
              style: const TextStyle(color: MoolColors.ink,
                  fontSize: 13, fontWeight: FontWeight.w600)),
          _StoreMoneyLine(alignAmountToEnd: true,
              leading: Text(order.discount.kind == 'percentage'
                  ? 'Bill discount (${order.discount.value / 100}%)' : 'Bill discount',
                  style: const TextStyle(color: MoolColors.muted, fontSize: 12)),
              value: '−${_price(order.discountMinor)}',
              style: const TextStyle(color: MoolColors.ink,
                  fontSize: 13, fontWeight: FontWeight.w600)),
        ],
        if (!reconciled)
          const Text('Price breakdown unavailable · saved total shown',
              key: Key('work-order-breakdown-unavailable'),
              style: TextStyle(color: MoolColors.muted, fontSize: 11)),
        _StoreMoneyLine(
          alignAmountToEnd: true,
          leading: const Text('Order total', style: TextStyle(
              color: MoolColors.navy, fontSize: 14, fontWeight: FontWeight.w700)),
          value: _price(order.payableMinor),
          style: const TextStyle(color: MoolColors.navy,
              fontSize: 14, fontWeight: FontWeight.w700),
        ),
        ],
      ],
    );
  }
}

// History presentation only: exact details and commands retain their owners.
class _OrdersHistoryRow extends StatelessWidget {
  const _OrdersHistoryRow({
    required this.session,
    required this.order,
    required this.onOpen,
    this.searchResult = false,
  });

  final WorkSession session;
  final WorkspaceOrderRecord order;
  final VoidCallback onOpen;
  final bool searchResult;

  @override
  Widget build(BuildContext context) {
    final placed = order.createdAt.toLocal();
    final localizations = MaterialLocalizations.of(context);
    final stage = session.workspaceOrderStageLabel(order);
    final payment = session.workspaceOrderPaymentLabel(order);
    final source = order.source == 'App' ? 'MoolSocial app' : order.source;
    final preview = order.hasCompleteItemSnapshot
        ? order.itemSnapshots
              .take(2)
              .map(
                (item) =>
                    '${item.name}${item.pack.isEmpty ? '' : ' · ${item.pack}'}',
              )
              .join(' · ')
        : order.items;
    final storeId = session.activeWorkspace?.id ?? session.workspaceId;
    return Material(
      color: Colors.white,
      child: InkWell(
        key: Key(searchResult ? 'work-search-order-${order.id}'
            : 'work-order-history-open-${order.id}'),
        onTap: () {
          if (storeId != (session.activeWorkspace?.id ?? session.workspaceId)) {
            return;
          }
          onOpen();
        },
        child: Container(
          constraints: const BoxConstraints(minHeight: 48),
          padding: const EdgeInsets.symmetric(vertical: 10),
          decoration: const BoxDecoration(
            border: Border(bottom: BorderSide(color: Color(0xFFE8EAF0))),
          ),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              _StoreMoneyLine(
                alignAmountToEnd: true,
                leading: Row(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Expanded(
                      child: Text(
                        searchResult ? _savedOrderCustomerName(session, order) : order.customer,
                        maxLines: 2,
                        overflow: TextOverflow.ellipsis,
                        style: const TextStyle(
                          color: MoolColors.ink,
                          fontSize: 13,
                          fontWeight: FontWeight.w600,
                        ),
                      ),
                    ),
                    const Icon(
                      Icons.chevron_right_rounded,
                      color: MoolColors.navy,
                      size: 18,
                    ),
                  ],
                ),
                value: '₹${_formatStoreMinorAmount(order.payableMinor)}',
                style: const TextStyle(
                  color: MoolColors.navy,
                  fontSize: 14,
                  fontWeight: FontWeight.w700,
                ),
              ),
              const SizedBox(height: 3),
              if (searchResult && _savedOrderCustomerName(session, order) != order.customer)
                Text(order.customer, style: const TextStyle(
                    color: MoolColors.ink, fontSize: 11)),
              Text(
                order.id,
                key: Key('work-order-history-reference-${order.id}'),
                style: const TextStyle(color: MoolColors.ink, fontSize: 11),
              ),
              Text(
                '${localizations.formatShortDate(placed)} · ${localizations.formatTimeOfDay(TimeOfDay.fromDateTime(placed))}',
                key: Key('work-order-history-date-${order.id}'),
                style: const TextStyle(color: MoolColors.muted, fontSize: 11),
              ),
              Wrap(
                spacing: 8,
                runSpacing: 2,
                children: [
                  Text(
                    stage,
                    key: Key('work-order-stage-label-${order.id}'),
                    style: const TextStyle(
                      color: MoolColors.navy,
                      fontSize: 11,
                      fontWeight: FontWeight.w600,
                    ),
                  ),
                  Text(
                    payment,
                    style: const TextStyle(color: MoolColors.ink, fontSize: 11),
                  ),
                  if (source.isNotEmpty || order.fulfilment.isNotEmpty)
                    Text(
                      [
                        source,
                        order.isCustomerCollection
                            ? 'Collect at store'
                            : order.fulfilment,
                      ].where((part) => part.isNotEmpty).join(' · '),
                      style: const TextStyle(
                        color: MoolColors.muted,
                        fontSize: 11,
                      ),
                    ),
                ],
              ),
              if (preview.isNotEmpty) ...[
                const SizedBox(height: 3),
                Text(
                  preview,
                  key: Key('work-order-history-items-${order.id}'),
                  maxLines: 2,
                  overflow: TextOverflow.ellipsis,
                  style: const TextStyle(color: MoolColors.ink, fontSize: 11),
                ),
              ],
              if (order.hasCompleteItemSnapshot &&
                  order.itemSnapshots.length > 2)
                Text(
                  '+${order.itemSnapshots.length - 2} more products',
                  style: const TextStyle(color: MoolColors.muted, fontSize: 11),
                ),
            ],
          ),
        ),
      ),
    );
  }
}

class _LiveOrderTicket extends StatelessWidget {
  const _LiveOrderTicket({
    required this.session,
    required this.onOpenCollection,
    required this.order,
    required this.active,
    required this.onOpenDelivery,
    required this.onReview,
    this.detailed = false,
  });

  final WorkSession session;
  final VoidCallback onOpenCollection;
  final WorkspaceOrderRecord order;
  final bool active;
  final VoidCallback onOpenDelivery;
  final VoidCallback onReview;
  final bool detailed;

  Widget _operationalTicket(BuildContext context) {
    final exact = order.operational!;
    final captured=_StoreOrderEffectScope.of(context);
    final storeId = session.activeWorkspace?.id ?? session.workspaceId;
    final scopeRevision = session.navigationScopeRevision;
    bool current() => context.mounted && captured?.current()!=false && storeId == (session.activeWorkspace?.id ?? session.workspaceId) &&
        scopeRevision == session.navigationScopeRevision &&
        exact.reference.storeId == storeId &&
        exact.viewerUserId == (session.contactDraftStore?.accountScope ?? session.pendingProofStore?.accountScope) &&
        identical(session.workspaceOrders.where((row) => row.id == order.id).firstOrNull?.operational, exact);
    bool can(WorkOrderAction action) => current() && captured?.permits(action.name)!=false && session.workspaceOrderCanAct(order.id, action);
    Future<void> act(WorkOrderAction action) async {
      if(!can(action))return;
      Future<void> original()async{
        if(!current() || !session.selectWorkspaceOrder(order.id) || !current())return;
        if(action==WorkOrderAction.reject){
          await _showRejectOrderSheet(context,session,inputCurrent:captured?.current,ownerChanges:captured?.changes);
        }else{
          await session.submitWorkspaceOrderAction(order.id,action,inputCurrent:captured?.current);
        }
      }
      if(captured==null){await original();}else{await captured.perform(original);}
    }
    final lines = exact.stage == 'Preparing' && exact.fulfilment != 'collection'
        ? session.workspacePackingLinesForOrder(order) : const <WorkspacePackingLine>[];
    final packed = lines.where((line) => line.packed).length;
    final originals = {for (final line in exact.original.lines) line.lineId: line};
    return _OrderDeadlineBoundary(deadline: exact.stage == 'Confirmed' ? exact.acceptanceDeadline : null,
      builder: (expired) => Material(key: ValueKey('work-operational-order-${order.id}'), color: Colors.white,
        child: Padding(padding: const EdgeInsets.symmetric(vertical: 10), child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch, children: [
          _StoreMoneyLine(leading: Text(order.customer, style: const TextStyle(fontWeight: FontWeight.w700)),
            value: _ExactOrderInformation._price(order.payableMinor), style: const TextStyle(fontWeight: FontWeight.w700)),
          Text(session.workspaceOrderStageLabel(order), style: const TextStyle(color: MoolColors.navy, fontWeight: FontWeight.w600)),
          Text(order.id, style: const TextStyle(color: MoolColors.muted, fontSize: 11)),
          if (!detailed) const Text('Payment status unavailable', style: TextStyle(color: MoolColors.muted, fontSize: 12)),
          if (exact.rejectionReason case final reason?) Text(reason),
          if (detailed) _ExactOrderInformation(order: order, showItems: captured!=null || lines.isEmpty),
          if (lines.isNotEmpty) ...[
            Padding(padding: const EdgeInsets.symmetric(vertical: 8), child: Text('$packed/${lines.length} lines packed')),
            if(captured==null||captured.operation=='packing')for (final line in lines.where((line)=>captured==null||line.id==captured.packingLineId)) ...[
              CheckboxListTile(key: Key('work-operational-pack-${line.id}'),
                contentPadding: EdgeInsets.zero, controlAffinity: ListTileControlAffinity.trailing,
                value: line.packed, title: Text('${line.label} · ${line.quantityLabel}'),
                subtitle: Text('Each ${_ExactOrderInformation._price(originals[line.id]!.unitPriceMinor)} · '
                  'Line total ${_ExactOrderInformation._price(originals[line.id]!.lineTotalMinor)}'),
                onChanged: !current() || session.workspaceOrderOperationState(order.id) != null ? null : (value) {
                  if (!current()) return;
                  if(captured!=null){
                    if(!captured.permits('packing')||captured.packingLineId!=line.id||captured.packingQuantity!=line.quantity||captured.packingValue!=(value==true))return;
                    unawaited(captured.perform(()async{if(!current()||!captured.current())return;
                      session.setWorkspaceOrderPackingLine(storeId:storeId,orderId:order.id,lineId:line.id,quantity:line.quantity,
                        packed:value==true,expectedOperational:exact);}));return;
                  }
                  session.setWorkspaceOrderPackingLine(storeId: storeId, orderId: order.id,
                    lineId: line.id, quantity: line.quantity, packed: value == true, expectedOperational: exact);
                }),
              if (session.originalPurchaseReader case final reader? when reader.isCurrent && reader.accountUserId == exact.viewerUserId)
                WorkspacePurchasedUnitsForLine(key: ValueKey(('packing-units', exact, reader, scopeRevision, line.id)),
                  gateway: reader, role: WorkspaceOrderIdentityRole.seller, realm: session.originalPurchaseRealm,
                  reference: exact.reference, line: originals[line.id]!,
                  onOpenDeviceCase: (handoff) => _openReceivedDeviceCase(context, session, handoff),
                  inputCurrent: () => current() && exact.stage == 'Preparing' && session.workspaceOrderOperationState(order.id) == null),
            ],
          ],
          if (exact.stage == 'Ready') const Text('Delivery confirmation is not connected. Ready does not mean delivered.',
            style: TextStyle(color: MoolColors.muted, fontSize: 12)),
          if (exact.fulfilment == 'collection') const Text('Collection actions are unavailable for this order.',
            style: TextStyle(color: MoolColors.muted, fontSize: 12)),
          if (session.workspaceOrderOperationState(order.id) != null)
            _OrderOperationStatus(session: session, orderId: order.id),
          Wrap(alignment: WrapAlignment.end, spacing: 8, runSpacing: 4, children: [
            if (!detailed) TextButton(onPressed: !current() ? null : onReview, child: const Text('Review')),
            if (exact.stage == 'Confirmed') ...[
              TextButton(key: Key('work-operational-reject-${order.id}'),
                onPressed: expired || !can(WorkOrderAction.reject) ? null : () => act(WorkOrderAction.reject), child: const Text('Reject')),
              FilledButton(key: Key('work-operational-accept-${order.id}'),
                onPressed: expired || !can(WorkOrderAction.accept) ? null : () => act(WorkOrderAction.accept), child: const Text('Accept')),
            ],
            if (exact.stage == 'Preparing') FilledButton(key: Key('work-operational-ready-${order.id}'),
              onPressed: !can(WorkOrderAction.ready) || lines.isEmpty || packed != lines.length ? null : () => act(WorkOrderAction.ready),
              child: const Text('Mark ready')),
          ]),
          const Divider(height: 16),
        ])),
      ));
  }

  @override
  Widget build(BuildContext context) {
    if (order.operational != null) return _operationalTicket(context);
    final packingIntent=_StoreOrderEffectScope.of(context);
    final effectIntent=packingIntent?.operation=='packing'?null:packingIntent;
    Future<void> runEffect(String operation,Future<void> Function() original)async{
      if(effectIntent==null){await original();return;}
      if(!effectIntent.permits(operation))return;
      await effectIntent.perform(()async{if(effectIntent.current())await original();});
    }
    final stage = order.stage;
    final storeId = session.activeWorkspace?.id ?? session.workspaceId;
    final invoiceAccount = session.workspaceFinance?.accountScope;
    final linkedInvoices = detailed ? session.workspaceInvoices.where(
        (invoice) => invoice.orderId == order.id).toList() : <WorkspaceCustomerInvoice>[];
    final inlineInvoice = linkedInvoices.length == 1 ? linkedInvoices.single : null;
    String savedName(WorkspaceBillingDetails? billing) => billing == null ? ''
        : billing.business && billing.businessName.trim().isNotEmpty
        ? billing.businessName.trim() : billing.name.trim();
    final invoiceName = savedName(inlineInvoice?.billingDetails);
    final orderName = savedName(order.billingDetails);
    final exactPayments = detailed && session.workspaceFinance?.workspaceId == storeId
        ? session.workspaceFinance!.payments.where((payment) => payment.valid &&
            payment.orderId == order.id &&
            (inlineInvoice == null || payment.invoiceId == inlineInvoice.id)).toList()
        : <WorkspacePaymentRecord>[];
    final paymentName = exactPayments.length == 1
        ? exactPayments.single.customerName.trim() : '';
    final customerName = invoiceName.isNotEmpty ? invoiceName
        : orderName.isNotEmpty ? orderName
        : paymentName.isNotEmpty ? paymentName : order.customer;
    final hasCustomerName = customerName.trim().isNotEmpty &&
        !RegExp(r'^\+?[\d\s()-]+$').hasMatch(customerName.trim());
    final selectedOrderIdAtBuild = session.currentWorkspaceOrderId;
    final reviewAccountAtBuild = session.contactDraftStore?.accountScope ??
        session.pendingProofStore?.accountScope;
    final reviewLedgerAtBuild = jsonEncode(order.toLedgerJson());
    final legacyAmountAtBuild = session.workspaceOrderAmount;
    final legacyTrackingAtBuild = selectedOrderIdAtBuild == null &&
        session.workspaceOrders.isEmpty && order.id == 'current-store-order' &&
        order.isDeliveryInProgress && stage != 'Ready';
    final legacyReadyAtBuild = active && stage == 'Ready' && order.needsDelivery &&
        selectedOrderIdAtBuild == null && session.workspaceOrders.isEmpty &&
        order.id == 'current-store-order';
    final legacyConfirmedAtBuild = active && stage == 'Confirmed' &&
        selectedOrderIdAtBuild == null && session.workspaceOrders.isEmpty &&
        order.id == 'current-store-order';
    final legacyAssignmentAtBuild = session.workspaceDeliveryAssignment;
    final legacyQuantitiesAtBuild = Map<String, int>.of(order.quantities);
    final legacyContactAtBuild = selectedOrderIdAtBuild == null &&
        session.workspaceOrders.isEmpty && order.id == 'current-store-order';
    bool currentContactFactsAreValid() {
      if (packingIntent?.current()==false || !context.mounted ||
          storeId != (session.activeWorkspace?.id ?? session.workspaceId) ||
          reviewAccountAtBuild != (session.contactDraftStore?.accountScope ??
              session.pendingProofStore?.accountScope) ||
          session.currentWorkspaceOrderId != selectedOrderIdAtBuild ||
          session.busy || session.workspaceOperationsSyncing ||
          session.workspaceHandoverBusy || session.counterDraftSubmitting ||
          session.hasPendingOrderTime ||
          session.currentCollection?.needsReconciliation == true ||
          !identical(session.workspaceDeliveryAssignment, legacyAssignmentAtBuild)) {
        return false;
      }
      final current = session.visibleWorkspaceOrders
          .where((record) => record.id == order.id).firstOrNull;
      if (current == null || current.isClosed || current.isCustomerCollection ||
          current.stage != stage) {
        return false;
      }
      if (!legacyContactAtBuild) {
        return identical(current, order) &&
            jsonEncode(current.toLedgerJson()) == reviewLedgerAtBuild &&
            session.workspaceOrderAmount == legacyAmountAtBuild;
      }
      // An unsaved row is recreated on read; its timestamp is not identity.
      return session.currentWorkspaceOrderId == null &&
          session.workspaceOrders.isEmpty && session.visibleWorkspaceOrders.length == 1 &&
          session.workspaceOrderStage == stage && current.customer == order.customer &&
          current.items == order.items && mapEquals(current.quantities, legacyQuantitiesAtBuild) &&
          current.amount == order.amount && session.workspaceOrderAmount == legacyAmountAtBuild &&
          current.source == order.source && current.payment == order.payment &&
          current.address == order.address && current.fulfilment == order.fulfilment &&
          current.needsDelivery == order.needsDelivery &&
          current.actionDeadline == order.actionDeadline;
    }
    String promotionInputs() => jsonEncode({
      'discount': session.workspaceCounterDiscount.toJson(),
      'products': [for (final product in session.workspaceCatalogueItems)
        if ((legacyQuantitiesAtBuild[product.id] ?? 0) > 0)
          product.toInventoryJson()],
    });
    final legacyPreparingAtBuild = active && stage == 'Preparing' &&
        selectedOrderIdAtBuild == null && session.workspaceOrders.isEmpty &&
        order.id == 'current-store-order';
    final legacyPromotionAtBuild = legacyReadyAtBuild || legacyConfirmedAtBuild || legacyPreparingAtBuild
        ? promotionInputs() : null;
    bool sameStore() =>
        context.mounted &&
        storeId == (session.activeWorkspace?.id ?? session.workspaceId);
    bool currentLegacyDeliveryFactsAreValid() {
      if (!sameStore() ||
          reviewAccountAtBuild != (session.contactDraftStore?.accountScope ??
              session.pendingProofStore?.accountScope) ||
          session.currentWorkspaceOrderId != null ||
          session.workspaceOrders.isNotEmpty || session.busy ||
          session.workspaceOperationsSyncing || session.workspaceHandoverBusy ||
          session.counterDraftSubmitting || session.hasPendingOrderTime ||
          session.currentCollection?.needsReconciliation == true ||
          !identical(session.workspaceDeliveryAssignment, legacyAssignmentAtBuild)) {
        return false;
      }
      final visible = session.visibleWorkspaceOrders;
      if (visible.length != 1) return false;
      final current = visible.single;
      // The model regenerates this unsaved row's createdAt on every read.
      // Guard durable facts here; each caller grants only its captured action.
      return current.id == 'current-store-order' && !current.isClosed &&
          !current.isCustomerCollection && current.isDeliveryInProgress &&
          current.stage == stage && session.workspaceOrderStage == stage &&
          current.customer == order.customer && current.items == order.items &&
          mapEquals(current.quantities, legacyQuantitiesAtBuild) &&
          current.amount == order.amount &&
          session.workspaceOrderAmount == legacyAmountAtBuild &&
          current.source == order.source && current.payment == order.payment &&
          current.address == order.address && current.fulfilment == order.fulfilment &&
          current.needsDelivery == order.needsDelivery &&
          current.actionDeadline == order.actionDeadline;
    }
    bool currentActionIsValid({bool allowLegacyPacking = false}) {
      if (packingIntent?.current()==false || !sameStore() ||
          session.currentWorkspaceOrderId != selectedOrderIdAtBuild ||
          session.busy ||
          session.workspaceOperationsSyncing ||
          session.workspaceHandoverBusy ||
          session.currentCollection?.needsReconciliation == true) {
        return false;
      }
      // The model supports an in-memory Preparing order before a stored ID
      // exists. Only packing/Ready may use it; never select or create a record
      // to get around the stored-order/draft guard. Its sentinel is not identity:
      // reject an old callback if any rendered order facts have been replaced.
      if (allowLegacyPacking && legacyPreparingAtBuild) {
        final visible = session.visibleWorkspaceOrders;
        if (session.currentWorkspaceOrderId != null ||
            session.workspaceOrders.isNotEmpty ||
            session.counterDraftSubmitting || session.hasPendingOrderTime ||
            visible.length != 1) {
          return false;
        }
        final current = visible.single;
        return current.id == order.id && !current.isClosed &&
            !current.isCustomerCollection && current.stage == 'Preparing' &&
            session.workspaceOrderStage == 'Preparing' &&
            current.customer == order.customer && current.items == order.items &&
            mapEquals(current.quantities, order.quantities) &&
            current.amount == order.amount &&
            session.workspaceOrderAmount == legacyAmountAtBuild &&
            current.source == order.source && current.payment == order.payment &&
            current.address == order.address &&
            current.fulfilment == order.fulfilment &&
            current.needsDelivery == order.needsDelivery &&
            current.actionDeadline == order.actionDeadline;
      }
      if (session.currentWorkspaceOrderId != order.id) {
        final current = session.visibleWorkspaceOrders
            .where((record) => record.id == order.id)
            .firstOrNull;
        if (current == null ||
            current.isClosed ||
            current.stage != stage ||
            !session.selectWorkspaceOrder(order.id)) {
          return false;
        }
      }
      return session.workspaceOrderStage == stage &&
          (session.currentWorkspaceOrderId == order.id ||
              (session.currentWorkspaceOrderId == null &&
                  session.visibleWorkspaceOrders.length == 1 &&
                  session.visibleWorkspaceOrders.single.id == order.id));
    }

    final packingLines = stage == 'Preparing' && !order.isCustomerCollection
        ? session.workspacePackingLinesForOrder(order)
        : const <WorkspacePackingLine>[];
    final itemSnapshots = order.hasCompleteItemSnapshot
        ? {for (final line in order.itemSnapshots) line.productId: line}
        : const <String, WorkspaceOrderItemSnapshot>{};
    final packedUnits = packingLines
        .where((line) => line.packed)
        .fold<int>(0, (total, line) => total + line.quantity);
    final totalUnits = packingLines.fold<int>(
      0,
      (total, line) => total + line.quantity,
    );
    final readyAssignmentAtBuild = stage == 'Ready' && order.needsDelivery &&
        !order.isCustomerCollection && legacyAssignmentAtBuild != null &&
        legacyAssignmentAtBuild.orderId == order.id;
    final nextAction = switch (stage) {
      'Confirmed' => 'Accept',
      'Preparing' => 'Mark ready',
      'Ready for pickup' => 'Confirm pickup',
      'Ready' when readyAssignmentAtBuild => 'Track delivery',
      'Ready' when order.needsDelivery => 'Arrange delivery',
      'Ready' => 'Complete pickup',
      'Delivery requested' => 'Track delivery',
      _ when order.isDeliveryInProgress => 'Track delivery',
      _ => 'Review',
    };
    Future<void> originalMarkReadyAndOpenDelivery() async {
      if (stage != 'Preparing' || !currentContactFactsAreValid() ||
          (legacyPreparingAtBuild && promotionInputs() != legacyPromotionAtBuild) ||
          !currentActionIsValid(allowLegacyPacking: true) ||
          !session.workspaceCanMarkReady) {
        return;
      }
      final targetId = session.currentWorkspaceOrderId;
      final target = session.currentWorkspaceOrder;
      final scopedCommand = targetId != null && session.hasScopedWorkspaceOrder(targetId);
      String readyFacts(Map<String, Object?> facts) {
        facts
          ..remove('stage')
          ..remove('actionDeadline');
        // A successful scoped reply owns its fulfilment timing. Commercial,
        // customer and order facts below still have to match the captured order.
        if (scopedCommand) facts.remove('fulfilmentDeadline');
        if (legacyPreparingAtBuild) {
          facts.remove('id');
          facts.remove('createdAt');
        }
        return jsonEncode(facts);
      }
      final expected = target?.toLedgerJson() ?? order.copyWith(
        amount: session.workspaceCounterDiscount.isEmpty
            ? order.amount : session.workspaceCounterPayableMinor ~/ 100,
        itemSnapshots: session.workspaceCounterPurchasedItems,
      ).toLedgerJson();
      if (legacyPreparingAtBuild) {
        expected['remainderPaise'] = session.workspaceCounterDiscount.isEmpty
            ? 0 : session.workspaceCounterPayableMinor % 100;
        expected['discount'] = session.workspaceCounterDiscount.toJson();
        expected['discountMinor'] = session.workspaceCounterDiscountMinor;
      }
      final capturedFacts = readyFacts(expected);
      Object? assignmentFacts(WorkspaceDeliveryAssignment? assignment) =>
          assignment == null ? null : (
            assignment.orderId, assignment.partnerName, assignment.vehicleLabel,
            assignment.eta.toUtc(), assignment.stage, assignment.updatedAt?.toUtc(),
          );
      final capturedAssignmentFacts = assignmentFacts(legacyAssignmentAtBuild);
      if (scopedCommand) {
        // Await the existing authority, never dispatch readiness a second time.
        if (!await session.submitWorkspaceOrderAction(targetId, WorkOrderAction.ready,inputCurrent:effectIntent?.current)) {
          return;
        }
      } else {
        _advanceDeskOrder(session, expectedOrderId: order.id);
      }
      final ready = session.currentWorkspaceOrder;
      if (!sameStore() ||
          reviewAccountAtBuild != (session.contactDraftStore?.accountScope ?? session.pendingProofStore?.accountScope) ||
          ready == null || session.currentWorkspaceOrderId != ready.id ||
          (legacyPreparingAtBuild && (session.workspaceOrders.length != 1 ||
              !identical(session.workspaceOrders.single, ready))) ||
          (targetId != null && ready.id != targetId) ||
          readyFacts(ready.toLedgerJson()) != capturedFacts ||
          ready.stage != 'Ready' || session.workspaceOrderStage != 'Ready' ||
          !ready.needsDelivery || ready.isCustomerCollection ||
          session.busy || (scopedCommand && session.workspaceOperationsSyncing) ||
          session.workspaceHandoverBusy || session.counterDraftSubmitting ||
          session.hasPendingOrderTime || session.currentCollection?.needsReconciliation == true ||
          (scopedCommand
              ? assignmentFacts(session.workspaceDeliveryAssignment) != capturedAssignmentFacts
              : !identical(session.workspaceDeliveryAssignment, legacyAssignmentAtBuild))) {
        return;
      }
      // Ready opens its working desk only; booking remains an explicit action.
      onOpenDelivery();
    }
    Future<void> markReadyAndOpenDelivery()=>runEffect('ready',originalMarkReadyAndOpenDelivery);
    bool keyboardVisible() => MediaQuery.viewInsetsOf(context).bottom > 0 ||
        View.of(context).viewInsets.bottom > 0;
    bool confirmedCommandIsValid() {
      if (stage != 'Confirmed' || !currentContactFactsAreValid() || keyboardVisible() ||
          order.actionDeadline?.isAfter(DateTime.now()) == false) {
        return false;
      }
      if (legacyConfirmedAtBuild) {
        return promotionInputs() == legacyPromotionAtBuild;
      }
      // Validate captured facts before selecting the displayed stored row.
      return currentActionIsValid();
    }
    void acceptConfirmedOrder() {
      if(!confirmedCommandIsValid())return;
      unawaited(runEffect('accept',()async{
        if(!confirmedCommandIsValid())return;
        if(effectIntent!=null&&session.hasScopedWorkspaceOrder(order.id)){
          await session.submitWorkspaceOrderAction(order.id,WorkOrderAction.accept,inputCurrent:effectIntent.current);
        }else{_advanceDeskOrder(session,expectedOrderId:order.id);}
      }));
    }
    Future<void> rejectConfirmedOrder()async {
      if(!confirmedCommandIsValid())return;
      await runEffect('reject',()async{
        if(confirmedCommandIsValid())await _showRejectOrderSheet(context,session,
          inputCurrent:effectIntent?.current,ownerChanges:effectIntent?.changes);
      });
    }
    final showContactActions = packingIntent==null && (active || detailed) && !order.isClosed &&
        !order.isCustomerCollection &&
        (stage == 'Confirmed' || stage == 'Preparing');
    final contactActions = _DeskCustomerActions(
      customer: order.customer, orderId: order.id,
      canAct: currentContactFactsAreValid,
      chatKey: stage == 'Preparing'
          ? const Key('work-packing-contact-customer') : null,
      chatDraft: stage == 'Preparing'
          ? 'I need to confirm a product or quantity in your ₹${legacyContactAtBuild ? legacyAmountAtBuild : _formatStoreMinorAmount(order.payableMinor)} order.' : null,
    );
    return _OrderDeadlineBoundary(
      deadline: stage == 'Confirmed' ? order.actionDeadline : null,
      observeMetrics: true,
      builder: (expired) => GestureDetector(
        key: const Key('work-order-command-swipe'),
        onHorizontalDragEnd: stage == 'Confirmed' && !keyboardVisible() ? (details) {
          if (expired) {
            return;
          }
          final velocity = details.primaryVelocity ?? 0;
          if (velocity > 380) {
            acceptConfirmedOrder();
          } else if (velocity < -380) {
            rejectConfirmedOrder();
          }
        } : null,
        child: Material(
        key: const Key('work-live-order-ticket'),
        color: Colors.white,
        elevation: 0,
        shadowColor: const Color(0x16001B4D),
        borderRadius: BorderRadius.circular(12),
        child: Padding(
          padding: EdgeInsets.symmetric(
            horizontal:
                detailed ? 0 : MediaQuery.sizeOf(context).width < 360 &&
                    MediaQuery.textScalerOf(context).scale(1) >= 2
                ? 6
                : 13,
            vertical: detailed ? 4 : 13,
          ),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              if (detailed) ...[
                Wrap(spacing: 10, runSpacing: 2, crossAxisAlignment: WrapCrossAlignment.center,
                    children: [Text(hasCustomerName ? customerName : order.customer,
                    key: hasCustomerName ? const Key('work-order-customer-name') : null,
                    style: const TextStyle(
                    color: MoolColors.ink, fontSize: 13, fontWeight: FontWeight.w600)),
                if (hasCustomerName && customerName != order.customer)
                  Text(order.customer, style: const TextStyle(
                      color: MoolColors.muted, fontSize: 11)),
                if (!hasCustomerName)
                  const Text('Customer name not recorded',
                      key: Key('work-order-customer-name'),
                      style: TextStyle(color: MoolColors.muted, fontSize: 11))]),
                Text(order.id, key: const Key('work-focused-order-id'),
                    style: const TextStyle(color: MoolColors.muted, fontSize: 11)),
                const SizedBox(height: 2),
              ] else if (order.isCustomerCollection)
                Text(
                  '${order.id} · ${session.workspaceOrderStageLabel(order)}',
                  key: Key('work-order-stage-label-${order.id}'),
                  style: const TextStyle(
                    fontSize: 12,
                    color: MoolColors.navy,
                    fontWeight: FontWeight.w700,
                  ),
                )
              else
                _StoreMoneyLine(
                  leading: Wrap(
                    spacing: 8,
                    runSpacing: 2,
                    crossAxisAlignment: WrapCrossAlignment.center,
                    children: [
                      Text(
                        stage == 'Confirmed'
                            ? expired
                                  ? 'Order update pending'
                                  : order.actionDeadline != null
                                  ? 'Accept within'
                                  : 'Awaiting acceptance'
                            : stage,
                        key: Key('work-order-stage-label-${order.id}'),
                        style: const TextStyle(
                          color: MoolColors.navy,
                          fontSize: 10,
                          fontWeight: FontWeight.w900,
                        ),
                      ),
                      if (order.actionDeadline case final deadline?)
                        _LiveCountdownText(
                          deadline: deadline,
                          fallback: 'Review',
                          style: const TextStyle(
                            color: MoolColors.navy,
                            fontSize: 10,
                            fontWeight: FontWeight.w900,
                          ),
                        ),
                    ],
                  ),
                  value: '₹${_formatStoreMinorAmount(order.payableMinor)}',
                  style: const TextStyle(
                    color: MoolColors.navy,
                    fontSize: 19,
                    fontWeight: FontWeight.w900,
                  ),
                ),
              if (!detailed) const SizedBox(height: 8),
              if (!detailed)
                LayoutBuilder(builder: (context, constraints) {
                  const customerStyle = TextStyle(
                    color: MoolColors.ink, fontSize: 16,
                    fontWeight: FontWeight.w900,
                  );
                  const factsStyle = TextStyle(color: MoolColors.muted, fontSize: 10.5);
                  final factsText = order.isCustomerCollection
                      ? '${session.workspaceOrderPaymentLabel(order)} · Collect at store'
                      : '${order.source} · ${session.workspaceOrderPaymentLabel(order)} · ${order.fulfilment}';
                  final facts = Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(order.customer, style: customerStyle),
                      Text(factsText, style: factsStyle),
                    ],
                  );
                  if (!showContactActions) return facts;
                  double widthOf(String text, TextStyle style) {
                    final painter = TextPainter(
                      text: TextSpan(text: text,
                        style: DefaultTextStyle.of(context).style.merge(style)),
                      textDirection: Directionality.of(context),
                      textScaler: MediaQuery.textScalerOf(context),
                      locale: Localizations.maybeLocaleOf(context),
                      maxLines: 1,
                    )..layout();
                    final width = painter.width;
                    painter.dispose();
                    return width;
                  }
                  final customerWidth = widthOf(order.customer, customerStyle);
                  final factsWidth = widthOf(factsText, factsStyle);
                  final fits = (customerWidth > factsWidth ? customerWidth : factsWidth) +
                      100 <= constraints.maxWidth;
                  return fits
                      ? Row(children: [
                          Expanded(child: facts),
                          const SizedBox(width: 4),
                          contactActions,
                        ])
                      : Column(crossAxisAlignment: CrossAxisAlignment.start,
                          children: [facts,
                            Align(alignment: Alignment.centerRight, child: contactActions)]);
                }),
              if (!detailed) const SizedBox(height: 7),
              if (detailed && showContactActions)
                Align(alignment: Alignment.centerRight,
                  child: contactActions),
              if (detailed)
                _ExactOrderInformation(
                  order: order,
                  showItems: packingLines.isEmpty && inlineInvoice == null,
                  showAmounts: inlineInvoice == null,
                  showPayment: inlineInvoice == null,
                  paymentLabel: session.workspaceFinanceStale
                      ? 'Last saved: ${session.workspaceOrderPaymentLabel(order)}'
                      : session.workspaceOrderPaymentLabel(order),
                  invoiceStyle: true,
                  stageLabel: session.workspaceOrderStageLabel(order),
                ),
              if (detailed && inlineInvoice != null)
                _StoreInvoiceSurface(
                  key: ValueKey((storeId, invoiceAccount, inlineInvoice.id)),
                  session: session, invoice: inlineInvoice, embedded: true,
                  orderDetails: true, onClose: () {}),
              if (detailed && linkedInvoices.length > 1)
                const Text('Invoice link needs review. Return to Sales to check the original bill.',
                    key: Key('work-order-invoice-link-unavailable'),
                    style: TextStyle(color: MoolColors.muted, fontSize: 12)),
              if (detailed && inlineInvoice == null && linkedInvoices.isEmpty)
                const Text('No linked invoice in the saved records.',
                    style: TextStyle(color: MoolColors.muted, fontSize: 11)),
              if(packingIntent==null)_StoreIssueReviews(
                session: session,
                target: WorkspaceIssueTarget.customerOrder,
                referenceId: order.id,
              ),
              if (!detailed && packingLines.isEmpty)
                Text(
                  order.items,
                  style: const TextStyle(
                    color: MoolColors.ink,
                    fontSize: 11,
                    fontWeight: FontWeight.w700,
                  ),
                ),
              if(effectIntent!=null)_ExactOrderInformation(order:order,showItems:true),
              if (effectIntent==null&&packingLines.isNotEmpty) ...[
                const SizedBox(height: 10),
                Row(
                  children: [
                    Expanded(
                      child: LinearProgressIndicator(
                        value: totalUnits == 0 ? 0 : packedUnits / totalUnits,
                        minHeight: 7,
                        borderRadius: BorderRadius.circular(999),
                      ),
                    ),
                    const SizedBox(width: 10),
                    Text(
                      '$packedUnits/$totalUnits packed',
                      style: const TextStyle(
                        color: MoolColors.navy,
                        fontSize: 10,
                        fontWeight: FontWeight.w900,
                      ),
                    ),
                  ],
                ),
                const SizedBox(height: 5),
                for (final line in packingLines.where((line)=>packingIntent==null||line.id==packingIntent.packingLineId))
                  Material(
                    color: const Color(0xFFF4F6FF),
                    borderRadius: BorderRadius.circular(12),
                    child: CheckboxListTile(
                      key: Key(
                        active
                            ? 'work-order-pack-${line.id}'
                            : 'work-order-pack-${order.id}-${line.id}',
                      ),
                      dense: true,
                      minTileHeight: 48,
                      visualDensity: VisualDensity.compact,
                      contentPadding: const EdgeInsets.symmetric(horizontal: 8),
                      controlAffinity: ListTileControlAffinity.trailing,
                      value: line.packed,
                      onChanged: (value) {
                        if (!sameStore() ||
                            (active && !currentActionIsValid(
                                allowLegacyPacking: true))) {
                          return;
                        }
                        if(packingIntent!=null){
                          if(!packingIntent.permits('packing')||packingIntent.packingLineId!=line.id||packingIntent.packingQuantity!=line.quantity||packingIntent.packingValue!=(value==true))return;
                          unawaited(packingIntent.perform(()async{if(!sameStore()||!packingIntent.current())return;
                            session.setWorkspaceOrderPackingLine(storeId:storeId,orderId:order.id,lineId:line.id,quantity:line.quantity,packed:value==true);}));return;
                        }
                        session.setWorkspaceOrderPackingLine(
                          storeId: storeId,
                          orderId: order.id,
                          lineId: line.id,
                          quantity: line.quantity,
                          packed: value == true,
                        );
                      },
                      title: Text(
                        detailed && itemSnapshots.containsKey(line.id)
                            ? '${itemSnapshots[line.id]!.name} · '
                                  '${itemSnapshots[line.id]!.pack} × ${line.quantity}'
                            : '${line.label} × ${line.quantity}',
                        style: const TextStyle(
                          color: MoolColors.ink,
                          fontSize: 10.5,
                          fontWeight: FontWeight.w800,
                        ),
                      ),
                      subtitle: detailed && itemSnapshots.containsKey(line.id)
                          ? Text(
                              'Each ${_ExactOrderInformation._price(itemSnapshots[line.id]!.unitPricePaise)} · '
                              'Total ${_ExactOrderInformation._price(itemSnapshots[line.id]!.lineTotalPaise)}',
                              style: const TextStyle(
                                color: MoolColors.muted,
                                fontSize: 12,
                              ),
                            )
                          : null,
                    ),
                  ),
              ],
              if (packingIntent==null && stage == 'Confirmed' && order.actionDeadline != null && !keyboardVisible())
                Align(
                  alignment: Alignment.centerRight,
                  child: TextButton(
                    key: Key('work-order-more-time-${order.id}'),
                    style: TextButton.styleFrom(minimumSize: const Size(48, 48)),
                    onPressed: session.busy || session.workspaceOperationsSyncing ||
                            session.workspaceHandoverBusy || session.orderTimeRequestBusy ||
                            session.workspaceOrderOperationState(order.id) != null
                        ? null
                        : () {
                            if (currentActionIsValid()) {
                              _showOrderTimeRequest(context, session);
                            }
                          },
                    child: const Text('More time'),
                  ),
                ),
              if (order.isCustomerCollection)
                Align(
                  alignment: Alignment.centerRight,
                  child: TextButton(
                    key: Key('work-order-collection-open-${order.id}'),
                    onPressed: () {
                      if (sameStore() &&
                          session.selectWorkspaceOrder(order.id)) {
                        onOpenCollection();
                      }
                    },
                    child: Text(
                      order.isClosed ? 'View collection' : 'Open collection',
                    ),
                  ),
                )
              else if (session.workspaceOrderOperationState(order.id) != null)
                _OrderOperationStatus(session: session, orderId: order.id)
              else if (stage == 'Confirmed' && keyboardVisible())
                const SizedBox.shrink()
              else if ((active && !order.isClosed) ||
                  (detailed && !order.isClosed && stage != 'Preparing')) ...[
                const SizedBox(height: 10),
                Wrap(
                  alignment: WrapAlignment.end,
                  spacing: 12,
                  crossAxisAlignment: WrapCrossAlignment.center,
                  children: [
                    if (packingIntent==null && stage == 'Confirmed')
                      TextButton(
                        key: const Key('work-activity-order-review'),
                        onPressed: currentContactFactsAreValid() ? () {
                          // Inspect the exact rendered order; never select/promote it.
                          if (currentContactFactsAreValid()) {
                            onReview();
                          }
                        } : null,
                        style: TextButton.styleFrom(minimumSize: const Size(48, 48)),
                        child: const Text('Review'),
                      ),
                    if (stage == 'Confirmed')
                      TextButton(
                        key: const Key('work-activity-order-reject'),
                        onPressed:
                            expired ||
                                session.hasPendingOrderTime ||
                                session.busy ||
                                session.workspaceOperationsSyncing || effectIntent?.permits('reject')==false
                            ? null
                            : rejectConfirmedOrder,
                        child: const Text('Reject'),
                      ),
                    FilledButton.icon(
                      key: stage == 'Confirmed' ? const Key('work-activity-order-accept') : null,
                      onPressed:
                          expired || effectIntent?.permits(stage=='Confirmed'?'accept':'ready')==false ||
                              (stage == 'Confirmed' && session.hasPendingOrderTime) ||
                              session.busy ||
                              session.workspaceOperationsSyncing ||
                              session.workspaceHandoverBusy ||
                              (stage == 'Preparing' &&
                                  !session.workspaceCanMarkReady)
                          ? null
                          : () {
                              if (stage == 'Confirmed') {
                                acceptConfirmedOrder();
                                return;
                              }
                              if (stage == 'Preparing') {
                                markReadyAndOpenDelivery();
                                return;
                              }
                              if (nextAction == 'Track delivery' && readyAssignmentAtBuild) {
                                if (currentContactFactsAreValid() &&
                                    (legacyContactAtBuild || currentActionIsValid())) {
                                  onOpenDelivery();
                                }
                                return;
                              }
                              if (nextAction == 'Track delivery' && legacyTrackingAtBuild) {
                                if (currentLegacyDeliveryFactsAreValid()) onOpenDelivery();
                                return;
                              }
                              if (nextAction == 'Arrange delivery' && legacyReadyAtBuild) {
                                if (!currentLegacyDeliveryFactsAreValid() ||
                                    promotionInputs() != legacyPromotionAtBuild) {
                                  return;
                                }
                                // Promotion and assignment remain the existing model's
                                // command. Never open as if a refused command succeeded.
                                session.advanceWorkspaceOrder();
                                if (session.workspaceOrderStage == 'Delivery requested' &&
                                    session.currentWorkspaceOrder?.stage == 'Delivery requested') {
                                  onOpenDelivery();
                                }
                                return;
                              }
                              if (nextAction == 'Review') {
                                final current = session.visibleWorkspaceOrders
                                    .where((record) => record.id == order.id)
                                    .firstOrNull;
                                if ((session.contactDraftStore?.accountScope ??
                                        session.pendingProofStore?.accountScope) !=
                                        reviewAccountAtBuild ||
                                    !identical(current, order) ||
                                    jsonEncode(current!.toLedgerJson()) !=
                                        reviewLedgerAtBuild ||
                                    !currentActionIsValid()) {
                                  return;
                                }
                                onReview();
                                return;
                              }
                              if ((stage == 'Confirmed' && session.hasPendingOrderTime) ||
                                  !currentActionIsValid(
                                      allowLegacyPacking: stage == 'Preparing') ||
                                  (stage == 'Preparing' &&
                                      !session.workspaceCanMarkReady)) {
                                return;
                              }
                              if (stage == 'Ready for pickup') {
                                _showWorkspacePickupSheet(context, session);
                              } else if (order.isDeliveryInProgress &&
                                  stage != 'Ready') {
                                onOpenDelivery();
                              } else if (stage == 'Ready' &&
                                  order.needsDelivery) {
                                session.advanceWorkspaceOrder();
                                onOpenDelivery();
                              } else {
                                _advanceDeskOrder(
                                  session,
                                  expectedOrderId: order.id,
                                );
                              }
                            },
                      style: FilledButton.styleFrom(
                        minimumSize: const Size(48, 48),
                        padding: const EdgeInsets.symmetric(horizontal: 16),
                      ),
                      icon: const Icon(Icons.arrow_forward_rounded, size: 17),
                      label: Text(nextAction),
                    ),
                  ],
                ),
              ] else if (stage == 'Preparing' && (packingIntent==null||effectIntent?.operation=='ready')) ...[
                Align(
                  alignment: Alignment.centerRight,
                  child: FilledButton(
                    key: Key('work-order-ready-${order.id}'),
                    onPressed:
                        effectIntent?.permits('ready')==false || session.busy ||
                            session.workspaceOperationsSyncing ||
                            session.workspaceHandoverBusy ||
                            packingLines.isEmpty ||
                            packingLines.any((line) => !line.packed)
                        ? null
                        : () {
                            final current = session.visibleWorkspaceOrders
                                .where((record) => record.id == order.id)
                                .firstOrNull;
                            final currentLines = current == null
                                ? const <WorkspacePackingLine>[]
                                : session.workspacePackingLinesForOrder(
                                    current,
                                  );
                            if (!sameStore() ||
                                current?.stage != 'Preparing' ||
                                current?.isCustomerCollection == true ||
                                currentLines.isEmpty ||
                                currentLines.any((line) => !line.packed)) {
                              return;
                            }
                            markReadyAndOpenDelivery();
                          },
                    child: const Text('Order ready'),
                  ),
                ),
              ] else if (!order.isClosed) ...[
                Align(
                  alignment: Alignment.centerRight,
                  child: TextButton(
                    key: Key('work-order-open-${order.id}'),
                    onPressed:
                        session.busy ||
                            session.workspaceOperationsSyncing ||
                            session.workspaceHandoverBusy
                        ? null
                        : () {
                            if (sameStore()) {
                              session.selectWorkspaceOrder(order.id);
                            }
                          },
                    child: const Text('Open order'),
                  ),
                ),
              ],
            ],
          ),
        ),
      ),
      ),
    );
  }
}

class _DeliveryDestinationSurface extends StatelessWidget {
  const _DeliveryDestinationSurface({
    required this.session,
    required this.onCreateOrder,
  });

  final WorkSession session;
  final VoidCallback onCreateOrder;

  @override
  Widget build(BuildContext context) {
    final hasConfirmedDelivery =
        session.workspaceOrderCustomer.isNotEmpty &&
        session.workspaceOrderNeedsDelivery;
