class _CustomersDestinationSurface extends StatefulWidget {
  const _CustomersDestinationSurface({
    required this.session,
    required this.onRepeatBasket,
    required this.onOffer,
    this.customerId,this.preparedSearch,this.reviewScope,this.repeatOnly=false,this.preparedRepeatCurrent,this.preparedRepeatChanges,
  });

  final WorkSession session;
  final ValueChanged<String> onRepeatBasket;
  final VoidCallback onOffer;
  final String? customerId,preparedSearch;
  final bool repeatOnly;final bool Function()? preparedRepeatCurrent;final Listenable? preparedRepeatChanges;
  final StoreCustomerActionReviewScope? reviewScope;

  @override
  State<_CustomersDestinationSurface> createState() =>
      _CustomersDestinationSurfaceState();
}

class _CustomersDestinationSurfaceState
    extends State<_CustomersDestinationSurface> {
  late final TextEditingController _search = TextEditingController(
    text: widget.preparedSearch??widget.session.workspaceCustomerSearch,
  );

  late String _preparedFilter=widget.session.workspaceCustomerFilter;
  void _changeSearch(String value){if(widget.reviewScope==null){widget.session.updateWorkspaceCustomerSearch(value);}else if(widget.reviewScope!.current()){setState((){});}}
  void _changeFilter(String value){if(widget.reviewScope==null){widget.session.setWorkspaceCustomerFilter(value);}else if(widget.reviewScope!.current()){setState(()=>_preparedFilter=value);}}
  @override
  void dispose() {
    _search.dispose();
    super.dispose();
  }

  bool _sameCustomer(String storeId, WorkspaceCustomerRecord customer) =>
      mounted && widget.preparedRepeatCurrent?.call()!=false &&
      (widget.reviewScope==null||widget.reviewScope!.current()&&ModalRoute.of(context)?.isCurrent==true) &&
      storeId == widget.session.activeWorkspace?.id &&
      widget.session.workspaceCustomerBook.any(
        (current) =>
            current.id == customer.id &&
            current.mobile == customer.mobile &&
            current.name == customer.name,
      );

  Future<void> _call(String storeId, WorkspaceCustomerRecord customer) async {
    if (!_sameCustomer(storeId, customer)) return;
    final mobile = normalizeWorkspaceMobile(customer.mobile);
    if (mobile == null) return;
    try {
      if (await launchUrl(Uri(scheme: 'tel', path: mobile))) return;
    } catch (_) {
      // A launch attempt cannot confirm a completed call.
    }
    if (_sameCustomer(storeId, customer)) {
      widget.session.showError(
        'Could not open your phone app. Please try again.',
      );
    }
  }

  Future<void> _whatsApp(
    String storeId,
    WorkspaceCustomerRecord customer,
  ) async {
    if (!_sameCustomer(storeId, customer)) return;
    final mobile = normalizeWorkspaceMobile(customer.mobile);
    if (mobile == null) return;
    final uri = Uri.https('wa.me', '/91$mobile', {
      'text':
          'Hello ${customer.name}, this is ${widget.session.activeWorkspace?.name ?? widget.session.workName}.',
    });
    try {
      if (await launchUrl(uri, mode: LaunchMode.externalApplication)) return;
    } catch (_) {
      // Opening WhatsApp does not prove that a message was sent.
    }
    if (_sameCustomer(storeId, customer)) {
      widget.session.showError('WhatsApp could not open. Try Chat or retry.');
    }
  }

  void _chat(
    BuildContext context,
    String storeId,
    WorkspaceCustomerRecord customer,
  ) {
    if (!_sameCustomer(storeId, customer)) return;
    context.push(
      Uri(
        path: '/app/chat/inbox',
        queryParameters: {
          'return': GoRouterState.of(context).uri.toString(),
          'type': 'business',
          'recipient': customer.mobile.isEmpty
              ? customer.name
              : customer.mobile,
          'name': customer.name,
          'draft': 'Customer support for ${customer.name}',
        },
      ).toString(),
    );
  }

  void _invoice(BuildContext context, WorkspaceCustomerRecord customer) {
    final invoice = widget.session.workspaceInvoices
        .where(
          (invoice) =>
              widget.session.workspaceCustomerId(invoice.customer) ==
              customer.id,
        )
        .firstOrNull;
    if (invoice == null) {
      widget.session.showError(
        'No invoice is available for this customer yet.',
      );
      return;
    }
    _showWorkspaceInvoiceSheet(context, widget.session, invoice);
  }

  Future<void> _showCustomer(
    BuildContext context,
    String storeId,
    WorkspaceCustomerRecord customer,
  ) async {
    if (!_sameCustomer(storeId, customer)) return;
    final contactErrorKey = GlobalKey();
    Future<void> contact(Future<void> Function() launch) async {
      await launch();
      if (!_sameCustomer(storeId, customer) ||
          widget.session.errorMessage == null) {
        return;
      }
      WidgetsBinding.instance.addPostFrameCallback((_) {
        final target = contactErrorKey.currentContext;
        if (_sameCustomer(storeId, customer) &&
            target != null &&
            target.mounted) {
          unawaited(Scrollable.ensureVisible(target, alignment: 0));
        }
      });
    }

    final inheritedOwnerChanges=context.getInheritedWidgetOfExactType<MoolAssistantHost>()?.contextChanges;
    final largeAmounts =
        customer.totalSpend >= 10000000 ||
        customer.amountDueMinor.abs() >= 1000000000 ||
        MediaQuery.textScalerOf(context).scale(1) > 1.4;
    await showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      useSafeArea: true,
      showDragHandle: true,
      builder: (sheetContext) {
        final ownSheetRoute=ModalRoute.of(sheetContext),ownSheetNavigator=Navigator.of(sheetContext);
        return _purchaseCapturedOwnerPage(context,sheetContext,widget.session,widget.preparedRepeatCurrent,FractionallySizedBox(
        heightFactor: .72,
        child: CustomScrollView(
          slivers: [
            SliverToBoxAdapter(
              child: Column(
                children: [
                  Padding(
                    padding: const EdgeInsets.symmetric(horizontal: 16),
                    child: Row(
                      children: [
                        CircleAvatar(
                          backgroundColor: const Color(0xFFE5EAFF),
                          foregroundColor: MoolColors.navy,
                          child: Text(
                            customer.name.substring(0, 1).toUpperCase(),
                            style: const TextStyle(fontWeight: FontWeight.w900),
                          ),
                        ),
                        const SizedBox(width: 10),
                        Expanded(
                          child: Column(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              Text(
                                customer.name,
                                maxLines: 1,
                                overflow: TextOverflow.ellipsis,
                                style: const TextStyle(
                                  color: MoolColors.navy,
                                  fontSize: 18,
                                  fontWeight: FontWeight.w900,
                                ),
                              ),
                              Text(
                                customer.mobile.isEmpty
                                    ? 'Phone number unavailable'
                                    : customer.mobile,
                                style: const TextStyle(color: MoolColors.muted),
                              ),
                            ],
                          ),
                        ),
                        if ((customer.hasDues || !customer.balanceAvailable) &&
                            !largeAmounts)
                          Text(
                            customer.balanceAvailable
                                ? '${_customerBalanceText(customer)} due'
                                : 'Balance unavailable',
                            style: const TextStyle(
                              color: Color(0xFFB42318),
                              fontWeight: FontWeight.w900,
                            ),
                          ),
                      ],
                    ),
                  ),
                  if (largeAmounts &&
                      (customer.hasDues || !customer.balanceAvailable))
                    Padding(
                      padding: const EdgeInsets.symmetric(horizontal: 16),
                      child: _MoneyDestinationLine(
                        label: 'Payment due',
                        value: _customerBalanceText(customer),
                      ),
                    ),
                  StoreCustomerPaymentTerms(
                    key: ValueKey('customer-terms-$storeId-${customer.id}'),
                    session: widget.session,
                    storeId: storeId,
                    customerId: customer.id,
                  ),
                  AnimatedBuilder(
                    key: contactErrorKey,
                    animation: widget.session,
                    builder: (context, _) => _sameCustomer(storeId, customer)
                        ? WorkMessageBanner(session: widget.session)
                        : const SizedBox.shrink(),
                  ),
                  const SizedBox(height: 10),
                  Padding(
                    padding: const EdgeInsets.symmetric(horizontal: 8),
                    child: _CustomerActionBar(
                      children: [
                        if(!widget.repeatOnly)_CustomerAction(
                          icon: Icons.call_outlined,
                          label: 'Call',
                          onTap: customer.mobile.isEmpty
                              ? null
                              : () => contact(() => _call(storeId, customer)),
                        ),
                        if(!widget.repeatOnly)_CustomerAction(
                          icon: Icons.chat_bubble_outline_rounded,
                          label: 'Chat',
                          onTap: () {
                            Navigator.pop(sheetContext);
                            _chat(context, storeId, customer);
                          },
                        ),
                        if(!widget.repeatOnly)_CustomerAction(
                          icon: Icons.message_outlined,
                          label: 'WhatsApp',
                          onTap: customer.mobile.isEmpty
                              ? null
                              : () =>
                                    contact(() => _whatsApp(storeId, customer)),
                        ),
                        _CustomerAction(
                          keyName: 'work-customer-repeat',
                          icon: Icons.repeat_rounded,
                          label: 'Repeat',
                          onTap: ()async {
                            if(!sheetContext.mounted||ownSheetRoute?.isActive!=true||ownSheetRoute?.isCurrent!=true||!_sameCustomer(storeId,customer))return;
                            final repeat=widget.onRepeatBasket,waitForOwnedClose=widget.repeatOnly;
                            ownSheetNavigator.pop();
                            // The captured AI owner can switch to the counter desk.
                            // Let only its own native sheet finish before that handoff.
                            if(waitForOwnedClose){await ownSheetRoute!.completed;if(!mounted||!_sameCustomer(storeId,customer))return;}
                            repeat(customer.id);
                          },
                        ),
                        if(!widget.repeatOnly)_CustomerAction(
                          icon: Icons.receipt_long_outlined,
                          label: 'Invoice',
                          onTap: () => _invoice(sheetContext, customer),
                        ),
                        if(!widget.repeatOnly)_CustomerAction(
                          icon: Icons.local_offer_outlined,
                          label: customer.messagesAllowed
                              ? 'Send offer'
                              : 'Offer locked',
                          onTap: customer.messagesAllowed
                              ? () {
                                  Navigator.pop(sheetContext);
                                  widget.onOffer();
                                }
                              : null,
                        ),
                      ],
                    ),
                  ),
                  Padding(
                    padding: const EdgeInsets.symmetric(horizontal: 16),
                    child: largeAmounts
                        ? Column(
                            children: [
                              _MoneyDestinationLine(
                                label: 'Orders',
                                value: '${customer.orderCount}',
                              ),
                              _MoneyDestinationLine(
                                label: 'Total purchases',
                                value:
                                    '₹${_formatStoreMinorAmount(customer.totalSpendMinor)}',
                              ),
                              _MoneyDestinationLine(
                                label: 'Average purchase',
                                value:
                                    '₹${_formatStoreAmount(customer.averageBasket)}',
                              ),
                            ],
                          )
                        : Row(
                            children: [
                              _CustomerMiniFact(
                                label: 'Orders',
                                value: '${customer.orderCount}',
                              ),
                              _CustomerMiniFact(
                                label: 'Spent',
                                value:
                                    '₹${_formatStoreMinorAmount(customer.totalSpendMinor)}',
                              ),
                              _CustomerMiniFact(
                                label: 'Average',
                                value:
                                    '₹${_formatStoreAmount(customer.averageBasket)}',
                              ),
                            ],
                          ),
                  ),
                  if (!customer.messagesAllowed)
                    const Padding(
                      padding: EdgeInsets.fromLTRB(16, 8, 16, 2),
                      child: Text(
                        'Order help remains available. Send promotional offers only after the customer allows store messages.',
                        style: TextStyle(color: MoolColors.muted, fontSize: 10),
                      ),
                    ),
                  const Divider(height: 18),
                ],
              ),
            ),
            SliverPadding(
              padding: const EdgeInsets.fromLTRB(16, 0, 16, 20),
              sliver: SliverList.separated(
                itemCount: customer.orders.length,
                separatorBuilder: (_, _) => const SizedBox(height: 7),
                itemBuilder: (context, index) {
                  final order = customer.orders[index];
                  return WorkCard(
                    keyName: 'work-customer-order-${order.id}',
                    padding: const EdgeInsets.all(10),
                    child: _StoreMoneyLine(
                      leading: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Text(
                            order.items,
                            style: const TextStyle(
                              color: MoolColors.ink,
                              fontWeight: FontWeight.w900,
                            ),
                          ),
                          Text(
                            '${order.payment} · ${widget.session.workspaceOrderStageLabel(order)} · ${order.createdAt.day}/${order.createdAt.month}/${order.createdAt.year}',
                            style: const TextStyle(
                              color: MoolColors.muted,
                              fontSize: 9.5,
                            ),
                          ),
                        ],
                      ),
                      value: '₹${_formatStoreMinorAmount(order.payableMinor)}',
                      style: const TextStyle(
                        color: MoolColors.navy,
                        fontWeight: FontWeight.w900,
                      ),
                    ),
                  );
                },
              ),
            ),
          ],
        ),
      ),ownerChanges:widget.preparedRepeatChanges,capturedContextChanges:inheritedOwnerChanges,useCapturedContextChanges:true);
      },
    );
  }

  Future<void> _chooseCustomPeriod(BuildContext context) async {
    final now = DateTime.now();
    final range = await showDateRangePicker(
      context: context,
      firstDate: DateTime(now.year - 3),
      lastDate: now,
      initialDateRange:
          widget.session.workspaceCustomerCustomStart != null &&
              widget.session.workspaceCustomerCustomEnd != null
          ? DateTimeRange(
              start: widget.session.workspaceCustomerCustomStart!,
              end: widget.session.workspaceCustomerCustomEnd!,
            )
          : null,
      builder: (context, child) => MediaQuery(
        data: MediaQuery.of(context).copyWith(
          textScaler: MediaQuery.textScalerOf(
            context,
          ).clamp(minScaleFactor: 1, maxScaleFactor: 1.2),
        ),
        child: child!,
      ),
    );
    if (range != null) {
      widget.session.setWorkspaceCustomerCustomPeriod(range.start, range.end);
    }
  }

  @override
  Widget build(BuildContext context) {
    final allCustomers = widget.session.workspaceCustomerBook
        .where(
          (customer) =>
              widget.customerId == null || customer.id == widget.customerId,
        )
        .toList(growable: false);
    final customers = widget.customerId == null
        ? widget.reviewScope==null?widget.session.visibleWorkspaceCustomers:widget.session.workspaceCustomerSearchResults(search:_search.text,filter:_preparedFilter)
        : allCustomers;
    final storeId = widget.session.activeWorkspace?.id ?? '';
    final repeat = allCustomers
        .where((customer) => customer.repeatCustomer)
        .length;
    final due = allCustomers.fold<int>(
      0,
      (total, customer) =>
          total + (customer.hasDues ? customer.amountDueMinor : 0),
    );
    final duesKnown = allCustomers.every(
      (customer) => customer.balanceAvailable,
    );
    if(widget.repeatOnly)return ListView(padding:const EdgeInsets.all(16),children:[
      for(final customer in customers)_CustomerBookRow(customer:customer,
        onOpen:()=>_showCustomer(context,storeId,customer),onCall:null,onChat:(){},showContactActions:false)]);
    return Container(
      key: const Key('work-customers-destination'),
      decoration: const BoxDecoration(
        gradient: LinearGradient(
          colors: [Color(0xFFF9FAFF), Color(0xFFEEF2FF)],
        ),
      ),
      child: ListView(
        keyboardDismissBehavior: ScrollViewKeyboardDismissBehavior.onDrag,
        padding: const EdgeInsets.fromLTRB(14, 8, 14, 28),
        children: [
          _StoreScaledPair(
            forceStack:
                due >= 1000000000 || MediaQuery.sizeOf(context).width < 380,
            first: Text(
              widget.customerId == null ? 'Customers' : 'Customer record',
              style: const TextStyle(
                color: MoolColors.ink,
                fontSize: 21,
                fontWeight: FontWeight.w900,
              ),
            ),
            second: Row(
              mainAxisSize: MainAxisSize.min,
              children: [
                _CustomerHeaderFact(
                  label: 'Total',
                  value: '${allCustomers.length}',
                ),
                _CustomerHeaderFact(label: 'Repeat', value: '$repeat'),
                _CustomerHeaderFact(
                  label: 'Due',
                  value: duesKnown ? _purchaseAmount(due) : 'Unavailable',
                  attention: due > 0,
                ),
              ],
            ),
          ),
          const SizedBox(height: 8),
          if (widget.customerId == null)
            StoreRecentSearches(
              controller: _search,
              history: widget.session.workspaceRecentSearches('customers'),
              onChanged: _changeSearch,
              child: TextField(
                key: const Key('work-customer-search'),
                controller: _search,
                onChanged: _changeSearch,
                textInputAction: TextInputAction.search,
                decoration: const InputDecoration(
                  hintText: 'Search name or mobile',
                  filled: false,
                  border: InputBorder.none,
                  enabledBorder: InputBorder.none,
                  focusedBorder: InputBorder.none,
                  disabledBorder: InputBorder.none,
                  errorBorder: InputBorder.none,
                  focusedErrorBorder: InputBorder.none,
                  prefixIcon: Icon(Icons.search_rounded),
                  isDense: true,
                ),
              ),
            ),
          const SizedBox(height: 6),
          if (widget.customerId == null)
            SizedBox(
              height: 28 + MediaQuery.textScalerOf(context).scale(20),
              child: ListView.separated(
                scrollDirection: Axis.horizontal,
                itemCount: 5,
                separatorBuilder: (_, _) => const SizedBox(width: 6),
                itemBuilder: (context, index) {
                  final filter = const [
                    'Recent',
                    'Repeat',
                    'Payment due',
                    'Following Store',
                    'Messages allowed',
                  ][index];
                  return ChoiceChip(
                    key: Key(
                      'work-customer-filter-${filter.toLowerCase().replaceAll(' ', '-')}',
                    ),
                    label: Text(filter),
                    selected: (widget.reviewScope==null?widget.session.workspaceCustomerFilter:_preparedFilter) == filter,
                    onSelected: (_) =>
                        _changeFilter(filter),
                  );
                },
              ),
            ),
          const SizedBox(height: 7),
          if (customers.isEmpty)
            const _StoreEmptyPanel(
              icon: Icons.people_outline_rounded,
              title: 'No customers found',
              detail:
                  'Completed counter, phone, Chat and app orders will build your customer book.',
            )
          else
            for (final customer in customers) ...[
              _CustomerBookRow(
                customer: customer,
                onOpen: () => _showCustomer(context, storeId, customer),
                onCall: customer.mobile.isEmpty
                    ? null
                    : () => _call(storeId, customer),
                onChat: () => _chat(context, storeId, customer),
              ),
              const SizedBox(height: 6),
            ],
          const SizedBox(height: 6),
          Material(
            color: Colors.white,
            borderRadius: BorderRadius.circular(15),
            child: Padding(
              padding: const EdgeInsets.symmetric(horizontal: 10),
              child: _StoreScaledPair(
                forceStack: MediaQuery.sizeOf(context).width < 380,
                expandSecond: true,
                first: const Row(
                  children: [
                    Icon(Icons.date_range_outlined, size: 18),
                    SizedBox(width: 7),
                    Expanded(
                      child: Text(
                        'Customer statement',
                        style: TextStyle(
                          fontSize: 12,
                          fontWeight: FontWeight.w900,
                        ),
                      ),
                    ),
                  ],
                ),
                second: Row(
                  children: [
                    Expanded(
                      child: DropdownButton<String>(
                        key: const Key('work-customer-period'),
                        isExpanded: true,
                        itemHeight: null,
                        value: widget.session.workspaceCustomerPeriod,
                        underline: const SizedBox.shrink(),
                        items: const [
                          DropdownMenuItem(value: 'Week', child: Text('Week')),
                          DropdownMenuItem(
                            value: 'Month',
                            child: Text('Month'),
                          ),
                          DropdownMenuItem(
                            value: 'Quarter',
                            child: Text('Quarter'),
                          ),
                          DropdownMenuItem(
                            value: 'Financial year',
                            child: Text('Financial year'),
                          ),
                          DropdownMenuItem(
                            value: 'Custom',
                            child: Text('Custom dates'),
                          ),
                        ],
                        onChanged: (value) {
                          if (value == 'Custom') {
                            _chooseCustomPeriod(context);
                          } else if (value != null) {
                            widget.session.setWorkspaceCustomerPeriod(value);
                          }
                        },
                      ),
                    ),
                    IconButton(
                      key: const Key('work-customer-custom-period'),
                      tooltip: 'Choose custom dates',
                      onPressed: () => _chooseCustomPeriod(context),
                      icon: const Icon(Icons.tune_rounded),
                    ),
                  ],
                ),
              ),
            ),
          ),
        ],
      ),
    );
  }
}

class _CustomerBookRow extends StatelessWidget {
  const _CustomerBookRow({
    required this.customer,
    required this.onOpen,
    required this.onCall,
    required this.onChat,this.showContactActions=true,
  });

  final WorkspaceCustomerRecord customer;
  final VoidCallback onOpen;
  final VoidCallback? onCall;
  final VoidCallback onChat;final bool showContactActions;

  @override
  Widget build(BuildContext context) {
    final lastContact = customer.lastContactAt;
    final expandedAmounts =
        customer.totalSpend >= 10000000 ||
        customer.amountDueMinor.abs() >= 1000000000 ||
        MediaQuery.textScalerOf(context).scale(11) > 16;
    return Material(
      key: Key('work-customer-${customer.id}'),
      color: Colors.white,
      borderRadius: BorderRadius.circular(16),
      child: InkWell(
        borderRadius: BorderRadius.circular(16),
        onTap: onOpen,
        child: Padding(
          padding: const EdgeInsets.fromLTRB(9, 7, 4, 7),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              Row(
                children: [
                  CircleAvatar(
                    radius: 19,
                    backgroundColor: const Color(0xFFE5EAFF),
                    foregroundColor: MoolColors.navy,
                    child: Text(
                      customer.name.substring(0, 1).toUpperCase(),
                      style: const TextStyle(fontWeight: FontWeight.w900),
                    ),
                  ),
                  const SizedBox(width: 9),
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(
                          customer.name,
                          maxLines: expandedAmounts ? null : 1,
                          overflow: expandedAmounts
                              ? TextOverflow.clip
                              : TextOverflow.ellipsis,
                          style: const TextStyle(
                            color: MoolColors.ink,
                            fontSize: 11.5,
                            fontWeight: FontWeight.w900,
                          ),
                        ),
                        if (!expandedAmounts)
                          Text(
                            '${customer.mobile} · ${customer.orderCount} orders · ₹${_formatStoreMinorAmount(customer.totalSpendMinor)}',
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: const TextStyle(
                              color: MoolColors.muted,
                              fontSize: 9,
                            ),
                          ),
                        if (!expandedAmounts)
                          Text(
                            !customer.balanceAvailable
                                ? 'Balance unavailable'
                                : customer.hasDues
                                ? '${_storeSummaryAmount(_customerBalanceText(customer))} payment due'
                                : customer.amountDueMinor < 0
                                ? '${_purchaseAmount(customer.amountDueMinor.abs())} customer credit'
                                : lastContact == null
                                ? 'Last purchase ${customer.lastPurchaseAt.day}/${customer.lastPurchaseAt.month}'
                                : 'Contacted ${lastContact.day}/${lastContact.month}',
                            style: TextStyle(
                              color: customer.hasDues
                                  ? const Color(0xFFB42318)
                                  : const Color(0xFF08765D),
                              fontSize: 8.5,
                              fontWeight: FontWeight.w800,
                            ),
                          ),
                      ],
                    ),
                  ),
                  if(showContactActions)IconButton(
                    key: Key('work-customer-call-${customer.id}'),
                    tooltip: 'Call ${customer.name}',
                    visualDensity: VisualDensity.compact,
                    onPressed: onCall,
                    icon: const Icon(Icons.call_outlined, size: 19),
                  ),
                  if(showContactActions)IconButton(
                    key: Key('work-customer-chat-${customer.id}'),
                    tooltip: 'Chat with ${customer.name}',
                    visualDensity: VisualDensity.compact,
                    onPressed: onChat,
                    icon: const Icon(
                      Icons.chat_bubble_outline_rounded,
                      size: 19,
                    ),
                  ),
                ],
              ),
              if (expandedAmounts) ...[
                const SizedBox(height: 4),
                Text(
                  '${customer.mobile} · ${customer.orderCount} ${customer.orderCount == 1 ? 'order' : 'orders'}',
                  style: const TextStyle(color: MoolColors.muted, fontSize: 11),
                ),
                const SizedBox(height: 4),
                _StoreScaledPair(
                  first: const Text(
                    'Purchased',
                    style: TextStyle(fontSize: 12),
                  ),
                  second: _StoreMoneyText(
                    '₹${_formatStoreMinorAmount(customer.totalSpendMinor)}',
                    summary: true,
                    textAlign: TextAlign.end,
                    style: const TextStyle(
                      color: MoolColors.navy,
                      fontSize: 14,
                      fontWeight: FontWeight.w800,
                    ),
                  ),
                ),
                if (customer.hasDues ||
                    !customer.balanceAvailable ||
                    customer.amountDueMinor < 0) ...[
                  const SizedBox(height: 4),
                  _StoreScaledPair(
                    first: Text(
                      customer.amountDueMinor < 0 && customer.balanceAvailable
                          ? 'Customer credit'
                          : 'Payment due',
                      style: const TextStyle(fontSize: 12),
                    ),
                    second: _StoreMoneyText(
                      customer.amountDueMinor < 0 && customer.balanceAvailable
                          ? _purchaseAmount(customer.amountDueMinor.abs())
                          : _customerBalanceText(customer),
                      summary: true,
                      textAlign: TextAlign.end,
                      style: const TextStyle(
                        color: Color(0xFFB42318),
                        fontSize: 14,
                        fontWeight: FontWeight.w800,
                      ),
                    ),
                  ),
                ] else ...[
                  const SizedBox(height: 4),
                  Text(
                    lastContact == null
                        ? 'Last purchase ${customer.lastPurchaseAt.day}/${customer.lastPurchaseAt.month}'
                        : 'Contacted ${lastContact.day}/${lastContact.month}',
                    style: const TextStyle(
                      color: Color(0xFF08765D),
                      fontSize: 11,
                      fontWeight: FontWeight.w800,
                    ),
                  ),
                ],
              ],
            ],
          ),
        ),
      ),
    );
  }
}

