/// Existing financial destinations share one scoped projection, with no local
/// money-moving capability. Summary totals are not inferred from partial rows.
class _CustomerLedgerStatement extends StatelessWidget {
  const _CustomerLedgerStatement({required this.ledger});
  final WorkspaceCustomerLedger ledger;

  @override
  Widget build(BuildContext context) {
    var running = ledger.openingBalanceMinor;
    final balances = <int?>[
      for (final entry in ledger.entries)
        running = running == null ? null : running + entry.balanceDeltaMinor,
    ];
    final closing = ledger.closingBalanceMinor;
    return ExpansionTile(
      key: PageStorageKey(
        'customer-ledger-${ledger.accountScope}-${ledger.workspaceId}-${ledger.customerId}',
      ),
      tilePadding: EdgeInsets.zero,
      title: Text(ledger.customerName),
      subtitle: Text(
        closing == null
            ? 'Customer statement · Balance unavailable'
            : 'Customer statement · ${closing < 0 ? 'Credit' : 'Due'} ${_purchaseAmount(closing.abs())}',
      ),
      children: [
        const Align(
          alignment: Alignment.centerLeft,
          child: Text('Available transaction history'),
        ),
        _MoneyDestinationLine(
          label: 'Opening balance',
          value: ledger.openingBalanceMinor == null
              ? 'Unavailable'
              : _purchaseAmount(ledger.openingBalanceMinor!),
        ),
        if (!ledger.historyComplete)
          const Text(
            'History is incomplete. A closing balance cannot be confirmed.',
          ),
        for (var i = 0; i < ledger.entries.length; i++)
          Padding(
            key: ValueKey('customer-ledger-entry-${ledger.entries[i].id}'),
            padding: const EdgeInsets.symmetric(vertical: 8),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                _MoneyDestinationLine(
                  label: switch (ledger.entries[i].kind) {
                    WorkspaceLedgerEntryKind.invoice => 'Invoice',
                    WorkspaceLedgerEntryKind.collection => 'Payment received',
                    WorkspaceLedgerEntryKind.creditNote => 'Return credit',
                    WorkspaceLedgerEntryKind.refund => 'Refund',
                    WorkspaceLedgerEntryKind.creditUsed => 'Customer credit used',
                    WorkspaceLedgerEntryKind.creditReceived => 'Customer credit applied',
                  },
                  value: _purchaseAmount(ledger.entries[i].amountMinor),
                ),
                Text(
                  '${ledger.entries[i].invoiceId} · ${ledger.entries[i].orderId}',
                ),
                if (ledger.entries[i].channel !=
                    WorkspacePaymentChannel.unknown)
                  Text(ledger.entries[i].channel.label),
                if (ledger.entries[i].paymentReference?.isNotEmpty == true)
                  Text('Reference ${ledger.entries[i].paymentReference}'),
                Text(
                  MaterialLocalizations.of(
                    context,
                  ).formatShortDate(ledger.entries[i].occurredAt.toLocal()),
                ),
                if (ledger.entries[i].state !=
                    WorkspaceLedgerPostingState.posted)
                  Text(
                    ledger.entries[i].state ==
                            WorkspaceLedgerPostingState.pending
                        ? 'Pending · Balance unchanged'
                        : 'Failed · Balance unchanged',
                  ),
                if (ledger.historyComplete && balances[i] != null)
                  _MoneyDestinationLine(
                    label: balances[i]! < 0 ? 'Customer credit' : 'Balance due',
                    value: _purchaseAmount(balances[i]!.abs()),
                  ),
              ],
            ),
          ),
      ],
    );
  }
}

// Unknown/pending credit history must not be treated as unused return capacity.
int? _remainingReturnUnits(WorkspaceOrderRecord order,
    WorkspacePaymentRecord payment, WorkspaceCustomerLedger? ledger) {
  if (!order.isCompleted || !order.hasCompleteItemSnapshot ||
      payment.invoiceId == null || ledger == null || !ledger.historyComplete ||
      ledger.customerId != payment.customerId) { return null; }
  final credits = ledger.entries.where((entry) =>
    entry.invoiceId == payment.invoiceId && entry.kind == WorkspaceLedgerEntryKind.creditNote);
  if (credits.any((entry) => entry.state == WorkspaceLedgerPostingState.pending ||
      (entry.state == WorkspaceLedgerPostingState.posted && entry.customerReturn == null))) { return null; }
  final returned = credits.where((entry) => entry.state == WorkspaceLedgerPostingState.posted)
      .expand((entry) => entry.customerReturn!.lines);
  var remaining = 0;
  for (final item in order.itemSnapshots) {
    final quantity = item.quantity - returned.where((line) => line.productId == item.productId)
        .fold<int>(0, (sum, line) => sum + line.quantity);
    if (quantity < 0) return null;
    remaining += quantity;
  }
  return remaining;
}

class _StoreFinanceSurface extends StatelessWidget {
  const _StoreFinanceSurface({
    required this.session,
    this.section = 'settlement',
    this.focus,
    this.onOpenInvoice,
    this.returnsOnly = false,this.reviewScope,this.preparedPeriodStart,
  });
  final WorkSession session;
  final String section;
  final _WorkspaceFinanceFocus? focus;
  final ValueChanged<WorkspaceCustomerInvoice>? onOpenInvoice;
  final bool returnsOnly;
  final StoreCustomerActionReviewScope? reviewScope;
  final DateTime? preparedPeriodStart;
  bool _preparedCurrent(BuildContext context)=>reviewScope==null||context.mounted&&reviewScope!.current()&&ModalRoute.of(context)?.isCurrent==true;

  @override
  Widget build(BuildContext context) {
    final finance = session.workspaceFinance;
    final target = focus;
    final exactPayment = finance?.payments
        .where(
          (p) =>
              p.orderId == target?.orderId &&
              p.customerId == target?.customerId,
        )
        .firstOrNull;
    final exactPayout = finance?.payouts
        .where(
          (p) =>
              p.id == target?.payoutId && p.operationId == target?.operationId,
        )
        .firstOrNull;
    if (target != null &&
        (finance == null ||
            finance.accountScope != target.accountScope ||
            finance.workspaceId != target.workspaceId ||
            (exactPayment == null && exactPayout == null))) {
      return ListView(
        key: const Key('work-finance-record-unavailable'),
        padding: const EdgeInsets.all(16),
        children: const [
          Text('This payment record is unavailable.'),
          Text('Return to Alerts for the latest update.'),
        ],
      );
    }
    if (finance != null && section == 'expenses') {
      return _StoreExpensesSurface(
        key: ValueKey((finance.accountScope, finance.workspaceId)),
        session: session,
      );
    }
    if (finance == null) {
      return ListView(
        key: const Key('work-finance-unavailable'),
        padding: const EdgeInsets.all(16),
        children: [
          _DeskEmpty(
            icon: Icons.account_balance_outlined,
            title: section == 'expenses'
                ? 'Expense updates unavailable'
                : 'Payment updates unavailable',
            detail: section == 'expenses'
                ? 'Linked business expenses will appear here.'
                : 'Your confirmed payments and settlement balance will appear here when available.',
          ),
        ],
      );
    }
    final start = target == null && section == 'payments'
        ? reviewScope==null?session.workspaceMoneyPeriodStart:preparedPeriodStart
        : null;
    final settlementCheck = finance.settlementPaidReconciliation;
    final payments =
        target != null
              ? [?exactPayment]
              : finance.payments
                    .where(
                      (p) =>
                          (section != 'dues' || p.dueMinor > 0) &&
                          (start == null || !p.updatedAt.isBefore(start)),
                    )
                    .toList()
          ..sort((a, b) => a.orderId.compareTo(b.orderId));
    final payouts = target != null
        ? [?exactPayout]
        : section == 'settlement'
        ? finance.payouts
        : const <WorkspacePayoutRecord>[];
    final orders = {for (final o in session.visibleWorkspaceOrders) o.id: o};
    final ledgers =
        target == null && (section == 'dues' || section == 'payments')
        ? finance.customerLedgers
        : const <WorkspaceCustomerLedger>[];
    return ListView.builder(
      key: ValueKey('work-finance-$section'),
      padding: EdgeInsets.symmetric(
        horizontal:
            target != null && MediaQuery.textScalerOf(context).scale(14) > 21
            ? 8
            : 16,
        vertical: 16,
      ),
      itemCount: 1 + ledgers.length + payouts.length + payments.length,
      itemBuilder: (context, index) {
        if (index == 0) {
          return Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              // The native dues route already names this screen in its AppBar.
              // Keep the source update and balance visible without a second title.
              if (target != null || section != 'dues') Text(
                target != null
                    ? (target.payoutId != null
                          ? 'Settlement details'
                          : returnsOnly ? 'Returns & refunds' : 'Payment details')
                    : section == 'settlement'
                    ? 'Settlement balance'
                    : section == 'dues'
                    ? 'Collect dues'
                    : 'Customer payments',
                style: TextStyle(
                  fontSize: target != null ? 16 : 20,
                  fontWeight: FontWeight.w800,
                  color: MoolColors.navy,
                ),
              ),
              Text(
                'Updated ${MaterialLocalizations.of(context).formatShortDate(finance.asOf.toLocal())} · '
                '${MaterialLocalizations.of(context).formatTimeOfDay(TimeOfDay.fromDateTime(finance.asOf.toLocal()))}',
                style: const TextStyle(fontSize: 11, color: MoolColors.muted),
              ),
              if (session.workspaceFinanceStale)
                const Text(
                  'Showing the last confirmed update. Current payment status is unavailable.',
                  key: Key('work-finance-stale'),
                ),
              if (session.pendingCustomerReturn != null) ...[
                Text(
                  session.customerReturnSaved
                      ? 'A return is awaiting confirmation. Its details are saved; do not enter it again.'
                      : 'Return details are not saved yet. Keep this bill open and retry.',
                ),
                TextButton(
                  onPressed: session.customerCollectionBusy
                      ? null
                      : reviewScope==null?()=>session.reconcileCustomerReturn():()async{if(!_preparedCurrent(context))return;await reviewScope!.runNative(()=>session.reconcileCustomerReturn(reviewOwnerCurrent:reviewScope!.ownerCurrent,reviewInputCurrent:()=>_preparedCurrent(context),onReviewNativeChange:reviewScope!.acceptNativeChange));},
                  child: Text(
                    session.customerReturnSaved
                        ? 'Check return status'
                        : 'Retry saving return',
                  ),
                ),
                const SizedBox(height: 8),
              ],
              if (session.pendingCustomerRefund != null) ...[
                Text(
                  session.customerRefundSaved
                      ? 'A refund is awaiting confirmation. Its details are saved; do not record it again.'
                      : 'Refund details are not saved yet. Keep this bill open and retry.',
                ),
                TextButton(
                  onPressed: session.customerCollectionBusy
                      ? null
                      : reviewScope==null?session.reconcileCustomerRefund:()async{if(!_preparedCurrent(context))return;await reviewScope!.runNative(()=>session.reconcileCustomerRefund(reviewOwnerCurrent:reviewScope!.ownerCurrent,reviewInputCurrent:()=>_preparedCurrent(context),onReviewNativeChange:reviewScope!.acceptNativeChange));},
                  child: Text(
                    session.customerRefundSaved
                        ? 'Check refund status'
                        : 'Retry saving refund',
                  ),
                ),
              ],
              if (session.pendingCustomerCollection != null) ...[
                const Text(
                  'A collection is awaiting confirmation. Do not record it again.',
                ),
                TextButton(
                  onPressed: session.customerCollectionBusy
                      ? null
                      : reviewScope==null?session.reconcileCustomerCollection:()async{if(!_preparedCurrent(context))return;await reviewScope!.runNative(()=>session.reconcileCustomerCollection(reviewOwnerCurrent:reviewScope!.ownerCurrent,reviewInputCurrent:()=>_preparedCurrent(context),onReviewNativeChange:reviewScope!.acceptNativeChange));},
                  child: const Text('Check collection status'),
                ),
              ],
              if (session.customerLedgerRecoveryError != null) ...[
                Text(session.customerLedgerRecoveryError!),
                TextButton(
                  onPressed: session.customerCollectionBusy
                      ? null
                      : session.recoverCustomerLedger,
                  child: const Text('Retry ledger recovery'),
                ),
              ],
              const SizedBox(height: 12),
              if (target == null && section == 'settlement') ...[
                for (final fact in <(String, int)>[
                  ('Available for settlement', finance.availableMinor),
                  ('On hold', finance.heldMinor),
                  ('Requested', finance.requestedMinor),
                  ('Paid to bank', finance.paidOutMinor),
                ])
                  _MoneyDestinationLine(
                    label: fact.$1,
                    value: _purchaseAmount(fact.$2),
                  ),
                const SizedBox(height: 8),
                const FilledButton(
                  onPressed: null,
                  child: Text('Request settlement'),
                ),
                const Text(
                  'Settlement requests are not connected yet. No money will move from this screen.',
                  style: TextStyle(fontSize: 12, color: MoolColors.muted),
                ),
                const SizedBox(height: 12),
                Text(
                  session.workspaceFinanceStale || settlementCheck == null
                      ? 'Settlement reconciliation unavailable.'
                      : settlementCheck.differenceMinor == null
                      ? 'Full payout history is needed to reconcile this total.'
                      : settlementCheck.differenceMinor == 0
                      ? 'Paid-out total matches the supplied payout records.'
                      : 'Paid-out total and payout records differ. Check the settlement update.',
                  key: const Key('work-settlement-reconciliation'),
                ),
                if (settlementCheck != null)
                  _MoneyDestinationLine(
                    label: 'Recorded paid payouts',
                    value: _purchaseAmount(settlementCheck.recordedMinor),
                  ),
                const Text(
                  'Requests and processing payouts are excluded. These records do not show your bank account balance.',
                  style: TextStyle(fontSize: 12, color: MoolColors.muted),
                ),
                const Divider(height: 24),
                const Text(
                  'Reported adjustments',
                  style: TextStyle(fontWeight: FontWeight.w700),
                ),
                for (final fact in <(String, int)>[
                  ('MoolSocial fees', finance.feesMinor),
                  ('Delivery adjustments', finance.deliveryAdjustmentsMinor),
                  ('Refunds', finance.refundsMinor),
                  ('Tax withheld', finance.taxWithheldMinor),
                ])
                  _MoneyDestinationLine(
                    label: fact.$1,
                    value: _purchaseAmount(fact.$2),
                  ),
              ],
              if (target == null && section == 'dues')
                _MoneyDestinationLine(
                  label: 'Unpaid balance',
                  value: _purchaseAmount(finance.duesMinor),
                ),
              if (target == null && !finance.historyComplete)
                const Padding(
                  padding: EdgeInsets.symmetric(vertical: 10),
                  child: Text(
                    'Showing available records. Full history is not available yet.',
                  ),
                ),
              if (payments.isEmpty &&
                  payouts.isEmpty &&
                  !((section == 'dues' || section == 'payments') &&
                      finance.customerLedgers.isNotEmpty))
                Text(
                  finance.historyComplete
                      ? 'No matching records in this view.'
                      : 'No matching updates available.',
                ),
            ],
          );
        }
        if (index <= ledgers.length) {
          return _CustomerLedgerStatement(ledger: ledgers[index - 1]);
        }
        final recordIndex = index - ledgers.length;
        if (recordIndex <= payouts.length) {
          final payout = payouts[recordIndex - 1];
          return Padding(
            key: ValueKey('work-finance-payout-${payout.id}'),
            padding: const EdgeInsets.symmetric(vertical: 12),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                const Divider(height: 16),
                _MoneyDestinationLine(
                  label: '${payout.id} · ${payout.state.label}',
                  value: _purchaseAmount(payout.amountMinor),
                ),
                if (payout.bankLabel?.isNotEmpty == true)
                  Text(payout.bankLabel!),
                if (payout.expectedBy?.isNotEmpty == true &&
                    {
                      WorkspacePayoutState.requested,
                      WorkspacePayoutState.processing,
                    }.contains(payout.state))
                  Text('Expected by ${payout.expectedBy}'),
                if (payout.message?.isNotEmpty == true) Text(payout.message!),
              ],
            ),
          );
        }
        final payment = payments[recordIndex - 1 - payouts.length];
        final order = orders[payment.orderId];
        final receiptLedger = finance.customerLedgers.where((ledger) =>
            ledger.accountScope == finance.accountScope &&
            ledger.workspaceId == finance.workspaceId &&
            ledger.customerId == payment.customerId).firstOrNull;
        final receiptChannels = receiptLedger?.recordedReceiptChannels(
            payment.invoiceId ?? '', payment.orderId) ?? <WorkspacePaymentChannel>{};
        final remainingReturnUnits = order == null ? null
            : _remainingReturnUnits(order, payment, receiptLedger);
        final mixedMethods = receiptChannels.length > 1
            ? 'Mixed payment · ${receiptChannels.map((channel) => switch (channel) {
                WorkspacePaymentChannel.cash => 'Cash',
                WorkspacePaymentChannel.directUpi => 'UPI',
                WorkspacePaymentChannel.bankTransfer => 'Bank transfer',
                _ => channel.label,
              }).join(' + ')}'
            : null;
        return Padding(
          key: ValueKey('work-finance-payment-${payment.orderId}'),
          padding: const EdgeInsets.symmetric(vertical: 12),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              const Divider(height: 16),
              _MoneyDestinationLine(
                label: '${payment.customerName} · ${payment.orderId}',
                value: _purchaseAmount(
                  section == 'dues' ? payment.dueMinor : payment.amountMinor,
                ),
              ),
              Text(
                payment.label,
                style: const TextStyle(
                  fontWeight: FontWeight.w700,
                  color: MoolColors.navy,
                ),
              ),
              if (mixedMethods != null || payment.state != WorkspacePaymentState.paid)
                Text(mixedMethods ?? payment.channel.label),
              if (order != null)
                Text(
                  'Order · ${order.stage == 'Confirmed' ? 'Awaiting acceptance' : session.workspaceOrderStageLabel(order)}',
                ),
              if (section != 'dues' && payment.dueMinor > 0)
                _MoneyDestinationLine(
                  label: 'Still due',
                  value: _purchaseAmount(payment.dueMinor),
                ),
              if (payment.paidMinor > 0 &&
                  payment.paidMinor != payment.amountMinor)
                _MoneyDestinationLine(
                  label: 'Paid so far',
                  value: _purchaseAmount(payment.paidMinor),
                ),
              if (payment.refundedMinor > 0)
                _MoneyDestinationLine(
                  label: 'Refunded',
                  value: _purchaseAmount(payment.refundedMinor),
                ),
              if (payment.invoiceId?.isNotEmpty == true)
                Text('Invoice ${payment.invoiceId}'),
              if (onOpenInvoice != null &&
                  session.workspaceInvoices.any(
                    (invoice) =>
                        invoice.id == payment.invoiceId &&
                        invoice.orderId == payment.orderId,
                  ))
                Align(
                  alignment: Alignment.centerLeft,
                  child: TextButton(
                    key: ValueKey('work-sales-invoice-${payment.invoiceId}'),
                    onPressed: () => onOpenInvoice!(
                      session.workspaceInvoices.firstWhere(
                        (invoice) =>
                            invoice.id == payment.invoiceId &&
                            invoice.orderId == payment.orderId,
                      ),
                    ),
                    child: const Text('View invoice'),
                  ),
                ),
              if (reviewScope==null && !returnsOnly && payment.dueMinor > 0 &&
                  payment.invoiceId != null &&
                  (section == 'dues' || section == 'payments'))
                Align(
                  alignment: Alignment.centerLeft,
                  child: TextButton(
                    key: ValueKey('record-collection-${payment.orderId}'),
                    onPressed:
                        session.customerCollectionAvailable &&
                            !session.customerCollectionBusy &&
                            session.pendingCustomerCollection == null &&
                            finance.customerLedgers.any(
                              (l) =>
                                  l.customerId == payment.customerId &&
                                  l.historyComplete,
                            )
                        ? () => showModalBottomSheet<void>(
                            context: context,
                            isScrollControlled: true,
                            useSafeArea: true,
                            isDismissible: false,
                            enableDrag: false,
                            builder: (_) => _CustomerCollectionSheet(
                              session: session,
                              payment: payment,
                              accountScope: finance.accountScope,
                              storeId: finance.workspaceId,
                            ),
                          )
                        : null,
                    child: const Text('Record collection'),
                  ),
                ),
              if (reviewScope==null && payment.invoiceId != null &&
                  finance.customerLedgers.any(
                    (ledger) =>
                        ledger.customerId == payment.customerId &&
                        (ledger
                                    .invoiceBalance(payment.invoiceId!)
                                    ?.refundableMinor ??
                                0) >
                            0,
                  ))
                Align(
                  alignment: Alignment.centerLeft,
                  child: TextButton(
                    key: ValueKey('record-refund-${payment.orderId}'),
                    onPressed:
                        session.customerRefundAvailable &&
                            payment.channel != WorkspacePaymentChannel.platform
                        ? () => showModalBottomSheet<void>(
                            context: context,
                            isScrollControlled: true,
                            useSafeArea: true,
                            isDismissible: false,
                            enableDrag: false,
                            builder: (_) => _CustomerCollectionSheet(
                              session: session,
                              payment: payment,
                              accountScope: finance.accountScope,
                              storeId: finance.workspaceId,
                              refund: true,
                            ),
                          )
                        : null,
                    child: const Text('Record refund'),
                  ),
                ),
              if (reviewScope==null && remainingReturnUnits != null && remainingReturnUnits > 0)
                Align(
                  alignment: Alignment.centerLeft,
                  child: TextButton(
                    key: ValueKey('record-return-${payment.orderId}'),
                    onPressed: session.customerReturnAvailable
                        ? () => showModalBottomSheet<void>(
                            context: context,
                            isScrollControlled: true,
                            useSafeArea: true,
                            isDismissible: false,
                            enableDrag: false,
                            builder: (_) => _CustomerReturnSheet(
                              session: session,
                              payment: payment,
                              order: order!,
                              account: finance.accountScope,
                              store: finance.workspaceId,
                            ),
                          )
                        : null,
                    child: const Text('Record return'),
                  ),
                ),
              if (returnsOnly && remainingReturnUnits == 0)
                const Text('All items on this invoice have already been returned.'),
              if (returnsOnly && remainingReturnUnits == null)
                const Text('Return quantities unavailable. Recover the original invoice records before recording a return.'),
              if (payment.transactionId?.isNotEmpty == true)
                Text('Transaction ${payment.transactionId}'),
              if (order != null)
                ExpansionTile(
                  key: PageStorageKey((
                    'work-finance-order-details',
                    finance.accountScope,
                    finance.workspaceId,
                    section,
                    payment.orderId,
                  )),
                  tilePadding: EdgeInsets.zero,
                  title: const Text(
                    'Order details',
                    style: TextStyle(fontSize: 13, fontWeight: FontWeight.w700),
                  ),
                  children: [
                    _ExactOrderInformation(
                      order: order,
                      showItems: true,
                      showPayment: false,
                    ),
                  ],
                ),
            ],
          ),
        );
      },
    );
  }
}

class _CustomerReturnSheet extends StatefulWidget {
  const _CustomerReturnSheet({
    required this.session,
    required this.payment,
    required this.order,
    required this.account,
    required this.store,
    this.onRecorded, this.reviewScope,this.preparedFields,this.capturedDraft,this.onPreparedDraft,
  });
  final StoreCustomerActionReviewScope? reviewScope;
  final Map<String,String>? preparedFields;
  final WorkspaceLedgerFormDraft? capturedDraft;
  final ValueChanged<Map<String,String>>? onPreparedDraft;
  final WorkSession session;
  final WorkspacePaymentRecord payment;
  final WorkspaceOrderRecord order;
  final String account, store;
  final VoidCallback? onRecorded;
  @override
  State<_CustomerReturnSheet> createState() => _CustomerReturnSheetState();
}

class _CustomerReturnSheetState extends State<_CustomerReturnSheet> with WidgetsBindingObserver {
  bool _preparedCompleted=false;
  bool _preparedCurrent()=>widget.reviewScope==null || mounted&&widget.reviewScope!.current()&&ModalRoute.of(context)?.isCurrent==true;
  Future<bool> _runPreparedNative(Future<bool> Function() run)=>widget.reviewScope?.runNative(run)??run();
  final quantities = <String, TextEditingController>{};
  final sellableQuantities = <String, TextEditingController>{};
  final selectedProducts = <String>{};
  final reason = TextEditingController();
  final _reasonFocus = FocusNode();
  final _reasonAnchor = GlobalKey();
  void _revealReason() {
    WidgetsBinding.instance.addPostFrameCallback((_) {
      final target = _reasonAnchor.currentContext;
      if (mounted && widget.reviewScope?.current()!=false && target != null) {
        Scrollable.ensureVisible(target, alignment: .2);
      }
    });
  }
  @override
  void didChangeMetrics() {
    if (_reasonFocus.hasFocus) _revealReason();
  }
  String? reasonCode;
  bool listenersAttached = false;
  late final _LedgerFormAutosave draft;
  bool saving = false;
  String? error;
  int? renderedCredit, renderedRevision;
  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    _reasonFocus.addListener(() {
      if (_reasonFocus.hasFocus) _revealReason();
    });
    for (final item in widget.order.itemSnapshots) {
      quantities[item.productId] = TextEditingController(text: '1');
      sellableQuantities[item.productId] = TextEditingController(text: '0');
    }
    final firstAvailable = widget.order.itemSnapshots
        .where((item) => remainingQuantity(item) > 0)
        .firstOrNull;
    if (firstAvailable != null) selectedProducts.add(firstAvailable.productId);
    draft = _LedgerFormAutosave(
      widget.session,
      widget.session.ledgerFormKey(widget.payment, 'return'),
      inputOwnerCurrent:widget.reviewScope?.current,preparedFields:widget.preparedFields,capturedDraft:widget.capturedDraft,onPreparedDraft:widget.onPreparedDraft,
    );
    draft.addListener(refreshDraft);
    unawaited(loadDraft());
  }

  void refreshDraft() {
    if (mounted) {
      setState(() {});
    }
  }

  Future<void> loadDraft() async {
    final fields = await draft.load();
    if (!mounted || widget.reviewScope?.current()==false || fields == null) {
      return;
    }
    final savedItems = fields['items'];
    if (savedItems != null) {
      final items = (jsonDecode(savedItems) as Map).cast<String, dynamic>();
      if (items.keys.any((id) => !quantities.containsKey(id))) {
        draft.ready = false;
        draft.error = 'Saved return items do not match this bill. Recover the original bill before continuing.';
        setState(() {});
        return;
      }
      selectedProducts
        ..clear()
        ..addAll(items.keys);
      for (final entry in items.entries) {
        quantities[entry.key]!.text = entry.value[0] as String;
        sellableQuantities[entry.key]!.text = entry.value[1] as String;
      }
    } else {
      // Retain a draft created by the previous single-product form.
      final id = fields['product'] ?? selectedProducts.first;
      if (!quantities.containsKey(id)) {
        draft.ready = false;
        draft.error = 'Saved return item does not match this bill. Recover the original bill before continuing.';
        setState(() {});
        return;
      }
      selectedProducts..clear()..add(id);
      quantities[id]!.text = fields['quantity'] ?? '1';
      sellableQuantities[id]!.text = fields['sellable'] ?? '0';
    }
    reason.text = fields['reason'] ?? '';
    final savedReasonCode = fields['reasonCode'];
    reasonCode = WorkspaceCustomerReturn.reasonLabels.containsKey(savedReasonCode)
        ? savedReasonCode : null;
    if (!listenersAttached) {
      for (final controller in [...quantities.values, ...sellableQuantities.values, reason]) {
        controller.addListener(saveDraft);
      }
      listenersAttached = true;
    }
    setState(() {});
  }

  Map<String,String> get _preparedFieldsNow=>{
      'items':jsonEncode({for(final id in selectedProducts)id:[quantities[id]!.text,sellableQuantities[id]!.text]}),
      'reason':reason.text,if(reasonCode!=null)'reasonCode':reasonCode!,
    };
  void saveDraft() {
    draft.save({
      'items': jsonEncode({
        for (final id in selectedProducts)
          id: [quantities[id]!.text, sellableQuantities[id]!.text],
      }),
      'reason': reason.text,
      'reasonCode': ?reasonCode,
    });
  }

  @override
  void dispose() {
    if(widget.preparedFields!=null)widget.onPreparedDraft?.call(_preparedFieldsNow);
    WidgetsBinding.instance.removeObserver(this);
    _reasonFocus.dispose();
    draft.removeListener(refreshDraft);
    draft.dispose();
    for (final controller in [...quantities.values, ...sellableQuantities.values]) {
      controller.dispose();
    }
    reason.dispose();
    super.dispose();
  }

  WorkspaceCustomerLedger? get ledger => widget
      .session
      .workspaceFinance
      ?.customerLedgers
      .where((item) => item.customerId == widget.payment.customerId)
      .firstOrNull;
  List<WorkspaceCustomerReturnLine> get lines => [
    for (final item in widget.order.itemSnapshots)
      if (selectedProducts.contains(item.productId))
        WorkspaceCustomerReturnLine(
          productId: item.productId,
          quantity: int.tryParse(quantities[item.productId]!.text) ?? 0,
          restockQuantity: int.tryParse(sellableQuantities[item.productId]!.text) ?? -1,
        ),
  ];
  int remainingQuantity(WorkspaceOrderItemSnapshot item) => item.quantity -
      (ledger?.entries.where((entry) =>
          entry.invoiceId == widget.payment.invoiceId &&
          entry.state == WorkspaceLedgerPostingState.posted)
        .expand((entry) => entry.customerReturn?.lines ?? const <WorkspaceCustomerReturnLine>[])
        .where((line) => line.productId == item.productId)
        .fold<int>(0, (sum, line) => sum + line.quantity) ?? 0);
  int? get credit {
    final history = ledger;
    if (history == null) return null;
    final credits = history.entries.where(
      (item) =>
          item.invoiceId == widget.payment.invoiceId &&
          item.kind == WorkspaceLedgerEntryKind.creditNote,
    );
    if (credits.any(
      (item) =>
          item.customerReturn == null ||
          item.state == WorkspaceLedgerPostingState.pending,
    )) {
      return null;
    }
    return WorkspaceCustomerReturn(
      accountScope: widget.account,
      workspaceId: widget.store,
      customerId: widget.payment.customerId,
      invoiceId: widget.payment.invoiceId!,
      orderId: widget.order.id,
      operationId: 'preview',
      expectedRevision: history.revision,
      reason: 'Return preview',
      lines: lines,
    ).creditMinorFor(
      widget.order,
      priorReturns: [
        for (final item in credits)
          if (item.state == WorkspaceLedgerPostingState.posted)
            item.customerReturn!,
      ],
    );
  }

  Future<void> submit() async {
    if (_preparedCompleted || !_preparedCurrent() || !await draft.flush() || !mounted || !_preparedCurrent()) {
      return;
    }
    final amount = renderedCredit;
    final revision = renderedRevision;
    if (amount == null ||
        amount <= 0 ||
        reason.text.trim().isEmpty ||
        widget.session.workspaceFinance?.accountScope != widget.account ||
        widget.session.workspaceFinance?.workspaceId != widget.store) {
      setState(
        () =>
            error = 'Check the quantities, reason and original Store invoice.',
      );
      return;
    }
    setState(() {
      saving = true;
      error = null;
    });
    final success = await _runPreparedNative(()=>widget.session.recordCustomerReturn(
      invoiceId: widget.payment.invoiceId!,
      lines: lines,
      reason: reason.text,
      reasonCode: reasonCode,
      expectedCreditMinor: amount,
      expectedLedgerRevision: revision, reviewOwnerCurrent:widget.reviewScope?.ownerCurrent,reviewInputCurrent:widget.reviewScope==null?null:_preparedCurrent,onReviewNativeChange:widget.reviewScope?.acceptNativeChange,
    ));
    if (!mounted) return;
    if (success) {
      if(widget.reviewScope!=null)setState((){_preparedCompleted=true;saving=false;});
      widget.onRecorded?.call();
      if(widget.reviewScope!=null && (!widget.reviewScope!.current() || ModalRoute.of(context)?.isCurrent!=true))return;
      _closeCapturedCustomerReview(context,widget.reviewScope);
      return;
    }
    setState(() {
      saving = false;
      error = widget.session.pendingCustomerReturn != null
          ? 'Return is not confirmed. Use Check return status or Retry saving in the invoice view.'
          : 'Invoice changed or return unavailable. Review the current bill before retrying.';
    });
  }

  @override
  Widget build(BuildContext context) {
    if(widget.reviewScope!=null&&_preparedCompleted)return _customerCompletedReview(context,widget.reviewScope!,"Return recorded");
    renderedCredit = credit;
    renderedRevision = ledger?.revision;
    return PopScope(
      canPop: widget.reviewScope?.current()==false || !saving && !draft.busy && (!draft.ready || draft.error == null),
      onPopInvokedWithResult: (didPop, result) async {
        if (!didPop && !saving && await draft.flush() && context.mounted) {
          _closeCapturedCustomerReview(context,widget.reviewScope);
        }
      },
      child: SafeArea(
        top: false,
        child: Padding(padding: EdgeInsets.only(bottom: MediaQuery.viewInsetsOf(context).bottom),
        child: Column(mainAxisSize: MainAxisSize.min, children: [
          Padding(padding: const EdgeInsets.fromLTRB(16, 8, 8, 4), child: Row(children: [
            Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              Text('Record return', style: Theme.of(context).textTheme.titleMedium),
              Text('Invoice ${widget.payment.invoiceId}', style: const TextStyle(fontSize: 12)),
            ])),
            TextButton(key: const Key('return-jump-reason'),
              onPressed: saving ? null : _revealReason, child: const Text('Reason')),
          ])),
        Flexible(child: SingleChildScrollView(
          padding: const EdgeInsets.fromLTRB(16, 4, 16, 16),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              if (widget.onRecorded != null)
                const Text('Exchange · Step 1: record returned items. Choose replacements after saving.',
                  style: TextStyle(fontSize: 12, color: MoolColors.ink)),
              const SizedBox(height: 12),
              if (widget.order.itemSnapshots.length > 1)
                Text('Select items to return · ${selectedProducts.length} selected'),
              for (final item in widget.order.itemSnapshots) ...[
                if (widget.order.itemSnapshots.length > 1)
                  CheckboxListTile(
                    key: Key('return-select-${item.productId}'),
                    contentPadding: EdgeInsets.zero,
                    controlAffinity: ListTileControlAffinity.leading,
                    value: selectedProducts.contains(item.productId),
                    title: Text('${item.name} · ${item.pack}'),
                    subtitle: Text('Billed: ${item.quantity} · Available to return: ${remainingQuantity(item)}'),
                    onChanged: saving || !draft.ready ? null : (value) {
                      setState(() {
                        if (value == true) {
                          selectedProducts.add(item.productId);
                        } else {
                          selectedProducts.remove(item.productId);
                        }
                      });
                      saveDraft();
                    },
                  )
                else ...[
                  Text('${item.name} · ${item.pack}', key: const Key('return-original-item')),
                  Text('Billed quantity: ${item.quantity} · Available to return: ${remainingQuantity(item)}'),
                  const SizedBox(height: 12),
                ],
                if (selectedProducts.contains(item.productId)) ...[
                  LayoutBuilder(builder: (context, constraints) {
                    final twoColumns = constraints.maxWidth >= 280 &&
                        MediaQuery.textScalerOf(context).scale(14) <= 18.2;
                    final fieldWidth = twoColumns
                        ? ((constraints.maxWidth - 12) / 2).clamp(0.0, 180.0)
                        : constraints.maxWidth.clamp(0.0, 240.0);
                    return Wrap(spacing: 12, runSpacing: 12, children: [
                  SizedBox(width: fieldWidth, child: TextField(
                    key: item == widget.order.itemSnapshots.first
                        ? const Key('return-quantity') : Key('return-quantity-${item.productId}'),
                    controller: quantities[item.productId],
                    enabled: !saving && draft.ready,
                    keyboardType: TextInputType.number,
                    decoration: const InputDecoration(labelText: 'Units returned',
                      isDense: true, contentPadding: EdgeInsets.symmetric(horizontal: 12, vertical: 14)),
                    onChanged: (_) => setState(() {}),
                  )),
                  SizedBox(width: fieldWidth, child: TextField(
                    key: item == widget.order.itemSnapshots.first
                        ? const Key('return-sellable') : Key('return-sellable-${item.productId}'),
                    controller: sellableQuantities[item.productId],
                    enabled: !saving && draft.ready,
                    keyboardType: TextInputType.number,
                    decoration: const InputDecoration(
                      labelText: 'Fit for resale',
                      isDense: true, contentPadding: EdgeInsets.symmetric(horizontal: 12, vertical: 14),
                    ),
                    onChanged: (_) => setState(() {}),
                  )),
                    ]);
                  }),
                  const SizedBox(height: 4),
                  const Text('Damaged units must not go back into sellable stock.',
                    style: TextStyle(fontSize: 12)),
                  const SizedBox(height: 12),
                ],
              ],
              const SizedBox(height: 12),
              SingleChildScrollView(
                key: const Key('return-reason-choices'),
                scrollDirection: Axis.horizontal,
                child: Row(children: [
                  for (final entry in WorkspaceCustomerReturn.reasonLabels.entries)
                    Padding(
                      padding: const EdgeInsets.only(right: 12),
                      child: Semantics(
                        checked: reasonCode == entry.key,
                        inMutuallyExclusiveGroup: true,
                        child: InkWell(
                          key: Key('return-reason-${entry.key}'),
                          onTap: saving || !draft.ready ? null : () {
                            if (reasonCode == entry.key) return;
                            setState(() {
                              reasonCode = entry.key;
                              reason.text = entry.key == 'other' ? '' : entry.value;
                            });
                            saveDraft();
                          },
                          child: ConstrainedBox(
                            constraints: const BoxConstraints(minHeight: 48),
                            child: Row(mainAxisSize: MainAxisSize.min, children: [
                              Icon(reasonCode == entry.key
                                ? Icons.radio_button_checked : Icons.radio_button_unchecked,
                                size: 18, color: MoolColors.navy),
                              const SizedBox(width: 5),
                              Text(entry.value, style: const TextStyle(fontSize: 13)),
                            ]),
                          ),
                        ),
                      ),
                    ),
                ]),
              ),
              Container(key: _reasonAnchor, child: TextField(
                key: const Key('return-reason'),
                controller: reason,
                focusNode: _reasonFocus,
                scrollPadding: const EdgeInsets.only(bottom: 100, top: 20),
                enabled: !saving && draft.ready,
                maxLength: 160,
                decoration: InputDecoration(
                  labelText: reasonCode == 'other' ? 'Describe the reason' : 'Reason for return',
                ),
                onChanged: (_) {
                  if (reasonCode == null) setState(() => reasonCode = 'other');
                  saveDraft();
                },
              )),
              Text(
                credit == null
                    ? 'Enter valid quantities within the original bill.'
                    : 'Return credit: ${_purchaseAmount(credit!)}',
              ),
              const Text(
                'Credit reduces this invoice’s dues first. Any amount owed back remains pending until a refund is confirmed.',
              ),
              if (draft.error != null) ...[
                Text(draft.error!),
                TextButton(
                  onPressed: draft.busy
                      ? null
                      : () {
                          if (draft.ready) {
                            saveDraft();
                          } else {
                            unawaited(loadDraft());
                          }
                        },
                  child: const Text('Retry saving input'),
                ),
              ],
              if (error != null)
                Padding(
                  padding: const EdgeInsets.only(top: 8),
                  child: Text(error!),
                ),
              const SizedBox(height: 12),
              FilledButton(
                onPressed:
                    !draft.ready ||
                        draft.busy ||
                        draft.error != null ||
                        saving ||
                        widget.session.pendingCustomerReturn != null
                    ? null
                    : submit,
                child: Text(saving ? 'Recording…' : 'Confirm return'),
              ),
            ],
          ),
        )),
        ])),
      ),
    );
  }
}

class _LedgerFormAutosave extends ChangeNotifier {
  _LedgerFormAutosave(this.session, this.key, {this.inputOwnerCurrent,this.preparedFields,this.capturedDraft,this.onPreparedDraft});
  final Map<String,String>? preparedFields;
  final WorkspaceLedgerFormDraft? capturedDraft;
  final ValueChanged<Map<String,String>>? onPreparedDraft;
  bool _preparedDraftRetired=false;
  final bool Function()? inputOwnerCurrent;
  final WorkSession session;
  final WorkspaceLedgerFormKey? key;
  int? revision;
  bool ready = false, busy = false, closed = false;
  String? error;
  WorkspaceLedgerFormDraft? pending;
  Future<void> writes = Future<void>.value();
  void changed() {
    if (!closed) {
      notifyListeners();
    }
  }

  Future<Map<String, String>?> load() async {
    if(preparedFields!=null){
      if(inputOwnerCurrent?.call()==false)return null;
      revision=capturedDraft?.revision;ready=true;error=null;changed();return Map.of(preparedFields!);
    }
    try {
      if (key == null) {
        throw StateError('Invoice unavailable');
      }
      final saved = await session.readLedgerForm(key!);
      revision = saved?.revision;
      ready = true;
      error = null;
      changed();
      return saved?.fields ?? const {};
    } catch (_) {
      error = 'Saved input could not be opened. Retry before editing.';
      changed();
      return null;
    }
  }

  void save(Map<String, String> fields) {
    if(preparedFields!=null){if(inputOwnerCurrent?.call()!=false)onPreparedDraft?.call(Map.of(fields));return;}
    // Refuse only a new edit after captured-owner retirement. Existing queued
    // native writes, pending snapshots and flush/leave recovery remain intact.
    if (!ready || key == null || inputOwnerCurrent?.call() == false) {
      return;
    }
    final snapshot = Map<String, String>.of(fields);
    busy = true;
    changed();
    writes = writes.then((_) async {
      try {
        if (pending != null) {
          await session.saveLedgerForm(pending!, expectedRevision: revision);
          revision = pending!.revision;
          pending = null;
        }
        pending = WorkspaceLedgerFormDraft(
          key: key!,
          revision: (revision ?? 0) + 1,
          fields: snapshot,
        );
        await session.saveLedgerForm(pending!, expectedRevision: revision);
        revision = pending!.revision;
        pending = null;
        error = null;
      } catch (_) {
        error = 'Input is not saved yet. Retry saving before leaving.';
      }
    });
    final current = writes;
    unawaited(
      current.then((_) {
        if (identical(current, writes)) {
          busy = false;
          changed();
        }
      }),
    );
  }

  Future<bool> flush() async {
    if(preparedFields!=null){
      if(_preparedDraftRetired || inputOwnerCurrent?.call()==false || key==null)return false;
      try{
        final actual=await session.readLedgerForm(key!);
        if(inputOwnerCurrent?.call()==false)return false;
        if(actual?.revision!=capturedDraft?.revision || !mapEquals(actual?.fields,capturedDraft?.fields)){
          _preparedDraftRetired=true;error='Saved input changed. Your entries are kept. Reopen this form to review both drafts.';changed();return false;
        }
        error=null;changed();return ready;
      }catch(_){error='Saved input could not be checked. Your entries are kept. Try again.';changed();return false;}
    }
    await writes;
    return ready && pending == null && error == null;
  }

  @override
  void dispose() {
    closed = true;
    super.dispose();
  }
}

class _StoreExpensesSurface extends StatefulWidget {
  const _StoreExpensesSurface({
    super.key,
    required this.session,
    this.statement = false,
    this.register = false,
  });
  final WorkSession session;
  final bool statement;
  final bool register;
  @override
  State<_StoreExpensesSurface> createState() => _StoreExpensesSurfaceState();
}

class _StoreExpensesSurfaceState extends State<_StoreExpensesSurface> {
  bool loading = true, recovered = false;
  bool _ledgerSheetOpen = false;
  String? _registerId;

  Future<void> _openExpense() => _openLedgerSheet((owner) =>
    _StoreMoneyEntrySheet(session: widget.session, ownerCurrent: owner));

  Future<void> _openRegisterEntry(String id) => _openLedgerSheet((owner) =>
    _StoreRegisterEntrySheet(session: widget.session, registerId: id, ownerCurrent: owner));

  Future<void> _openLedgerSheet(Widget Function(bool Function()) content) async {
    if (_ledgerSheetOpen || _supplierMoneyFormOpen(widget.session)) return;
    final session = widget.session, host = context.getInheritedWidgetOfExactType<MoolAssistantHost>();
    final captured = host?.readContext(), scope = session.workspaceSupplierScope;
    final original = session.workspaceOriginalLedgerConfigured;
    bool owner() {
      if (!mounted || session.workspaceSupplierScope != scope) return false;
      if (!original) return true;
      final current = host?.readContext(), account = current?.accountScope;
      return current?.binding == captured?.binding && account is
          ({String environment, String projectId, String? tenantId, String userId}) &&
        session.workspaceApprovalMatchesAccount(account);
    }
    if (!owner()) return;
    _ledgerSheetOpen = true;
    try {
      await showModalBottomSheet<void>(context: context, isScrollControlled: true, useSafeArea: true,
        builder: (sheetContext) => _supplierCapturedOwnerSheet(context, sheetContext, session, owner, content(owner)));
    } finally {_ledgerSheetOpen = false;}
  }

  Widget _originalExpenseAction() => TextButton.icon(key: const Key('store-expense-open'),
    onPressed: _openExpense, icon: const Icon(Icons.add, size: 18),
    label: Text(widget.session.workspaceOriginalLedgerPending?.operation == 'recordStoreExpense'
      ? 'Check expense status' : 'Record expense'));

  Widget _moneyBook(BuildContext context) {
    final session = widget.session;
    final original = session.workspaceOriginalLedgerConfigured;
    final pending = session.workspaceOriginalLedgerPending;
    final pendingRegister = pending?.operation == 'recordStoreMoneyRegisterEntry' ? pending!.targetId : null;
    if (loading || !recovered || original && session.workspaceOriginalLedgerSections == null) {
      return ListView(
        children: [
          Text(
            loading
                ? 'Opening saved money records…'
                : 'Money records are unavailable.',
          ),
          if (!loading)
            TextButton(
              onPressed: recover,
              child: const Text('Retry opening records'),
            ),
          if (!loading && pendingRegister != null)
            TextButton(key: const Key('work-money-register-record'), onPressed: () => _openRegisterEntry(pendingRegister),
              child: const Text('Check money-entry status')),
        ],
      );
    }
    final registers = session.workspaceMoneyRegisters;
    final selected = _registerId == ''
        ? null
        : registers
              .where((r) => _registerId == null || r.registerId == _registerId)
              .firstOrNull;
    final rows = <List<String>>[];
    final keys = <Key>[];
    final entryEntities=<int,String>{},entrySignatures=<int,String>{};
    final capturedSelection=_registerId,capturedPeriod=session.workspaceMoneyPeriod;
    void bindEntry(String entity) {
      final view=_storeMoneyEntryView(session,entity);
      if(view!=null){entryEntities[rows.length]=entity;entrySignatures[rows.length]=view.signature;}
    }

    var debit = 0, credit = 0;
    String balanceText(int? minor) => minor == null
        ? 'Unavailable'
        : '${_formatStoreMinorAmount(minor.abs())}${minor == 0
              ? ''
              : minor > 0
              ? ' Dr'
              : ' Cr'}';
    int? closing;
    var unavailable = false;
    if (selected != null) {
      final now = DateTime.now();
      final end = selected.asOf.isBefore(now) ? selected.asOf : now;
      final start = session.workspaceMoneyPeriodStart ?? selected.openingAt;
      final balances = !original && session.workspaceFinanceStale
          ? null
          : selected.balances(start, end);
      int? running = balances?.openingMinor;
      unavailable = balances == null;
      rows.add(['', 'Opening Balance', '', '', '', '', balanceText(running)]);
      keys.add(const ValueKey('money-book-opening'));
      for (final entry in selected.entries.where(
        (e) => !e.occurredAt.isBefore(start) && e.occurredAt.isBefore(end),
      )) {
        if (entry.deltaMinor > 0) {
          debit += entry.deltaMinor;
        } else {
          credit -= entry.deltaMinor;
        }
        if (running != null) running += entry.deltaMinor;
        bindEntry(jsonEncode(['register',selected.registerId,entry.id]));
        rows.add([
          _registerDate(entry.occurredAt),
          entry.reference,
          'Movement',
          entry.id,
          entry.deltaMinor > 0 ? _formatStoreMinorAmount(entry.deltaMinor) : '',
          entry.deltaMinor < 0
              ? _formatStoreMinorAmount(-entry.deltaMinor)
              : '',
          balanceText(running),
        ]);
        keys.add(ValueKey('money-book-entry-${entry.id}'));
      }
      closing = balances?.closingMinor;
      rows.add(['', 'Closing Balance', '', '', '', '', balanceText(closing)]);
      keys.add(const ValueKey('money-book-closing'));
    } else {
      unavailable = true;
      final statement = session.workspaceMoneyStatement;
      for (final entry
          in statement?.entries ?? <WorkspaceMoneyStatementEntry>[]) {
        if (entry.posted && !entry.transfer) {
          if (entry.incoming) {
            debit += entry.amountMinor;
          } else {
            credit += entry.amountMinor;
          }
        }
        bindEntry(entry.id);
        rows.add([
          _registerDate(entry.occurredAt),
          entry.party,
          entry.label,
          entry.reference,
          entry.incoming ? _formatStoreMinorAmount(entry.amountMinor) : '',
          !entry.incoming ? _formatStoreMinorAmount(entry.amountMinor) : '',
          entry.status,
        ]);
        keys.add(ValueKey('work-money-entry-${entry.id}'));
      }
    }
    return Column(
      key: const Key('work-money-statement'),
      children: [
        Align(
          alignment: Alignment.centerLeft,
          child: PopupMenuButton<String>(
            key: const Key('work-money-book-selector'),
            onSelected: (id) => setState(() => _registerId = id),
            itemBuilder: (_) => [
              for (final r in registers)
                PopupMenuItem(value: r.registerId, child: Text(r.label)),
              const PopupMenuItem(value: '', child: Text('Recorded movements')),
            ],
            child: Padding(
              padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 12),
              child: Row(
                mainAxisSize: MainAxisSize.min,
                children: [
                  Flexible(
                    child: Text(
                      selected?.label ?? 'Recorded movements',
                      style: const TextStyle(
                        fontSize: 13,
                        fontWeight: FontWeight.w600,
                      ),
                    ),
                  ),
                  const SizedBox(width: 4),
                  const Icon(Icons.expand_more, size: 18),
                ],
              ),
            ),
          ),
        ),
        if (original && (pendingRegister != null || selected != null &&
            session.canRecordWorkspaceOriginalRegisterEntry(selected.registerId)))
          Align(alignment: Alignment.centerLeft, child: TextButton.icon(key: const Key('work-money-register-record'),
            onPressed: () => _openRegisterEntry(pendingRegister ?? selected!.registerId),
            icon: const Icon(Icons.add, size: 18), label: Text(pendingRegister == null ? 'Record money entry' : 'Check money-entry status'))),
        if (unavailable)
          Padding(
            padding: const EdgeInsets.symmetric(horizontal: 16),
            child: Text(
              selected == null
                  ? 'Select a supplied cash/bank account for balances.'
                  : 'Opening balance or complete history unavailable.',
              style: const TextStyle(fontSize: 11),
            ),
          ),
        Expanded(
          child: _StoreVoucherRegister(
            identity: (
              'money',
              session.workspaceStockHistoryScope()?.key,
              selected?.registerId,
              session.workspaceMoneyPeriod,
            ),
            headers: selected == null
                ? const [
                    'Date',
                    'Particulars',
                    'Entry Type',
                    'Reference',
                    'Money in (₹)',
                    'Money out (₹)',
                    'Status',
                  ]
                : const [
                    'Date',
                    'Particulars',
                    'Entry Type',
                    'Reference ID',
                    'Debit (₹)',
                    'Credit (₹)',
                    'Balance (₹)',
                  ],
            rows: rows,
            rowKeys: keys,
            openableRows:entryEntities.keys.toSet(),
            onOpen:(index) {
              if(!mounted||ModalRoute.of(context)?.isCurrent!=true||_registerId!=capturedSelection||session.workspaceMoneyPeriod!=capturedPeriod)return;
              final entity=entryEntities[index],signature=entrySignatures[index];
              if(entity==null||signature==null||_storeMoneyEntryView(session,entity)?.signature!=signature)return;
              unawaited(showStoreMoneyEntryDetails(context,session,entity,expectedSignature:signature,
                ownerCurrent:()=>mounted&&_registerId==capturedSelection&&session.workspaceMoneyPeriod==capturedPeriod,
                ownerChanges:session));
            },

            amountColumns: const {4, 5, 6},
            total: '',
            footer: [
              '',
              'Recorded total',
              '',
              '',
              original && selected == null ? 'Unavailable' : _formatStoreMinorAmount(debit),
              original && selected == null ? 'Unavailable' : _formatStoreMinorAmount(credit),
              selected == null ? '' : balanceText(closing),
            ],
            notice: selected == null
                ? original ? 'Combined movements require their original source. Select an available cash/bank register.'
                  : 'Posted movements only in totals; pending entries and transfers excluded.'
                : 'Book balance, not a verified bank balance. Movement type is supplied without an inferred voucher classification.',
            empty: original && selected == null ? 'Combined money movements are unavailable.' : 'No records in this period.',
          ),
        ),
      ],
    );
  }

  @override
  void initState() {
    super.initState();
    unawaited(recover());
  }

  Future<void> recover() async {
    final result = widget.session.workspaceOriginalLedgerConfigured
      ? await widget.session.loadWorkspaceOriginalLedger(retry: true)
      : await widget.session.recoverCustomerLedger();
    if (mounted) {
      setState(() {
        loading = false;
        recovered = result;
      });
    }
  }

  @override
  Widget build(BuildContext context) {
    if (widget.statement) return _moneyBook(context);
    final original = widget.session.workspaceOriginalLedgerConfigured;
    final sourceReady = recovered && (!original || widget.session.workspaceOriginalLedgerSections != null);
    final start = widget.session.workspaceMoneyPeriodStart;
    final expenses = widget.session.workspaceExpenses
        .where(
          (expense) => start == null || !expense.occurredAt.isBefore(start),
        )
        .toList();
    if (sourceReady && widget.register) {
      final register = _StoreVoucherRegister(
        identity: (
          'expenses',
          widget.session.workspaceStockHistoryScope()?.key,
          widget.session.workspaceMoneyPeriod,
        ),
        headers: const [
          'Date',
          'Particulars',
          'Voucher Type',
          'Reference',
          'Amount (₹)',
        ],
        rows: [
          for (final expense in expenses)
            [
              _registerDate(expense.occurredAt),
              expense.category,
              'Expense',
              expense.reference,
              _formatStoreMinorAmount(expense.amountMinor),
            ],
        ],
        rowKeys: [
          for (final expense in expenses)
            ValueKey('work-expense-${expense.operationId}'),
        ],
        amountColumns: const {4},
        total: _formatStoreMinorAmount(
          expenses.fold<int>(0, (sum, expense) => sum + expense.amountMinor),
        ),
        notice: 'Recorded expenses · not a cash or bank balance',
        empty: 'No expense entries recorded for this period.',
      );
      return original ? Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
        if (widget.session.canRecordWorkspaceOriginalExpense ||
            widget.session.workspaceOriginalLedgerPending?.operation == 'recordStoreExpense')
          Align(alignment: Alignment.centerLeft, child: _originalExpenseAction()),
        Expanded(child: register),
      ]) : register;
    }
    return ListView(
      key: const Key('work-finance-expenses'),
      padding: const EdgeInsets.all(16),
      children: [
        Text(
          'Business expenses',
          style: Theme.of(context).textTheme.titleLarge,
        ),
        if (loading)
          const Text('Opening saved expenses…')
        else if (!sourceReady) ...[
          const Text('Saved expenses could not be opened.'),
          TextButton(
            onPressed: recover,
            child: const Text('Retry opening expenses'),
          ),
          if (original && widget.session.workspaceOriginalLedgerPending?.operation == 'recordStoreExpense')
            TextButton(key: const Key('store-expense-open'), onPressed: _openExpense, child: const Text('Check expense status')),
        ] else ...[
          Text(
            'Recorded expenses ${_purchaseAmount(expenses.fold<int>(0, (sum, expense) => sum + expense.amountMinor))}',
            key: const Key('work-expense-period-total'),
          ),
          if (widget.session.canRecordStoreReviewExpense || widget.session.canRecordWorkspaceOriginalExpense ||
              widget.session.workspaceOriginalLedgerPending?.operation == 'recordStoreExpense')
            TextButton.icon(
              key: const Key('store-expense-open'),
              icon: const Icon(Icons.add),
              label: Text(widget.session.workspaceOriginalLedgerConfigured
                ? widget.session.workspaceOriginalLedgerPending?.operation == 'recordStoreExpense'
                  ? 'Check expense status' : 'Record expense'
                : 'Record test expense'),
              onPressed: _openExpense,
            ),
          const Text(
            'Recorded entries for this Store and period. Purchases and settlements stay in their own records.',
          ),
          if (expenses.isEmpty)
            const Text('No expense entries recorded for this period.'),
          for (final expense in expenses)
            Padding(
              key: ValueKey('work-expense-${expense.operationId}'),
              padding: const EdgeInsets.symmetric(vertical: 12),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    expense.category,
                    style: const TextStyle(fontWeight: FontWeight.w700),
                  ),
                  Text(_purchaseAmount(expense.amountMinor)),
                  Text('${expense.method} · ${expense.reference}'),
                  Text(
                    '${expense.occurredAt.day}/${expense.occurredAt.month}/${expense.occurredAt.year}',
                  ),
                  if (expense.note.isNotEmpty) Text(expense.note),
                  const Divider(),
                ],
              ),
            ),
        ],
      ],
    );
  }
}

class _StoreSupplierRefundTarget {
  const _StoreSupplierRefundTarget({required this.supplierId, required this.sourceKind,
    required this.sourceId, required this.label, required this.opening, this.copy});
  final String supplierId, sourceId, label;
  final WorkspaceSupplierRefundSourceKind sourceKind;
  final WorkspaceSupplierOpeningRecord opening;
  final WorkspacePurchaseSavedCopy? copy;
  WorkspaceLedgerFormKey? key(WorkSession session) => session.supplierRefundRecoveryFormKey(
    supplierId: supplierId, sourceKind: sourceKind, sourceId: sourceId,
    openingRevision: opening.revision, copyId: copy?.id, copyRevision: copy?.revision);
}

String _supplierRefundPrintedDate(String value) {
  if (!RegExp(r'^\d{4}-\d{2}-\d{2}$').hasMatch(value)) return value;
  final day = DateTime.tryParse(value);
  if (day == null || !day.toIso8601String().startsWith(value)) return value;
  return '${value.substring(8)}/${value.substring(5, 7)}/${value.substring(0, 4)}';
}

class _StoreSupplierRefundSourceSelector extends StatefulWidget {
  const _StoreSupplierRefundSourceSelector({required this.supplierName, required this.sources});
  final String supplierName;
  final List<_StoreSupplierRefundTarget> sources;
  @override
  State<_StoreSupplierRefundSourceSelector> createState() => _StoreSupplierRefundSourceSelectorState();
}

class _StoreSupplierRefundSourceSelectorState extends State<_StoreSupplierRefundSourceSelector> {
  final search = TextEditingController();
  String normalized(String value) => value.toLowerCase().replaceAll(RegExp(r'\s'), '');
  @override
  void dispose() { search.dispose(); super.dispose(); }
  @override
  Widget build(BuildContext context) => Dialog.fullscreen(child: SafeArea(child: LayoutBuilder(builder: (context, bounds) {
    final query = normalized(search.text);
    // Enumerate before filtering: row identity and returned source stay unchanged.
    final visible = widget.sources.indexed.where((row) => normalized(row.$2.label).contains(query)).toList();
    final short = bounds.maxHeight < MediaQuery.textScalerOf(context).scale(160);
    const heading = Text('Choose refund source',
      style: TextStyle(fontSize: 14, fontWeight: FontWeight.w700, color: MoolColors.navy));
    final identity = Align(alignment: Alignment.centerLeft, child: Text(widget.supplierName,
      style: const TextStyle(fontSize: 12, fontWeight: FontWeight.w600, color: MoolColors.ink)));
    const guide = Text('Choose the bill or advance linked to the refund. You can also reopen a saved request.',
      style: TextStyle(fontSize: 12, color: MoolColors.muted));
    final close = IconButton(key: const Key('supplier-refund-source-close'), tooltip: 'Close',
      onPressed: () => Navigator.pop(context), icon: const Icon(Icons.close, size: 20));
    final searchField = TextField(key: const Key('supplier-refund-source-search'), controller: search,
      onChanged: (_) => setState(() {}), style: const TextStyle(fontSize: 13), textInputAction: TextInputAction.search,
      decoration: InputDecoration(hintText: 'Search bill, advance or date', isDense: true,
        constraints: const BoxConstraints(minHeight: 48), prefixIcon: const Icon(Icons.search, size: 20),
        suffixIcon: search.text.isEmpty ? null : IconButton(tooltip: 'Clear source search',
          onPressed: () { search.clear(); setState(() {}); }, icon: const Icon(Icons.clear, size: 20))));
    final empty = Padding(padding: const EdgeInsets.all(16), child: Text(widget.sources.isEmpty
      ? 'No saved bill or advance. Recover the supplier account or record the supporting bill first.'
      : 'No matching sources', style: const TextStyle(fontSize: 13)));
    return Column(key: const Key('supplier-refund-source-selector'), children: [
      if (short) Padding(padding: const EdgeInsets.only(left: 12, right: 4),
        child: Row(children: [Expanded(child: searchField), close]))
      else ...[
        Padding(padding: const EdgeInsets.only(left: 12, right: 4), child: Row(children: [Expanded(child: heading), close])),
        Padding(padding: const EdgeInsets.symmetric(horizontal: 12), child: ConstrainedBox(
          constraints: BoxConstraints(maxHeight: bounds.maxHeight * .15), child: SingleChildScrollView(child: identity))),
        const Padding(padding: EdgeInsets.fromLTRB(12, 4, 12, 0), child: guide),
        Padding(padding: const EdgeInsets.fromLTRB(12, 8, 12, 8), child: searchField),
      ],
      Expanded(child: visible.isEmpty && !short ? Center(child: empty)
        : ListView.builder(key: const Key('supplier-refund-source-results'), itemCount: visible.length + (short ? 1 : 0),
          itemBuilder: (context, index) {
            if (short && index == 0) {
              return Padding(padding: const EdgeInsets.all(12), child: Column(
              crossAxisAlignment: CrossAxisAlignment.start, children: [heading, const SizedBox(height: 4), identity,
                const SizedBox(height: 4), guide, if (visible.isEmpty) empty]));
            }
            final row = visible[index - (short ? 1 : 0)];
            return InkWell(key: ValueKey('supplier-refund-source-${row.$1}'), onTap: () => Navigator.pop(context, row.$2),
              child: Container(constraints: const BoxConstraints(minHeight: 48),
                padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 10),
                decoration: const BoxDecoration(border: Border(bottom: BorderSide(color: MoolColors.line))),
                child: Row(children: [Expanded(child: Text(row.$2.label,
                  style: const TextStyle(fontSize: 13, fontWeight: FontWeight.w600, color: MoolColors.navy))),
                  const SizedBox(width: 8), const Icon(Icons.chevron_right, size: 18, color: MoolColors.muted)])));
          })),
    ]);
  })));
}

List<_StoreSupplierRefundTarget> _supplierRefundTargets(WorkSession session, String supplierId) {
  final opening = session.workspaceSupplierOpeningRecord(supplierId);
  if (opening == null) return const [];
  final ledger = session.workspaceSupplierLedger(supplierId);
  final sources = <_StoreSupplierRefundTarget>[
    if (opening.supplierCredit) _StoreSupplierRefundTarget(supplierId: supplierId,
      sourceKind: WorkspaceSupplierRefundSourceKind.openingAdvance, sourceId: opening.id,
      label: 'Starting advance · ${_supplierRefundPrintedDate(opening.asOfDate)}', opening: opening),
    for (final entry in ledger?.entries ?? <WorkspaceSupplierLedgerEntry>[])
      if (entry.origin == WorkspaceSupplierEntryOrigin.supplierAccount && entry.kind == WorkspaceSupplierEntryKind.advance)
        _StoreSupplierRefundTarget(supplierId: supplierId,
          sourceKind: WorkspaceSupplierRefundSourceKind.accountAdvance, sourceId: entry.operationId,
          label: 'Advance · ${entry.reference} · ${_supplierRefundPrintedDate(entry.moneyReview?.occurredOn ?? '')}', opening: opening),
    for (final copy in session.workspaceLatestPurchaseCopies.where((c) => c.supplier.id == supplierId))
      _StoreSupplierRefundTarget(supplierId: supplierId, sourceKind: WorkspaceSupplierRefundSourceKind.manualBillSurplus,
        sourceId: copy.draft.id, label: 'Bill ${copy.draft.invoiceReference} · ${copy.draft.invoiceDate}',
        opening: opening, copy: copy),
  ];
  // These immutable journal identities only reopen encrypted originals when
  // ordinary source rows are unavailable. They never supply available credit.
  if (session.workspaceOriginalSupplierRefundConfigured) {
    final scope = session.workspaceSupplierScope;
    for (final original in [session.workspaceOriginalLedgerPending, session.workspaceOriginalLedgerResolution?.original]) {
      if (scope == null || original?.operation != 'recordStoreSupplierRefund' || original?.targetId != supplierId ||
          original?.scope.account != scope.$1 || original?.scope.store != scope.$2 || original?.scope.realm != session.originalPurchaseRealm) continue;
      try {
        final intent = WorkspaceSupplierRefundIntent.fromJson(original!.input);
        if (intent.qa != scope.$3 || intent.openingId != opening.id || intent.openingRevision != opening.revision) continue;
        final copy = intent.copyId == null ? null : session.workspacePurchaseCopies.where((copy) =>
          copy.id == intent.copyId && copy.revision == intent.copyRevision && copy.supplier.id == supplierId).singleOrNull;
        if (intent.copyId != null && copy == null || sources.any((target) =>
            target.sourceKind == intent.sourceKind && target.sourceId == intent.sourceId && target.copy?.id == intent.copyId)) continue;
        sources.add(_StoreSupplierRefundTarget(supplierId: supplierId, sourceKind: intent.sourceKind, sourceId: intent.sourceId,
          label: 'Saved refund · ${intent.reference}', opening: opening, copy: copy));
      } on Object {continue;}
    }
  }
  return sources;
}

Future<void> _chooseSupplierRefund(BuildContext context, WorkSession session, String supplierId, {bool Function()? ownerCurrent}) async {
  final host = context.getInheritedWidgetOfExactType<MoolAssistantHost>();
  final workspace = context.getInheritedWidgetOfExactType<MoolAssistantWorkspaceScope>();
  final captured = host?.readContext().withWorkspace(workspace?.readWorkspace());
  final scope = session.workspaceSupplierScope, publication = session.publicationPreferencesContext;
  bool current() => context.mounted && ownerCurrent?.call() != false && session.workspaceSupplierScope == scope &&
    session.publicationPreferencesContext == publication && (host == null || captured?.signedIn == true &&
      host.readContext().withWorkspace(workspace?.readWorkspace()).binding == captured!.binding);
  if (!current()) return;
  if (session.workspaceSupplierOpeningRecord(supplierId) == null) return;
  final retained = <WorkSupplierRefundRecoverySource>[];
  // A current original source already lists every advance. Inspect encrypted
  // form identities only when that source is unavailable, never for capacity.
  if (session.workspaceOriginalSupplierRefundConfigured && session.workspaceOriginalLedgerSections == null) {
    try {retained.addAll(await session.readWorkspaceOriginalSupplierRefundRecoverySources(supplierId));}
    on Object {if (current()) session.showNotice('Saved refund sources could not be verified. Keep the original requests and retry.'); return;}
    if (!current()) return;
  }
  final sources = _supplierRefundTargets(session, supplierId);
  final opening = session.workspaceSupplierOpeningRecord(supplierId);
  if (opening == null) return;
  for (final hint in retained) {
    if (hint.qa != scope?.$3 || hint.openingId != opening.id || hint.openingRevision != opening.revision ||
        sources.any((source) => source.sourceKind == hint.sourceKind && source.sourceId == hint.sourceId && source.copy?.id == hint.copyId)) continue;
    final copy = hint.copyId == null ? null : session.workspacePurchaseCopies.where((copy) =>
      copy.id == hint.copyId && copy.revision == hint.copyRevision && copy.supplier.id == supplierId).singleOrNull;
    if (hint.copyId != null && copy == null) continue;
    sources.add(_StoreSupplierRefundTarget(supplierId: supplierId, sourceKind: hint.sourceKind, sourceId: hint.sourceId,
      label: 'Saved refund · ${hint.reference}', opening: opening, copy: copy));
  }
  final target = await showDialog<_StoreSupplierRefundTarget>(context: context, useSafeArea: true,
    builder: (dialogContext) => _purchaseCapturedOwnerPage(context, dialogContext, session, current, _StoreSupplierRefundSourceSelector(
      supplierName: session.workspaceSuppliers.where((supplier) => supplier.id == supplierId).firstOrNull?.name ?? 'Supplier unavailable',
      sources: sources)));
  if (target != null && current()) await _showSupplierRefund(context, session, target, ownerCurrent: current);
}

Future<void> _showSupplierRefund(BuildContext context, WorkSession session,
    _StoreSupplierRefundTarget target, {StoreSupplierRefundInitialData? initialData,
    WorkspaceLedgerFormDraft? recoveryDraft,
    WorkspaceLedgerFormKey? prefillKey, String? prefillSignature,
    bool Function()? prefillCurrent, bool Function()? ownerCurrent, bool readOnlyOpen = false, StoreSupplierSelectedDocumentInput? selectedDocument}) async {
  final host = context.getInheritedWidgetOfExactType<MoolAssistantHost>();
  final workspace = context.getInheritedWidgetOfExactType<MoolAssistantWorkspaceScope>();
  final captured = host?.readContext().withWorkspace(workspace?.readWorkspace());
  bool refundOwner() => context.mounted && ownerCurrent?.call() != false &&
    (host == null || captured?.signedIn == true &&
      host.readContext().withWorkspace(workspace?.readWorkspace()).binding == captured!.binding);
  if (session.workspaceOriginalSupplierRefundConfigured) {
    final owner = session.workspaceSupplierScope, publication = session.publicationPreferencesContext;
    if (!readOnlyOpen) await session.loadWorkspaceOriginalLedger();
    if (!refundOwner() || owner != session.workspaceSupplierScope ||
        publication != session.publicationPreferencesContext || !session.hasVerifiedWorkspace) return;
  }
  if (!refundOwner()) return;
  await showModalBottomSheet<void>(context: context,
      isScrollControlled: true, useSafeArea: true, isDismissible: false, enableDrag: false,
      builder: (sheetContext) => _supplierCapturedOwnerSheet(
        context, sheetContext, session, refundOwner, _StoreSupplierRefundSheet(session: session, target: target,
        initialData: initialData, recoveryDraft: recoveryDraft,
        prefillKey: prefillKey, prefillSignature: prefillSignature,
        prefillCurrent: prefillCurrent, ownerCurrent: refundOwner, readOnlyOpen: readOnlyOpen, selectedDocument: selectedDocument)));
}

class _StoreSupplierRefundSheet extends StatefulWidget {
  const _StoreSupplierRefundSheet({required this.session, required this.target,
    this.initialData, this.recoveryDraft, this.prefillKey, this.prefillSignature, this.prefillCurrent, this.ownerCurrent, this.readOnlyOpen = false, this.selectedDocument});
  final StoreSupplierRefundInitialData? initialData;
  final WorkspaceLedgerFormDraft? recoveryDraft;
  final WorkspaceLedgerFormKey? prefillKey;
  final String? prefillSignature;
  final bool Function()? prefillCurrent, ownerCurrent;
  final bool readOnlyOpen;
  final StoreSupplierSelectedDocumentInput? selectedDocument;
  final WorkSession session;
  final _StoreSupplierRefundTarget target;
  @override
  State<_StoreSupplierRefundSheet> createState() => _StoreSupplierRefundSheetState();
}

class _StoreSupplierRefundSheetState extends State<_StoreSupplierRefundSheet> {
  final Object _nativeAdjustmentToken = Object();
  late final WorkSession _nativeAdjustmentOwner;
  bool _initialAttempted = false;
  bool _recoveryReadChecked = false;
  late final _LedgerFormAutosave draft;
  final formFocus = FocusScopeNode();
  final amount = TextEditingController(), reference = TextEditingController(), date = TextEditingController();
  String channel = 'Cash';
  WorkspaceSupplierRefundIntent? frozen;
  late final bool _originalRefund;
  WorkspaceLedgerIntent? _refundIntent;
  String? _refundStatus;
  WorkspaceLedgerFormDraft? resetAttempt;
  WorkspaceSupplierMoneyCopies? supportingCopies;
  bool _busy = false, closing = false, recovered = false, statusVerified = false;
  Object? _copyBusyLease;
  bool get busy => _busy || _copyBusyLease != null;
  String? confirmedAttempt;
  bool get confirmed => current && frozen != null &&
    confirmedAttempt == jsonEncode(frozen!.toJson());
  String? error;
  WorkspaceSupplierLedger? get ledger => widget.session.workspaceSupplierLedger(widget.target.supplierId);
  bool get current => draft.key != null && widget.ownerCurrent?.call() != false && widget.target.key(widget.session) == draft.key;
  String printedDate(String day) => '${day.substring(8)}/${day.substring(5, 7)}/${day.substring(0, 4)}';
  String? get occurredOn {
    final m = RegExp(r'^(\d{2})/(\d{2})/(\d{4})$').firstMatch(date.text.trim());
    if (m == null) return null;
    final parsed = DateTime(int.parse(m[3]!), int.parse(m[2]!), int.parse(m[1]!));
    if (parsed.year != int.parse(m[3]!) || parsed.month != int.parse(m[2]!) || parsed.day != int.parse(m[1]!)) return null;
    return '${m[3]}-${m[2]}-${m[1]}';
  }
  WorkspaceSupplierRefundIntent intent({required String id, required int minor}) => WorkspaceSupplierRefundIntent(
    operationId: id, accountScope: draft.key!.account, workspaceId: draft.key!.store,
    supplierId: widget.target.supplierId, qa: widget.target.opening.qa,
    openingId: widget.target.opening.id, openingRevision: widget.target.opening.revision,
    sourceKind: widget.target.sourceKind, sourceId: widget.target.sourceId,
    copyId: widget.target.copy?.id, copyRevision: widget.target.copy?.revision,
    amountMinor: minor, reference: reference.text.trim(), occurredOn: occurredOn ?? '',
    paymentMethod: channel, requestedAt: DateTime.now().toUtc());
  int? get capacity {
    if (!recovered || !current) return null;
    final probe = WorkspaceSupplierRefundIntent(operationId: 'refund-capacity-review',
      accountScope: draft.key!.account, workspaceId: draft.key!.store, supplierId: widget.target.supplierId,
      qa: widget.target.opening.qa, openingId: widget.target.opening.id,
      openingRevision: widget.target.opening.revision, sourceKind: widget.target.sourceKind,
      sourceId: widget.target.sourceId, copyId: widget.target.copy?.id, copyRevision: widget.target.copy?.revision,
      amountMinor: 1, reference: 'Capacity review', occurredOn: DateTime.now().toIso8601String().substring(0, 10),
      paymentMethod: 'Cash', requestedAt: DateTime.now().toUtc());
    return ledger?.reviewedRefundCapacity(probe);
  }
  Map<String, String> get fields => {'amount': amount.text, 'reference': reference.text,
    'channel': channel, 'occurredOn': frozen?.occurredOn ?? date.text,
    'sourceKind': widget.target.sourceKind.name, 'sourceId': widget.target.sourceId,
    if (frozen != null) 'attempt': jsonEncode(frozen!.toJson()),
    if (supportingCopies != null) 'supportingCopies': jsonEncode(supportingCopies!.toJson())};
  @override
  void initState() {
    super.initState();
    _nativeAdjustmentOwner = widget.session;
    _originalRefund = widget.session.workspaceOriginalSupplierRefundConfigured;
    if (_originalRefund) widget.session.addListener(refresh);
    (_openSupplierAdjustmentForms[_nativeAdjustmentOwner] ??= <Object>{}).add(_nativeAdjustmentToken);
    draft = _LedgerFormAutosave(widget.session, widget.recoveryDraft?.key ?? widget.target.key(widget.session),
      inputOwnerCurrent: () => widget.ownerCurrent?.call() != false && _refundIntent == null);
    draft.addListener(refresh); FocusManager.instance.addListener(refresh); unawaited(load(readOnlyOpen: widget.readOnlyOpen));
  }
  void refresh() { if (mounted) setState(() {}); }
  Future<void> verify() async {
    statusVerified = false;
    if (!current || frozen == null) return;
    if (_originalRefund) {
      final retained = await widget.session.readWorkspaceOriginalSupplierRefundRequest(draft.key!, frozen!);
      if (!mounted || !current) return;
      if (_refundIntent != null && (retained?.fingerprint != _refundIntent!.fingerprint ||
          retained?.idempotencyKey != _refundIntent!.idempotencyKey)) throw StateError('Original refund identity changed');
      _refundIntent = retained;
      if (retained == null && ledger?.refunds.containsKey(frozen!.operationId) == true) {
        throw StateError('Recorded refund original identity unavailable');
      }
      if (retained != null) await _resolveOriginalRefund();
      return;
    }
    final reviewed = frozen!;
    final proof = await widget.session.readWorkspaceSupplierRefundStatus(draft.key!, reviewed);
    if (!mounted || !current || frozen == null ||
        jsonEncode(frozen!.toJson()) != jsonEncode(reviewed.toJson())) {
      throw StateError('Store or saved request changed');
    }
    confirmedAttempt = proof != null ? jsonEncode(reviewed.toJson()) : null;
    statusVerified = true;
  }
  Future<void> load({bool readOnlyOpen = false}) async {
    if (busy || draft.busy) return;
    setState(() { _busy = true; error = null; });
    try {
      if (!await flushPending() || !mounted || !current) return;
      if (_originalRefund && !readOnlyOpen) {
        await widget.session.loadWorkspaceOriginalLedger(retry: true);
        if (!mounted || !current) return;
      }
      final saved = await draft.load();
      if (!mounted || saved == null || !current) throw StateError('Saved request unavailable');
      final expected = widget.recoveryDraft;
      if (expected != null && !_recoveryReadChecked) {
        if (draft.key != expected.key || draft.revision != expected.revision ||
            !mapEquals(saved, expected.fields)) {
          throw StateError('Original saved adjustment changed before restoration');
        }
        _recoveryReadChecked = true;
      }
      final copies = WorkspaceLedgerFormDraft(key: draft.key!, revision: draft.revision ?? 1,
        fields: saved).supplierRefundCopies;
      if (copies != null && copies.qa != widget.session.workspaceSupplierScope?.$3) {
        throw const FormatException('Saved refund copies belong to another Store mode');
      }
      frozen = saved['attempt']?.isNotEmpty == true
        ? WorkspaceSupplierRefundIntent.fromJson(jsonDecode(saved['attempt']!)) : null;
      supportingCopies = copies;
      amount.text = saved['amount'] ?? ''; reference.text = saved['reference'] ?? '';
      channel = saved['channel']?.isNotEmpty == true ? saved['channel']! : 'Cash';
      final savedDate = saved['occurredOn'];
      date.text = frozen == null ? savedDate == null ? printedDate(DateTime.now().toIso8601String().substring(0, 10))
        : RegExp(r'^\d{4}-\d{2}-\d{2}$').hasMatch(savedDate) ? printedDate(savedDate) : savedDate
        : printedDate(frozen!.occurredOn);
      if (frozen != null) await verify();
      recovered = _originalRefund ? widget.session.workspaceOriginalLedgerSections != null
        : readOnlyOpen ? widget.session.workspaceInvoiceHistoryLoaded : await widget.session.recoverCustomerLedger();
      if (!current) throw StateError('Store changed');
      if (!recovered) error = confirmed ? 'Refund recorded; account refresh pending.' : 'Account unavailable. Keep the saved request and retry recovery.';
      final initial = widget.initialData;
      if (initial != null && !_initialAttempted) {
        _initialAttempted = true;
        final pristine = saved.isEmpty && draft.revision == null && draft.pending == null &&
          !draft.busy && draft.error == null && frozen == null && supportingCopies == null &&
          resetAttempt == null && !confirmed && amount.text.isEmpty && reference.text.isEmpty;
        if (!current || !recovered || widget.prefillCurrent?.call() == false || !pristine ||
            widget.prefillKey != draft.key || !initial.matches(widget.target) ||
            widget.prefillSignature != _assistantRefundSignature(widget.session, widget.target)) {
          error = 'Suggestion was not applied. Existing refund input and saved attempts are kept.';
        } else {
          amount.text = initial.inputs['amount']!; reference.text = initial.inputs['reference']!;
          channel = initial.inputs['channel']!; date.text = _supplierRefundPrintedDate(initial.inputs['occurredOn']!);
          // No draft.save or flush; no money is recorded by Review.
        }
      }
    } on Object {
      recovered = false;
      error = confirmed ? 'Refund recorded; account refresh pending.' : 'Saved refund status is unverified. Keep these details and retry.';
    } finally { if (mounted) setState(() => _busy = false); }
  }
  Future<bool> flushPending() async {
    if (!draft.ready) return true;
    if (draft.pending != null) draft.save(fields);
    return await draft.flush();
  }
  Future<void> close() async {
    if (busy || closing || draft.busy) return;
    final route = ModalRoute.of(context);
    setState(() { closing = true; _busy = true; });
    try {
      if (await flushPending() && mounted && route?.isCurrent == true) {
        Navigator.pop(context);
      }
    } finally {
      if (mounted) setState(() { closing = false; _busy = false; });
    }
  }
  Future<void> submit() async {
    if (busy || !current || !draft.ready || draft.busy) return;
    setState(() { _busy = true; error = null; });
    try {
      if (!await draft.flush() || !mounted || !current) return;
      if (confirmed) {
        if (!recovered) { error = 'Refresh the account before recording another refund.'; return; }
        resetAttempt ??= WorkspaceLedgerFormDraft(key: draft.key!, revision: draft.revision! + 1, fields: {
          if (supportingCopies != null) 'supportingCopies': jsonEncode(supportingCopies!.archiveRefund(frozen!).toJson())});
        if (!await widget.session.resetConfirmedWorkspaceSupplierRefundDraft(resetAttempt!, expectedRevision: draft.revision!,
            original: _refundIntent, ownerCurrent: () => mounted && current)) {
          error = 'Recorded refund is kept. Retry recovery before starting another.'; return;
        }
        if (!mounted || !current) return;
        draft.revision = resetAttempt!.revision; draft.pending = null; draft.error = null;
        supportingCopies = resetAttempt!.supplierRefundCopies;
        frozen = null; resetAttempt = null; confirmedAttempt = null; statusVerified = false;
        _refundIntent = null; _refundStatus = null;
        amount.clear(); reference.clear(); channel = 'Cash';
        date.text = printedDate(DateTime.now().toIso8601String().substring(0, 10));
        return;
      }
      if (_originalRefund && _refundIntent != null) {await _resolveOriginalRefund(); return;}
      if (frozen == null) {
        if (_originalRefund && widget.initialData != null &&
            (widget.prefillCurrent?.call() == false ||
              widget.prefillSignature != _assistantRefundSignature(widget.session, widget.target))) {
          error = 'Refund records changed. Keep your input and review a fresh suggestion before saving.';
          return;
        }
        if (!recovered) { error = 'Recover the supplier account before recording money received.'; return; }
        final minor = WorkspacePurchaseEntryDraft.printedPaise(amount.text);
        if (minor == null || minor <= 0 || occurredOn == null) {
          error = 'Enter the amount received and a valid date (DD/MM/YYYY).'; return;
        }
        final review = intent(id: widget.session.newWorkspaceSupplierRefundId(), minor: minor);
        final available = ledger?.reviewedRefundCapacity(review);
        if (!review.valid || available == null || minor > available) {
          error = 'Check the reference, date and available credit. No refund was recorded.'; return;
        }
        reference.text = review.reference; amount.text = (minor / 100).toStringAsFixed(2);
        frozen = review; draft.save(fields);
        if (!await draft.flush() || !mounted || !current) return;
      }
      if (_originalRefund) {
        if (!current || !recovered) return;
        _refundIntent = widget.session.prepareWorkspaceOriginalSupplierRefund(draft.key!, frozen!);
        if (_refundIntent == null) {error = 'Refund records changed. Keep this input and refresh the original records.'; return;}
        await _resolveOriginalRefund(firstSave: true); return;
      }
      final posted = await widget.session.recordWorkspaceSupplierRefundDraft(draft.key!, frozen!);
      if (!mounted || !current) return;
      await verify();
      recovered = await widget.session.recoverCustomerLedger();
      if (!current) return;
      error = confirmed ? recovered ? null : 'Refund recorded; account refresh pending.'
        : posted ? 'Saved status needs verification. Retry recovery; do not enter this refund again.'
        : 'Refund not confirmed. Keep and retry this same saved request.';
    } on Object {
      error = confirmed ? 'Refund recorded; account refresh pending.' : 'Refund status unverified. Keep and recover this saved request.';
    } finally { if (mounted) setState(() => _busy = false); }
  }
  Future<void> _resolveOriginalRefund({bool firstSave = false, bool explicitRetry = false}) async {
    final original = _refundIntent, input = frozen, key = draft.key;
    if (original == null || input == null || key == null || !current) return;
    final result = firstSave
      ? await widget.session.recordWorkspaceOriginalSupplierRefund(original, key: key, intent: input,
          ownerCurrent: () => mounted && current)
      : await widget.session.checkWorkspaceOriginalSupplierRefundRequest(original, key: key, intent: input,
          explicitRetry: explicitRetry, ownerCurrent: () => mounted && current);
    if (!mounted || !current) return;
    if (result?.attempt != null) _refundStatus = result!.attempt!['status'] as String?;
    confirmedAttempt = _refundStatus == 'saved' ? jsonEncode(input.toJson()) : null;
    statusVerified = _refundStatus != null;
    recovered = widget.session.workspaceOriginalLedgerSections != null;
    error = result == null ? widget.session.workspaceOriginalLedgerError ?? 'Refund status could not be verified. Keep this original request.'
      : confirmed ? null : _refundStatus == 'not_saved' ? 'Refund not recorded. Review the saved details before trying again.'
      : 'Refund status is unconfirmed. Keep this request and check again.';
  }
  Future<void> _retryOriginalRefund() async {
    if (busy || !current || _refundIntent == null || _refundStatus != null) return;
    setState(() {_busy = true; error = null;});
    try {await _resolveOriginalRefund(explicitRetry: true);}
    finally {if (mounted) setState(() => _busy = false);}
  }
  Future<void> _reviewRefusedRefund() async {
    if (busy || !current || _refundStatus != 'not_saved' || draft.revision == null || frozen == null) return;
    setState(() {_busy = true; error = null;});
    try {
      final retained = {...fields}..remove('attempt'), oldDay = frozen!.occurredOn;
      final next = WorkspaceLedgerFormDraft(key: draft.key!, revision: draft.revision! + 1, fields: retained);
      if (!await widget.session.resetRefusedWorkspaceSupplierRefundDraft(next,
          expectedRevision: draft.revision!, ownerCurrent: () => mounted && current)) {
        if (mounted && current) error = 'Check this exact refund status before reviewing the saved details.';
        return;
      }
      if (!mounted || !current) return;
      draft.revision = next.revision; draft.pending = null; draft.error = null;
      frozen = null; _refundIntent = null; _refundStatus = null; confirmedAttempt = null; statusVerified = false;
      date.text = printedDate(oldDay); recovered = widget.session.workspaceOriginalLedgerSections != null;
    } finally {if (mounted) setState(() => _busy = false);}
  }
  @override
  void dispose() {
    if (_originalRefund) widget.session.removeListener(refresh);
    _openSupplierAdjustmentForms[_nativeAdjustmentOwner]?.remove(_nativeAdjustmentToken);
    draft.removeListener(refresh); draft.dispose();
    FocusManager.instance.removeListener(refresh); formFocus.dispose();
    amount.dispose(); reference.dispose(); date.dispose(); super.dispose();
  }
  InputDecoration _refundInput(String? label, {String? helper}) => InputDecoration(
    labelText: label, helperText: helper, helperMaxLines: 3, isDense: true,
    labelStyle: const TextStyle(fontSize: 12), helperStyle: const TextStyle(fontSize: 11),
    constraints: const BoxConstraints(minHeight: 48),
    contentPadding: const EdgeInsets.symmetric(horizontal: 12, vertical: 14));
  EditableTextState? get _focusedRefundEditor {
    final editor = FocusManager.instance.primaryFocus?.context?.findAncestorStateOfType<EditableTextState>();
    return editor?.context.findAncestorStateOfType<_StoreSupplierRefundSheetState>() == this ? editor : null;
  }
  double _refundDateWidth(BuildContext context, double availableWidth) {
    final theme = Theme.of(context);
    final base = theme.useMaterial3 ? theme.textTheme.bodyLarge! : theme.textTheme.titleMedium!;
    final painter = TextPainter(text: TextSpan(
      text: RegExp(r'^\d{2}/\d{2}/\d{4}$').hasMatch(date.text) ? date.text : '00/00/0000',
      style: base.merge(const TextStyle(fontSize: 13))),
      textDirection: Directionality.of(context), textScaler: MediaQuery.textScalerOf(context))..layout();
    // Material 3 also reserves the outline's gap on each side of the input.
    final border = theme.inputDecorationTheme.border;
    final outlineGaps = theme.useMaterial3 && border is OutlineInputBorder ? border.gapPadding * 2 : 0.0;
    final measured = (painter.width + 24 + outlineGaps + 8).ceilToDouble();
    painter.dispose();
    return (measured < 170 ? 170.0 : measured).clamp(0.0, availableWidth).toDouble();
  }
  Widget _refundViewport(BuildContext context, Widget body) => FocusScope(node: formFocus,
    child: SafeArea(top: false, child: Padding(padding: EdgeInsets.only(
      // Leave a small usable gap between field borders/help and the keyboard.
      bottom: MediaQuery.viewInsetsOf(context).bottom > 0 ? MediaQuery.viewInsetsOf(context).bottom + 8 : 0),
      child: LayoutBuilder(builder: (context, constraints) => ConstrainedBox(
        constraints: BoxConstraints(maxHeight: constraints.maxHeight),
        child: Column(mainAxisSize: MainAxisSize.min, children: [
          Padding(padding: const EdgeInsets.fromLTRB(16, 8, 8, 0), child: Row(children: [
            const Expanded(child: Text('Supplier refund received',
              style: TextStyle(fontSize: 14, fontWeight: FontWeight.w700, color: MoolColors.navy))),
            if (_focusedRefundEditor?.widget.readOnly == false || MediaQuery.viewInsetsOf(context).bottom > 0)
              IconButton(key: const Key('supplier-refund-hide-keyboard'), tooltip: 'Hide keyboard',
                onPressed: formFocus.unfocus, icon: const Icon(Icons.keyboard_hide_outlined)),
            TextButton(key: const Key('supplier-refund-close'),
              style: TextButton.styleFrom(textStyle: const TextStyle(fontSize: 12)),
              onPressed: busy || draft.busy ? null : close, child: const Text('Close')),
          ])),
          Flexible(child: NotificationListener<ScrollNotification>(onNotification: (notification) {
            if (notification.depth == 0 &&
                (notification is ScrollStartNotification || notification is ScrollUpdateNotification)) {
              _focusedRefundEditor?.hideToolbar();
            }
            return false;
          }, child: body)),
        ]),
      )))));
  @override
  Widget build(BuildContext context) {
    final editable = draft.ready && recovered && current && !busy && frozen == null;
    final retained = current && frozen != null;
    final available = capacity;
    return PopScope(canPop: !busy && !draft.busy && draft.pending == null && draft.error == null,
      onPopInvokedWithResult: (didPop, result) async { if (!didPop) await close(); },
      child: _refundViewport(context, SingleChildScrollView(padding: const EdgeInsets.fromLTRB(16, 8, 16, 16),
        child: Theme(data: Theme.of(context).copyWith(textButtonTheme: TextButtonThemeData(
          style: TextButton.styleFrom(minimumSize: const Size(48, 48), textStyle: const TextStyle(fontSize: 12)))),
        child: DefaultTextStyle.merge(style: const TextStyle(fontSize: 12, color: MoolColors.ink),
          child: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.stretch, children: [
            Text(widget.session.workspaceSuppliers.where((s) => s.id == widget.target.supplierId).firstOrNull?.name ?? 'Supplier',
              key: const Key('supplier-refund-supplier'), style: const TextStyle(fontSize: 13, fontWeight: FontWeight.w600)),
            Text(widget.target.label, key: const Key('supplier-refund-source')),
            const SizedBox(height: 6),
            const Text('Record money already received from your supplier.'),
            const SizedBox(height: 6),
            Text(available == null ? 'Available credit needs verification' : 'Available credit ${_purchaseAmount(available)}',
              key: const Key('supplier-refund-available'), style: const TextStyle(fontWeight: FontWeight.w600)),
            if (!retained && available == 0) const Padding(padding: EdgeInsets.only(top: 4),
              child: Text('No refundable balance is recorded for this source. Refresh the supplier account or check its linked payments and credits.',
                key: Key('supplier-refund-zero-guide'), style: TextStyle(fontSize: 11))),
            const SizedBox(height: 8),
            LayoutBuilder(builder: (context, constraints) => Wrap(spacing: 12, runSpacing: 8, children: [
              _purchaseCompactLabeledField('Amount received (₹)', width: 145, field: TextField(
                key: const Key('supplier-refund-amount'), controller: amount, enabled: editable || retained,
                readOnly: retained,
                keyboardType: const TextInputType.numberWithOptions(decimal: true),
                style: const TextStyle(fontSize: 13), decoration: _refundInput(null),
                onChanged: editable ? (_) => draft.save(fields) : null)),
              _purchaseCompactLabeledField('Receipt date', width: _refundDateWidth(context, constraints.maxWidth), field: TextField(
                key: const Key('supplier-refund-date'), controller: date, enabled: editable || retained,
                readOnly: retained,
                style: const TextStyle(fontSize: 13),
                decoration: _refundInput(null, helper: retained ? null : 'DD/MM/YYYY'), keyboardType: TextInputType.datetime,
                onChanged: editable ? (_) => draft.save(fields) : null)),
            ])),
            const SizedBox(height: 8),
            if (retained) Padding(padding: const EdgeInsets.symmetric(vertical: 8),
              child: Text('Refund mode · $channel', key: const Key('supplier-refund-saved-method'),
                style: const TextStyle(fontSize: 13, fontWeight: FontWeight.w600)))
            else DropdownButtonFormField<String>(key: ValueKey('supplier-refund-method-$channel'), initialValue: channel,
              isExpanded: true, style: const TextStyle(fontSize: 13, color: MoolColors.navy), decoration: _refundInput('Refund mode'),
              items: [for (final method in ['Cash', 'UPI', 'Bank transfer']) DropdownMenuItem(value: method, child: Text(method))],
              onChanged: editable ? (value) { setState(() => channel = value!); draft.save(fields); } : null),
            const SizedBox(height: 8),
            TextField(key: const Key('supplier-refund-reference'), controller: reference, enabled: editable || retained,
              readOnly: retained,
              style: const TextStyle(fontSize: 13), decoration: _refundInput('Refund reference'),
              onChanged: editable ? (_) => draft.save(fields) : null),
            if (!retained) const Padding(padding: EdgeInsets.only(top: 4), child: Text(
              'Receipt No. / UPI reference / bank reference', style: TextStyle(fontSize: 11))),
            if (frozen != null) Text(confirmed ? 'Refund recorded · ${_purchaseAmount(frozen!.amountMinor)}'
              : statusVerified ? 'Saved request · not recorded' : 'Saved refund status unverified', key: const Key('supplier-refund-status')),
            if (confirmed && recovered && ledger?.creditMinor != null) Text('Credit remaining with supplier ${_purchaseAmount(ledger!.creditMinor!)}'),
            if (draft.ready && recovered && current && widget.session.workspaceSupplierScope != null &&
                (frozen == null || supportingCopies?.active.isNotEmpty == true ||
                  supportingCopies?.previous.isNotEmpty == true)) _SupplierPaymentDraftCopies(
              sourceRevision: () => jsonEncode([draft.revision, fields]),
              selectedDocument: widget.selectedDocument,
              canStageSelected: (lease) => draft.ready && recovered && current && !_busy && frozen == null && !draft.busy && draft.error == null &&
                (_copyBusyLease == null || identical(_copyBusyLease, lease)),
              session: widget.session, value: supportingCopies ?? WorkspaceSupplierMoneyCopies(
                key: draft.key!, qa: widget.session.workspaceSupplierScope!.$3),
              editable: editable && !draft.busy && draft.error == null,
              saved: draft.pending == null && !draft.busy && draft.error == null,
              isCurrent: () => mounted && current, beforeChange: draft.flush,
              onBusy: (lease, active) {
                if (mounted && (active || identical(_copyBusyLease, lease))) {
                  setState(() => _copyBusyLease = active ? lease : null);
                }
              },
              onChanged: (value) async {
                if (!mounted || !current || frozen != null || !recovered) return false;
                setState(() => supportingCopies = value);
                draft.save(fields);
                return draft.flush();
              }),
            if (error != null || draft.error != null) Text(error ?? draft.error!, style: const TextStyle(color: Color(0xffa52a2a))),
            if (draft.error != null) TextButton(key: const Key('supplier-refund-retry-save'),
              onPressed: busy ? null : () => draft.save(fields), child: const Text('Retry saving input')),
            if (_originalRefund && _refundIntent != null && _refundStatus == null)
              TextButton(key: const Key('supplier-refund-retry-original'), onPressed: busy ? null : _retryOriginalRefund,
                child: const Text('Try this same request again')),
            if (_originalRefund && _refundStatus == 'not_saved')
              TextButton(key: const Key('supplier-refund-review-refused'), onPressed: busy ? null : _reviewRefusedRefund,
                child: const Text('Review saved details')),
            if (frozen != null || error != null || draft.error != null || !recovered || available == 0)
              TextButton(key: const Key('supplier-refund-recover'), onPressed: busy || draft.busy ? null : load,
              child: Text(frozen == null && available == 0 ? 'Refresh supplier account' : 'Recover saved refund')),
            FilledButton(key: const Key('supplier-refund-submit'), onPressed: !busy && !draft.busy && draft.ready && current && draft.error == null &&
              (frozen != null || recovered && (available ?? 0) > 0) ? submit : null,
              child: Text(busy ? 'Recording…' : confirmed ? 'Record another refund'
                : frozen == null ? 'Record refund received' : _originalRefund ? 'Check saved status' : 'Retry same refund')),
          ]))))));
  }
}

class _StorePaymentBillSelector extends StatefulWidget {
