  Widget _taxRowFields(int index, bool editable) {
    final row = taxRows[index];
    const labels = {'rate': 'GST rate (%)', 'taxable': 'Taxable value (₹)', 'cgst': 'CGST (₹)',
      'sgst': 'SGST / UTGST (₹)', 'igst': 'IGST (₹)', 'cess': 'Cess (₹)'};
    return Padding(padding: const EdgeInsets.only(top: 8), child: Column(
      key: ObjectKey(row), crossAxisAlignment: CrossAxisAlignment.stretch, children: [
      Row(children: [Expanded(child: Text('Rate ${index + 1}', style: const TextStyle(fontWeight: FontWeight.w600))),
        IconButton(key: ValueKey('supplier-credit-remove-tax-$index'), tooltip: 'Remove GST rate',
          onPressed: editable ? () {
            setState(() { taxRows.removeAt(index); });
            for (final controller in row.values) { controller.dispose(); }
            changed();
          } : null, icon: const Icon(Icons.close, size: 18))]),
      LayoutBuilder(builder: (context, constraints) {
        final paired = constraints.maxWidth >= 280 && MediaQuery.textScalerOf(context).scale(13) <= 18;
        final width = paired ? (constraints.maxWidth - 8) / 2 : constraints.maxWidth;
        return Wrap(spacing: 8, runSpacing: 8, children: [for (final field in row.entries)
          SizedBox(width: width, child: TextField(key: ValueKey('supplier-credit-tax-$index-${field.key}'),
            controller: field.value, enabled: editable, maxLength: 24,
            keyboardType: const TextInputType.numberWithOptions(decimal: true),
            style: const TextStyle(fontSize: 13), decoration: _creditInput(labels[field.key]).copyWith(counterText: ''),
            onChanged: (_) => changed()))]);
      }),
    ]));
  }
}

List<(WorkspaceSupplierMoneySourceKind, String, String, int)> _supplierAllocationSources(
  WorkspaceSupplierLedger? current, WorkspacePurchaseSavedCopy copy, {bool includeExhausted = false}) {
    if (current == null || !current.valid) return const [];
    final list = <(WorkspaceSupplierMoneySourceKind, String, String, int)>[];
    void add(WorkspaceSupplierMoneySourceKind kind, String id, String label) {
      final remaining = current.unallocatedMoneyMinor(kind, id);
      if (remaining != null && (remaining > 0 || includeExhausted)) {
        list.add((kind, id, label, remaining));
      }
    }
    final opening = current.openingRecord;
    if (opening?.supplierCredit == true) {
      add(WorkspaceSupplierMoneySourceKind.openingAdvance, opening!.id, 'Starting advance / credit');
    }
    for (final entry in current.entries.where((e) => e.origin == WorkspaceSupplierEntryOrigin.supplierAccount &&
      e.moneyReview != null && (e.kind == WorkspaceSupplierEntryKind.advance || e.kind == WorkspaceSupplierEntryKind.payment))) {
      add(entry.kind == WorkspaceSupplierEntryKind.advance ? WorkspaceSupplierMoneySourceKind.accountAdvance
        : WorkspaceSupplierMoneySourceKind.accountPayment, entry.operationId,
        '${entry.kind == WorkspaceSupplierEntryKind.advance ? 'Advance' : 'Account payment'} · ${entry.reference}'
        ' · ${entry.moneyReview!.occurredOn} · ${entry.paymentMethod ?? 'Method not recorded'}');
    }
    for (final bill in current.purchaseBills.values.where((b) => b.billId != copy.draft.id)) {
      add(WorkspaceSupplierMoneySourceKind.manualBillSurplus, bill.billId,
        'Bill credit · ${bill.copy.draft.invoiceReference} · ${bill.copy.draft.invoiceDate}');
    }
    return [for (var index = 0; index < list.length; index++)
      (list[index].$1, list[index].$2,
        list.where((source) => source.$3 == list[index].$3).length > 1
          ? '${list[index].$3} · Record ${index + 1}' : list[index].$3,
        list[index].$4)];
}

Future<void> _showSupplierAllocation(BuildContext context, WorkSession session,
    WorkspacePurchaseSavedCopy copy, {StoreSupplierAllocationInitialData? initialData,
    WorkspaceLedgerFormDraft? recoveryDraft,
    WorkspaceLedgerFormKey? prefillKey, String? prefillSignature,
    bool Function()? prefillCurrent, bool Function()? ownerCurrent, bool readOnlyOpen = false, StoreSupplierSelectedDocumentInput? selectedDocument}) async {
  final host = context.getInheritedWidgetOfExactType<MoolAssistantHost>();
  final workspace = context.getInheritedWidgetOfExactType<MoolAssistantWorkspaceScope>();
  final captured = host?.readContext().withWorkspace(workspace?.readWorkspace());
  bool allocationOwner() => context.mounted && ownerCurrent?.call() != false &&
    (host == null || captured?.signedIn == true &&
      host.readContext().withWorkspace(workspace?.readWorkspace()).binding == captured!.binding);
  if (session.workspaceOriginalSupplierAllocationConfigured) {
    final owner = session.workspaceSupplierScope, publication = session.publicationPreferencesContext;
    if (!readOnlyOpen) await session.loadWorkspaceOriginalLedger();
    if (!allocationOwner() || owner != session.workspaceSupplierScope ||
        publication != session.publicationPreferencesContext || !session.hasVerifiedWorkspace) return;
  }
  if (!allocationOwner()) return;
  await showModalBottomSheet<void>(context: context,
      isScrollControlled: true, useSafeArea: true, isDismissible: false, enableDrag: false,
      builder: (sheetContext) => _supplierCapturedOwnerSheet(
        context, sheetContext, session, allocationOwner, _StoreSupplierAllocationSheet(session: session, copy: copy,
        initialData: initialData, recoveryDraft: recoveryDraft,
        prefillKey: prefillKey, prefillSignature: prefillSignature,
        prefillCurrent: prefillCurrent, ownerCurrent: allocationOwner, readOnlyOpen: readOnlyOpen, selectedDocument: selectedDocument)));
}

class _StoreSupplierAllocationSheet extends StatefulWidget {
  const _StoreSupplierAllocationSheet({required this.session, required this.copy,
    this.initialData, this.recoveryDraft, this.prefillKey, this.prefillSignature, this.prefillCurrent, this.ownerCurrent, this.readOnlyOpen = false, this.selectedDocument});
  final StoreSupplierAllocationInitialData? initialData;
  final WorkspaceLedgerFormDraft? recoveryDraft;
  final WorkspaceLedgerFormKey? prefillKey;
  final String? prefillSignature;
  final bool Function()? prefillCurrent, ownerCurrent;
  final bool readOnlyOpen;
  final StoreSupplierSelectedDocumentInput? selectedDocument;
  final WorkSession session;
  final WorkspacePurchaseSavedCopy copy;
  @override
  State<_StoreSupplierAllocationSheet> createState() => _StoreSupplierAllocationSheetState();
}

class _StoreSupplierAllocationSheetState extends State<_StoreSupplierAllocationSheet> {
  final Object _nativeAllocationToken = Object();
  late final WorkSession _nativeAllocationOwner;
  bool _initialAttempted = false;
  bool _recoveryReadChecked = false;
  bool get _ownerCurrent => widget.ownerCurrent?.call() != false;
  bool get _sourceCurrent => widget.initialData == null ||
    _assistantSupplierAllocationSignature(widget.session, widget.copy, null) == widget.prefillSignature;
  late final _LedgerFormAutosave draft;
  final amount = TextEditingController();
  final amountFocus = FocusNode();
  WorkspaceSupplierMoneySourceKind? sourceKind;
  String sourceId = '';
  WorkspaceSupplierMoneyAllocationIntent? frozen;
  late final bool _originalAllocation;
  WorkspaceLedgerIntent? _allocationIntent;
  String? _allocationStatus;
  WorkspaceLedgerFormDraft? resetAttempt;
  WorkspaceSupplierMoneyCopies? supportingCopies;
  bool _busy = false, recovered = false, confirmed = false, conflict = false;
  Object? _copyBusyLease;
  bool get busy => _busy || _copyBusyLease != null;
  String? error;
  WorkspaceSupplierLedger? get ledger => widget.session.workspaceSupplierLedger(widget.copy.supplier.id);
  List<(WorkspaceSupplierMoneySourceKind, String, String, int)> get sources =>
    _supplierAllocationSources(ledger, widget.copy, includeExhausted: frozen != null);
  String sourceValue(WorkspaceSupplierMoneySourceKind kind, String id) => jsonEncode([kind.name, id]);
  Map<String, String> get fields => {'amount': amount.text, 'sourceKind': sourceKind?.name ?? '',
    'sourceId': sourceId, if (frozen != null) 'attempt': jsonEncode(frozen!.intentToJson()),
    if (supportingCopies != null) 'supportingCopies': jsonEncode(supportingCopies!.toJson())};

  @override
  void initState() {
    super.initState();
    _nativeAllocationOwner = widget.session;
    _originalAllocation = widget.session.workspaceOriginalSupplierAllocationConfigured;
    if (_originalAllocation) widget.session.addListener(refresh);
    (_openSupplierMoneyForms[_nativeAllocationOwner] ??= <Object>{}).add(_nativeAllocationToken);
    draft = _LedgerFormAutosave(widget.session, widget.recoveryDraft?.key ?? widget.session.supplierAllocationFormKey(widget.copy),
      inputOwnerCurrent: () => _ownerCurrent && _allocationIntent == null);
    draft.addListener(refresh);
    amountFocus.addListener(refresh);
    unawaited(load(readOnlyOpen: widget.readOnlyOpen));
  }
  void refresh() { if (mounted) setState(() {}); }
  void inspect() {
    if (_originalAllocation) {
      confirmed = _allocationIntent != null && _allocationStatus == 'saved'; return;
    }
    confirmed = false;
    if (frozen == null || !recovered) return;
    final saved = ledger?.billMoneyAllocations[frozen!.operationId];
    if (saved != null) {
      confirmed = workspaceLedgerCanonical(saved.intentToJson()) == workspaceLedgerCanonical(frozen!.intentToJson());
      if (!confirmed) { conflict = true; error = 'Recorded allocation differs. Keep this request for review.'; }
    }
  }
  Future<void> recordMoney(bool advance) async {
    final session = widget.session;
    if (!_ownerCurrent || busy || conflict || frozen != null || !draft.ready || !recovered ||
        session.supplierAllocationFormKey(widget.copy) != draft.key) { return; }
    setState(() => _busy = true);
    try {
      if (!await draft.flush() || !mounted || !_ownerCurrent ||
          session.supplierAllocationFormKey(widget.copy) != draft.key) { return; }
      await _showSupplierMoneyEntry(context, session,
        _StoreSupplierMoneyTarget(supplierId: widget.copy.supplier.id, advance: advance),
        ownerCurrent: widget.ownerCurrent);
    } finally { if (mounted) setState(() => _busy = false); }
    if (mounted && session.supplierAllocationFormKey(widget.copy) == draft.key) {
      await load();
    } else if (mounted) {
      setState(() { conflict = true; error = 'Return to the original Store to recover this allocation.'; });
    }
  }
  Future<void> load({bool readOnlyOpen = false}) async {
    if (!_ownerCurrent || busy || draft.busy) return;
    final pristineAtStart = amount.text.isEmpty && sourceKind == null && sourceId.isEmpty &&
      draft.revision == null && draft.pending == null && draft.error == null &&
      frozen == null && supportingCopies == null && resetAttempt == null && !confirmed && !conflict;
    setState(() => _busy = true);
    try {
      var pendingConflict = false;
      if (draft.pending != null) {
        draft.save(conflict ? draft.pending!.fields : fields);
        pendingConflict = !await draft.flush();
      }
      if (!mounted || !_ownerCurrent || draft.key == null) return;
      recovered = readOnlyOpen ? await widget.session.inspectWorkspaceSupplierAllocationCheckpoint(draft.key!)
        : await widget.session.recoverWorkspaceSupplierAllocationStatus(draft.key!);
      if (!mounted || !_ownerCurrent) return;
      final saved = await draft.load();
      if (!mounted || !_ownerCurrent || saved == null) return;
      final expected = widget.recoveryDraft;
      if (expected != null && !_recoveryReadChecked) {
        if (draft.key != expected.key || draft.revision != expected.revision ||
            !mapEquals(saved, expected.fields)) {
          throw StateError('Original saved allocation changed before restoration');
        }
        _recoveryReadChecked = true;
      }
      final copies = WorkspaceLedgerFormDraft(key: draft.key!, revision: draft.revision ?? 1,
        fields: saved).supplierAllocationCopies;
      if (copies != null && copies.qa != widget.session.workspaceSupplierScope?.$3) {
        throw const FormatException('Saved allocation copies belong to another Store mode');
      }
      supportingCopies = copies;
      amount.text = saved['amount'] ?? '';
      sourceKind = WorkspaceSupplierMoneySourceKind.values.where((k) => k.name == saved['sourceKind']).firstOrNull;
      sourceId = saved['sourceId'] ?? '';
      final text = saved['attempt'];
      frozen = text == null || text.isEmpty ? null : WorkspaceSupplierMoneyAllocationIntent.fromJson(jsonDecode(text));
      conflict = false; error = null; resetAttempt = null;
      if (pendingConflict && draft.pending != null) {
        if (jsonEncode(draft.pending!.fields) == jsonEncode(saved)) {
          draft.pending = null;
        } else {
          conflict = true;
          draft.error = 'Saved allocation differs from unsaved input. Both versions are kept; retry recovery before continuing.';
          error = draft.error;
        }
      }
      if (_originalAllocation && frozen != null) {
        final retained = await widget.session.readWorkspaceOriginalSupplierAllocationRequest(draft.key!, frozen!);
        if (!mounted || !_ownerCurrent) return;
        if (_allocationIntent != null && (retained?.fingerprint != _allocationIntent!.fingerprint ||
            retained?.idempotencyKey != _allocationIntent!.idempotencyKey)) {
          conflict = true; error = 'Keep the original allocation request and its saved input.'; return;
        }
        _allocationIntent = retained;
        if (retained == null && ledger?.billMoneyAllocations.containsKey(frozen!.operationId) == true) {
          conflict = true; error = 'Keep this allocation and its original request. Its saved identity could not be recovered.'; return;
        }
        if (retained != null) await _resolveOriginalAllocation();
        if (!mounted || !_ownerCurrent) return;
      }
      inspect();
      final initial = widget.initialData;
      if (initial != null && !_initialAttempted) {
        _initialAttempted = true;
        final pristine = pristineAtStart && saved.isEmpty && draft.revision == null &&
          draft.pending == null && draft.error == null && !pendingConflict &&
          frozen == null && supportingCopies == null && resetAttempt == null && !confirmed && !conflict;
        if (!pristine || !recovered || !_ownerCurrent || !_sourceCurrent ||
            widget.prefillCurrent?.call() == false || widget.prefillKey != draft.key ||
            !initial.matches(widget.session, widget.copy)) {
          error = 'Suggestion was not applied. Existing allocation input and saved attempts are kept.';
        } else {
          // No autosave callback, flush or posting on Review.
          amount.text = initial.amount;
          sourceKind = initial.sourceKind;
          sourceId = initial.sourceId;
        }
      }
    } on Object {
      if (mounted) setState(() { conflict = true; error = 'Saved allocation could not be read. Keep the request and retry recovery.'; });
    } finally { if (mounted) setState(() => _busy = false); }
  }
  Future<void> submit() async {
    if (!_ownerCurrent || busy || conflict || !draft.ready || draft.key == null ||
        _allocationIntent == null && !recovered) return;
    if (frozen == null && !_sourceCurrent) {
      setState(() => error = 'Allocation source changed. Close and reopen this bill before applying.');
      return;
    }
    setState(() { _busy = true; error = null; });
    try {
      if (!await draft.flush() || !mounted || !_ownerCurrent || frozen == null && !_sourceCurrent) return;
      if (confirmed) {
        resetAttempt ??= WorkspaceLedgerFormDraft(key: draft.key!, revision: draft.revision! + 1,
          fields: {'amount': '', 'sourceKind': '', 'sourceId': '',
            if (supportingCopies != null) 'supportingCopies': jsonEncode(supportingCopies!.archiveAllocation(frozen!).toJson())});
        if (await widget.session.resetConfirmedWorkspaceSupplierAllocationDraft(resetAttempt!, expectedRevision: draft.revision!,
            original: _allocationIntent, ownerCurrent: () => mounted && _ownerCurrent) && mounted && _ownerCurrent) {
          draft.revision = resetAttempt!.revision; draft.pending = null; draft.error = null;
          supportingCopies = resetAttempt!.supplierAllocationCopies;
          amount.clear(); sourceKind = null; sourceId = ''; frozen = null; confirmed = false; resetAttempt = null;
          _allocationIntent = null; _allocationStatus = null;
        } else { error = 'Recorded allocation is kept. Retry before starting another.'; }
        return;
      }
      if (_originalAllocation && _allocationIntent != null) {
        await _resolveOriginalAllocation(); return;
      }
      final current = ledger;
      if (frozen == null) {
        final minor = WorkspacePurchaseEntryDraft.printedPaise(amount.text);
        final available = sourceKind == null ? null : current?.unallocatedMoneyMinor(sourceKind!, sourceId);
        final billDue = current?.manualBillRemainingMinor(widget.copy.draft.id);
        if (minor == null || minor <= 0 || available == null || billDue == null ||
            minor > available || minor > billDue || current?.openingRecord == null) {
          error = 'Choose an advance, payment or bill credit and an amount within its available balance and this bill’s due.';
          return;
        }
        final key = draft.key!;
        frozen = WorkspaceSupplierMoneyAllocationIntent(operationId: widget.session.newWorkspaceSupplierMoneyAllocationId(),
          accountScope: key.account, workspaceId: key.store, supplierId: key.customer,
          sourceKind: sourceKind!, sourceId: sourceId, openingId: current!.openingRecord!.id,
          openingRevision: current.openingRecord!.revision, billId: widget.copy.draft.id,
          copyId: widget.copy.id, copyRevision: widget.copy.revision, amountMinor: minor,
          requestedAt: DateTime.now().toUtc(),
          sourceCopyId: sourceKind == WorkspaceSupplierMoneySourceKind.manualBillSurplus
            ? current.purchaseBills[sourceId]?.copy.id : null,
          sourceCopyRevision: sourceKind == WorkspaceSupplierMoneySourceKind.manualBillSurplus
            ? current.purchaseBills[sourceId]?.copy.revision : null);
        draft.save(fields);
        if (!await draft.flush() || !mounted) { error = 'Request is not submitted. Save and retry this same request.'; return; }
      }
      if (!_ownerCurrent) return;
      if (_originalAllocation) {
        _allocationIntent = widget.session.prepareWorkspaceOriginalSupplierAllocation(draft.key!, frozen!);
        if (_allocationIntent == null) {error = 'Allocation records changed. Keep this input and refresh the original records.'; return;}
        await _resolveOriginalAllocation(firstSave: true); return;
      }
      final saved = await widget.session.recordWorkspaceSupplierAllocationDraft(draft.key!, frozen!);
      if (!mounted) return;
      recovered = await widget.session.recoverWorkspaceSupplierAllocationStatus(draft.key!);
      inspect();
      final remainingSource = ledger?.unallocatedMoneyMinor(frozen!.sourceKind, frozen!.sourceId);
      final remainingBill = ledger?.manualBillRemainingMinor(widget.copy.draft.id);
      final capacityChanged = recovered && !confirmed && remainingSource != null && remainingBill != null &&
        (remainingSource < frozen!.amountMinor || remainingBill < frozen!.amountMinor);
      error = saved && confirmed ? null : capacityChanged
        ? 'This request cannot be linked: the available money or bill due has changed. The request is retained for review.'
        : 'Allocation status needs recovery. Keep and retry this request, not a new one.';
    } finally { if (mounted) setState(() => _busy = false); }
  }
  Future<void> _resolveOriginalAllocation({bool firstSave = false, bool explicitRetry = false}) async {
    final original = _allocationIntent, input = frozen, key = draft.key;
    if (original == null || input == null || key == null || !_ownerCurrent) return;
    final result = firstSave
      ? await widget.session.recordWorkspaceOriginalSupplierAllocation(original, key: key, intent: input,
          ownerCurrent: () => mounted && _ownerCurrent)
      : await widget.session.checkWorkspaceOriginalSupplierAllocationRequest(original, key: key, intent: input,
          explicitRetry: explicitRetry, ownerCurrent: () => mounted && _ownerCurrent);
    if (!mounted || !_ownerCurrent) return;
    _allocationStatus = result?.attempt?['status'] as String?;
    confirmed = _allocationStatus == 'saved';
    recovered = widget.session.workspaceOriginalLedgerSections != null;
    error = confirmed ? null : widget.session.workspaceOriginalLedgerError ??
      'Allocation status is unconfirmed. Keep this request and check again.';
  }
  Future<void> _retryOriginalAllocation() async {
    if (busy || !_ownerCurrent || _allocationIntent == null || _allocationStatus != null) return;
    setState(() {_busy = true; error = null;});
    try {await _resolveOriginalAllocation(explicitRetry: true);}
    finally {if (mounted) setState(() => _busy = false);}
  }
  Future<void> _reviewRefusedAllocation() async {
    if (busy || !_ownerCurrent || _allocationStatus != 'not_saved' || draft.key == null || draft.revision == null) return;
    setState(() {_busy = true; error = null;});
    try {
      final retained = {...fields}..remove('attempt');
      final next = WorkspaceLedgerFormDraft(key: draft.key!, revision: draft.revision! + 1, fields: retained);
      final reset = await widget.session.resetRefusedWorkspaceSupplierAllocationDraft(next,
        expectedRevision: draft.revision!, ownerCurrent: () => mounted && _ownerCurrent);
      if (!mounted || !_ownerCurrent) return;
      if (!reset) {error = 'Check this exact allocation status before reviewing the saved details.'; return;}
      draft.revision = next.revision; draft.pending = null; draft.error = null;
      frozen = null; _allocationIntent = null; _allocationStatus = null; confirmed = false;
      recovered = widget.session.workspaceOriginalLedgerSections != null;
    } finally {if (mounted) setState(() => _busy = false);}
  }
  @override
  void dispose() {
    if (_originalAllocation) widget.session.removeListener(refresh);
    _openSupplierMoneyForms[_nativeAllocationOwner]?.remove(_nativeAllocationToken);
    draft.removeListener(refresh); draft.dispose(); amount.dispose();
    amountFocus.removeListener(refresh); amountFocus.dispose(); super.dispose();
  }
  Widget _allocationViewport(BuildContext context, Widget body) => SafeArea(top: false,
    child: Padding(padding: EdgeInsets.only(bottom: MediaQuery.viewInsetsOf(context).bottom),
      child: LayoutBuilder(builder: (context, constraints) => ConstrainedBox(
        constraints: BoxConstraints(maxHeight: constraints.maxHeight),
        child: Column(mainAxisSize: MainAxisSize.min, children: [
          Padding(padding: const EdgeInsets.fromLTRB(16, 8, 8, 0), child: Row(children: [
            const Expanded(child: Text('Apply payment or credit to bill',
              style: TextStyle(fontSize: 14, fontWeight: FontWeight.w700, color: MoolColors.navy))),
            if (amountFocus.hasFocus || MediaQuery.viewInsetsOf(context).bottom > 0)
              IconButton(key: const Key('supplier-allocation-hide-keyboard'), tooltip: 'Hide keyboard',
                onPressed: () => FocusScope.of(context).unfocus(), icon: const Icon(Icons.keyboard_hide_outlined)),
            TextButton(key: const Key('supplier-allocation-close'),
              style: TextButton.styleFrom(textStyle: const TextStyle(fontSize: 12)),
              onPressed: busy || conflict ? null : () async {
                if (await draft.flush() && context.mounted) Navigator.pop(context);
              }, child: const Text('Close')),
          ])),
          Flexible(child: NotificationListener<ScrollNotification>(
            onNotification: (notification) {
              if (notification.depth == 0 &&
                  (notification is ScrollStartNotification || notification is ScrollUpdateNotification)) {
                final editor = FocusManager.instance.primaryFocus?.context
                    ?.findAncestorStateOfType<EditableTextState>();
                if (editor?.context.findAncestorStateOfType<_StoreSupplierAllocationSheetState>() == this) {
                  editor?.hideToolbar();
                }
              }
              return false;
            }, child: body)),
        ]),
      ))));
  @override
  Widget build(BuildContext context) {
    final list = sources;
    final accountReady = recovered && widget.session.supplierAllocationFormKey(widget.copy) == draft.key;
    final billDue = accountReady ? ledger?.manualBillRemainingMinor(widget.copy.draft.id) : null;
    final settled = accountReady && billDue != null && billDue <= 0 && frozen == null;
    final emptySources = accountReady && list.isEmpty && frozen == null;
    final selected = sourceKind == null ? null : sourceValue(sourceKind!, sourceId);
    final selectionKnown = list.any((s) => sourceValue(s.$1, s.$2) == selected);
    final selectedSource = list.where((s) => sourceValue(s.$1, s.$2) == selected).firstOrNull;
    final savedVerified = draft.pending == null && draft.error == null && draft.revision != null && !draft.busy;
    final editable = draft.ready && accountReady && !busy && !conflict && frozen == null;
    return PopScope(canPop: !busy && !draft.busy && draft.pending == null && draft.error == null && !conflict,
      onPopInvokedWithResult: (didPop, result) async {
        if (!didPop && !busy && !conflict && await draft.flush() && context.mounted) Navigator.pop(context);
      }, child: _allocationViewport(context, SingleChildScrollView(
        padding: const EdgeInsets.fromLTRB(16, 8, 16, 16),
        child: Theme(data: Theme.of(context).copyWith(textButtonTheme: TextButtonThemeData(
          style: TextButton.styleFrom(minimumSize: const Size(48, 48), textStyle: const TextStyle(fontSize: 12)))),
        child: DefaultTextStyle.merge(style: const TextStyle(fontSize: 12, color: MoolColors.ink),
        child: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.stretch, children: [
          Text(widget.copy.supplier.name, key: const Key('supplier-allocation-supplier'),
            style: const TextStyle(fontSize: 13, fontWeight: FontWeight.w600)),
          Text('Bill ${widget.copy.draft.invoiceReference}', key: const Key('supplier-allocation-bill')),
          const SizedBox(height: 6),
          const Text('Apply a recorded payment, advance or credit to this bill.',
            key: Key('supplier-allocation-purpose-guide')),
          const SizedBox(height: 6),
          Text(billDue == null ? 'Bill due unavailable' : billDue < 0
            ? 'Credit with supplier ${_purchaseAmount(-billDue)}' : 'Bill due ${_purchaseAmount(billDue)}',
            style: const TextStyle(fontWeight: FontWeight.w600)),
          if (settled) const Text('No amount remains to link to this bill. Your recorded payments and allocations are kept.',
            key: Key('supplier-allocation-settled')),
          if (!settled && list.isEmpty && accountReady && frozen == null) ...[
            const SizedBox(height: 6),
            const Text('No unallocated payment, advance or bill credit is available. If you have already paid and it is not recorded, record that payment or advance first.'),
            if (billDue != null && billDue > 0) Wrap(spacing: 8, children: [
              TextButton(key: const Key('supplier-allocation-record-payment'),
                onPressed: editable ? () => recordMoney(false) : null, child: const Text('Record payment')),
              TextButton(key: const Key('supplier-allocation-record-advance'),
                onPressed: editable ? () => recordMoney(true) : null, child: const Text('Record advance')),
            ]),
          ],
          if (!settled && !emptySources) ...[
          const SizedBox(height: 12),
          DropdownButtonFormField<String>(key: ValueKey(('supplier-allocation-source', selected)),
            initialValue: selectionKnown ? selected : null, isExpanded: true,
            style: const TextStyle(fontSize: 13, color: MoolColors.navy),
            decoration: const InputDecoration(labelText: 'Advance, payment or bill credit', isDense: true,
              constraints: BoxConstraints(minHeight: 48), labelStyle: TextStyle(fontSize: 12),
              contentPadding: EdgeInsets.symmetric(horizontal: 12, vertical: 14)),
            items: [for (final s in list) DropdownMenuItem(value: sourceValue(s.$1, s.$2),
              child: Text('${s.$3} · Unassigned ${_purchaseAmount(s.$4)}', overflow: TextOverflow.ellipsis))],
            onChanged: editable ? (value) {
              if (value == null) return;
              final source = list.singleWhere((s) => sourceValue(s.$1, s.$2) == value);
              setState(() { sourceKind = source.$1; sourceId = source.$2; }); draft.save(fields);
            } : null),
          if (selectedSource != null) Text('${selectedSource.$3} · Unassigned ${_purchaseAmount(selectedSource.$4)}',
            key: const Key('supplier-allocation-selected-source')),
          const SizedBox(height: 12),
          Align(alignment: Alignment.centerLeft, child: SizedBox(width: 180, child: TextField(
            key: const Key('supplier-allocation-amount'), controller: amount, enabled: editable, focusNode: amountFocus,
            style: const TextStyle(fontSize: 13),
            keyboardType: const TextInputType.numberWithOptions(decimal: true),
            decoration: const InputDecoration(labelText: 'Apply amount (₹)', isDense: true, floatingLabelBehavior: FloatingLabelBehavior.always,
              constraints: BoxConstraints(minHeight: 48), labelStyle: TextStyle(fontSize: 12),
              contentPadding: EdgeInsets.symmetric(horizontal: 12, vertical: 14)), onChanged: (_) => draft.save(fields)))),
          ],
          if (frozen != null) Text(confirmed ? 'Allocation recorded · ${_purchaseAmount(frozen!.amountMinor)}'
            : savedVerified ? 'Saved allocation request · recover and retry the same details.'
            : 'Saved status unverified · keep this request and retry saving.', key: const Key('supplier-allocation-status')),
          if (draft.ready && accountReady && !conflict && widget.session.workspaceSupplierScope != null &&
              ((frozen == null && !settled) || supportingCopies?.active.isNotEmpty == true ||
                supportingCopies?.previous.isNotEmpty == true)) _SupplierPaymentDraftCopies(
            sourceRevision: () => jsonEncode([draft.revision, fields]),
              selectedDocument: widget.selectedDocument,
              canStageSelected: (lease) => draft.ready && accountReady && _ownerCurrent && !_busy && !conflict && frozen == null && !settled && !draft.busy && draft.error == null &&
                (_copyBusyLease == null || identical(_copyBusyLease, lease)),
            session: widget.session, value: supportingCopies ?? WorkspaceSupplierMoneyCopies(
              key: draft.key!, qa: widget.session.workspaceSupplierScope!.$3),
            editable: editable && !settled && !draft.busy && draft.error == null,
            saved: draft.pending == null && !draft.busy && draft.error == null,
            isCurrent: () => mounted && _ownerCurrent && widget.session.supplierAllocationFormKey(widget.copy) == draft.key,
            beforeChange: draft.flush,
            onBusy: (lease, active) {
              if (mounted && (active || identical(_copyBusyLease, lease))) {
                setState(() => _copyBusyLease = active ? lease : null);
              }
            },
            onChanged: (value) async {
              if (!mounted || !_ownerCurrent || widget.session.supplierAllocationFormKey(widget.copy) != draft.key ||
                  frozen != null || conflict) { return false; }
              setState(() => supportingCopies = value);
              draft.save(fields);
              return draft.flush();
            }),
          if (error != null || draft.error != null) Text(error ?? draft.error!, style: const TextStyle(color: Color(0xffa52a2a))),
          if (draft.error != null) TextButton(key: const Key('supplier-allocation-retry-save'),
            onPressed: busy || conflict ? null : () => draft.save(fields), child: const Text('Retry saving input')),
          if (_originalAllocation && _allocationIntent != null && _allocationStatus == null)
            TextButton(key: const Key('supplier-allocation-retry-original'), onPressed: busy ? null : _retryOriginalAllocation,
              child: const Text('Retry same allocation')),
          if (_originalAllocation && _allocationStatus == 'not_saved')
            TextButton(key: const Key('supplier-allocation-review-refused'), onPressed: busy ? null : _reviewRefusedAllocation,
              child: const Text('Review allocation details')),
          TextButton(key: const Key('supplier-allocation-recover'), onPressed: busy || draft.busy ? null : load,
            child: Text(frozen != null && !confirmed ? 'Check saved allocation' : 'Refresh payments & credits')),
          if (!settled && !emptySources) FilledButton(key: const Key('supplier-allocation-submit'),
            onPressed: draft.ready && (accountReady || _allocationIntent != null) && _allocationStatus != 'not_saved' &&
              !busy && !conflict && !draft.busy && draft.error == null ? submit : null,
            child: Text(busy ? 'Recording…' : confirmed ? 'Link another amount'
              : frozen == null ? 'Apply selected amount' : _allocationIntent != null ? 'Check saved allocation' : 'Retry same allocation')),
        ]))))));
  }
}

class _SupplierPaymentDraftCopies extends StatefulWidget {
  const _SupplierPaymentDraftCopies({required this.session, required this.value,
    required this.editable, required this.saved, required this.isCurrent, required this.beforeChange,
    required this.onBusy, required this.onChanged, required this.sourceRevision, required this.canStageSelected, this.selectedDocument});
  final WorkSession session;
  final WorkspaceSupplierMoneyCopies value;
  final String Function() sourceRevision;
  final StoreSupplierSelectedDocumentInput? selectedDocument;
  final bool Function(Object lease) canStageSelected;
  final bool editable, saved;
  final bool Function() isCurrent;
  final Future<bool> Function() beforeChange;
  final void Function(Object, bool) onBusy;
  final Future<bool> Function(WorkspaceSupplierMoneyCopies) onChanged;
  @override
  State<_SupplierPaymentDraftCopies> createState() => _SupplierPaymentDraftCopiesState();
}

class _SupplierPaymentDraftCopiesState extends State<_SupplierPaymentDraftCopies> {
  late final _scope = widget.session.workspaceSupplierScope!;
  late final _navigation = widget.session.navigationScopeRevision;
  bool _busy = false;
  final Object _busyLease = Object();
  late String _type;
  String? _error;
  String? _unsavedValue;
  bool get _selectedReady => _editable && widget.saved && _unsavedValue == null;
  final _selectionChanges = ValueNotifier<int>(0);
  bool _selectedStarted = false, _selectedScheduled = false;
  bool _selectionDisposed = false;
  String? _lastSelectedSource;
  ModalRoute<dynamic>? _selectedOwnerRoute;
  NavigatorState? _selectedNavigator;
  bool get _selectedAllowed => !_selectionDisposed && _current && widget.canStageSelected(_busyLease);
  String get _selectedSource => assistant_hash.sha256.convert(utf8.encode(jsonEncode([widget.sourceRevision(), widget.value.toJson(), _type]))).toString();
  bool get _credit => widget.value.key.kind == 'supplierCredit';
  bool get _refund => widget.value.key.kind == 'supplierRefund';
  bool get _allocation => widget.value.key.kind == 'supplierAllocation';
  String get _prefix => _allocation ? 'supplier-allocation' : _refund ? 'supplier-refund' : _credit ? 'supplier-credit' : 'supplier-payment';
  String get _inputName => _allocation ? 'allocation' : _refund ? 'refund' : _credit ? 'credit-note' : 'payment';
  String get _unsavedWarning => 'Copy details are not saved yet. Retry saving the $_inputName input before leaving.';
  bool get _current => mounted && widget.isCurrent() &&
    widget.session.workspaceSupplierScope == _scope &&
    widget.session.navigationScopeRevision == _navigation;
  bool get _editable => _current && widget.editable && !_busy;
  @override
  void initState() {
    super.initState();
    _type = _allocation ? 'paymentAdvice' : _credit ? 'supplierCreditNote' : 'paymentReceipt';
    widget.session.addListener(_scopeChanged);
  }
  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    _selectedOwnerRoute = ModalRoute.of(context);
    _selectedNavigator = Navigator.of(context, rootNavigator: true);
    _queueSelectedOriginal();
  }
  @override
  void didUpdateWidget(_SupplierPaymentDraftCopies oldWidget) {
    super.didUpdateWidget(oldWidget);
    _queueSelectedOriginal();
    final next = _selectedSource;
    if (_lastSelectedSource != next) {
      _lastSelectedSource = next;
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted && !_selectionDisposed) _selectionChanges.value++;
      });
    }
    if (_unsavedValue != null && widget.saved &&
        jsonEncode(widget.value.toJson()) == _unsavedValue) {
      _unsavedValue = null;
      if (_error == _unsavedWarning) { _error = null; }
    }
  }
  void _scopeChanged() {
    if (!mounted) return;
    if (!_current && _busy) { widget.onBusy(_busyLease, false); }
    setState(() {});
  }
  bool _fits(WorkspacePurchaseInvoiceAttachment value) => widget.value.withActive([
    for (final old in widget.value.active) if (old.digest == value.digest) value else old,
  ]).valid;
  Future<void> _run(Future<void> Function() action, {bool mutate = false}) async {
    if (!_current || _busy || (mutate && !_editable)) return;
    setState(() { _busy = true; _error = null; });
    widget.onBusy(_busyLease, true);
    try {
      if (mutate && !await widget.beforeChange()) {
        if (_current) setState(() => _error = 'Save the current $_inputName input before attaching or editing a copy.');
        return;
      }
      if (_current) await action();
    } on Object catch (error) {
        if (_current) { setState(() => _error = error is WorkGatewayException ? error.message :
        'Copy could not be opened or saved. Your earlier copies and $_inputName input are kept.'); }
    } finally {
      widget.onBusy(_busyLease, false);
      if (mounted) { setState(() => _busy = false); }
    }
  }
  @override
  void dispose() {
    _selectionDisposed = true;
    WidgetsBinding.instance.addPostFrameCallback((_) { _selectionChanges.value++; _selectionChanges.dispose(); });
    widget.session.removeListener(_scopeChanged);
    final release = widget.onBusy;
    final lease = _busyLease;
    WidgetsBinding.instance.addPostFrameCallback((_) => release(lease, false));
    super.dispose();
  }
  Future<void> _keep(WorkspaceSupplierMoneyCopies value) async {
    if (!_current) return;
    if (!value.valid) {
      setState(() => _error = 'The draft-copy limit has been reached. Earlier copies are kept; use smaller copies.');
      return;
    }
    final saved = await widget.onChanged(value);
    if (_current && !saved) {
      setState(() {
        _unsavedValue = jsonEncode(value.toJson());
        _error = _unsavedWarning;
      });
    }
  }
  void _queueSelectedOriginal() {
    if(_selectedStarted||_selectedScheduled||widget.selectedDocument==null)return;
    _selectedScheduled=true;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      _selectedScheduled=false;
      final input=widget.selectedDocument;
      if(!mounted||_selectedStarted||input==null||!_selectedReady||!input.current())return;
      _selectedStarted=true;
      unawaited(_stageSupportingCopyInput(this,input));
    });
  }
  Future<MoolAssistantReviewResult> _addSelectedOriginal(MoolAssistantSelectedDocument selected,
      bool Function() current, Listenable ownerChanges, NavigatorState navigator,
      void Function(Route<WorkspacePurchaseInvoiceAttachment>) bindReview,
      void Function(Route<void>) bindOriginal) async {
    if (!mounted || !navigator.mounted || !current() || !_selectedReady) return MoolAssistantReviewResult.stale;
    if (widget.value.active.any((copy) => copy.digest == selected.sourceDigest)) return MoolAssistantReviewResult.unavailable;
    final baseline = _selectedSource;
    bool ready() => mounted && navigator.mounted && current() && _selectedAllowed && _selectedSource == baseline;
    var result = MoolAssistantReviewResult.unavailable;
    await _run(() async {
      final retained = await widget.session.workspacePurchaseInvoiceCapture.retainSelectedForDraft(
        _scope, widget.value.captureId, selected.proof, source: selected.reference.source,
        canRetain: (candidate) => ready() && candidate.digest == selected.sourceDigest &&
          !widget.value.active.any((copy) => copy.digest == candidate.digest) &&
          widget.value.withActive([...widget.value.active,
            candidate.withDocumentDetails({if (_type.isNotEmpty) 'type': _type})]).valid);
      if (!ready()) { result = MoolAssistantReviewResult.stale; return; }
      final candidate = retained.withDocumentDetails({if (_type.isNotEmpty) 'type': _type});
      // Retention is private-file IO only. No draft save, scan or financial
      // effect occurs before this original native Add copy control.
      late final MaterialPageRoute<WorkspacePurchaseInvoiceAttachment> route;
      route = MaterialPageRoute<WorkspacePurchaseInvoiceAttachment>(builder: (_) =>
        _ReceivingOwnerSurface(current: ready, changes: ownerChanges,
          retiredMessage: 'This supporting-copy review is no longer available.',
          child: _ReceivingScannedFieldsScreen(session: widget.session, scope: _scope,
          captureId: widget.value.captureId, attachment: candidate, readOnly: false,
          isCurrent: () => ready() && route.isActive, canKeep: (value) => ready() && widget.value.withActive([...widget.value.active, value]).valid,
          copyDescription: 'supporting copy', limitDescription: 'draft',
          title: 'Add supporting copy', saveLabel: 'Add copy', ownerChanges: ownerChanges, capturedRoute: route,
          onOriginalRoute: bindOriginal, beforeKeep: (value) async {
            if (!ready() || value.digest != candidate.digest) return false;
            try { await widget.session.workspacePurchaseInvoiceCapture.read(_scope, widget.value.captureId, candidate); }
            on Object { return false; }
            return ready();
          })));
      bindReview(route);
      final accepted = await navigator.push(route);
      if (!ready()) { result = MoolAssistantReviewResult.stale; return; }
      if (accepted == null) { result = MoolAssistantReviewResult.cancelled; return; }
      if (accepted.digest != candidate.digest || !widget.value.withActive([...widget.value.active, accepted]).valid) return;
      await _keep(widget.value.withActive([...widget.value.active, accepted]));
      result = _current && _unsavedValue == null ? MoolAssistantReviewResult.opened : MoolAssistantReviewResult.unavailable;
    });
    return result;
  }
  Future<void> _capture(WorkProofSource source) => _run(() async {
    final value = await widget.session.workspacePurchaseInvoiceCapture.captureForDraft(_scope, widget.value.captureId, source,
      canRetain: (candidate) => _current && (widget.value.active.any((a) =>
        a.digest == candidate.digest && a.byteLength == candidate.byteLength && a.contentType == candidate.contentType) ||
        widget.value.withActive([...widget.value.active,
          candidate.withDocumentDetails({if (_type.isNotEmpty) 'type': _type})]).valid));
    if (!_current || value == null) return;
    if (widget.value.active.any((a) => a.digest == value.digest)) {
      setState(() => _error = 'This copy is already in the current draft.'); return;
    }
    await _keep(widget.value.withActive([...widget.value.active,
      value.withDocumentDetails({if (_type.isNotEmpty) 'type': _type})]));
  }, mutate: true);
  Future<void> _details(WorkspacePurchaseInvoiceAttachment copy, bool readOnly) => _run(() async {
    final value = await showModalBottomSheet<WorkspacePurchaseInvoiceAttachment>(context: context,
      isScrollControlled: true, useSafeArea: true, builder: (_) => _TradeDocumentDetailsEditor(
        session: widget.session, attachment: copy, types: widget.value.documentTypes,
        isCurrent: () => _current, readOnly: readOnly, canKeep: _fits));
    if (_current && !readOnly && value != null) await _replace(value);
  }, mutate: !readOnly);
  Future<void> _replace(WorkspacePurchaseInvoiceAttachment value) => _keep(widget.value.withActive([
    for (final old in widget.value.active) if (old.digest == value.digest) value else old,
  ]));
  Future<void> _read(WorkspacePurchaseInvoiceAttachment copy) => _run(() async {
    final value = await widget.session.workspacePurchaseInvoiceCapture.scan(_scope, widget.value.captureId, copy);
    if (_current) await _replace(value);
  }, mutate: true);
  Future<void> _fields(WorkspacePurchaseInvoiceAttachment copy, bool readOnly) => _run(() async {
    final value = await Navigator.of(context).push<WorkspacePurchaseInvoiceAttachment>(MaterialPageRoute(
      builder: (_) => _ReceivingScannedFieldsScreen(session: widget.session, scope: _scope,
        captureId: widget.value.captureId, attachment: copy, readOnly: readOnly,
        isCurrent: () => _current, canKeep: _fits,
        copyDescription: 'supporting copy', limitDescription: 'draft')));
    if (_current && !readOnly && value != null) await _replace(value);
  }, mutate: !readOnly);
  Future<void> _view(WorkspacePurchaseInvoiceAttachment copy) => _run(() async {
    await Navigator.of(context).push<void>(MaterialPageRoute(builder: (_) => _GoodsReceiptCopyScreen(
      session: widget.session, scope: _scope, captureId: widget.value.captureId,
      attachment: copy, title: 'Supporting copy', isCurrent: () => _current)));
  });
  Widget _copy(WorkspacePurchaseInvoiceAttachment copy, {bool previous = false}) {
    final readOnly = previous || !widget.editable;
    return Column(key: ValueKey('$_prefix-copy-${previous ? 'previous-' : ''}${copy.digest}'),
      crossAxisAlignment: CrossAxisAlignment.stretch, children: [
      Text(copy.documentDetails['reference']?.trim().isNotEmpty == true
        ? '${copy.documentDetails['reference']} · ${copy.fileName}' : copy.fileName,
        maxLines: 2, overflow: TextOverflow.ellipsis, style: const TextStyle(fontSize: 12)),
      Text(storeTradeDocumentLabel(copy.documentDetails['type'] ?? ''), style: const TextStyle(fontSize: 11)),
      Wrap(spacing: 4, children: [
        TextButton(onPressed: !_current || _busy ? null : () => _view(copy), child: const Text('View copy')),
        TextButton(onPressed: !_current || _busy ? null : () => _details(copy, readOnly), child: const Text('Document details')),
        if (!readOnly) TextButton(onPressed: !_editable ? null : () => _read(copy), child: const Text('Read text')),
        if (copy.detectedText.isNotEmpty || copy.extractedFields.isNotEmpty)
          TextButton(onPressed: !_current || _busy ? null : () => _fields(copy, readOnly),
            child: Text('Printed fields · ${copy.extractedFields.length}')),
        if (!readOnly) TextButton(onPressed: !_editable ? null : () => _run(() async {
          final remove = await showDialog<bool>(context: context, builder: (context) => AlertDialog(
            title: const Text('Remove from this draft?'),
            content: const Text('This removes the copy from the current draft. It does not delete the private original file.'),
            actions: [TextButton(onPressed: () => Navigator.pop(context, false), child: const Text('Keep copy')),
              TextButton(onPressed: () => Navigator.pop(context, true), child: const Text('Remove from draft'))]));
          if (_current && remove == true) { await _keep(widget.value.withActive(
            widget.value.active.where((a) => a.digest != copy.digest).toList())); }
        }, mutate: true), child: const Text('Remove')),
      ]),
      if (copy.extractionOverflow) const Text('Review the original: some printed details exceeded the field limit.',
        style: TextStyle(fontSize: 11)),
    ]);
  }
  @override
  Widget build(BuildContext context) => ExpansionTile(
    key: Key('$_prefix-supporting-copies'), tilePadding: EdgeInsets.zero,
    childrenPadding: EdgeInsets.zero, dense: true,
    title: const Text('Supporting copies · optional', style: TextStyle(fontSize: 13, fontWeight: FontWeight.w600)),
    subtitle: Text('${widget.value.active.length} current · ${widget.value.previous.length} previous drafts',
      style: const TextStyle(fontSize: 11)),
    children: [Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
      Text(_allocation
        ? 'Attach payment advice to this private draft.'
        : _refund
        ? 'Attach a refund receipt, bank advice or supplier refund voucher to this private draft.'
        : _credit
        ? 'Attach your supplier’s credit note to this private draft.'
        : 'Attach a receipt or payment advice to this private draft.',
        style: const TextStyle(fontSize: 12)),
      if (widget.editable || _busy) ...[
        TextButton(key: Key('$_prefix-copy-type'), onPressed: !_editable ? null : () async {
          final value = await _chooseTradeDocumentType(context, session: widget.session,
            types: widget.value.documentTypes, selected: _type, isCurrent: () => _current);
          if (_editable && value != null) setState(() => _type = value);
        }, child: Align(alignment: Alignment.centerLeft, child: Text('${storeTradeDocumentLabel(_type)} ▾',
          style: const TextStyle(fontSize: 13, fontWeight: FontWeight.w500)))),
        Wrap(spacing: 4, children: [for (final item in [
          (WorkProofSource.camera, Icons.camera_alt_outlined, 'Camera'),
          (WorkProofSource.gallery, Icons.photo_library_outlined, 'Gallery'),
          (WorkProofSource.upload, Icons.attach_file, 'Photo / PDF')])
          TextButton.icon(key: Key('$_prefix-copy-${item.$1.name}'),
            onPressed: !_editable || widget.value.active.length >= 3 || widget.value.previous.length >= 1000
              ? null : () => _capture(item.$1), icon: Icon(item.$2, size: 18),
            label: Text(item.$3, style: const TextStyle(fontSize: 12, fontWeight: FontWeight.w500)))]),
        const Text('Up to 3 current copies · 10 MB each, 20 MB total. Compare read fields with the original.',
          style: TextStyle(fontSize: 11)),
      ],
      if (!widget.editable && !_busy && widget.value.active.isNotEmpty)
        Text(_allocation ? 'Copies are read-only with this saved allocation request.'
          : _refund ? 'Copies are read-only with this saved refund request.'
          : _credit ? 'Copies are read-only with this saved credit-note request.'
          : 'Copies are read-only with this saved payment attempt.', style: const TextStyle(fontSize: 11)),
      for (final copy in widget.value.active) _copy(copy),
      if (widget.value.previous.isNotEmpty) ExpansionTile(tilePadding: EdgeInsets.zero, dense: true,
        key: Key('$_prefix-previous-copies'), title: const Text('Previous draft copies', style: TextStyle(fontSize: 12)),
        children: [SizedBox(height: 320, child: ListView.builder(
          itemCount: widget.value.previous.length, itemBuilder: (_, index) {
            final group = widget.value.previous[widget.value.previous.length - 1 - index];
            return Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
              Text(group.date.isEmpty ? group.reference : '${group.reference} · ${group.date}',
                style: const TextStyle(fontSize: 12, fontWeight: FontWeight.w600)),
              for (final copy in group.copies) _copy(copy, previous: true),
            ]);
          }))]),
      if (_busy) const LinearProgressIndicator(),
      if (_error != null) Semantics(liveRegion: true, child: Text(_error!, style: const TextStyle(fontSize: 12))),
    ])]);
}

class _StoreRegisterEntrySheet extends StatefulWidget {
  const _StoreRegisterEntrySheet({required this.session, required this.registerId,
    required this.ownerCurrent, this.initialData, this.prefillCurrent});
  final WorkSession session;
  final String registerId;
  final bool Function() ownerCurrent;
  final StoreRegisterEntryInitialData? initialData;
  final bool Function()? prefillCurrent;
  @override State<_StoreRegisterEntrySheet> createState() => _StoreRegisterEntrySheetState();
}

class _StoreRegisterEntrySheetState extends State<_StoreRegisterEntrySheet> {
  final amount = TextEditingController(), reference = TextEditingController();
  final _token = Object();
  late final Object? _scope, _context;
  DateTime occurredAt = DateTime.now().toUtc();
  String direction = 'in';
  bool ready = false, busy = false, dirty = false, _initialAttempted = false;
  int? _reviewedHead, _reviewedRegister;
  WorkspaceLedgerIntent? original;
  String? status, error;
  WorkspaceMoneyRegisterSnapshot? get register => widget.session.workspaceOriginalLedgerSections?.registers[widget.registerId];
  bool get current => mounted && widget.ownerCurrent() && widget.session.hasVerifiedWorkspace &&
    widget.session.workspaceSupplierScope == _scope && widget.session.publicationPreferencesContext == _context;
  bool get editable => ready && current && !busy && original == null &&
    widget.session.canRecordWorkspaceOriginalRegisterEntry(widget.registerId);
  @override void initState() {
    super.initState();
    _scope = widget.session.workspaceSupplierScope; _context = widget.session.publicationPreferencesContext;
    (_openSupplierMoneyForms[widget.session] ??= <Object>{}).add(_token);
    widget.session.addListener(refresh);
    unawaited(load());
  }
  void refresh() {if (mounted) setState(() {});}
  Future<void> load() async {
    if (busy || !current) return;
    setState(() {busy = true; error = null;});
    try {
      final opened = await widget.session.loadWorkspaceOriginalLedger(retry: true);
      if (!current) return;
      final retained = widget.session.workspaceOriginalLedgerPending;
      if (retained?.operation == 'recordStoreMoneyRegisterEntry' && retained!.targetId == widget.registerId) {
        original = retained;
        final entry = Map<String, Object?>.from(retained.input! as Map), delta = entry['deltaMinor']! as int;
        amount.text = '${delta.abs() ~/ 100}.${(delta.abs() % 100).toString().padLeft(2, '0')}';
        direction = delta > 0 ? 'in' : 'out'; reference.text = entry['reference']! as String;
        occurredAt = DateTime.parse(entry['occurredAt']! as String); ready = true; return;
      }
      if (!opened || register == null || !widget.session.canRecordWorkspaceOriginalRegisterEntry(widget.registerId)) {
        error = 'This original account is unavailable. No entry has been recorded.'; return;
      }
      _reviewedHead = widget.session.workspaceOriginalLedgerSections!.revision;
      _reviewedRegister = register!.revision;
      if (!_initialAttempted && widget.initialData != null) {
        _initialAttempted = true;
        if (dirty || widget.prefillCurrent?.call() == false) {
          error = 'Suggestion was not applied. Your existing entry is kept.';
        } else {
          final fields = widget.initialData!.fields;
          amount.text = fields['amount']!; direction = fields['direction']!;
          reference.text = fields['reference']!;
          if (fields['occurredAt'] != null) occurredAt = DateTime.parse(fields['occurredAt']!);
        }
      }
      ready = true;
    } finally {if (mounted) setState(() => busy = false);}
  }
  Future<void> save() async {
    if (busy || !current) return;
    if (original != null) {await check(); return;}
    if (!editable) return;
    final minor = WorkspacePurchaseEntryDraft.printedPaise(amount.text.trim());
    if (minor == null || minor <= 0 || reference.text.trim().isEmpty) {
      setState(() => error = 'Enter the amount and movement reference.'); return;
    }
    if (_reviewedHead != widget.session.workspaceOriginalLedgerSections?.revision ||
        _reviewedRegister != register?.revision || widget.prefillCurrent?.call() == false) {
      setState(() => error = 'The account changed. Refresh records and review your entry.'); return;
    }
    final next = widget.session.prepareWorkspaceOriginalRegisterEntry(registerId: widget.registerId,
      deltaMinor: direction == 'in' ? minor : -minor, reference: reference.text.trim(), occurredAt: occurredAt);
    if (next == null) {setState(() => error = 'Check the entry date, time and original account.'); return;}
    setState(() {original = next; busy = true; error = null;});
    try {await finish(await widget.session.recordWorkspaceOriginalRegisterEntry(next));}
    finally {if (mounted) setState(() => busy = false);}
  }
  Future<void> finish(WorkspaceLedgerReadback? result) async {
    if (!current) return;
    status = result?.attempt?['status'] as String?;
    if (status == 'saved') {Navigator.pop(context); return;}
    error = widget.session.workspaceOriginalLedgerError ?? 'Saved status is unconfirmed. Keep this original request.';
  }
  Future<void> check({bool explicitRetry = false}) async {
    if (busy || !current || original == null) return;
    setState(() {busy = true; error = null;});
    try {await finish(await widget.session.checkWorkspaceOriginalLedgerAttempt(original!, explicitRetry: explicitRetry));}
    finally {if (mounted) setState(() => busy = false);}
  }
  Future<void> chooseTime() async {
    if (!editable || register == null) return;
    final now = DateTime.now(), first = register!.openingAt.toLocal();
    if (first.isAfter(now)) {setState(() => error = 'The original account dates need checking.'); return;}
    final local = occurredAt.toLocal();
    final date = await showDatePicker(context: context,
      initialDate: local.isBefore(first) || local.isAfter(now) ? now : local,
      firstDate: DateTime(first.year, first.month, first.day), lastDate: now);
    if (!editable || date == null) return;
    final time = await showTimePicker(context: context, initialTime: TimeOfDay.fromDateTime(local));
    if (!editable || time == null) return;
    setState(() {occurredAt = DateTime(date.year, date.month, date.day, time.hour, time.minute).toUtc(); dirty = true;});
  }
  Future<bool> confirmLeave() async {
    if (busy) return false;
    if (!current || !dirty || original != null) return true;
    return await showDialog<bool>(context: context, builder: (dialog) => AlertDialog(
      title: const Text('Discard unsaved entry?'), content: const Text('This money entry has not been recorded.'),
      actions: [TextButton(onPressed: () => Navigator.pop(dialog, false), child: const Text('Keep editing')),
        TextButton(onPressed: () => Navigator.pop(dialog, true), child: const Text('Discard changes'))])) == true;
  }
  @override void dispose() {
    widget.session.removeListener(refresh); _openSupplierMoneyForms[widget.session]?.remove(_token);
    amount.dispose(); reference.dispose(); super.dispose();
  }
  @override Widget build(BuildContext context) => PopScope(canPop: !busy && (!dirty || original != null || !current),
    onPopInvokedWithResult: (didPop, _) async {if (!didPop && await confirmLeave() && context.mounted) Navigator.pop(context);},
    child: SafeArea(top: false, child: Padding(padding: EdgeInsets.only(bottom: MediaQuery.viewInsetsOf(context).bottom),
      child: Column(mainAxisSize: MainAxisSize.min, children: [
        Padding(padding: const EdgeInsets.only(left: 16, right: 8), child: Row(children: [
          const Expanded(child: Text('Record money entry', style: TextStyle(fontSize: 14, fontWeight: FontWeight.w700))),
          TextButton(key: const Key('work-money-entry-form-close'), onPressed: busy ? null : () async {
            if (await confirmLeave() && context.mounted) Navigator.pop(context);
          }, child: const Text('Close'))])),
        Flexible(child: SingleChildScrollView(key: const Key('work-money-entry-form'), padding: const EdgeInsets.all(16),
          child: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.stretch, children: [
            if (!current) const Text('Return to the Store where you started. Your entry is kept.')
            else ...[
              Text(register?.label ?? 'Saved money entry', style: const TextStyle(fontSize: 13, fontWeight: FontWeight.w600)),
              const Text('Record a movement already made in this account. No money is transferred.', style: TextStyle(fontSize: 12)),
              const SizedBox(height: 8),
              TextField(key: const Key('work-money-entry-amount'), controller: amount, enabled: editable,
                keyboardType: const TextInputType.numberWithOptions(decimal: true),
                decoration: const InputDecoration(labelText: 'Amount (₹)', isDense: true), onChanged: (_) {if (editable) setState(() => dirty = true);}),
              const SizedBox(height: 8),
              DropdownButtonFormField<String>(key: ValueKey('work-money-entry-direction-$direction'), initialValue: direction,
                decoration: const InputDecoration(labelText: 'Movement', isDense: true),
                items: const [DropdownMenuItem(value: 'in', child: Text('Money in')), DropdownMenuItem(value: 'out', child: Text('Money out'))],
                onChanged: !editable ? null : (value) {if (editable && value != null) setState(() {direction = value; dirty = true;});}),
              const SizedBox(height: 8),
              TextField(key: const Key('work-money-entry-reference'), controller: reference, enabled: editable, maxLength: 512,
                decoration: const InputDecoration(labelText: 'Movement reference', isDense: true), onChanged: (_) {if (editable) setState(() => dirty = true);}),
              TextButton.icon(key: const Key('work-money-entry-date'), onPressed: editable ? chooseTime : null,
                icon: const Icon(Icons.calendar_today_outlined, size: 18),
                label: Text('Entry date & time · ${_registerDate(occurredAt.toLocal())} ${occurredAt.toLocal().hour.toString().padLeft(2, '0')}:${occurredAt.toLocal().minute.toString().padLeft(2, '0')}')),
              if (error != null) Text(error!),
              if (original != null) ...[
                Text(status == 'not_saved' ? 'This entry was not recorded. Close and reopen to review it.' : 'The original request is kept until its status is confirmed.'),
                TextButton(key: const Key('work-money-entry-check-status'), onPressed: busy ? null : check, child: const Text('Check saved status')),
                if (status == null) TextButton(key: const Key('work-money-entry-retry-original'), onPressed: busy ? null : () => check(explicitRetry: true), child: const Text('Retry same entry')),
              ] else ...[
                if (!ready || error != null) TextButton(onPressed: busy ? null : load, child: const Text('Refresh records')),
                FilledButton(key: const Key('work-money-entry-submit'), onPressed: editable ? save : null, child: Text(busy ? 'Saving…' : 'Save entry')),
              ],
            ],
          ]))),
      ]))));
}

class _StoreMoneyEntrySheet extends StatefulWidget {
  const _StoreMoneyEntrySheet({required this.session, this.purchase, this.supplierMoney,
    this.initialData, this.expenseInitialData, this.prefillKey, this.prefillSignature, this.prefillCurrent, this.ownerCurrent, this.readOnlyOpen = false, this.selectedDocument})
    : assert(purchase == null || supplierMoney == null);
  final StoreSupplierMoneyInitialData? initialData;
  final StoreExpenseInitialData? expenseInitialData;
  final WorkspaceLedgerFormKey? prefillKey;
  final String? prefillSignature;
  final bool Function()? prefillCurrent, ownerCurrent;
  final bool readOnlyOpen;
  final StoreSupplierSelectedDocumentInput? selectedDocument;
  final WorkSession session;
  final WorkspacePurchaseRecord? purchase;
  final _StoreSupplierMoneyTarget? supplierMoney;
  @override
  State<_StoreMoneyEntrySheet> createState() => _StoreMoneyEntrySheetState();
}

class _StoreMoneyEntrySheetState extends State<_StoreMoneyEntrySheet> {
  final Object _nativeMoneyToken = Object();
  late final WorkSession _nativeMoneyOwner;
  bool _initialAttempted = false;
  late final bool _originalExpense;
  late final bool _originalSupplierMoney;
  late final Object? _expenseOwnerScope, _expenseOwnerContext;
  WorkspaceLedgerIntent? _expenseIntent;
  String? _expenseStatus;
  WorkspaceLedgerIntent? _moneyIntent;
  String? _moneyStatus;
  bool get _hasOriginalRequest => _expenseIntent != null || _moneyIntent != null;
  bool get _inputOwnerCurrent => widget.ownerCurrent?.call() != false &&
    (!(_originalExpense || _originalSupplierMoney) || widget.session.hasVerifiedWorkspace &&
      const {WorkRemoteReviewStatus.approved, WorkRemoteReviewStatus.live}.contains(widget.session.remoteReviewStatus) &&
      widget.session.workspaceSupplierScope == _expenseOwnerScope &&
      widget.session.publicationPreferencesContext == _expenseOwnerContext);
  bool get _compactMoney => manualMoney || _originalExpense;
  bool get _editableExpense => !_originalExpense || _expenseIntent == null && _inputOwnerCurrent &&
    widget.session.canRecordWorkspaceOriginalExpense;
  bool get expense => widget.purchase == null && widget.supplierMoney == null;
  bool get manualMoney => widget.supplierMoney != null;
  WorkspaceSupplierLedger? get moneyLedger => widget.session.workspaceSupplierLedger(widget.supplierMoney?.supplierId ?? '');
  bool get _settledBillInput => manualMoney && widget.supplierMoney!.copy != null &&
    moneyRecovered && draft.ready && !draft.busy && draft.error == null &&
    frozen == null && billBalance != null && billBalance! <= 0;
  // Absence must be recovered, not inferred from initially empty controllers.
  // Every editable method/date/checkbox change uses the same autosave owner.
  bool get _compactSettled => _settledBillInput && !saving && !conflict && error == null &&
    draft.revision == null && draft.pending == null && amount.text.isEmpty && reference.text.isEmpty;
  String get title => _settledBillInput ? 'Bill payment details' : manualMoney ? widget.supplierMoney!.advance
      ? 'Record supplier advance' : 'Record supplier payment'
      : expense ? _originalExpense ? 'Record expense' : 'Record test expense' : 'Record test payment';
  int? get billBalance {
    if (manualMoney) {
      final copy = widget.supplierMoney!.copy;
      return copy == null ? moneyLedger?.payableMinor : moneyLedger?.manualBillRemainingMinor(copy.draft.id);
    }
    final ledger = widget.session.workspaceSupplierLedger(
      widget.purchase?.supplierId ?? '',
    );
    if (ledger == null || !ledger.historyComplete) {
      return null;
    }
    return ledger.entries
        .where((entry) => entry.orderId == widget.purchase?.orderId)
        .fold<int>(0, (sum, entry) => sum + entry.payableDeltaMinor);
  }

  final amount = TextEditingController(), reference = TextEditingController();
  final note = TextEditingController();
  final amountFocus = FocusNode(), referenceFocus = FocusNode();
  String category = 'Shop expense';
  String method = 'Bank transfer';
  bool _saving = false;
  Object? _copyBusyLease;
  bool get saving => _saving || _copyBusyLease != null;
  bool moneyRecovered = false, excludedFromOpening = false, confirmed = false, conflict = false;
  String occurredOn = DateTime.now().toIso8601String().substring(0, 10);
  WorkspaceSupplierMoneyAttempt? frozen;
  WorkspaceSupplierMoneyCopies? supportingCopies;
  WorkspaceLedgerFormDraft? resetAttempt;
  String? error;
  late final _LedgerFormAutosave draft;
  Map<String, String> get fields => {
    'amount': amount.text,
    'reference': reference.text,
    'channel': method,
    if (expense) 'category': category,
    if (expense) 'note': note.text,
    if (manualMoney) 'occurredOn': occurredOn,
    if (manualMoney) 'notIncludedInOpening': '$excludedFromOpening',
    if (manualMoney && frozen != null) 'attempt': jsonEncode(frozen!.toJson()),
    if (manualMoney && supportingCopies != null) 'supportingCopies': jsonEncode(supportingCopies!.toJson()),
  };
  @override
  void initState() {
    super.initState();
    _originalExpense = expense && widget.session.workspaceOriginalLedgerConfigured;
    _originalSupplierMoney = manualMoney && widget.session.workspaceOriginalSupplierMoneyConfigured;
    _expenseOwnerScope = widget.session.workspaceSupplierScope;
    _expenseOwnerContext = widget.session.publicationPreferencesContext;
    _nativeMoneyOwner = widget.session;
    if (_originalExpense || _originalSupplierMoney) widget.session.addListener(refresh);
    (_openSupplierMoneyForms[_nativeMoneyOwner] ??= <Object>{}).add(_nativeMoneyToken);
    draft = _LedgerFormAutosave(
      widget.session,
      manualMoney ? widget.session.supplierMoneyFormKey(widget.supplierMoney!.supplierId,
        copy: widget.supplierMoney!.copy, advance: widget.supplierMoney!.advance)
      : expense
          ? widget.session.expenseFormKey()
          : widget.session.supplierPaymentFormKey(widget.purchase!),
      inputOwnerCurrent: () => _inputOwnerCurrent && !_hasOriginalRequest,
    );
    draft.addListener(refresh);
    amountFocus.addListener(refresh);
    referenceFocus.addListener(refresh);
    unawaited(load(readOnlyOpen: widget.readOnlyOpen));
  }

  void refresh() {
    if (mounted) {
      setState(() {});
    }
  }

  Future<void> load({bool readOnlyOpen = false}) async {
    if (saving || draft.busy) return;
    setState(() => _saving = true);
    try {
      await _loadMoneyInputLocked(readOnlyOpen: readOnlyOpen);
    } finally {
      if (mounted) setState(() => _saving = false);
    }
  }

  Future<void> _loadMoneyInputLocked({bool readOnlyOpen = false}) async {
    if (!_inputOwnerCurrent) return;
    if (_originalSupplierMoney) {
      final ready = await widget.session.loadWorkspaceOriginalLedger();
      if (!mounted || !_inputOwnerCurrent) return;
      final pending = widget.session.workspaceOriginalLedgerPending;
      if (pending?.operation == 'recordStoreSupplierMoney' && pending!.targetId == widget.supplierMoney!.supplierId) {
        final attempt = WorkspaceSupplierMoneyAttempt.fromJson({'entry': pending.input,
          'expectedRevision': pending.data['expectedSupplierRevision']});
        final copy = widget.supplierMoney!.copy;
        if (attempt == null || (attempt.entry.kind == WorkspaceSupplierEntryKind.advance) != widget.supplierMoney!.advance ||
            (copy == null ? attempt.entry.origin != WorkspaceSupplierEntryOrigin.supplierAccount
              : attempt.entry.origin != WorkspaceSupplierEntryOrigin.manualPurchase ||
                attempt.entry.purchaseId != copy.id || attempt.entry.billId != copy.draft.id)) {
          conflict = true; error = 'Open the original supplier payment request. Its saved input is kept.'; return;
        }
        _moneyIntent = pending; frozen = attempt;
        amount.text = '${attempt.entry.amountMinor ~/ 100}.${(attempt.entry.amountMinor % 100).toString().padLeft(2, '0')}';
        reference.text = attempt.entry.reference; method = attempt.entry.paymentMethod!;
        occurredOn = attempt.entry.moneyReview!.occurredOn; excludedFromOpening = true;
        // The immutable request stays available for status recovery even when
        // the original source refresh failed. No editable fallback is opened.
        if (!ready) {error = widget.session.workspaceOriginalLedgerError; return;}
      }
      if (!ready) {error = widget.session.workspaceOriginalLedgerError ?? 'Original supplier accounts are unavailable.'; return;}
    }
    if (_originalExpense) {
      final ready = await widget.session.loadWorkspaceOriginalLedger();
      if (!mounted || !_inputOwnerCurrent) return;
      final original = widget.session.workspaceOriginalLedgerPending;
      if (original?.operation == 'recordStoreExpense') {
        final expense = WorkspaceExpenseRecord.fromJson(original!.input);
        if (expense == null) { error = 'Saved expense request could not be opened. Its data is kept.'; return; }
        _expenseIntent = original;
        amount.text = '${expense.amountMinor ~/ 100}.${(expense.amountMinor % 100).toString().padLeft(2, '0')}';
        reference.text = expense.reference; category = expense.category;
        method = expense.method; note.text = expense.note;
        return;
      }
      if (!ready) {error = widget.session.workspaceOriginalLedgerError ?? 'Original expense records are unavailable.'; return;}
    }
    final pristineAtStart = amount.text.isEmpty && reference.text.isEmpty &&
      draft.revision == null && draft.pending == null && !draft.busy && draft.error == null &&
      frozen == null && supportingCopies == null && resetAttempt == null && !confirmed && !conflict;
    var pendingConflict = false;
    if (manualMoney && draft.pending != null) {
      draft.save(fields);
      pendingConflict = !await draft.flush();
      if (!mounted) return;
    }
    if (manualMoney) moneyRecovered = _originalSupplierMoney
      ? widget.session.workspaceOriginalLedgerSections != null
      : readOnlyOpen ? widget.session.workspaceInvoiceHistoryLoaded : await widget.session.recoverCustomerLedger();
    final saved = await draft.load();
    if (!mounted || saved == null || !_inputOwnerCurrent) {
      return;
    }
    if (_originalSupplierMoney && _moneyIntent != null) {
      final retained = WorkspaceLedgerFormDraft(key: draft.key!, revision: draft.revision ?? 1,
        fields: saved).supplierMoneyAttempt;
      if (retained == null || frozen == null ||
          jsonEncode(retained.toJson()) != jsonEncode(frozen!.toJson())) {
        conflict = true;
        error = 'The original payment request does not match the saved input. Keep both records and check its saved status.';
        return;
      }
    }
    amount.text = saved['amount'] ?? '';
    reference.text = saved['reference'] ?? '';
    method = saved['channel'] ?? (expense ? 'Cash' : 'Bank transfer');
    category = saved['category'] ?? 'Shop expense';
    note.text = saved['note'] ?? '';
    if (manualMoney) {
      supportingCopies = WorkspaceLedgerFormDraft(key: draft.key!, revision: draft.revision ?? 1,
        fields: saved).supplierMoneyCopies;
      if (supportingCopies != null && supportingCopies!.qa != widget.session.workspaceSupplierScope?.$3) {
        setState(() { conflict = true; error = 'Return to the same Store session to open the saved draft copies.'; });
        return;
      }
      occurredOn = saved['occurredOn'] ?? occurredOn;
      excludedFromOpening = saved['notIncludedInOpening'] == 'true';
      final text = saved['attempt'];
      try {
        frozen = text == null || text.isEmpty ? null
          : WorkspaceSupplierMoneyAttempt.fromJson(jsonDecode(text));
      } on FormatException {
        setState(() { conflict = true; error = 'Saved payment attempt could not be read. Its data is kept; do not replace it.'; });
        return;
      }
      resetAttempt = null;
      _inspectSavedMoney();
      if (_originalSupplierMoney && frozen != null) {
        try {
          final original = await widget.session.readWorkspaceOriginalSupplierMoneyRequest(draft.key!, frozen!);
          if (!mounted || !_inputOwnerCurrent) return;
          if (_moneyIntent != null && (original == null || original.fingerprint != _moneyIntent!.fingerprint ||
              original.idempotencyKey != _moneyIntent!.idempotencyKey)) {
            conflict = true; error = 'Keep the original payment request and its saved input.'; return;
          }
          _moneyIntent = original;
        } on Object {
          conflict = true; error = 'Saved payment identity could not be verified. Keep its original input.'; return;
        }
      }
      if (pendingConflict) {
        // Preserve the losing local payload; authoritative recovery must not
        // be blocked forever by retrying a stale write before every read.
        final pending = draft.pending;
        if (pending != null && jsonEncode(pending.fields) == jsonEncode(saved)) {
          draft.pending = null;
        } else {
          conflict = true;
          draft.error = 'Saved payment details differ from this unsaved input. The unsaved input remains on this screen; do not submit or replace either record.';
          error = draft.error;
        }
      }
    }
    final expenseInitial = widget.expenseInitialData;
    if (expenseInitial != null && !_initialAttempted) {
      _initialAttempted = true;
      final pristine = pristineAtStart && saved.isEmpty && draft.revision == null &&
        draft.pending == null && !draft.busy && draft.error == null && !pendingConflict &&
        amount.text.isEmpty && reference.text.isEmpty && note.text.isEmpty;
      if (!expense || !pristine || !_inputOwnerCurrent || widget.prefillCurrent?.call() == false ||
          widget.prefillKey != draft.key || widget.prefillSignature !=
            _supplierAccountAssistantSignature(widget.session, 'AI-ACT-270', null)) {
        error = 'Suggestion was not applied. Existing expense input is kept.';
      } else {
        // Programmatic raw input only; the original controls own every save.
        amount.text = expenseInitial.inputs['amount']!;
        reference.text = expenseInitial.inputs['reference']!;
        method = expenseInitial.inputs['channel']!;
        category = expenseInitial.inputs['category']!;
        note.text = expenseInitial.inputs['note']!;
      }
    }
    final initial = widget.initialData;
    if (initial != null && !_initialAttempted) {
      _initialAttempted = true;
      final target = widget.supplierMoney;
      final pristine = pristineAtStart && saved.isEmpty && draft.revision == null &&
        draft.pending == null && !draft.busy && draft.error == null && !pendingConflict &&
        frozen == null && supportingCopies == null && resetAttempt == null &&
        !confirmed && !conflict && amount.text.isEmpty && reference.text.isEmpty;
      if (!manualMoney || target == null || !moneyRecovered || !_inputOwnerCurrent ||
          widget.prefillCurrent?.call() == false || !pristine ||
          widget.prefillKey != draft.key || !initial.matches(widget.session, target) ||
          widget.prefillSignature != _assistantSupplierMoneySignature(widget.session, target)) {
        error = 'Suggestion was not applied. Existing supplier input and saved attempts are kept.';
      } else {
        // Programmatic assignment does not invoke TextField onChanged.
        // No draft.save or flush here; original user actions own persistence.
        amount.text = initial.inputs['amount']!;
        reference.text = initial.inputs['reference']!;
        method = initial.inputs['channel']!;
        occurredOn = initial.inputs['occurredOn']!;
        // Do not tick the original opening-balance confirmation for the user.
      }
    }
    setState(() {});
  }

  void _inspectSavedMoney() {
    confirmed = false;
    conflict = false;
    if (frozen == null || !moneyRecovered) return;
    final found = moneyLedger?.entries.where((entry) => entry.operationId == frozen!.entry.operationId).toList();
    if (found?.length == 1) {
      confirmed = jsonEncode(found!.single.toJson()) == jsonEncode(frozen!.entry.toJson());
      conflict = !confirmed;
      if (conflict) error = 'Saved payment details conflict. Keep this attempt and recover the supplier account.';
    }
  }

  Future<void> submitManualMoney() async {
    if (_originalSupplierMoney && _moneyIntent != null) {await _checkOriginalMoney(); return;}
    if (saving || confirmed || conflict || !moneyRecovered || !_inputOwnerCurrent) return;
    setState(() => _saving = true);
    try {
      await _submitManualMoneyLocked();
    } finally {
      if (mounted) setState(() => _saving = false);
    }
  }

  Future<void> _submitManualMoneyLocked() async {
    if (!await draft.flush() || !mounted || !_inputOwnerCurrent) return;
    final ledger = moneyLedger;
    final opening = ledger?.openingRecord;
    final minor = WorkspacePurchaseEntryDraft.printedPaise(amount.text);
    if (frozen == null) {
      if (ledger == null || opening == null || minor == null || minor <= 0 ||
          reference.text.trim().isEmpty || !excludedFromOpening) {
        setState(() => error = 'Enter the amount, payment reference and date. Confirm it is not already included in the starting balance.');
        return;
      }
      final target = widget.supplierMoney!;
      final payable = ledger.payableMinor;
      if (!target.advance && (billBalance == null || payable == null || minor > billBalance! || minor > payable)) {
        setState(() => error = 'Amount exceeds the verified dues. Record extra money separately as an advance.');
        return;
      }
      final review = WorkspaceSupplierMoneyReview(occurredOn: occurredOn,
        openingId: opening.id, openingRevision: opening.revision, notIncludedInOpening: true);
      final entry = WorkspaceSupplierLedgerEntry(operationId: widget.session.newWorkspaceSupplierMoneyOperationId(),
        reference: reference.text.trim(), origin: target.copy == null
          ? WorkspaceSupplierEntryOrigin.supplierAccount : WorkspaceSupplierEntryOrigin.manualPurchase,
        purchaseId: target.copy?.id, billId: target.copy?.draft.id,
        kind: target.advance ? WorkspaceSupplierEntryKind.advance : WorkspaceSupplierEntryKind.payment,
        amountMinor: minor, paymentMethod: method, postedAt: DateTime.now().toUtc(), moneyReview: review);
      final attempt = WorkspaceSupplierMoneyAttempt(entry: entry, expectedRevision: ledger.revision);
      if (!attempt.valid) { setState(() => error = 'Check the payment date and details.'); return; }
      setState(() { frozen = attempt; _saving = true; error = null; });
      // Earlier editable snapshots have been flushed. Persist the immutable
      // attempt first; a failed/lost draft reply cannot create another payment.
      draft.save(fields);
      if (!await draft.flush() || !mounted) {
        if (mounted) setState(() { _saving = false; error = 'Payment has not been submitted. Retry saving this same attempt first.'; });
        return;
      }
    } else {
      setState(() { _saving = true; error = null; });
    }
    if (!_inputOwnerCurrent) return;
    if (_originalSupplierMoney) {
      final original = widget.session.prepareWorkspaceOriginalSupplierMoney(key: draft.key!, attempt: frozen!);
      if (original == null) {error = 'Supplier records changed. Reopen and review this saved payment input.'; return;}
      _moneyIntent = original;
      await _checkOriginalMoney(firstSave: true);
      return;
    }
    final saved = await widget.session.recordWorkspaceSupplierMoneyDraft(draft.key!, frozen!);
    if (!mounted) return;
    moneyRecovered = await widget.session.recoverCustomerLedger();
    if (!mounted) return;
    _inspectSavedMoney();
    setState(() {
      _saving = false;
      error = saved && confirmed ? null : 'Payment status needs checking. This saved attempt is retained; recover and retry it, not a new payment.';
    });
  }

  Future<void> recordAnother() async {
    if (!_inputOwnerCurrent || saving || !confirmed || draft.revision == null) return;
    setState(() => _saving = true);
    try {
      await _recordAnotherLocked();
    } finally {
      if (mounted) setState(() => _saving = false);
    }
  }

  Future<void> _recordAnotherLocked() async {
    if (!_inputOwnerCurrent || !await draft.flush() || !mounted || !_inputOwnerCurrent) return;
    resetAttempt ??= WorkspaceLedgerFormDraft(key: draft.key!, revision: draft.revision! + 1,
      fields: {'amount': '', 'reference': '', 'channel': method,
        'occurredOn': DateTime.now().toIso8601String().substring(0, 10), 'notIncludedInOpening': 'false',
        if (supportingCopies != null) 'supportingCopies': jsonEncode(supportingCopies!.archive(frozen!).toJson())});
    setState(() { _saving = true; error = null; });
    if (!_inputOwnerCurrent) return;
    final reset = await widget.session.resetConfirmedWorkspaceSupplierMoneyDraft(resetAttempt!, expectedRevision: draft.revision!);
    if (!mounted || !_inputOwnerCurrent) return;
    if (reset) {
      draft.revision = resetAttempt!.revision;
      draft.pending = null;
      draft.error = null;
      amount.clear(); reference.clear();
      supportingCopies = resetAttempt!.supplierMoneyCopies;
      occurredOn = resetAttempt!.fields['occurredOn']!;
      excludedFromOpening = false; frozen = null; confirmed = false; conflict = false; resetAttempt = null;
      _moneyIntent = null; _moneyStatus = null;
    }
    setState(() { _saving = false; error = reset ? null : 'The recorded payment is kept. Retry starting another payment.'; });
  }

  Future<void> choosePaymentDate() async {
    if (saving || conflict || frozen != null || !draft.ready) return;
    final now = DateTime.now();
    final parsed = DateTime.tryParse(occurredOn);
    final initial = parsed == null || parsed.isAfter(now) || parsed.isBefore(DateTime(2000)) ? now : parsed;
    final chosen = await showDatePicker(context: context,
      initialDate: initial,
      firstDate: DateTime(2000), lastDate: now);
    if (!mounted || chosen == null || frozen != null) return;
    setState(() => occurredOn = chosen.toIso8601String().substring(0, 10));
    draft.save(fields);
  }

  Future<void> submit() async {
    if (manualMoney) { await submitManualMoney(); return; }
    if (_originalExpense) {await _submitOriginalExpense(); return;}
    if (saving || !_inputOwnerCurrent ||
        (widget.expenseInitialData != null && widget.prefillSignature !=
          _supplierAccountAssistantSignature(widget.session, 'AI-ACT-270', null)) ||
        !await draft.flush() || !mounted || !_inputOwnerCurrent) {
      return;
    }
    final text = amount.text.trim();
    if (!RegExp(r'^\d{1,10}(\.\d{1,2})?$').hasMatch(text) ||
        reference.text.trim().isEmpty) {
      setState(
        () => error = 'Enter the amount paid and its payment reference.',
      );
      return;
    }
    final parts = text.split('.');
    final minor =
        int.parse(parts.first) * 100 +
        (parts.length == 1 ? 0 : int.parse(parts.last.padRight(2, '0')));
    final key = draft.key!;
    setState(() {
      _saving = true;
      error = null;
    });
    final saved = expense
        ? await widget.session.recordStoreReviewExpense(
            key: key,
            amountMinor: minor,
            category: category,
            method: method,
            reference: reference.text.trim(),
            note: note.text.trim(),
          )
        : await widget.session.recordStoreReviewSupplierPayment(
            widget.purchase!,
            operationId: jsonEncode([
              'supplier-payment',
              key.account,
              key.store,
              key.customer,
              key.invoice,
              key.order,
              key.ledgerRevision,
            ]),
            reference: reference.text.trim(),
            paymentMethod: method,
            amountMinor: minor,
            expectedRevision: key.ledgerRevision,
          );
    if (!mounted) {
      return;
    }
    if (saved) {
      Navigator.pop(context);
      return;
    }
    setState(() {
      _saving = false;
      error = expense
          ? 'Expense not confirmed. Recover saved status before retrying.'
          : 'Payment not confirmed. Check the bill balance and saved status before retrying.';
    });
  }

  Future<void> _submitOriginalExpense() async {
    if (saving || !_inputOwnerCurrent) return;
    // An earlier Save callback is status-only once an attempt exists.
    if (_expenseIntent != null) {await _checkOriginalExpense(); return;}
    setState(() {_saving = true; error = null;});
    try {
      if (!await draft.flush() || !mounted || !_inputOwnerCurrent) return;
      if (widget.expenseInitialData != null && widget.prefillSignature !=
          _supplierAccountAssistantSignature(widget.session, 'AI-ACT-270', null)) {
        error = 'Expense records changed. Reopen and review your saved input.'; return;
      }
      final minor = WorkspacePurchaseEntryDraft.printedPaise(amount.text.trim());
      if (minor == null || minor <= 0 || reference.text.trim().isEmpty) {
        error = 'Enter the expense amount and its receipt or payment reference.'; return;
      }
      final key = draft.key;
      final original = key == null ? null : widget.session.prepareWorkspaceOriginalExpense(
        key: key, amountMinor: minor, category: category, method: method,
        reference: reference.text.trim(), note: note.text.trim());
      if (original == null) {error = 'Expense records changed. Reopen and review your saved input.'; return;}
      _expenseIntent = original;
      await _checkOriginalExpense(firstSave: true);
    } finally {if (mounted) setState(() => _saving = false);}
  }

  Future<void> _checkOriginalMoney({bool firstSave = false, bool explicitRetry = false}) async {
    final original = _moneyIntent;
    if (original == null || !_inputOwnerCurrent || !firstSave && saving) return;
    setState(() {_saving = true; error = null;});
    try {
      final result = firstSave
        ? await widget.session.recordWorkspaceOriginalSupplierMoney(original, key: draft.key!, attempt: frozen!)
        : await widget.session.checkWorkspaceOriginalSupplierMoneyRequest(widget.supplierMoney!.supplierId,
            original, key: draft.key, attempt: frozen, explicitRetry: explicitRetry);
      if (!mounted || !_inputOwnerCurrent) return;
      _moneyStatus = result?.attempt?['status'] as String?;
      confirmed = _moneyStatus == 'saved';
      moneyRecovered = widget.session.workspaceOriginalLedgerSections != null;
      error = confirmed ? null : widget.session.workspaceOriginalLedgerError ??
        'Payment status is unconfirmed. Keep this request and check again.';
    } finally {if (mounted) setState(() => _saving = false);}
  }

  Future<void> _reviewRefusedMoney() async {
    if (saving || !_inputOwnerCurrent || _moneyStatus != 'not_saved' ||
        draft.key == null || draft.revision == null || frozen == null) return;
    setState(() {_saving = true; error = null;});
    try {
      final retained = {...fields}..remove('attempt'); retained['notIncludedInOpening'] = 'false';
      final next = WorkspaceLedgerFormDraft(key: draft.key!, revision: draft.revision! + 1, fields: retained);
      final reset = await widget.session.resetRefusedWorkspaceSupplierMoneyDraft(next, expectedRevision: draft.revision!);
      if (!mounted || !_inputOwnerCurrent) return;
      if (!reset) {error = 'Check this exact payment status before reviewing the saved details.'; return;}
      draft.revision = next.revision; draft.pending = null; draft.error = null;
      frozen = null; _moneyIntent = null; _moneyStatus = null; excludedFromOpening = false; confirmed = false;
      moneyRecovered = widget.session.workspaceOriginalLedgerSections != null;
    } finally {if (mounted) setState(() => _saving = false);}
  }

  Future<void> _checkOriginalExpense({bool firstSave = false, bool explicitRetry = false}) async {
    final original = _expenseIntent;
    if (original == null || !_inputOwnerCurrent || !firstSave && saving) return;
    setState(() {_saving = true; error = null;});
    try {
      final result = firstSave
        ? await widget.session.recordWorkspaceOriginalExpense(original)
        : await widget.session.checkWorkspaceOriginalLedgerAttempt(original, explicitRetry: explicitRetry);
      if (!mounted || !_inputOwnerCurrent) return;
      _expenseStatus = result?.attempt?['status'] as String?;
      if (_expenseStatus == 'saved') {Navigator.pop(context); return;}
      error = widget.session.workspaceOriginalLedgerError ?? 'Expense status is unconfirmed. Keep this request and check again.';
    } finally {if (mounted) setState(() => _saving = false);}
  }

  @override
  void dispose() {
    if (_originalExpense || _originalSupplierMoney) widget.session.removeListener(refresh);
    _openSupplierMoneyForms[_nativeMoneyOwner]?.remove(_nativeMoneyToken);
    draft.removeListener(refresh);
    draft.dispose();
    amount.dispose();
    reference.dispose();
    note.dispose();
    amountFocus.removeListener(refresh);
    referenceFocus.removeListener(refresh);
    amountFocus.dispose();
    referenceFocus.dispose();
    super.dispose();
  }

  InputDecoration _moneyDecoration(String label, {String? hint}) =>
      InputDecoration(labelText: label, hintText: hint,
        isDense: manualMoney ? true : null,
        constraints: manualMoney ? const BoxConstraints(minHeight: 48) : null,
        labelStyle: manualMoney ? const TextStyle(fontSize: 12) : null,
        hintStyle: manualMoney ? const TextStyle(fontSize: 12) : null,
        contentPadding: manualMoney ? const EdgeInsets.symmetric(horizontal: 12, vertical: 14) : null);

  Widget _paidAmountField() => TextField(
    key: Key(expense ? 'store-expense-amount' : 'supplier-payment-amount'),
    controller: amount,
    focusNode: manualMoney ? amountFocus : null,
    style: manualMoney ? const TextStyle(fontSize: 13) : null,
    enabled: draft.ready && !saving && _editableExpense && !_settledBillInput && (!manualMoney || (frozen == null && !conflict)),
    keyboardType: const TextInputType.numberWithOptions(decimal: true),
    decoration: _originalExpense ? _moneyDecoration('Expense amount (₹)')
      : manualMoney ? _moneyDecoration('Amount paid (₹)') : const InputDecoration(labelText: 'Paid (₹)'),
    onChanged: (_) => draft.save(fields));

  Widget _paymentMethodField() => DropdownButtonFormField<String>(
    key: ValueKey('supplier-payment-method-$method'),
    initialValue: method,
    isExpanded: true,
    style: manualMoney ? const TextStyle(fontSize: 13, color: Color(0xff000066)) : null,
    decoration: manualMoney ? _moneyDecoration('Payment method') : const InputDecoration(labelText: 'Method used'),
    items: [for (final value in {'UPI', 'Cheque', 'Bank transfer', 'NEFT', 'RTGS', 'Cash', method})
      DropdownMenuItem(value: value, child: Text(value))],
    onChanged: !draft.ready || saving || !_editableExpense || _settledBillInput || (manualMoney && (frozen != null || conflict))
      ? null : (value) {
        if (value != null) {
          setState(() => method = value);
          draft.save(fields);
        }
      });

  Widget _manualAmountAndMethod() => LayoutBuilder(builder: (context, constraints) {
    final paired = constraints.maxWidth >= MediaQuery.textScalerOf(context).scale(140) * 2 + 8;
    final width = paired ? (constraints.maxWidth - 8) / 2 : constraints.maxWidth;
    return Wrap(spacing: 8, runSpacing: 8, children: [
      SizedBox(width: width, child: _paidAmountField()),
      SizedBox(width: width, child: _paymentMethodField()),
    ]);
  });

  Widget _moneyViewport(BuildContext context, Widget fields) {
    if (!_compactMoney) return fields;
    return LayoutBuilder(builder: (context, constraints) => ConstrainedBox(
      constraints: BoxConstraints(maxHeight: constraints.maxHeight),
      child: Column(mainAxisSize: MainAxisSize.min, children: [
        Padding(padding: const EdgeInsets.fromLTRB(16, 8, 8, 0),
          child: Row(children: [
            Expanded(child: Text(title,
              style: const TextStyle(fontSize: 14, fontWeight: FontWeight.w700, color: Color(0xff000066)))),
            if (amountFocus.hasFocus || referenceFocus.hasFocus || MediaQuery.viewInsetsOf(context).bottom > 0)
              IconButton(key: const Key('supplier-money-hide-keyboard'),
              tooltip: 'Hide keyboard',
              onPressed: () => FocusScope.of(context).unfocus(),
              icon: const Icon(Icons.keyboard_hide_outlined)),
            TextButton(key: const Key('supplier-money-close'),
              style: TextButton.styleFrom(textStyle: const TextStyle(fontSize: 13)),
              onPressed: saving ? null : () async {
                if ((_hasOriginalRequest || !_inputOwnerCurrent || await draft.flush()) && context.mounted) Navigator.pop(context);
              }, child: const Text('Close')),
          ])),
        Flexible(child: NotificationListener<ScrollNotification>(
          onNotification: (notification) {
            if (notification.depth == 0 &&
                (notification is ScrollStartNotification ||
                 notification is ScrollUpdateNotification)) {
              // Selection handles follow their field outside the scrolling
              // viewport; hide them before they can cover the fixed controls.
              final editor = FocusManager.instance.primaryFocus?.context
                  ?.findAncestorStateOfType<EditableTextState>();
              if (editor?.context.findAncestorStateOfType<_StoreMoneyEntrySheetState>() == this) {
                editor?.hideToolbar();
              }
            }
            return false;
          }, child: fields)),
      ]),
    ));
  }

  @override
  Widget build(BuildContext context) => (_originalExpense || _originalSupplierMoney) && !_inputOwnerCurrent
    ? Padding(padding: const EdgeInsets.all(16), child: Column(mainAxisSize: MainAxisSize.min, children: [
      Text('Return to the Store where you started. ${_originalSupplierMoney ? 'Payment' : 'Expense'} input is kept.'),
      TextButton(onPressed: () => Navigator.pop(context), child: const Text('Close'))]))
    : PopScope(
    canPop: !saving && (_hasOriginalRequest || !draft.busy && draft.error == null),
    onPopInvokedWithResult: (didPop, result) async {
      if (!didPop && !saving && await draft.flush() && context.mounted) {
        Navigator.pop(context);
      }
    },
    child: SafeArea(
      top: false,
      child: Padding(
        padding: EdgeInsets.only(bottom: _compactMoney ? MediaQuery.viewInsetsOf(context).bottom : 0),
      child: _moneyViewport(context, SingleChildScrollView(
        padding: EdgeInsets.fromLTRB(
          16,
          16,
          16,
          16 + (_compactMoney ? 0 : MediaQuery.viewInsetsOf(context).bottom),
        ),
        child: Column(
          key: _compactSettled ? const Key('supplier-money-compact-settled') : null,
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            if (!_compactMoney) Text(title, style: Theme.of(context).textTheme.titleLarge),
            if (manualMoney) ...[
              Text(moneyLedger?.supplierName ?? 'Supplier', key: const Key('supplier-money-supplier'),
                style: const TextStyle(fontSize: 13, fontWeight: FontWeight.w600)),
              if (widget.supplierMoney!.copy != null)
                Text('Bill ${widget.supplierMoney!.copy!.draft.invoiceReference}', key: const Key('supplier-money-bill-reference'),
                  style: const TextStyle(fontSize: 12)),
              const SizedBox(height: 4),
            ] else Text(
              expense
                  ? 'Business expense not already recorded elsewhere.'
                  : '${widget.purchase!.supplierName} · ${draft.key?.invoice ?? 'Bill unavailable'}',
            ),
            if (_compactSettled) Text('Bill balance ${_purchaseAmount(billBalance!)}',
              key: const Key('supplier-money-compact-balance'),
              style: Theme.of(context).textTheme.titleMedium?.copyWith(fontWeight: FontWeight.w600)),
            if (manualMoney) Text(widget.supplierMoney!.copy != null
              ? 'Record a payment already made against this bill.'
              : widget.supplierMoney!.advance
              ? 'Record an advance already paid; apply it to a bill later.'
              : 'Record money already paid without linking it to a bill.',
              key: const Key('supplier-money-purpose-guide'),
              style: const TextStyle(fontSize: 12, color: MoolColors.muted))
            else if (_originalExpense) const Text('Record a business expense already paid. No money is transferred.',
              style: TextStyle(fontSize: 12, color: MoolColors.muted))
            else const Text('Test record only. No money is transferred.'),
            if (_settledBillInput) const Text(
              'No amount is due on this bill. To record extra money already paid to the supplier, close and choose Record advance paid.',
              key: Key('supplier-money-no-bill-due')),
            if (!expense && !_compactSettled && !(manualMoney && widget.supplierMoney!.advance))
              Text(
                billBalance == null
                    ? 'Bill balance unavailable'
                    : '${manualMoney && widget.supplierMoney!.copy == null ? 'Supplier dues' : 'Bill balance'} ${_purchaseAmount(billBalance!)}',
                style: manualMoney ? const TextStyle(fontSize: 12, fontWeight: FontWeight.w600) : null,
              ),
            if (!_compactSettled) ...[
              if (manualMoney) ...[
                const SizedBox(height: 12),
                _manualAmountAndMethod(),
                const SizedBox(height: 8),
              ] else ...[_paidAmountField(), _paymentMethodField()],
            ],
            if (!_compactSettled) TextField(
              key: Key(
                expense
                    ? 'store-expense-reference'
                    : 'supplier-payment-reference',
              ),
              controller: reference,
              focusNode: manualMoney ? referenceFocus : null,
              style: manualMoney ? const TextStyle(fontSize: 13) : null,
              enabled: draft.ready && !saving && _editableExpense && !_settledBillInput && (!manualMoney || (frozen == null && !conflict)),
              decoration: _originalExpense ? _moneyDecoration('Receipt / payment reference')
                : manualMoney ? _moneyDecoration('Payment reference', hint: 'UPI/bank reference or cash note')
                : const InputDecoration(labelText: 'Payment reference'),
              onChanged: (_) => draft.save(fields),
            ),
            if (manualMoney) ...[
              if (!_compactSettled) Align(alignment: Alignment.centerLeft, child: TextButton.icon(key: const Key('supplier-money-date'),
                style: TextButton.styleFrom(textStyle: const TextStyle(fontSize: 12), alignment: Alignment.centerLeft),
                onPressed: !draft.ready || saving || _settledBillInput || conflict || frozen != null ? null : choosePaymentDate,
                icon: const Icon(Icons.calendar_today_outlined, size: 16),
                label: Text('Payment date · ${occurredOn.split('-').reversed.join('/')}'))),
              if (!_compactSettled) CheckboxListTile(key: const Key('supplier-money-opening-excluded'),
                contentPadding: EdgeInsets.zero, dense: true, value: excludedFromOpening,
                title: const Text('This payment is not included in opening balance', style: TextStyle(fontSize: 12)),
                onChanged: !draft.ready || saving || _settledBillInput || conflict || frozen != null ? null : (value) {
                  setState(() => excludedFromOpening = value == true); draft.save(fields);
                }),
              if (frozen != null) Text(confirmed ? '${widget.supplierMoney!.advance ? 'Advance' : 'Payment'} recorded · ${_purchaseAmount(frozen!.entry.amountMinor)} · ${frozen!.entry.paymentMethod}'
                  : draft.pending == null && draft.error == null && draft.revision != null && !draft.busy
                    ? 'Saved payment attempt · recover and retry these same details.'
                    : 'Saved status unverified · keep this payment request and retry saving.',
                key: const Key('supplier-money-attempt-status')),
              if (_originalSupplierMoney && _moneyIntent != null) ...[
                TextButton(key: const Key('supplier-money-check-status'),
                  onPressed: saving ? null : _checkOriginalMoney, child: const Text('Check saved status')),
                if (_moneyStatus == null) TextButton(key: const Key('supplier-money-retry-original'),
                  onPressed: saving ? null : () => _checkOriginalMoney(explicitRetry: true), child: const Text('Retry same payment')),
                if (_moneyStatus == 'not_saved') TextButton(key: const Key('supplier-money-review-refused'),
                  onPressed: saving ? null : _reviewRefusedMoney, child: const Text('Review payment details')),
              ] else if (!moneyRecovered || (frozen != null && !confirmed))
                TextButton(key: const Key('supplier-money-recover'),
                  onPressed: saving || draft.busy ? null : load, child: const Text('Recover saved payment')),
            ],
            if (expense) ...[
              DropdownButtonFormField<String>(
                key: ValueKey('store-expense-category-$category'),
                initialValue: category,
                isExpanded: true,
                decoration: const InputDecoration(labelText: 'Category'),
                items: [
                  for (final value in {
                    'Shop expense',
                    'Delivery',
                    'Electricity',
                    'Salary',
                    'Repair',
                    'Other',
                    category,
                  })
                    DropdownMenuItem(value: value, child: Text(value)),
                ],
                onChanged: !draft.ready || saving || !_editableExpense
                    ? null
                    : (value) {
                        if (value != null) {
                          setState(() => category = value);
                          draft.save(fields);
                        }
                      },
              ),
              TextField(
                key: const Key('store-expense-note'),
                controller: note,
                maxLength: 512,
                enabled: draft.ready && !saving && _editableExpense,
                decoration: const InputDecoration(labelText: 'Expense note'),
                onChanged: (_) => draft.save(fields),
              ),
            ],
            if (manualMoney && draft.ready && moneyRecovered && !conflict && draft.key != null &&
                widget.session.workspaceSupplierScope != null &&
                ((frozen == null && !_settledBillInput) || supportingCopies?.active.isNotEmpty == true ||
                  supportingCopies?.previous.isNotEmpty == true)) _SupplierPaymentDraftCopies(
              sourceRevision: () => jsonEncode([draft.revision, fields]),
              selectedDocument: widget.selectedDocument,
              canStageSelected: (lease) => manualMoney && draft.ready && moneyRecovered && !conflict && !_saving && !draft.busy && draft.error == null && frozen == null && !_settledBillInput &&
                (_copyBusyLease == null || identical(_copyBusyLease, lease)),
              session: widget.session, value: supportingCopies ?? WorkspaceSupplierMoneyCopies(
                key: draft.key!, qa: widget.session.workspaceSupplierScope!.$3),
              editable: !saving && !draft.busy && draft.error == null && frozen == null && !_settledBillInput,
              saved: draft.pending == null && !draft.busy && draft.error == null,
              isCurrent: () => mounted && _inputOwnerCurrent && widget.session.supplierMoneyFormKey(widget.supplierMoney!.supplierId,
                copy: widget.supplierMoney!.copy, advance: widget.supplierMoney!.advance) == draft.key,
              beforeChange: draft.flush,
              onBusy: (lease, busy) {
                if (mounted && (busy || identical(_copyBusyLease, lease))) {
                  setState(() => _copyBusyLease = busy ? lease : null);
                }
              },
              onChanged: (value) async {
                if (!mounted || !_inputOwnerCurrent || frozen != null || conflict ||
                    widget.session.supplierMoneyFormKey(widget.supplierMoney!.supplierId,
                      copy: widget.supplierMoney!.copy, advance: widget.supplierMoney!.advance) != draft.key) { return false; }
                setState(() => supportingCopies = value);
                draft.save(fields);
                return draft.flush();
              }),
            if (error != null || draft.error != null)
              Text(error ?? draft.error!),
            if (_originalExpense && _expenseIntent != null) ...[
              Text(_expenseStatus == 'not_saved' ? 'This expense was not recorded. Close and reopen to review the saved input.'
                : 'Keep this expense request until its saved status is confirmed.', key: const Key('store-expense-attempt-status')),
              TextButton(key: const Key('store-expense-check-status'),
                onPressed: saving ? null : _checkOriginalExpense, child: const Text('Check saved status')),
              if (_expenseStatus == null) TextButton(key: const Key('store-expense-retry-original'),
                onPressed: saving ? null : () => _checkOriginalExpense(explicitRetry: true), child: const Text('Retry same expense')),
            ],
            if (!draft.ready && !_hasOriginalRequest)
              TextButton(
                onPressed: load,
                child: const Text('Retry opening saved input'),
              ),
            if (draft.error != null && draft.ready && !_hasOriginalRequest)
              TextButton(
                onPressed: saving || (manualMoney && conflict) ? null : () => draft.save(fields),
                child: const Text('Retry saving input'),
              ),
            if (!_compactSettled && _expenseIntent == null && (_moneyIntent == null || confirmed)) FilledButton(
              key: manualMoney ? const Key('supplier-money-submit') : _originalExpense ? const Key('store-expense-submit') : null,
              onPressed:
                  draft.ready && !saving && !draft.busy && draft.error == null &&
                    _editableExpense && !_settledBillInput && (!manualMoney || (moneyRecovered && !conflict))
                  ? manualMoney && confirmed ? recordAnother : submit
                  : null,
              child: Text(
                saving
                    ? 'Recording…'
                    : _settledBillInput ? 'No bill amount due'
                    : manualMoney ? confirmed ? widget.supplierMoney!.advance ? 'Record another advance' : 'Record another payment'
                        : frozen != null ? 'Retry same payment' : widget.supplierMoney!.advance ? 'Record advance paid' : 'Record payment'
                    : expense
                    ? _originalExpense ? 'Save expense' : 'Record test expense'
                    : 'Record test payment',
              ),
            ),
          ],
        ),
      )),
      ),
    ),
  );
}

class _CustomerCollectionSheet extends StatefulWidget {
  const _CustomerCollectionSheet({
    super.key,
    required this.session,
    required this.payment,
    required this.accountScope,
    required this.storeId,
    this.refund = false,
    this.counterSaleReceipt = false,
    this.onClose, this.reviewScope,this.preparedFields,this.capturedDraft,this.onPreparedDraft,
  });
  final StoreCustomerActionReviewScope? reviewScope;
  final Map<String,String>? preparedFields;
  final WorkspaceLedgerFormDraft? capturedDraft;
  final ValueChanged<Map<String,String>>? onPreparedDraft;
  final bool refund;
  final bool counterSaleReceipt;
  final VoidCallback? onClose;
  final WorkSession session;
  final WorkspacePaymentRecord payment;
  final String accountScope, storeId;
  @override
  State<_CustomerCollectionSheet> createState() =>
      _CustomerCollectionSheetState();
}

class _CustomerCollectionSheetState extends State<_CustomerCollectionSheet>
    with WidgetsBindingObserver {
  bool _preparedCompleted=false;
  bool _preparedCurrent()=>widget.reviewScope==null || mounted&&widget.reviewScope!.current()&&ModalRoute.of(context)?.isCurrent==true;
  Future<bool> _runPreparedNative(Future<bool> Function() run)=>widget.reviewScope?.runNative(run)??run();
  Future<bool> flushForNavigation() async =>
      !saving && !confirming && await draft.flush();
  final amount = TextEditingController();
  final reference = TextEditingController();
  final amountFocus = FocusNode();
  final referenceFocus = FocusNode();
  final _receiptContentKey = GlobalKey();
  bool _receiptRevealScheduled = false;
  bool get _inlineCounterReceipt =>
      widget.counterSaleReceipt && widget.onClose != null;
  late WorkspacePaymentChannel channel;
  String? sourceCollectionId;
  WorkspaceCustomerLedger? get refundLedger {
    final finance = widget.session.workspaceFinance;
    if (finance?.accountScope != widget.accountScope ||
        finance?.workspaceId != widget.storeId ||
        widget.session.activeWorkspace?.id != widget.storeId) {
      return null;
    }
    return finance?.customerLedgers.where((l) =>
        l.customerId == widget.payment.customerId && l.valid && l.historyComplete).firstOrNull;
  }
  List<WorkspaceCustomerLedgerEntry> get refundReceipts =>
      refundLedger?.entries.where((e) => e.valid &&
          e.invoiceId == widget.payment.invoiceId &&
          e.orderId == widget.payment.orderId &&
          e.kind == WorkspaceLedgerEntryKind.collection &&
          e.state == WorkspaceLedgerPostingState.posted).toList() ?? [];
  WorkspaceCustomerLedgerEntry? get sourceReceipt => refundReceipts
      .where((e) => e.id == sourceCollectionId).firstOrNull;
  String receiptRemainingLabel(WorkspaceCustomerLedgerEntry receipt) {
    final remaining = refundLedger?.receiptRemainingMinor(widget.payment.invoiceId!, receipt.id);
    return remaining == null ? 'Unavailable' : _purchaseAmount(remaining);
  }
  bool get sourceRefundSupported => sourceReceipt != null &&
      const [WorkspacePaymentChannel.cash, WorkspacePaymentChannel.directUpi,
        WorkspacePaymentChannel.bankTransfer].contains(sourceReceipt!.channel) &&
      refundLedger?.receiptRemainingMinor(widget.payment.invoiceId!, sourceCollectionId!) != null;
  bool get _bankTransfer => channel == WorkspacePaymentChannel.bankTransfer;
  bool get _needsReference =>
      _bankTransfer || channel == WorkspacePaymentChannel.directUpi;
  bool get _showPreparedReference=>_needsReference||widget.preparedFields?.containsKey("reference")==true;
  String get _referenceLabel => widget.preparedFields!=null&&channel==WorkspacePaymentChannel.cash ? (widget.refund?'Refund receipt reference (optional)':'Receipt reference (optional)') : widget.refund ? 'Refund transaction reference' : _bankTransfer
      ? 'Bank transaction reference'
      : 'UPI transaction reference';
  bool saving = false;
  bool confirming = false;
  String? error;
  String? amountError, referenceError;
  late final _LedgerFormAutosave draft;
  Map<String, String> get draftFields => {
    'amount': amount.text,
    'reference': reference.text,
    'channel': channel.name,
    if (widget.refund && sourceCollectionId != null) 'sourceCollectionId': sourceCollectionId!,
  };
  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    amountFocus.addListener(_scheduleReceiptReveal);
    referenceFocus.addListener(_scheduleReceiptReveal);
    final invoice = widget.session.workspaceInvoices
        .where(
          (invoice) =>
              invoice.id == widget.payment.invoiceId &&
              invoice.orderId == widget.payment.orderId,
        )
        .firstOrNull;
    // An unpaid ledger correctly has no recorded tender yet. Use the saved
    // invoice's intended method without changing that financial fact.
    channel =
        (!widget.refund && invoice?.payment == 'UPI') ||
            widget.payment.channel == WorkspacePaymentChannel.directUpi
        ? WorkspacePaymentChannel.directUpi
        : WorkspacePaymentChannel.cash;
    if (widget.counterSaleReceipt) {
      channel = switch (invoice?.payment) {
        'UPI' => WorkspacePaymentChannel.directUpi,
        'Bank Transfer' => WorkspacePaymentChannel.bankTransfer,
        _ => WorkspacePaymentChannel.cash,
      };
      amount.text = _formatStoreMinorAmount(
        widget.payment.dueMinor,
      ).replaceAll(',', '');
    }
    if (widget.refund) {
      final receipts = refundReceipts;
      if (receipts.length == 1) {
        sourceCollectionId = receipts.single.id;
        channel = receipts.single.channel;
      } else {
        channel = WorkspacePaymentChannel.unknown;
      }
    }
    draft = _LedgerFormAutosave(
      widget.session,
      widget.session.ledgerFormKey(
        widget.payment,
        widget.refund ? 'refund' : 'collection',
      ),
      inputOwnerCurrent:widget.reviewScope?.current,preparedFields:widget.preparedFields,capturedDraft:widget.capturedDraft,onPreparedDraft:widget.onPreparedDraft,
    );
    draft.addListener(refreshDraft);
    unawaited(loadDraft());
  }

  @override
  void didChangeMetrics() => _scheduleReceiptReveal();

  void _scheduleReceiptReveal() {
    if (!_inlineCounterReceipt ||
        _receiptRevealScheduled ||
        (!amountFocus.hasFocus && !referenceFocus.hasFocus)) {
      return;
    }
    _receiptRevealScheduled = true;
    // Run after EditableText's post-frame caret scrolling, which otherwise
    // overrides the form reveal during successive keyboard-inset changes.
    unawaited(
      WidgetsBinding.instance.endOfFrame.then((_) {
        _receiptRevealScheduled = false;
        if (!mounted ||
            !_inlineCounterReceipt ||
            (!amountFocus.hasFocus && !referenceFocus.hasFocus)) {
          return;
        }
        final target = _receiptContentKey.currentContext;
        if (target == null || !target.mounted) return;
        final box = target.findRenderObject();
        final scroll = Scrollable.maybeOf(target);
        if (box is! RenderBox || !box.hasSize || scroll == null) return;
        // Reveal the complete editor/action after IME and validation layout, not
        // only the text caret. On very short screens prioritise the active field
        // and retain ordinary scrolling rather than hide it to expose the button.
        final fits = box.size.height <= scroll.position.viewportDimension;
        final focused = referenceFocus.hasFocus ? referenceFocus : amountFocus;
        final reveal = fits ? target : focused.context;
        if (reveal == null || !reveal.mounted) return;
        unawaited(
          Scrollable.ensureVisible(
            reveal,
            alignment: fits ? 1 : .5,
            duration: const Duration(milliseconds: 180),
          ),
        );
      }),
    );
  }

  void refreshDraft() {
    if (mounted) {
      setState(() {});
    }
  }

  Future<void> loadDraft() async {
    final fields = await draft.load();
    if (!mounted || widget.reviewScope?.current()==false || fields == null) {
      return;
    }
    amount.text = fields['amount'] ?? amount.text;
    reference.text = fields['reference'] ?? '';
    if (!widget.counterSaleReceipt) {
      channel = switch (fields['channel']) {
        'directUpi' => WorkspacePaymentChannel.directUpi,
        'cash' => WorkspacePaymentChannel.cash,
        'bankTransfer' when widget.preparedFields!=null => WorkspacePaymentChannel.bankTransfer,
        _ => channel,
      };
    }
    if (widget.refund) {
      final savedSource = fields['sourceCollectionId'];
      if (refundReceipts.any((e) => e.id == savedSource)) sourceCollectionId = savedSource;
      channel = sourceReceipt?.channel ?? WorkspacePaymentChannel.unknown;
    }
    amount.addListener(saveDraft);
    reference.addListener(saveDraft);
    setState(() {});
  }

  void saveDraft() {
    draft.save(draftFields);
  }

  @override
  void dispose() {
    if(widget.preparedFields!=null)widget.onPreparedDraft?.call(draftFields);
    WidgetsBinding.instance.removeObserver(this);
    amountFocus.removeListener(_scheduleReceiptReveal);
    referenceFocus.removeListener(_scheduleReceiptReveal);
    draft.removeListener(refreshDraft);
    draft.dispose();
    amount.dispose();
    reference.dispose();
    amountFocus.dispose();
    referenceFocus.dispose();
    super.dispose();
  }

  int get limitMinor {
    if (!widget.refund) return widget.payment.dueMinor;
    final ledger = refundLedger;
    final credit = ledger?.invoiceBalance(widget.payment.invoiceId!)?.refundableMinor ?? 0;
    final remaining = sourceCollectionId == null ? 0 :
        ledger?.receiptRemainingMinor(widget.payment.invoiceId!, sourceCollectionId!) ?? 0;
    return remaining < credit ? remaining : credit;
  }

  Future<void> submit() async {
    if (_preparedCompleted || !_preparedCurrent() || saving || confirming || !draft.ready || draft.error != null) return;
    setState(() => confirming = true);
    try {
      await _submitCollection();
    } finally {
      if (mounted) {
        setState(() => confirming = false);
        _scheduleReceiptReveal();
      }
    }
  }

  Future<void> _submitCollection() async {
    if (!await draft.flush() || !mounted || !_preparedCurrent()) {
      return;
    }
    setState(() {
      amountError = null;
      referenceError = null;
      error = null;
    });
    if (widget.refund && !sourceRefundSupported) {
      setState(() => error = 'Select a verified original receipt. Refund allocation is unavailable for incomplete records.');
      return;
    }
    final text = amount.text.trim();
    if (!RegExp(r'^\d{1,10}(\.\d{1,2})?$').hasMatch(text)) {
      setState(
        () =>
            amountError = 'Enter a valid amount with up to two decimal places.',
      );
      amountFocus.requestFocus();
      return;
    }
    final parts = text.split('.');
    final minor =
        int.parse(parts[0]) * 100 +
        (parts.length == 1 ? 0 : int.parse(parts[1].padRight(2, '0')));
    if (minor <= 0) {
      setState(() => amountError = 'Enter an amount greater than zero.');
      amountFocus.requestFocus();
      return;
    }
    if (minor > limitMinor) {
      setState(
        () => amountError = 'Enter ${_purchaseAmount(limitMinor)} or less.',
      );
      amountFocus.requestFocus();
      return;
    }
    if (_needsReference && reference.text.trim().isEmpty) {
      setState(
        () => referenceError = 'Enter the ${_referenceLabel.toLowerCase()}.',
      );
      referenceFocus.requestFocus();
      return;
    }
    if (widget.session.workspaceFinance?.accountScope != widget.accountScope ||
        widget.session.workspaceFinance?.workspaceId != widget.storeId) {
      setState(() => error = 'Store changed. Return to the correct invoice.');
      return;
    }
    setState(() {
      saving = true;
      error = null;
    });
    final recorded = await _runPreparedNative(()=>widget.refund
        ? widget.session.recordCustomerRefund(
            customerId: widget.payment.customerId,
            invoiceId: widget.payment.invoiceId!,
            amountMinor: minor,
            channel: channel,
            reference: reference.text,
            sourceCollectionId: sourceCollectionId, reviewOwnerCurrent:widget.reviewScope?.ownerCurrent,reviewInputCurrent:widget.reviewScope==null?null:_preparedCurrent,onReviewNativeChange:widget.reviewScope?.acceptNativeChange,
          )
        : widget.session.recordCustomerCollection(
      customerId: widget.payment.customerId,
      invoiceId: widget.payment.invoiceId!,
      amountMinor: minor,
      channel: channel,
      reference: reference.text, reviewOwnerCurrent:widget.reviewScope?.ownerCurrent,reviewInputCurrent:widget.reviewScope==null?null:_preparedCurrent,onReviewNativeChange:widget.reviewScope?.acceptNativeChange,
    ));
    if (!mounted) return;
    if (recorded) {
      if(widget.reviewScope!=null)setState((){_preparedCompleted=true;saving=false;});
      if(widget.reviewScope!=null && (!widget.reviewScope!.current() || ModalRoute.of(context)?.isCurrent!=true))return;
      if (widget.onClose != null) {
        widget.onClose!();
      } else {
        _closeCapturedCustomerReview(context,widget.reviewScope);
      }
      return;
    }
    setState(() {
      saving = false;
      error = widget.refund
          ? 'Refund not confirmed. Close this sheet and check its status.'
          : 'Collection not confirmed. Close this sheet and check its status.';
    });
  }

  Widget _inlineReceipt() => Container(
    key: const Key('work-counter-inline-receipt'),
    margin: const EdgeInsets.only(top: 10, bottom: 8),
    padding: const EdgeInsets.symmetric(vertical: 4),
    decoration: const BoxDecoration(
      color: Colors.white,
      border: Border(top: BorderSide(color: _counterSaleLine)),
    ),
    child: Column(
      key: _receiptContentKey,
      crossAxisAlignment: CrossAxisAlignment.stretch,
      mainAxisSize: MainAxisSize.min,
      children: [
        Row(
          children: [
            Expanded(
              child: Text(
                _bankTransfer ? 'Bank transfer receipt' : 'Cash receipt',
                style: const TextStyle(fontWeight: FontWeight.w600),
              ),
            ),
            IconButton(
              tooltip: 'Close receipt entry',
              onPressed: saving || confirming
                  ? null
                  : () async {
                      if (await draft.flush() && mounted) widget.onClose!();
                    },
              icon: const Icon(Icons.close, size: 18),
            ),
          ],
        ),
        LayoutBuilder(
          builder: (context, constraints) {
            final input = TextField(
              key: const Key('collection-amount'),
              controller: amount,
              focusNode: amountFocus,
              enabled: !saving && !confirming && draft.ready,
              keyboardType: const TextInputType.numberWithOptions(
                decimal: true,
              ),
              textInputAction: _needsReference
                  ? TextInputAction.next
                  : TextInputAction.done,
              onSubmitted: (_) => _needsReference
                  ? referenceFocus.requestFocus()
                  : amountFocus.unfocus(),
              onChanged: (_) {
                if (amountError != null) {
                  setState(() => amountError = null);
                  _scheduleReceiptReveal();
                }
              },
              decoration: InputDecoration(
                labelText: 'Amount received',
                prefixText: '₹ ',
                errorText: amountError,
                errorMaxLines: 3,
                isDense: true,
                filled: false,
                border: InputBorder.none,
                enabledBorder: InputBorder.none,
                focusedBorder: InputBorder.none,
              ),
            );
            final action = TextButton(
              key: const Key('collection-confirm'),
              onPressed:
                  !draft.ready ||
                      draft.busy ||
                      draft.error != null ||
                      saving ||
                      confirming
                  ? null
                  : submit,
              child: Text(saving ? 'Checking…' : 'Record receipt'),
            );
            if (!_needsReference &&
                amountError == null &&
                constraints.maxWidth >= 300 &&
                MediaQuery.textScalerOf(context).scale(14) <= 16.8) {
              return Row(
                children: [
                  Expanded(child: input),
                  const SizedBox(width: 8),
                  action,
                ],
              );
            }
            return Column(
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                input,
                if (!_needsReference)
                  Align(alignment: Alignment.centerRight, child: action),
              ],
            );
          },
        ),
        if (_showPreparedReference) ...[
          const SizedBox(height: 12),
          TextField(
            key: const Key('collection-reference'),
            controller: reference,
            focusNode: referenceFocus,
            enabled: !saving && !confirming && draft.ready,
            textInputAction: TextInputAction.done,
            onSubmitted: (_) => referenceFocus.unfocus(),
            onChanged: (_) {
              if (referenceError != null) {
                setState(() => referenceError = null);
                _scheduleReceiptReveal();
              }
            },
            decoration: InputDecoration(
              labelText: _referenceLabel,
              errorText: referenceError,
              errorMaxLines: 3,
            ),
          ),
        ],
        if (_needsReference)
          TextButton(
            key: const Key('collection-confirm'),
            onPressed:
                !draft.ready ||
                    draft.busy ||
                    draft.error != null ||
                    saving ||
                    confirming
                ? null
                : submit,
            child: Text(saving ? 'Checking…' : 'Record receipt'),
          ),
        Text(
          _bankTransfer
              ? 'Confirm only after checking the credit in your bank account.'
              : 'Confirm only after receiving the cash.',
          style: const TextStyle(fontSize: 12, color: MoolColors.muted),
        ),
        if (draft.error != null) ...[
          Text(draft.error!),
          TextButton(
            onPressed: draft.busy
                ? null
                : () {
                    if (draft.ready) {
                      saveDraft();
                    } else {
                      unawaited(loadDraft());
                    }
                  },
            child: const Text('Retry saving input'),
          ),
        ],
        if (error != null) Text(error!),
      ],
    ),
  );

  @override
  Widget build(BuildContext context) {
    if(widget.reviewScope!=null&&_preparedCompleted)return _customerCompletedReview(context,widget.reviewScope!,widget.refund?"Refund recorded":"Receipt recorded");
    return widget.counterSaleReceipt && widget.onClose != null
      ? _inlineReceipt()
      : PopScope(
          canPop:
              widget.reviewScope?.current()==false || !saving &&
              !confirming &&
              !draft.busy &&
              (!draft.ready || draft.error == null),
          onPopInvokedWithResult: (didPop, result) async {
            if (!didPop &&
                !saving &&
                !confirming &&
                await draft.flush() &&
                context.mounted) {
              if (widget.onClose != null) {
                widget.onClose!();
              } else {
                _closeCapturedCustomerReview(context,widget.reviewScope);
              }
            }
          },
          child: SafeArea(
            top: false,
            child: Padding(
              padding: EdgeInsets.only(
                bottom: widget.onClose == null
                    ? MediaQuery.viewInsetsOf(context).bottom
                    : 0,
              ),
              child: _StoreFormLayout(
                compact: true,
                action: ListenableBuilder(
                  listenable: Listenable.merge([amountFocus, referenceFocus]),
                  builder: (context, action) => Row(
                    children: [
                      if (amountFocus.hasFocus || referenceFocus.hasFocus)
                        IconButton(
                          key: const Key('ledger-hide-keyboard'),
                          tooltip: 'Hide keyboard',
                          onPressed: () {
                            amountFocus.unfocus();
                            referenceFocus.unfocus();
                          },
                          icon: const Icon(Icons.keyboard_hide_outlined),
                        ),
                      Expanded(child: action!),
                    ],
                  ),
                  child: FilledButton(
                  key: Key(
                    widget.refund ? 'refund-confirm' : 'collection-confirm',
                  ),
                  style: widget.counterSaleReceipt
                      ? FilledButton.styleFrom(
                          backgroundColor: const Color(0xFFF0F1F7),
                          foregroundColor: MoolColors.navy,
                          minimumSize: const Size(48, 48),
                        )
                      : null,
                  onPressed:
                      !draft.ready ||
                          draft.busy ||
                          draft.error != null ||
                          saving ||
                          confirming ||
                          (widget.refund &&
                              (widget.session.pendingCustomerRefund != null || !sourceRefundSupported))
                      ? null
                      : submit,
                  child: Text(
                    saving
                        ? 'Checking…'
                        : widget.refund
                        ? 'Confirm refund'
                        : widget.counterSaleReceipt
                        ? 'Record receipt'
                        : 'Confirm collection',
                  ),
                ),
                ),
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    Row(
                      children: [
                        Expanded(
                          child: Text(
                            widget.refund
                                ? 'Record refund'
                                : widget.counterSaleReceipt
                                ? 'Payment receipt'
                                : 'Record collection',
                            style: widget.counterSaleReceipt
                                ? const TextStyle(
                                    fontSize: 18,
                                    fontWeight: FontWeight.w700,
                                    color: MoolColors.ink,
                                  )
                                : Theme.of(context).textTheme.titleLarge,
                          ),
                        ),
                        IconButton(
                          key: Key(widget.refund ? 'refund-close' : 'collection-close'),
                          tooltip: 'Close',
                          onPressed: saving || confirming
                              ? null
                              : () => Navigator.maybePop(context),
                          icon: const Icon(Icons.close, size: 20),
                        ),
                      ],
                    ),
                    if (widget.counterSaleReceipt) const SizedBox(height: 6),
                    Text(
                      '${widget.payment.customerName} · ${widget.payment.invoiceId}',
                      style: widget.counterSaleReceipt
                          ? const TextStyle(
                              fontSize: 12,
                              color: MoolColors.muted,
                            )
                          : null,
                    ),
                    if (widget.counterSaleReceipt) const SizedBox(height: 14),
                    if (!widget.counterSaleReceipt)
                      Text(
                        widget.refund && !sourceRefundSupported
                            ? 'Select an original payment with verified refund availability.'
                            : '${widget.refund ? 'Maximum refund now' : 'Due'} ${_purchaseAmount(limitMinor)}',
                      ),
                    if (widget.refund) ...[
                      if (sourceRefundSupported &&
                          refundLedger?.invoiceBalance(widget.payment.invoiceId!) != null)
                        Text(
                          'Limited to the lower of invoice refund credit '
                          '${_purchaseAmount(refundLedger!.invoiceBalance(widget.payment.invoiceId!)!.refundableMinor)} '
                          'and the selected payment’s remaining refundable amount.',
                          key: const Key('refund-limit-explanation'),
                          style: const TextStyle(fontSize: 12, color: MoolColors.muted),
                        ),
                      const Text('Original payment', style: TextStyle(fontWeight: FontWeight.w600)),
                      if (refundReceipts.isEmpty)
                        const Text('Original payment details unavailable.')
                      else
                        for (final receipt in refundReceipts)
                          TextButton.icon(
                            key: ValueKey('refund-source-${receipt.id}'),
                            onPressed: saving || confirming ? null : () {
                              setState(() {
                                sourceCollectionId = receipt.id;
                                channel = receipt.channel;
                                reference.clear();
                                amountError = null;
                              });
                              saveDraft();
                            },
                            icon: Icon(sourceCollectionId == receipt.id ? Icons.radio_button_checked : Icons.radio_button_unchecked, size: 18),
                            label: Text('${receipt.channel.label} · ${_purchaseAmount(receipt.amountMinor)} · '
                                '${MaterialLocalizations.of(context).formatShortDate(receipt.occurredAt.toLocal())}\n'
                                'Payment refundable balance: ${receiptRemainingLabel(receipt)}'),
                          ),
                      if (sourceReceipt?.paymentReference?.isNotEmpty == true)
                        Text('Original transaction: ${sourceReceipt!.paymentReference}', key: const Key('refund-original-reference')),
                      if (sourceReceipt != null && channel != WorkspacePaymentChannel.cash)
                        const Text('Original payer account details unavailable. Confirm the customer’s destination before returning money. Original-payment refunds require a connected payment provider.', key: Key('refund-account-guidance')),
                      const SizedBox(height: 16),
                    ],
                    _StoreAmountWidth(
                      controller: amount,
                      child: TextField(
                      key: Key(
                        widget.refund ? 'refund-amount' : 'collection-amount',
                      ),
                      controller: amount,
                      focusNode: amountFocus,
                      onChanged: (_) {
                        if (amountError != null) {
                          setState(() => amountError = null);
                        }
                      },
                      textInputAction: _needsReference
                          ? TextInputAction.next
                          : TextInputAction.done,
                      onSubmitted: (_) => _needsReference
                          ? referenceFocus.requestFocus()
                          : amountFocus.unfocus(),
                      enabled: !saving && !confirming && draft.ready,
                      keyboardType: const TextInputType.numberWithOptions(
                        decimal: true,
                      ),
                      decoration: InputDecoration(
                        errorText: amountError,
                        errorMaxLines: 3,
                        labelText: widget.refund
                            ? 'Amount refunded (₹)'
                            : widget.counterSaleReceipt
                            ? 'Amount received'
                            : 'Amount received (₹)',
                        prefixText: widget.counterSaleReceipt ? '₹ ' : null,
                      ),
                      ),
                    ),
                    if (widget.counterSaleReceipt)
                      Padding(
                        padding: const EdgeInsets.symmetric(vertical: 8),
                        child: Text(
                          'Payment method: ${_bankTransfer
                              ? 'Bank Transfer'
                              : channel == WorkspacePaymentChannel.cash
                              ? 'Cash'
                              : 'UPI'}',
                          key: const Key('work-counter-receipt-method'),
                        ),
                      )
                    else if (!widget.refund)
                      Wrap(
                        spacing: 8,
                        children: [
                          for (final mode in [
                            WorkspacePaymentChannel.cash,
                            WorkspacePaymentChannel.directUpi,
                          ])
                            ChoiceChip(
                              label: Text(
                                mode == WorkspacePaymentChannel.cash
                                    ? 'Cash'
                                    : 'UPI',
                              ),
                              selected: channel == mode,
                              onSelected: saving || confirming || !draft.ready
                                  ? null
                                  : (_) {
                                      setState(() => channel = mode);
                                      saveDraft();
                                    },
                            ),
                        ],
                      ),
                    if (widget.refund && _needsReference)
                      const SizedBox(height: 16),
                    if (_showPreparedReference)
                      TextField(
                        key: Key(
                          widget.refund
                              ? 'refund-reference'
                              : 'collection-reference',
                        ),
                        controller: reference,
                        focusNode: referenceFocus,
                        enabled: !saving && !confirming && draft.ready,
                        textInputAction: TextInputAction.done,
                        onSubmitted: (_) => referenceFocus.unfocus(),
                        onChanged: (_) {
                          if (referenceError != null) {
                            setState(() => referenceError = null);
                          }
                        },
                        decoration: InputDecoration(
                          labelText: _referenceLabel,
                          errorText: referenceError,
                          errorMaxLines: 3,
                        ),
                      ),
                    Text(
                      widget.refund
                          ? 'Record money already returned to this customer. This does not transfer money.'
                          : 'Record a payment already received. This does not request or transfer money.',
                    ),
                    if (draft.error != null) ...[
                      Text(draft.error!),
                      TextButton(
                        onPressed: draft.busy
                            ? null
                            : () {
                                if (draft.ready) {
                                  saveDraft();
                                } else {
                                  unawaited(loadDraft());
                                }
                              },
                        child: const Text('Retry saving input'),
                      ),
                    ],
                    if (error != null) Text(error!),
                  ],
                ),
              ),
            ),
          ),
        );
  }
}

class _MoneyDestinationSurface extends StatelessWidget {
  const _MoneyDestinationSurface({required this.session});

  final WorkSession session;

  @override
  Widget build(BuildContext context) {
    if (!session.workspaceFinanceUsesLegacyReview) {
      return _StoreFinanceSurface(session: session);
    }
    final orders = session.filteredWorkspaceMoneyOrders;
    final pendingFulfilment = orders
        .where(
          (order) => order.stage != 'Completed' && order.stage != 'Cancelled',
        )
        .fold<int>(0, (total, order) => total + order.payableMinor);
    final settlementActivity = session.workspaceActivity
        .where(
          (entry) =>
              entry.message.toLowerCase().contains('settlement') ||
              entry.message.toLowerCase().contains('order'),
        )
        .take(5)
        .toList();
    return Container(
      key: const Key('work-money-destination'),
      color: Colors.white,
      child: ListView(
        padding: const EdgeInsets.fromLTRB(12, 12, 12, 20),
        children: [
          const Text(
            'Settlement',
            style: TextStyle(
              color: MoolColors.muted,
              fontSize: 16,
              fontWeight: FontWeight.w900,
            ),
          ),
          const SizedBox(height: 6),
          _StoreScaledPair(
            crossAxisAlignment: CrossAxisAlignment.center,
            forceStack: session.workspaceSettlementEligible >= 10000000,
            first: _StoreMoneyText(
              '₹${_formatStoreAmount(session.workspaceSettlementEligible)}',
              style: const TextStyle(
                color: MoolColors.navy,
                fontSize: 24,
                height: 1,
                fontWeight: FontWeight.w900,
              ),
            ),
            second: TextButton.icon(
              key: const Key('work-money-request-settlement'),
              onPressed:
                  session.workspaceSettlementEligible > 0 && !session.busy
                  ? () => _showWorkspaceSettlementReview(context, session)
                  : null,
              style: TextButton.styleFrom(
                foregroundColor: MoolColors.navy,
                padding: const EdgeInsets.symmetric(
                  horizontal: 14,
                  vertical: 12,
                ),
                minimumSize: const Size(48, 48),
              ),
              icon: const Icon(Icons.account_balance_outlined, size: 18),
              label: const Text(
                'Review payout',
                textAlign: TextAlign.center,
                style: TextStyle(fontSize: 12),
              ),
            ),
          ),
          const Text(
            'Recorded balance',
            style: TextStyle(fontSize: 12, color: MoolColors.muted),
          ),
          if (session.workspaceSettlementEligible <= 0)
            const Text(
              'No balance available for payout.',
              style: TextStyle(fontSize: 12, color: MoolColors.muted),
            ),
          const SizedBox(height: 8),
          for (final fact in [
            ('Sales today', session.workspaceSalesTodayMinor),
