final _deliverySettingsEditors = <_WorkspaceDeliverySettingsSurfaceState>{};
final _staffSettingsEditors = <_WorkspaceStaffSettingsSurfaceState>{};

class _WorkspaceDeliverySettingsSurface extends StatefulWidget {
  const _WorkspaceDeliverySettingsSurface({required this.session, this.initialData, this.reviewScope});
  final StoreSettingsInitialData? initialData;
  final StoreSettingsReviewScope? reviewScope;

  final WorkSession session;

  @override
  State<_WorkspaceDeliverySettingsSurface> createState() =>
      _WorkspaceDeliverySettingsSurfaceState();
}

class _WorkspaceDeliverySettingsSurfaceState
    extends State<_WorkspaceDeliverySettingsSurface> {
  late final String? _storeId;
  late final int? _scopeRevision;
  late final Object _pickupContext;
  late Future<bool> _pickupLoad;
  @override
  void initState() {
    super.initState();
    _deliverySettingsEditors.add(this);
    _storeId = widget.session.activeWorkspace?.id ?? widget.session.workspaceId;
    _scopeRevision = widget.session.navigationScopeRevision;
    _city = TextEditingController(text: widget.session.workspaceDeliveryCity);
    _area = TextEditingController(text: widget.session.workspaceDeliveryArea);
    _pincode = TextEditingController(text: widget.session.workspaceDeliveryPincode);
    _pickupEnabled = widget.session.workspacePickupEnabled;
    _pickupContext = widget.session.pickupPreferencesContext;
    _pickupLoad = _loadPickupPreferences();
  }
  late final TextEditingController _city, _area, _pincode;
  late bool _pickupEnabled;
  String? _privateSourceProof;
  String get _pickupInputSignature => jsonEncode([_city.text, _area.text, _pincode.text, _pickupEnabled]);
  bool get _currentPickup => mounted && widget.reviewScope?.current() != false &&
    _pickupContext == widget.session.pickupPreferencesContext && _scopeRevision == widget.session.navigationScopeRevision &&
    _storeId == (widget.session.activeWorkspace?.id ?? widget.session.workspaceId);

  bool get _pickupInputsChanged =>
      _city.text.trim() != widget.session.workspaceDeliveryCity ||
      _area.text.trim() != widget.session.workspaceDeliveryArea ||
      _pincode.text.trim() != widget.session.workspaceDeliveryPincode ||
      _pickupEnabled != widget.session.workspacePickupEnabled;

  Future<bool> _loadPickupPreferences() async {
    final inputSignature = _pickupInputSignature;
    var loaded = await widget.session.loadWorkspacePickupPreferences(expectedStoreId: _storeId ?? '');
    if (!mounted || widget.reviewScope?.mayApply == false || _pickupContext != widget.session.pickupPreferencesContext) return false;
    if (loaded && widget.session.workspaceOriginalPrivatePreferencesConfigured) {
      loaded = await widget.session.loadWorkspacePrivatePreferences(WorkspacePrivatePreferenceKind.pickup, refresh: true,
        inputPristine: () => _currentPickup && _pickupInputSignature == inputSignature);
      if (!_currentPickup) return false;
      if (!loaded && widget.session.workspacePrivatePreferencePending(WorkspacePrivatePreferenceKind.pickup) == null) return false;
      loaded = true;
      _privateSourceProof = widget.session.workspacePrivatePreferenceSourceProof(WorkspacePrivatePreferenceKind.pickup);
    }
    if (loaded) {
      _city.text = widget.session.workspaceDeliveryCity;
      _area.text = widget.session.workspaceDeliveryArea;
      _pincode.text = widget.session.workspaceDeliveryPincode;
      _pickupEnabled = widget.session.workspacePickupEnabled;
      final fields = widget.initialData?.fields ?? const <String, Object?>{};
      _city.text = fields['city'] as String? ?? _city.text;
      _area.text = fields['area'] as String? ?? _area.text;
      _pincode.text = fields['pincode'] as String? ?? _pincode.text;
      _pickupEnabled = fields['pickupEnabled'] as bool? ?? _pickupEnabled;
    }
    return loaded;
  }

  Future<void> _savePickupOriginal() async {
    const kind = WorkspacePrivatePreferenceKind.pickup;
    if (!_currentPickup || widget.reviewScope?.mayApply == false || !_privatePreferenceCanSave(widget.session, kind, _privateSourceProof)) {
      widget.session.showError('Check the saved pickup preferences before another Save. Your entries are kept.'); return;
    }
    final signature = _pickupInputSignature;
    final fields = <String, Object?>{'city': _city.text.trim(), 'area': _area.text.trim(),
      'pincode': _pincode.text.trim(), 'pickupEnabled': _pickupEnabled};
    if (widget.reviewScope?.beginAttempt(fields) == false) return;
    final accepted = widget.session.saveWorkspaceDeliverySettings(city: _city.text, area: _area.text, pincode: _pincode.text,
      pickupEnabled: _pickupEnabled, expectedStoreId: _storeId, expectedNavigationRevision: _scopeRevision);
    if (!accepted) return;
    if (widget.session.pickupPreferencesPersistenceAvailable && !await widget.session.workspacePickupPreferencesWrite) return;
    if (!_currentPickup || _pickupInputSignature != signature) return;
    widget.reviewScope?.completeAttempt();
    final saved = await _saveStorePrivatePreference(widget.session, kind, fields, originalProof: _privateSourceProof,
      reviewScope: widget.reviewScope, current: () => _currentPickup && _pickupInputSignature == signature);
    if (saved && _currentPickup) setState(() { _privateSourceProof = widget.session.workspacePrivatePreferenceSourceProof(kind); });
  }

  @override
  void dispose() {
    _deliverySettingsEditors.remove(this);
    _city.dispose();
    _area.dispose();
    _pincode.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return FutureBuilder<bool>(future: _pickupLoad, builder: (context, snapshot) {
      if (widget.reviewScope?.current() == false || _pickupContext != widget.session.pickupPreferencesContext) {
        return const Center(child: Text('Your Store or account changed. Reopen pickup settings. Your entries are kept.'));
      }
      if (snapshot.connectionState != ConnectionState.done) {
        return const Center(child: CircularProgressIndicator(semanticsLabel: 'Opening saved pickup preferences'));
      }
      if (snapshot.data != true) {
        return Center(child: Padding(padding: const EdgeInsets.all(16), child: Column(
          mainAxisSize: MainAxisSize.min, children: [
            Text(widget.session.workspacePrivatePreferenceError(WorkspacePrivatePreferenceKind.pickup) ?? widget.session.workspacePickupPreferencesError ?? 'Saved pickup preferences could not be opened.'),
            OutlinedButton(onPressed: () => setState(() { _pickupLoad = _loadPickupPreferences(); }),
              child: const Text('Try again')),
          ],
        )));
      }
      return AnimatedBuilder(animation: Listenable.merge([
        widget.session, _city, _area, _pincode,
      ]), builder: (context, _) => StoreSettingsForm(
      key: const Key('work-delivery-settings-screen'),
      title: 'Delivery & pickup',
      detail: widget.session.workspaceOriginalPrivatePreferencesConfigured
          ? widget.session.workspacePrivatePreferenceError(WorkspacePrivatePreferenceKind.pickup) ?? 'Set the pickup location and whether customers can collect.'
          : widget.session.pickupPreferencesPersistenceAvailable
          ? widget.session.workspacePickupPreferencesError ??
              (widget.session.workspacePickupPreferencesSaving ? 'Saving pickup preferences on this device…' :
               _pickupInputsChanged ? 'Unsaved changes. Save on this device to keep them. Public sync and collection confirmation are pending.' :
               widget.session.workspacePickupPreferencesSaved ? 'Saved on this device. Public sync and collection confirmation are pending.' :
               'Save your pickup preferences on this device. Public sync and collection confirmation are pending.')
          : 'Preferences apply in this session. Durable sync and MoolSocial delivery/collection confirmation are pending.',
      leading: widget.session.workspacePublicationDetails.city.trim().isNotEmpty &&
              widget.session.workspacePublicationDetails.street.trim().isNotEmpty &&
              RegExp(r'^[1-9][0-9]{5}$').hasMatch(widget.session.workspacePublicationDetails.pinCode)
          ? TextButton.icon(
              key: const Key('work-delivery-use-store-address'),
              icon: const Icon(Icons.storefront_outlined),
              label: const Text('Use saved Store address'),
              onPressed: () {
                if (_storeId != (widget.session.activeWorkspace?.id ?? widget.session.workspaceId) ||
                    _scopeRevision != widget.session.navigationScopeRevision) {
                  widget.session.showError('Your Store changed. Reopen these settings in the correct Store.');
                  return;
                }
                final details = widget.session.workspacePublicationDetails;
                _city.text = details.city;
                _area.text = details.street;
                _pincode.text = details.pinCode;
              },
            ) : null,
      fields: [
        StoreSettingsInput(
          id: 'work-delivery-city',
          label: 'Store city',
          controller: _city,
          validate: StoreSettingsInput.requiredText,
        ),
        StoreSettingsInput(
          id: 'work-delivery-pincode',
          label: 'PIN code',
          controller: _pincode,
          numeric: true,
          validate: StoreSettingsInput.pin,
        ),
        StoreSettingsInput(
          id: 'work-delivery-area',
          label: 'Pickup address / area',
          controller: _area,
          fullWidth: true,
          maxLines: 3,
          validate: StoreSettingsInput.requiredText,
        ),
      ],
      trailing: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          if (widget.session.workspaceOriginalPrivatePreferencesConfigured) _StorePrivatePreferenceRecovery(
            session: widget.session, kind: WorkspacePrivatePreferenceKind.pickup, current: () => _currentPickup, reviewScope: widget.reviewScope,
            onRecovered: () {if (_currentPickup) setState(() { _privateSourceProof = widget.session.workspacePrivatePreferenceSourceProof(WorkspacePrivatePreferenceKind.pickup); });},
            onReload: () async {if (_currentPickup) setState(() { _pickupLoad = _loadPickupPreferences(); });}),
          const Padding(
            padding: EdgeInsets.only(bottom: 6),
            child: Text(
              'Coverage & charges · Set by MoolSocial',
              key: Key('work-delivery-fleet-coverage'),
              style: TextStyle(fontSize: 12, color: MoolColors.muted),
            ),
          ),
          StoreSettingsCard(
            child: SwitchListTile.adaptive(
              key: const Key('work-delivery-pickup'),
              title: const Text('Allow Store pickup'),
              value: _pickupEnabled,
              onChanged: (value) => setState(() => _pickupEnabled = value),
            ),
          ),
        ],
      ),
      saveKey: 'work-delivery-settings-save',
      saveLabel: widget.session.workspaceOriginalPrivatePreferencesConfigured
          ? widget.session.workspacePrivatePreferenceBusy(WorkspacePrivatePreferenceKind.pickup) ? 'Saving…' : 'Save preferences'
          : widget.session.workspacePickupPreferencesSaving ? 'Saving…' :
          widget.session.pickupPreferencesPersistenceAvailable ? 'Save on this device' : 'Apply pickup preferences',
      saveEnabled: !widget.session.workspacePickupPreferencesSaving && (!widget.session.workspaceOriginalPrivatePreferencesConfigured || widget.session.workspacePrivatePreferenceReady(WorkspacePrivatePreferenceKind.pickup)),
      onSave: () {
        if (widget.session.workspaceOriginalPrivatePreferencesConfigured) {unawaited(_savePickupOriginal()); return;}
        if (widget.reviewScope?.mayApply == false || _pickupContext != widget.session.pickupPreferencesContext) {
          widget.session.showError('Your Store or account changed. Your entries are kept.');
          return;
        }
        final attempt = <String, Object?>{'city': _city.text.trim(), 'area': _area.text.trim(),
          'pincode': _pincode.text.trim(), 'pickupEnabled': _pickupEnabled};
        if (widget.reviewScope?.beginAttempt(attempt) == false) return;
        final accepted = widget.session.saveWorkspaceDeliverySettings(
          city: _city.text,
          area: _area.text,
          pincode: _pincode.text,
          pickupEnabled: _pickupEnabled,
          expectedStoreId: _storeId,
          expectedNavigationRevision: _scopeRevision,
        );
        final scope = widget.reviewScope;
        if (accepted && scope != null) {
          if (!widget.session.pickupPreferencesPersistenceAvailable) { scope.completeAttempt(); }
          else { unawaited(widget.session.workspacePickupPreferencesWrite.then((confirmed) {
            if (mounted && scope.current() && confirmed && widget.session.workspacePickupPreferencesSaved) scope.completeAttempt();
          })); }
        }
      },
    ));
    });
  }
}

class _WorkspaceStaffSettingsSurface extends StatefulWidget {
  const _WorkspaceStaffSettingsSurface({
    required this.session,
    this.embedded = false,
    this.initialData, this.reviewScope,
  });

  final WorkSession session;
  final bool embedded;
  final StoreSettingsInitialData? initialData;
  final StoreSettingsReviewScope? reviewScope;

  @override
  State<_WorkspaceStaffSettingsSurface> createState() =>
      _WorkspaceStaffSettingsSurfaceState();
}

class _WorkspaceStaffSettingsSurfaceState
    extends State<_WorkspaceStaffSettingsSurface> {
  late bool _enabled = widget.session.workspaceStaffAccessEnabled;
  late final TextEditingController _counters = TextEditingController(
    text: '${widget.session.workspaceCounterCount}',
  );

  late final _store = widget.session.activeWorkspace?.id ?? widget.session.workspaceId;
  late final _navigation = widget.session.navigationScopeRevision;
  late final _ownerContext = widget.session.publicationPreferencesContext;
  String? _privateSourceProof;
  bool _originalOpening = false, _originalAvailable = false;
  String get _staffInputSignature => jsonEncode([_enabled, _counters.text]);
  bool get _currentStaff => mounted && widget.reviewScope?.current() != false &&
    _store == (widget.session.activeWorkspace?.id ?? widget.session.workspaceId) && _navigation == widget.session.navigationScopeRevision &&
    _ownerContext == widget.session.publicationPreferencesContext;
  bool get _dirty => _enabled != widget.session.workspaceStaffAccessEnabled ||
    _counters.text != '${widget.session.workspaceCounterCount}';
  @override void initState() {
    super.initState(); _staffSettingsEditors.add(this);
    final fields = widget.initialData?.fields ?? const <String, Object?>{};
    _enabled = fields['staffAccessEnabled'] as bool? ?? _enabled;
    if (fields['counterCount'] != null) _counters.text = '${fields['counterCount']}';
    if (widget.session.workspaceOriginalPrivatePreferencesConfigured) unawaited(_loadOriginalStaff());
  }
  Future<void> _loadOriginalStaff() async {
    if (!_currentStaff) return;
    final signature = _staffInputSignature;
    setState(() => _originalOpening = true);
    final loaded = await widget.session.loadWorkspacePrivatePreferences(WorkspacePrivatePreferenceKind.staff, refresh: true,
      inputPristine: () => _currentStaff && _staffInputSignature == signature);
    if (!mounted) return;
    setState(() {
      _originalOpening = false;
      _originalAvailable = _currentStaff && (loaded || widget.session.workspacePrivatePreferencePending(WorkspacePrivatePreferenceKind.staff) != null);
      if (!_originalAvailable) return;
      _privateSourceProof = widget.session.workspacePrivatePreferenceSourceProof(WorkspacePrivatePreferenceKind.staff);
      _enabled = widget.session.workspaceStaffAccessEnabled; _counters.text = '${widget.session.workspaceCounterCount}';
      final fields = widget.initialData?.fields ?? const <String, Object?>{};
      _enabled = fields['staffAccessEnabled'] as bool? ?? _enabled;
      if (fields['counterCount'] != null) _counters.text = '${fields['counterCount']}';
    });
  }
  Future<void> _saveOriginalStaff() async {
    const kind = WorkspacePrivatePreferenceKind.staff;
    if (!_currentStaff || widget.reviewScope?.mayApply == false || !_privatePreferenceCanSave(widget.session, kind, _privateSourceProof)) {
      widget.session.showError('Check the saved staff preferences before another Save. Your entries are kept.'); return;
    }
    final count = int.tryParse(_counters.text.trim()), signature = _staffInputSignature;
    if (count == null || count < 1 || count > 20) {widget.session.showError('Enter a whole counter count from 1 to 20.'); return;}
    final fields = <String, Object?>{'staffAccessEnabled': _enabled, 'counterCount': count};
    if (widget.reviewScope?.beginAttempt(fields) == false) return;
    widget.session.saveWorkspaceStaffSettings(staffAccessEnabled: _enabled, counterCount: count);
    widget.reviewScope?.completeAttempt();
    final saved = await _saveStorePrivatePreference(widget.session, kind, fields, originalProof: _privateSourceProof,
      reviewScope: widget.reviewScope, current: () => _currentStaff && _staffInputSignature == signature);
    if (saved && _currentStaff) setState(() { _privateSourceProof = widget.session.workspacePrivatePreferenceSourceProof(kind); });
  }

  @override
  void dispose() {
    _staffSettingsEditors.remove(this);
    _counters.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    if (!_currentStaff) return const Center(child: Text('Your Store or account changed. Your entries are kept. Reopen staff settings.'));
    if (!widget.session.workspaceOriginalPrivatePreferencesConfigured) return _buildForm(context);
    if (_originalOpening) return const Center(child: CircularProgressIndicator(semanticsLabel: 'Opening saved staff preferences'));
    if (!_originalAvailable) return Center(child: Column(mainAxisSize: MainAxisSize.min, children: [
      Text(widget.session.workspacePrivatePreferenceError(WorkspacePrivatePreferenceKind.staff) ?? 'Saved staff preferences could not be opened.'),
      TextButton(onPressed: _loadOriginalStaff, child: const Text('Try again')),
    ]));
    return AnimatedBuilder(animation: widget.session, builder: (context, _) => _buildForm(context));
  }
  Widget _buildForm(BuildContext context) {
    return StoreSettingsForm(
      key: const Key('work-staff-settings-screen'),
      embedded: widget.embedded,
      title: 'Staff and counters',
      detail: 'Set up billing on your Store-managed devices.',
      leading: StoreSettingsCard(
        tonal: true,
        child: SwitchListTile.adaptive(
          key: const Key('work-staff-access-toggle'),
          value: _enabled,
          onChanged: (value) => setState(() => _enabled = value),
          title: const Text('Counter staff access'),
          subtitle: Text(_enabled ? 'On' : 'Off'),
        ),
      ),
      fields: [
        StoreSettingsInput(
          id: 'work-counter-count',
          label: 'Billing counters',
          controller: _counters,
          numeric: true,
          helper: '1–20 counters',
          validate: (value) => StoreSettingsInput.whole(value, 1, 20),
        ),
      ],
      trailing: widget.session.workspaceOriginalPrivatePreferencesConfigured ? Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
        const Text('Does not grant staff account access.'),
        _StorePrivatePreferenceRecovery(session: widget.session, kind: WorkspacePrivatePreferenceKind.staff, current: () => _currentStaff,
          reviewScope: widget.reviewScope, onRecovered: () {if (_currentStaff) setState(() { _privateSourceProof = widget.session.workspacePrivatePreferenceSourceProof(WorkspacePrivatePreferenceKind.staff); });},
          onReload: _loadOriginalStaff),
      ]) : const Text('Does not grant staff account access.'),
      saveKey: 'work-staff-settings-save',
      saveLabel: widget.session.workspacePrivatePreferenceBusy(WorkspacePrivatePreferenceKind.staff) ? 'Saving…' : 'Save staff controls',
      saveEnabled: !widget.session.workspaceOriginalPrivatePreferencesConfigured || widget.session.workspacePrivatePreferenceReady(WorkspacePrivatePreferenceKind.staff),
      onSave: () {
        if (!_currentStaff) return;
        if (widget.session.workspaceOriginalPrivatePreferencesConfigured) {unawaited(_saveOriginalStaff()); return;}
        if (widget.reviewScope != null && (!widget.reviewScope!.mayApply ||
            _store != (widget.session.activeWorkspace?.id ?? widget.session.workspaceId) ||
            _navigation != widget.session.navigationScopeRevision)) return;
        if (widget.reviewScope?.beginAttempt({'staffAccessEnabled': _enabled, 'counterCount': int.parse(_counters.text.trim())}) == false) return;
        widget.session.saveWorkspaceStaffSettings(
          staffAccessEnabled: _enabled,
          counterCount: int.parse(_counters.text.trim()),
        );
        widget.reviewScope?.completeAttempt();
      },
    );
  }
}

/// Inline Store-owned information. Verification is supplied, never inferred from
/// document count. Updates use the existing request draft; nothing is sent here.
/// One inline Settings editor. Stock management keeps its own existing screen.

/// Supplied facts only; unspecified controls retain the recovered native value.
class StoreProductDefaultsInitialData {
  StoreProductDefaultsInitialData._(this.fields);
  final Map<String, Object?> fields;
  static const allowedFields = <String>{
    'stockMode', 'lowStockThreshold', 'customerListingRequested',
  };
  factory StoreProductDefaultsInitialData.fromFields(Map<String, Object?> fields) {
    if (fields.isEmpty || fields.keys.any((key) => !allowedFields.contains(key))) {
      throw const FormatException('Supply an existing product default.');
    }
    if (fields.containsKey('stockMode') &&
        fields['stockMode'] != 'exactQuantity' && fields['stockMode'] != 'availabilityOnly') {
      throw const FormatException('Choose an existing stock mode.');
    }
    if (fields.containsKey('customerListingRequested') && fields['customerListingRequested'] is! bool) {
      throw const FormatException('Supply the customer listing choice.');
    }
    if (fields.containsKey('lowStockThreshold')) {
      final raw = fields['lowStockThreshold'];
      final count = raw is String ? int.tryParse(raw.trim()) : null;
      if (count == null || count < 0 || count > 999999999) {
        throw const FormatException('Enter a whole count from 0 to 999999999.');
      }
    }
    return StoreProductDefaultsInitialData._(Map.unmodifiable(fields));
  }
}

final _defaultsEditors = Expando<Set<_StoreProductDefaultsSectionState>>();
bool _defaultsEditorBusy(WorkSession session) => _defaultsEditors[session]?.any(
  (state) => state.mounted && state._current &&
      (!state._initialized || state._dirty || state._saving || state.widget.reviewOwnerCurrent != null),
) == true;

class _StoreProductDefaultsAdapter implements MoolAssistantNativeAdapter {
  const _StoreProductDefaultsAdapter({required this.actionId, required this.readContext,
    required this.readSnapshot, required this.open});
  @override final String actionId;
  final MoolAssistantContext? Function() readContext;
  final Future<MoolAssistantNativeSnapshot?> Function(MoolAssistantContext, String?) readSnapshot;
  final Future<MoolAssistantReviewResult> Function(MoolAssistantProposal, bool Function()) open;
  @override Set<String> get allowedFields => actionId == 'AI-ACT-218'
      ? const <String>{} : StoreProductDefaultsInitialData.allowedFields;
  @override String? validateFields(Map<String, Object?> fields) {
    if (actionId == 'AI-ACT-218') return fields.isEmpty ? null : 'Viewing defaults takes no changes.';
    try { StoreProductDefaultsInitialData.fromFields(fields); return null; }
    on FormatException catch (error) { return error.message.toString(); }
  }
  @override Future<MoolAssistantNativeSnapshot?> snapshot(MoolAssistantContext ctx, String? entityId) =>
      readSnapshot(ctx, entityId);
  @override Future<MoolAssistantReviewResult> openReview(
    MoolAssistantProposal proposal, bool Function() isCurrent,
  ) async {
    final trusted = readContext();
    if (!isCurrent() || trusted == null || trusted.binding != proposal.binding ||
        proposal.actionId != actionId || validateFields(proposal.fields) != null) {
      return MoolAssistantReviewResult.stale;
    }
    return open(proposal, isCurrent);
  }
}

/// The existing controls, in a native route above AI; opening never saves.
Future<MoolAssistantReviewResult> showStoreProductDefaultsReview(
  BuildContext context, WorkSession session, {
  StoreProductDefaultsInitialData? initialData, required bool readOnly,
  required bool Function() isCurrent, required bool Function() ownerCurrent,
  Listenable? ownerChanges,
}) async {
  final trading = session.tradingPreferencesContext;
  final navigation = session.navigationScopeRevision;
  bool owner() => context.mounted && ownerCurrent() &&
      session.tradingPreferencesContext == trading && session.navigationScopeRevision == navigation;
  if (!owner() || !isCurrent() || _defaultsEditorBusy(session) || session.workspaceTradingPreferencesSaving) {
    return MoolAssistantReviewResult.stale;
  }
  await Navigator.of(context).push<void>(MaterialPageRoute<void>(builder: (_) =>
    _StoreProductDefaultsReviewPage(session: session, initialData: initialData,
      readOnly: readOnly, ownerCurrent: owner, prefillCurrent: () => owner() && isCurrent(),
      ownerChanges: Listenable.merge([session, ownerChanges]))));
  return owner() ? MoolAssistantReviewResult.opened : MoolAssistantReviewResult.stale;
}

class _StoreProductDefaultsReviewPage extends StatefulWidget {
  const _StoreProductDefaultsReviewPage({required this.session, required this.initialData,
    required this.readOnly, required this.ownerCurrent, required this.prefillCurrent,
    required this.ownerChanges});
  final WorkSession session;
  final StoreProductDefaultsInitialData? initialData;
  final bool readOnly;
  final bool Function() ownerCurrent, prefillCurrent;
  final Listenable ownerChanges;
  @override State<_StoreProductDefaultsReviewPage> createState() => _StoreProductDefaultsReviewPageState();
}
class _StoreProductDefaultsReviewPageState extends State<_StoreProductDefaultsReviewPage> {
  final _section = GlobalKey<_StoreProductDefaultsSectionState>();
  bool _allowPop = false, _closing = false;
  void _finish() {
    if (!mounted || _allowPop) return;
    setState(() => _allowPop = true);
    WidgetsBinding.instance.addPostFrameCallback((_) { if (mounted) Navigator.pop(context); });
  }
  Future<void> _close() async {
    if (_closing) return;
    if (_section.currentState?._saving == true) return;
    if (!widget.ownerCurrent() || widget.readOnly || _section.currentState?._dirty != true) {
      _finish(); return;
    }
    _closing = true;
    final discard = await showDialog<bool>(context: context, builder: (context) => AlertDialog(
      title: const Text('Discard default changes?'),
      content: const Text('Your entries have not been saved. Keep editing or discard these changes.'),
      actions: [TextButton(onPressed: () => Navigator.pop(context, false), child: const Text('Keep editing')),
        TextButton(onPressed: () => Navigator.pop(context, true), child: const Text('Discard changes'))]));
    _closing = false;
    if (mounted && (discard == true || !widget.ownerCurrent())) _finish();
  }
  @override Widget build(BuildContext context) => AnimatedBuilder(animation: widget.ownerChanges,
    builder: (context, _) {
      final current = widget.ownerCurrent();
      return PopScope<void>(canPop: _allowPop || !current || widget.readOnly,
        onPopInvokedWithResult: (didPop, _) { if (!didPop) unawaited(_close()); },
        child: Scaffold(appBar: AppBar(leading: BackButton(onPressed: _close),
          title: Text(widget.readOnly ? 'Product defaults' : 'Review product defaults')),
          body: SafeArea(child: SingleChildScrollView(padding: const EdgeInsets.all(16),
            child: Column(children: [
              // Keep original controllers alive for explicit native discard;
              // stale account/Store contents are never visible or actionable.
              Offstage(offstage: !current, child: StoreSettingsStyle(child: StoreProductDefaultsSection(
                key: _section, session: widget.session, initialData: widget.initialData,
                readOnly: widget.readOnly, initiallyExpanded: true,
                reviewOwnerCurrent: widget.ownerCurrent, prefillCurrent: widget.prefillCurrent))),
              if (!current) const Text('Your Store or account changed. Close this review and reopen Product controls. Your entries are kept here.'),
            ])))));
    });
}

class StoreProductDefaultsSection extends StatefulWidget {
  const StoreProductDefaultsSection({super.key, required this.session,
    this.initialData, this.readOnly = false, this.initiallyExpanded = false,
    this.reviewOwnerCurrent, this.prefillCurrent});
  final WorkSession session;
  final StoreProductDefaultsInitialData? initialData;
  final bool readOnly, initiallyExpanded;
  final bool Function()? reviewOwnerCurrent, prefillCurrent;
  @override
  State<StoreProductDefaultsSection> createState() =>
      _StoreProductDefaultsSectionState();
}

class _StoreProductDefaultsSectionState
    extends State<StoreProductDefaultsSection> {
  late final String? _scope;
  late final Object _inputContext;
  late final WorkSession _owner;
  late Future<bool> _load;
  bool _initialized = false, _saving = false;
  bool _count = true, _listing = false;
  final _low = TextEditingController();
  String? _error;
  bool _saved = false;
  bool _prefillRejected = false;
  int _editRevision = 0;
  (bool, bool, String)? _baseline;
  String? _sourceDefaults;
  bool get _dirty => _initialized && _baseline != (_count, _listing, _low.text);
  @override
  void initState() {
    super.initState();
    _scope = widget.session.activeWorkspace?.id ?? widget.session.workspaceId;
    _inputContext = widget.session.tradingPreferencesContext;
    _owner = widget.session;
    (_defaultsEditors[_owner] ??= <_StoreProductDefaultsSectionState>{}).add(this);
    _low.addListener(() { _editRevision++; });
    if (!widget.session.tradingPreferencesPersistenceAvailable) {
      _initializeInputs();
      _load = Future.value(true);
    } else { _load = _loadInputs(); }
  }
  bool get _current => identical(widget.session, _owner) &&
      _inputContext == widget.session.tradingPreferencesContext &&
      widget.reviewOwnerCurrent?.call() != false;
  void _initializeInputs() {
    if (widget.prefillCurrent?.call() == false) {
      _prefillRejected = true;
      return;
    }
    final defaults = widget.session.workspaceProductDefaults;
    _count = defaults.stockMode == WorkspaceStockMode.exactQuantity;
    _listing = defaults.customerListingRequested;
    _low.text = '${defaults.lowStockThreshold}';
    _saved = widget.session.workspaceProductDefaultsSaved;
    _sourceDefaults = jsonEncode(defaults.toJson());
    _baseline = (_count, _listing, _low.text);
    if (widget.initialData != null && widget.prefillCurrent?.call() != false) {
      final supplied = widget.initialData!.fields;
      if (supplied.containsKey('stockMode')) _count = supplied['stockMode'] == 'exactQuantity';
      if (supplied.containsKey('customerListingRequested')) _listing = supplied['customerListingRequested'] as bool;
      if (supplied.containsKey('lowStockThreshold')) _low.text = supplied['lowStockThreshold'] as String;
      _saved = false;
      _editRevision++;
    }
    _initialized = true;
  }
  Future<bool> _loadInputs() async {
    final id = _scope;
    final loaded = id != null && await widget.session.loadWorkspaceProductDefaults(expectedStoreId: id);
    if (loaded && mounted && _current && !_initialized) _initializeInputs();
    return loaded;
  }
  @override
  void dispose() {
    _defaultsEditors[_owner]?.remove(this);
    _low.dispose();
    super.dispose();
  }

  Future<void> _save() async {
    if (widget.readOnly || _saving || widget.session.workspaceTradingPreferencesSaving) return;
    if (widget.reviewOwnerCurrent != null &&
        _sourceDefaults != jsonEncode(widget.session.workspaceProductDefaults.toJson())) {
      setState(() => _error = 'Saved defaults changed. Reopen Product controls. Your entries are kept.');
      return;
    }
    final low = int.tryParse(_low.text.trim());
    if (!_current) {
      setState(() => _error = 'Your Store changed. Reopen Product controls.');
      return;
    }
    if (low == null || low < 0 || low > 999999999) {
      setState(() => _error = 'Enter a whole count from 0 to 999999999.');
      return;
    }
    final saved = widget.session.saveWorkspaceProductDefaults(
      WorkspaceProductDefaults(
        stockMode: _count
            ? WorkspaceStockMode.exactQuantity
            : WorkspaceStockMode.availabilityOnly,
        lowStockThreshold: low,
        customerListingRequested: _listing,
      ),
      expectedStoreId: _scope,
      expectedNavigationRevision: widget.session.navigationScopeRevision,
    );
    if (!saved) {
      setState(() { _error = widget.session.errorMessage ?? 'Defaults could not be updated.'; _saved = false; });
      return;
    }
    // Native Save accepted the local value. Preserve its existing retry path if
    // the device write fails; another owner's later change still fails above.
    _sourceDefaults = jsonEncode(widget.session.workspaceProductDefaults.toJson());
    setState(() { _saving = true; _saved = false; _error = null; });
    final confirmed = !widget.session.tradingPreferencesPersistenceAvailable ||
        await widget.session.workspaceTradingPreferencesWrite;
    if (!mounted) return;
    if (!_current) {
      setState(() { _saving = false; _error = 'Your Store or account changed. Reopen Product controls. Your entries are kept.'; });
      return;
    }
    setState(() {
      _saving = false;
      _error = confirmed ? null : widget.session.workspaceTradingPreferencesError ?? 'Device save could not be confirmed. Your entries are kept. Try again.';
      _saved = confirmed;
      if (confirmed) _baseline = (_count, _listing, _low.text);
    });
    if (confirmed) FocusScope.of(context).unfocus();
  }

  @override
  Widget build(BuildContext context) => FutureBuilder<bool>(future: _load,
    initialData: _initialized ? true : null, builder: (context, snapshot) {
      if (_prefillRejected || !_current) return const Text('Your Store or account changed. Reopen Product controls. Your entries are kept.');
      if (snapshot.data != true || !_initialized) {
        return ExpansionTile(title: const Text('Product controls'), children: [
          if (snapshot.connectionState != ConnectionState.done)
            const Padding(padding: EdgeInsets.all(12), child: CircularProgressIndicator(semanticsLabel: 'Opening saved product defaults'))
          else ...[
            Text(widget.session.workspaceTradingPreferencesError ?? 'Saved product defaults could not be opened.'),
            OutlinedButton(onPressed: () => setState(() { _load = _loadInputs(); }), child: const Text('Try again')),
          ],
        ]);
      }
      return AnimatedBuilder(animation: widget.session, builder: (context, _) =>
        AbsorbPointer(absorbing: _saving || widget.session.workspaceTradingPreferencesSaving,
          child: _editor(context)));
    });

  Widget _editor(BuildContext context) => ExpansionTile(
    initiallyExpanded: widget.initiallyExpanded,
    leading: const Icon(Icons.inventory_2_outlined),
    title: const Text('Product controls'),
    childrenPadding: const EdgeInsets.fromLTRB(16, 0, 16, 12),
    children: [
      const Align(
        alignment: Alignment.centerLeft,
        child: Text(
          'Defaults for new products only',
          style: TextStyle(fontSize: 12, color: MoolColors.ink),
        ),
      ),
      Row(
        children: [
          const Expanded(child: Text('Keep stock count')),
          Switch(
            key: const Key('work-default-stock-count'),
            value: _count,
            onChanged: widget.readOnly ? null : (v) => setState(() {
              _editRevision++;
              _count = v;
              _saved = false;
            }),
          ),
        ],
      ),
      Row(
        children: [
          const Expanded(child: Text('Offer to customers')),
          Switch(
            key: const Key('work-default-customer-listing'),
            value: _listing,
            onChanged: widget.readOnly ? null : (v) => setState(() {
              _editRevision++;
              _listing = v;
              _saved = false;
            }),
          ),
        ],
      ),
      const Align(
        alignment: Alignment.centerLeft,
        child: Text(
          'Review each product before publishing. CSV imports stay private.',
          style: TextStyle(fontSize: 12, color: MoolColors.ink),
        ),
      ),
      const SizedBox(height: 10),
      LayoutBuilder(
        builder: (context, constraints) {
          final style = Theme.of(context).textTheme.bodyLarge!;
          final measure = TextPainter(
            text: TextSpan(text: '${_low.text} units', style: style),
            textDirection: TextDirection.ltr,
            textScaler: MediaQuery.textScalerOf(context),
          )..layout();
          final width = (measure.width + 40)
              .clamp(104.0, constraints.maxWidth)
              .toDouble();
          measure.dispose();
          final field = SizedBox(
            width: width,
            child: TextField(
              key: const Key('work-default-low-stock'),
              controller: _low,
              enabled: _count && !widget.readOnly,
              keyboardType: TextInputType.number,
              textInputAction: TextInputAction.done,
              decoration: const InputDecoration(
                isDense: true,
                suffixText: 'units',
              ),
              onChanged: (_) => setState(() {
                _error = null;
                _saved = false;
              }),
              onSubmitted: widget.readOnly ? null : (_) => _save(),
            ),
          );
          if (constraints.maxWidth - width < 130 ||
              MediaQuery.textScalerOf(context).scale(14) > 20) {
            return Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                const Text('Low stock below'),
                const SizedBox(height: 6),
                field,
              ],
            );
          }
          return Row(
            children: [
              const Expanded(child: Text('Low stock below')),
              const SizedBox(width: 12),
              field,
            ],
          );
        },
      ),
      if (_error != null)
        Padding(
          padding: const EdgeInsets.only(top: 8),
          child: Text(
            _error!,
            style: TextStyle(color: Theme.of(context).colorScheme.error),
          ),
        ),
      if (_saved)
        Padding(
          padding: EdgeInsets.only(top: 8),
          child: Text(widget.session.tradingPreferencesPersistenceAvailable
              ? 'Defaults saved on this device. New products only.' : 'Defaults applied',
            style: const TextStyle(fontSize: 12)),
        ),
      const SizedBox(height: 10),
      Align(
        alignment: Alignment.centerRight,
        child: FilledButton(
          key: const Key('work-defaults-save'),
          onPressed: widget.readOnly || _saving || widget.session.workspaceTradingPreferencesSaving ? null : _save,
          child: Text(_saving ? 'Saving…' : 'Save defaults'),
        ),
      ),
    ],
  );
}

