  void _finishSavedBill(
    ({String orderId, WorkspaceCustomerInvoice? invoice}) submitted,
    Object identity,
  ) {
    if (_assistantMode) { _assistantCommitted = true; _assistantDirty = false; }
    setState(() => _error = null);
    // The central invoice is the confirmation; a duplicate global banner can
    // crowd its payment controls out of a compact, enlarged-text viewport.
    widget.session.clearMessages();
    FocusManager.instance.primaryFocus?.unfocus();
    if (_fulfilment == 'At the shop') {
      final invoice = submitted.invoice;
      if (invoice != null) {
        setState(() {
          _invoice = invoice;
          _collection = null;
          _invoiceAccount = widget.session.workspaceFinance?.accountScope;
          _invoiceStore = widget.session.activeWorkspace?.id;
          _stage = 'invoice';
        });
      }
    } else {
      widget.session.showNotice(
        _source == 'Phone'
            ? 'Delivery order saved. Confirm the order with the customer before dispatch.'
            : 'Delivery order saved. Pack the items before requesting a rider.',
      );
      widget.onArrangeDelivery(submitted.orderId);
    }
  }

