  Future<void> _openProduct(WorkspaceCatalogueItem product) async {
    if (!_assistantCurrent) return;
    if (_saving || _openingDraft || widget.session.counterDraftEditingBlocked) {
      return;
    }
    final identity = _currentDraftIdentity;
    final saleGeneration = widget.session.counterSaleGeneration;
    _productSearchFocus.unfocus();
    await Navigator.of(context).push<void>(
      MaterialPageRoute(
        builder: (_) => Theme(
          data: _counterSaleTheme(Theme.of(context)),
          child: _CounterStoreProductPage(
            session: widget.session,
            productId: product.id,
            quantity: _assistantMode ? () => _quantities[product.id] ?? 0 : null,
            adjust: _assistantMode ? (change) => _adjustQuantity(product.id,change) : null,
            ownerChanges: Listenable.merge([_ownerChanges,_assistantEdits]),
            isCurrent: () =>
                mounted && _assistantCurrent &&
                identity == _currentDraftIdentity &&
                saleGeneration == widget.session.counterSaleGeneration &&
                !widget.session.counterDraftEditingBlocked,
          ),
        ),
      ),
    );
  }

  Future<void> _scanProduct() async {
    if (!_assistantCurrent) return;
    if (_saving || _openingDraft || widget.session.counterDraftEditingBlocked) {
      return;
    }
    final identity = _currentDraftIdentity;
    final saleGeneration = widget.session.counterSaleGeneration;
    final code = await showStoreProductScanner(context,ownerCurrent: _assistantMode || _transferredOwner != null ? () => _assistantCurrent : null,ownerChanges: _ownerChanges);
    if (!mounted || !_assistantCurrent || code == null || code.trim().isEmpty) return;
    if (identity != _currentDraftIdentity ||
        saleGeneration != widget.session.counterSaleGeneration) {
      return;
    }
    _addScannedProduct(code);
  }

  void _toggleUsbScanner() {
    if (!_assistantCurrent) return;
    _clearScannerBuffer();
    final enable = !_usbScanMode || !_barcodeFocus.hasPrimaryFocus;
    setState(() => _usbScanMode = enable);
    if (_usbScanMode) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted && _usbScanMode) _barcodeFocus.requestFocus();
      });
    } else {
      _barcodeFocus.unfocus();
      _clearScannerBuffer();
    }
  }

  void _clearScannerBuffer() {
    _barcodeBuffer = '';
    _barcodeOverflow = false;
    _lastScannerKeyAt = null;
  }

  KeyEventResult _handleScannerKey(FocusNode node, KeyEvent event) {
    if (!_assistantCurrent || !_usbScanMode || !node.hasPrimaryFocus || _stage != 'items') {
      return KeyEventResult.ignored;
    }
    if (event is KeyRepeatEvent) return KeyEventResult.handled;
    if (event is! KeyDownEvent) return KeyEventResult.ignored;
    if (event.logicalKey == LogicalKeyboardKey.escape) {
      _toggleUsbScanner();
      return KeyEventResult.handled;
    }
    final now = DateTime.now();
    if (_lastScannerKeyAt != null &&
        now.difference(_lastScannerKeyAt!) > const Duration(seconds: 2)) {
      _clearScannerBuffer();
    }
    _lastScannerKeyAt = now;
    if (event.logicalKey == LogicalKeyboardKey.enter ||
        event.logicalKey == LogicalKeyboardKey.numpadEnter) {
      final code = _barcodeBuffer;
      final overflow = _barcodeOverflow;
      _clearScannerBuffer();
      if (overflow) {
        widget.session.showError('Scan the product again.');
      } else {
        _addScannedProduct(code);
      }
      return KeyEventResult.handled;
    }
    final character = event.character;
    if (character == null || character.runes.any((rune) => rune < 32)) {
      return KeyEventResult.ignored;
    }
    if (_barcodeBuffer.length + character.length > 128) {
      _barcodeOverflow = true;
    } else {
      _barcodeBuffer += character;
    }
    return KeyEventResult.handled;
  }

  void _addScannedProduct(String code) {
    if (!_assistantCurrent) return;
    if (_saving ||
        _openingDraft ||
        widget.session.counterDraftEditingBlocked ||
        _stage != 'items' ||
        code.trim().isEmpty) {
      return;
    }
    widget.session.clearMessages();
    final normalized = code.trim().toLowerCase();
    final matches = widget.session.workspaceCatalogueItems
        .where(
          (item) =>
              item.barcode.toLowerCase() == normalized ||
              item.sku.toLowerCase() == normalized ||
              item.canonicalId.toLowerCase() == normalized,
        )
        .toList(growable: false);
    if (matches.length > 1) {
      widget.session.showError(
        'More than one product matches this code. Search and choose the correct pack.',
      );
      return;
    }
    final product = matches.firstOrNull;
    if (product == null || !product.canSellAtCounter) {
      widget.session.showError(
        'This product is not available in your store inventory.',
      );
      return;
    }
    _adjustQuantity(product.id, 1);
  }

  Future<void> _editCustomer({bool returnToItems = true}) async {
    if (!_assistantCurrent) return;
    if (_openingDraft || _saving || widget.session.counterDraftEditingBlocked) {
      return;
    }
    FocusManager.instance.primaryFocus?.unfocus();
    setState(() {
      _customerReturnToItems = returnToItems;
      _stage = 'customer';
    });
  }

  Widget _customerPanel() => _StoreSaleCustomerSheet(
    key: _assistantMode ? ValueKey((_currentDraftIdentity,'assistant',_assistantSource)) : ValueKey(_currentDraftIdentity),
    initialValue:
        _customerInput ?? widget.session.counterCustomerInput ?? _customer.text,
    recentCustomers: _recentCustomers,
    billingDetails: _billing,
    billingCustomer: _billingCustomer,
    onBillingChanged: (details, mobile) {
      if (!_assistantCurrent) return;
      if (_assistantMode) { _assistantBilling = details; _assistantBillingCustomer = mobile ?? ''; _assistantDirty = true; }
      else { widget.session.updateWorkspaceCounterDetails(billingDetails: details,billingCustomer: mobile ?? ''); }
    },
    onClose: () {
      if (!_assistantCurrent) return;
      if (_storedCounterCustomerMobile(_customer.text) == null) {
        widget.onExit();
      } else {
        setState(() => _stage = 'items');
      }
    },
    onConfirmed: (selected) {
      if (!_assistantCurrent) return;
      setState(() {
        _customer.text = selected;
        _customerInput = null;
        _error = null;
        _stage = 'items';
      });
      _rememberDetails();
    },
    onDraftChanged: (value) {
      if (!_assistantCurrent) return;
      _customerInput = value;
      if (_assistantMode) { _assistantDirty = true; } else { widget.session.retainWorkspaceCounterCustomerInput(value); }
    },
  );

  @override
  Widget build(BuildContext context) {
    final body = _buildCounter(context);
    return _transferredOwner == null ? body : _StoreSalesOwnerSurface(current: () => _assistantCurrent,
      changes: _transferredChanges!,child: body);
  }
  Widget _buildCounter(BuildContext context) {
    final validPhone = _storedCounterCustomerMobile(_customer.text) != null;
    if (_openingDraft || widget.session.counterDraftLoading) {
      return const Center(
        child: CircularProgressIndicator(
          semanticsLabel: 'Opening your saved bill',
        ),
      );
    }
    if ((widget.session.counterDraftEditingBlocked || (_initial?.actionId == 'AI-ACT-292' || _assistantDiscardRequested)) && !_saving) {
      final draft = widget.session.retainedCounterDraft;
      return ListView(
        key: const Key('work-counter-draft-recovery'),
        padding: const EdgeInsets.all(16),
        children: [
          Text(
            widget.session.counterDraftError ?? 'Checking your saved bill…',
            style: const TextStyle(
              color: MoolColors.navy,
              fontWeight: FontWeight.w600,
            ),
          ),
          const SizedBox(height: 8),
          Align(
            alignment: Alignment.centerRight,
            child: FilledButton(
              key: const Key('work-counter-draft-retry'),
              style: FilledButton.styleFrom(minimumSize: const Size(48, 48)),
              onPressed: widget.session.counterDraftSubmitting
                  ? null
                  : () => _openDraft(retry: true),
              child: const Text('Try again'),
            ),
          ),
          if (draft != null) ...[
            const SizedBox(height: 12),
            Text(draft.customer),
            if (draft.submissionOrderId != null) Text(draft.submissionOrderId!),
            for (final line in draft.lines)
              ListTile(
                contentPadding: EdgeInsets.zero,
                title: Text('${line.name} · ${line.pack} × ${line.quantity}'),
                subtitle: Text(
                  '₹${_formatStoreAmount(line.lineTotalPaise ~/ 100)}.${(line.lineTotalPaise % 100).toString().padLeft(2, '0')}',
                ),
              ),
          ],
          if (widget.session.counterDraftCatalogueChanged ||
              (_initial?.actionId == 'AI-ACT-292' || _assistantDiscardRequested) && _assistantCurrent &&
              draft != null && draft.stage != WorkspaceCounterDraftStage.retired &&
              widget.session.counterDraftLoaded && !widget.session.counterDraftLoading &&
              !widget.session.counterDraftSubmitting && !widget.session.counterDraftNeedsReconciliation)
            TextButton(
              key: const Key('work-counter-draft-discard'),
              onPressed: () async {
                if (!_assistantCurrent) return;
                final discard = await showDialog<bool>(
                  context: context,
                  builder: (context) => AlertDialog(
                    title: const Text('Discard saved bill?'),
                    content: const Text(
                      'No order will be cancelled. This removes only the unfinished bill.',
                    ),
                    actions: [
                      TextButton(
                        onPressed: () => Navigator.pop(context, false),
                        child: const Text('Keep bill'),
                      ),
                      FilledButton(
                        onPressed: () => Navigator.pop(context, true),
                        child: const Text('Discard'),
                      ),
                    ],
                  ),
                );
                if (_assistantMode) {
                  if (discard != true || !mounted || !_assistantCurrent) return;
                  _assistantFinalStarted = true;
                  final removed = await widget.session.discardWorkspaceCounterDraft();
                  if (!mounted || !_nativeOwnerCurrent) return;
                  if (removed) { _assistantDirty = false; widget.session.startNewWorkspaceOrder(); widget.onExit(); }
                  return;
                }
                if (discard == true &&
                    mounted && _assistantCurrent &&
                    await widget.session.discardWorkspaceCounterDraft() &&
                    mounted && _assistantCurrent) {
                  widget.session.startNewWorkspaceOrder();
                  await _openDraft();
                }
              },
              child: const Text('Discard bill'),
            ),
        ],
      );
    }
    if (_invoice != null && (_stage == 'invoice' || _stage == 'payment')) {
      return Column(
        children: [
          Expanded(
            child: _StoreInvoiceSurface(
              key: ValueKey(_invoice!.id),
              embedded: true,
              counterAppearance: true,
              session: widget.session,
              invoice: _invoice!,
              ownerCurrent: _assistantMode || _transferredOwner != null ? () => _assistantCurrent : null,ownerChanges: _ownerChanges,
              onClose: _nextSale,
              receiptEditor:
                  _stage == 'payment' &&
                      _collection != null &&
                      _invoiceAccount != null &&
                      _invoiceStore != null
                  ? _CustomerCollectionSheet(
                      key: _collectionKey,
                      session: widget.session,
                      payment: _collection!,
                      accountScope: _invoiceAccount!,
                      storeId: _invoiceStore!,
                      counterSaleReceipt: true,
                      onClose: () => setState(() {
                        widget.session.clearMessages();
                        _collection = null;
                        _stage = 'invoice';
                      }),
                    )
                  : null,
              onRecord: (payment) {
                setState(() {
                  _collection = payment;
                  _stage = 'payment';
                });
                WidgetsBinding.instance.addPostFrameCallback((_) {
                  final target = _collectionKey.currentContext;
                  if (!mounted ||
                      _stage != 'payment' ||
                      _collection != payment ||
                      target == null) {
                    return;
                  }
                  unawaited(
                    Scrollable.ensureVisible(
                      target,
                      alignment: 1,
                      duration: const Duration(milliseconds: 180),
                    ),
                  );
                });
              },
            ),
          ),
          if (_stage == 'invoice')
            Padding(
              padding: const EdgeInsets.fromLTRB(12, 8, 12, 12),
              child: SizedBox(
                width: double.infinity,
                child: FilledButton.icon(
                  key: const Key('work-sale-next'),
                  style: FilledButton.styleFrom(
                    minimumSize: const Size(0, 48),
                    padding: const EdgeInsets.symmetric(
                      horizontal: 16,
                      vertical: 12,
                    ),
                  ),
                  onPressed: _nextSale,
                  icon: const Icon(Icons.add),
                  label: const Text('New sale'),
                ),
              ),
            ),
        ],
      );
    }
    if (_stage == 'customer') {
      return Material(color: Colors.white, child: _customerPanel());
    }
    if (_stage == 'review') return _reviewPanel();
    final query = _productSearch.text.trim().toLowerCase();
    final searchTerms = query
        .split(RegExp(r'\s+'))
        .where((term) => term.isNotEmpty);
    final products = widget.session.workspaceCatalogueItems
        .where(
          (product) => searchTerms.every(
            (term) =>
                '${product.title} ${product.brand} ${product.variant} ${product.pack} ${product.sku} ${product.barcode}'
                    .toLowerCase()
                    .contains(term),
          ),
        )
        .toList(growable: false);
    final enteredName = _billing.name.trim();
    final selectedCustomer = enteredName.isNotEmpty
        ? enteredName
        : _RecentCounterCustomer(
            _customer.text.trim(),
            _billing,
          ).label;
    final mobile = _storedCounterCustomerMobile(_customer.text.trim());
    final customerName =
        selectedCustomer.replaceAll(RegExp(r'\D'), '') == mobile
        ? 'Customer'
        : selectedCustomer.split('·').first.trim();
    final customerControls = Container(
      key: const Key('work-sale-compact-controls'),
      padding: const EdgeInsets.symmetric(horizontal: 12),
      decoration: const BoxDecoration(
        border: Border(bottom: BorderSide(color: Color(0xFFE9EDF5))),
      ),
      child: SizedBox(
        width: double.infinity,
        child: TextButton(
          key: const Key('work-sale-customer'),
          onPressed: _editCustomer,
          style: TextButton.styleFrom(
            minimumSize: const Size(48, 48),
            padding: const EdgeInsets.symmetric(horizontal: 4, vertical: 6),
            alignment: Alignment.centerLeft,
          ),
          child: Row(children: [Expanded(child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(
                customerName.isEmpty ? 'Customer' : customerName,
                key: const Key('work-sale-customer-label'),
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
                semanticsLabel: selectedCustomer,
                style: const TextStyle(
                  fontSize: 13,
                  fontWeight: FontWeight.w600,
                ),
              ),
              if (mobile != null)
                Text(
                  '+91 $mobile',
                  key: const Key('work-sale-customer-mobile'),
                  style: const TextStyle(fontSize: 12, color: MoolColors.muted),
                ),
            ],
          )), const Icon(Icons.edit_outlined, size: 16, key: Key('work-sale-customer-edit'))]),
        ),
      ),
    );
    final controls = Column(
      mainAxisSize: MainAxisSize.min,
      children: [
        Padding(
          padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
          child: Semantics(
            textField: true,
            label: 'Search store products',
            onTap: _productSearchFocus.requestFocus,
            child: StoreRecentSearches(
              controller: _productSearch,
              focusNode: _productSearchFocus,
              history: widget.session.workspaceRecentSearches(
                'counter-products',
              ),
              onChanged: (_) => setState(() {}),
              child: TextField(
                key: const Key('work-counter-product-search'),
                controller: _productSearch,
                focusNode: _productSearchFocus,
                onChanged: (_) => setState(() {}),
                onSubmitted: (_) => _productSearchFocus.unfocus(),
                textInputAction: TextInputAction.search,
                style: const TextStyle(
                  fontSize: 13,
                  fontWeight: FontWeight.w600,
                ),
                decoration: InputDecoration(
                  hintText: MediaQuery.textScalerOf(context).scale(13) > 17
                      ? 'Search'
                      : 'Search Store stock',
                  isDense: true,
                  filled: false,
                  prefixIcon: const Icon(Icons.search_rounded, size: 21),
                  border: InputBorder.none,
                  enabledBorder: InputBorder.none,
                  focusedBorder: InputBorder.none,
                  contentPadding: const EdgeInsets.symmetric(vertical: 12),
                  suffixIcon: Row(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      if (query.isNotEmpty)
                        IconButton(
                          key: const Key('work-counter-search-clear'),
                          tooltip: 'Clear search',
                          icon: const Icon(Icons.clear),
                          onPressed: () {
                            setState(_productSearch.clear);
                            _productSearchFocus.requestFocus();
                          },
                        ),
                      IconButton(
                        key: const Key('work-counter-camera-scan'),
                        tooltip: 'Scan product',
                        onPressed: () {
                          _productSearchFocus.unfocus();
                          _scanProduct();
                        },
                        icon: const Column(mainAxisSize: MainAxisSize.min, children: [
                          Icon(Icons.qr_code_scanner, size: 18),
                          Text('Camera', style: TextStyle(fontSize: 9)),
                        ]),
                      ),
                      IconButton(
                        key: const Key('work-counter-usb-scan'),
                        tooltip: _usbScanMode
                            ? 'Stop attached scanner'
                            : 'Use attached scanner',
                        onPressed: _toggleUsbScanner,
                        isSelected: _usbScanMode,
                        icon: const Column(mainAxisSize: MainAxisSize.min, children: [
                          Icon(Icons.barcode_reader, size: 18),
                          Text('Scanner', style: TextStyle(fontSize: 9)),
                        ]),
                      ),
                    ],
                  ),
                ),
              ),
            ),
          ),
        ),
        customerControls,
      ],
    );
    final hasStoreStock = widget.session.workspaceCatalogueItems.isNotEmpty;
    final emptyProducts = Center(
      child: SingleChildScrollView(
        padding: const EdgeInsets.all(12),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            if (!hasStoreStock) ...[
              const Icon(
                Icons.shopping_cart_outlined,
                size: 32,
                color: MoolColors.navy,
              ),
              const SizedBox(height: 8),
              const Text(
                'No stock yet',
                style: TextStyle(fontSize: 16, fontWeight: FontWeight.w700),
              ),
              const SizedBox(height: 4),
              const Text(
                'Add products to your Store to start billing.',
                textAlign: TextAlign.center,
                style: TextStyle(color: MoolColors.muted, fontSize: 13),
              ),
              const SizedBox(height: 8),
              OutlinedButton.icon(
                onPressed: widget.onOpenCatalogue,
                icon: const Icon(Icons.add_rounded),
                label: const Text('Add products'),
              ),
              const SizedBox(height: 8),
            ],
            if (hasStoreStock)
              Text(
                query.isNotEmpty
                    ? 'No products match your search'
                    : 'Add products to Store stock to start billing.',
                style: const TextStyle(color: MoolColors.muted, fontSize: 13),
                textAlign: TextAlign.center,
              ),
          ],
        ),
      ),
    );
    var errorText =
        widget.session.counterDraftError ??
        _error ??
        (widget.fullScreen ? widget.session.errorMessage : null);
    // The shared Sales shell already announces session errors. Keep local
    // draft/retry failures here, without repeating the same global message.
    if (widget.session.counterDraftError == null &&
        errorText == widget.session.errorMessage &&
        context.findAncestorWidgetOfExactType<WorkPageScaffold>() != null) {
      errorText = null;
    }
    final error = errorText == null
        ? null
        : Padding(
            padding: const EdgeInsets.fromLTRB(16, 4, 16, 8),
            child: Semantics(
              liveRegion: true,
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    errorText,
                    key: const Key('work-order-error'),
                    style: const TextStyle(color: Color(0xFFB42318)),
                  ),
                  if (widget.session.counterDraftError != null)
                    TextButton(
                      key: const Key('work-counter-draft-save-retry'),
                      onPressed: _saving ? null : () => _openDraft(retry: true),
                      child: const Text('Try again'),
                    ),
                ],
              ),
            ),
          );
    final total = Container(
      key: const Key('work-sale-total-bar'),
      padding: const EdgeInsets.fromLTRB(16, 6, 16, 6),
      decoration: const BoxDecoration(
        color: _counterSaleTint,
        border: Border(top: BorderSide(color: _counterSaleLine), bottom: BorderSide(color: _counterSaleLine)),
      ),
      child: _StoreScaledPair(
        forceStack: _subtotal >= 1000000000,
        first: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(
              '$_selectedUnits ${_selectedUnits == 1 ? 'unit' : 'units'}',
              style: const TextStyle(color: MoolColors.muted, fontSize: 12),
            ),
            _StoreMoneyText(
              _discountError == null
                  ? '₹${_formatStoreMinorAmount(_payable)}'
                  : 'Review discount',
              style: const TextStyle(
                color: MoolColors.navy,
                fontSize: 23,
                fontWeight: FontWeight.w800,
              ),
            ),
          ],
        ),
        second: FilledButton(
          key: const Key('work-order-review'),
          onPressed:
              _saving ||
                  widget.session.counterDraftSubmitting ||
                  _selectedUnits == 0
              ? null
              : validPhone
              ? _review
              : _editCustomer,
          style: FilledButton.styleFrom(
            minimumSize: const Size(48, 48),
            padding: const EdgeInsets.symmetric(horizontal: 18, vertical: 12),
            shape: RoundedRectangleBorder(
              borderRadius: BorderRadius.circular(12),
            ),
          ),
          child: Text(
            _selectedUnits == 0
                ? 'Review bill'
                : validPhone
                ? 'Review bill'
                : 'Add customer',
            textAlign: TextAlign.center,
          ),
        ),
      ),
    );
    return Material(
      key: const Key('work-dashboard-counter-order-screen'),
      color: Colors.white,
      child: Focus(
        key: const Key('work-counter-scanner-listener'),
        focusNode: _barcodeFocus,
        skipTraversal: true,
        canRequestFocus: _usbScanMode,
        onFocusChange: (focused) {
          if (!focused) _clearScannerBuffer();
        },
        onKeyEvent: _handleScannerKey,
        child: LayoutBuilder(
          builder: (context, constraints) {
            // Keep the same editable/scroll subtree when the keyboard resizes
            // this surface. Replacing it detaches Search's native IME connection.
            final scaledLine = MediaQuery.textScalerOf(context).scale(14);
            final pinBillAction =
                hasStoreStock && constraints.maxHeight >= scaledLine * 5 + 100;
            final scroll = CustomScrollView(
              key: const Key('work-sale-short-scroll'),
              keyboardDismissBehavior: ScrollViewKeyboardDismissBehavior.onDrag,
              slivers: [
                SliverToBoxAdapter(child: controls),
                if (products.isEmpty)
                  SliverToBoxAdapter(child: emptyProducts)
                else
                  SliverPadding(
                    padding: const EdgeInsets.fromLTRB(16, 4, 16, 12),
                    sliver: SliverList(
                      key: const Key('work-sale-products'),
                      delegate: SliverChildBuilderDelegate(
                        (context, index) => index.isOdd
                            ? const Divider(height: 1, color: Color(0xFFE9EDF5))
                            : _SaleProductTile(
                                product: products[index ~/ 2],
                                session: widget.session,
                                reviewQuantity: _assistantMode ? _quantities[products[index ~/ 2].id] ?? 0 : null,
                                reviewAdjust: _assistantMode ? (change) => _adjustQuantity(products[index ~/ 2].id,change) : null,
                                isCurrent: _assistantMode || _transferredOwner != null ? () => _assistantCurrent : null,
                                onOpen: () =>
                                    _openProduct(products[index ~/ 2]),
                              ),
                        childCount: products.length * 2 - 1,
                      ),
                    ),
                  ),
                if (error != null) SliverToBoxAdapter(child: error),
                if (hasStoreStock && !pinBillAction)
                  SliverToBoxAdapter(child: total),
              ],
            );
            return Column(
              children: [
                Expanded(child: scroll),
                if (pinBillAction) total,
              ],
            );
          },
        ),
      ),
    );
  }
}

/// Keeps the next step visible while the form scrolls above the keyboard.
/// Very short windows retain one scroll surface instead of overflowing a footer.
class _StoreAmountWidth extends StatelessWidget {
  const _StoreAmountWidth({required this.controller, required this.child});
  final TextEditingController controller;
  final Widget child;

  @override
  Widget build(BuildContext context) => LayoutBuilder(
    builder: (context, constraints) => ValueListenableBuilder<TextEditingValue>(
      valueListenable: controller,
      child: child,
      builder: (context, value, field) {
        final scaler = MediaQuery.textScalerOf(context);
        final measure = TextPainter(
          text: TextSpan(text: '₹ ${value.text}',
              style: Theme.of(context).textTheme.bodyLarge),
          textDirection: Directionality.of(context), textScaler: scaler,
        )..layout();
        final preferred = measure.width + 56;
        final minimum = scaler.scale(220);
        final width = (preferred > minimum ? preferred : minimum)
            .clamp(0.0, constraints.maxWidth).toDouble();
        measure.dispose();
        return Align(alignment: Alignment.centerLeft,
            child: SizedBox(width: width, child: field));
      },
    ),
  );
}

class _StoreFormLayout extends StatelessWidget {
  const _StoreFormLayout({
    required this.child,
    required this.action,
    this.scrollKey,
    this.compact = false,
    this.padding = const EdgeInsets.all(16),
  });

  final Widget child, action;
  final Key? scrollKey;
  final bool compact;
  final EdgeInsets padding;

  @override
  Widget build(BuildContext context) => LayoutBuilder(
    builder: (context, constraints) {
      final footer = Padding(
        padding: const EdgeInsets.fromLTRB(16, 8, 16, 12),
        child: SizedBox(width: double.infinity, child: action),
      );
      if (!constraints.hasBoundedHeight || constraints.maxHeight < 180) {
        return SingleChildScrollView(
          key: scrollKey,
          keyboardDismissBehavior: ScrollViewKeyboardDismissBehavior.onDrag,
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              Padding(padding: padding, child: child),
              footer,
            ],
          ),
        );
      }
      return Column(
        mainAxisSize: compact ? MainAxisSize.min : MainAxisSize.max,
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          Flexible(
            fit: compact ? FlexFit.loose : FlexFit.tight,
            child: SingleChildScrollView(
              key: scrollKey,
              keyboardDismissBehavior: ScrollViewKeyboardDismissBehavior.onDrag,
              padding: padding,
              child: child,
            ),
          ),
          footer,
        ],
      );
    },
  );
}

class _RecentCounterCustomer {
  const _RecentCounterCustomer(this.customer, this.billingDetails);
  final String customer;
  final WorkspaceBillingDetails billingDetails;
  String? get mobile => _storedCounterCustomerMobile(customer);
  String get label =>
      billingDetails.business && billingDetails.businessName.trim().isNotEmpty
      ? billingDetails.businessName.trim()
      : billingDetails.name.trim().isNotEmpty
      ? billingDetails.name.trim()
      : customer;
}

class _StoreSaleCustomerSheet extends StatefulWidget {
  const _StoreSaleCustomerSheet({
    super.key,
    required this.initialValue,
    required this.recentCustomers,
    this.onDraftChanged,
    this.onConfirmed,
    this.onClose,
    this.billingDetails = const WorkspaceBillingDetails(),
    this.billingCustomer = '',
    this.onBillingChanged,
  });
  final ValueChanged<String>? onConfirmed;
  final VoidCallback? onClose;
  final WorkspaceBillingDetails billingDetails;
  final String billingCustomer;
  final void Function(WorkspaceBillingDetails, String?)? onBillingChanged;
  final String initialValue;
  final List<_RecentCounterCustomer> recentCustomers;
  final ValueChanged<String>? onDraftChanged;

  @override
  State<_StoreSaleCustomerSheet> createState() =>
      _StoreSaleCustomerSheetState();
}

class _StoreSaleCustomerSheetState extends State<_StoreSaleCustomerSheet> {
  late final _controller = TextEditingController(text: widget.initialValue);
  bool get _enteredCountryPrefix {
    final value = _controller.text.trimLeft();
    return value.startsWith('+') ||
        (normalizeWorkspaceMobile(value) != null &&
            value.replaceAll(RegExp(r'[ +\-]'), '').length == 12);
  }

  late bool _showMobilePrefix = !_enteredCountryPrefix;
  String? _error;
  late bool _business = widget.billingDetails.business;
  late bool _businessExpanded = widget.billingDetails.business;
  late final _name = TextEditingController(text: widget.billingDetails.name);
  late final _businessName = TextEditingController(
    text: widget.billingDetails.businessName,
  );
  late final _gst = TextEditingController(text: widget.billingDetails.gst);
  late final _billingAddress = TextEditingController(
    text: widget.billingDetails.address,
  );
  bool _applyingRecent = false;
  late String? _billingMobile =
      normalizeWorkspaceMobile(widget.billingCustomer) ??
      _storedCounterCustomerMobile(widget.initialValue);
  final _customerDrafts = <String, (WorkspaceBillingDetails, bool)>{};

  WorkspaceBillingDetails get _currentBilling => WorkspaceBillingDetails(
    business: _business,
    name: _name.text,
    businessName: _businessName.text,
    gst: _gst.text,
    address: _billingAddress.text,
  );

  void _cacheBilling() {
    if (_billingMobile case final mobile?) {
      _customerDrafts[mobile] = (_currentBilling, _businessExpanded);
    }
  }

  void _applyBilling(WorkspaceBillingDetails details, bool expanded) {
    _applyingRecent = true;
    _name.text = details.name;
    _businessName.text = details.businessName;
    _gst.text = details.gst;
    _billingAddress.text = details.address;
    _business = details.business;
    _businessExpanded = expanded;
    _applyingRecent = false;
  }

  void _switchBillingTo(String next) {
    if (next == _billingMobile) return;
    _cacheBilling();
    final hadOwner = _billingMobile != null;
    _billingMobile = next;
    final saved = _customerDrafts[next];
    if (hadOwner || saved != null) {
      setState(
        () => _applyBilling(
          saved?.$1 ?? const WorkspaceBillingDetails(),
          saved?.$2 ?? false,
        ),
      );
    }
    _rememberBilling();
  }

  void _rememberBilling() {
    if (_applyingRecent) return;
    _cacheBilling();
    widget.onBillingChanged?.call(_currentBilling, _billingMobile);
  }

  void _selectRecent(_RecentCounterCustomer customer) {
    final mobile = customer.mobile;
    if (mobile == null) return;
    final details = customer.billingDetails;
    _cacheBilling();
    _billingMobile = mobile;
    _applyingRecent = true;
    _controller.text = mobile;
    _name.text = details.name;
    _businessName.text = details.businessName;
    _gst.text = details.gst;
    _billingAddress.text = details.address;
    _business = details.business;
    _businessExpanded = details.business;
    _lastDraft = mobile;
    _applyingRecent = false;
    widget.onDraftChanged?.call(mobile);
    _rememberBilling();
    _confirm();
  }

  void _complete(String value) {
    if (widget.onConfirmed != null) {
      widget.onConfirmed!(value);
    } else {
      Navigator.pop(context, value);
    }
  }

  late String _lastDraft = widget.initialValue;

  @override
  void initState() {
    super.initState();
    for (final controller in [_name, _businessName, _gst, _billingAddress]) {
      controller.addListener(_rememberBilling);
    }
    _controller.addListener(() {
      final showPrefix = !_enteredCountryPrefix;
      if (_showMobilePrefix != showPrefix) {
        // Keep the actual editing value, selection and IME connection intact.
        setState(() => _showMobilePrefix = showPrefix);
      }
      if (_applyingRecent) return;
      if (_error != null &&
          normalizeWorkspaceMobile(_controller.text) != null) {
        setState(() => _error = null);
      }
      if (_lastDraft != _controller.text) {
        final next = normalizeWorkspaceMobile(_controller.text);
        if (next != null && next != _billingMobile) {
          // A partially typed number is not a customer switch. A different
          // complete number must never inherit another customer's billing facts.
          _switchBillingTo(next);
        } else if (next == null && _billingMobile != null) {
          // Bind legacy valid drafts before saving their first partial edit.
          _rememberBilling();
        }
        _lastDraft = _controller.text;
        widget.onDraftChanged?.call(_lastDraft);
      }
    });
  }

  @override
  void dispose() {
    _controller.dispose();
    for (final controller in [_name, _businessName, _gst, _billingAddress]) {
      controller.dispose();
    }
    super.dispose();
  }

  void _confirm() {
    final value = normalizeWorkspaceMobile(_controller.text);
    if (value == null) {
      setState(() => _error = 'Enter a valid 10-digit customer mobile number.');
      return;
    }
    _switchBillingTo(value);
    FocusManager.instance.primaryFocus?.unfocus();
    _complete(value);
  }

  @override
  Widget build(BuildContext context) {
    final media = MediaQuery.of(context);
    return Padding(
      padding: EdgeInsets.only(
        bottom: widget.onConfirmed == null ? media.viewInsets.bottom : 0,
      ),
      child: SafeArea(
        top: false,
        child: ConstrainedBox(
          constraints: BoxConstraints(
            maxHeight: widget.onConfirmed == null
                ? (media.size.height - media.viewInsets.bottom) * .8
                : double.infinity,
          ),
          child: _StoreFormLayout(
            scrollKey: const Key('work-sale-customer-sheet'),
            padding: const EdgeInsets.fromLTRB(16, 4, 16, 12),
            action: FilledButton(
              key: const Key('work-sale-customer-confirm'),
              onPressed: _confirm,
              style: FilledButton.styleFrom(
                minimumSize: const Size(48, 48),
                padding: const EdgeInsets.symmetric(
                  horizontal: 16,
                  vertical: 12,
                ),
              ),
              child: Text(
                widget.onConfirmed == null
                    ? 'Use customer'
                    : 'Add items to bill',
              ),
            ),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                Row(
                  children: [
                    const Expanded(
                      child: Text(
                        'Customer details',
                        key: Key('work-sale-customer-title'),
                        style: TextStyle(
                          color: MoolColors.navy,
                          fontSize: 18,
                          fontWeight: FontWeight.w800,
                        ),
                      ),
                    ),
