class _WorkspaceStatusSurface extends StatelessWidget {
  const _WorkspaceStatusSurface({
    required this.scrollController,
    required this.session,
    this.recovery,
    required this.acceptingOrders,
    required this.visibleToCustomers,
    required this.fulfilmentMode,
    required this.busyMinutes,
    required this.reopensAt,
    required this.openingTime,
    required this.closingTime,
    required this.maximumActiveOrders,
    required this.alertSound,
    required this.alertVibration,
    required this.onAcceptingChanged,
    required this.onVisibilityChanged,
    required this.onFulfilmentChanged,
    required this.onBusyMinutesChanged,
    required this.onReopensChanged,
    required this.onOpeningTimeChanged,
    required this.onClosingTimeChanged,
    required this.onMaximumActiveOrdersChanged,
    required this.onAlertSoundChanged,
    required this.onAlertVibrationChanged,
    required this.onDeliveryControls,
    required this.onPaymentControls,
  });

  final WorkSession session;
  final Widget? recovery;
  final ScrollController scrollController;
  final bool acceptingOrders;
  final bool visibleToCustomers;
  final String fulfilmentMode;
  final int busyMinutes;
  final String reopensAt;
  final String openingTime;
  final String closingTime;
  final int maximumActiveOrders;
  final bool alertSound;
  final bool alertVibration;
  final ValueChanged<bool> onAcceptingChanged;
  final ValueChanged<bool> onVisibilityChanged;
  final ValueChanged<String> onFulfilmentChanged;
  final ValueChanged<int> onBusyMinutesChanged;
  final ValueChanged<String> onReopensChanged;
  final ValueChanged<String> onOpeningTimeChanged;
  final ValueChanged<String> onClosingTimeChanged;
  final ValueChanged<int> onMaximumActiveOrdersChanged;
  final ValueChanged<bool> onAlertSoundChanged;
  final ValueChanged<bool> onAlertVibrationChanged;
  final VoidCallback onDeliveryControls;
  final VoidCallback onPaymentControls;

  @override
  Widget build(BuildContext context) {
    final currentState = acceptingOrders
        ? WorkspaceStoreState.open
        : reopensAt.isEmpty
        ? WorkspaceStoreState.off
        : WorkspaceStoreState.paused;
    final publicationReport = session.workspacePublicationReport;
    final tradingChanged = busyMinutes != session.workspaceBusyMinutes ||
        fulfilmentMode != session.workspaceFulfilmentMode ||
        openingTime != session.workspaceOpeningTime ||
        closingTime != session.workspaceClosingTime ||
        maximumActiveOrders != session.workspaceMaximumActiveOrders ||
        alertSound != session.workspaceOrderAlertSound ||
        alertVibration != session.workspaceOrderAlertVibration;
    return StoreSettingsStyle(
      child: ListView(
        key: const Key('work-dashboard-status-screen'),
        controller: scrollController,
        padding: const EdgeInsets.fromLTRB(
          MoolSpacing.md,
          MoolSpacing.xs,
          MoolSpacing.md,
          MoolSpacing.xl,
        ),
        children: [
          if (recovery != null) recovery!,
          const SizedBox(height: 4),
          SegmentedButton<WorkspaceStoreState>(
            key: const Key('work-status-store-state'),
            showSelectedIcon: false,
            segments: const [
              ButtonSegment(
                value: WorkspaceStoreState.open,
                label: Text('Open'),
              ),
              ButtonSegment(
                value: WorkspaceStoreState.paused,
                label: Text('Paused'),
              ),
              ButtonSegment(value: WorkspaceStoreState.off, label: Text('Off')),
            ],
            selected: {currentState},
            onSelectionChanged: (selection) {
              switch (selection.first) {
                case WorkspaceStoreState.open:
                  onAcceptingChanged(true);
                  onReopensChanged('');
                case WorkspaceStoreState.paused:
                  onAcceptingChanged(false);
                  onReopensChanged(reopensAt.isEmpty ? 'In 1 hour' : reopensAt);
                case WorkspaceStoreState.off:
                  onAcceptingChanged(false);
                  onReopensChanged('');
              }
            },
          ),
          if (currentState == WorkspaceStoreState.paused) ...[
            const SizedBox(height: 8),
            const Text(
              'Pause until',
              style: TextStyle(color: MoolColors.muted, fontSize: 12),
            ),
            Wrap(
              spacing: 6,
              runSpacing: 4,
              children: [
                for (final option in const [
                  'In 30 minutes',
                  'In 1 hour',
                  'Tomorrow at 8:00 AM',
                ])
                  ChoiceChip(
                    key: Key(
                      'work-status-reopens-${option.toLowerCase().replaceAll(RegExp(r'[^a-z0-9]+'), '-')}',
                    ),
                    label: Text(option),
                    selected: reopensAt == option,
                    onSelected: (selected) {
                      if (selected) onReopensChanged(option);
                    },
                  ),
              ],
            ),
          ],
          if (currentState == WorkspaceStoreState.off)
            const Padding(
              padding: EdgeInsets.only(top: 8),
              child: Text(
                'Ordering stays off until you reopen your Store.',
                style: TextStyle(color: MoolColors.muted, fontSize: 12),
              ),
            ),
          const SizedBox(height: 12),
          if (session.tradingPreferencesPersistenceAvailable)
            Padding(padding: const EdgeInsets.only(bottom: 8), child: Text(
              session.workspaceTradingPreferencesError ??
              (session.workspaceTradingPreferencesSaving ? 'Saving Store preferences on this device…' :
               tradingChanged ? 'Unsaved Store preferences.' :
               session.workspaceTradingPreferencesSaved ?
                 (session.workspaceReadinessPreferencesSaved
                   ? 'Store preferences saved on this device. Public sync is pending.'
                   : 'Hours and alerts saved on this device. Public sync is pending.') :
               'Apply settings to keep Store preferences on this device. Public sync is pending.'),
              key: const Key('work-status-trading-device-status'),
              style: const TextStyle(color: MoolColors.muted, fontSize: 12))),
          Material(
            color: Colors.white,
            borderRadius: BorderRadius.circular(18),
            clipBehavior: Clip.antiAlias,
            child: Column(
              children: [
                SwitchListTile.adaptive(
                  key: const Key('work-status-visibility'),
                  title: const Text('Show Store to customers'),
                  value: visibleToCustomers,
                  onChanged: onVisibilityChanged,
                ),
                const Divider(height: 1, indent: 16, endIndent: 16),
                _SettingsHoursPair(
                  opening: ListTile(
                    key: const Key('work-status-opening-time'),
                    title: const Text('Opens'),
                    subtitle: Text(
                      parseStoreHours(openingTime)?.format(context) ??
                          openingTime,
                    ),
                    trailing: const Icon(Icons.edit_outlined),
                    onTap: () async {
                      final selected = await showTimePicker(
                        context: context,
                        initialTime:
                            parseStoreHours(openingTime) ??
                            const TimeOfDay(hour: 8, minute: 0),
                        builder: (_, child) =>
                            StoreSettingsStyle(child: child!),
                      );
                      if (selected != null && context.mounted) {
                        onOpeningTimeChanged(storeHoursValue(selected));
                      }
                    },
                  ),
                  closing: ListTile(
                    key: const Key('work-status-closing-time'),
                    title: const Text('Closes'),
                    subtitle: Text(
                      parseStoreHours(closingTime)?.format(context) ??
                          closingTime,
                    ),
                    trailing: const Icon(Icons.edit_outlined),
                    onTap: () async {
                      final selected = await showTimePicker(
                        context: context,
